window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["住房城乡建设部"] = {"zhucejianzhushitiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国行政许可法》和《中华人民共和国注册建筑师条例》（以下简称《条例》），制定本细则。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内注册建筑师的考试、注册、执业、继续教育和监督管理，适用本细则。"},{"i":3,"n":"第三条","txt":"注册建筑师，是指经考试、特许、考核认定取得中华人民共和国注册建筑师执业资格证书（以下简称执业资格证书），或者经资格互认方式取得建筑师互认资格证书（以下简称互认资格证书），并按照本细则注册，取得中华人民共和国注册建筑师注册证书（以下简称注册证书）和中华人民共和国注册建筑师执业印章（以下简称执业印章），从事建筑设计及相关业务活动的专业技术人员。 未取得注册证书和执业印章的人员，不得以注册建筑师的名义从事建筑设计及相关业务活动。"},{"i":4,"n":"第四条","txt":"国务院建设主管部门、人事主管部门按职责分工对全国注册建筑师考试、注册、执业和继续教育实施指导和监督。 省、自治区、直辖市人民政府建设主管部门、人事主管部门按职责分工对本行政区域内注册建筑师考试、注册、执业和继续教育实施指导和监督。"},{"i":5,"n":"第五条","txt":"全国注册建筑师管理委员会负责注册建筑师考试、一级注册建筑师注册、制定颁布注册建筑师有关标准以及相关国际交流等具体工作。 省、自治区、直辖市注册建筑师管理委员会负责本行政区域内注册建筑师考试、注册以及协助全国注册建筑师管理委员会选派专家等具体工作。"},{"i":6,"n":"第六条","txt":"全国注册建筑师管理委员会委员由国务院建设主管部门商人事主管部门聘任。 全国注册建筑师管理委员会由国务院建设主管部门、人事主管部门、其他有关主管部门的代表和建筑设计专家组成，设主任委员一名、副主任委员若干名。全国注册建筑师管理委员会秘书处设在建设部执业资格注册中心。全国注册建筑师管理委员会秘书处承担全国注册建筑师管理委员会的日常工作职责，并承担相应的法律责任。 省、自治区、直辖市注册建筑师管理委员会由省、自治区、直辖市人民政府建设主管部门商同级人事主管部门参照本条第一款、第二款规定成立。"},{"i":7,"n":"第七条","txt":"注册建筑师考试分为一级注册建筑师考试和二级注册建筑师考试。注册建筑师考试实行全国统一考试，每年进行一次。遇特殊情况，经国务院建设主管部门和人事主管部门同意，可调整该年度考试次数。 注册建筑师考试由全国注册建筑师管理委员会统一部署，省、自治区、直辖市注册建筑师管理委员会组织实施。"},{"i":8,"n":"第八条","txt":"一级注册建筑师考试内容包括：建筑设计前期工作、场地设计、建筑设计与表达、建筑结构、环境控制、建筑设备、建筑材料与构造、建筑经济、施工与设计业务管理、建筑法规等。上述内容分成若干科目进行考试。科目考试合格有效期为八年。 二级注册建筑师考试内容包括：场地设计、建筑设计与表达、建筑结构与设备、建筑法规、建筑经济与施工等。上述内容分成若干科目进行考试。科目考试合格有效期为四年。"},{"i":9,"n":"第九条","txt":"《条例》第八条第（一）、（二）、（三）项，第九条第（一）项中所称相近专业，是指大学本科及以上建筑学的相近专业，包括城市规划、建筑工程和环境艺术等专业。 《条例》第九条第（二）项所称相近专业，是指大学专科建筑设计的相近专业，包括城乡规划、房屋建筑工程、风景园林、建筑装饰技术和环境艺术等专业。 《条例》第九条第（四）项所称相近专业，是指中等专科学校建筑设计技术的相近专业，包括工业与民用建筑、建筑装饰、城镇规划和村镇建设等专业。 《条例》第八条第（五）项所称设计成绩突出，是指获得国家或省部级优秀工程设计铜质或二等奖（建筑）及以上奖励。"},{"i":10,"n":"第十条","txt":"申请参加注册建筑师考试者，可向省、自治区、直辖市注册建筑师管理委员会报名，经省、自治区、直辖市注册建筑师管理委员会审查，符合《条例》第八条或者第九条规定的，方可参加考试。"},{"i":11,"n":"第十一条","txt":"经一级注册建筑师考试，在有效期内全部科目考试合格的，由全国注册建筑师管理委员会核发国务院建设主管部门和人事主管部门共同用印的一级注册建筑师执业资格证书。 经二级注册建筑师考试，在有效期内全部科目考试合格的，由省、自治区、直辖市注册建筑师管理委员会核发国务院建设主管部门和人事主管部门共同用印的二级注册建筑师执业资格证书。 自考试之日起，九十日内公布考试成绩；自考试成绩公布之日起，三十日内颁发执业资格证书。"},{"i":12,"n":"第十二条","txt":"申请参加注册建筑师考试者，应当按规定向省、自治区、直辖市注册建筑师管理委员会交纳考务费和报名费。"},{"i":13,"n":"第十三条","txt":"注册建筑师实行注册执业管理制度。取得执业资格证书或者互认资格证书的人员，必须经过注册方可以注册建筑师的名义执业。"},{"i":14,"n":"第十四条","txt":"取得一级注册建筑师资格证书并受聘于一个相关单位的人员，应当通过聘用单位向单位工商注册所在地的省、自治区、直辖市注册建筑师管理委员会提出申请；省、自治区、直辖市注册建筑师管理委员会受理后提出初审意见，并将初审意见和申请材料报全国注册建筑师管理委员会审批；符合条件的，由全国注册建筑师管理委员会颁发一级注册建筑师注册证书和执业印章。"},{"i":15,"n":"第十五条","txt":"省、自治区、直辖市注册建筑师管理委员会在收到申请人申请一级注册建筑师注册的材料后，应当即时作出是否受理的决定，并向申请人出具书面凭证；申请材料不齐全或者不符合法定形式的，应当在五日内一次性告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。 对申请初始注册的，省、自治区、直辖市注册建筑师管理委员会应当自受理申请之日起二十日内审查完毕，并将申请材料和初审意见报全国注册建筑师管理委员会。全国注册建筑师管理委员会应当自收到省、自治区、直辖市注册建筑师管理委员会上报材料之日起，二十日内审批完毕并作出书面决定。 审查结果由全国注册建筑师管理委员会予以公示，公示时间为十日，公示时间不计算在审批时间内。 全国注册建筑师管理委员会自作出审批决定之日起十日内，在公众媒体上公布审批结果。 对申请变更注册、延续注册的，省、自治区、直辖市注册建筑师管理委员会应当自受理申请之日起十日内审查"},{"i":16,"n":"第十六条","txt":"注册证书和执业印章是注册建筑师的执业凭证，由注册建筑师本人保管、使用。 注册建筑师由于办理延续注册、变更注册等原因，在领取新执业印章时，应当将原执业印章交回。 禁止涂改、倒卖、出租、出借或者以其他形式非法转让执业资格证书、互认资格证书、注册证书和执业印章。"},{"i":17,"n":"第十七条","txt":"申请注册建筑师初始注册，应当具备以下条件： （一）依法取得执业资格证书或者互认资格证书； （二）只受聘于中华人民共和国境内的一个建设工程勘察、设计、施工、监理、招标代理、造价咨询、施工图审查、城乡规划编制等单位（以下简称聘用单位）； （三）近三年内在中华人民共和国境内从事建筑设计及相关业务一年以上； （四）达到继续教育要求； （五）没有本细则第二十一条所列的情形。"},{"i":18,"n":"第十八条","txt":"初始注册者可以自执业资格证书签发之日起三年内提出申请。逾期未申请者，须符合继续教育的要求后方可申请初始注册。 初始注册需要提交下列材料： （一）初始注册申请表； （二）资格证书复印件； （三）身份证明复印件； （四）聘用单位资质证书副本复印件； （五）与聘用单位签订的聘用劳动合同复印件； （六）相应的业绩证明； （七）逾期初始注册的，应当提交达到继续教育要求的证明材料。"},{"i":19,"n":"第十九条","txt":"注册建筑师每一注册有效期为二年。注册建筑师注册有效期满需继续执业的，应在注册有效期届满三十日前，按照本细则第十五条规定的程序申请延续注册。延续注册有效期为二年。 延续注册需要提交下列材料： （一）延续注册申请表； （二）与聘用单位签订的聘用劳动合同复印件； （三）注册期内达到继续教育要求的证明材料。"},{"i":20,"n":"第二十条","txt":"注册建筑师变更执业单位，应当与原聘用单位解除劳动关系，并按照本细则第十五条规定的程序办理变更注册手续。变更注册后，仍延续原注册有效期。 原注册有效期届满在半年以内的，可以同时提出延续注册申请。准予延续的，注册有效期重新计算。 变更注册需要提交下列材料： （一）变更注册申请表； （二）新聘用单位资质证书副本的复印件； （三）与新聘用单位签订的聘用劳动合同复印件； （四）工作调动证明或者与原聘用单位解除聘用劳动合同的证明文件、劳动仲裁机构出具的解除劳动关系的仲裁文件、退休人员的退休证明复印件； （五）在办理变更注册时提出延续注册申请的，还应当提交在本注册有效期内达到继续教育要求的证明材料。"},{"i":21,"n":"第二十一条","txt":"申请人有下列情形之一的，不予注册： （一）不具有完全民事行为能力的； （二）申请在两个或者两个以上单位注册的； （三）未达到注册建筑师继续教育要求的； （四）因受刑事处罚，自刑事处罚执行完毕之日起至申请注册之日止不满五年的； （五）因在建筑设计或者相关业务中犯有错误受行政处罚或者撤职以上行政处分，自处罚、处分决定之日起至申请之日止不满二年的； （六）受吊销注册建筑师证书的行政处罚，自处罚决定之日起至申请注册之日止不满五年的； （七）申请人的聘用单位不符合注册单位要求的； （八）法律、法规规定不予注册的其他情形。"},{"i":22,"n":"第二十二条","txt":"注册建筑师有下列情形之一的，其注册证书和执业印章失效： （一）聘用单位破产的； （二）聘用单位被吊销营业执照的； （三）聘用单位相应资质证书被吊销或者撤回的； （四）已与聘用单位解除聘用劳动关系的； （五）注册有效期满且未延续注册的； （六）死亡或者丧失民事行为能力的； （七）其他导致注册失效的情形。"},{"i":23,"n":"第二十三条","txt":"注册建筑师有下列情形之一的，由注册机关办理注销手续，收回注册证书和执业印章或公告注册证书和执业印章作废： （一）有本细则第二十二条所列情形发生的； （二）依法被撤销注册的； （三）依法被吊销注册证书的； （四）受刑事处罚的； （五）法律、法规规定应当注销注册的其他情形。 注册建筑师有前款所列情形之一的，注册建筑师本人和聘用单位应当及时向注册机关提出注销注册申请；有关单位和个人有权向注册机关举报；县级以上地方人民政府建设主管部门或者有关部门应当及时告知注册机关。"},{"i":24,"n":"第二十四条","txt":"被注销注册者或者不予注册者，重新具备注册条件的，可以按照本细则第十五条规定的程序重新申请注册。"},{"i":25,"n":"第二十五条","txt":"高等学校（院）从事教学、科研并具有注册建筑师资格的人员，只能受聘于本校（院）所属建筑设计单位从事建筑设计，不得受聘于其他建筑设计单位。在受聘于本校(院)所属建筑设计单位工作期间，允许申请注册。获准注册的人员，在本校（院）所属建筑设计单位连续工作不得少于二年。具体办法由国务院建设主管部门商教育主管部门规定。"},{"i":26,"n":"第二十六条","txt":"注册建筑师因遗失、污损注册证书或者执业印章，需要补办的，应当持在公众媒体上刊登的遗失声明的证明，或者污损的原注册证书和执业印章，向原注册机关申请补办。原注册机关应当在十日内办理完毕。"},{"i":27,"n":"第二十七条","txt":"取得资格证书的人员，应当受聘于中华人民共和国境内的一个建设工程勘察、设计、施工、监理、招标代理、造价咨询、施工图审查、城乡规划编制等单位，经注册后方可从事相应的执业活动。 从事建筑工程设计执业活动的，应当受聘并注册于中华人民共和国境内一个具有工程设计资质的单位。"},{"i":28,"n":"第二十八条","txt":"注册建筑师的执业范围具体为： （一）建筑设计； （二）建筑设计技术咨询； （三）建筑物调查与鉴定； （四）对本人主持设计的项目进行施工指导和监督； （五）国务院建设主管部门规定的其他业务。 本条第一款所称建筑设计技术咨询包括建筑工程技术咨询，建筑工程招标、采购咨询，建筑工程项目管理，建筑工程设计文件及施工图审查，工程质量评估，以及国务院建设主管部门规定的其他建筑技术咨询业务。"},{"i":29,"n":"第二十九条","txt":"一级注册建筑师的执业范围不受工程项目规模和工程复杂程度的限制。二级注册建筑师的执业范围只限于承担工程设计资质标准中建设项目设计规模划分表中规定的小型规模的项目。 注册建筑师的执业范围不得超越其聘用单位的业务范围。注册建筑师的执业范围与其聘用单位的业务范围不符时，个人执业范围服从聘用单位的业务范围。"},{"i":30,"n":"第三十条","txt":"注册建筑师所在单位承担民用建筑设计项目，应当由注册建筑师任工程项目设计主持人或设计总负责人；工业建筑设计项目，须由注册建筑师任工程项目建筑专业负责人。"},{"i":31,"n":"第三十一条","txt":"凡属工程设计资质标准中建筑工程建设项目设计规模划分表规定的工程项目，在建筑工程设计的主要文件（图纸）中，须由主持该项设计的注册建筑师签字并加盖其执业印章，方为有效。否则设计审查部门不予审查，建设单位不得报建，施工单位不准施工。"},{"i":32,"n":"第三十二条","txt":"修改经注册建筑师签字盖章的设计文件，应当由原注册建筑师进行；因特殊情况，原注册建筑师不能进行修改的，可以由设计单位的法人代表书面委托其他符合条件的注册建筑师修改，并签字、加盖执业印章，对修改部分承担责任。"},{"i":33,"n":"第三十三条","txt":"注册建筑师从事执业活动，由聘用单位接受委托并统一收费。"},{"i":34,"n":"第三十四条","txt":"注册建筑师在每一注册有效期内应当达到全国注册建筑师管理委员会制定的继续教育标准。继续教育作为注册建筑师逾期初始注册、延续注册、重新申请注册的条件之一。"},{"i":35,"n":"第三十五条","txt":"继续教育分为必修课和选修课，在每一注册有效期内各为四十学时。"},{"i":36,"n":"第三十六条","txt":"国务院建设主管部门对注册建筑师注册执业活动实施统一的监督管理。县级以上地方人民政府建设主管部门负责对本行政区域内的注册建筑师注册执业活动实施监督管理。"},{"i":37,"n":"第三十七条","txt":"建设主管部门履行监督检查职责时，有权采取下列措施： （一）要求被检查的注册建筑师提供资格证书、注册证书、执业印章、设计文件（图纸）； （二）进入注册建筑师聘用单位进行检查，查阅相关资料； （三）纠正违反有关法律、法规和本细则及有关规范和标准的行为。 建设主管部门依法对注册建筑师进行监督检查时，应当将监督检查情况和处理结果予以记录，由监督检查人员签字后归档。"},{"i":38,"n":"第三十八条","txt":"建设主管部门在实施监督检查时，应当有两名以上监督检查人员参加，并出示执法证件，不得妨碍注册建筑师正常的执业活动，不得谋取非法利益。 注册建筑师和其聘用单位对依法进行的监督检查应当协助与配合，不得拒绝或者阻挠。"},{"i":39,"n":"第三十九条","txt":"注册建筑师及其聘用单位应当按照要求，向注册机关提供真实、准确、完整的注册建筑师信用档案信息。 注册建筑师信用档案应当包括注册建筑师的基本情况、业绩、良好行为、不良行为等内容。违法违规行为、被投诉举报处理、行政处罚等情况应当作为注册建筑师的不良行为记入其信用档案。 注册建筑师信用档案信息按照有关规定向社会公示。"},{"i":40,"n":"第四十条","txt":"隐瞒有关情况或者提供虚假材料申请注册的，注册机关不予受理，并由建设主管部门给予警告，申请人一年之内不得再次申请注册。"},{"i":41,"n":"第四十一条","txt":"以欺骗、贿赂等不正当手段取得注册证书和执业印章的，由全国注册建筑师管理委员会或省、自治区、直辖市注册建筑师管理委员会撤销注册证书并收回执业印章，三年内不得再次申请注册，并由县级以上人民政府建设主管部门处以罚款。其中没有违法所得的，处以1万元以下罚款；有违法所得的处以违法所得3倍以下且不超过3万元的罚款。"},{"i":42,"n":"第四十二条","txt":"违反本细则，未受聘并注册于中华人民共和国境内一个具有工程设计资质的单位，从事建筑工程设计执业活动的，由县级以上人民政府建设主管部门给予警告，责令停止违法活动，并可处以1万元以上3万元以下的罚款。"},{"i":43,"n":"第四十三条","txt":"违反本细则，未办理变更注册而继续执业的，由县级以上人民政府建设主管部门责令限期改正；逾期未改正的，可处以5000元以下的罚款。"},{"i":44,"n":"第四十四条","txt":"违反本细则，涂改、倒卖、出租、出借或者以其他形式非法转让执业资格证书、互认资格证书、注册证书和执业印章的，由县级以上人民政府建设主管部门责令改正，其中没有违法所得的，处以1万元以下罚款；有违法所得的处以违法所得3倍以下且不超过3万元的罚款。"},{"i":45,"n":"第四十五条","txt":"违反本细则，注册建筑师或者其聘用单位未按照要求提供注册建筑师信用档案信息的，由县级以上人民政府建设主管部门责令限期改正；逾期未改正的，可处以1000元以上1万元以下的罚款。"},{"i":46,"n":"第四十六条","txt":"聘用单位为申请人提供虚假注册材料的，由县级以上人民政府建设主管部门给予警告，责令限期改正；逾期未改正的，可处以1万元以上3万元以下的罚款。"},{"i":47,"n":"第四十七条","txt":"有下列情形之一的，全国注册建筑师管理委员会或者省、自治区、直辖市注册建筑师管理委员可以撤销其注册： （一）全国注册建筑师管理委员会或者省、自治区、直辖市注册建筑师管理委员的工作人员滥用职权、玩忽职守颁发注册证书和执业印章的； （二）超越法定职权颁发注册证书和执业印章的； （三）违反法定程序颁发注册证书和执业印章的； （四）对不符合法定条件的申请人颁发注册证书和执业印章的； （五）依法可以撤销注册的其他情形。"},{"i":48,"n":"第四十八条","txt":"县级以上人民政府建设主管部门、人事主管部门及全国注册建筑师管理委员会或者省、自治区、直辖市注册建筑师管理委员的工作人员，在注册建筑师管理工作中，有下列情形之一的，依法给予处分；构成犯罪的，依法追究刑事责任： （一）对不符合法定条件的申请人颁发执业资格证书、注册证书和执业印章的； （二）对符合法定条件的申请人不予颁发执业资格证书、注册证书和执业印章的； （三）对符合法定条件的申请不予受理或者未在法定期限内初审完毕的； （四）利用职务上的便利，收受他人财物或者其他好处的； （五）不依法履行监督管理职责，或者发现违法行为不予查处的。"},{"i":49,"n":"第四十九条","txt":"注册建筑师执业资格证书由国务院人事主管部门统一制作；一级注册建筑师注册证书、执业印章和互认资格证书由全国注册建筑师管理委员会统一制作；二级注册建筑师注册证书和执业印章由省、自治区、直辖市注册建筑师管理委员会统一制作。"},{"i":50,"n":"第五十条","txt":"香港特别行政区、澳门特别行政区、台湾地区的专业技术人员按照国家有关规定和有关协议，报名参加全国统一考试和申请注册。 外籍专业技术人员参加全国统一考试按照对等原则办理；申请建筑师注册的，其所在国应当已与中华人民共和国签署双方建筑师对等注册协议。"},{"i":51,"n":"第五十一条","txt":"本细则自2008年3月15日起施行。1996年7月1日建设部颁布的《中华人民共和国注册建筑师条例实施细则》（建设部令第52号）同时废止。"}],"zhuzhaizhuanxiangweixiuzijinguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对住宅专项维修资金的管理，保障住宅共用部位、共用设施设备的维修和正常使用，维护住宅专项维修资金所有者的合法权益，根据《物权法》、《物业管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"商品住宅、售后公有住房住宅专项维修资金的交存、使用、管理和监督，适用本办法。 本办法所称住宅专项维修资金，是指专项用于住宅共用部位、共用设施设备保修期满后的维修和更新、改造的资金。"},{"i":3,"n":"第三条","txt":"本办法所称住宅共用部位，是指根据法律、法规和房屋买卖合同，由单幢住宅内业主或者单幢住宅内业主及与之结构相连的非住宅业主共有的部位，一般包括：住宅的基础、承重墙体、柱、梁、楼板、屋顶以及户外的墙面、门厅、楼梯间、走廊通道等。 本办法所称共用设施设备，是指根据法律、法规和房屋买卖合同，由住宅业主或者住宅业主及有关非住宅业主共有的附属设施设备，一般包括电梯、天线、照明、消防设施、绿地、道路、路灯、沟渠、池、井、非经营性车场车库、公益性文体设施和共用设施设备使用的房屋等。"},{"i":4,"n":"第四条","txt":"住宅专项维修资金管理实行专户存储、专款专用、所有权人决策、政府监督的原则。"},{"i":5,"n":"第五条","txt":"国务院建设主管部门会同国务院财政部门负责全国住宅专项维修资金的指导和监督工作。 县级以上地方人民政府建设（房地产）主管部门会同同级财政部门负责本行政区域内住宅专项维修资金的指导和监督工作。"},{"i":6,"n":"第六条","txt":"下列物业的业主应当按照本办法的规定交存住宅专项维修资金： （一）住宅，但一个业主所有且与其他物业不具有共用部位、共用设施设备的除外； （二）住宅小区内的非住宅或者住宅小区外与单幢住宅结构相连的非住宅。 前款所列物业属于出售公有住房的，售房单位应当按照本办法的规定交存住宅专项维修资金。"},{"i":7,"n":"第七条","txt":"商品住宅的业主、非住宅的业主按照所拥有物业的建筑面积交存住宅专项维修资金，每平方米建筑面积交存首期住宅专项维修资金的数额为当地住宅建筑安装工程每平方米造价的5%至8%。 直辖市、市、县人民政府建设（房地产）主管部门应当根据本地区情况，合理确定、公布每平方米建筑面积交存首期住宅专项维修资金的数额，并适时调整。"},{"i":8,"n":"第八条","txt":"出售公有住房的，按照下列规定交存住宅专项维修资金： （一）业主按照所拥有物业的建筑面积交存住宅专项维修资金，每平方米建筑面积交存首期住宅专项维修资金的数额为当地房改成本价的2%。 （二）售房单位按照多层住宅不低于售房款的20%、高层住宅不低于售房款的30%，从售房款中一次性提取住宅专项维修资金。"},{"i":9,"n":"第九条","txt":"业主交存的住宅专项维修资金属于业主所有。 从公有住房售房款中提取的住宅专项维修资金属于公有住房售房单位所有。"},{"i":10,"n":"第十条","txt":"业主大会成立前，商品住宅业主、非住宅业主交存的住宅专项维修资金，由物业所在地直辖市、市、县人民政府建设（房地产）主管部门代管。 直辖市、市、县人民政府建设（房地产）主管部门应当委托所在地一家商业银行，作为本行政区域内住宅专项维修资金的专户管理银行，并在专户管理银行开立住宅专项维修资金专户。 开立住宅专项维修资金专户，应当以物业管理区域为单位设账，按房屋户门号设分户账；未划定物业管理区域的，以幢为单位设账，按房屋户门号设分户账。"},{"i":11,"n":"第十一条","txt":"业主大会成立前，已售公有住房住宅专项维修资金，由物业所在地直辖市、市、县人民政府财政部门或者建设（房地产）主管部门负责管理。 负责管理公有住房住宅专项维修资金的部门应当委托所在地一家商业银行，作为本行政区域内公有住房住宅专项维修资金的专户管理银行，并在专户管理银行开立公有住房住宅专项维修资金专户。 开立公有住房住宅专项维修资金专户，应当按照售房单位设账，按幢设分账；其中，业主交存的住宅专项维修资金，按房屋户门号设分户帐。"},{"i":12,"n":"第十二条","txt":"商品住宅的业主应当在办理房屋入住手续前，将首期住宅专项维修资金存入住宅专项维修资金专户。 已售公有住房的业主应当在办理房屋入住手续前，将首期住宅专项维修资金存入公有住房住宅专项维修资金专户或者交由售房单位存入公有住房住宅专项维修资金专户。 公有住房售房单位应当在收到售房款之日起30日内，将提取的住宅专项维修资金存入公有住房住宅专项维修资金专户。"},{"i":13,"n":"第十三条","txt":"未按本办法规定交存首期住宅专项维修资金的，开发建设单位或者公有住房售房单位不得将房屋交付购买人。"},{"i":14,"n":"第十四条","txt":"专户管理银行、代收住宅专项维修资金的售房单位应当出具由财政部或者省、自治区、直辖市人民政府财政部门统一监制的住宅专项维修资金专用票据。"},{"i":15,"n":"第十五条","txt":"业主大会成立后，应当按照下列规定划转业主交存的住宅专项维修资金： （一）业主大会应当委托所在地一家商业银行作为本物业管理区域内住宅专项维修资金的专户管理银行，并在专户管理银行开立住宅专项维修资金专户。 开立住宅专项维修资金专户，应当以物业管理区域为单位设账，按房屋户门号设分户账。 （二）业主委员会应当通知所在地直辖市、市、县人民政府建设（房地产）主管部门；涉及已售公有住房的，应当通知负责管理公有住房住宅专项维修资金的部门。 （三）直辖市、市、县人民政府建设（房地产）主管部门或者负责管理公有住房住宅专项维修资金的部门应当在收到通知之日起30日内，通知专户管理银行将该物业管理区域内业主交存的住宅专项维修资金账面余额划转至业主大会开立的住宅专项维修资金账户，并将有关账目等移交业主委员会。"},{"i":16,"n":"第十六条","txt":"住宅专项维修资金划转后的账目管理单位，由业主大会决定。业主大会应当建立住宅专项维修资金管理制度。 业主大会开立的住宅专项维修资金账户，应当接受所在地直辖市、市、县人民政府建设（房地产）主管部门的监督。"},{"i":17,"n":"第十七条","txt":"业主分户账面住宅专项维修资金余额不足首期交存额30%的，应当及时续交。 成立业主大会的，续交方案由业主大会决定。 未成立业主大会的，续交的具体管理办法由直辖市、市、县人民政府建设（房地产）主管部门会同同级财政部门制定。"},{"i":18,"n":"第十八条","txt":"住宅专项维修资金应当专项用于住宅共用部位、共用设施设备保修期满后的维修和更新、改造，不得挪作他用。"},{"i":19,"n":"第十九条","txt":"住宅专项维修资金的使用，应当遵循方便快捷、公开透明、受益人和负担人相一致的原则。"},{"i":20,"n":"第二十条","txt":"住宅共用部位、共用设施设备的维修和更新、改造费用，按照下列规定分摊： （一）商品住宅之间或者商品住宅与非住宅之间共用部位、共用设施设备的维修和更新、改造费用，由相关业主按照各自拥有物业建筑面积的比例分摊。 （二）售后公有住房之间共用部位、共用设施设备的维修和更新、改造费用，由相关业主和公有住房售房单位按照所交存住宅专项维修资金的比例分摊；其中，应由业主承担的，再由相关业主按照各自拥有物业建筑面积的比例分摊。 （三）售后公有住房与商品住宅或者非住宅之间共用部位、共用设施设备的维修和更新、改造费用，先按照建筑面积比例分摊到各相关物业。其中，售后公有住房应分摊的费用，再由相关业主和公有住房售房单位按照所交存住宅专项维修资金的比例分摊。"},{"i":21,"n":"第二十一条","txt":"住宅共用部位、共用设施设备维修和更新、改造，涉及尚未售出的商品住宅、非住宅或者公有住房的，开发建设单位或者公有住房单位应当按照尚未售出商品住宅或者公有住房的建筑面积，分摊维修和更新、改造费用。"},{"i":22,"n":"第二十二条","txt":"住宅专项维修资金划转业主大会管理前，需要使用住宅专项维修资金的，按照以下程序办理： （一）物业服务企业根据维修和更新、改造项目提出使用建议；没有物业服务企业的，由相关业主提出使用建议； （二）住宅专项维修资金列支范围内专有部分占建筑物总面积三分之二以上的业主且占总人数三分之二以上的业主讨论通过使用建议； （三）物业服务企业或者相关业主组织实施使用方案； （四）物业服务企业或者相关业主持有关材料，向所在地直辖市、市、县人民政府建设（房地产）主管部门申请列支；其中，动用公有住房住宅专项维修资金的，向负责管理公有住房住宅专项维修资金的部门申请列支； （五）直辖市、市、县人民政府建设（房地产）主管部门或者负责管理公有住房住宅专项维修资金的部门审核同意后，向专户管理银行发出划转住宅专项维修资金的通知； （六）专户管理银行将所需住宅专项维修资金划转至维修单位。"},{"i":23,"n":"第二十三条","txt":"住宅专项维修资金划转业主大会管理后，需要使用住宅专项维修资金的，按照以下程序办理： （一）物业服务企业提出使用方案，使用方案应当包括拟维修和更新、改造的项目、费用预算、列支范围、发生危及房屋安全等紧急情况以及其他需临时使用住宅专项维修资金的情况的处置办法等； （二）业主大会依法通过使用方案； （三）物业服务企业组织实施使用方案； （四）物业服务企业持有关材料向业主委员会提出列支住宅专项维修资金；其中，动用公有住房住宅专项维修资金的，向负责管理公有住房住宅专项维修资金的部门申请列支； （五）业主委员会依据使用方案审核同意，并报直辖市、市、县人民政府建设（房地产）主管部门备案；动用公有住房住宅专项维修资金的，经负责管理公有住房住宅专项维修资金的部门审核同意；直辖市、市、县人民政府建设（房地产）主管部门或者负责管理公有住房住宅专项维修资金的部门发现不符合有关法律、法规、规章和使用方案的，应当"},{"i":24,"n":"第二十四条","txt":"发生危及房屋安全等紧急情况，需要立即对住宅共用部位、共用设施设备进行维修和更新、改造的，按照以下规定列支住宅专项维修资金： （一）住宅专项维修资金划转业主大会管理前，按照本办法第二十二条第四项、第五项、第六项的规定办理； （二）住宅专项维修资金划转业主大会管理后，按照本办法第二十三条第四项、第五项、第六项和第七项的规定办理。 发生前款情况后，未按规定实施维修和更新、改造的，直辖市、市、县人民政府建设（房地产）主管部门可以组织代修，维修费用从相关业主住宅专项维修资金分户账中列支；其中，涉及已售公有住房的，还应当从公有住房住宅专项维修资金中列支。"},{"i":25,"n":"第二十五条","txt":"下列费用不得从住宅专项维修资金中列支： （一）依法应当由建设单位或者施工单位承担的住宅共用部位、共用设施设备维修、更新和改造费用； （二）依法应当由相关单位承担的供水、供电、供气、供热、通讯、有线电视等管线和设施设备的维修、养护费用； （三）应当由当事人承担的因人为损坏住宅共用部位、共用设施设备所需的修复费用； （四）根据物业服务合同约定，应当由物业服务企业承担的住宅共用部位、共用设施设备的维修和养护费用。"},{"i":26,"n":"第二十六条","txt":"在保证住宅专项维修资金正常使用的前提下，可以按照国家有关规定将住宅专项维修资金用于购买国债。 利用住宅专项维修资金购买国债，应当在银行间债券市场或者商业银行柜台市场购买一级市场新发行的国债，并持有到期。 利用业主交存的住宅专项维修资金购买国债的，应当经业主大会同意；未成立业主大会的，应当经专有部分占建筑物总面积三分之二以上的业主且占总人数三分之二以上业主同意。 利用从公有住房售房款中提取的住宅专项维修资金购买国债的，应当根据售房单位的财政隶属关系，报经同级财政部门同意。 禁止利用住宅专项维修资金从事国债回购、委托理财业务或者将购买的国债用于质押、抵押等担保行为。"},{"i":27,"n":"第二十七条","txt":"下列资金应当转入住宅专项维修资金滚存使用： （一）住宅专项维修资金的存储利息； （二）利用住宅专项维修资金购买国债的增值收益； （三）利用住宅共用部位、共用设施设备进行经营的，业主所得收益，但业主大会另有决定的除外； （四）住宅共用设施设备报废后回收的残值。"},{"i":28,"n":"第二十八条","txt":"房屋所有权转让时，业主应当向受让人说明住宅专项维修资金交存和结余情况并出具有效证明，该房屋分户账中结余的住宅专项维修资金随房屋所有权同时过户。 受让人应当持住宅专项维修资金过户的协议、房屋权属证书、身份证等到专户管理银行办理分户账更名手续。"},{"i":29,"n":"第二十九条","txt":"房屋灭失的，按照以下规定返还住宅专项维修资金： （一）房屋分户账中结余的住宅专项维修资金返还业主； （二）售房单位交存的住宅专项维修资金账面余额返还售房单位；售房单位不存在的，按照售房单位财务隶属关系，收缴同级国库。"},{"i":30,"n":"第三十条","txt":"直辖市、市、县人民政府建设（房地产）主管部门，负责管理公有住房住宅专项维修资金的部门及业主委员会，应当每年至少一次与专户管理银行核对住宅专项维修资金账目，并向业主、公有住房售房单位公布下列情况： （一）住宅专项维修资金交存、使用、增值收益和结存的总额； （二）发生列支的项目、费用和分摊情况； （三）业主、公有住房售房单位分户账中住宅专项维修资金交存、使用、增值收益和结存的金额； （四）其他有关住宅专项维修资金使用和管理的情况。 业主、公有住房售房单位对公布的情况有异议的，可以要求复核。"},{"i":31,"n":"第三十一条","txt":"专户管理银行应当每年至少一次向直辖市、市、县人民政府建设（房地产）主管部门，负责管理公有住房住宅专项维修资金的部门及业主委员会发送住宅专项维修资金对账单。 直辖市、市、县建设（房地产）主管部门，负责管理公有住房住宅专项维修资金的部门及业主委员会对资金账户变化情况有异议的，可以要求专户管理银行进行复核。 专户管理银行应当建立住宅专项维修资金查询制度，接受业主、公有住房售房单位对其分户账中住宅专项维修资金使用、增值收益和账面余额的查询。"},{"i":32,"n":"第三十二条","txt":"住宅专项维修资金的管理和使用，应当依法接受审计部门的审计监督。"},{"i":33,"n":"第三十三条","txt":"住宅专项维修资金的财务管理和会计核算应当执行财政部有关规定。 财政部门应当加强对住宅专项维修资金收支财务管理和会计核算制度执行情况的监督。"},{"i":34,"n":"第三十四条","txt":"住宅专项维修资金专用票据的购领、使用、保存、核销管理，应当按照财政部以及省、自治区、直辖市人民政府财政部门的有关规定执行，并接受财政部门的监督检查。"},{"i":35,"n":"第三十五条","txt":"公有住房售房单位有下列行为之一的，由县级以上地方人民政府财政部门会同同级建设（房地产）主管部门责令限期改正： （一）未按本办法第八条、第十二条第三款规定交存住宅专项维修资金的； （二）违反本办法第十三条规定将房屋交付买受人的； （三）未按本办法第二十一条规定分摊维修、更新和改造费用的。"},{"i":36,"n":"第三十六条","txt":"开发建设单位违反本办法第十三条规定将房屋交付买受人的，由县级以上地方人民政府建设（房地产）主管部门责令限期改正；逾期不改正的，处以3万元以下的罚款。 开发建设单位未按本办法第二十一条规定分摊维修、更新和改造费用的，由县级以上地方人民政府建设（房地产）主管部门责令限期改正；逾期不改正的，处以1万元以下的罚款。"},{"i":37,"n":"第三十七条","txt":"违反本办法规定，挪用住宅专项维修资金的，由县级以上地方人民政府建设(房地产)主管部门追回挪用的住宅专项维修资金，没收违法所得，可以并处挪用金额2倍以下的罚款；构成犯罪的，依法追究直接负责的主管人员和其他直接责任人员的刑事责任。 物业服务企业挪用住宅专项维修资金，情节严重的，除按前款规定予以处罚外，还应由颁发资质证书的部门吊销资质证书。 直辖市、市、县人民政府建设（房地产）主管部门挪用住宅专项维修资金的，由上一级人民政府建设（房地产）主管部门追回挪用的住宅专项维修资金，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。 直辖市、市、县人民政府财政部门挪用住宅专项维修资金的，由上一级人民政府财政部门追回挪用的住宅专项维修资金，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"直辖市、市、县人民政府建设（房地产）主管部门违反本办法第二十六条规定的，由上一级人民政府建设（房地产）主管部门责令限期改正，对直接负责的主管人员和其他直接责任人员依法给予处分；造成损失的，依法赔偿；构成犯罪的，依法追究刑事责任。 直辖市、市、县人民政府财政部门违反本办法第二十六条规定的，由上一级人民政府财政部门责令限期改正，对直接负责的主管人员和其他直接责任人员依法给予处分；造成损失的，依法赔偿；构成犯罪的，依法追究刑事责任。 业主大会违反本办法第二十六条规定的，由直辖市、市、县人民政府建设（房地产）主管部门责令改正。"},{"i":39,"n":"第三十九条","txt":"对违反住宅专项维修资金专用票据管理规定的行为，按照《财政违法行为处罚处分条例》的有关规定追究法律责任。"},{"i":40,"n":"第四十条","txt":"县级以上人民政府建设（房地产）主管部门、财政部门及其工作人员利用职务上的便利，收受他人财物或者其他好处，不依法履行监督管理职责，或者发现违法行为不予查处的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"省、自治区、直辖市人民政府建设（房地产）主管部门会同同级财政部门可以依据本办法，制定实施细则。"},{"i":42,"n":"第四十二条","txt":"本办法实施前，商品住宅、公有住房已经出售但未建立住宅专项维修资金的，应当补建。具体办法由省、自治区、直辖市人民政府建设（房地产）主管部门会同同级财政部门依据本办法制定。"},{"i":43,"n":"第四十三条","txt":"本办法由国务院建设主管部门、财政部门共同解释。"},{"i":44,"n":"第四十四条","txt":"本办法自2008年2月1日起施行，1998年12月16日建设部、财政部发布的《住宅共用部位共用设施设备维修基金管理办法》（建住房[1998]213号）同时废止。"}],"zhuzhaishineizhuangshizhuangxiuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强住宅室内装饰装修管理，保证装饰装修工程质量和安全，维护公共安全和公众利益，根据有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在城市从事住宅室内装饰装修活动，实施对住宅室内装饰装修活动的监督管理，应当遵守本办法。 本办法所称住宅室内装饰装修，是指住宅竣工验收合格后，业主或者住宅使用人（以下简称装修人）对住宅室内进行装饰装修的建筑活动。"},{"i":3,"n":"第三条","txt":"住宅室内装饰装修应当保证工程质量和安全，符合工程建设强制性标准。"},{"i":4,"n":"第四条","txt":"国务院建设行政主管部门负责全国住宅室内装饰装修活动的管理工作。 省、自治区人民政府建设行政主管部门负责本行政区域内的住宅室内装饰装修活动的管理工作。 直辖市、市、县人民政府房地产行政主管部门负责本行政区域内的住宅室内装饰装修活动的管理工作。"},{"i":5,"n":"第五条","txt":"住宅室内装饰装修活动，禁止下列行为： （一）未经原设计单位或者具有相应资质等级的设计单位提出设计方案，变动建筑主体和承重结构； （二）将没有防水要求的房间或者阳台改为卫生间、厨房间； （三）扩大承重墙上原有的门窗尺寸，拆除连接阳台的砖、混凝土墙体； （四）损坏房屋原有节能设施，降低节能效果； （五）其他影响建筑结构和使用安全的行为。 本办法所称建筑主体，是指建筑实体的结构构造，包括屋盖、楼盖、梁、柱、支撑、墙体、连接接点和基础等。 本办法所称承重结构，是指直接将本身自重与各种外加作用力系统地传递给基础地基的主要结构构件和其连接接点，包括承重墙体、立杆、柱、框架柱、支墩、楼板、梁、屋架、悬索等。"},{"i":6,"n":"第六条","txt":"装修人从事住宅室内装饰装修活动，未经批准，不得有下列行为： （一）搭建建筑物、构筑物； （二）改变住宅外立面，在非承重外墙上开门、窗； （三）拆改供暖管道和设施； （四）拆改燃气管道和设施。 本条所列第（一）项、第（二）项行为，应当经城市规划行政主管部门批准；第（三）项行为，应当经供暖管理单位批准；第（四）项行为应当经燃气管理单位批准。"},{"i":7,"n":"第七条","txt":"住宅室内装饰装修超过设计标准或者规范增加楼面荷载的，应当经原设计单位或者具有相应资质等级的设计单位提出设计方案。"},{"i":8,"n":"第八条","txt":"改动卫生间、厨房间防水层的，应当按照防水标准制订施工方案，并做闭水试验。"},{"i":9,"n":"第九条","txt":"装修人经原设计单位或者具有相应资质等级的设计单位提出设计方案变动建筑主体和承重结构的，或者装修活动涉及本办法第六条　、第七条　、第八条内容的，必须委托具有相应资质的装饰装修企业承担。"},{"i":10,"n":"第十条","txt":"装饰装修企业必须按照工程建设强制性标准和其他技术标准施工，不得偷工减料，确保装饰装修工程质量。"},{"i":11,"n":"第十一条","txt":"装饰装修企业从事住宅室内装饰装修活动，应当遵守施工安全操作规程，按照规定采取必要的安全防护和消防措施，不得擅自动用明火和进行焊接作业，保证作业人员和周围住房及财产的安全。"},{"i":12,"n":"第十二条","txt":"装修人和装饰装修企业从事住宅室内装饰装修活动，不得侵占公共空间，不得损害公共部位和设施。"},{"i":13,"n":"第十三条","txt":"装修人在住宅室内装饰装修工程开工前，应当向物业管理企业或者房屋管理机构（以下简称物业管理单位）申报登记。 非业主的住宅使用人对住宅室内进行装饰装修，应当取得业主的书面同意。"},{"i":14,"n":"第十四条","txt":"申报登记应当提交下列材料： （一）房屋所有权证（或者证明其合法权益的有效凭证）； （二）申请人身份证件； （三）装饰装修方案； （四）变动建筑主体或者承重结构的，需提交原设计单位或者具有相应资质等级的设计单位提出的设计方案； （五）涉及本办法第六条行为的，需提交有关部门的批准文件，涉及本办法第七条　、第八条行为的，需提交设计方案或者施工方案； （六）委托装饰装修企业施工的，需提供该企业相关资质证书的复印件。 非业主的住宅使用人，还需提供业主同意装饰装修的书面证明。"},{"i":15,"n":"第十五条","txt":"物业管理单位应当将住宅室内装饰装修工程的禁止行为和注意事项告知装修人和装修人委托的装饰装修企业。 装修人对住宅进行装饰装修前，应当告知邻里。"},{"i":16,"n":"第十六条","txt":"装修人，或者装修人和装饰装修企业，应当与物业管理单位签订住宅室内装饰装修管理服务协议。 住宅室内装饰装修管理服务协议应当包括下列内容： （一）装饰装修工程的实施内容； （二）装饰装修工程的实施期限； （三）允许施工的时间； （四）废弃物的清运与处置； （五）住宅外立面设施及防盗窗的安装要求； （六）禁止行为和注意事项； （七）管理服务费用； （八）违约责任； （九）其他需要约定的事项。"},{"i":17,"n":"第十七条","txt":"物业管理单位应当按照住宅室内装饰装修管理服务协议实施管理，发现装修人或者装饰装修企业有本办法第五条行为的，或者未经有关部门批准实施本办法第六条所列行为的，或者有违反本办法第七条　、第八条　、第九条规定行为的，应当立即制止；已造成事实后果或者拒不改正的，应当及时报告有关部门依法处理。对装修人或者装饰装修企业违反住宅室内装饰装修管理服务协议的，追究违约责任。"},{"i":18,"n":"第十八条","txt":"有关部门接到物业管理单位关于装修人或者装饰装修企业有违反本办法行为的报告后，应当及时到现场检查核实，依法处理。"},{"i":19,"n":"第十九条","txt":"禁止物业管理单位向装修人指派装饰装修企业或者强行推销装饰装修材料。"},{"i":20,"n":"第二十条","txt":"装修人不得拒绝和阻碍物业管理单位依据住宅室内装饰装修管理服务协议的约定，对住宅室内装饰装修活动的监督检查。"},{"i":21,"n":"第二十一条","txt":"任何单位和个人对住宅室内装饰装修中出现的影响公众利益的质量事故、质量缺陷以及其他影响周围住户正常生活的行为，都有权检举、控告、投诉。"},{"i":22,"n":"第二十二条","txt":"承接住宅室内装饰装修工程的装饰装修企业，必须经建设行政主管部门资质审查，取得相应的建筑业企业资质证书，并在其资质等级许可的范围内承揽工程。"},{"i":23,"n":"第二十三条","txt":"装修人委托企业承接其装饰装修工程的，应当选择具有相应资质等级的装饰装修企业。"},{"i":24,"n":"第二十四条","txt":"装修人与装饰装修企业应当签订住宅室内装饰装修书面合同，明确双方的权利和义务。 住宅室内装饰装修合同应当包括下列主要内容： （一）委托人和被委托人的姓名或者单位名称、住所地址、联系电话； （二）住宅室内装饰装修的房屋间数、建筑面积，装饰装修的项目、方式、规格、质量要求以及质量验收方式； （三）装饰装修工程的开工、竣工时间； （四）装饰装修工程保修的内容、期限； （五）装饰装修工程价格，计价和支付方式、时间； （六）合同变更和解除的条件； （七）违约责任及解决纠纷的途径； （八）合同的生效时间； （九）双方认为需要明确的其他条款。"},{"i":25,"n":"第二十五条","txt":"住宅室内装饰装修工程发生纠纷的，可以协商或者调解解决。不愿协商、调解或者协商、调解不成的，可以依法申请仲裁或者向人民法院起诉。"},{"i":26,"n":"第二十六条","txt":"装饰装修企业从事住宅室内装饰装修活动，应当严格遵守规定的装饰装修施工时间，降低施工噪音，减少环境污染。"},{"i":27,"n":"第二十七条","txt":"住宅室内装饰装修过程中所形成的各种固体、可燃液体等废物，应当按照规定的位置、方式和时间堆放和清运。严禁违反规定将各种固体、可燃液体等废物堆放于住宅垃圾道、楼道或者其他地方。"},{"i":28,"n":"第二十八条","txt":"住宅室内装饰装修工程使用的材料和设备必须符合国家标准，有质量检验合格证明和有中文标识的产品名称、规格、型号、生产厂厂名、厂址等。禁止使用国家明令淘汰的建筑装饰装修材料和设备。"},{"i":29,"n":"第二十九条","txt":"装修人委托企业对住宅室内进行装饰装修的，装饰装修工程竣工后，空气质量应当符合国家有关标准。装修人可以委托有资格的检测单位对空气质量进行检测。检测不合格的，装饰装修企业应当返工，并由责任人承担相应损失。"},{"i":30,"n":"第三十条","txt":"住宅室内装饰装修工程竣工后，装修人应当按照工程设计合同约定和相应的质量标准进行验收。验收合格后，装饰装修企业应当出具住宅室内装饰装修质量保修书。 物业管理单位应当按照装饰装修管理服务协议进行现场检查，对违反法律、法规和装饰装修管理服务协议的，应当要求装修人和装饰装修企业纠正，并将检查记录存档。"},{"i":31,"n":"第三十一条","txt":"住宅室内装饰装修工程竣工后，装饰装修企业负责采购装饰装修材料及设备的，应当向业主提交说明书、保修单和环保说明书。"},{"i":32,"n":"第三十二条","txt":"在正常使用条件下，住宅室内装饰装修工程的最低保修期限为二年，有防水要求的厨房、卫生间和外墙面的防渗漏为五年。保修期自住宅室内装饰装修工程竣工验收合格之日起计算。"},{"i":33,"n":"第三十三条","txt":"因住宅室内装饰装修活动造成相邻住宅的管道堵塞、渗漏水、停水停电、物品毁坏等，装修人应当负责修复和赔偿；属于装饰装修企业责任的，装修人可以向装饰装修企业追偿。 装修人擅自拆改供暖、燃气管道和设施造成损失的，由装修人负责赔偿。"},{"i":34,"n":"第三十四条","txt":"装修人因住宅室内装饰装修活动侵占公共空间，对公共部位和设施造成损害的，由城市房地产行政主管部门责令改正，造成损失的，依法承担赔偿责任。"},{"i":35,"n":"第三十五条","txt":"装修人未申报登记进行住宅室内装饰装修活动的，由城市房地产行政主管部门责令改正，处5百元以上1千元以下的罚款。"},{"i":36,"n":"第三十六条","txt":"装修人违反本办法规定，将住宅室内装饰装修工程委托给不具有相应资质等级企业的，由城市房地产行政主管部门责令改正，处5百元以上1千元以下的罚款。"},{"i":37,"n":"第三十七条","txt":"装饰装修企业自行采购或者向装修人推荐使用不符合国家标准的装饰装修材料，造成空气污染超标的，由城市房地产行政主管部门责令改正，造成损失的，依法承担赔偿责任。"},{"i":38,"n":"第三十八条","txt":"住宅室内装饰装修活动有下列行为之一的，由城市房地产行政主管部门责令改正，并处罚款： （一）将没有防水要求的房间或者阳台改为卫生间、厨房间的，或者拆除连接阳台的砖、混凝土墙体的，对装修人处5百元以上1千元以下的罚款，对装饰装修企业处1千元以上1万元以下的罚款； （二）损坏房屋原有节能设施或者降低节能效果的，对装饰装修企业处1千元以上5千元以下的罚款； （三）擅自拆改供暖、燃气管道和设施的，对装修人处5百元以上1千元以下的罚款； （四）未经原设计单位或者具有相应资质等级的设计单位提出设计方案，擅自超过设计标准或者规范增加楼面荷载的，对装修人处5百元以上1千元以下的罚款，对装饰装修企业处1千元以上1万元以下的罚款。"},{"i":39,"n":"第三十九条","txt":"未经城市规划行政主管部门批准，在住宅室内装饰装修活动中搭建建筑物、构筑物的，或者擅自改变住宅外立面、在非承重外墙上开门、窗的，由城市规划行政主管部门按照《中华人民共和国城乡规划法》及相关法规的规定处罚。"},{"i":40,"n":"第四十条","txt":"装修人或者装饰装修企业违反《建设工程质量管理条例》的，由建设行政主管部门按照有关规定处罚。"},{"i":41,"n":"第四十一条","txt":"装饰装修企业违反国家有关安全生产规定和安全生产技术规程，不按照规定采取必要的安全防护和消防措施，擅自动用明火作业和进行焊接作业的，或者对建筑安全事故隐患不采取措施予以消除的，由建设行政主管部门责令改正，并处1千元以上1万元以下的罚款；情节严重的，责令停业整顿，并处1万元以上3万元以下的罚款；造成重大安全事故的，降低资质等级或者吊销资质证书。"},{"i":42,"n":"第四十二条","txt":"物业管理单位发现装修人或者装饰装修企业有违反本办法规定的行为不及时向有关部门报告的，由房地产行政主管部门给予警告，可处装饰装修管理服务协议约定的装饰装修管理服务费2至3倍的罚款。"},{"i":43,"n":"第四十三条","txt":"有关部门的工作人员接到物业管理单位对装修人或者装饰装修企业违法行为的报告后，未及时处理，玩忽职守的，依法给予行政处分。"},{"i":44,"n":"第四十四条","txt":"工程投资额在30万元以下或者建筑面积在300平方米以下，可以不申请办理施工许可证的非住宅装饰装修活动参照本办法执行。"},{"i":45,"n":"第四十五条","txt":"住宅竣工验收合格前的装饰装修工程管理，按照《建设工程质量管理条例》执行。"},{"i":46,"n":"第四十六条","txt":"省、自治区、直辖市人民政府建设行政主管部门可以依据本办法，制定实施细则。"},{"i":47,"n":"第四十七条","txt":"本办法由国务院建设行政主管部门负责解释。"},{"i":48,"n":"第四十八条","txt":"本办法自2002年5月1日起施行。"}],"zhufanghechengxiangjianshexingzhengchufachengxuguifa844e":[{"i":1,"n":"第一条","txt":"为保障和监督住房和城乡建设行政执法机关有效实施行政处罚，保护公民、法人或者其他组织的合法权益，促进住房和城乡建设行政执法工作规范化，根据《中华人民共和国行政处罚法》等法律法规，结合住房和城乡建设工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"住房和城乡建设行政执法机关（以下简称执法机关）对违反相关法律、法规、规章的公民、法人或者其他组织依法实施行政处罚，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定适用的行政处罚种类包括： （一）警告、通报批评； （二）罚款、没收违法所得、没收非法财物； （三）暂扣许可证件、降低资质等级、吊销许可证件； （四）限制开展生产经营活动、责令停业整顿、责令停止执业、限制从业； （五）法律、行政法规规定的其他行政处罚。"},{"i":4,"n":"第四条","txt":"执法机关实施行政处罚，应当遵循公正、公开的原则，坚持处罚与教育相结合，做到认定事实清楚、证据合法充分、适用依据准确、程序合法、处罚适当。"},{"i":5,"n":"第五条","txt":"行政处罚由违法行为发生地的执法机关管辖。法律、行政法规、部门规章另有规定的，从其规定。 行政处罚由县级以上地方人民政府执法机关管辖。法律、行政法规另有规定的，从其规定。"},{"i":6,"n":"第六条","txt":"执法机关发现案件不属于本机关管辖的，应当将案件移送有管辖权的行政机关。 行政处罚过程中发生的管辖权争议，应当自发生争议之日起七日内协商解决，并制作保存协商记录；协商不成的，报请共同的上一级行政机关指定管辖。上一级执法机关应当自收到报请材料之日起七日内指定案件的管辖机关。"},{"i":7,"n":"第七条","txt":"执法机关发现违法行为涉嫌犯罪的，应当依法将案件移送司法机关。"},{"i":8,"n":"第八条","txt":"执法机关应当将本机关负责实施的行政处罚事项、立案依据、实施程序和救济渠道等信息予以公示。"},{"i":9,"n":"第九条","txt":"执法机关应当依法以文字、音像等形式，对行政处罚的启动、调查取证、审核、决定、送达、执行等进行全过程记录，归档保存。 住房和城乡建设行政处罚文书示范文本，由国务院住房和城乡建设主管部门制定。省、自治区、直辖市人民政府执法机关可以参照制定适用于本行政区域的行政处罚文书示范文本。"},{"i":10,"n":"第十条","txt":"执法机关作出具有一定社会影响的行政处罚决定，应当自作出决定之日起七日内依法公开。公开的行政处罚决定信息不得泄露国家秘密。涉及商业秘密和个人隐私的，应当依照有关法律法规规定处理。 公开的行政处罚决定被依法变更、撤销、确认违法或者确认无效的，执法机关应当在三日内撤回行政处罚决定信息并公开说明理由；相关行政处罚决定信息已推送至其他行政机关或者有关信用信息平台的，应当依照有关规定及时处理。"},{"i":11,"n":"第十一条","txt":"行政处罚应当由两名以上具有行政执法资格的执法人员实施，法律另有规定的除外。执法人员应当依照有关规定参加执法培训和考核，取得执法证件。 执法人员在案件调查取证、听取陈述申辩、参加听证、送达执法文书等直接面对当事人或者有关人员的活动中，应当主动出示执法证件。配备统一执法制式服装或者执法标志标识的，应当按照规定着装或者佩戴执法标志标识。"},{"i":12,"n":"第十二条","txt":"违法事实确凿并有法定依据，对公民处以二百元以下、对法人或者其他组织处以三千元以下罚款或者警告的行政处罚的，可以当场作出行政处罚决定。法律另有规定的，从其规定。"},{"i":13,"n":"第十三条","txt":"当场作出行政处罚决定的，执法人员应当向当事人出示执法证件，填写预定格式、编有号码的行政处罚决定书，并当场交付当事人。当事人拒绝签收的，应当在行政处罚决定书上注明。 当事人提出陈述、申辩的，执法人员应当听取当事人的意见，并复核事实、理由和证据。"},{"i":14,"n":"第十四条","txt":"当场作出的行政处罚决定书应当载明当事人的违法行为，行政处罚的种类和依据、罚款数额、时间、地点，申请行政复议、提起行政诉讼的途径和期限以及执法机关名称，并由执法人员签名或者盖章。 执法人员当场作出的行政处罚决定，应当在三日内报所属执法机关备案。"},{"i":15,"n":"第十五条","txt":"执法机关对依据监督检查职权或者通过投诉、举报等途径发现的违法行为线索，应当在十五日内予以核查，情况复杂确实无法按期完成的，经本机关负责人批准，可以延长十日。 经核查，符合下列条件的，应当予以立案： （一）有初步证据证明存在违法行为； （二）违法行为属于本机关管辖； （三）违法行为未超过行政处罚时效。 立案应当填写立案审批表，附上相关材料，报本机关负责人批准。 立案前核查或者监督检查过程中依法取得的证据材料，可以作为案件的证据使用。"},{"i":16,"n":"第十六条","txt":"执法人员询问当事人及有关人员，应当个别进行并制作笔录，笔录经被询问人核对、修改差错、补充遗漏后，由被询问人逐页签名或者盖章。"},{"i":17,"n":"第十七条","txt":"执法人员收集、调取的书证、物证应当是原件、原物。调取原件、原物有困难的，可以提取复制件、影印件或者抄录件，也可以拍摄或者制作足以反映原件、原物外形或者内容的照片、录像。复制件、影印件、抄录件和照片、录像应当标明经核对与原件或者原物一致，并由证据提供人、执法人员签名或者盖章。 提取物证应当有当事人在场，对所提取的物证应当开具物品清单，由执法人员和当事人签名或者盖章，各执一份。无法找到当事人，或者当事人在场确有困难、拒绝到场、拒绝签字的，执法人员可以邀请有关基层组织的代表或者无利害关系的其他人到场见证，也可以用录像等方式进行记录，依照有关规定提取物证。 对违法嫌疑物品或者场所进行检查时，应当通知当事人在场，并制作现场笔录，载明时间、地点、事件等内容，由执法人员、当事人签名或者盖章。无法找到当事人，或者当事人在场确有困难、拒绝到场、拒绝签字的，应当用录像等方式记录检查过程并在现场笔录中注明。"},{"i":18,"n":"第十八条","txt":"为了查明案情，需要进行检测、检验、鉴定的，执法机关应当依法委托具备相应条件的机构进行。检测、检验、鉴定结果应当告知当事人。 执法机关因实施行政处罚的需要，可以向有关机关出具协助函，请求有关机关协助进行调查取证等。"},{"i":19,"n":"第十九条","txt":"执法机关查处违法行为过程中，在证据可能灭失或者以后难以取得的情况下，经本机关负责人批准，可以对证据先行登记保存。 先行登记保存证据，应当当场清点，开具清单，标注物品的名称、数量、规格、型号、保存地点等信息，清单由执法人员和当事人签名或者盖章，各执一份。当事人拒绝签字的，执法人员在执法文书中注明，并通过录像等方式保留相应证据。先行登记保存期间，当事人或者有关人员不得销毁或者转移证据。 对于先行登记保存的证据，应当在七日内作出以下处理决定： （一）根据情况及时采取记录、复制、拍照、录像等证据保全措施； （二）需要检测、检验、鉴定的，送交检测、检验、鉴定； （三）依据有关法律、法规规定应当采取查封、扣押等行政强制措施的，决定采取行政强制措施； （四）违法事实成立，依法应当予以没收的，依照法定程序处理； （五）违法事实不成立，或者违法事实成立但依法不应当予以查封、扣押或者没收的，决定解除先行登"},{"i":20,"n":"第二十条","txt":"案件调查终结，执法人员应当制作书面案件调查终结报告。 案件调查终结报告的内容包括：当事人的基本情况、案件来源及调查经过、调查认定的事实及主要证据、行政处罚意见及依据、裁量基准的运用及理由等。 对涉及生产安全事故的案件，执法人员应当依据经批复的事故调查报告认定有关情况。"},{"i":21,"n":"第二十一条","txt":"行政处罚决定作出前，执法机关应当制作行政处罚意见告知文书，告知当事人拟作出的行政处罚内容及事实、理由、依据以及当事人依法享有的陈述权、申辩权。拟作出的行政处罚属于听证范围的，还应当告知当事人有要求听证的权利。"},{"i":22,"n":"第二十二条","txt":"执法机关必须充分听取当事人的意见，对当事人提出的事实、理由和证据进行复核，并制作书面复核意见。当事人提出的事实、理由或者证据成立的，执法机关应当予以采纳，不得因当事人陈述、申辩而给予更重的处罚。 当事人自行政处罚意见告知文书送达之日起五日内，未行使陈述权、申辩权，视为放弃此权利。"},{"i":23,"n":"第二十三条","txt":"在作出《中华人民共和国行政处罚法》第五十八条规定情形的行政处罚决定前，执法人员应当将案件调查终结报告连同案件材料，提交执法机关负责法制审核工作的机构，由法制审核人员进行重大执法决定法制审核。未经法制审核或者审核未通过的，不得作出决定。"},{"i":24,"n":"第二十四条","txt":"执法机关负责法制审核工作的机构接到审核材料后，应当登记并审核以下内容： （一）行政处罚主体是否合法，行政执法人员是否具备执法资格； （二）行政处罚程序是否合法； （三）当事人基本情况、案件事实是否清楚，证据是否合法充分； （四）适用法律、法规、规章是否准确，裁量基准运用是否适当； （五）是否超越执法机关法定权限； （六）行政处罚文书是否完备、规范； （七）违法行为是否涉嫌犯罪、需要移送司法机关； （八）法律、法规规定应当审核的其他内容。"},{"i":25,"n":"第二十五条","txt":"执法机关负责法制审核工作的机构应当自收到审核材料之日起十日内完成审核，并提出以下书面意见： （一）对事实清楚、证据合法充分、适用依据准确、处罚适当、程序合法的案件，同意处罚意见； （二）对事实不清、证据不足的案件，建议补充调查； （三）对适用依据不准确、处罚不当、程序不合法的案件，建议改正； （四）对超出法定权限的案件，建议按有关规定移送。 对执法机关负责法制审核工作的机构提出的意见，执法人员应当进行研究，作出相应处理后再次报送法制审核。"},{"i":26,"n":"第二十六条","txt":"执法机关负责人应当对案件调查结果进行审查，根据不同情况，分别作出如下决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为涉嫌犯罪的，移送司法机关。 对情节复杂或者重大违法行为给予行政处罚，执法机关负责人应当集体讨论决定。"},{"i":27,"n":"第二十七条","txt":"执法机关对当事人作出行政处罚，应当制作行政处罚决定书。行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）违反法律、法规、规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）申请行政复议、提起行政诉讼的途径和期限； （六）作出行政处罚决定的执法机关名称和作出决定的日期。 行政处罚决定书必须盖有作出行政处罚决定的执法机关的印章。"},{"i":28,"n":"第二十八条","txt":"行政处罚决定生效后，任何人不得擅自变更或者撤销。作出行政处罚决定的执法机关发现确需变更或者撤销的，应当依法办理。 行政处罚决定存在未载明决定作出日期等遗漏，对公民、法人或者其他组织的合法权益没有实际影响等情形的，应当予以补正。 行政处罚决定存在文字表述错误或者计算错误等情形，应当予以更正。 执法机关作出补正或者更正的，应当制作补正或者更正文书。"},{"i":29,"n":"第二十九条","txt":"执法机关应当自立案之日起九十日内作出行政处罚决定。因案情复杂或者其他原因，不能在规定期限内作出行政处罚决定的，经本机关负责人批准，可以延长三十日。案情特别复杂或者有其他特殊情况，经延期仍不能作出行政处罚决定的，应当由本机关负责人集体讨论决定是否再次延期，决定再次延期的，再次延长的期限不得超过六十日。 案件处理过程中，听证、检测、检验、鉴定等时间不计入前款规定的期限。"},{"i":30,"n":"第三十条","txt":"案件处理过程中，有下列情形之一，经执法机关负责人批准，中止案件调查： （一）行政处罚决定须以相关案件的裁判结果或者其他行政决定为依据，而相关案件尚未审结或者其他行政决定尚未作出的； （二）涉及法律适用等问题，需要报请有权机关作出解释或者确认的； （三）因不可抗力致使案件暂时无法调查的； （四）因当事人下落不明致使案件暂时无法调查的； （五）其他应当中止调查的情形。 中止调查情形消失，执法机关应当及时恢复调查程序。中止调查的时间不计入案件办理期限。"},{"i":31,"n":"第三十一条","txt":"行政处罚案件有下列情形之一，执法人员应当在十五日内填写结案审批表，经本机关负责人批准后，予以结案： （一）行政处罚决定执行完毕的； （二）依法终结执行的； （三）因不能认定违法事实或者违法行为已过行政处罚时效等情形，案件终止调查的； （四）依法作出不予行政处罚决定的； （五）其他应予结案的情形。"},{"i":32,"n":"第三十二条","txt":"执法机关在作出较大数额罚款、没收较大数额违法所得、没收较大价值非法财物、降低资质等级、吊销许可证件、责令停业整顿、责令停止执业、限制从业等较重行政处罚决定之前，应当告知当事人有要求听证的权利。"},{"i":33,"n":"第三十三条","txt":"当事人要求听证的，应当自行政处罚意见告知文书送达之日起五日内以书面或者口头方式向执法机关提出。"},{"i":34,"n":"第三十四条","txt":"执法机关应当在举行听证的七日前，通知当事人及有关人员听证的时间、地点。 听证由执法机关指定的非本案调查人员主持，并按以下程序进行： （一）听证主持人宣布听证纪律和流程，并告知当事人申请回避的权利； （二）调查人员提出当事人违法的事实、证据和行政处罚建议，并向当事人出示证据； （三）当事人进行申辩，并对证据的真实性、合法性和关联性进行质证； （四）调查人员和当事人分别进行总结陈述。 听证应当制作笔录，全面、准确记录调查人员和当事人陈述内容、出示证据和质证等情况。笔录应当由当事人或者其代理人核对无误后签字或者盖章。当事人或者其代理人拒绝签字或者盖章的，由听证主持人在笔录中注明。执法机关应当根据听证笔录，依法作出决定。"},{"i":35,"n":"第三十五条","txt":"执法机关应当依照《中华人民共和国行政处罚法》《中华人民共和国民事诉讼法》的有关规定送达行政处罚意见告知文书和行政处罚决定书。 执法机关送达行政处罚意见告知文书或者行政处罚决定书，应当直接送交受送达人，由受送达人在送达回证上签名或者盖章，并注明签收日期。签收日期为送达日期。 受送达人拒绝接收行政处罚意见告知文书或者行政处罚决定书的，送达人可以邀请有关基层组织或者所在单位的代表到场见证，在送达回证上注明拒收事由和日期，由送达人、见证人签名或者盖章，把行政处罚意见告知文书或者行政处罚决定书留在受送达人的住所；也可以将行政处罚意见告知文书或者行政处罚决定书留在受送达人的住所，并采取拍照、录像等方式记录送达过程，即视为送达。"},{"i":36,"n":"第三十六条","txt":"行政处罚意见告知文书或者行政处罚决定书直接送达有困难的，按照下列方式送达： （一）委托当地执法机关代为送达的，依照本规定第三十五条执行； （二）邮寄送达的，交由邮政企业邮寄。挂号回执上注明的收件日期或者通过中国邮政网站等查询到的收件日期为送达日期。 受送达人下落不明，或者采用本章其他方式无法送达的，执法机关可以通过本机关或者本级人民政府网站公告送达，也可以根据需要在当地主要新闻媒体公告或者在受送达人住所地、经营场所公告送达。"},{"i":37,"n":"第三十七条","txt":"当事人同意以电子方式送达的，应当签订确认书，准确提供用于接收行政处罚意见告知文书、行政处罚决定书和有关文书的传真号码、电子邮箱地址或者即时通讯账号，并提供特定系统发生故障时的备用联系方式。联系方式发生变更的，当事人应当在五日内书面告知执法机关。 当事人同意并签订确认书的，执法机关可以采取相应电子方式送达，并通过拍照、截屏、录音、录像等方式予以记录，传真、电子邮件、即时通讯信息等到达受送达人特定系统的日期为送达日期。"},{"i":38,"n":"第三十八条","txt":"当事人不履行行政处罚决定，执法机关可以依法强制执行或者申请人民法院强制执行。"},{"i":39,"n":"第三十九条","txt":"当事人不服执法机关作出的行政处罚决定，可以依法申请行政复议，也可以依法直接向人民法院提起行政诉讼。 行政复议和行政诉讼期间，行政处罚不停止执行，法律另有规定的除外。"},{"i":40,"n":"第四十条","txt":"结案后，执法人员应当将案件材料依照档案管理的有关规定立卷归档。案卷归档应当一案一卷、材料齐全、规范有序。 案卷材料按照下列类别归档，每一类别按照归档材料形成的时间先后顺序排列： （一）案源材料、立案审批表； （二）案件调查终结报告、行政处罚意见告知文书、行政处罚决定书等行政处罚文书及送达回证； （三）证据材料； （四）当事人陈述、申辩材料； （五）听证笔录； （六）书面复核意见、法制审核意见、集体讨论记录； （七）执行情况记录、财物处理单据； （八）其他有关材料。 执法机关应当依照有关规定对本机关和下级执法机关的行政处罚案卷进行评查。"},{"i":41,"n":"第四十一条","txt":"执法机关及其执法人员应当在法定职权范围内依照法定程序从事行政处罚活动。行政处罚没有依据或者实施主体不具有行政主体资格的，行政处罚无效。违反法定程序构成重大且明显违法的，行政处罚无效。"},{"i":42,"n":"第四十二条","txt":"执法机关从事行政处罚活动，应当自觉接受上级执法机关或者有关机关的监督管理。上级执法机关或者有关机关发现下级执法机关违法违规实施行政处罚的，应当依法责令改正，对直接负责的主管人员和有关执法人员给予处分。"},{"i":43,"n":"第四十三条","txt":"对于阻碍执法人员依法行使职权，打击报复执法人员的单位或者个人，由执法机关或者有关机关视情节轻重，依法追究其责任。"},{"i":44,"n":"第四十四条","txt":"执法机关应当对本行政区域内行政处罚案件进行统计。省、自治区、直辖市人民政府执法机关应当在每年3月底前，向国务院住房和城乡建设主管部门报送上一年度行政处罚案件统计数据。"},{"i":45,"n":"第四十五条","txt":"本规定中有关期间以日计算的，期间开始的日不计算在内。期间不包括行政处罚文书送达在途时间。期间届满的最后一日为法定节假日的，以法定节假日后的第一日为期间届满的日期。 本规定中“三日”“五日”“七日”“十日”“十五日”的规定，是指工作日，不含法定节假日。"},{"i":46,"n":"第四十六条","txt":"本规定自2022年5月1日起施行。1999年2月3日原建设部公布的《建设行政处罚程序暂行规定》同时废止。"}],"zhufangchengxiangjianshexingzhengfuyibanfa":[{"i":1,"n":"第一条","txt":"为规范住房城乡建设行政复议工作，防止和纠正违法或者不当的行政行为，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政复议法》和《中华人民共和国行政复议法实施条例》等相关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人和其他组织（以下统称申请人）依法向住房城乡建设行政复议机关申请行政复议，住房城乡建设行政复议机关（以下简称行政复议机关）开展行政复议工作，适用本办法。"},{"i":3,"n":"第三条","txt":"行政复议机关应当认真履行行政复议职责，遵循合法、公正、公开、及时、便民的原则，坚持有错必纠，保障法律、法规和规章的正确实施。 行政复议机关应当依照有关规定配备专职行政复议人员，为行政复议工作提供必要的物质和经费保障。"},{"i":4,"n":"第四条","txt":"行政复议机关负责法制工作的机构作为行政复议机构，办理行政复议有关事项，履行下列职责： （一）受理行政复议申请； （二）向有关组织和人员调查取证，查阅文件和资料，组织行政复议听证； （三）通知第三人参加行政复议； （四）主持行政复议调解，审查行政复议和解协议； （五）审查申请行政复议的行政行为是否合法与适当，提出处理建议，拟订行政复议决定； （六）法律、法规、规章规定的其他职责。"},{"i":5,"n":"第五条","txt":"行政复议机关可以根据行政复议工作的需要，设立行政复议委员会，其主要职责是： （一）制定行政复议工作的规则、程序； （二）对重大、复杂、疑难的行政复议案件提出处理意见； （三）对行政复议涉及的有权处理的规范性文件的审查提出处理意见； （四）其他需要决定的重大行政复议事项。"},{"i":6,"n":"第六条","txt":"专职行政复议人员应当具备与履行行政复议职责相适应的品行、专业知识和业务能力，定期参加业务培训。"},{"i":7,"n":"第七条","txt":"国务院住房城乡建设主管部门对全国住房城乡建设行政复议工作进行指导。 县级以上地方人民政府住房城乡建设主管部门对本行政区域内的住房城乡建设行政复议工作进行指导。"},{"i":8,"n":"第八条","txt":"各级行政复议机关应当定期总结行政复议工作，对在行政复议工作中做出显著成绩的单位和个人，依照有关规定给予表彰和奖励。"},{"i":9,"n":"第九条","txt":"有下列情形之一的，申请人可以依法向住房城乡建设行政复议机关提出行政复议申请： （一）不服县级以上人民政府住房城乡建设主管部门作出的警告，罚款，没收违法所得，没收违法建筑物、构筑物和其他设施，责令停业整顿，责令停止执业，降低资质等级，吊销资质证书，吊销执业资格证书和其他许可证、执照等行政处罚的； （二）不服县级以上人民政府住房城乡建设主管部门作出的限期拆除决定和强制拆除违法建筑物、构筑物、设施以及其他住房城乡建设相关行政强制行为的； （三）不服县级以上人民政府住房城乡建设主管部门作出的行政许可决定以及行政许可的变更、延续、中止、撤销、撤回和注销决定的； （四）向县级以上人民政府住房城乡建设主管部门申请履行法律、法规和规章规定的法定职责，但认为县级以上人民政府住房城乡建设主管部门没有依法履行的； （五）认为县级以上人民政府住房城乡建设主管部门违法要求履行其他义务的； （六）认为县级以上人民"},{"i":10,"n":"第十条","txt":"有下列情形之一的，申请人提出行政复议申请，行政复议机关不予受理： （一）不服县级以上人民政府住房城乡建设主管部门作出的行政处分、人事任免有关决定，或者认为住房城乡建设主管部门应当履行但未依法履行有关行政处分、人事任免职责的； （二）不服县级以上人民政府住房城乡建设主管部门对有权处理的信访事项，根据《信访条例》作出的处理意见、复查意见、复核意见和不再受理决定的； （三）不服县级以上人民政府住房城乡建设主管部门制定的规范性文件，以及作出的行政调解行为、行政和解行为、行政复议决定的； （四）以行政复议申请名义，向行政复议机关提出批评、意见、建议、控告、检举、投诉，以及其他信访请求的； （五）申请人已就同一事项先向其他有权受理的行政复议机关提出行政复议申请的，或者人民法院已就该事项立案登记的； （六）被复议的行政行为已为其他生效法律文书的效力所羁束的； （七）法律、法规规定的不应纳入行政复议范"},{"i":11,"n":"第十一条","txt":"申请人书面申请行政复议的，可以采取当面递交、邮寄等方式，向行政复议机关提交行政复议申请书及有关材料；书面申请确有困难的，可以口头申请，由行政复议机关记入笔录，经由申请人核实后签名或者盖章确认。有条件的行政复议机关，可以提供行政复议网上申请的有关服务。 申请人不服县级以上人民政府住房城乡建设主管部门作出的两个及两个以上行政行为的，应当分别提出行政复议申请。"},{"i":12,"n":"第十二条","txt":"申请人以书面方式申请行政复议的，应当提交行政复议申请书正本副本各一份。复议申请书应当载明下列内容： （一）申请人姓名或者名称、地址； （二）被申请人的名称、地址； （三）行政复议请求； （四）主要事实和理由（包括知道行政行为的时间）； （五）提出行政复议申请的日期。 复议申请书应当由申请人或者申请人的法定代表人签字或者盖章，并附有必要的证据。申请人为自然人的，应当提交身份证件复印件；申请人为法人或者其他组织的，应当提交有效营业执照或者其他有效证件的复印件、法定代表人身份证明等。申请人授权委托人代为申请的，应当提交申请人与委托人的合法身份证明和授权委托书。"},{"i":13,"n":"第十三条","txt":"申请人认为行政行为侵犯其合法权益的，可以自知道或者应当知道该行政行为之日起60日内提出行政复议申请；但是法律规定的申请期限超过60日的除外。因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。 申请人认为行政机关不履行法定职责的，可以在法律、法规、规章规定的履行期限届满后，按照前款规定提出行政复议申请；法律、法规、规章没有规定履行期限的，可以自向行政机关提出申请满60日后，按照前款规定提出行政复议申请。 对涉及不动产的行政行为从作出之日起超过20年、其他行政行为从作出之日起超过5年申请行政复议的，行政复议机关不予受理。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的，申请人应当提供相应的证明材料： （一）认为被申请人行政不作为的，应当提供曾经要求被申请人履行法定职责而被申请人未履行的证明材料； （二）行政复议申请超出本办法第十三条规定的行政复议申请期限的，应当提供因不可抗力或者其他正当理由耽误法定申请期限的证明材料； （三）提出行政赔偿请求的，应当提供受行政行为侵害而造成损害的证明材料； （四）法律、法规和规章规定需要申请人提供证明材料的其他情形。"},{"i":15,"n":"第十五条","txt":"与行政行为有利害关系的其他公民、法人或者其他组织以书面形式提出申请，经行政复议机关审查同意，可以作为第三人参加行政复议。 行政复议机关认为必要时，也可以通知与行政行为有利害关系的其他公民、法人或者其他组织作为第三人参加行政复议。 第三人不参加行政复议的，不影响行政复议审查。"},{"i":16,"n":"第十六条","txt":"申请人、被申请人、第三人可以委托一至两人作为复议代理人。下列人员可以被委托为复议代理人： （一）律师、基层法律服务工作者； （二）申请人、第三人的近亲属或者工作人员； （三）申请人、第三人所在社区、单位及有关社会团体推荐的公民。 申请人、被申请人、第三人委托代理人参加行政复议的，应当向行政复议机关提交由委托人签字或者盖章的委托书，委托书应当载明委托事项和具体权限；解除或者变更委托的，应当书面通知行政复议机关。"},{"i":17,"n":"第十七条","txt":"行政复议机关收到行政复议申请后，应当在5日内进行审查，对不符合本办法第十八条规定的行政复议申请，决定不予受理，并书面告知申请人；对不属于本机关受理的行政复议申请，应当告知申请人向有关行政复议机关提出。 除前款规定外，行政复议申请自行政复议机构收到之日起即为受理。"},{"i":18,"n":"第十八条","txt":"行政复议机关对符合下列条件的行政复议申请，应当予以受理： （一）有明确的申请人和符合规定的被申请人； （二）申请人与行政行为有利害关系； （三）有具体的行政复议请求和理由； （四）在法定申请期限内提出； （五）属于本办法规定的行政复议范围； （六）属于收到行政复议申请的行政复议机构的职责范围； （七）申请人尚未就同一事项向其他有权受理的行政复议机关提出行政复议申请，人民法院尚未就申请人同一事项立案登记的； （八）符合法律、法规规定的其他条件。"},{"i":19,"n":"第十九条","txt":"行政复议申请材料不齐全或者表述不清楚的，行政复议机构可以自收到该行政复议申请之日起5日内书面通知申请人补正。补正通知书应当载明下列事项： （一）行政复议申请书中需要补充、说明、修改的具体内容； （二）需要补正的材料、证据； （三）合理的补正期限； （四）逾期未补正的法律后果。 申请人应当按照补正通知书要求提交补正材料。申请人无正当理由逾期不补正的，视为放弃行政复议申请。申请人超过补正通知书载明的补正期限补正，或者补正材料不符合补正通知书要求的，行政复议机关可以不予受理其行政复议申请。 补正申请材料所用时间不计入行政复议审理期限。"},{"i":20,"n":"第二十条","txt":"行政复议机关应当自行政复议申请受理之日起7日内，向被申请人发出答复通知书，并将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到答复通知书之日起10日内，提出书面答复。"},{"i":21,"n":"第二十一条","txt":"被申请人的书面答复应当载明以下内容： （一）被申请人的基本情况； （二）作出行政行为的过程和相关情况； （三）作出行政行为的事实依据和有关证据材料； （四）对申请人提出的事实和理由进行答辩； （五）作出行政行为所依据的法律、法规、规章和规范性文件； （六）作出答复的时间。"},{"i":22,"n":"第二十二条","txt":"行政复议案件原则上采取书面审查的办法。行政复议机关认为必要，或者申请人提出听证要求经行政复议机关同意的，可以采取听证的方式审查。听证所需时间不计入行政复议审理期限。 行政复议机关决定举行听证的，应当于举行听证5日前将举行听证的时间、地点、具体要求等事项，通知申请人、被申请人和第三人。申请人超过5人的，应当推选1至5名代表参加听证。申请人无正当理由不参加听证或者未经许可中途退出听证的，视为自动放弃听证权利，听证程序终止；第三人不参加听证的，不影响听证的举行；被申请人必须参加听证。 行政复议机关认为必要的，可以实地调查核实。被调查单位和人员应当予以配合，不得拒绝或者阻挠。"},{"i":23,"n":"第二十三条","txt":"两个及两个以上的复议申请人不服县级以上人民政府住房城乡建设主管部门作出的一个行政行为或者基本相同的多个行政行为，向行政复议机关分别提起多件行政复议申请的，行政复议机关可以合并审理。"},{"i":24,"n":"第二十四条","txt":"在行政复议中，被申请人应当对其作出的行政行为承担举证责任，对其提交的证据材料应当分类编号，对证据材料的来源、证明对象和内容作简要说明。"},{"i":25,"n":"第二十五条","txt":"行政复议机关审查行政复议案件，应当以证据证明的案件事实为依据。定案证据应当具有合法性、真实性和关联性。"},{"i":26,"n":"第二十六条","txt":"行政复议机关应当对被申请人作出的行政行为的下列事项进行审查： （一）是否具有相应的法定职责； （二）主要事实是否清楚，证据是否确凿； （三）适用依据是否正确； （四）是否符合法定程序； （五）是否超越或者滥用职权； （六）是否存在明显不当。"},{"i":27,"n":"第二十七条","txt":"行政复议机关对申请人认为被申请人不履行法定职责的行政复议案件，应当审查下列事项： （一）申请人是否曾经要求被申请人履行法定职责； （二）被申请人是否具有法律、法规或者规章明确规定的具体法定职责； （三）被申请人是否明确表示拒绝履行或者不予答复； （四）是否超过法定履行期限； （五）被申请人提出不能在法定期限内履行或者不能及时履行的理由是否正当。"},{"i":28,"n":"第二十八条","txt":"行政复议决定作出前，申请人可以撤回行政复议申请。 申请人撤回行政复议申请的，不得再以同一事实和理由提出行政复议申请。但是，申请人能够证明撤回行政复议申请违背其真实意思表示的除外。"},{"i":29,"n":"第二十九条","txt":"行政复议机关中止、恢复行政复议案件的审理，或者终止行政复议的，应当书面通知申请人、被申请人和第三人。"},{"i":30,"n":"第三十条","txt":"行政行为认定事实清楚，证据确凿，适用依据正确，程序合法，内容适当的，行政复议机关应当决定维持。"},{"i":31,"n":"第三十一条","txt":"行政行为有下列情形之一的，行政复议机关应当决定撤销： （一）主要事实不清，证据不足的； （二）适用依据错误的； （三）违反法定程序的； （四）超越或者滥用职权的； （五）行政行为明显不当的。"},{"i":32,"n":"第三十二条","txt":"行政行为有下列情形之一的，行政复议机关可以决定变更该行政行为： （一）认定事实清楚，证据确凿，程序合法，但是明显不当或者适用依据错误的； （二）认定事实不清，证据不足，经行政复议程序审理查明事实清楚，证据确凿的。"},{"i":33,"n":"第三十三条","txt":"有下列情形之一的，行政复议机关应当决定驳回行政复议申请： （一）申请人认为被申请人不履行法定职责申请行政复议，行政复议机关受理后发现被申请人没有相应法定职责或者在受理前已经履行法定职责的； （二）行政复议机关受理行政复议申请后，发现该行政复议申请不属于本办法规定的行政复议受案范围或者不符合受理条件的； （三）被复议的行政行为，已为人民法院或者行政复议机关作出的生效法律文书的效力所羁束的； （四）法律、法规和规章规定的其他情形。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，行政复议机关应当决定被申请人在一定期限内履行法定职责： （一）属于被申请人的法定职责，被申请人明确表示拒绝履行或者不予答复的； （二）属于被申请人的法定职责，并有法定履行期限，被申请人无正当理由逾期未履行或者未予答复的； （三）属于被申请人的法定职责，没有履行期限规定，被申请人自收到申请满60日起无正当理由未履行或者未予答复的。 前款规定的法定职责，是指县级以上人民政府住房城乡建设主管部门根据法律、法规或者规章的明确规定，在接到申请人的履责申请后应当履行的职责。"},{"i":35,"n":"第三十五条","txt":"行政行为有下列情形之一的，行政复议机关应当确认违法，但不撤销或者变更行政行为： （一）行政行为依法应当撤销或者变更，但撤销或者变更该行政行为将会给国家利益、社会公共利益造成重大损害的； （二）行政行为程序轻微违法，但对申请人权利不产生实际影响的； （三）被申请人不履行法定职责或者拖延履行法定职责，判令履行没有意义的； （四）行政行为违法，但不具有可撤销、变更内容的； （五）法律、法规和规章规定的其他情形。"},{"i":36,"n":"第三十六条","txt":"被申请人在复议期间改变原行政行为的，应当书面告知行政复议机关。 被申请人改变原行政行为，申请人撤回行政复议申请的，行政复议机关准予撤回的，行政复议终止；申请人不撤回行政复议申请的，行政复议机关经审查认为原行政行为违法的，应当作出确认其违法的行政复议决定；认为原行政行为合法的，应当驳回行政复议申请。"},{"i":37,"n":"第三十七条","txt":"行政复议机关决定撤销行政行为，可以责令被申请人在一定期限内重新作出行政行为。重新作出行政行为的期限自《行政复议决定书》送达之日起最长不超过60日，法律、法规、规章另有规定的除外。 行政复议机关确认行政行为违法的，可以责令被申请人采取相应的补救措施。 申请人对行政机关重新作出的行政行为不服，可以依法申请行政复议或者提起行政诉讼。"},{"i":38,"n":"第三十八条","txt":"行政复议机关在申请人的行政复议请求范围内，不得作出对申请人更为不利的行政复议决定。但利害关系人同为申请人，且行政复议请求相反的除外。"},{"i":39,"n":"第三十九条","txt":"申请人与被申请人在行政复议决定作出前，依法自愿达成和解的，由申请人按照本办法规定向行政复议机关撤回行政复议申请。和解内容不得损害国家利益、社会公共利益和他人合法权益。"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，行政复议机关可以按照自愿、合法的原则进行调解： （一）申请人对行政机关行使法律、法规规定的自由裁量权作出的行政行为不服申请行政复议的； （二）当事人之间的行政赔偿或者行政补偿纠纷。 经调解达成协议的，行政复议机关应当制作行政复议调解书。行政复议调解书经双方当事人签字，即具有法律效力。调解未达成协议或者调解书送达前一方反悔的，行政复议机关应当及时作出行政复议决定。"},{"i":41,"n":"第四十一条","txt":"行政复议文书有笔误的，行政复议机关可以对笔误进行更正。"},{"i":42,"n":"第四十二条","txt":"申请人、第三人在行政复议期间以及行政复议决定作出之日起90日内，可以向行政复议机关申请查阅被申请人提出的书面答复、作出行政行为的证据、依据和其他有关材料，除涉及国家秘密、商业秘密或者个人隐私外，行政复议机关不得拒绝。查阅应当依照下列程序办理： （一）申请人、第三人应当至少提前5日向行政复议机关预约时间； （二）查阅时，申请人、第三人应当出示身份证件，行政复议机关工作人员应当在场； （三）申请人、第三人不得涂改、毁损、拆换、取走、增添查阅材料；未经复议机关同意，不得进行复印、翻拍、翻录。 申请人、第三人通过政府信息公开方式，向县级以上人民政府住房城乡建设部门申请公开被申请人提出的书面答复、作出行政行为的证据、依据和其他有关材料的，县级以上人民政府住房城乡建设部门可以告知申请人、第三人按照前款规定申请查阅。 申请人、第三人以外的其他人，或者申请人、第三人超过规定期限申请查阅被申请人提出的书"},{"i":43,"n":"第四十三条","txt":"行政复议机关应当推进信息化建设，研究开发行政复议信息系统，逐步实现行政复议办公自动化和行政复议档案电子化。"},{"i":44,"n":"第四十四条","txt":"行政复议案件审查结束后，行政复议机关应当及时将案卷进行整理归档。"},{"i":45,"n":"第四十五条","txt":"被申请人应当履行行政复议决定。被申请人不履行或者无正当理由拖延履行行政复议决定的，作出复议决定的行政复议机关可以责令其在规定期限内履行。"},{"i":46,"n":"第四十六条","txt":"被责令重新作出行政行为的，被申请人不得以同一事实和理由作出与原行政行为相同或者基本相同的行政行为，但因违反法定程序被责令重新作出行政行为的除外。"},{"i":47,"n":"第四十七条","txt":"行政复议期间行政复议机关发现被申请人或者其他下级行政机关有下列情形之一的，可以制作行政复议意见书；有关机关应当自收到行政复议意见书之日起60日内将纠正相关行政违法行为或者做好善后工作的情况报告行政复议机关： （一）具体行政行为有违法或者不当情形，导致被撤销、变更或者确认违法的； （二）行政机关不依法履行法定职责，存在不作为的； （三）具体行政行为存在瑕疵或者其他问题的； （四）具体行政行为依据的规范性文件存在问题的； （五）行政机关在行政管理中存在问题和制度漏洞的； （六）行政机关需要做好相关善后工作的； （七）其他需要制作行政复议意见书的。 行政复议期间，行政复议机构发现法律、法规、规章实施中带有普遍性的问题，可以制作行政复议建议书，向有关机关提出完善制度和改进行政执法的建议。"},{"i":48,"n":"第四十八条","txt":"国务院住房城乡建设主管部门可以对县级以上地方人民政府住房城乡建设主管部门的行政复议工作和制度执行情况进行监督检查。 省、自治区、直辖市人民政府住房城乡建设主管部门可以通过定期检查、抽查等方式，对本行政区域内行政复议工作和制度执行情况进行监督检查。 不履行行政复议决定，或者在收到行政复议意见书之日起60日内未将纠正相关行政违法行为的情况报告行政复议机关的，行政复议机关可以通报批评。"},{"i":49,"n":"第四十九条","txt":"行政复议工作、行政复议决定的执行情况纳入县级以上地方人民政府住房城乡建设主管部门依法行政的考核范围。"},{"i":50,"n":"第五十条","txt":"行政复议机关应当建立行政复议案件统计制度，并按规定向上级行政复议主管部门报送本行政区的行政复议情况。"},{"i":51,"n":"第五十一条","txt":"本办法所称“涉及不动产的行政行为”，是指直接发生设立、变更、转让和消灭不动产物权效力的行政行为。"},{"i":52,"n":"第五十二条","txt":"行政复议机关可以使用行政复议专用章。行政复议专用章用于办理行政复议事项，与行政复议机关印章具有同等效力。"},{"i":53,"n":"第五十三条","txt":"行政复议文书直接送达的，复议申请人在送达回证上的签收日期为送达日期。行政复议文书邮寄送达的，邮寄地址为复议申请人在行政复议申请书中写明的地址，送达日期为复议申请人收到邮件的日期。因复议申请人自己提供的地址不准确、地址变更未及时告知行政复议机关、复议申请人本人或者其指定的代收人拒绝签收以及逾期签收，导致行政复议文书被国家邮政机构退回的，文书退回之日视为送达之日。 行政复议文书送达第三人的，适用前款规定。"},{"i":54,"n":"第五十四条","txt":"期间开始之日不计算在期间内。期间届满的最后一日是节假日的，以节假日后的第一日为期间届满的日期。 本办法关于行政复议期间有关“5日”、“7日”的规定是指工作日，不含节假日和当日。"},{"i":55,"n":"第五十五条","txt":"外国人、无国籍人、外国组织在中华人民共和国境内向行政复议机关申请行政复议，参照适用本办法。"},{"i":56,"n":"第五十六条","txt":"本办法未规定事项，依照《中华人民共和国行政复议法》和《中华人民共和国行政复议法实施条例》的规定执行。"},{"i":57,"n":"第五十七条","txt":"本办法自2015年11月1日起实施。"}],"gonggongzulinzhufangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对公共租赁住房的管理，保障公平分配，规范运营与使用，健全退出机制，制定本办法。"},{"i":2,"n":"第二条","txt":"公共租赁住房的分配、运营、使用、退出和管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称公共租赁住房，是指限定建设标准和租金水平，面向符合规定条件的城镇中等偏下收入住房困难家庭、新就业无房职工和在城镇稳定就业的外来务工人员出租的保障性住房。 公共租赁住房通过新建、改建、收购、长期租赁等多种方式筹集，可以由政府投资，也可以由政府提供政策支持、社会力量投资。 公共租赁住房可以是成套住房，也可以是宿舍型住房。"},{"i":4,"n":"第四条","txt":"国务院住房和城乡建设主管部门负责全国公共租赁住房的指导和监督工作。 县级以上地方人民政府住房城乡建设（住房保障）主管部门负责本行政区域内的公共租赁住房管理工作。"},{"i":5,"n":"第五条","txt":"直辖市和市、县级人民政府住房保障主管部门应当加强公共租赁住房管理信息系统建设，建立和完善公共租赁住房管理档案。"},{"i":6,"n":"第六条","txt":"任何组织和个人对违反本办法的行为都有权进行举报、投诉。 住房城乡建设（住房保障）主管部门接到举报、投诉，应当依法及时核实、处理。"},{"i":7,"n":"第七条","txt":"申请公共租赁住房，应当符合以下条件： （一）在本地无住房或者住房面积低于规定标准； （二）收入、财产低于规定标准； （三）申请人为外来务工人员的，在本地稳定就业达到规定年限。 具体条件由直辖市和市、县级人民政府住房保障主管部门根据本地区实际情况确定，报本级人民政府批准后实施并向社会公布。"},{"i":8,"n":"第八条","txt":"申请人应当根据市、县级人民政府住房保障主管部门的规定，提交申请材料，并对申请材料的真实性负责。申请人应当书面同意市、县级人民政府住房保障主管部门核实其申报信息。 申请人提交的申请材料齐全的，市、县级人民政府住房保障主管部门应当受理，并向申请人出具书面凭证；申请材料不齐全的，应当一次性书面告知申请人需要补正的材料。 对在开发区和园区集中建设面向用工单位或者园区就业人员配租的公共租赁住房，用人单位可以代表本单位职工申请。"},{"i":9,"n":"第九条","txt":"市、县级人民政府住房保障主管部门应当会同有关部门，对申请人提交的申请材料进行审核。 经审核，对符合申请条件的申请人，应当予以公示，经公示无异议或者异议不成立的，登记为公共租赁住房轮候对象，并向社会公开；对不符合申请条件的申请人，应当书面通知并说明理由。 申请人对审核结果有异议，可以向市、县级人民政府住房保障主管部门申请复核。市、县级人民政府住房保障主管部门应当会同有关部门进行复核，并在15个工作日内将复核结果书面告知申请人。"},{"i":10,"n":"第十条","txt":"对登记为轮候对象的申请人，应当在轮候期内安排公共租赁住房。 直辖市和市、县级人民政府住房保障主管部门应当根据本地区经济发展水平和公共租赁住房需求，合理确定公共租赁住房轮候期，报本级人民政府批准后实施并向社会公布。轮候期一般不超过5年。"},{"i":11,"n":"第十一条","txt":"公共租赁住房房源确定后，市、县级人民政府住房保障主管部门应当制定配租方案并向社会公布。 配租方案应当包括房源的位置、数量、户型、面积，租金标准，供应对象范围，意向登记时限等内容。 企事业单位投资的公共租赁住房的供应对象范围，可以规定为本单位职工。"},{"i":12,"n":"第十二条","txt":"配租方案公布后，轮候对象可以按照配租方案，到市、县级人民政府住房保障主管部门进行意向登记。 市、县级人民政府住房保障主管部门应当会同有关部门，在15个工作日内对意向登记的轮候对象进行复审。对不符合条件的，应当书面通知并说明理由。"},{"i":13,"n":"第十三条","txt":"对复审通过的轮候对象，市、县级人民政府住房保障主管部门可以采取综合评分、随机摇号等方式，确定配租对象与配租排序。 综合评分办法、摇号方式及评分、摇号的过程和结果应当向社会公开。"},{"i":14,"n":"第十四条","txt":"配租对象与配租排序确定后应当予以公示。公示无异议或者异议不成立的，配租对象按照配租排序选择公共租赁住房。 配租结果应当向社会公开。"},{"i":15,"n":"第十五条","txt":"复审通过的轮候对象中享受国家定期抚恤补助的优抚对象、孤老病残人员等，可以优先安排公共租赁住房。优先对象的范围和优先安排的办法由直辖市和市、县级人民政府住房保障主管部门根据本地区实际情况确定，报本级人民政府批准后实施并向社会公布。 社会力量投资和用人单位代表本单位职工申请的公共租赁住房，只能向经审核登记为轮候对象的申请人配租。"},{"i":16,"n":"第十六条","txt":"配租对象选择公共租赁住房后，公共租赁住房所有权人或者其委托的运营单位与配租对象应当签订书面租赁合同。 租赁合同签订前，所有权人或者其委托的运营单位应当将租赁合同中涉及承租人责任的条款内容和应当退回公共租赁住房的情形向承租人明确说明。"},{"i":17,"n":"第十七条","txt":"公共租赁住房租赁合同一般应当包括以下内容： （一）合同当事人的名称或姓名； （二）房屋的位置、用途、面积、结构、室内设施和设备，以及使用要求； （三）租赁期限、租金数额和支付方式； （四）房屋维修责任； （五）物业服务、水、电、燃气、供热等相关费用的缴纳责任； （六）退回公共租赁住房的情形； （七）违约责任及争议解决办法； （八）其他应当约定的事项。 省、自治区、直辖市人民政府住房城乡建设（住房保障）主管部门应当制定公共租赁住房租赁合同示范文本。 合同签订后，公共租赁住房所有权人或者其委托的运营单位应当在30日内将合同报市、县级人民政府住房保障主管部门备案。"},{"i":18,"n":"第十八条","txt":"公共租赁住房租赁期限一般不超过5年。"},{"i":19,"n":"第十九条","txt":"市、县级人民政府住房保障主管部门应当会同有关部门，按照略低于同地段住房市场租金水平的原则，确定本地区的公共租赁住房租金标准，报本级人民政府批准后实施。 公共租赁住房租金标准应当向社会公布，并定期调整。"},{"i":20,"n":"第二十条","txt":"公共租赁住房租赁合同约定的租金数额，应当根据市、县级人民政府批准的公共租赁住房租金标准确定。"},{"i":21,"n":"第二十一条","txt":"承租人应当根据合同约定，按时支付租金。 承租人收入低于当地规定标准的，可以依照有关规定申请租赁补贴或者减免。"},{"i":22,"n":"第二十二条","txt":"政府投资的公共租赁住房的租金收入按照政府非税收入管理的有关规定缴入同级国库，实行收支两条线管理，专项用于偿还公共租赁住房贷款本息及公共租赁住房的维护、管理等。"},{"i":23,"n":"第二十三条","txt":"因就业、子女就学等原因需要调换公共租赁住房的，经公共租赁住房所有权人或者其委托的运营单位同意，承租人之间可以互换所承租的公共租赁住房。"},{"i":24,"n":"第二十四条","txt":"公共租赁住房的所有权人及其委托的运营单位应当负责公共租赁住房及其配套设施的维修养护，确保公共租赁住房的正常使用。 政府投资的公共租赁住房维修养护费用主要通过公共租赁住房租金收入以及配套商业服务设施租金收入解决，不足部分由财政预算安排解决；社会力量投资建设的公共租赁住房维修养护费用由所有权人及其委托的运营单位承担。"},{"i":25,"n":"第二十五条","txt":"公共租赁住房的所有权人及其委托的运营单位不得改变公共租赁住房的保障性住房性质、用途及其配套设施的规划用途。"},{"i":26,"n":"第二十六条","txt":"承租人不得擅自装修所承租公共租赁住房。确需装修的，应当取得公共租赁住房的所有权人或其委托的运营单位同意。"},{"i":27,"n":"第二十七条","txt":"承租人有下列行为之一的，应当退回公共租赁住房： （一）转借、转租或者擅自调换所承租公共租赁住房的； （二）改变所承租公共租赁住房用途的； （三）破坏或者擅自装修所承租公共租赁住房，拒不恢复原状的； （四）在公共租赁住房内从事违法活动的； （五）无正当理由连续6个月以上闲置公共租赁住房的。 承租人拒不退回公共租赁住房的，市、县级人民政府住房保障主管部门应当责令其限期退回；逾期不退回的，市、县级人民政府住房保障主管部门可以依法申请人民法院强制执行。"},{"i":28,"n":"第二十八条","txt":"市、县级人民政府住房保障主管部门应当加强对公共租赁住房使用的监督检查。 公共租赁住房的所有权人及其委托的运营单位应当对承租人使用公共租赁住房的情况进行巡查，发现有违反本办法规定行为的，应当及时依法处理或者向有关部门报告。"},{"i":29,"n":"第二十九条","txt":"承租人累计6个月以上拖欠租金的，应当腾退所承租的公共租赁住房；拒不腾退的，公共租赁住房的所有权人或者其委托的运营单位可以向人民法院提起诉讼，要求承租人腾退公共租赁住房。"},{"i":30,"n":"第三十条","txt":"租赁期届满需要续租的，承租人应当在租赁期满3个月前向市、县级人民政府住房保障主管部门提出申请。 市、县级人民政府住房保障主管部门应当会同有关部门对申请人是否符合条件进行审核。经审核符合条件的，准予续租，并签订续租合同。 未按规定提出续租申请的承租人，租赁期满应当腾退公共租赁住房；拒不腾退的，公共租赁住房的所有权人或者其委托的运营单位可以向人民法院提起诉讼，要求承租人腾退公共租赁住房。"},{"i":31,"n":"第三十一条","txt":"承租人有下列情形之一的，应当腾退公共租赁住房： （一）提出续租申请但经审核不符合续租条件的； （二）租赁期内，通过购买、受赠、继承等方式获得其他住房并不再符合公共租赁住房配租条件的； （三）租赁期内，承租或者承购其他保障性住房的。 承租人有前款规定情形之一的，公共租赁住房的所有权人或者其委托的运营单位应当为其安排合理的搬迁期，搬迁期内租金按照合同约定的租金数额缴纳。 搬迁期满不腾退公共租赁住房，承租人确无其他住房的，应当按照市场价格缴纳租金；承租人有其他住房的，公共租赁住房的所有权人或者其委托的运营单位可以向人民法院提起诉讼，要求承租人腾退公共租赁住房。"},{"i":32,"n":"第三十二条","txt":"房地产经纪机构及其经纪人员不得提供公共租赁住房出租、转租、出售等经纪业务。"},{"i":33,"n":"第三十三条","txt":"住房城乡建设（住房保障）主管部门及其工作人员在公共租赁住房管理工作中不履行本办法规定的职责，或者滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"公共租赁住房的所有权人及其委托的运营单位违反本办法，有下列行为之一的，由市、县级人民政府住房保障主管部门责令限期改正，并处以3万元以下罚款： （一）向不符合条件的对象出租公共租赁住房的； （二）未履行公共租赁住房及其配套设施维修养护义务的； （三）改变公共租赁住房的保障性住房性质、用途，以及配套设施的规划用途的。 公共租赁住房的所有权人为行政机关的，按照本办法第三十三条处理。"},{"i":35,"n":"第三十五条","txt":"申请人隐瞒有关情况或者提供虚假材料申请公共租赁住房的，市、县级人民政府住房保障主管部门不予受理，给予警告，并记入公共租赁住房管理档案。 以欺骗等不正手段，登记为轮候对象或者承租公共租赁住房的，由市、县级人民政府住房保障主管部门处以1000元以下罚款，记入公共租赁住房管理档案；登记为轮候对象的，取消其登记；已承租公共租赁住房的，责令限期退回所承租公共租赁住房，并按市场价格补缴租金，逾期不退回的，可以依法申请人民法院强制执行，承租人自退回公共租赁住房之日起五年内不得再次申请公共租赁住房。"},{"i":36,"n":"第三十六条","txt":"承租人有下列行为之一的，由市、县级人民政府住房保障主管部门责令按市场价格补缴从违法行为发生之日起的租金，记入公共租赁住房管理档案，处以1000元以下罚款；有违法所得的，处以违法所得3倍以下但不超过3万元的罚款： （一）转借、转租或者擅自调换所承租公共租赁住房的； （二）改变所承租公共租赁住房用途的； （三）破坏或者擅自装修所承租公共租赁住房，拒不恢复原状的； （四）在公共租赁住房内从事违法活动的； （五）无正当理由连续6个月以上闲置公共租赁住房的。 有前款所列行为，承租人自退回公共租赁住房之日起五年内不得再次申请公共租赁住房；造成损失的，依法承担赔偿责任。"},{"i":37,"n":"第三十七条","txt":"违反本办法第三十二条的，依照《房地产经纪管理办法》第三十七条，由县级以上地方人民政府住房城乡建设（房地产）主管部门责令限期改正，记入房地产经纪信用档案；对房地产经纪人员，处以1万元以下罚款；对房地产经纪机构，取消网上签约资格，处以3万元以下罚款。"},{"i":38,"n":"第三十八条","txt":"省、自治区、直辖市住房城乡建设（住房保障）主管部门可以根据本办法制定实施细则。"},{"i":39,"n":"第三十九条","txt":"本办法自2012年7月15日起施行。"}],"kanchashejizhucegongchengshiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对建设工程勘察、设计注册工程师的管理，维护公共利益和建筑市场秩序，提高建设工程勘察、设计质量与水平，依据《中华人民共和国建筑法》、《建设工程勘察设计管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内建设工程勘察设计注册工程师（以下简称注册工程师）的注册、执业、继续教育和监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称注册工程师，是指经考试取得中华人民共和国注册工程师资格证书（以下简称资格证书），并按照本规定注册，取得中华人民共和国注册工程师注册执业证书（以下简称注册证书）和执业印章，从事建设工程勘察、设计及有关业务活动的专业技术人员。 未取得注册证书及执业印章的人员，不得以注册工程师的名义从事建设工程勘察、设计及有关业务活动。"},{"i":4,"n":"第四条","txt":"注册工程师按专业类别设置，具体专业划分由国务院住房城乡建设主管部门和人事主管部门商国务院有关部门制定。 除注册结构工程师分为一级和二级外，其他专业注册工程师不分级别。"},{"i":5,"n":"第五条","txt":"国务院住房城乡建设主管部门对全国的注册工程师的注册、执业活动实施统一监督管理；国务院铁路、交通、水利等有关部门按照国务院规定的职责分工，负责全国有关专业工程注册工程师执业活动的监督管理。 县级以上地方人民政府住房城乡建设主管部门对本行政区域内的注册工程师的注册、执业活动实施监督管理；县级以上地方人民政府交通、水利等有关部门在各自的职责范围内，负责本行政区域内有关专业工程注册工程师执业活动的监督管理。"},{"i":6,"n":"第六条","txt":"注册工程师实行注册执业管理制度。取得资格证书的人员，必须经过注册方能以注册工程师的名义执业。"},{"i":7,"n":"第七条","txt":"取得资格证书的人员申请注册，由国务院住房城乡建设主管部门审批；其中涉及有关部门的专业注册工程师的注册，由国务院住房城乡建设主管部门和有关部门审批。 取得资格证书并受聘于一个建设工程勘察、设计、施工、监理、招标代理、造价咨询等单位的人员，应当通过聘用单位提出注册申请，并可以向单位工商注册所在地的省、自治区、直辖市人民政府住房城乡建设主管部门提交申请材料；省、自治区、直辖市人民政府住房城乡建设主管部门收到申请材料后，应当在5日内将全部申请材料报审批部门。"},{"i":8,"n":"第八条","txt":"国务院住房城乡建设主管部门在收到申请材料后，应当依法作出是否受理的决定，并出具凭证；申请材料不齐全或者不符合法定形式的，应当在5日内一次性告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。 申请初始注册的，国务院住房城乡建设主管部门应当自受理之日起20日内审批完毕并作出书面决定。自作出决定之日起10日内公告审批结果。由国务院住房城乡建设主管部门和有关部门共同审批的，国务院有关部门应当在15日内审核完毕，并将审核意见报国务院住房城乡建设主管部门。 对申请变更注册、延续注册的，国务院住房城乡建设主管部门应当自受理申请之日起10日内审批完毕并作出书面决定。 符合条件的，由审批部门核发由国务院住房城乡建设主管部门统一制作、国务院住房城乡建设主管部门或者国务院住房城乡建设主管部门和有关部门共同用印的注册证书，并核定执业印章编号。对不予批准的，应当说明理由，并告知申请人享有"},{"i":9,"n":"第九条","txt":"二级注册结构工程师的注册受理和审批，由省、自治区、直辖市人民政府住房城乡建设主管部门负责。"},{"i":10,"n":"第十条","txt":"注册证书和执业印章是注册工程师的执业凭证，由注册工程师本人保管、使用。注册证书和执业印章的有效期为3年。"},{"i":11,"n":"第十一条","txt":"初始注册者，可自资格证书签发之日起3年内提出申请。逾期未申请者，须符合本专业继续教育的要求后方可申请初始注册。 初始注册需要提交下列材料： （一）申请人的注册申请表； （二）申请人的资格证书复印件； （三）申请人与聘用单位签订的聘用劳动合同复印件； （四）逾期初始注册的，应提供达到继续教育要求的证明材料。"},{"i":12,"n":"第十二条","txt":"注册工程师每一注册期为3年，注册期满需继续执业的，应在注册期满前30日，按照本规定第七条规定的程序申请延续注册。 延续注册需要提交下列材料： （一）申请人延续注册申请表； （二）申请人与聘用单位签订的聘用劳动合同复印件； （三）申请人注册期内达到继续教育要求的证明材料。"},{"i":13,"n":"第十三条","txt":"在注册有效期内，注册工程师变更执业单位，应与原聘用单位解除劳动关系，并按本规定第七条规定的程序办理变更注册手续，变更注册后仍延续原注册有效期。 变更注册需要提交下列材料： （一）申请人变更注册申请表； （二）申请人与新聘用单位签订的聘用劳动合同复印件； （三）申请人的工作调动证明（或者与原聘用单位解除聘用劳动合同的证明文件、退休人员的退休证明）。"},{"i":14,"n":"第十四条","txt":"注册工程师有下列情形之一的，其注册证书和执业印章失效： （一）聘用单位破产的； （二）聘用单位被吊销营业执照的； （三）聘用单位相应资质证书被吊销的； （四）已与聘用单位解除聘用劳动关系的； （五）注册有效期满且未延续注册的； （六）死亡或者丧失行为能力的； （七）注册失效的其他情形。"},{"i":15,"n":"第十五条","txt":"注册工程师有下列情形之一的，负责审批的部门应当办理注销手续，收回注册证书和执业印章或者公告其注册证书和执业印章作废： （一）不具有完全民事行为能力的； （二）申请注销注册的； （三）有本规定第十四条所列情形发生的； （四）依法被撤销注册的； （五）依法被吊销注册证书的； （六）受到刑事处罚的； （七）法律、法规规定应当注销注册的其他情形。 注册工程师有前款情形之一的，注册工程师本人和聘用单位应当及时向负责审批的部门提出注销注册的申请；有关单位和个人有权向负责审批的部门举报；住房城乡建设主管部门和有关部门应当及时向负责审批的部门报告。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，不予注册： （一）不具有完全民事行为能力的； （二）因从事勘察设计或者相关业务受到刑事处罚，自刑事处罚执行完毕之日起至申请注册之日止不满2年的； （三）法律、法规规定不予注册的其他情形。"},{"i":17,"n":"第十七条","txt":"被注销注册者或者不予注册者，在重新具备初始注册条件，并符合本专业继续教育要求后，可按照本规定第七条规定的程序重新申请注册。"},{"i":18,"n":"第十八条","txt":"取得资格证书的人员，应受聘于一个具有建设工程勘察、设计、施工、监理、招标代理、造价咨询等一项或多项资质的单位，经注册后方可从事相应的执业活动。但从事建设工程勘察、设计执业活动的，应受聘并注册于一个具有建设工程勘察、设计资质的单位。"},{"i":19,"n":"第十九条","txt":"注册工程师的执业范围： （一）工程勘察或者本专业工程设计； （二）本专业工程技术咨询； （三）本专业工程招标、采购咨询； （四）本专业工程的项目管理； （五）对工程勘察或者本专业工程设计项目的施工进行指导和监督； （六）国务院有关部门规定的其他业务。"},{"i":20,"n":"第二十条","txt":"建设工程勘察、设计活动中形成的勘察、设计文件由相应专业注册工程师按照规定签字盖章后方可生效。各专业注册工程师签字盖章的勘察、设计文件种类及办法由国务院住房城乡建设主管部门会同有关部门规定。"},{"i":21,"n":"第二十一条","txt":"修改经注册工程师签字盖章的勘察、设计文件，应当由该注册工程师进行；因特殊情况，该注册工程师不能进行修改的，应由同专业其他注册工程师修改，并签字、加盖执业印章，对修改部分承担责任。"},{"i":22,"n":"第二十二条","txt":"注册工程师从事执业活动，由所在单位接受委托并统一收费。"},{"i":23,"n":"第二十三条","txt":"因建设工程勘察、设计事故及相关业务造成的经济损失，聘用单位应承担赔偿责任；聘用单位承担赔偿责任后，可依法向负有过错的注册工程师追偿。"},{"i":24,"n":"第二十四条","txt":"注册工程师在每一注册期内应达到国务院住房城乡建设主管部门规定的本专业继续教育要求。继续教育作为注册工程师逾期初始注册、延续注册和重新申请注册的条件。"},{"i":25,"n":"第二十五条","txt":"继续教育按照注册工程师专业类别设置，分为必修课和选修课，每注册期各为60学时。"},{"i":26,"n":"第二十六条","txt":"注册工程师享有下列权利： （一）使用注册工程师称谓； （二）在规定范围内从事执业活动； （三）依据本人能力从事相应的执业活动； （四）保管和使用本人的注册证书和执业印章； （五）对本人执业活动进行解释和辩护； （六）接受继续教育； （七）获得相应的劳动报酬； （八）对侵犯本人权利的行为进行申诉。"},{"i":27,"n":"第二十七条","txt":"注册工程师应当履行下列义务： （一）遵守法律、法规和有关管理规定； （二）执行工程建设标准规范； （三）保证执业活动成果的质量，并承担相应责任； （四）接受继续教育，努力提高执业水准； （五）在本人执业活动所形成的勘察、设计文件上签字、加盖执业印章； （六）保守在执业中知悉的国家秘密和他人的商业、技术秘密； （七）不得涂改、出租、出借或者以其他形式非法转让注册证书或者执业印章； （八）不得同时在两个或两个以上单位受聘或者执业； （九）在本专业规定的执业范围和聘用单位业务范围内从事执业活动； （十）协助注册管理机构完成相关工作。"},{"i":28,"n":"第二十八条","txt":"隐瞒有关情况或者提供虚假材料申请注册的，审批部门不予受理，并给予警告，一年之内不得再次申请注册。"},{"i":29,"n":"第二十九条","txt":"以欺骗、贿赂等不正当手段取得注册证书的，由负责审批的部门撤销其注册，3年内不得再次申请注册；并由县级以上人民政府住房城乡建设主管部门或者有关部门处以罚款，其中没有违法所得的，处以1万元以下的罚款；有违法所得的，处以违法所得3倍以上但不超过3万元的罚款；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"注册工程师在执业活动中有下列行为之一的，由县级以上人民政府住房城乡建设主管部门或者有关部门予以警告，责令其改正，没有违法所得的，处以1万元以下的罚款；有违法所得的，处以违法所得3倍以上但不超过3万元的罚款；造成损失的，应当承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）以个人名义承接业务的； （二）涂改、出租、出借或者以形式非法转让注册证书或者执业印章的； （三）泄露执业中应当保守的秘密并造成严重后果的； （四）超出本专业规定范围或者聘用单位业务范围从事执业活动的； （五）弄虚作假提供执业活动成果的； （六）其它违反法律、法规、规章的行为。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，负责审批的部门或者其上级主管部门，可以撤销其注册： （一）住房城乡建设主管部门或者有关部门的工作人员滥用职权、玩忽职守颁发注册证书和执业印章的； （二）超越法定职权颁发注册证书和执业印章的； （三）违反法定程序颁发注册证书和执业印章的； （四）对不符合法定条件的申请人颁发注册证书和执业印章的； （五）依法可以撤销注册的其他情形。"},{"i":32,"n":"第三十二条","txt":"县级以上人民政府住房城乡建设主管部门及有关部门的工作人员，在注册工程师管理工作中，有下列情形之一的，依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）对不符合法定条件的申请人颁发注册证书和执业印章的； （二）对符合法定条件的申请人不予颁发注册证书和执业印章的； （三）对符合法定条件的申请人未在法定期限内颁发注册证书和执业印章的； （四）利用职务上的便利，收受他人财物或者其他好处的； （五）不依法履行监督管理职责，或者发现违法行为不予查处的。"},{"i":33,"n":"第三十三条","txt":"注册工程师资格考试工作按照国务院住房城乡建设主管部门、国务院人事主管部门的有关规定执行。"},{"i":34,"n":"第三十四条","txt":"香港特别行政区、澳门特别行政区、台湾地区及外籍专业技术人员，注册工程师注册和执业的管理办法另行制定。"},{"i":35,"n":"第三十五条","txt":"本规定自2005年4月1日起施行。"}],"weixianxingjiaodadefenbufenxianggongchenganquangua074478":[{"i":1,"n":"第一条","txt":"为加强对房屋建筑和市政基础设施工程中危险性较大的分部分项工程安全管理，有效防范生产安全事故，依据《中华人民共和国建筑法》《中华人民共和国安全生产法》《建设工程安全生产管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于房屋建筑和市政基础设施工程中危险性较大的分部分项工程安全管理。"},{"i":3,"n":"第三条","txt":"本规定所称危险性较大的分部分项工程（以下简称“危大工程”），是指房屋建筑和市政基础设施工程在施工过程中，容易导致人员群死群伤或者造成重大经济损失的分部分项工程。 危大工程及超过一定规模的危大工程范围由国务院住房城乡建设主管部门制定。 省级住房城乡建设主管部门可以结合本地区实际情况，补充本地区危大工程范围。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责全国危大工程安全管理的指导监督。 县级以上地方人民政府住房城乡建设主管部门负责本行政区域内危大工程的安全监督管理。"},{"i":5,"n":"第五条","txt":"建设单位应当依法提供真实、准确、完整的工程地质、水文地质和工程周边环境等资料。"},{"i":6,"n":"第六条","txt":"勘察单位应当根据工程实际及工程周边环境资料，在勘察文件中说明地质条件可能造成的工程风险。 设计单位应当在设计文件中注明涉及危大工程的重点部位和环节，提出保障工程周边环境安全和工程施工安全的意见，必要时进行专项设计。"},{"i":7,"n":"第七条","txt":"建设单位应当组织勘察、设计等单位在施工招标文件中列出危大工程清单，要求施工单位在投标时补充完善危大工程清单并明确相应的安全管理措施。"},{"i":8,"n":"第八条","txt":"建设单位应当按照施工合同约定及时支付危大工程施工技术措施费以及相应的安全防护文明施工措施费，保障危大工程施工安全。"},{"i":9,"n":"第九条","txt":"建设单位在申请办理施工许可手续时，应当提交危大工程清单及其安全管理措施等资料。"},{"i":10,"n":"第十条","txt":"施工单位应当在危大工程施工前组织工程技术人员编制专项施工方案。 实行施工总承包的，专项施工方案应当由施工总承包单位组织编制。危大工程实行分包的，专项施工方案可以由相关专业分包单位组织编制。"},{"i":11,"n":"第十一条","txt":"专项施工方案应当由施工单位技术负责人审核签字、加盖单位公章，并由总监理工程师审查签字、加盖执业印章后方可实施。 危大工程实行分包并由分包单位编制专项施工方案的，专项施工方案应当由总承包单位技术负责人及分包单位技术负责人共同审核签字并加盖单位公章。"},{"i":12,"n":"第十二条","txt":"对于超过一定规模的危大工程，施工单位应当组织召开专家论证会对专项施工方案进行论证。实行施工总承包的，由施工总承包单位组织召开专家论证会。专家论证前专项施工方案应当通过施工单位审核和总监理工程师审查。 专家应当从地方人民政府住房城乡建设主管部门建立的专家库中选取，符合专业要求且人数不得少于5名。与本工程有利害关系的人员不得以专家身份参加专家论证会。"},{"i":13,"n":"第十三条","txt":"专家论证会后，应当形成论证报告，对专项施工方案提出通过、修改后通过或者不通过的一致意见。专家对论证报告负责并签字确认。 专项施工方案经论证需修改后通过的，施工单位应当根据论证报告修改完善后，重新履行本规定第十一条的程序。 专项施工方案经论证不通过的，施工单位修改后应当按照本规定的要求重新组织专家论证。"},{"i":14,"n":"第十四条","txt":"施工单位应当在施工现场显著位置公告危大工程名称、施工时间和具体责任人员，并在危险区域设置安全警示标志。"},{"i":15,"n":"第十五条","txt":"专项施工方案实施前，编制人员或者项目技术负责人应当向施工现场管理人员进行方案交底。 施工现场管理人员应当向作业人员进行安全技术交底，并由双方和项目专职安全生产管理人员共同签字确认。"},{"i":16,"n":"第十六条","txt":"施工单位应当严格按照专项施工方案组织施工，不得擅自修改专项施工方案。 因规划调整、设计变更等原因确需调整的，修改后的专项施工方案应当按照本规定重新审核和论证。涉及资金或者工期调整的，建设单位应当按照约定予以调整。"},{"i":17,"n":"第十七条","txt":"施工单位应当对危大工程施工作业人员进行登记，项目负责人应当在施工现场履职。 项目专职安全生产管理人员应当对专项施工方案实施情况进行现场监督，对未按照专项施工方案施工的，应当要求立即整改，并及时报告项目负责人，项目负责人应当及时组织限期整改。 施工单位应当按照规定对危大工程进行施工监测和安全巡视，发现危及人身安全的紧急情况，应当立即组织作业人员撤离危险区域。"},{"i":18,"n":"第十八条","txt":"监理单位应当结合危大工程专项施工方案编制监理实施细则，并对危大工程施工实施专项巡视检查。"},{"i":19,"n":"第十九条","txt":"监理单位发现施工单位未按照专项施工方案施工的，应当要求其进行整改；情节严重的，应当要求其暂停施工，并及时报告建设单位。施工单位拒不整改或者不停止施工的，监理单位应当及时报告建设单位和工程所在地住房城乡建设主管部门。"},{"i":20,"n":"第二十条","txt":"对于按照规定需要进行第三方监测的危大工程，建设单位应当委托具有相应勘察资质的单位进行监测。 监测单位应当编制监测方案。监测方案由监测单位技术负责人审核签字并加盖单位公章，报送监理单位后方可实施。 监测单位应当按照监测方案开展监测，及时向建设单位报送监测成果，并对监测成果负责；发现异常时，及时向建设、设计、施工、监理单位报告，建设单位应当立即组织相关单位采取处置措施。"},{"i":21,"n":"第二十一条","txt":"对于按照规定需要验收的危大工程，施工单位、监理单位应当组织相关人员进行验收。验收合格的，经施工单位项目技术负责人及总监理工程师签字确认后，方可进入下一道工序。 危大工程验收合格后，施工单位应当在施工现场明显位置设置验收标识牌，公示验收时间及责任人员。"},{"i":22,"n":"第二十二条","txt":"危大工程发生险情或者事故时，施工单位应当立即采取应急处置措施，并报告工程所在地住房城乡建设主管部门。建设、勘察、设计、监理等单位应当配合施工单位开展应急抢险工作。"},{"i":23,"n":"第二十三条","txt":"危大工程应急抢险结束后，建设单位应当组织勘察、设计、施工、监理等单位制定工程恢复方案，并对应急抢险工作进行后评估。"},{"i":24,"n":"第二十四条","txt":"施工、监理单位应当建立危大工程安全管理档案。 施工单位应当将专项施工方案及审核、专家论证、交底、现场检查、验收及整改等相关资料纳入档案管理。 监理单位应当将监理实施细则、专项施工方案审查、专项巡视检查、验收及整改等相关资料纳入档案管理。"},{"i":25,"n":"第二十五条","txt":"设区的市级以上地方人民政府住房城乡建设主管部门应当建立专家库，制定专家库管理制度，建立专家诚信档案，并向社会公布，接受社会监督。"},{"i":26,"n":"第二十六条","txt":"县级以上地方人民政府住房城乡建设主管部门或者所属施工安全监督机构，应当根据监督工作计划对危大工程进行抽查。 县级以上地方人民政府住房城乡建设主管部门或者所属施工安全监督机构，可以通过政府购买技术服务方式，聘请具有专业技术能力的单位和人员对危大工程进行检查，所需费用向本级财政申请予以保障。"},{"i":27,"n":"第二十七条","txt":"县级以上地方人民政府住房城乡建设主管部门或者所属施工安全监督机构，在监督抽查中发现危大工程存在安全隐患的，应当责令施工单位整改；重大安全事故隐患排除前或者排除过程中无法保证安全的，责令从危险区域内撤出作业人员或者暂时停止施工；对依法应当给予行政处罚的行为，应当依法作出行政处罚决定。"},{"i":28,"n":"第二十八条","txt":"县级以上地方人民政府住房城乡建设主管部门应当将单位和个人的处罚信息纳入建筑施工安全生产不良信用记录。"},{"i":29,"n":"第二十九条","txt":"建设单位有下列行为之一的，责令限期改正，并处1万元以上3万元以下的罚款；对直接负责的主管人员和其他直接责任人员处1000元以上5000元以下的罚款： （一）未按照本规定提供工程周边环境等资料的； （二）未按照本规定在招标文件中列出危大工程清单的； （三）未按照施工合同约定及时支付危大工程施工技术措施费或者相应的安全防护文明施工措施费的； （四）未按照本规定委托具有相应勘察资质的单位进行第三方监测的； （五）未对第三方监测单位报告的异常情况组织采取处置措施的。"},{"i":30,"n":"第三十条","txt":"勘察单位未在勘察文件中说明地质条件可能造成的工程风险的，责令限期改正，依照《建设工程安全生产管理条例》对单位进行处罚；对直接负责的主管人员和其他直接责任人员处1000元以上5000元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"设计单位未在设计文件中注明涉及危大工程的重点部位和环节，未提出保障工程周边环境安全和工程施工安全的意见的，责令限期改正，并处1万元以上3万元以下的罚款；对直接负责的主管人员和其他直接责任人员处1000元以上5000元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"施工单位未按照本规定编制并审核危大工程专项施工方案的，依照《建设工程安全生产管理条例》对单位进行处罚，并暂扣安全生产许可证30日；对直接负责的主管人员和其他直接责任人员处1000元以上5000元以下的罚款。"},{"i":33,"n":"第三十三条","txt":"施工单位有下列行为之一的，依照《中华人民共和国安全生产法》《建设工程安全生产管理条例》对单位和相关责任人员进行处罚： （一）未向施工现场管理人员和作业人员进行方案交底和安全技术交底的； （二）未在施工现场显著位置公告危大工程，并在危险区域设置安全警示标志的； （三）项目专职安全生产管理人员未对专项施工方案实施情况进行现场监督的。"},{"i":34,"n":"第三十四条","txt":"施工单位有下列行为之一的，责令限期改正，处1万元以上3万元以下的罚款，并暂扣安全生产许可证30日；对直接负责的主管人员和其他直接责任人员处1000元以上5000元以下的罚款： （一）未对超过一定规模的危大工程专项施工方案进行专家论证的； （二）未根据专家论证报告对超过一定规模的危大工程专项施工方案进行修改，或者未按照本规定重新组织专家论证的； （三）未严格按照专项施工方案组织施工，或者擅自修改专项施工方案的。"},{"i":35,"n":"第三十五条","txt":"施工单位有下列行为之一的，责令限期改正，并处1万元以上3万元以下的罚款；对直接负责的主管人员和其他直接责任人员处1000元以上5000元以下的罚款： （一）项目负责人未按照本规定现场履职或者组织限期整改的； （二）施工单位未按照本规定进行施工监测和安全巡视的； （三）未按照本规定组织危大工程验收的； （四）发生险情或者事故时，未采取应急处置措施的； （五）未按照本规定建立危大工程安全管理档案的。"},{"i":36,"n":"第三十六条","txt":"监理单位有下列行为之一的，依照《中华人民共和国安全生产法》《建设工程安全生产管理条例》对单位进行处罚；对直接负责的主管人员和其他直接责任人员处1000元以上5000元以下的罚款： （一）总监理工程师未按照本规定审查危大工程专项施工方案的； （二）发现施工单位未按照专项施工方案实施，未要求其整改或者停工的； （三）施工单位拒不整改或者不停止施工时，未向建设单位和工程所在地住房城乡建设主管部门报告的。"},{"i":37,"n":"第三十七条","txt":"监理单位有下列行为之一的，责令限期改正，并处1万元以上3万元以下的罚款；对直接负责的主管人员和其他直接责任人员处1000元以上5000元以下的罚款： （一）未按照本规定编制监理实施细则的； （二）未对危大工程施工实施专项巡视检查的； （三）未按照本规定参与组织危大工程验收的； （四）未按照本规定建立危大工程安全管理档案的。"},{"i":38,"n":"第三十八条","txt":"监测单位有下列行为之一的，责令限期改正，并处1万元以上3万元以下的罚款；对直接负责的主管人员和其他直接责任人员处1000元以上5000元以下的罚款： （一）未取得相应勘察资质从事第三方监测的； （二）未按照本规定编制监测方案的； （三）未按照监测方案开展监测的； （四）发现异常未及时报告的。"},{"i":39,"n":"第三十九条","txt":"县级以上地方人民政府住房城乡建设主管部门或者所属施工安全监督机构的工作人员，未依法履行危大工程安全监督管理职责的，依照有关规定给予处分。"},{"i":40,"n":"第四十条","txt":"本规定自2018年6月1日起施行。"}],"lishiwenhuamingchengmingzhenmingcunjiequbaohuguihu29c7dc":[{"i":1,"n":"第一条","txt":"为了规范历史文化名城、名镇、名村、街区保护规划编制和审批工作，根据《中华人民共和国城乡规划法》和《历史文化名城名镇名村保护条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"历史文化名城、名镇、名村、街区保护规划的编制和审批，适用本办法。"},{"i":3,"n":"第三条","txt":"对历史文化名城、名镇、名村、街区实施保护管理，在历史文化名城、名镇、名村、街区保护范围内从事建设活动，改善基础设施、公共服务设施和居住环境，应当符合保护规划。"},{"i":4,"n":"第四条","txt":"编制保护规划，应当保持和延续历史文化名城、名镇、名村、街区的传统格局和历史风貌，维护历史文化遗产的真实性和完整性，继承和弘扬中华民族优秀传统文化，正确处理经济社会发展和历史文化遗产保护的关系。"},{"i":5,"n":"第五条","txt":"历史文化名城、名镇保护规划应当单独编制，下列内容应当纳入城市、镇总体规划： （一）保护原则和保护内容； （二）保护措施、开发强度和建设控制要求； （三）传统格局和历史风貌保护要求； （四）核心保护范围和建设控制地带； （五）需要纳入的其他内容。"},{"i":6,"n":"第六条","txt":"历史文化街区所在地的城市、县已被确定为历史文化名城的，该历史文化街区保护规划应当依据历史文化名城保护规划单独编制。 历史文化街区所在地的城市、县未被确定为历史文化名城的，应当单独编制历史文化街区保护规划，并纳入城市、镇总体规划。"},{"i":7,"n":"第七条","txt":"编制历史文化名城、名镇、街区控制性详细规划的，应当符合历史文化名城、名镇、街区保护规划。 历史文化街区保护规划的规划深度应当达到详细规划深度，并可以作为该街区的控制性详细规划。 历史文化名城、名镇、街区保护范围内建设项目的规划许可，不得违反历史文化名城、名镇、街区保护规划。"},{"i":8,"n":"第八条","txt":"历史文化名城批准公布后，历史文化名城人民政府应当组织编制历史文化名城保护规划。历史文化名镇、名村批准公布后，所在地的县级人民政府应当组织编制历史文化名镇、名村保护规划。历史文化街区批准公布后，所在地的城市、县人民政府应当组织编制历史文化街区保护规划。 保护规划应当自历史文化名城、名镇、名村、街区批准公布之日起1年内编制完成。"},{"i":9,"n":"第九条","txt":"历史文化名城、名镇、街区保护规划的编制，应当由具有甲级资质的城乡规划编制单位承担。 历史文化名村保护规划的编制，应当由具有乙级以上资质的城乡规划编制单位承担。"},{"i":10,"n":"第十条","txt":"编制保护规划，应当遵守国家有关标准和技术规范，采用符合国家有关规定的基础资料。 历史文化名镇、名村、街区的核心保护范围内，确因保护需要无法按照有关的消防技术标准和规范设置消防设施和消防通道的，由城市、县人民政府公安机关消防机构会同同级城乡规划主管部门制订相应的防火安全保障方案。 因公共利益需要进行建设活动，对历史建筑无法实施原址保护、必须迁移异地保护或者拆除的，应当由城市、县人民政府城乡规划主管部门会同同级文物主管部门，报省、自治区、直辖市人民政府确定的保护主管部门会同同级文物主管部门批准。 县级以上地方人民政府有关主管部门应当根据编制保护规划的需要，及时提供有关基础资料。"},{"i":11,"n":"第十一条","txt":"编制保护规划，应当进行科学论证，并广泛征求有关部门、专家和公众的意见；必要时，可以举行听证。"},{"i":12,"n":"第十二条","txt":"历史文化名城保护规划应当包括下列内容： （一）评估历史文化价值、特色和存在问题； （二）确定总体保护目标和保护原则、内容和重点； （三）提出总体保护策略和市（县）域的保护要求； （四）划定文物保护单位、地下文物埋藏区、历史建筑、历史文化街区的核心保护范围和建设控制地带界线，制定相应的保护控制措施； （五）划定历史城区的界限，提出保护名城传统格局、历史风貌、空间尺度及其相互依存的地形地貌、河湖水系等自然景观和环境的保护措施； （六）描述历史建筑的艺术特征、历史特征、建设年代、使用现状等情况，对历史建筑进行编号，提出保护利用的内容和要求； （七）提出继承和弘扬传统文化、保护非物质文化遗产的内容和措施； （八）提出完善城市功能、改善基础设施、公共服务设施、生产生活环境的规划要求和措施； （九）提出展示、利用的要求和措施； （十）提出近期实施保护内容； （十一）提出规划实施保障措施。"},{"i":13,"n":"第十三条","txt":"历史文化名镇名村保护规划应当包括下列内容： （一）评估历史文化价值、特色和存在问题； （二）确定保护原则、内容和重点； （三）提出总体保护策略和镇域保护要求； （四）提出与名镇名村密切相关的地形地貌、河湖水系、农田、乡土景观、自然生态等景观环境的保护措施； （五）确定保护范围，包括核心保护范围和建设控制地带界线，制定相应的保护控制措施； （六）提出保护范围内建筑物、构筑物和环境要素的分类保护整治要求，对历史建筑进行编号，分别提出保护利用的内容和要求； （七）提出继承和弘扬传统文化、保护非物质文化遗产的内容和措施； （八）提出改善基础设施、公共服务设施、生产生活环境的规划方案； （九）保护规划分期实施方案； （十）提出规划实施保障措施。"},{"i":14,"n":"第十四条","txt":"历史文化街区保护规划应当包括下列内容： （一）评估历史文化价值、特点和存在问题； （二）确定保护原则和保护内容； （三）确定保护范围，包括核心保护范围和建设控制地带界线，制定相应的保护控制措施； （四）提出保护范围内建筑物、构筑物和环境要素的分类保护整治要求，对历史建筑进行编号，分别提出保护利用的内容和要求； （五）提出延续继承和弘扬传统文化、保护非物质文化遗产的内容和规划措施； （六）提出改善交通等基础设施、公共服务设施、居住环境的规划方案； （七）提出规划实施保障措施。"},{"i":15,"n":"第十五条","txt":"历史文化名城、名镇、名村、街区保护规划确定的核心保护范围和建设控制地带，按照以下方法划定： （一）各级文物保护单位的保护范围和建设控制地带以及地下文物埋藏区的界线，以县级以上地方人民政府公布的保护范围、建设控制地带为准； （二）历史建筑的保护范围包括历史建筑本身和必要的建设控制区； （三）历史文化街区、名镇、名村内传统格局和历史风貌较为完整、历史建筑或者传统风貌建筑集中成片的地区应当划为核心保护范围，在核心保护范围之外划定建设控制地带； （四）历史文化名城的保护范围，应当包括历史城区和其他需要保护、控制的地区； （五）历史文化名城、名镇、名村、街区保护规划确定的核心保护范围和建设控制地带应当边界清楚，四至范围明确，便于保护和管理。"},{"i":16,"n":"第十六条","txt":"历史文化名城、名镇、街区保护规划的规划期限应当与城市、镇总体规划的规划期限相一致。 历史文化名村保护规划的规划期限应当与村庄规划的规划期限相一致。"},{"i":17,"n":"第十七条","txt":"保护规划成果应当包括规划文本、图纸和附件，以书面和电子文件两种形式表达。 规划成果的表达应当清晰、规范，符合城乡规划有关的技术标准和技术规范。"},{"i":18,"n":"第十八条","txt":"在历史文化名城、名镇、名村、街区保护规划成果编制阶段，历史文化名城、名镇、名村、街区所在地的省、自治区、直辖市人民政府城乡规划主管部门，应当组织专家对保护规划的成果进行审查。 在国家历史文化名城保护规划成果编制阶段，国家历史文化名城所在地的省、自治区、直辖市人民政府城乡规划主管部门，应当提请国务院城乡规划主管部门组织专家对成果进行审查。"},{"i":19,"n":"第十九条","txt":"历史文化名城、名镇、名村保护规划由省、自治区、直辖市人民政府审批。历史文化街区保护规划按照省、自治区、直辖市的有关规定审批。 保护规划报送审批文件中应当附具本办法第十八条规定的审查意见采纳情况及理由；经听证的，还应当附具听证笔录。"},{"i":20,"n":"第二十条","txt":"国家历史文化名城、中国历史文化名镇、名村保护规划经依法批准后30日内，组织编制机关应当报国务院城乡规划主管部门和国务院文物主管部门备案。报送备案时，应当提交下列材料： （一）保护规划编制单位资质的相关材料； （二）保护规划的批准文件； （三）以书面和电子文件两种形式表达的规划文本、图纸和附件； （四）本办法第十八条规定的审查意见； （五）国务院城乡规划主管部门要求的其他材料。"},{"i":21,"n":"第二十一条","txt":"保护规划的组织编制机关应当及时公布经依法批准和备案的保护规划。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，保护规划的组织编制机关可以按照规定的权限和程序修改保护规划： （一）新发现地下遗址等重要历史文化遗存，或者历史文化遗存与环境发生重大变化，经评估确需修改保护规划的； （二）因行政区划调整确需修改保护规划的； （三）因国务院批准重大建设工程确需修改保护规划的； （四）依法应当修改保护规划的其他情形。 需要修改保护规划的，组织编制机关应当提出专题报告报送原审批机关批准后，方可编制修改方案；修改国家历史文化名城、中国历史文化名镇、名村保护规划的，还应当报告国务院城乡规划主管部门。 修改后的保护规划，应当按照原程序报送审批和备案。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人都应当遵守经依法批准并公布的保护规划，服从规划管理，并有权就涉及其利害关系的建设活动是否符合保护规划的要求向城乡规划主管部门查询。 任何单位和个人都有权向城乡规划主管部门或者其他有关部门举报或者控告违反保护规划的行为。"},{"i":24,"n":"第二十四条","txt":"违反本办法规定，地方人民政府有下列行为之一的，由上级人民政府责令改正，对直接负责的主管人员和其他直接责任人员，依法给予处分： （一）未组织编制保护规划的； （二）未按照法定程序组织编制保护规划的； （三）擅自修改保护规划的； （四）未将批准的保护规划予以公布的。"},{"i":25,"n":"第二十五条","txt":"县级以上地方人民政府城乡规划主管部门及其工作人员或者由省、自治区、直辖市人民政府确定的镇人民政府及其工作人员有下列行为之一的，对有关责任人员给予警告或者记过处分，情节较重的，给予记大过或者降级处分；情节严重的，给予撤职处分： （一）违反规划批准在历史文化街区、名镇、名村核心保护范围内进行新建、扩建活动或者违反规定批准对历史建筑进行迁移、拆除的； （二）违反历史文化街区和历史建筑的保护范围界限（紫线）等城乡规划强制性内容的规定核发规划许可的。"},{"i":26,"n":"第二十六条","txt":"历史文化名城、名镇、名村、街区保护规划编制审批中涉及文物保护内容的，应当符合文物保护法律法规的规定。"},{"i":27,"n":"第二十七条","txt":"本办法自2014年12月29日起施行。"}],"shangpinfangwuzulinguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强商品房屋租赁管理，规范商品房屋租赁行为，维护商品房屋租赁双方当事人的合法权益，根据《中华人民共和国城市房地产管理法》等有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"城市规划区内国有土地上的商品房屋租赁（以下简称房屋租赁）及其监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"房屋租赁应当遵循平等、自愿、合法和诚实信用原则。"},{"i":4,"n":"第四条","txt":"国务院住房和城乡建设主管部门负责全国房屋租赁的指导和监督工作。 县级以上地方人民政府建设（房地产）主管部门负责本行政区域内房屋租赁的监督管理。"},{"i":5,"n":"第五条","txt":"直辖市、市、县人民政府建设（房地产）主管部门应当加强房屋租赁管理规定和房屋使用安全知识的宣传，定期分区域公布不同类型房屋的市场租金水平等信息。"},{"i":6,"n":"第六条","txt":"有下列情形之一的房屋不得出租： （一）属于违法建筑的； （二）不符合安全、防灾等工程建设强制性标准的； （三）违反规定改变房屋使用性质的； （四）法律、法规规定禁止出租的其他情形。"},{"i":7,"n":"第七条","txt":"房屋租赁当事人应当依法订立租赁合同。房屋租赁合同的内容由当事人双方约定，一般应当包括以下内容： （一）房屋租赁当事人的姓名（名称）和住所； （二）房屋的坐落、面积、结构、附属设施，家具和家电等室内设施状况； （三）租金和押金数额、支付方式； （四）租赁用途和房屋使用要求； （五）房屋和室内设施的安全性能； （六）租赁期限； （七）房屋维修责任； （八）物业服务、水、电、燃气等相关费用的缴纳； （九）争议解决办法和违约责任； （十）其他约定。 房屋租赁当事人应当在房屋租赁合同中约定房屋被征收或者拆迁时的处理办法。 建设（房地产）管理部门可以会同工商行政管理部门制定房屋租赁合同示范文本，供当事人选用。"},{"i":8,"n":"第八条","txt":"出租住房的，应当以原设计的房间为最小出租单位，人均租住建筑面积不得低于当地人民政府规定的最低标准。 厨房、卫生间、阳台和地下储藏室不得出租供人员居住。"},{"i":9,"n":"第九条","txt":"出租人应当按照合同约定履行房屋的维修义务并确保房屋和室内设施安全。未及时修复损坏的房屋，影响承租人正常使用的，应当按照约定承担赔偿责任或者减少租金。 房屋租赁合同期内，出租人不得单方面随意提高租金水平。"},{"i":10,"n":"第十条","txt":"承租人应当按照合同约定的租赁用途和使用要求合理使用房屋，不得擅自改动房屋承重结构和拆改室内设施，不得损害其他业主和使用人的合法权益。 承租人因使用不当等原因造成承租房屋和设施损坏的，承租人应当负责修复或者承担赔偿责任。"},{"i":11,"n":"第十一条","txt":"承租人转租房屋的，应当经出租人书面同意。 承租人未经出租人书面同意转租的，出租人可以解除租赁合同，收回房屋并要求承租人赔偿损失。"},{"i":12,"n":"第十二条","txt":"房屋租赁期间内，因赠与、析产、继承或者买卖转让房屋的，原房屋租赁合同继续有效。 承租人在房屋租赁期间死亡的，与其生前共同居住的人可以按照原租赁合同租赁该房屋。"},{"i":13,"n":"第十三条","txt":"房屋租赁期间出租人出售租赁房屋的，应当在出售前合理期限内通知承租人，承租人在同等条件下有优先购买权。"},{"i":14,"n":"第十四条","txt":"房屋租赁合同订立后三十日内，房屋租赁当事人应当到租赁房屋所在地直辖市、市、县人民政府建设（房地产）主管部门办理房屋租赁登记备案。 房屋租赁当事人可以书面委托他人办理房屋租赁登记备案。"},{"i":15,"n":"第十五条","txt":"办理房屋租赁登记备案，房屋租赁当事人应当提交下列材料： （一）房屋租赁合同； （二）房屋租赁当事人身份证明； （三）房屋所有权证书或者其他合法权属证明； （四）直辖市、市、县人民政府建设（房地产）主管部门规定的其他材料。 房屋租赁当事人提交的材料应当真实、合法、有效，不得隐瞒真实情况或者提供虚假材料。"},{"i":16,"n":"第十六条","txt":"对符合下列要求的，直辖市、市、县人民政府建设（房地产）主管部门应当在三个工作日内办理房屋租赁登记备案，向租赁当事人开具房屋租赁登记备案证明： （一）申请人提交的申请材料齐全并且符合法定形式； （二）出租人与房屋所有权证书或者其他合法权属证明记载的主体一致； （三）不属于本办法第六条规定不得出租的房屋。 申请人提交的申请材料不齐全或者不符合法定形式的，直辖市、市、县人民政府建设（房地产）主管部门应当告知房屋租赁当事人需要补正的内容。"},{"i":17,"n":"第十七条","txt":"房屋租赁登记备案证明应当载明出租人的姓名或者名称，承租人的姓名或者名称、有效身份证件种类和号码，出租房屋的坐落、租赁用途、租金数额、租赁期限等。"},{"i":18,"n":"第十八条","txt":"房屋租赁登记备案证明遗失的，应当向原登记备案的部门补领。"},{"i":19,"n":"第十九条","txt":"房屋租赁登记备案内容发生变化、续租或者租赁终止的，当事人应当在三十日内，到原租赁登记备案的部门办理房屋租赁登记备案的变更、延续或者注销手续。"},{"i":20,"n":"第二十条","txt":"直辖市、市、县建设（房地产）主管部门应当建立房屋租赁登记备案信息系统，逐步实行房屋租赁合同网上登记备案，并纳入房地产市场信息系统。 房屋租赁登记备案记载的信息应当包含以下内容： （一）出租人的姓名（名称）、住所； （二）承租人的姓名（名称）、身份证件种类和号码； （三）出租房屋的坐落、租赁用途、租金数额、租赁期限； （四）其他需要记载的内容。"},{"i":21,"n":"第二十一条","txt":"违反本办法第六条规定的，由直辖市、市、县人民政府建设（房地产）主管部门责令限期改正，对没有违法所得的，可处以五千元以下罚款；对有违法所得的，可以处以违法所得一倍以上三倍以下，但不超过三万元的罚款。"},{"i":22,"n":"第二十二条","txt":"违反本办法第八条规定的，由直辖市、市、县人民政府建设（房地产）主管部门责令限期改正，逾期不改正的，可处以五千元以上三万元以下罚款。"},{"i":23,"n":"第二十三条","txt":"违反本办法第十四条第一款、第十九条规定的，由直辖市、市、县人民政府建设（房地产）主管部门责令限期改正；个人逾期不改正的，处以一千元以下罚款；单位逾期不改正的，处以一千元以上一万元以下罚款。"},{"i":24,"n":"第二十四条","txt":"直辖市、市、县人民政府建设（房地产）主管部门对符合本办法规定的房屋租赁登记备案申请不予办理、对不符合本办法规定的房屋租赁登记备案申请予以办理，或者对房屋租赁登记备案信息管理不当，给租赁当事人造成损失的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"保障性住房租赁按照国家有关规定执行。"},{"i":26,"n":"第二十六条","txt":"城市规划区外国有土地上的房屋租赁和监督管理，参照本办法执行。"},{"i":27,"n":"第二十七条","txt":"省、自治区、直辖市人民政府住房和城乡建设主管部门可以依据本办法制定实施细则。"},{"i":28,"n":"第二十八条","txt":"本办法自2011年2月1日起施行，建设部1995年5月9日发布的《城市房屋租赁管理办法》（建设部令第42号）同时废止。"}],"shangpinfangxiaoshouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范商品房销售行为，保障商品房交易双方当事人的合法权益，根据《中华人民共和国城市房地产管理法》、《城市房地产开发经营管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"商品房销售及商品房销售管理应当遵守本办法。"},{"i":3,"n":"第三条","txt":"商品房销售包括商品房现售和商品房预售。 本办法所称商品房现售，是指房地产开发企业将竣工验收合格的商品房出售给买受人，并由买受人支付房价款的行为。 本办法所称商品房预售，是指房地产开发企业将正在建设中的商品房预先出售给买受人，并由买受人支付定金或者房价款的行为。"},{"i":4,"n":"第四条","txt":"房地产开发企业可以自行销售商品房，也可以委托房地产中介服务机构销售商品房。"},{"i":5,"n":"第五条","txt":"国务院建设行政主管部门负责全国商品房的销售管理工作。 省、自治区人民政府建设行政主管部门负责本行政区域内商品房的销售管理工作。 直辖市、市、县人民政府建设行政主管部门、房地产行政主管部门（以下统称房地产开发主管部门）按照职责分工，负责本行政区域内商品房的销售管理工作。"},{"i":6,"n":"第六条","txt":"商品房预售实行预售许可制度。 商品房预售条件及商品房预售许可证明的办理程序，按照《城市房地产开发经营管理条例》和《城市商品房预售管理办法》的有关规定执行。"},{"i":7,"n":"第七条","txt":"商品房现售,应当符合以下条件： （一）现售商品房的房地产开发企业应当具有企业法人营业执照和房地产开发企业资质证书； （二）取得土地使用权证书或者使用土地的批准文件； （三）持有建设工程规划许可证和施工许可证； （四）已通过竣工验收； （五）拆迁安置已经落实； （六）供水、供电、供热、燃气、通讯等配套基础设施具备交付使用条件，其他配套基础设施和公共设施具备交付使用条件或者已确定施工进度和交付日期； （七）物业管理方案已经落实。"},{"i":8,"n":"第八条","txt":"房地产开发企业应当在商品房现售前将房地产开发项目手册及符合商品房现售条件的有关证明文件报送房地产开发主管部门备案。"},{"i":9,"n":"第九条","txt":"房地产开发企业销售设有抵押权的商品房，其抵押权的处理按照《中华人民共和国担保法》、《城市房地产抵押管理办法》的有关规定执行。"},{"i":10,"n":"第十条","txt":"房地产开发企业不得在未解除商品房买卖合同前，将作为合同标的物的商品房再行销售给他人。"},{"i":11,"n":"第十一条","txt":"房地产开发企业不得采取返本销售或者变相返本销售的方式销售商品房。 房地产开发企业不得采取售后包租或者变相售后包租的方式销售未竣工商品房。"},{"i":12,"n":"第十二条","txt":"商品住宅按套销售，不得分割拆零销售。"},{"i":13,"n":"第十三条","txt":"商品房销售时，房地产开发企业选聘了物业管理企业的，买受人应当在订立商品房买卖合同时与房地产开发企业选聘的物业管理企业订立有关物业管理的协议。"},{"i":14,"n":"第十四条","txt":"房地产开发企业、房地产中介服务机构发布商品房销售宣传广告，应当执行《中华人民共和国广告法》、《房地产广告发布暂行规定》等有关规定，广告内容必须真实、合法、科学、准确。"},{"i":15,"n":"第十五条","txt":"房地产开发企业、房地产中介服务机构发布的商品房销售广告和宣传资料所明示的事项，　当事人应当在商品房买卖合同中约定。"},{"i":16,"n":"第十六条","txt":"商品房销售时，房地产开发企业和买受人应当订立书面商品房买卖合同。 商品房买卖合同应当明确以下主要内容： （一）当事人名称或者姓名和住所； （二）商品房基本状况； （三）商品房的销售方式； （四）商品房价款的确定方式及总价款、付款方式、付款时间； （五）交付使用条件及日期； （六）装饰、设备标准承诺； （七）供水、供电、供热、燃气、通讯、道路、绿化等配套基础设施和公共设施的交付承诺和有关权益、责任； （八）公共配套建筑的产权归属； （九）面积差异的处理方式； （十）办理产权登记有关事宜； （十一）解决争议的方法； （十二）违约责任； （十三）双方约定的其他事项。"},{"i":17,"n":"第十七条","txt":"商品房销售价格由当事人协商议定，国家另有规定的除外。"},{"i":18,"n":"第十八条","txt":"商品房销售可以按套（单元）计价，也可以按套内建筑面积或者建筑面积计价。 商品房建筑面积由套内建筑面积和分摊的共有建筑面积组成，套内建筑面积部分为独立产权，分摊的共有建筑面积部分为共有产权，买受人按照法律、法规的规定对其享有权利，承担责任。 按套（单元）计价或者按套内建筑面积计价的，商品房买卖合同中应当注明建筑面积和分摊的共有建筑面积。"},{"i":19,"n":"第十九条","txt":"按套（单元）计价的现售房屋，当事人对现售房屋实地勘察后可以在合同中直接约定总价款。 按套（单元）计价的预售房屋，房地产开发企业应当在合同中附所售房屋的平面图。平面图应当标明详细尺寸，并约定误差范围。房屋交付时，套型与设计图纸一致，相关尺寸也在约定的误差范围内，维持总价款不变；套型与设计图纸不一致或者相关尺寸超出约定的误差范围，合同中未约定处理方式的，买受人可以退房或者与房地产开发企业重新约定总价款。买受人退房的，由房地产开发企业承担违约责任。"},{"i":20,"n":"第二十条","txt":"按套内建筑面积或者建筑面积计价的，当事人应当在合同中载明合同约定面积与产权登记面积发生误差的处理方式。 合同未作约定的，按以下原则处理： （一）面积误差比绝对值在3％以内（含3％）的，据实结算房价款； （二）面积误差比绝对值超出3％时，买受人有权退房。买受人退房的，房地产开发企业应当在买受人提出退房之日起30日内将买受人已付房价款退还给买受人，同时支付已付房价款利息。买受人不退房的，产权登记面积大于合同约定面积时，面积误差比在3％以内（含3％）部分的房价款由买受人补足；超出3％部分的房价款由房地产开发企业承担，产权归买受人。产权登记面积小于合同约定面积时，面积误差比绝对值在3％以内（含3％）部分的房价款由房地产开发企业返还买受人；绝对值超出3％部分的房价款由房地产开发企业双倍返还买受人。 产权登记面积－合同约定面积 面积误差比＝　————————————————×100％ 合同约定面积"},{"i":21,"n":"第二十一条","txt":"按建筑面积计价的，当事人应当在合同中约定套内建筑面积和分摊的共有建筑面积，并约定建筑面积不变而套内建筑面积发生误差以及建筑面积与套内建筑面积均发生误差时的处理方式。"},{"i":22,"n":"第二十二条","txt":"不符合商品房销售条件的，房地产开发企业不得销售商品房，不得向买受人收取任何预订款性质费用。 符合商品房销售条件的，房地产开发企业在订立商品房买卖合同之前向买受人收取预订款性质费用的，订立商品房买卖合同时，所收费用应当抵作房价款；当事人未能订立商品房买卖合同的，房地产开发企业应当向买受人返还所收费用；当事人之间另有约定的，从其约定。"},{"i":23,"n":"第二十三条","txt":"房地产开发企业应当在订立商品房买卖合同之前向买受人明示《商品房销售管理办法》和《商品房买卖合同示范文本》；预售商品房的，还必须明示《城市商品房预售管理办法》。"},{"i":24,"n":"第二十四条","txt":"房地产开发企业应当按照批准的规划、设计建设商品房。商品房销售后，房地产开发企业不得擅自变更规划、设计。 经规划部门批准的规划变更、设计单位同意的设计变更导致商品房的结构型式、户型、空间尺寸、朝向变化，以及出现合同当事人约定的其他影响商品房质量或者使用功能情形的，　房地产开发企业应当在变更确立之日起10日内，书面通知买受人。 买受人有权在通知到达之日起15日内做出是否退房的书面答复。买受人在通知到达之日起15日内未作书面答复的，视同接受规划、设计变更以及由此引起的房价款的变更。房地产开发企业未在规定时限内通知买受人的，买受人有权退房；买受人退房的，由房地产开发企业承担违约责任。"},{"i":25,"n":"第二十五条","txt":"房地产开发企业委托中介服务机构销售商品房的，受托机构应当是依法设立并取得工商营业执照的房地产中介服务机构。 房地产开发企业应当与受托房地产中介服务机构订立书面委托合同，委托合同应当载明委托期限、委托权限以及委托人和被委托人的权利、义务。"},{"i":26,"n":"第二十六条","txt":"受托房地产中介服务机构销售商品房时，应当向买受人出示商品房的有关证明文件和商品房销售委托书。"},{"i":27,"n":"第二十七条","txt":"受托房地产中介服务机构销售商品房时，应当如实向买受人介绍所代理销售商品房的有关情况。 受托房地产中介服务机构不得代理销售不符合销售条件的商品房。"},{"i":28,"n":"第二十八条","txt":"受托房地产中介服务机构在代理销售商品房时不得收取佣金以外的其他费用。"},{"i":29,"n":"第二十九条","txt":"商品房销售人员应当经过专业培训，方可从事商品房销售业务。"},{"i":30,"n":"第三十条","txt":"房地产开发企业应当按照合同约定，将符合交付使用条件的商品房按期交付给买受人。未能按期交付的，房地产开发企业应当承担违约责任。 因不可抗力或者当事人在合同中约定的其他原因，需延期交付的，房地产开发企业应当及时告知买受人。"},{"i":31,"n":"第三十一条","txt":"房地产开发企业销售商品房时设置样板房的，应当说明实际交付的商品房质量、设备及装修与样板房是否一致，未作说明的，实际交付的商品房应当与样板房一致。"},{"i":32,"n":"第三十二条","txt":"销售商品住宅时，房地产开发企业应当根据《商品住宅实行质量保证书和住宅使用说明书制度的规定》（以下简称《规定》），向买受人提供《住宅质量保证书》、《住宅使用说明书》。"},{"i":33,"n":"第三十三条","txt":"房地产开发企业应当对所售商品房承担质量保修责任。当事人应当在合同中就保修范围、保修期限、保修责任等内容做出约定。保修期从交付之日起计算。 商品住宅的保修期限不得低于建设工程承包单位向建设单位出具的质量保修书约定保修期的存续期；存续期少于《规定》中确定的最低保修期限的，保修期不得低于《规定》中确定的最低保修期限。 非住宅商品房的保修期限不得低于建设工程承包单位向建设单位出具的质量保修书约定保修期的存续期。 在保修期限内发生的属于保修范围的质量问题，房地产开发企业应当履行保修义务，并对造成的损失承担赔偿责任。因不可抗力或者使用不当造成的损坏，房地产开发企业不承担责任。"},{"i":34,"n":"第三十四条","txt":"房地产开发企业应当在商品房交付使用前按项目委托具有房产测绘资格的单位实施测绘，测绘成果报房地产行政主管部门审核后用于房屋权属登记。 房地产开发企业应当在商品房交付使用之日起60日内，将需要由其提供的办理房屋权属登记的资料报送房屋所在地房地产行政主管部门。 房地产开发企业应当协助商品房买受人办理土地使用权变更和房屋所有权登记手续。"},{"i":35,"n":"第三十五条","txt":"商品房交付使用后，买受人认为主体结构质量不合格的，可以依照有关规定委托工程质量检测机构重新核验。经核验，确属主体结构质量不合格的，买受人有权退房；给买受人造成损失的，房地产开发企业应当依法承担赔偿责任。"},{"i":36,"n":"第三十六条","txt":"未取得营业执照，擅自销售商品房的，由县级以上人民政府工商行政管理部门依照《城市房地产开发经营管理条例》的规定处罚。"},{"i":37,"n":"第三十七条","txt":"未取得房地产开发企业资质证书，擅自销售商品房的，责令停止销售活动，处5万元以上10万元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"违反法律、法规规定，擅自预售商品房的，责令停止违法行为，没收违法所得；收取预付款的，可以并处已收取的预付款1％以下的罚款。"},{"i":39,"n":"第三十九条","txt":"在未解除商品房买卖合同前，将作为合同标的物的商品房再行销售给他人的，处以警告，责令限期改正，并处2万元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"房地产开发企业将未组织竣工验收、验收不合格或者对不合格按合格验收的商品房擅自交付使用的，按照《建设工程质量管理条例》的规定处罚。"},{"i":41,"n":"第四十一条","txt":"房地产开发企业未按规定将测绘成果或者需要由其提供的办理房屋权属登记的资料报送房地产行政主管部门的，处以警告，责令限期改正，并可处以2万元以上3万元以下罚款。"},{"i":42,"n":"第四十二条","txt":"房地产开发企业在销售商品房中有下列行为之一的，处以警告，责令限期改正，并可处以1万元以上3万元以下罚款。 （一）未按照规定的现售条件现售商品房的； （二）未按照规定在商品房现售前将房地产开发项目手册及符合商品房现售条件的有关证明文件报送房地产开发主管部门备案的； （三）返本销售或者变相返本销售商品房的； （四）采取售后包租或者变相售后包租方式销售未竣工商品房的； （五）分割拆零销售商品住宅的； （六）不符合商品房销售条件，向买受人收取预订款性质费用的； （七）未按照规定向买受人明示《商品房销售管理办法》、《商品房买卖合同示范文本》、《城市商品房预售管理办法》的； （八）委托没有资格的机构代理销售商品房的。"},{"i":43,"n":"第四十三条","txt":"房地产中介服务机构代理销售不符合销售条件的商品房的,处以警告，责令停止销售，并可处以2万元以上3万元以下罚款。"},{"i":44,"n":"第四十四条","txt":"国家机关工作人员在商品房销售管理工作中玩忽职守、滥用职权、徇私舞弊，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":45,"n":"第四十五条","txt":"本办法所称返本销售，是指房地产开发企业以定期向买受人返还购房款的方式销售商品房的行为。 本办法所称售后包租，是指房地产开发企业以在一定期限内承租或者代为出租买受人所购该企业商品房的方式销售商品房的行为。 本办法所称分割拆零销售，是指房地产开发企业以将成套的商品住宅分割为数部分分别出售给买受人的方式销售商品住宅的行为。 本办法所称产权登记面积，是指房地产行政主管部门确认登记的房屋面积。"},{"i":46,"n":"第四十六条","txt":"省、自治区、直辖市人民政府建设行政主管部门可以根据本办法制定实施细则。"},{"i":47,"n":"第四十七条","txt":"本办法由国务院建设行政主管部门负责解释。"},{"i":48,"n":"第四十八条","txt":"本办法自2001年6月1日起施行。"}],"guojiajifengjingmingshengquguihuabianzhishenpibanf87653f":[{"i":1,"n":"第一条","txt":"为了规范国家级风景名胜区规划的编制和审批，根据《中华人民共和国城乡规划法》、《风景名胜区条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"国家级风景名胜区规划的编制和审批，适用本办法。"},{"i":3,"n":"第三条","txt":"经批准的国家级风景名胜区规划是国家级风景名胜区保护、利用和管理的依据。风景名胜区管理机构以及县级以上地方人民政府住房城乡建设主管部门不得违反国家级风景名胜区规划审批各类建设活动。 国家级风景名胜区规划未经批准的，不得在国家级风景名胜区内进行建设活动。"},{"i":4,"n":"第四条","txt":"编制国家级风景名胜区规划，应当坚持保护优先、开发服从保护的原则，突出风景名胜资源的自然特性、文化内涵和地方特色，实现风景名胜资源的永续利用。"},{"i":5,"n":"第五条","txt":"国家级风景名胜区规划分为总体规划和详细规划。"},{"i":6,"n":"第六条","txt":"省、自治区人民政府住房城乡建设主管部门和直辖市人民政府风景名胜区主管部门（以下简称风景名胜区规划组织编制机关），负责组织国家级风景名胜区所在地市、县人民政府和风景名胜区管理机构等开展国家级风景名胜区规划编制工作。"},{"i":7,"n":"第七条","txt":"编制国家级风景名胜区总体规划应当由具有甲级资质的城乡规划编制单位承担。 编制国家级风景名胜区详细规划应当由同时具有乙级以上城乡规划编制单位资质和风景园林工程设计专项资质的单位承担。"},{"i":8,"n":"第八条","txt":"编制国家级风景名胜区规划应当遵守国家有关技术规范和标准，采用符合国家有关规定的基础资料。"},{"i":9,"n":"第九条","txt":"编制国家级风景名胜区总体规划，应当进行科学论证，并广泛征求有关部门、专家和公众意见；必要时，可以举行听证。"},{"i":10,"n":"第十条","txt":"国家级风景名胜区总体规划应当包括下列内容： （一）界定风景名胜区和核心景区的范围边界，根据需要划定外围保护地带； （二）明确风景名胜资源的类型和特色，评价资源价值和等级； （三）确定风景名胜区的性质和定位； （四）提出风景名胜区保护与发展目标，确定风景名胜区的游客容量、建设用地控制规模、旅游床位控制规模等； （五）确定功能分区，提出基础设施、游览服务、风景游赏、居民点的空间布局； （六）划定分级保护范围，提出分级保护规定；明确禁止建设和限制建设的范围，提出开发利用强度控制要求；提出重要风景名胜资源专项保护措施和生态环境保护控制要求； （七）确定重大建设项目布局；提出建设行为引导控制和景观风貌管控要求；确定需要编制详细规划的区域，提出详细规划编制应当遵从的重要控制指标或者要求； （八）编制游赏、设施、居民点协调、相关规划协调等专项规划。"},{"i":11,"n":"第十一条","txt":"国家级风景名胜区总体规划应当自国家级风景名胜区批准设立之日起2年内编制完成。总体规划的规划期一般为20年。"},{"i":12,"n":"第十二条","txt":"编制国家级风景名胜区详细规划应当符合国家级风景名胜区总体规划。总体规划确定的主要入口区、游览服务设施相对集中区等涉及较多建设活动的区域应当编制详细规划。 国家级风景名胜区详细规划应当包括下列内容： （一）明确规划范围和规划区域的定位，分析总体规划相关要求； （二）确定规划目标，提出发展控制规模； （三）评价规划范围的资源、环境和用地条件，确定规划布局和建设用地的范围边界； （四）提出建设用地范围内各地块的建筑限高、建筑密度、容积率、绿地率、给排水与水环境等控制指标及建筑形式、体量、风貌、色彩等设计要求；明确重要项目选址、布局、规模、高度等建设控制要求，对重要建（构）筑物的景观视线影响进行分析，提出设计方案引导措施； （五）编制综合设施、游赏组织、居民点建设引导、土地利用协调等专项规划。"},{"i":13,"n":"第十三条","txt":"编制国家级风景名胜区规划，不得在核心景区内安排下列项目、设施或者建筑物： （一）索道、缆车、铁路、水库、高等级公路等重大建设工程项目； （二）宾馆、招待所、培训中心、疗养院等住宿疗养设施； （三）大型文化、体育和游乐设施； （四）其他与核心景区资源、生态和景观保护无关的项目、设施或者建筑物。"},{"i":14,"n":"第十四条","txt":"国家级风景名胜区规划成果应当包括规划文本、规划图纸、规划说明书、基础资料汇编、遥感影像图，以书面和电子文件两种形式表达。 征求意见及意见采纳的情况、专题论证材料、专家评审意见、公示情况等，应当纳入基础资料汇编。"},{"i":15,"n":"第十五条","txt":"编制国家级风景名胜区总体规划，确需对经审定的风景名胜区范围进行较大调整或者安排索道、缆车等重大建设工程项目的，风景名胜区规划组织编制机关应当组织专家进行专题论证，形成专题论证材料。"},{"i":16,"n":"第十六条","txt":"国家级风景名胜区规划编制完成后，风景名胜区规划组织编制机关应当组织专家进行评审。评审专家应当包括3名以上国务院住房城乡建设主管部门的风景园林专家委员会成员。"},{"i":17,"n":"第十七条","txt":"国家级风景名胜区规划报送审批前，风景名胜区规划组织编制机关和风景名胜区管理机构应当依法将规划草案予以公示；公示时间不得少于30日。"},{"i":18,"n":"第十八条","txt":"国家级风景名胜区总体规划由省、自治区、直辖市人民政府报国务院审批。 国家级风景名胜区详细规划由风景名胜区规划组织编制机关报国务院住房城乡建设主管部门审批。"},{"i":19,"n":"第十九条","txt":"国家级风景名胜区总体规划审批前，国务院住房城乡建设主管部门应当按照国务院要求，组织专家对规划进行审查，征求国务院有关部门意见后，提出审查意见报国务院。"},{"i":20,"n":"第二十条","txt":"风景名胜区规划组织编制机关和风景名胜区管理机构应当将经批准的国家级风景名胜区规划及时向社会公布，并为公众查阅提供便利。法律、行政法规规定不得公开的内容除外。"},{"i":21,"n":"第二十一条","txt":"经批准的国家级风景名胜区规划不得擅自修改。确需对经批准的国家级风景名胜区总体规划中的风景名胜区范围、性质、保护目标、生态资源保护措施、重大建设项目布局、开发利用强度以及风景名胜区的功能结构、空间布局、游客容量进行修改的，应当报原审批机关批准；对其他内容进行修改的，应当报原审批机关备案。 国家级风景名胜区详细规划确需修改的，应当报原审批机关批准。"},{"i":22,"n":"第二十二条","txt":"编制城市、镇规划，规划范围与国家级风景名胜区存在交叉或者重合的，应当将国家级风景名胜区总体规划中的保护要求纳入城市、镇规划。编制乡规划和村庄规划，规划范围与国家级风景名胜区存在交叉或者重合的，应当符合国家级风景名胜区总体规划。 国家级风景名胜区外围保护地带内的城乡建设和发展，应当与国家级风景名胜区总体规划的要求相协调。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人都应当遵守经批准的国家级风景名胜区规划，服从规划管理，并有权就涉及其利害关系的建设活动是否符合国家级风景名胜区规划的要求向风景名胜区管理机构查询。 任何单位和个人都有权向风景名胜区管理机构举报或者控告违反国家级风景名胜区规划的行为。"},{"i":24,"n":"第二十四条","txt":"风景名胜区规划组织编制机关应当至少每5年组织专家对规划实施情况进行一次评估。评估报告应当及时报国务院住房城乡建设主管部门。 国家级风景名胜区总体规划的规划期届满前2年，风景名胜区规划组织编制机关应当对规划进行评估，作出是否重新编制规划的决定。在新规划批准前，原规划继续有效。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，风景名胜区规划组织编制机关或者风景名胜区管理机构有下列行为之一的，由上级地方人民政府或者主管部门责令改正，并依法对直接负责的主管人员和其他直接责任人员给予处分： （一）未组织编制国家级风景名胜区规划的； （二）未按照法定程序组织编制国家级风景名胜区规划的； （三）批准设立之日起2年内未编制完成国家级风景名胜区总体规划的； （四）擅自修改国家级风景名胜区规划的； （五）未将批准的国家级风景名胜区规划予以公布的。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，风景名胜区管理机构以及县级以上地方人民政府住房城乡建设主管部门违反国家级风景名胜区规划批准建设活动的，应当依法对直接负责的主管人员和其他直接责任人员给予处分。"},{"i":27,"n":"第二十七条","txt":"本办法自2015年12月1日起施行。"}],"chengxiangguihuabianzhidanweizizhiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对城乡规划编制单位的管理，规范城乡规划编制工作，保证城乡规划编制质量，根据《中华人民共和国城乡规划法》、《中华人民共和国行政许可法》等法律，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内申请城乡规划编制单位资质，实施对城乡规划编制单位资质监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"城乡规划组织编制机关应当委托具有相应资质等级的单位承担城乡规划的具体编制工作。"},{"i":4,"n":"第四条","txt":"从事城乡规划编制的单位，应当取得相应等级的资质证书，并在资质等级许可的范围内从事城乡规划编制工作。"},{"i":5,"n":"第五条","txt":"国务院城乡规划主管部门负责全国城乡规划编制单位的资质管理工作。 县级以上地方人民政府城乡规划主管部门负责本行政区域内城乡规划编制单位的资质管理工作。"},{"i":6,"n":"第六条","txt":"城乡规划编制单位资质分为甲级、乙级、丙级。"},{"i":7,"n":"第七条","txt":"甲级城乡规划编制单位资质标准： （一）有法人资格； （二）专业技术人员不少于40人，其中具有城乡规划专业高级技术职称的不少于4人，具有其他专业高级技术职称的不少于4人（建筑、道路交通、给排水专业各不少于1人）；具有城乡规划专业中级技术职称的不少于8人，具有其他专业中级技术职称的不少于15人； （三）注册规划师不少于10人； （四）具备符合业务要求的计算机图形输入输出设备及软件； （五）有400平方米以上的固定工作场所，以及完善的技术、质量、财务管理制度。"},{"i":8,"n":"第八条","txt":"乙级城乡规划编制单位资质标准： （一）有法人资格； （二）专业技术人员不少于25人，其中具有城乡规划专业高级技术职称的不少于2人，具有高级建筑师不少于1人、具有高级工程师不少于1人；具有城乡规划专业中级技术职称的不少于5人，具有其他专业中级技术职称的不少于10人； （三）注册规划师不少于4人； （四）具备符合业务要求的计算机图形输入输出设备； （五）有200平方米以上的固定工作场所，以及完善的技术、质量、财务管理制度。"},{"i":9,"n":"第九条","txt":"丙级城乡规划编制单位资质标准： （一）有法人资格； （二）专业技术人员不少于15人，其中具有城乡规划专业中级技术职称的不少于2人，具有其他专业中级技术职称的不少于4人； （三）注册规划师不少于1人； （四）专业技术人员配备计算机达80%； （五）有100平方米以上的固定工作场所，以及完善的技术、质量、财务管理制度。"},{"i":10,"n":"第十条","txt":"城乡规划编制单位的高级职称技术人员或注册规划师年龄应当在70岁以下，其中，甲级城乡规划编制单位60岁以上高级职称技术人员或注册规划师不应超过4人，乙级城乡规划编制单位60岁以上高级职称技术人员或注册规划师不应超过2人。 城乡规划编制单位的其他专业技术人员年龄应当在60岁以下。 高等院校的城乡规划编制单位中专职从事城乡规划编制的人员不得低于技术人员总数的70%。"},{"i":11,"n":"第十一条","txt":"甲级城乡规划编制单位承担城乡规划编制业务的范围不受限制。"},{"i":12,"n":"第十二条","txt":"乙级城乡规划编制单位可以在全国承担下列业务： （一）镇、20万现状人口以下城市总体规划的编制； （二）镇、登记注册所在地城市和100万现状人口以下城市相关专项规划的编制； （三）详细规划的编制； （四）乡、村庄规划的编制； （五）建设工程项目规划选址的可行性研究。"},{"i":13,"n":"第十三条","txt":"丙级城乡规划编制单位可以在全国承担下列业务： （一）镇总体规划（县人民政府所在地镇除外）的编制； （二）镇、登记注册所在地城市和20万现状人口以下城市的相关专项规划及控制性详细规划的编制； （三）修建性详细规划的编制； （四）乡、村庄规划的编制； （五）中、小型建设工程项目规划选址的可行性研究。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市人民政府城乡规划主管部门可以根据实际情况，设立专门从事乡和村庄规划编制单位的资质，并将资质标准报国务院城乡规划主管部门备案。"},{"i":15,"n":"第十五条","txt":"申请资质证书应当提供以下材料： （一）城乡规划编制单位资质申请表； （二）法人资格证明材料； （三）法定代表人和主要技术负责人的身份证明、任职文件、学历证书、职称证书等； （四）专业技术人员的身份证明、执业资格证明、职称证书、劳动合同、社会保险缴纳证明等； （五）完成城乡规划编制项目情况； （六）技术装备和工作场所等证明材料； （七）其他需要出具的证明或者资料。"},{"i":16,"n":"第十六条","txt":"城乡规划编制单位甲级资质许可，由国务院城乡规划主管部门实施。 城乡规划编制单位申请甲级资质的，可以向登记注册所在地省、自治区、直辖市人民政府城乡规划主管部门提交申请材料。省、自治区、直辖市人民政府城乡规划主管部门收到申请材料后，应当核对身份证、职称证、学历证等原件，在相应复印件上注明原件已核对，并于5日内将全部申请材料报国务院城乡规划主管部门。 国务院城乡规划主管部门在收到申请材料后，应当依法作出是否受理的决定，并出具凭证；申请材料不齐全或者不符合法定形式的，应当在5日内一次性告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。 国务院城乡规划主管部门应当自受理申请材料之日起20日内作出审批决定。自作出决定之日起10日内公告审批结果。 组织专家评审所需时间不计算在上述时限内，但应当明确告知申请人。"},{"i":17,"n":"第十七条","txt":"城乡规划编制单位乙级、丙级资质许可，由登记注册所在地省、自治区、直辖市人民政府城乡规划主管部门实施。资质许可的实施办法由省、自治区、直辖市人民政府城乡规划主管部门依法确定。 省、自治区、直辖市人民政府城乡规划主管部门应当自作出决定之日起30日内，将准予资质许可的决定报国务院城乡规划主管部门备案。"},{"i":18,"n":"第十八条","txt":"资质许可机关作出准予资质许可的决定，应当予以公告，公众有权查阅。"},{"i":19,"n":"第十九条","txt":"城乡规划编制单位初次申请，其申请资质等级最高不超过乙级。"},{"i":20,"n":"第二十条","txt":"乙级、丙级城乡规划编制单位取得资质证书满2年后，可以申请高一级别的城乡规划编制单位资质。"},{"i":21,"n":"第二十一条","txt":"在资质证书有效期内，单位名称、地址、法定代表人等发生变更的，应当在登记注册部门办理变更手续后30日内到原资质许可机关办理资质证书变更手续。"},{"i":22,"n":"第二十二条","txt":"申请资质证书变更，应当提交以下材料： （一）资质证书变更申请； （二）法人资格证明材料； （三）资质证书正、副本原件； （四）与资质变更事项有关的证明材料。"},{"i":23,"n":"第二十三条","txt":"城乡规划编制单位合并的，合并后存续或者新设立的编制单位可以承继合并前各方中较高的资质等级，但应当符合相应的资质等级条件。 城乡规划编制单位分立的，分立后资质等级，根据实际达到的资质条件，按照本规定的审批程序核定。 城乡规划编制单位改制的，改制后不再符合资质标准的，应按其实际达到的资质标准及本规定申请重新核定；资质条件不发生变化的，按本规定第二十二条办理。"},{"i":24,"n":"第二十四条","txt":"城乡规划编制单位资质证书分为正本和副本，正本一份，副本若干份，由国务院城乡规划主管部门统一印制，正本和副本具有同等法律效力。资质证书有效期为5年。"},{"i":25,"n":"第二十五条","txt":"资质证书有效期届满，城乡规划编制单位需要延续资质证书有效期的，应当在资质证书有效期届满前3个月，申请办理资质延续手续。 对在资质证书有效期内遵守有关法律、法规、规章、技术标准，信用档案中无不良行为记录，满足资质标准要求的城乡规划编制单位，经资质许可机关同意，有效期延续5年。"},{"i":26,"n":"第二十六条","txt":"城乡规划编制单位领取新的资质证书，应当将原资质证书交回资质许可机关予以注销。城乡规划编制单位遗失资质证书的，应当在公众媒体上发布遗失声明后，向资质许可机关申请补发。"},{"i":27,"n":"第二十七条","txt":"城乡规划编制单位设立的分支机构中，具有独立法人资格的，应当按照本规定申请资质证书。非独立法人的机构，不得以分支机构名义承揽业务。"},{"i":28,"n":"第二十八条","txt":"两个以上城乡规划编制单位合作编制城乡规划，资质等级较高的一方应对编制成果质量负责。"},{"i":29,"n":"第二十九条","txt":"编制城乡规划以及所提交的规划编制成果，应当符合国家有关城乡规划的法律、法规和规章，符合与城乡规划编制有关的标准、规范。 城乡规划编制单位提交的城乡规划编制成果，应当在文件扉页注明单位资质等级和证书编号。"},{"i":30,"n":"第三十条","txt":"资质许可机关可以依法对城乡规划编制单位进行必要的检查，并有权采取下列措施： （一）要求被检查单位提供资质证书，有关人员的职称证书、注册证书、学历证书、社会保险证明等，有关城乡规划编制成果及有关质量管理、档案管理、财务管理等企业内部管理制度的文件； （二）进入被检查单位进行检查，查阅相关资料； （三）纠正违反有关法律、法规和本规定及有关规范和标准的行为。 资质许可机关依法进行监督检查时，应当将监督检查情况和处理结果予以记录，由监督检查人员签字后归档。"},{"i":31,"n":"第三十一条","txt":"资质许可机关在实施监督检查时，应当有两名以上监督检查人员参加，不得妨碍单位正常的生产经营活动，不得索取或者收受单位的财物，不得谋取其他利益。 有关单位和个人对依法进行的监督检查应当协助与配合，不得拒绝或者阻挠。 监督检查机关应当将监督检查的处理结果向社会公布。"},{"i":32,"n":"第三十二条","txt":"城乡规划编制单位违法从事城乡规划编制活动的，违法行为发生地的县级以上地方人民政府城乡规划主管部门应当依法查处，并将违法事实、处理结果或者处理建议及时告知该城乡规划编制单位的资质许可机关。"},{"i":33,"n":"第三十三条","txt":"城乡规划编制单位取得资质后，不再符合相应资质条件的，由原资质许可机关责令限期改正；逾期不改的，降低资质等级或者吊销资质证书。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，资质许可机关或者其上级机关，根据利害关系人的请求或者依据职权，可以撤销城乡规划编制单位资质： （一）资质许可机关工作人员滥用职权、玩忽职守作出准予城乡规划编制单位资质许可的； （二）超越法定职权作出准予城乡规划编制单位资质许可的； （三）违反法定程序作出准予城乡规划编制单位资质许可的； （四）对不符合许可条件的申请人作出准予城乡规划编制单位资质许可的； （五）依法可以撤销资质证书的其他情形。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一的，资质许可机关应当依法注销城乡规划编制单位资质，并公告其资质证书作废，城乡规划编制单位应当及时将资质证书交回资质许可机关： （一）资质证书有效期届满未延续的； （二）城乡规划编制单位依法终止的； （三）资质依法被撤销、吊销的； （四）法律、法规规定的应当注销资质的其他情形。"},{"i":36,"n":"第三十六条","txt":"城乡规划编制单位应当按照有关规定，向资质许可机关提供真实、准确、完整的信用档案信息。 城乡规划编制单位的信用档案应当包括单位基本情况、业绩、合同履约等情况。被投诉举报和处理、行政处罚等情况应当作为不良行为记入其信用档案。 城乡规划编制单位的信用档案信息按照有关规定向社会公示。"},{"i":37,"n":"第三十七条","txt":"申请人隐瞒有关情况或者提供虚假材料申请城乡规划编制单位资质的，不予受理或者不予行政许可，并给予警告，申请人在1年内不得再次申请城乡规划编制单位资质。 以欺骗、贿赂等不正当手段取得城乡规划编制单位资质证书的，由县级以上地方人民政府城乡规划主管部门处3万元罚款，申请人在3年内不得再次申请城乡规划编制单位资质。"},{"i":38,"n":"第三十八条","txt":"涂改、倒卖、出租、出借或者以其他形式非法转让资质证书的，由县级以上地方人民政府城乡规划主管部门给予警告，责令限期改正，并处3万元罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"城乡规划编制单位有下列行为之一的，由所在地城市、县人民政府城乡规划主管部门责令限期改正，处以合同约定的规划编制费1倍以上2倍以下的罚款；情节严重的，责令停业整顿，由原资质许可机关降低资质等级或者吊销资质证书；造成损失的，依法承担赔偿责任： （一）超越资质等级许可的范围承揽城乡规划编制工作的； （二）违反国家有关标准编制城乡规划的。 未依法取得资质证书承揽城乡规划编制工作的，由县级以上地方人民政府城乡规划主管部门责令停止违法行为，依照前款规定处以罚款；造成损失的，依法承担赔偿责任。 以欺骗手段取得资质证书承揽城乡规划编制工作的，由原资质许可机关吊销资质证书，依照本条第一款规定处以罚款；造成损失的，依法承担赔偿责任。"},{"i":40,"n":"第四十条","txt":"城乡规划编制单位未按照本规定要求提供信用档案信息的，由县级以上地方人民政府城乡规划主管部门给予警告，责令限期改正；逾期未改正的，可处1000元以上1万元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"城乡规划主管部门及其工作人员，违反本规定，有下列情形之一的，由其上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分： （一）对不符合条件的申请人准予城乡规划编制单位资质许可的； （二）对符合条件的申请人不予城乡规划编制单位资质许可或者未在法定期限内作出准予许可决定的； （三）对符合条件的申请不予受理或者未在法定期限内初审完毕的； （四）利用职务上的便利，收受他人财物或者其他好处的； （五）不依法履行监督职责或者监督不力，造成严重后果的。"},{"i":42,"n":"第四十二条","txt":"外商投资企业可以依照本规定申请取得城乡规划编制单位资质证书，在相应资质等级许可范围内，承揽城市、镇总体规划服务以外的城乡规划编制工作。 资质许可机关应当在外商投资企业的资质证书中注明“城市、镇总体规划服务除外”。"},{"i":43,"n":"第四十三条","txt":"本规定自2012年9月1日起施行，原建设部2001年1月23日发布的《城市规划编制单位资质管理规定》（建设部令第84号）同时废止。"}],"chengshigongshuishuizhiguanliguiding":[{"i":1,"n":"第一条","txt":"为加强城市供水水质管理，保障城市供水水质安全，根据《中华人民共和国产品质量法》和《城市供水条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"从事城市供水活动，对城市供水水质实施监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称城市供水水质，是指城市公共供水及自建设施供水（包括二次供水、深度净化处理水）的水质。 本规定所称二次供水，是指单位或者个人使用储存、加压等设施，将城市公共供水或者自建设施供水经储存、加压后再供用户的形式。 本规定所称深度净化处理水，是指利用活性碳、膜等技术对城市自来水或者其他原水作进一步处理后，通过管道形式直接供给城市居民饮用的水。 本规定所称城市供水单位，是指从事城市公共供水及自建设施供水（包括深度净化处理供水）的企业和单位。"},{"i":4,"n":"第四条","txt":"国务院建设主管部门负责全国城市供水水质监督管理工作。 省、自治区人民政府建设主管部门负责本行政区域内的城市供水水质监督管理工作。 直辖市、市、县人民政府确定的城市供水主管部门负责本行政区域内的城市供水水质监督管理工作。 涉及生活饮用水的卫生监督管理，由县级以上人民政府建设、卫生主管部门按照《生活饮用水卫生监督管理办法》（建设部、卫生部令第53号）的规定分工负责。"},{"i":5,"n":"第五条","txt":"对在城市供水水质管理工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰或者奖励。"},{"i":6,"n":"第六条","txt":"城市供水水质监测体系由国家和地方两级城市供水水质监测网络组成。 国家城市供水水质监测网，由建设部城市供水水质监测中心和直辖市、省会城市及计划单列市等经过国家质量技术监督部门资质认定的城市供水水质监测站（以下简称国家站）组成，业务上接受国务院建设主管部门指导。建设部城市供水水质监测中心为国家城市供水水质监测网中心站，承担国务院建设主管部门委托的有关工作。 地方城市供水水质监测网（以下简称地方网），由设在直辖市、省会城市、计划单列市等的国家站和其他城市经过省级以上质量技术监督部门资质认定的城市供水水质监测站（以下简称地方站）组成，业务上接受所在地省、自治区建设主管部门或者直辖市人民政府城市供水主管部门指导。 省、自治区建设主管部门和直辖市人民政府城市供水主管部门应当根据本行政区域的特点、水质检测机构的能力和水质监测任务的需要，确定地方网中心站。"},{"i":7,"n":"第七条","txt":"城市供水单位对其供应的水的质量负责，其中，经二次供水到达用户的，二次供水的水质由二次供水管理单位负责。 城市供水水质应当符合国家有关标准的规定。"},{"i":8,"n":"第八条","txt":"城市供水原水水质应当符合生活饮用水水源水质标准。 城市供水单位应当做好原水水质检测工作。发现原水水质不符合生活饮用水水源水质标准时，应当及时采取相应措施，并报告所在地直辖市、市、县人民政府城市供水、水利、环境保护和卫生主管部门。"},{"i":9,"n":"第九条","txt":"城市供水单位所用的净水剂及与制水有关的材料等，应当符合国家有关标准。 净水剂及与制水有关的材料等实施生产许可证管理的，城市供水单位应当选用获证企业的产品。 城市供水单位所用的净水剂及与制水有关的材料等，在使用前应当按照国家有关质量标准进行检验；未经检验或者检验不合格的，不得投入使用。"},{"i":10,"n":"第十条","txt":"城市供水设备、管网应当符合保障水质安全的要求。 用于城市供水的新设备、新管网或者经改造的原有设备、管网，应当严格进行清洗消毒，经质量技术监督部门资质认定的水质检测机构检验合格后，方可投入使用。"},{"i":11,"n":"第十一条","txt":"城市供水单位应当履行以下义务： （一）编制供水安全计划并报所在地直辖市、市、县人民政府城市供水主管部门备案； （二）按照有关规定，对其管理的供水设施定期巡查和维修保养； （三）建立健全水质检测机构和检测制度，提高水质检测能力； （四）按照国家规定的检测项目、检测频率和有关标准、方法，定期检测原水、出厂水、管网水的水质； （五）做好各项检测分析资料和水质报表存档工作； （六）定期向所在地直辖市、市、县人民政府城市供水主管部门如实报告供水水质检测数据； （七）按照所在地直辖市、市、县人民政府城市供水主管部门的要求公布有关水质信息； （八）接受公众关于城市供水水质信息的查询。"},{"i":12,"n":"第十二条","txt":"城市供水单位上报的水质检测数据，应当是经质量技术监督部门资质认定的水质检测机构检测的数据。水质检测机构应当依照国家有关规定，客观、公正地出具检验结果。水质检测数据按以下程序报送： （一）城市供水单位将水质检测数据报所在地市、县人民政府城市供水主管部门审核后，报送地方网中心站汇总； （二）地方网中心站将汇总、分析后的报表和报告送省、自治区建设主管部门或者直辖市人民政府城市供水主管部门审核后，报送建设部城市供水水质监测中心； （三）建设部城市供水水质监测中心汇总、分析地方网中心站上报的报表和报告，形成水质报告，报送国务院建设主管部门。"},{"i":13,"n":"第十三条","txt":"城市供水单位从事生产和水质检测的人员，应当经专业培训合格，持证上岗；但是，仅向本单位提供用水的自建设施供水单位除外。"},{"i":14,"n":"第十四条","txt":"二次供水管理单位，应当建立水质管理制度，配备专（兼）职人员，加强水质管理，定期进行水质检测并对各类储水设施清洗消毒（每半年不得少于一次）。不具备相应水质检测能力的，应当委托经质量技术监督部门资质认定的水质检测机构进行现场检测。"},{"i":15,"n":"第十五条","txt":"国务院建设主管部门，省、自治区建设主管部门以及直辖市、市、县人民政府城市供水主管部门 [以下简称建设（城市供水）主管部门]应当建立健全城市供水水质检查和督察制度，对本规定的执行情况进行监督检查。"},{"i":16,"n":"第十六条","txt":"建设（城市供水）主管部门实施监督检查时，可以采取以下措施： （一）进入现场实施检查； （二）对供水水质进行抽样检测； （三）查阅、复制相关报表、数据、原始记录等文件和资料； （四）要求被检查的单位就有关问题做出说明； （五）纠正违反有关法律、法规和本办法规定的行为。"},{"i":17,"n":"第十七条","txt":"实施监督检查 , 不得妨碍被检查单位正常的生产经营活动。 建设（城市供水）主管部门及其工作人员对知悉的被检查单位的商业秘密负有保密义务。"},{"i":18,"n":"第十八条","txt":"建设（城市供水）主管部门依法实施监督检查，有关单位和个人不得拒绝或者阻挠。被检查单位应当接受监督检查和督察，并提供工作方便。"},{"i":19,"n":"第十九条","txt":"建设（城市供水）主管部门实施现场检查时应当做好检查记录，并在取得抽检水样检测报告十五日内，向被检查单位出具检查意见书。 发现供水水质不合格或存在安全隐患的，建设（城市供水）主管部门应当责令被检查单位限期改正。"},{"i":20,"n":"第二十条","txt":"建设（城市供水）主管部门实施监督检查，应当委托城市供水水质监测网监测站或者其他经质量技术监督部门资质认定的水质检测机构进行水质检测。"},{"i":21,"n":"第二十一条","txt":"被检查单位对监督检查结果有异议的，可以自收到监督检查意见书之日起十五日内向实施监督检查的机关申请复查。"},{"i":22,"n":"第二十二条","txt":"县级以上地方人民政府建设（城市供水）主管部门应当将监督检查情况及有关问题的处理结果，报上一级建设（城市供水）主管部门，并向社会公布城市供水水质监督检查年度报告。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人发现违反本规定行为的，有权向建设（城市供水）主管部门举报。"},{"i":24,"n":"第二十四条","txt":"建设（城市供水）主管部门应当会同有关部门制定城市供水水质突发事件应急预案，经同级人民政府批准后组织实施。 城市供水单位应当依据所在地城市供水水质突发事件应急预案，制定相应的突发事件应急预案，报所在地直辖市、市、县人民政府城市供水主管部门备案，并定期组织演练。"},{"i":25,"n":"第二十五条","txt":"城市供水水质突发事件应急预案应当包括以下内容： （一）突发事件的应急管理工作机制； （二）突发事件的监测与预警； （三）突发事件信息的收集、分析、报告、通报制度； （四）突发事件应急处理技术和监测机构及其任务； （五）突发事件的分级和应急处理工作方案； （六）突发事件预防与处理措施； （七）应急供水设施、设备及其他物资和技术的储备与调度； （八）突发事件应急处理专业队伍的建设和培训。"},{"i":26,"n":"第二十六条","txt":"任何单位和个人发现城市供水水质安全事故或者安全隐患后，应当立即向有关城市供水单位、二次供水管理单位或者所在地直辖市、市、县人民政府城市供水主管部门报告。 城市供水单位、二次供水管理单位接到安全事故或者安全隐患报告的，应当立即向所在地直辖市、市、县人民政府城市供水主管部门和其他有关部门报告。 直辖市、市、县人民政府城市供水主管部门接到安全事故或者安全隐患报告的，应当按照有关规定，向同级人民政府报告，并通知有关城市供水单位、二次供水管理单位。"},{"i":27,"n":"第二十七条","txt":"发现城市供水水质安全隐患或者安全事故后，直辖市、市、县人民政府城市供水主管部门应当会同有关部门立即启动城市供水水质突发事件应急预案，采取措施防止事故发生或者扩大，并保障有关单位和个人的用水；有关城市供水单位、二次供水管理单位应当立即组织人员查明情况，组织抢险抢修。 城市供水单位发现供水水质不能达到标准，确需停止供水的，应当报经所在地直辖市、市、县人民政府城市供水主管部门批准，并提前24小时通知用水单位和个人；因发生灾害或者紧急事故，不能提前通知的，应当在采取应急措施的同时，通知用水单位和个人，并向所在地直辖市、市、县人民政府城市供水主管部门报告。"},{"i":28,"n":"第二十八条","txt":"发生城市供水水质安全事故后，直辖市、市、县人民政府城市供水主管部门应当会同有关部门立即派员前往现场，进行调查和取证。调查取证应当全面、客观、公正。 调查期间，有关单位和个人应当予以配合，如实提供有关情况和证据，不得谎报或者隐匿、毁灭证据，阻挠、妨碍事故原因的调查和取证。"},{"i":29,"n":"第二十九条","txt":"违反本规定，有下列行为之一的，由直辖市、市、县人民政府城市供水主管部门给予警告，并处以3万元的罚款： （一）供水水质达不到国家有关标准规定的； （二）城市供水单位、二次供水管理单位未按规定进行水质检测或者委托检测的； （三）对于实施生产许可证管理的净水剂及与制水有关的材料等，选用未获证企业产品的； （四）城市供水单位使用未经检验或者检验不合格的净水剂及有关制水材料的； （五）城市供水单位使用未经检验或者检验不合格的城市供水设备、管网的； （六）二次供水管理单位，未按规定对各类储水设施进行清洗消毒的； （七）城市供水单位、二次供水管理单位隐瞒、缓报、谎报水质突发事件或者水质信息的； （八）违反本规定，有危害城市供水水质安全的其他行为的。"},{"i":30,"n":"第三十条","txt":"违反本规定，有下列行为之一的，由直辖市、市、县人民政府城市供水主管部门给予警告，并处以5000元以上2万元以下的罚款： （一）城市供水单位未制定城市供水水质突发事件应急预案的； （二）城市供水单位未按规定上报水质报表的。"},{"i":31,"n":"第三十一条","txt":"建设（城市供水）主管部门不履行本规定职责、玩忽职守、滥用职权、徇私舞弊的，对负有责任的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"因城市供水单位原因导致供水水质不符合国家有关标准，给用户造成损失的，应当依法承担赔偿责任。"},{"i":33,"n":"第三十三条","txt":"本规定自2007年5月1日起施行。《城市供水水质管理规定》（建设部令第67号）、《建设部关于修改〈城市供水水质管理规定〉的决定》（建设部令第132号令）同时废止。"}],"chengshigongceguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进社会主义精神文明建设，加强城市公厕管理，提高城市公厕卫生水平，方便群众使用，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于城市（指国家按行政建制设立的直辖市、市、镇）的公厕管理。"},{"i":3,"n":"第三条","txt":"本办法所称公厕，是指供城市居民和流动人口共同使用的厕所，包括公共建筑（如车站、码头、商店、饭店、影剧院、体育场馆、展览馆、办公楼等）附设的公厕。"},{"i":4,"n":"第四条","txt":"任何人使用城市公厕，都应当自觉维护公厕的清洁、卫生，爱护公厕的设备、设施。"},{"i":5,"n":"第五条","txt":"国务院建设行政主管部门负责全国城市公厕的监督管理。 省、自治区人民政府建设行政主管部门负责本行政区域城市公厕的监督管理。 城市人民政府环境卫生行政主管部门负责本行政区域城市公厕的监督管理。"},{"i":6,"n":"第六条","txt":"城市公厕应当按照“全面规划、合理布局、改建并重、卫生适用、方便群众、水厕为主、有利排运”的原则，进行规划建设。"},{"i":7,"n":"第七条","txt":"城市公厕规划是城市环境卫生规划的组成部分，应当由城市人民政府环境卫生行政主管部门会同城市规划行政主管部门，依照《城市公共厕所规划和设计标准》及公共建筑设计规范进行编制。"},{"i":8,"n":"第八条","txt":"下列城市公共场所应当设置公厕，并应当设立明显的标志或指路牌： （一）广场和主要交通干道两侧； （二）车站、码头、展览馆等公共建筑物附近。"},{"i":9,"n":"第九条","txt":"城市公厕应当修建在明显易找、便于粪便排放或机器抽运的地段。新修建的公厕外观应当与周围环境相协调。"},{"i":10,"n":"第十条","txt":"任何单位和个人不得擅自占用城市公厕规划用地或者改变其性质。 建设单位经批准使用的土地含有城市公厕规划用地的，建设单位应当按照城市公厕规划和城市人民政府环境卫生行政主管部门的要求修建公厕，并向社会开放使用。"},{"i":11,"n":"第十一条","txt":"城市公厕的建设和维修管理，按照下列分工，分别由城市环境卫生单位和有关单位负责： （一）城市主次干道两侧的公厕由城市人民政府环境卫生行政主管部门指定的管理单位负责； （二）城市各类集贸市场的公厕由集贸市场经营管理单位负责； （三）新建、改建居民楼群和住宅小区的公厕由其管理单位负责； （四）风景名胜、旅游点的公厕由其主管部门或经营管理单位负责； （五）公共建筑附设的公厕由产权单位负责。 本条前款第二、三、四项中的单位，可以与城市环境卫生单位商签协议，委托其代建和维修管理。"},{"i":12,"n":"第十二条","txt":"新建的公厕应当以水冲式厕所为主。对于原有不符合卫生标准的旱厕，应当逐步进行改造。"},{"i":13,"n":"第十三条","txt":"影剧院、商店、饭店、车站等公共建筑没有附设公厕或者原有公厕及其卫生设施不足的，应当按照城市人民政府环境卫生行政主管部门的要求进行新建、扩建或者改造。"},{"i":14,"n":"第十四条","txt":"公共建筑附设的公厕及其卫生设施的设计和安装，应当符合国家和地方的有关标准。"},{"i":15,"n":"第十五条","txt":"对于损坏严重或者年久失修的公厕，依照本章第十一条的规定，分别由有关单位负责改造或者重建，但在拆除重建时应当先建临时公厕。"},{"i":16,"n":"第十六条","txt":"独立设置的城市公厕竣工时，建设单位应当通知城市人民政府环境卫生行政主管部门或者其指定的部门参加验收。凡验收不合格的，不准交付使用。"},{"i":17,"n":"第十七条","txt":"城市公厕产权单位应当依照《城市建设档案管理规定》，管理好公厕档案。非单一产权的公厕，由城市人民政府环境卫生行政主管部门指定有关单位代为管理。"},{"i":18,"n":"第十八条","txt":"城市公厕的保洁工作，依照本办法第十一条的规定，分别由有关单位负责或者与城市环境卫生单位商签协议，委托代管。"},{"i":19,"n":"第十九条","txt":"城市公厕的保洁，应当逐步做到规范化、标准化，保持公厕的清洁、卫生和设备、设施完好。 城市公厕的保洁标准，由城市人民政府环境卫生行政主管部门制定。"},{"i":20,"n":"第二十条","txt":"城市人民政府环境卫生行政主管部门应当对公厕的卫生及设备、设施等进行检查，对于不符合规定的，应当予以纠正。"},{"i":21,"n":"第二十一条","txt":"在旅游景点、车站、繁华商业区等公共场所独立设置的较高档次公厕，可以适当收费。具体收费办法由省、自治区人民政府建设行政主管部门和直辖市人民政府环境卫生行政主管部门提出方案，经同级人民政府物价、财政部门批准。所收费用专项用于公厕的维修和管理。"},{"i":22,"n":"第二十二条","txt":"城市人民政府环境卫生行政主管部门，对于在城市公厕的规划、建设和管理中取得显著成绩的单位和个人，应当给予表彰和奖励。"},{"i":23,"n":"第二十三条","txt":"凡违反本办法第十条　、第十一条　、第十三条　、第十四条　、第十五条　、第十六条规定的单位和个人，城市人民政府环境卫生行政主管部门可以根据情节，给予警告，责令限期改正或者罚款。"},{"i":24,"n":"第二十四条","txt":"对于违反本办法，有下列行为之一的，城市人民政府环境卫生行政主管部门可以责令其恢复原状、赔偿损失，并处以罚款： （一）在公厕内乱丢垃圾、污物，随地吐痰，乱涂乱画的； （二）破坏公厕设施、设备的；　 （三）未经批准擅自占用或者改变公厕使用性质的。"},{"i":25,"n":"第二十五条","txt":"对于违反本办法第二十一条的规定，擅自收费或者滥收费的，由当地物价部门的物价检查机构依照《中华人民共和国价格管理条例》的有关规定进行处罚。"},{"i":26,"n":"第二十六条","txt":"对于违反本办法，同时又违反《中华人民共和国治安管理处罚法》的，由公安机关给予治安管理处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"当事人对行政处罚决定不服，可以依照《中华人民共和国行政诉讼法》的有关规定，申请行政复议或者向人民法院起诉。逾期不申请复议或者不向人民法院起诉，又不履行处罚决定的，由作出处罚决定的机关申请人民法院强制执行。"},{"i":28,"n":"第二十八条","txt":"未设镇建制的工矿区公厕管理，可以参照本办法执行。"},{"i":29,"n":"第二十九条","txt":"各省、自治区人民政府建设行政主管部门和直辖市人民政府环境卫生行政主管部门可以根据本办法制订实施细则，报同级人民政府批准发布。"},{"i":30,"n":"第三十条","txt":"本办法由建设部负责解释。"},{"i":31,"n":"第三十一条","txt":"本办法自一九九一年一月一日起施行。"}],"chengshidongwuyuanguanliguiding":[{"i":1,"n":"第一条","txt":"为加强城市动物园管理，充分发挥动物园的作用，满足人民物质和文化生活提高的需要，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于综合性动物园（水族馆）、专类性动物园、野生动物园、城市公园的动物展区、珍稀濒危动物饲养繁殖研究场所。 从事城市动物园（以下简称动物园）的规划、建设、管理和动物保护必须遵守本规定。"},{"i":3,"n":"第三条","txt":"国务院建设行政主管部门负责全国动物园管理工作。 省、自治区人民政府建设行政主管部门负责本行政区域内的动物园管理工作。 城市人民政府园林行政主管部门负责本城市的动物园管理工作。 动物园管理机构负责动物园的日常管理及动物保护工作。"},{"i":4,"n":"第四条","txt":"国家鼓励动物园积极开展珍稀濒危野生动物的科学研究和移地保护工作。"},{"i":5,"n":"第五条","txt":"动物园的规划和建设必须符合城市总体规划及城市园林和绿化规划，并进行统筹安排，协调发展。"},{"i":6,"n":"第六条","txt":"需要新建动物园的，应当对建设地点、资金、动物资源和技术条件、管理人员配备等，进行综合分析论证，提出可行性报告和计划任务书，并向城市人民政府规划行政主管部门提出申请。 城市人民政府规划行政主管部门审批前，应当征得城市人民政府园林行政主管部门同意。 城市人民政府园林行政主管部门应当对新建动物园组织论证，广泛征求社会各界意见，论证结果应当公示。"},{"i":7,"n":"第七条","txt":"动物园的规划设计应当坚持环境优美、适于动物栖息、生长和展出、保证安全、方便游人的原则，遵照城市园林绿化规划设计的有关标准规范。"},{"i":8,"n":"第八条","txt":"动物园的设计单位应当具有国家规定的设计资质，并在资质证书许可的范围内承接业务。"},{"i":9,"n":"第九条","txt":"动物园规划设计应当包括下列内容： （一）全园总体布局规划； （二）饲养动物种类、数量，展览分区方案，分期引进计划； （三）展览方式、路线规划，动物笼舍和展馆设计，游览区及设施规划设计； （四）动物医疗、隔离和动物园管理设施； （五）绿化规划设计，绿地和水面面积不应低于国家规定的标准； （六）基础设施规划设计； （七）商业、服务设施规划设计； （八）人员配制规划，建设资金概算及建设进度计划等； （九）建成后维护管理资金估算。"},{"i":10,"n":"第十条","txt":"动物笼舍和展馆设计应当遵循下列原则： （一）符合动物生活习性要求； （二）方便游览观赏； （三）保证动物、游人和饲养人员的安全； （四）饲养人员管理操作方便； （五）规定的设施齐全。"},{"i":11,"n":"第十一条","txt":"城市人民政府规划行政主管部门在动物园规划审批时，应当将动物园规划设计方案征求城市人民政府园林行政主管部门的意见。 动物园规划设计方案，应当由城市人民政府园林行政主管部门组织论证，广泛征求社会各界意见，论证结果应当公示。 动物园应当按照批准的规划设计方案进行建设。规划设计方案确需改变的，应当报经原审批部门批准。"},{"i":12,"n":"第十二条","txt":"动物园的建设必须严格按照批准的规划设计进行。动物园的施工应当由具有相应资质等级的单位承担，严格执行国家有关标准、规范，竣工后按规定验收合格方可投入使用。"},{"i":13,"n":"第十三条","txt":"任何单位和个人都不得擅自侵占动物园及其规划用地，已被占用的应当限期归还。"},{"i":14,"n":"第十四条","txt":"动物园扩大规模、增加动物种类，必须在动物资源、动物笼舍、饲料、医疗等物质条件和技术、管理人员都具备的情况下稳步进行。"},{"i":15,"n":"第十五条","txt":"动物园管理机构应当加强动物园的科学化管理，建立健全必要的职能部门，配备相应的人员，建立和完善各项规章制度。科技人员应达到规定的比例。"},{"i":16,"n":"第十六条","txt":"动物园管理机构应当严格执行建设部颁发的《动物园动物管理技术规程》标准。"},{"i":17,"n":"第十七条","txt":"动物园管理机构应当备有卫生防疫、医疗救护、麻醉保定设施，定时进行防疫和消毒。有条件的动物园要设有动物疾病检疫隔离场。"},{"i":18,"n":"第十八条","txt":"动物园管理机构应当对饲养动物加强档案管理，建立、健全饲养动物谱系。 动物园都应当设立谱系登记员，负责整理全园饲养动物的谱系资料。"},{"i":19,"n":"第十九条","txt":"动物园管理机构每年应当从事业经费中提取一定比例的资金作为科研经费，用于饲养野生动物的科学研究。"},{"i":20,"n":"第二十条","txt":"动物园管理机构应当制定野生动物科学普及教育计划，要设专人负责科普工作，利用各种方式向群众，特别是向青少年，进行宣传教育。"},{"i":21,"n":"第二十一条","txt":"动物园管理机构应当完善各项安全设施，加强安全管理，确保游人、管理人员和动物的安全。 动物园管理机构应当加强对游人的管理，严禁游人在动物展区内惊扰动物和大声喧哗，闭园后禁止在动物展区进行干扰动物的各种活动。"},{"i":22,"n":"第二十二条","txt":"动物园管理机构应当加强园容和环境卫生的管理，完善环卫设施，妥善处理垃圾、排泄物和废弃物，防止污染环境。"},{"i":23,"n":"第二十三条","txt":"动物园管理机构应当加强绿地的美化和管理，搞好绿地和园林植物的维护。"},{"i":24,"n":"第二十四条","txt":"动物园内的服务设施的设置应当符合动物园规划设计方案。 任何单位和个人不得擅自在动物园内摆摊设点。"},{"i":25,"n":"第二十五条","txt":"动物园管理机构应当制定野生动物种群发展计划。动物园间应当密切配合和协作，共同做好濒危物种的保护繁育研究工作。有条件的动物园应当建立繁育研究基地。"},{"i":26,"n":"第二十六条","txt":"国家重点保护的野生动物因自然或人为灾害受到威胁时，动物园管理机构有责任进行保护和拯救。"},{"i":27,"n":"第二十七条","txt":"动物园与国外进行“濒危野生动植物种进出口国际贸易公约”附录Ⅰ、Ⅱ野生动物的交换、展览、赠送等，涉及进出口边境口岸的，经国务院建设行政主管部门审核同意后，报国务院野生动物行政主管部门批准，并取得国家濒危物种进出口管理机构核发的允许进出口证明书。大熊猫的进出口需报国务院批准。"},{"i":28,"n":"第二十八条","txt":"对在动物园建设、管理和野生动物特别是珍稀濒危野生动物的保护和科学普及教育中作出显著成绩的单位和个人，应当给予表彰或奖励。"},{"i":29,"n":"第二十九条","txt":"有下列行为之一的，按照有关规定处罚： （一）未取得设计、施工资质证书或者超越资质证书许可的范围承担动物园设计或施工的； （二）违反批准的规划设计方案进行动物园建设的； （三）未经批准擅自改变动物园规划设计方案的； （四）擅自侵占动物园及其规划用地的。"},{"i":30,"n":"第三十条","txt":"擅自在动物园内摆摊设点的，由城市人民政府园林行政主管部门责令限期改正，可以并处1000元以下的罚款；造成损失的，应当承担赔偿责任。"},{"i":31,"n":"第三十一条","txt":"违反本规定同时违反《中华人民共和国治安管理处罚法》的，由公安机关予以处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"城市园林行政主管部门或动物园管理机构的工作人员玩忽职守、滥用职权、徇私舞弊的，由其所在单位或上级主管部门给予行政处分；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市人民政府建设行政主管部门可以依照本规定制定实施细则。"},{"i":34,"n":"第三十四条","txt":"本规定由建设部负责解释。"},{"i":35,"n":"第三十五条","txt":"本规定自1994年9月1日起施行。"}],"chengshiweixianfangwuguanliguiding":[{"i":1,"n":"第一条","txt":"为加强城市危险房屋管理，保障居住和使用安全，促进房屋有效利用，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于城市（指直辖市、市、建制镇，下同）内各种所有制的房屋。 本规定所称危险房屋，系指结构已严重损坏或承重构件已属危险构件，随时有可能丧失结构稳定和承载能力，不能保证居住和使用安全的房屋。"},{"i":3,"n":"第三条","txt":"房屋所有人、使用人，均应遵守本规定。"},{"i":4,"n":"第四条","txt":"房屋所有人和使用人，应当爱护和正确使用房屋。"},{"i":5,"n":"第五条","txt":"建设部负责全国的城市危险房屋管理工作。 县级以上地方人民政府房地产行政主管部门负责本辖区的城市危险房屋管理工作。"},{"i":6,"n":"第六条","txt":"市、县人民政府房地产行政主管部门应设立房屋安全鉴定机构（以下简称鉴定机构），负责房屋的安全鉴定，并统一启用“房屋安全鉴定专用章”。"},{"i":7,"n":"第七条","txt":"房屋所有人或使用人向当地鉴定机构提供鉴定申请时，必须持有证明其具备相关民事权利的合法证件。 鉴定机构接到鉴定申请后，应及时进行鉴定。"},{"i":8,"n":"第八条","txt":"鉴定机构进行房屋安全鉴定应按下列程序进行： （一）受理申请； （二）初始调查，摸清房屋的历史和现状； （三）现场查勘、测试、记录各种损坏数据和状况； （四）检测验算，整理技术资料； （五）全面分析，论证定性，作出综合判断，提出处理建议； （六）签发鉴定文书。"},{"i":9,"n":"第九条","txt":"对被鉴定为危险房屋的，一般可分为以下四类进行处理： （一）观察使用。适用于采取适当安全技术措施后，尚能短期使用，但需继续观察的房屋。 （二）处理使用。适用于采取适当技术措施后，可解除危险的房屋。 （三）停止使用。适用于已无修缮价值，暂时不便拆除，又不危及相邻建筑和影响他人安全的房屋。 （四）整体拆除。适用于整幢危险且无修缮价值，需立即拆除的房屋。"},{"i":10,"n":"第十条","txt":"进行安全鉴定，必须有两名以上鉴定人员参加。对特殊复杂的鉴定项目，鉴定机构可另外聘请专业人员或邀请有关部门派员参与鉴定。"},{"i":11,"n":"第十一条","txt":"房屋安全鉴定应使用统一术语，填写鉴定文书，提出处理意见。 经鉴定属危险房屋的，鉴定机构必须及时发出危险房屋通知书；属于非危险房屋的，应在鉴定文书上注明在正常使用条件下的有效时限，一般不超过一年。"},{"i":12,"n":"第十二条","txt":"房屋经安全鉴定后，鉴定机构可以收取鉴定费。鉴定费的收取标准，可根据当地情况，由鉴定机构提出，经市、县人民政府房地产行政主管部门会同物价部门批准后执行。 房屋所有人和使用人都可提出鉴定申请；经鉴定为危险房屋的，鉴定费由所有人承担；经鉴定为非危险房屋的，鉴定费由申请人承担。"},{"i":13,"n":"第十三条","txt":"受理涉及危险房屋纠纷案件的仲裁或审判机关，可指定纠纷案件的当事人申请房屋安全鉴定；必要时，亦可直接提出房屋安全鉴定的要求。"},{"i":14,"n":"第十四条","txt":"鉴定危险房屋执行部颁《危险房屋鉴定标准》（CJ13—86）。对工业建筑、公共建筑、高层建筑及文物保护建筑等的鉴定，还应参照有关专业技术标准、规范和规程进行。"},{"i":15,"n":"第十五条","txt":"房屋所有人应定期对其房屋进行安全检查。在暴风、雨雪季节，房屋所有人应做好排险解危的各项准备；市、县人民政府房地产行政主管部门要加强监督检查，并在当地政府统一领导下，做好抢险救灾工作。"},{"i":16,"n":"第十六条","txt":"房屋所有人对危险房屋能解危的，要及时解危；解危暂时有困难的，应采取安全措施。"},{"i":17,"n":"第十七条","txt":"房屋所有人对经鉴定的危险房屋，必须按照鉴定机构的处理建议，及时加固或修缮治理；如房屋所有人拒不按照处理建议修缮治理，或使用人有阻碍行为的，房地产行政主管部门有权指定有关部门代修，或采取其它强制措施。发生的费用由责任人承担。"},{"i":18,"n":"第十八条","txt":"房屋所有人进行抢险解危需要办理各项手续时，各有关部门应给予支持，及时办理，以免延误时间发生事故。"},{"i":19,"n":"第十九条","txt":"治理私有危险房屋，房屋所有人确有经济困难无力治理时，其所在单位可给予借贷；如系出租房屋，可以和承租人合资治理，承租人付出的修缮费用可以折抵租金或由出租人分期偿还。"},{"i":20,"n":"第二十条","txt":"经鉴定机构鉴定为危险房屋，并需要拆除重建时，有关部门应酌情给予政策优惠。"},{"i":21,"n":"第二十一条","txt":"异产毗连危险房屋的各所有人，应按照国家对异产毗连房屋的有关规定，共同履行治理责任。拒不承担责任的，由房屋所在地房地产行政主管部门调处；当事人不服的，可向当地人民法院起诉。"},{"i":22,"n":"第二十二条","txt":"因下列原因造成事故的，房屋所有人应承担民事或行政责任： （一）有险不查或损坏不修； （二）经鉴定机构鉴定为危险房屋而未采取有效的解危措施。"},{"i":23,"n":"第二十三条","txt":"因下列原因造成事故的，使用人、行为人应承担民事责任： （一）使用人擅自改变房屋结构、构件、设备或使用性质； （二）使用人阻碍房屋所有人对危险房屋采取解危措施； （三）行为人由于施工、堆物、碰撞等行为危及房屋。"},{"i":24,"n":"第二十四条","txt":"有下列情况的，鉴定机构应承担民事或行政责任： （一）因故意把非危险房屋鉴定为危险房屋而造成损失； （二）因过失把危险房屋鉴定为非危险房屋，并在有效时限内发生事故； （三）因拖延鉴定时间而发生事故。"},{"i":25,"n":"第二十五条","txt":"有本章第二十二、二十三、二十四条所列行为，给他人造成生命财产损失，已构成犯罪的，由司法机关依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"县级以上地方人民政府房地产行政主管部门可依据本规定，结合当地情况，制定实施细则，经同级人民政府批准后，报上一级主管部门备案。"},{"i":27,"n":"第二十七条","txt":"未设镇建制的工矿区可参照本规定执行。"},{"i":28,"n":"第二十八条","txt":"本规定由建设部负责解释。"},{"i":29,"n":"第二十九条","txt":"本规定自一九九○年一月一日起施行。"}],"chengshishangpinfangyushouguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强商品房预售管理，维护商品房交易双方的合法权益，根据《中华人民共和国城市房地产管理法》、《城市房地产开发经营管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称商品房预售是指房地产开发企业（以下简称开发企业）将正在建设中的房屋预先出售给承购人，由承购人支付定金或房价款的行为。"},{"i":3,"n":"第三条","txt":"本办法适用于城市商品房预售的管理。"},{"i":4,"n":"第四条","txt":"国务院建设行政主管部门归口管理全国城市商品房预售管理； 省、自治区建设行政主管部门归口管理本行政区域内城市商品房预售管理； 市、县人民政府建设行政主管部门或房地产行政主管部门（以下简称房地产管理部门）负责本行政区域内城市商品房预售管理。"},{"i":5,"n":"第五条","txt":"商品房预售应当符合下列条件： （一）已交付全部土地使用权出让金，取得土地使用权证书； （二）持有建设工程规划许可证和施工许可证； （三）按提供预售的商品房计算，投入开发建设的资金达到工程建设总投资的25％以上，并已经确定施工进度和竣工交付日期。"},{"i":6,"n":"第六条","txt":"商品房预售实行许可制度。开发企业进行商品房预售，应当向房地产管理部门申请预售许可，取得《商品房预售许可证》。 未取得《商品房预售许可证》的，不得进行商品房预售。"},{"i":7,"n":"第七条","txt":"开发企业申请预售许可，应当提交下列证件（复印件）及资料： （一）商品房预售许可申请表； （二）开发企业的《营业执照》和资质证书； （三）土地使用权证、建设工程规划许可证、施工许可证； （四）投入开发建设的资金占工程建设总投资的比例符合规定条件的证明； （五）工程施工合同及关于施工进度的说明； （六）商品房预售方案。预售方案应当说明预售商品房的位置、面积、竣工交付日期等内容，并应当附预售商品房分层平面图。"},{"i":8,"n":"第八条","txt":"商品房预售许可依下列程序办理： （一）受理。开发企业按本办法第七条的规定提交有关材料，材料齐全的，房地产管理部门应当当场出具受理通知书；材料不齐的，应当当场或者5日内一次性书面告知需要补充的材料。 （二）审核。房地产管理部门对开发企业提供的有关材料是否符合法定条件进行审核。 开发企业对所提交材料实质内容的真实性负责。 （三）许可。经审查，开发企业的申请符合法定条件的，房地产管理部门应当在受理之日起10日内，依法作出准予预售的行政许可书面决定，发送开发企业，并自作出决定之日起10日内向开发企业颁发、送达《商品房预售许可证》。 经审查，开发企业的申请不符合法定条件的，房地产管理部门应当在受理之日起10日内，依法作出不予许可的书面决定。书面决定应当说明理由，告知开发企业享有依法申请行政复议或者提起行政诉讼的权利，并送达开发企业。 商品房预售许可决定书、不予商品房预售许可决定书应当加盖房地产管"},{"i":9,"n":"第九条","txt":"开发企业进行商品房预售，应当向承购人出示《商品房预售许可证》。售楼广告和说明书应当载明《商品房预售许可证》的批准文号。"},{"i":10,"n":"第十条","txt":"商品房预售，开发企业应当与承购人签订商品房预售合同。开发企业应当自签约之日起30日内，向房地产管理部门和市、县人民政府土地管理部门办理商品房预售合同登记备案手续。 房地产管理部门应当积极应用网络信息技术，逐步推行商品房预售合同网上登记备案。 商品房预售合同登记备案手续可以委托代理人办理。委托代理人办理的，应当有书面委托书。"},{"i":11,"n":"第十一条","txt":"开发企业预售商品房所得款项应当用于有关的工程建设。 商品房预售款监管的具体办法，由房地产管理部门制定。"},{"i":12,"n":"第十二条","txt":"预售的商品房交付使用之日起90日内，承购人应当依法到房地产管理部门和市、县人民政府土地管理部门办理权属登记手续。开发企业应当予以协助，并提供必要的证明文件。 由于开发企业的原因，承购人未能在房屋交付使用之日起90日内取得房屋权属证书的，除开发企业和承购人有特殊约定外，开发企业应当承担违约责任。"},{"i":13,"n":"第十三条","txt":"开发企业未取得《商品房预售许可证》预售商品房的，依照《城市房地产开发经营管理条例》第三十九条的规定处罚。"},{"i":14,"n":"第十四条","txt":"开发企业不按规定使用商品房预售款项的，由房地产管理部门责令限期纠正，并可处以违法所得３倍以下但不超过３万元的罚款。"},{"i":15,"n":"第十五条","txt":"开发企业隐瞒有关情况、提供虚假材料，或者采用欺骗、贿赂等不正当手段取得商品房预售许可的，由房地产管理部门责令停止预售，撤销商品房预售许可，并处3万元罚款。"},{"i":16,"n":"第十六条","txt":"省、自治区建设行政主管部门、直辖市建设行政主管部门或房地产行政管理部门可以根据本办法制定实施细则。"},{"i":17,"n":"第十七条","txt":"本办法由国务院建设行政主管部门负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自1995年1月1日起施行。 附件：商品房预售许可证"}],"chengshiguoyoutudishiyongquanchurangzhuanrangguihue2af4b":[{"i":1,"n":"第一条","txt":"为了加强城市国有土地使用权出让、转让的规划管理，保证城市规划实施，科学、合理利用城市土地，根据《中华人民共和国城乡规划法》、《中华人民共和国土地管理法》、《中华人民共和国城镇国有土地使用权出让和转让暂行条例》和《外商投资开发经营成片土地暂行管理办法》等制定本办法。"},{"i":2,"n":"第二条","txt":"在城市规划区内城市国有土地使用权出让、转让必须符合城市规划，有利于城市经济社会的发展，并遵守本办法。"},{"i":3,"n":"第三条","txt":"国务院城市规划行政主管部门负责全国城市国有土地使用权出让、转让规划管理的指导工作。 省、自治区、直辖市人民政府城市规划行政主管部门负责本省、自治区、直辖市行政区域内城市国有土地使用权出让、转让规划管理的指导工作。 直辖市、市和县人民政府城市规划行政主管部门负责城市规划区内城市国有土地使用权出让、转让的规划管理工作。"},{"i":4,"n":"第四条","txt":"城市国有土地使用权出让的投放量应当与城市土地资源、经济社会发展和市场需求相适应。土地使用权出让、转让应当与建设项目相结合。城市规划行政主管部门和有关部门要根据城市规划实施的步骤和要求，编制城市国有土地使用权出让规划和计划，包括地块数量、用地面积、地块位置、出让步骤等，保证城市国有土地使用权的出让有规划、有步骤、有计划地进行。"},{"i":5,"n":"第五条","txt":"出让城市国有土地使用权，出让前应当制定控制性详细规划。 出让的地块，必须具有城市规划行政主管部门提出的规划设计条件及附图。"},{"i":6,"n":"第六条","txt":"规划设计条件应当包括：地块面积，土地使用性质，容积率，建筑密度，建筑高度，停车泊位，主要出入口，绿地比例，须配置的公共设施、工程设施，建筑界线，开发期限以及其他要求。 附图应当包括：地块区位和现状，地块座标、标高，道路红线座标、标高，出入口位置，建筑界线以及地块周围地区环境与基础设施条件。"},{"i":7,"n":"第七条","txt":"城市国有土地使用权出让、转让合同必须附具规划设计条件及附图。 规划设计条件及附图，出让方和受让方不得擅自变更。在出让、转让过程中确需变更的，必须经城市规划行政主管部门批准。"},{"i":8,"n":"第八条","txt":"城市用地分等定级应当根据城市各地段的现状和规划要求等因素确定。土地出让金的测算应当把出让地块的规划设计条件作为重要依据之一。在城市政府的统一组织下，城市规划行政主管部门应当和有关部门进行城市用地分等定级和土地出让金的测算。"},{"i":9,"n":"第九条","txt":"已取得土地出让合同的，受让方应当持出让合同依法向城市规划行政主管部门申请建设用地规划许可证。在取得建设用地规划许可证后，方可办理土地使用权属证明。"},{"i":10,"n":"第十条","txt":"通过出让获得的土地使用权再转让时，受让方应当遵守原出让合同附具的规划设计条件，并由受让方向城市规划行政主管部门办理登记手续。 受让方如需改变原规划设计条件，应当先经城市规划行政主管部门批准。"},{"i":11,"n":"第十一条","txt":"受让方在符合规划设计条件外为公众提供公共使用空间或设施的，经城市规划行政主管部门批准后，可给予适当提高容积率的补偿。 受让方经城市规划行政主管部门批准变更规划设计条件而获得的收益，应当按规定比例上交城市政府。"},{"i":12,"n":"第十二条","txt":"城市规划行政主管部门有权对城市国有土地使用权出让、转让过程是否符合城市规划进行监督检查。"},{"i":13,"n":"第十三条","txt":"凡持未附具城市规划行政主管部门提供规划设计条件及附图的出让、转让合同，或擅自变更的，城市规划行政主管部门不予办理建设用地规划许可证。 凡未取得或擅自变更建设用地规划许可证而办理土地使用权属证明的，土地权属证明无效。"},{"i":14,"n":"第十四条","txt":"各级人民政府城市规划行政主管部门，应当对本行政区域内的城市国有土地使用权出让、转让规划管理情况逐项登记，定期汇总。"},{"i":15,"n":"第十五条","txt":"城市规划行政主管部门应当深化城市土地利用规划，加强规划管理工作。城市规划行政主管部门必须提高办事效率，对申领规划设计条件及附图、建设用地规划许可证的，应当在规定的期限内完成。"},{"i":16,"n":"第十六条","txt":"各省、自治区、直辖市城市规划行政主管部门可以根据本办法制定实施细则，报当地人民政府批准后执行。"},{"i":17,"n":"第十七条","txt":"本办法由建设部负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自1993年1月1日起施行。"}],"chengshidixiakongjiankaifaliyongguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对城市地下空间开发利用的管理，合理开发城市地下空间资源，适应城市现代化和城市可持续发展建设的需要，依据《中华人民共和国城乡规划法》及有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"编制城市地下空间规划，对城市规划区范围内的地下空间进行开发利用，必须遵守本规定。 本规定所称的城市地下空间，是指城市规划区内地表以下的空间。"},{"i":3,"n":"第三条","txt":"城市地下空间的开发利用应贯彻统一规划、综合开发、合理利用、依法管理的原则，坚持社会效益、经济效益和环境效益相结合，考虑防灾和人民防空等需要。"},{"i":4,"n":"第四条","txt":"国务院建设行政主管部门负责全国城市地下空间的开发利用管理工作。 省、自治区人民政府建设行政主管部门负责本行政区域内城市地下空间的开发利用管理工作。 直辖市、市、县人民政府建设行政主管部门和城市规划行政主管部门按照职责分工，负责本行政区域内城市地下空间的开发利用管理工作。"},{"i":5,"n":"第五条","txt":"城市地下空间规划是城市规划的重要组成部分。各级人民政府在组织编制城市总体规划时，应根据城市发展的需要，编制城市地下空间开发利用规划。 各级人民政府在编制城市详细规划时，应当依据城市地下空间开发利用规划对城市地下空间开发利用作出具体规定。"},{"i":6,"n":"第六条","txt":"城市地下空间开发利用规划的主要内容包括：地下空间现状及发展预测，地下空间开发战略，开发层次、内容、期限，规模与布局，以及地下空间开发实施步骤等。"},{"i":7,"n":"第七条","txt":"城市地下空间的规划编制应注意保护和改善城市的生态环境，科学预测城市发展的需要，坚持因地制宜，远近兼顾，全面规划，分步实施，使城市地下空间的开发利用同国家和地方的经济技术发展水平相适应。城市地下空间规划应实行竖向分层立体综合开发，横向相关空间互相连通，地面建筑与地下工程协调配合。"},{"i":8,"n":"第八条","txt":"编制城市地下空间规划必备的城市勘察、测量、水文、地质等资料应当符合国家有关规定。承担编制任务的单位，应当符合国家规定的资质要求。"},{"i":9,"n":"第九条","txt":"城市地下空间规划作为城市规划的组成部分，依据《中华人民共和国城乡规划法》的规定进行审批和调整。"},{"i":10,"n":"第十条","txt":"城市地下空间的工程建设必须符合城市地下空间规划，服从规划管理。"},{"i":11,"n":"第十一条","txt":"附着地面建筑进行地下工程建设，应随地面建筑一并向城市规划行政主管部门申请办理选址意见书、建设用地规划许可证、建设工程规划许可证。"},{"i":12,"n":"第十二条","txt":"独立开发的地下交通、商业、仓储、能源、通讯、管线、人防工程等设施，应持有关批准文件、技术资料，依据《中华人民共和国城乡规划法》的有关规定，向城市规划行政主管部门申请办理选址意见书、建设用地规划许可证、建设工程规划许可证。"},{"i":13,"n":"第十三条","txt":"建设单位或者个人在取得建设工程规划许可证和其他有关批准文件后，方可向建设行政主管部门申请办理建设工程施工许可证。"},{"i":14,"n":"第十四条","txt":"地下工程建设应符合国家有关规定、标准和规范。"},{"i":15,"n":"第十五条","txt":"地下工程的勘察设计，应由具备相应资质的勘察设计单位承担。"},{"i":16,"n":"第十六条","txt":"地下工程设计应满足地下空间对环境、安全和设施运行、维护等方面的使用要求，使用功能与出入口设计应与地面建设相协调。"},{"i":17,"n":"第十七条","txt":"地下工程的设计文件应当按照国家有关规定进行设计审查。"},{"i":18,"n":"第十八条","txt":"地下工程的施工应由具备相应资质的施工单位承担，确保工程质量。"},{"i":19,"n":"第十九条","txt":"地下工程必须按照设计图纸进行施工。施工单位认为有必要改变设计方案的，应由原设计单位进行修改，建设单位应重新办理审批手续。"},{"i":20,"n":"第二十条","txt":"地下工程的施工，应尽量避免因施工干扰城市正常的交通和生活秩序，不得破坏现有建筑物，对临时损坏的地表地貌应及时恢复。"},{"i":21,"n":"第二十一条","txt":"地下工程施工应当推行工程监理制度。"},{"i":22,"n":"第二十二条","txt":"地下工程的专用设备、器材的定型、生产应当执行国家统一标准。"},{"i":23,"n":"第二十三条","txt":"地下工程竣工后，建设单位应当组织设计、施工、工程监理等有关单位进行竣工验收，经验收合格的方可交付使用。 建设单位应当自竣工验收合格之日起15日内，将建设工程竣工验收报告和规划、公安消防、环保等部门出具的认可文件或者准许使用文件报建设行政主管部门或者其他有关部门备案，并及时向建设行政主管部门或者其他有关部门移交建设项目档案。"},{"i":24,"n":"第二十四条","txt":"城市地下工程由开发利用的建设单位或者使用单位进行管理，并接受建设行政主管部门的监督检查。"},{"i":25,"n":"第二十五条","txt":"地下工程应本着“谁投资、谁所有、谁受益、谁维护”的原则，允许建设单位对其投资开发建设的地下工程自营或者依法进行转让、租赁。"},{"i":26,"n":"第二十六条","txt":"建设单位或者使用单位应加强地下空间开发利用工程的使用管理，做好工程的维护管理和设施维修、更新，并建立健全维护管理制度和工程维修档案，确保工程、设备处于良好状态。"},{"i":27,"n":"第二十七条","txt":"建设单位或者使用单位应当建立健全地下工程的使用安全责任制度，采取可行的措施，防范发生火灾、水灾、爆炸及危害人身健康的各种污染。"},{"i":28,"n":"第二十八条","txt":"建设单位或者使用单位在使用或者装饰装修中不得擅自改变地下工程的结构设计；需改变原结构设计的，应当由具备相应资质的设计单位设计，并按照规定重新办理审批手续。"},{"i":29,"n":"第二十九条","txt":"平战结合的地下工程，平时由建设或者使用单位进行管理，并应保证战时能迅速提供有关部门和单位使用。"},{"i":30,"n":"第三十条","txt":"进行城市地下空间的开发建设，违反城市地下空间的规划及法定实施管理程序规定的，由县级以上人民政府城市规划行政主管部门依法处罚。"},{"i":31,"n":"第三十一条","txt":"有下列行为之一的，县级以上人民政府建设行政主管部门根据有关法律、法规处罚。 （一）未领取建设工程施工许可证擅自开工，进行地下工程建设的； （二）设计文件未按照规定进行设计审查，擅自施工的； （三）不按照工程设计图纸进行施工的； （四）在使用或者装饰装修中擅自改变地下工程结构设计的； （五）地下工程的专用设备、器材的定型、生产未执行国家统一标准的。"},{"i":32,"n":"第三十二条","txt":"在城市地下空间的开发利用管理工作中，建设行政主管部门和城市规划行政主管部门工作人员玩忽职守、滥用职权、徇私舞弊，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"省、自治区人民政府建设行政主管部门、直辖市人民政府建设行政主管部门和城市规划行政主管部门可根据本规定制定实施办法。"},{"i":34,"n":"第三十四条","txt":"本规定由国务院建设行政主管部门负责解释。"},{"i":35,"n":"第三十五条","txt":"本规定自1997年12月1日起施行。"}],"chengshidixiaguanxiangongchengdanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强城市地下管线工程档案的管理，根据《中华人民共和国城乡规划法》、《中华人民共和国档案法》、《建设工程质量管理条例》等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于城市规划区内地下管线工程档案的管理。 本办法所称城市地下管线工程，是指城市新建、扩建、改建的各类地下管线（含城市供水、排水、燃气、热力、电力、电信、工业等的地下管线）及相关的人防、地铁等工程。"},{"i":3,"n":"第三条","txt":"国务院建设主管部门对全国城市地下管线工程档案管理工作实施指导、监督。  省、自治区人民政府建设主管部门负责本行政区域内城市地下管线工程档案的管理工作，并接受国务院建设主管部门的指导、监督。 县级以上城市人民政府建设主管部门或者规划主管部门负责本行政区域内城市地下管线工程档案的管理工作，并接受上一级建设主管部门的指导、监督。 城市地下管线工程档案的收集、保管、利用等具体工作，由城建档案馆或者城建档案室（以下简称城建档案管理机构）负责。 各级城建档案管理机构同时接受同级档案行政管理部门的业务指导、监督。"},{"i":4,"n":"第四条","txt":"建设单位在申请领取建设工程规划许可证前，应当到城建档案管理机构查询施工地段的地下管线工程档案，取得该施工地段地下管线现状资料。"},{"i":5,"n":"第五条","txt":"建设单位在申请领取建设工程规划许可证时，应当向规划主管部门报送地下管线现状资料。"},{"i":6,"n":"第六条","txt":"在建设单位办理地下管线工程施工许可手续时，城建档案管理机构应当将工程竣工后需移交的工程档案内容和要求告知建设单位。"},{"i":7,"n":"第七条","txt":"施工单位在地下管线工程施工前应当取得施工地段地下管线现状资料；施工中发现未建档的管线，应当及时通过建设单位向当地县级以上人民政府建设主管部门或者规划主管部门报告。 建设主管部门、规划主管部门接到报告后，应当查明未建档的管线性质、权属，责令地下管线产权单位测定其坐标、标高及走向，地下管线产权单位应当及时将测量的材料向城建档案管理机构报送。"},{"i":8,"n":"第八条","txt":"地下管线工程覆土前，建设单位应当委托具有相应资质的工程测量单位，按照《城市地下管线探测技术规程》（CJJ61）进行竣工测量，形成准确的竣工测量数据文件和管线工程测量图。"},{"i":9,"n":"第九条","txt":"城建档案管理机构应当按照建设工程竣工联合验收的规定对地下管线工程档案进行验收。"},{"i":10,"n":"第十条","txt":"建设单位在地下管线工程竣工验收备案前，应当向城建档案管理机构移交下列档案资料： （一）地下管线工程项目准备阶段文件、监理文件、施工文件、竣工验收文件和竣工图； （二）地下管线竣工测量成果； （三）其他应当归档的文件资料（电子文件、工程照片、录像等）。 城市供水、排水、燃气、热力、电力、电讯等地下管线专业管理单位（以下简称地下管线专业管理单位）应当及时向城建档案管理机构移交地下专业管线图。"},{"i":11,"n":"第十一条","txt":"建设单位向城建档案管理机构移交的档案资料应当符合《建设工程文件归档整理规范》（GB/T50328）的要求。"},{"i":12,"n":"第十二条","txt":"地下管线专业管理单位应当将更改、报废、漏测部分的地下管线工程档案，及时修改补充到本单位的地下管线专业图上，并将修改补充的地下管线专业图及有关资料向城建档案管理机构移交。"},{"i":13,"n":"第十三条","txt":"工程测量单位应当及时向城建档案管理机构移交有关地下管线工程的1：500城市地形图和控制成果。 对于工程测量单位移交的城市地形图和控制成果，城建档案管理机构不得出售、转让。"},{"i":14,"n":"第十四条","txt":"城建档案管理机构应当绘制城市地下管线综合图，建立城市地下管线信息系统，并及时接收普查和补测、补绘所形成的地下管线成果。 城建档案管理机构应当依据地下管线专业图等有关的地下管线工程档案资料和工程测量单位移交的城市地形图和控制成果，及时修改城市地下管线综合图，并输入城市地下管线信息系统。"},{"i":15,"n":"第十五条","txt":"城建档案管理机构应当建立、健全科学的管理制度，依法做好地下管线工程档案的接收、整理、鉴定、统计、保管、利用和保密工作。"},{"i":16,"n":"第十六条","txt":"城建档案管理机构应当建立地下管线工程档案资料的使用制度，积极开发地下管线工程档案资源，为城市规划、建设和管理提供服务。"},{"i":17,"n":"第十七条","txt":"建设单位违反本办法规定，未移交地下管线工程档案的，由建设主管部门责令改正，处1万元以上10万元以下的罚款；对单位直接负责的主管人员和其他直接责任人员，处单位罚款数额5％以上10％以下的罚款；因建设单位未移交地下管线工程档案，造成施工单位在施工中损坏地下管线的，建设单位依法承担相应的责任。"},{"i":18,"n":"第十八条","txt":"地下管线专业管理单位违反本办法规定，未移交地下管线工程档案的，由建设主管部门责令改正，处1万元以下的罚款；因地下管线专业管理单位未移交地下管线工程档案，造成施工单位在施工中损坏地下管线的，地下管线专业管理单位依法承担相应的责任。"},{"i":19,"n":"第十九条","txt":"建设单位和施工单位未按照规定查询和取得施工地段的地下管线资料而擅自组织施工，损坏地下管线给他人造成损失的，依法承担赔偿责任。"},{"i":20,"n":"第二十条","txt":"工程测量单位未按照规定提供准确的地下管线测量成果，致使施工时损坏地下管线给他人造成损失的，依法承担赔偿责任。"},{"i":21,"n":"第二十一条","txt":"城建档案管理机构因保管不善，致使档案丢失，或者因汇总管线信息资料错误致使在施工中造成损失的，依法承担赔偿责任；对有关责任人员，依法给予行政处分。"},{"i":22,"n":"第二十二条","txt":"本办法自2005年5月1日起施行。"}],"chengshijuminzhuzhaianquanfangfansheshijiansheguan25a314":[{"i":1,"n":"第一条","txt":"为加强城市居民住宅安全防范设施的建设和管理，提高居民住宅安全防范功能，保护居民人身财产安全，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事城市居民住宅安全防范设施的建设和管理，应当遵守本规定。"},{"i":3,"n":"第三条","txt":"本规定所称城市，是指国家按行政建制设立的直辖市、市、镇。 本规定所称居民住宅安全防范设施，是指附属于住宅建筑主体并具有安全防范功能的防盗门、防盗锁、防踹板、防护墙、监控和报警装置，以及居民住宅或住宅区内附设的治安值班室。"},{"i":4,"n":"第四条","txt":"城市居民住宅安全防范设施，必须具备防撬、防踹、防攀缘、防跨越、防爬入等安全防范功能。"},{"i":5,"n":"第五条","txt":"城市居民住宅安全防范设施的建设，应当遵循下列原则： （一）适用、安全、经济、美观； （二）符合消防法规、技术规范、标准的要求和城市容貌规定； （三）符合当地居民习俗； （四）因地制宜。"},{"i":6,"n":"第六条","txt":"城市居民住宅安全防范设施的建设，应当纳入住宅建设规划，并同时设计、同时施工、同时投入使用。"},{"i":7,"n":"第七条","txt":"设计单位应当依据与住宅安全防范设施建设有关的规范、标准、规定进行设计。"},{"i":8,"n":"第八条","txt":"建设行政主管部门组织审批的有关住宅建筑设计文件应当包括城市居民住宅安全防范设施部分。对不符合安全防范设施规范、标准、规定的设计文件，应责成原设计单位修改。"},{"i":9,"n":"第九条","txt":"施工单位应当严格按照安全防范设计要求进行施工，不得擅自改动。必须修改的，应当由原设计单位出具变更设计通知书及相应的图纸并报设计审批部门重新审批后方可进行。"},{"i":10,"n":"第十条","txt":"城市居民住宅安全防范设施所用产品、设备和材料，必须是符合有关标准规定并经鉴定合格的产品。未经鉴定和不合格的产品不得采用。"},{"i":11,"n":"第十一条","txt":"城市居民住宅竣工后，工程质量监督部门和住宅管理单位必须按规定对安全防范设施进行验收，不合格的不得交付使用。"},{"i":12,"n":"第十二条","txt":"城市居民住宅安全防范设施建设所需费用，由产权人或使用人承担。"},{"i":13,"n":"第十三条","txt":"城市居民住宅安全防范设施的管理，由具体管理住宅的单位实施。 公安机关负责城市居民住宅安全防范设施管理的监督检查。"},{"i":14,"n":"第十四条","txt":"居民住宅区的防护墙、治安值班室等公共安全防范设施应由产权人和使用人妥善使用与保护，不得破坏或挪作他用。"},{"i":15,"n":"第十五条","txt":"公民和单位有责任保护居民住宅安全防范设施，对破坏居民住宅安全防范设施的行为有权向公安机关举报。"},{"i":16,"n":"第十六条","txt":"违反本规定，有下列行为之一的，由城市人民政府建设行政主管部门责令增补、修改、停工、返工、恢复原状，或采取其他补救措施，并可处以罚款： （一）未按有关规范、标准、规定进行设计的； （二）擅自改动设计文件中安全防范设施内容的； （三）使用未经鉴定和鉴定不合格的产品、材料、设备的； （四）安全防范设施未经验收或验收不合格而交付使用的。 有（三）、（四）行为之一，造成经济损失的，由责任者负责赔偿损失。"},{"i":17,"n":"第十七条","txt":"违反本规定，破坏居民住宅安全防范设施，由公安机关责令其改正、恢复原状，并可依据《治安管理处罚条例》的规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"本规定由建设部、公安部负责解释。"},{"i":19,"n":"第十九条","txt":"省、自治区、直辖市人民政府建设行政主管部门、公安行政主管部门，要根据本规定制定实施细则。"},{"i":20,"n":"第二十条","txt":"本规定自1996年2月1日起施行。"}],"chengshijianzhulajiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对城市建筑垃圾的管理，保障城市市容和环境卫生，根据《中华人民共和国固体废物污染环境防治法》、《城市市容和环境卫生管理条例》和《国务院对确需保留的行政审批项目设定行政许可的决定》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于城市规划区内建筑垃圾的倾倒、运输、中转、回填、消纳、利用等处置活动。 本规定所称建筑垃圾，是指建设单位、施工单位新建、改建、扩建和拆除各类建筑物、构筑物、管网等以及居民装饰装修房屋过程中所产生的弃土、弃料及其它废弃物。"},{"i":3,"n":"第三条","txt":"国务院建设主管部门负责全国城市建筑垃圾的管理工作。 省、自治区建设主管部门负责本行政区域内城市建筑垃圾的管理工作。 城市人民政府市容环境卫生主管部门负责本行政区域内建筑垃圾的管理工作。"},{"i":4,"n":"第四条","txt":"建筑垃圾处置实行减量化、资源化、无害化和谁产生、谁承担处置责任的原则。 国家鼓励建筑垃圾综合利用，鼓励建设单位、施工单位优先采用建筑垃圾综合利用产品"},{"i":5,"n":"第五条","txt":"建筑垃圾消纳、综合利用等设施的设置，应当纳入城市市容环境卫生专业规划。"},{"i":6,"n":"第六条","txt":"城市人民政府市容环境卫生主管部门应当根据城市内的工程施工情况，制定建筑垃圾处置计划，合理安排各类建设工程需要回填的建筑垃圾。"},{"i":7,"n":"第七条","txt":"处置建筑垃圾的单位，应当向城市人民政府市容环境卫生主管部门提出申请，获得城市建筑垃圾处置核准后，方可处置。 城市人民政府市容环境卫生主管部门应当在接到申请后的20日内作出是否核准的决定。予以核准的，颁发核准文件；不予核准的，应当告知申请人，并说明理由。 城市建筑垃圾处置核准的具体条件按照《建设部关于纳入国务院决定的十五项行政许可的条件的规定》执行。"},{"i":8,"n":"第八条","txt":"禁止涂改、倒卖、出租、出借或者以其他形式非法转让城市建筑垃圾处置核准文件。"},{"i":9,"n":"第九条","txt":"任何单位和个人不得将建筑垃圾混入生活垃圾，不得将危险废物混入建筑垃圾，不得擅自设立弃置场受纳建筑垃圾。"},{"i":10,"n":"第十条","txt":"建筑垃圾储运消纳场不得受纳工业垃圾、生活垃圾和有毒有害垃圾。"},{"i":11,"n":"第十一条","txt":"居民应当将装饰装修房屋过程中产生的建筑垃圾与生活垃圾分别收集，并堆放到指定地点。建筑垃圾中转站的设置应当方便居民。 装饰装修施工单位应当按照城市人民政府市容环境卫生主管部门的有关规定处置建筑垃圾。"},{"i":12,"n":"第十二条","txt":"施工单位应当及时清运工程施工过程中产生的建筑垃圾，并按照城市人民政府市容环境卫生主管部门的规定处置，防止污染环境。"},{"i":13,"n":"第十三条","txt":"施工单位不得将建筑垃圾交给个人或者未经核准从事建筑垃圾运输的单位运输。"},{"i":14,"n":"第十四条","txt":"处置建筑垃圾的单位在运输建筑垃圾时，应当随车携带建筑垃圾处置核准文件，按照城市人民政府有关部门规定的运输路线、时间运行，不得丢弃、遗撒建筑垃圾，不得超出核准范围承运建筑垃圾。"},{"i":15,"n":"第十五条","txt":"任何单位和个人不得随意倾倒、抛撒或者堆放建筑垃圾。"},{"i":16,"n":"第十六条","txt":"建筑垃圾处置实行收费制度，收费标准依据国家有关规定执行。"},{"i":17,"n":"第十七条","txt":"任何单位和个人不得在街道两侧和公共场地堆放物料。因建设等特殊需要，确需临时占用街道两侧和公共场地堆放物料的，应当征得城市人民政府市容环境卫生主管部门同意后，按照有关规定办理审批手续。"},{"i":18,"n":"第十八条","txt":"城市人民政府市容环境卫生主管部门核发城市建筑垃圾处置核准文件，有下列情形之一的，由其上级行政机关或者监察机关责令纠正，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）对不符合法定条件的申请人核发城市建筑垃圾处置核准文件或者超越法定职权核发城市建筑垃圾处置核准文件的； （二）对符合条件的申请人不予核发城市建筑垃圾处置核准文件或者不在法定期限内核发城市建筑垃圾处置核准文件的。"},{"i":19,"n":"第十九条","txt":"城市人民政府市容环境卫生主管部门的工作人员玩忽职守、滥用职权、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"任何单位和个人有下列情形之一的，由城市人民政府市容环境卫生主管部门责令限期改正，给予警告，处以罚款： （一）将建筑垃圾混入生活垃圾的； （二）将危险废物混入建筑垃圾的； （三）擅自设立弃置场受纳建筑垃圾的； 单位有前款第一项、第二项行为之一的，处300O元以下罚款；有前款第三项行为的，处5000元以上1万元以下罚款。个人有前款第一项、第二项行为之一的，处20O元以下罚款；有前款第三项行为的，处3000元以下罚款。"},{"i":21,"n":"第二十一条","txt":"建筑垃圾储运消纳场受纳工业垃圾、生活垃圾和有毒有害垃圾的，由城市人民政府市容环境卫生主管部门责令限期改正，给予警告，处5000元以上1万元以下罚款。"},{"i":22,"n":"第二十二条","txt":"施工单位未及时清运工程施工过程中产生的建筑垃圾，造成环境污染的，由城市人民政府市容环境卫生主管部门责令限期改正，给予警告，处5000元以上5万元以下罚款。 施工单位将建筑垃圾交给个人或者未经核准从事建筑垃圾运输的单位处置的，由城市人民政府市容环境卫生主管部门责令限期改正，给予警告，处1万元以上10万元以下罚款。"},{"i":23,"n":"第二十三条","txt":"处置建筑垃圾的单位在运输建筑垃圾过程中沿途丢弃、遗撒建筑垃圾的，由城市人民政府市容环境卫生主管部门责令限期改正，给予警告，处5000元以上5万元以下罚款。"},{"i":24,"n":"第二十四条","txt":"涂改、倒卖、出租、出借或者以其他形式非法转让城市建筑垃圾处置核准文件的，由城市人民政府市容环境卫生主管部门责令限期改正，给予警告，处5000元以上2万元以 下罚款。"},{"i":25,"n":"第二十五条","txt":"违反本规定，有下列情形之一的，由城市人民政府市容环境卫生主管部门责令限期改正，给予警告，对施工单位处 1万元以上10万元以下罚款，对建设单位、运输建筑垃圾的单位处5000元以上3万元以下罚款： （一）未经核准擅自处置建筑垃圾的； （二）处置超出核准范围的建筑垃圾的。"},{"i":26,"n":"第二十六条","txt":"任何单位和个人随意倾倒、抛撒或者堆放建筑垃圾的，由城市人民政府市容环境卫生主管部门责令限期改正，给予警告，并对单位处5000元以上5万元以下罚款，对个人处200元以下罚款。"},{"i":27,"n":"第二十七条","txt":"本规定自2005年6月1日起施行。"}],"chengshijianshedanganguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强城市建设档案（以下简称城建档案）管理，充分发挥城建档案在城市规划、建设、管理中的作用，根据《中华人民共和国档案法》、《中华人民共和国城乡规划法》、《科学技术档案工作条例》、《建设工程质量管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于城市内（包括城市各类开发区）的城建档案的管理。 本规定所称城建档案是指在城市规划、建设及其管理活动中直接形成的对国家和社会具有保存价值的文字、图纸、图表、声像等各种载体的文件材料。"},{"i":3,"n":"第三条","txt":"国务院建设行政主管部门负责全国城建档案管理工作，业务上受国家档案部门的监督、指导。 县级以上地方人民政府建设行政主管部门负责本行政区域内的城建档案管理工作，业务上受同级档案部门的监督、指导。 城市的建设行政主管部门应当设置城建档案工作管理机构或者配备城建档案管理人员，负责全市城建档案工作。城市的建设行政主管部门也可以委托城建档案馆负责城建档案工作的日常管理工作。"},{"i":4,"n":"第四条","txt":"城建档案馆的建设资金按照国家或者地方的有关规定，采取多种渠道解决。城建档案馆的设计应当符合档案馆建筑设计规范要求。城建档案的管理应当逐步采用新技术，实现管理现代化。"},{"i":5,"n":"第五条","txt":"城建档案馆重点管理下列档案资料： （一）各类城市建设工程档案： １、工业、民用建筑工程； ２、市政基础设施工程； ３、公用基础设施工程； ４、交通基础设施工程； ５、园林建设、风景名胜建设工程； ６、市容环境卫生设施建设工程； ７、城市防洪、抗震、人防工程； ８、军事工程档案资料中，除军事禁区和军事管理区以外的穿越市区的地下管线走向和有关隐蔽工程的位置图。 （二）建设系统各专业管理部门（包括城市规划、勘测、设计、施工、监理、园林、风景名胜、环卫、市政、公用、房地产管理、人防等部门）形成的业务管理和业务技术档案。 （三）有关城市规划、建设及其管理的方针、政策、法规、计划方面的文件、科学研究成果和城市历史、自然、经济等方面的基础资料。"},{"i":6,"n":"第六条","txt":"建设单位应当在工程竣工验收后“三”个月内，向城建档案馆报送一套符合规定的建设工程档案。凡工程建筑档案不齐全的，应当限期补充。 停建、缓建工程的档案，暂由建设单位保管。 撤销单位的建设工程档案，应当向上级主管机关或者城建档案馆移交。"},{"i":7,"n":"第七条","txt":"对改建、扩建和重要部位维修的工程，建设单位应当组织设计、施工单位据实修改、补充和完善原建设工程档案。凡结构和平面布置等改变的，应当重新编制建设工程档案，并在工程竣工后三个月内向城建档案馆报送。"},{"i":8,"n":"第八条","txt":"列入城建档案馆档案接收范围的工程，城建档案管理机构按照建设工程竣工联合验收的规定对工程档案进行验收。"},{"i":9,"n":"第九条","txt":"建设系统各专业管理部门形成的业务管理和业务技术档案，凡具有永久保存价值的，在本单位保管使用一至五年后，按本规定全部向城建档案馆移交。有长期保存价值的档案，由城建档案馆根据城市建设的需要选择接收。 城市地下管线普查和补测补绘形成的地下管线档案应当在普查、测绘结束后三个月内接收进馆。地下管线专业管理单位每年应当向城建档案馆报送更改、报废、漏测部分的管线现状图和资料。 房地产权属档案的管理，由国务院建设行政主管部门另行规定。"},{"i":10,"n":"第十条","txt":"城建档案馆对接收的档案应当及时登记、整理，编制检索工具。做好档案的保管、保护工作，对破损或者变质的档案应当及时抢救。特别重要的城建档案应当采取有效措施，确保其安全无损。 城建档案馆应当积极开发档案信息资源，并按照国家的有关规定，向社会提供服务。"},{"i":11,"n":"第十一条","txt":"建设行政主管部门对在城建档案工作中做出显著成绩的单位和个人，应当给予表彰和奖励。"},{"i":12,"n":"第十二条","txt":"违反本规定有下列行为之一的，由建设行政主管部门对直接负责的主管人员或者其他直接责任人员依法给予行政处分；构成犯罪的，由司法机关依法追究刑事责任： （一）无故延期或者不按照规定归档、报送的； （二）涂改、伪造档案的； （三）档案工作人员玩忽职守，造成档案损失的。"},{"i":13,"n":"第十三条","txt":"建设工程竣工验收后，建设单位未按照本规定移交建设工程档案的，依照《建设工程质量管理条例》的规定处罚。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市人民政府建设行政主管部门可以根据本规定制定实施细则。"},{"i":15,"n":"第十五条","txt":"本规定由国务院建设行政主管部门负责解释。"},{"i":16,"n":"第十六条","txt":"本规定自1998年１月１日起施行。以前发布的有关规定与本规定不符的，按本规定执行。"}],"chengshifangdichandiyaguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强房地产抵押管理，维护房地产市场秩序，保障房地产抵押当事人的合法权益，根据《中华人民共和国城市房地产管理法》、《中华人民共和国担保法》，制定本办法。"},{"i":2,"n":"第二条","txt":"凡在城市规划区国有土地范围内从事房地产抵押活动的，应当遵守本办法。 地上无房屋（包括建筑物、构筑物及在建工程）的国有土地使用权设定抵押的，不适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称房地产抵押，是指抵押人以其合法的房地产以不转移占有的方式向抵押权人提供债务履行担保的行为。债务人不履行债务时，债权人有权依法以抵押的房地产拍卖所得的价款优先受偿。 本办法所称抵押人，是指将依法取得的房地产提供给抵押权人，作为本人或者第三人履行债务担保的公民、法人或者其他组织。 本办法所称抵押权人，是指接受房地产抵押作为债务人履行债务担保的公民、法人或者其他组织。 本办法所称预购商品房贷款抵押，是指购房人在支付首期规定的房价款后，由贷款银行代其支付其余的购房款，将所购商品房抵押给贷款银行作为偿还贷款履行担保的行为。 本办法所称在建工程抵押，是指抵押人为取得在建工程继续建造资金的贷款，以其合法方式取得的土地使用权连同在建工程的投入资产，以不转移占有的方式抵押给贷款银行作为偿还贷款履行担保的行为。"},{"i":4,"n":"第四条","txt":"以依法取得的房屋所有权抵押的，该房屋占用范围内的土地使用权必须同时抵押。"},{"i":5,"n":"第五条","txt":"房地产抵押，应当遵循自愿、互利、公平和诚实信用的原则。 依法设定的房地产抵押，受国家法律保护。"},{"i":6,"n":"第六条","txt":"国家实行房地产抵押登记制度。"},{"i":7,"n":"第七条","txt":"国务院建设行政主管部门归口管理全国城市房地产抵押管理工作。 省、自治区建设行政主管部门归口管理本行政区域内的城市房地产抵押管理工作。 直辖市、市、县人民政府房地产行政主管部门（以下简称房地产管理部门）负责管理本行政区域内的房地产抵押管理工作。"},{"i":8,"n":"第八条","txt":"下列房地产不得设定抵押： （一）权属有争议的房地产； （二）用于教育、医疗、市政等公共福利事业的房地产； （三）列入文物保护的建筑物和有重要纪念意义的其他建筑物； （四）已依法公告列入拆迁范围的房地产； （五）被依法查封、扣押、监管或者以其他形式限制的房地产； （六）依法不得抵押的其他房地产。"},{"i":9,"n":"第九条","txt":"同一房地产设定两个以上抵押权的，抵押人应当将已经设定过的抵押情况告知抵押权人。 抵押人所担保的债权不得超出其抵押物的价值。 房地产抵押后，该抵押房地产的价值大于所担保债权的余额部分，可以再次抵押，但不得超出余额部分。"},{"i":10,"n":"第十条","txt":"以两宗以上房地产设定同一抵押权的，视为同一抵押房地产。但抵押当事人另有约定的除外。"},{"i":11,"n":"第十一条","txt":"以在建工程已完工部分抵押的，其土地使用权随之抵押。"},{"i":12,"n":"第十二条","txt":"以享受国家优惠政策购买的房地产抵押的，其抵押额以房地产权利人可以处分和收益的份额比例为限。"},{"i":13,"n":"第十三条","txt":"国有企业、事业单位法人以国家授予其经营管理的房地产抵押的，应当符合国有资产管理的有关规定。"},{"i":14,"n":"第十四条","txt":"以集体所有制企业的房地产抵押的，必须经集体所有制企业职工（代表）大会通过，并报其上级主管机关备案。"},{"i":15,"n":"第十五条","txt":"以中外合资企业、合作经营企业和外商独资企业的房地产抵押的，必须经董事会通过，但企业章程另有规定的除外。"},{"i":16,"n":"第十六条","txt":"以有限责任公司、股份有限公司的房地产抵押的，必须经董事会或者股东大会通过，但企业章程另有规定的除外。"},{"i":17,"n":"第十七条","txt":"有经营期限的企业以其所有的房地产设定抵押的，所担保债务的履行期限不应当超过该企业的经营期限。"},{"i":18,"n":"第十八条","txt":"以具有土地使用年限的房地产设定抵押的，所担保债务的履行期限不得超过土地使用权出让合同规定的使用年限减去已经使用年限后的剩余年限。"},{"i":19,"n":"第十九条","txt":"以共有的房地产抵押的，抵押人应当事先征得其他共有人的书面同意。"},{"i":20,"n":"第二十条","txt":"预购商品房贷款抵押的，商品房开发项目必须符合房地产转让条件并取得商品房预售许可证。"},{"i":21,"n":"第二十一条","txt":"以已出租的房地产抵押的，抵押人应当将租赁情况告知抵押权人，并将抵押情况告知承租人。原租赁合同继续有效。"},{"i":22,"n":"第二十二条","txt":"设定房地产抵押时，抵押房地产的价值可以由抵押当事人协商议定，也可以由房地产价格评估机构评估确定。 法律、法规另有规定的除外。"},{"i":23,"n":"第二十三条","txt":"抵押当事人约定对抵押房地产保险的，由抵押人为抵押的房地产投保，保险费由抵押人负担。抵押房地产投保的，抵押人应当将保险单移送抵押权人保管。在抵押期间，抵押权人为保险赔偿的第一受益人。"},{"i":24,"n":"第二十四条","txt":"企业、事业单位法人分立或者合并后，原抵押合同继续有效。其权利和义务由变更后的法人享有和承担。 抵押人死亡、依法被宣告死亡或者被宣告失踪时，其房地产合法继承人或者代管人应当继续履行原抵押合同。"},{"i":25,"n":"第二十五条","txt":"房地产抵押，抵押当事人应当签订书面抵押合同。"},{"i":26,"n":"第二十六条","txt":"房地产抵押合同应当载明下列主要内容： （一）抵押人、抵押权人的名称或者个人姓名、住所； （二）主债权的种类、数额； （三）抵押房地产的处所、名称、状况、建筑面积、用地面积以及四至等； （四）抵押房地产的价值； （五）抵押房地产的占用管理人、占用管理方式、占用管理责任以及意外损毁、灭失的责任； （六）债务人履行债务的期限； （七）抵押权灭失的条件； （八）违约责任： （九）争议解决方式； （十）抵押合同订立的时间与地点； （十一）双方约定的其他事项。"},{"i":27,"n":"第二十七条","txt":"以预购商品房贷款抵押的，须提交生效的预购房屋合同。"},{"i":28,"n":"第二十八条","txt":"以在建工程抵押的，抵押合同还应当载明以下内容： （一）《国有土地使用权证》、《建设用地规划许可证》和《建设工程规划许可证》编号； （二）已交纳的土地使用权出让金或需交纳的相当于土地使用权出让金的款额； （三）已投入在建工程的工程款； （四）施工进度及工程竣工日期； （五）已完成的工作量和工程量。"},{"i":29,"n":"第二十九条","txt":"抵押权人要求抵押房地产保险的，以及要求在房地产抵押后限制抵押人出租、转让抵押房地产或者改变抵押房地产用途的，抵押当事人应当在抵押合同中载明。"},{"i":30,"n":"第三十条","txt":"房地产抵押合同自签订之日起30日内，抵押当事人应当到房地产所在地的房地产管理部门办理房地产抵押登记。"},{"i":31,"n":"第三十一条","txt":"房地产抵押合同自抵押登记之日起生效。"},{"i":32,"n":"第三十二条","txt":"办理房地产抵押登记，应当向登记机关交验下列文件： （一）抵押当事人的身份证明或法人资格证明； （二）抵押登记申请书； （三）抵押合同； （四）《国有土地使用权证》、《房屋所有权证》或《房地产权证》，共有的房屋还必须提交《房屋共有权证》和其他共有人同意抵押的证明； （五）可以证明抵押人有权设定抵押权的文件与证明材料； （六）可以证明抵押房地产价值的资料； （七）登记机关认为必要的其他文件。"},{"i":33,"n":"第三十三条","txt":"登记机关应当对申请人的申请进行审核。凡权属清楚、证明材料齐全的，应当在受理登记之日起７日内决定是否予以登记，对不予登记的，应当书面通知申请人。"},{"i":34,"n":"第三十四条","txt":"以依法取得的房屋所有权证书的房地产抵押的，登记机关应当在原《房屋所有权证》上作他项权利记载后，由抵押人收执。并向抵押权人颁发《房屋他项权证》。 以预售商品房或者在建工程抵押的，登记机关应当在抵押合同上作记载。抵押的房地产在抵押期间竣工的，当事人应当在抵押人领取房地产权属证书后，重新办理房地产抵押登记。"},{"i":35,"n":"第三十五条","txt":"抵押合同发生变更或者抵押关系终止时，抵押当事人应当在变更或者终止之日起15日内，到原登记机关办理变更或者注销抵押登记。 因依法处分抵押房地产而取得土地使用权和土地建筑物、其他附着物所有权的，抵押当事人应当自处分行为生效之日起30日内，到县级以上地方人民政府房地产管理部门申请房屋所有权转移登记，并凭变更后的房屋所有权证书向同级人民政府土地管理部门申请土地使用权变更登记。"},{"i":36,"n":"第三十六条","txt":"已作抵押的房地产，由抵押人占用与管理。 抵押人在抵押房地产占用与管理期间应当维护抵押房地产的安全与完好。抵押权人有权按照抵押合同的规定监督、检查抵押房地产的管理情况。"},{"i":37,"n":"第三十七条","txt":"抵押权可以随债权转让。抵押权转让时，应当签订抵押权转让合同，并办理抵押权变更登记。抵押权转让后，原抵押权人应当告知抵押人。 经抵押权人同意，抵押房地产可以转让或者出租。 抵押房地产转让或者出租所得价款，应当向抵押权人提前清偿所担保的债权。超过债权数额的部分，归抵押人所有，不足部分由债务人清偿。"},{"i":38,"n":"第三十八条","txt":"因国家建设需要，将已设定抵押权的房地产列入拆迁范围的，抵押人应当及时书面通知抵押权人；抵押双方可以重新设定抵押房地产，也可以依法清理债权债务，解除抵押合同。"},{"i":39,"n":"第三十九条","txt":"抵押人占用与管理的房地产发生损毁、灭失的，抵押人应当及时将情况告知抵押权人，并应当采取措施防止损失的扩大。抵押的房地产因抵押人的行为造成损失使抵押房地产价值不足以作为履行债务的担保时，抵押权人有权要求抵押人重新提供或者增加担保以弥补不足。 抵押人对抵押房地产价值减少无过错的，抵押权人只能在抵押人因损害而得到的赔偿的范围内要求提供担保。抵押房地产价值未减少的部分，仍作为债务的担保。"},{"i":40,"n":"第四十条","txt":"有下列情况之一的，抵押权人有权要求处分抵押的房地产： （一）债务履行期满，抵押权人未受清偿的，债务人又未能与抵押权人达成延期履行协议的； （二）抵押人死亡、或者被宣告死亡而无人代为履行到期债务的；或者抵押人的合法继承人，受遗赠人拒绝履行到期债务的； （三）抵押人被依法宣告解散或者破产的； （四）抵押人违反本办法的有关规定，擅自处分抵押房地产的； （五）抵押合同约定的其他情况。"},{"i":41,"n":"第四十一条","txt":"有本办法第四十条规定情况之一的，经抵押当事人协商可以通过拍卖等合法方式处分抵押房地产。协议不成的，抵押权人可以向人民法院提起诉讼。"},{"i":42,"n":"第四十二条","txt":"抵押权人处分抵押房地产时，应当事先书面通知抵押人；抵押房地产为共有或者出租的，还应当同时书面通知共有人或承租人；在同等条件下，共有人或承租人依法享有优先购买权。"},{"i":43,"n":"第四十三条","txt":"同一房地产设定两个以上抵押权时，以抵押登记的先后顺序受偿。"},{"i":44,"n":"第四十四条","txt":"处分抵押房地产时，可以依法将土地上新增的房屋与抵押财产一同处分，但对处分新增房屋所得，抵押权人无权优先受偿。"},{"i":45,"n":"第四十五条","txt":"以划拨方式取得的土地使用权连同地上建筑物设定的房地产抵押进行处分时，应当从处分所得的价款中缴纳相当于应当缴纳的土地使用权出让金的款额后，抵押权人方可优先受偿。 法律、法规另有规定的依照其规定。"},{"i":46,"n":"第四十六条","txt":"抵押权人对抵押房地产的处分，因下列情况而中止： （一）抵押权人请求中止的； （二）抵押人申请愿意并证明能够及时履行债务，并经抵押权人同意的； （三）发现被拍卖抵押物有权属争议的； （四）诉讼或仲裁中的抵押房地产； （五）其他应当中止的情况。"},{"i":47,"n":"第四十七条","txt":"处分抵押房地产所得金额，依下列顺序分配： （一）支付处分抵押房地产的费用； （二）扣除抵押房地产应缴纳的税款； （三）偿还抵押权人债权本息及支付违约金； （四）赔偿由债务人违反合同而对抵押权人造成的损害； （五）剩余金额交还抵押人。 处分抵押房地产所得金额不足以支付债务和违约金、赔偿金时，抵押权人有权向债务人追索不足部分。"},{"i":48,"n":"第四十八条","txt":"抵押人隐瞒抵押的房地产存在共有、产权争议或者被查封、扣押等情况的，抵押人应当承担由此产生的法律责任。"},{"i":49,"n":"第四十九条","txt":"抵押人擅自以出售、出租、交换、赠与或者以其他方式处分抵押房地产的，其行为无效；造成第三人损失的，由抵押人予以赔偿。"},{"i":50,"n":"第五十条","txt":"抵押当事人因履行抵押合同或者处分抵押房地产发生争议的，可以协商解决；协商不成的，抵押当事人可以根据双方达成的仲裁协议向仲裁机构申请仲裁；没有仲裁协议的，也可以直接向人民法院提起诉讼。"},{"i":51,"n":"第五十一条","txt":"因国家建设需要，将已设定抵押权的房地产列入拆迁范围时，抵押人违反前述第三十八条的规定，不依法清理债务，也不重新设定抵押房地产的，抵押权人可以向人民法院提起诉讼。"},{"i":52,"n":"第五十二条","txt":"登记机关工作人员玩忽职守、滥用职权，或者利用职务上的便利，索取他人财物，或者非法收受他人财物为他人谋取利益的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"在城市规划区外国有土地上进行房地产抵押活动的，参照本办法执行。"},{"i":54,"n":"第五十四条","txt":"本办法由国务院建设行政主管部门负责解释。"},{"i":55,"n":"第五十五条","txt":"本办法自1997年6月1日起施行。"}],"chengshifangdichanquanshudanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强城市房地产权属档案管理，保障房地产权利人的合法权益，有效保护和利用城市房地产权属档案，根据《中华人民共和国城市房地产管理法》、《中华人民共和国档案法》、《中华人民共和国档案法实施办法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于城市规划区国有土地范围内房地产权属档案的管理。"},{"i":3,"n":"第三条","txt":"房地产权属档案是城市房地产行政主管部门在房地产权属登记、调查、测绘、权属转移、变更等房地产权属管理工作中直接形成的有保存价值的文字、图表、声像等不同形式的历史记录，是城市房地产权属登记管理工作的真实记录和重要依据，是城市建设档案的组成部分。"},{"i":4,"n":"第四条","txt":"国务院建设行政主管部门负责全国城市房地产权属档案管理工作； 省、自治区人民政府建设行政主管部门负责本行政区域内的房地产权属档案的管理工作。 直辖市、市、县人民政府房地产行政主管部门负责本行政区域内的房地产权属档案的管理工作。 房地产权属档案管理业务上受同级城市建设档案管理部门的监督和指导。"},{"i":5,"n":"第五条","txt":"市（县）人民政府房地产行政主管部门应当根据房地产权属档案管理工作的需要，建立房地产权属档案管理机构，配备专职档案管理人员，健全工作制度，配备必要的安全保护设施，确保房地产权属档案的完整、准确、安全和有效利用。"},{"i":6,"n":"第六条","txt":"从事房地产权属档案管理的工作人员经过业务培训后，方可上岗。"},{"i":7,"n":"第七条","txt":"房地产权属登记管理部门应当建立健全房地产权属文件材料的收集、整理、归档制度。"},{"i":8,"n":"第八条","txt":"下列文件材料属于房地产权属档案的归档范围： 一、房地产权利人、房地产权属登记确权、房地产权属转移及变更、设定他项权利等有关的证明和文件。 （一）房地产权利人（自然人或法人）的身份（资格）证明、法人代理人的身份证明、授权委托书等； （二）建设工程规划许可证、建设用地规划许可证、土地使用权证书或者土地来源证明、房屋拆迁批件及补偿安置协议书、联建或者统建合同、翻改扩建及固定资产投资批准文件、房屋竣工验收有关材料等； （三）房地产买卖合同书、房产继承书、房产赠与书、房产析产协议书、房产交换协议书、房地产调拨凭证、有关房产转移的上级批件，有关房产的判决、裁决、仲裁文书及公证文书等； （四）设定房地产他项权利的有关合同、文件等。 二、房屋及其所占用的土地使用权权属界定位置图；房地产分幅平面图、分丘平面图、分层分户平面图等。 三、房地产产权登记工作中形成的各种文件材料，包括房产登记申请书、收件收据存"},{"i":9,"n":"第九条","txt":"每件（宗）房地产权属登记工作完成后，权属登记人员应当及时将整理好的权属文件材料，经权属登记负责人审查后，送交房地产权属档案管理机构立卷归档。任何单位和个人都不得将房地产权属文件材料据为己有或者拒不归档。国家规定不得归档的材料，禁止归档。"},{"i":10,"n":"第十条","txt":"归档的有关房地产权属的资料，应当是原件；原件已存城市建设档案馆或者经房地产管理部门批准认定的，可以是复印、复制件。复印、复制件应当由经办人与原件校对、签章，并注明校对日期及原件的存放处。"},{"i":11,"n":"第十一条","txt":"归档的房地产权属资料，应当做到书写材料合乎标准、字迹工整、内容规范、图形清晰、数据准确、符合档案保护的要求。"},{"i":12,"n":"第十二条","txt":"房地产权属档案管理机构应当按照档案管理的规定对归档的各种房地产权属档案材料进行验收，不符合要求的，不予归档。"},{"i":13,"n":"第十三条","txt":"房地产权属档案管理机构对归档的房地产权属文件材料应当及时进行登记、整理、分类编目、划分密级、编制检索工具。"},{"i":14,"n":"第十四条","txt":"房地产权属档案应当以丘为单元建档。丘号的编定按照国家《房产测量规范》标准执行。"},{"i":15,"n":"第十五条","txt":"房地产权属档案应当以房地产权利人（即权属单元）为宗立卷。卷内文件排列，应当按照房地产权属变化、产权文件形成时间及权属文件主次关系为序。"},{"i":16,"n":"第十六条","txt":"房地产权属档案管理机构应当掌握房地产权属变化情况，及时补充有关权属档案材料，保持房地产权属档案与房地产权属现状的一致。"},{"i":17,"n":"第十七条","txt":"房地产权属档案管理人员应当严格执行权属档案管理的有关规定，不得擅自修改房地产权属档案。确需变更和修改的，应当经房地产权属登记机关批准，按照规定程序进行。"},{"i":18,"n":"第十八条","txt":"房地产权属档案应当妥善保存，定期检查和鉴定。对破损或者变质的档案，应当及时修复；档案毁损或者丢失，应当采取补救措施。未经批准，任何人不得以任何借口擅自销毁房地产权属档案。"},{"i":19,"n":"第十九条","txt":"保管房地产权属档案应当配备符合设计规范的专用库房，并按照国家《档案库房技术管理暂行规定》实施管理。"},{"i":20,"n":"第二十条","txt":"房地产权属档案管理应当逐步采用新技术、新设备，实现管理现代化。"},{"i":21,"n":"第二十一条","txt":"房地产权属档案管理机构应当与城市建设档案管理机构密切联系，加强信息沟通，逐步实现档案信息共享。"},{"i":22,"n":"第二十二条","txt":"房地产权属档案管理机构的隶属关系及档案管理人员发生变动，应当及时办理房地产权属档案的交接手续。"},{"i":23,"n":"第二十三条","txt":"房屋自然灭失或者依法被拆除后，房地产权属档案管理机构应当自档案整理归档完毕之日起15日内书面通知城市建设档案馆。"},{"i":24,"n":"第二十四条","txt":"房地产权属档案管理机构应当充分利用现有的房地产权属档案，及时为房地产权属登记、房地产交易、房地产纠纷仲裁、物业管理、房屋拆迁、住房制度改革、城市规划、城市建设等各项工作提供服务。"},{"i":25,"n":"第二十五条","txt":"房地产权属档案管理机构应当严格执行国家档案管理的保密规定，防止房地产权属档案的散失、泄密；定期对房地产权属档案的密级进行审查，根据有关规定，及时调整密级。"},{"i":26,"n":"第二十六条","txt":"查阅、抄录和复制房地产权属档案材料应当履行审批手续，并登记备案。 涉及军事机密和其他保密的房地产权属档案，以及向境外团体和个人提供的房地产权属档案应当按照国家安全、保密等有关规定保管和利用。"},{"i":27,"n":"第二十七条","txt":"向社会提供利用房地产权属档案，可以按照国家有关规定，实行有偿服务。"},{"i":28,"n":"第二十八条","txt":"有下列行为之一的，由县级以上人民政府房地产行政主管部门对直接负责的主管人员或者其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）损毁、丢失房地产权属档案的； （二）擅自提供、抄录、公布、销毁房地产权属档案的； （三）涂改、伪造房地产权属档案的； （四）擅自出卖或者转让房地产权属档案的； （五）违反本办法第九条规定，不按照规定归档的； （六）档案管理工作人员玩忽职守，造成房地产权属档案损失的。"},{"i":29,"n":"第二十九条","txt":"违反《中华人民共和国档案法》、《中华人民共和国档案法实施办法》以及本办法的规定，造成房地产权属档案损失的，由县级以上人民政府房地产行政主管部门根据损失档案的价值，责令赔偿损失。"},{"i":30,"n":"第三十条","txt":"有下列行为之一的，按照有关法律法规的规定处罚： （一）在利用房地产权属档案的过程中，损毁、丢失、涂改、伪造房地产权属档案或者擅自提供、抄录、公布、销毁房地产权属档案的； （二）企事业组织或者个人擅自出卖或者转让房地产权属档案的。"},{"i":31,"n":"第三十一条","txt":"房地产权属档案管理机构的设置、编制、经费，房地产权属档案管理工作人员的职称、奖惩办法等参照国家档案管理的有关规定执行。"},{"i":32,"n":"第三十二条","txt":"城市规划区集体土地范围内和城市规划区外土地上的房地产权属档案管理可以参照本办法执行。"},{"i":33,"n":"第三十三条","txt":"各省、自治区人民政府建设行政主管部门、直辖市房地产行政主管部门可以根据本办法制定实施细则。"},{"i":34,"n":"第三十四条","txt":"本办法由国务院建设行政主管部门负责解释。"},{"i":35,"n":"第三十五条","txt":"本办法自二○○一年十二月一日起施行。"}],"chengshifangdichanzhuanrangguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对城市房地产转让的管理，维护房地产市场秩序，保障房地产转让当事人的合法权益，根据《中华人民共和国城市房地产管理法》，制定本规定。"},{"i":2,"n":"第二条","txt":"凡在城市规划区国有土地范围内从事房地产转让，实施房地产转让管理，均应遵守本规定。"},{"i":3,"n":"第三条","txt":"本规定所称房地产转让，是指房地产权利人通过买卖、赠与或者其他合法方式将其房地产转移给他人的行为。 前款所称其他合法方式，主要包括下列行为： （一）以房地产作价入股、与他人成立企业法人，房地产权属发生变更的； （二）一方提供土地使用权，另一方或者多方提供资金，合资、合作开发经营房地产，而使房地产权属发生变更的； （三）因企业被收购、兼并或合并，房地产权属随之转移的； （四）以房地产抵债的； （五）法律、法规规定的其他情形。"},{"i":4,"n":"第四条","txt":"国务院建设行政主管部门归口管理全国城市房地产转让工作。 省、自治区人民政府建设行政主管部门归口管理本行政区域内的城市房地产转让工作。 直辖市、市、县人民政府房地产行政主管部门（以下简称房地产管理部门）负责本行政区域内的城市房地产转让管理工作。"},{"i":5,"n":"第五条","txt":"房地产转让时，房屋所有权和该房屋占用范围内的土地使用权同时转让。"},{"i":6,"n":"第六条","txt":"下列房地产不得转让： （一）以出让方式取得土地使用权但不符合本规定第十条规定的条件的； （二）司法机关和行政机关依法裁定，决定查封或者以其他形式限制房地产权利的； （三）依法收回土地使用权的； （四）共有房地产，未经其他共有人书面同意的； （五）权属有争议的； （六）未依法登记领取权属证书的； （七）法律、行政法规规定禁止转让的其他情形。"},{"i":7,"n":"第七条","txt":"房地产转让，应当按照下列程序办理： （一）房地产转让当事人签订书面转让合同； （二）房地产转让当事人在房地产转让合同签订后90日内持房地产权属证书、当事人的合法证明、转让合同等有关文件向房地产所在地的房地产管理部门提出申请，并申报成交价格； （三）房地产管理部门对提供的有关文件进行审查，并在7日内作出是否受理的书面答复，7日内未作书面答复的，视为同意受理； （四）房地产管理部门核实申报的成交价格，并根据需要对转让的房地产进行现场查勘和评估； （五）房地产转让当事人按照规定缴纳有关税费； （六）房地产管理部门办理房屋权属登记手续，核发房地产权属证书。"},{"i":8,"n":"第八条","txt":"房地产转让合同应当载明下列主要内容： （一）双方当事人的姓名或者名称、住所； （二）房地产权属证书名称和编号； （三）房地产座落位置、面积、四至界限； （四）土地宗地号、土地使用权取得的方式及年限； （五）房地产的用途或使用性质； （六）成交价格及支付方式； （七）房地产交付使用的时间； （八）违约责任； （九）双方约定的其他事项。"},{"i":9,"n":"第九条","txt":"以出让方式取得土地使用权的，房地产转让时，土地使用权出让合同载明的权利、义务随之转移。"},{"i":10,"n":"第十条","txt":"以出让方式取得土地使用权的，转让房地产时，应当符合下列条件： （一）按照出让合同约定已经支付全部土地使用权出让金，并取得土地使用权证书； （二）按照出让合同约定进行投资开发，属于房屋建设工程的，应完成开发投资总额的百分之二十五以上；属于成片开发土地的，依照规划对土地进行开发建设，完成供排水、供电、供热、道路交通、通信等市政基础设施、公用设施的建设，达到场地平整，形成工业用地或者其他建设用地条件。 转让房地产时房屋已经建成的，还应当持有房屋所有权证书。"},{"i":11,"n":"第十一条","txt":"以划拨方式取得土地使用权的，转让房地产时，按照国务院的规定，报有批准权的人民政府审批。有批准权的人民政府准予转让的，除符合本规定第十二条所列的可以不办理土地使用权出让手续的情形外，应当由受让方办理土地使用权出让手续，并依照国家有关规定缴纳土地使用权出让金。"},{"i":12,"n":"第十二条","txt":"以划拨方式取得土地使用权的，转让房地产时，属于下列情形之一的，经有批准权的人民政府批准，可以不办理土地使用权出让手续，但应当将转让房地产所获收益中的土地收益上缴国家或者作其他处理。土地收益的缴纳和处理的办法按照国务院规定办理。 （一）经城市规划行政主管部门批准，转让的土地用于建设《中华人民共和国城市房地产管理法》第二十三条规定的项目的； （二）私有住宅转让后仍用于居住的； （三）按照国务院住房制度改革有关规定出售公有住宅的； （四）同一宗土地上部分房屋转让而土地使用权不可分割转让的； （五）转让的房地产暂时难以确定土地使用权出让用途、年限和其他条件的； （六）根据城市规划土地使用权不宜出让的； （七）县级以上人民政府规定暂时无法或不需要采取土地使用权出让方式的其他情形。依照前款规定缴纳土地收益或作其他处理的，应当在房地产转让合同中注明。"},{"i":13,"n":"第十三条","txt":"依照本规定第十二条规定转让的房地产再转让，需要办理出让手续、补交土地使用权出让金的，应当扣除已经缴纳的土地收益。"},{"i":14,"n":"第十四条","txt":"国家实行房地产成交价格申报制度。 房地产权利人转让房地产，应当如实申报成交价格，不得瞒报或者作不实的申报。 房地产转让应当以申报的房地产成交价格作为缴纳税费的依据。成交价格明显低于正常市场价格的，以评估价格作为缴纳税费的依据。"},{"i":15,"n":"第十五条","txt":"商品房预售按照建设部《城市商品房预售管理办法》执行。"},{"i":16,"n":"第十六条","txt":"房地产管理部门在办理房地产转让时，其收费的项目和标准，必须经有批准权的物价部门和建设行政主管部门批准，不得擅自增加收费项目和提高收费标准。"},{"i":17,"n":"第十七条","txt":"违反本规定第十条第一款和第十一条，未办理土地使用权出让手续，交纳土地使用权出让金的，按照《中华人民共和国城市房地产管理法》的规定进行处罚。"},{"i":18,"n":"第十八条","txt":"房地产管理部门工作人员玩忽职守、滥用职权、徇私舞弊、索贿受贿的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"在城市规划区外的国有土地范围内进行房地产转让的，参照本规定执行。"},{"i":20,"n":"第二十条","txt":"省、自治区人民政府建设行政主管部门、直辖市房地产行政主管部门可以根据本规定制定实施细则。"},{"i":21,"n":"第二十一条","txt":"本规定由国务院建设行政主管部门负责解释。"},{"i":22,"n":"第二十二条","txt":"本规定自1995年9月1日起施行。"}],"chengshifangwubianqishuixiangyingyongjianduguanlib2e377b":[{"i":1,"n":"第一条","txt":"为加强对城市房屋便器水箱质量和应用的监督管理，节约用水，根据《城市节约用水管理规定》，制定本办法。"},{"i":2,"n":"第二条","txt":"各有关部门应当按照职责分工，加强对房屋便器水箱和配件产品生产、销售以及设计、施工、安装、使用等全过程的监督管理。 各级人民政府城市建设行政主管部门依照本办法，对城市规划区内的房屋便器水箱和配件的应用实施统一的监督管理。"},{"i":3,"n":"第三条","txt":"新建房屋建筑必须安装符合国家标准的便器水箱和配件。凡新建房屋继续安装经国家有关行政主管部门已通知淘汰的便器水箱和配件（以下简称淘汰便器水箱和配件）的，不得竣工验收交付使用，供水部门不予供水，由城市建设行政主管部门责令限期更换。"},{"i":4,"n":"第四条","txt":"原有房屋安装使用淘汰便器水箱和配件的，房屋产权单位应当制定更新改造计划，分期分批进行改造。"},{"i":5,"n":"第五条","txt":"公有房屋淘汰便器水箱和配件所需要的更新改造资金，由房屋产权单位和使用权单位共同负担，并与房屋维修改造相结合，逐步推广使用节水型水箱配件和克漏阀等节水型产品。"},{"i":6,"n":"第六条","txt":"建设单位未按照本办法规定仍安装淘汰便器水箱和配件的，应当追究责任者的责任，经主管部门认定属于设计或者施工单位责任的，由责任方赔偿房屋产权单位全部更换费用和相关的经济损失。"},{"i":7,"n":"第七条","txt":"城市建设行政主管部门对漏水严重的房屋便器水箱和配件，应当责令房屋产权单位限期维修或者更新。"},{"i":8,"n":"第八条","txt":"房屋产权单位安装使用符合国家标准的便器水箱和配件出现质量问题，在质量保证期内生产企业应当对产品质量负责。由于产品质量原因引起漏水的，生产企业应当包修或者更换，并赔偿由此造成的经济损失。"},{"i":9,"n":"第九条","txt":"违反本办法有下列行为之一的，由城市建设行政主管部门责令限期改正、按测算漏水量月累计征收3—5倍的加价水费，并可按每套便器水箱配件处以30—100元的罚款，最高不超过30000元： （一）将安装有淘汰便器水箱和配件的新建房屋验收交付使用的； （二）未按更新改造计划更换淘汰便器水箱和配件的； （三）在限定的期限内未更换淘汰便器水箱和配件的； （四）对漏水严重的房屋便器水箱和配件未按期进行维修或者更新的。"},{"i":10,"n":"第十条","txt":"按本办法征收的加价水费按国家规定管理，专项用于推广应用符合国家标准的便器水箱和更新改造淘汰便器水箱，不得挪用。"},{"i":11,"n":"第十一条","txt":"城市建设行政主管部门的工作人员在房屋便器水箱应用监督工作中玩忽职守，滥用职权，徇私舞弊的，由其所在单位或者上级主管部门给予行政处分。构成犯罪的，由司法机关依法追究刑事责任"},{"i":12,"n":"第十二条","txt":"城市建设行政主管部门可以委托供水和节水管理部门对本办法具体组织实施。"},{"i":13,"n":"第十三条","txt":"各省、自治区、直辖市住房城乡建设主管部门可以根据本办法制定实施细则，报建设部备案。  十四条　本办法由住房城乡建设部负责解释。"},{"i":14,"n":"第十五条","txt":"本办法自一九九二年六月一日起施行。"}],"chengshifangwubaiyifangzhiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强城市房屋的白蚁防治管理，控制白蚁危害，保证城市房屋的住用安全，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于白蚁危害地区城市房屋的白蚁防治管理。 本规定所称的城市房屋白蚁防冶管理，是指对新建、改建、扩建、装饰装修等房屋的白蚁预防和对原有房屋的白蚁检查与灭治的管理。 凡白蚁危害地区的新建、改建、扩建、装饰装修的房屋必须实施白蚁预防处理。 白蚁危害地区的确定由省、自治区人民政府建设行政主管部门、直辖市人民政府房地产行政主管部门负责。"},{"i":3,"n":"第三条","txt":"城市房屋白蚁防治工作应当贯彻预防为主、防治结合、综合治理的方针。"},{"i":4,"n":"第四条","txt":"国家鼓励开展城市房屋白蚁防治科学研究，推广应用新药物、新技术、新工艺、新设备。"},{"i":5,"n":"第五条","txt":"国务院建设行政主管部门负责全国城市房屋白蚁防治的监督管理工作。 省、自治区人民政府建设行政主管部门负责本行政区域内城市房屋白蚁防治的监督管理工作。 直辖市、市、县人民政府房地产行政主管部门负责本行政区域内城市房屋白蚁防治的监督管理工作。"},{"i":6,"n":"第六条","txt":"设立白蚁防治单位，应当具备以下条件： （一）有自己的名称和组织机构； （二）有固定的办公地点及场所； （三）有生物、药物检测和建筑工程等专业的专职技术人员。"},{"i":7,"n":"第七条","txt":"建设项目依法批准后，建设单位应当将白蚁预防费用列入工程概预算。"},{"i":8,"n":"第八条","txt":"建设项目开工前，建设单位应当与白蚁防治单位签订白蚁预防合同。白蚁预防合同中应当载明防治范围、防治费用、质量标准、验收方法、包治期限、定期回访、双方的权利义务以及违约责任等内容。 白蚁预防包治期限不得低于15年，包治期限自工程交付使用之日起计算。"},{"i":9,"n":"第九条","txt":"白蚁防治单位应当建立健全白蚁防治质量保证体系，严格按照国家和地方有关城市房屋白蚁防治的施工技术规范和操作程序进行防治。"},{"i":10,"n":"第十条","txt":"城市房屋白蚁防治应当使用经国家有关部门批准生产的药剂。白蚁防治单位应当建立药剂进出领料制度。药剂必须专仓储存、专人管理。"},{"i":11,"n":"第十一条","txt":"房地产开发企业在进行商品房销（预）售时，应当向购房人出具该项目的《白蚁预防合同》或者其他实施房屋白蚁预防的证明文件，提供的《住宅质量保证书》中必须包括白蚁预防质量保证的内容。 建设单位在办理房屋产权登记手续时，应当向房地产行政主管部门出具按照本规定实施房屋白蚁预防的证明文件。"},{"i":12,"n":"第十二条","txt":"原有房屋和超过白蚁预防包治期限的房屋发生蚁害的，房屋所有人、使用人或者房屋管理单位应当委托白蚁防治单位进行灭治。 房屋所有人、使用人以及房屋管理单位应当配合白蚁防治单位进行白蚁的检查和灭治工作。"},{"i":13,"n":"第十三条","txt":"违反本规定第六条的规定，从事白蚁防治业务的，由房屋所在地的县级以上地方人民政府房地产行政主管部门责令改正，并可处以1万元以上3万元以下的罚款。"},{"i":14,"n":"第十四条","txt":"白蚁防治单位违反本规定第九条规定的，由房屋所在地的县级以上人民政府房地产行政主管部门责令限期改正，并处以1万元以上3万元以下的罚款。"},{"i":15,"n":"第十五条","txt":"白蚁防治单位违反本规定第十条的规定，使用不合格药物的，由房屋所在地的县级以上人民政府房地产行政主管部门责令限期改正，并处以3万元的罚款。"},{"i":16,"n":"第十六条","txt":"房地产开发企业违反本规定第十一条第一款的规定，由房屋所在地的县级以上地方人民政府房地产行政主管部门责令限期改正，并处以2万元以上3万元以下的罚款。 建设单位未按照本规定进行白蚁预防的，由房屋所在地的县级以上地方人民政府房地产行政主管部门责令限期改正，并处以1万元以上3万元以下的罚款。"},{"i":17,"n":"第十七条","txt":"房屋所有人、使用人或者房屋管理单位违反本规定第十二条规定的，房屋所在地的县级以上地方人民政府房地产行政主管部门，可以对责任人处以1000元的罚款。"},{"i":18,"n":"第十八条","txt":"白蚁防治单位违反本规定从事白蚁防治工作，给当事人造成损失的，承担相应的赔偿责任；造成重大质量事故或者其他严重后果，构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"国家机关工作人员在城市房屋白蚁防治管理工作中玩忽职守、徇私舞弊、滥用职权的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"本规定由国务院建设行政主管部门负责解释。"},{"i":21,"n":"第二十一条","txt":"本规定自1999年11月1日起施行。"}],"chengshikangzhenfangzaiguihuaguanliguiding":[{"i":1,"n":"第一条","txt":"为了提高城市的综合抗震防灾能力，减轻地震灾害，根据《中华人民共和国城乡规划法》、《中华人民共和国防震减灾法》等有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在抗震设防区的城市，编制与实施城市抗震防灾规划，必须遵守本规定。 本规定所称抗震设防区，是指地震基本烈度六度及六度以上地区（地震动峰值加速度≥0.05g的地区）。"},{"i":3,"n":"第三条","txt":"城市抗震防灾规划是城市总体规划中的专业规划。在抗震设防区的城市，编制城市总体规划时必须包括城市抗震防灾规划。城市抗震防灾规划的规划范围应当与城市总体规划相一致，并与城市总体规划同步实施。 城市总体规划与防震减灾规划应当相互协调。"},{"i":4,"n":"第四条","txt":"城市抗震防灾规划的编制要贯彻“预防为主，防、抗、避、救相结合”的方针，结合实际、因地制宜、突出重点。"},{"i":5,"n":"第五条","txt":"国务院建设行政主管部门负责全国的城市抗震防灾规划综合管理工作。 省、自治区人民政府建设行政主管部门负责本行政区域内的城市抗震防灾规划的管理工作。 直辖市、市、县人民政府城乡规划行政主管部门会同有关部门组织编制本行政区域内的城市抗震防灾规划，并监督实施。"},{"i":6,"n":"第六条","txt":"编制城市抗震防灾规划应当对城市抗震防灾有关的城市建设、地震地质、工程地质、水文地质、地形地貌、土层分布及地震活动性等情况进行深入调查研究，取得准确的基础资料。 有关单位应当依法为编制城市抗震防灾规划提供必需的资料。"},{"i":7,"n":"第七条","txt":"编制和实施城市抗震防灾规划应当符合有关的标准和技术规范，应当采用先进技术方法和手段。"},{"i":8,"n":"第八条","txt":"城市抗震防灾规划编制应当达到下列基本目标： （一）当遭受多遇地震时，城市一般功能正常； （二）当遭受相当于抗震设防烈度的地震时，城市一般功能及生命线系统基本正常，重要工矿企业能正常或者很快恢复生产； （三）当遭受罕遇地震时，城市功能不瘫痪，要害系统和生命线工程不遭受严重破坏，不发生严重的次生灾害。"},{"i":9,"n":"第九条","txt":"城市抗震防灾规划应当包括下列内容： （一）地震的危害程度估计，城市抗震防灾现状、易损性分析和防灾能力评价，不同强度地震下的震害预测等。 （二）城市抗震防灾规划目标、抗震设防标准。 （三）建设用地评价与要求： 1、城市抗震环境综合评价，包括发震断裂、地震场地破坏效应的评价等； 2、抗震设防区划，包括场地适宜性分区和危险地段、不利地段的确定，提出用地布局要求； 3、各类用地上工程设施建设的抗震性能要求。 （四）抗震防灾措施： 1、市、区级避震通道及避震疏散场地（如绿地、广场等）和避难中心的设置与人员疏散的措施； 2、城市基础设施的规划建设要求：城市交通、通讯、给排水、燃气、电力、热力等生命线系统，及消防、供油网络、医疗等重要设施的规划布局要求； 3、防止地震次生灾害要求：对地震可能引起的水灾、火灾、爆炸、放射性辐射、有毒物质扩散或者蔓延等次生灾害的防灾对策； 4、重要建（构）筑物、超高建（"},{"i":10,"n":"第十条","txt":"城市抗震防灾规划中的抗震设防标准、建设用地评价与要求、抗震防灾措施应当列为城市总体规划的强制性内容，作为编制城市详细规划的依据。"},{"i":11,"n":"第十一条","txt":"城市抗震防灾规划应当按照城市规模、重要性和抗震防灾的要求，分为甲、乙、丙三种模式： （一）位于地震基本烈度七度及七度以上地区（地震动峰值加速度≥0.10g的地区）的大城市应当按照甲类模式编制； （二）中等城市和位于地震基本烈度六度地区（地震动峰值加速度等于0.05g的地区）的大城市按照乙类模式编制； （三）其他在抗震设防区的城市按照丙类模式编制。 甲、乙、丙类模式抗震防灾规划的编制深度应当按照有关的技术规定执行。规划成果应当包括规划文本、说明、有关图纸和软件。"},{"i":12,"n":"第十二条","txt":"抗震防灾规划应当由省、自治区建设行政主管部门或者直辖市城乡规划行政主管部门组织专家评审，进行技术审查。专家评审委员会的组成应当包括规划、勘察、抗震等方面的专家和省级地震主管部门的专家。甲、乙类模式抗震防灾规划评审时应当有三名以上建设部全国城市抗震防灾规划审查委员会成员参加。全国城市抗震防灾规划审查委员会委员由国务院建设行政主管部门聘任。"},{"i":13,"n":"第十三条","txt":"经过技术审查的抗震防灾规划应当作为城市总体规划的组成部分，按照法定程序审批。"},{"i":14,"n":"第十四条","txt":"批准后的抗震防灾规划应当公布。"},{"i":15,"n":"第十五条","txt":"城市抗震防灾规划应当根据城市发展和科学技术水平等各种因素的变化，与城市总体规划同步修订。对城市抗震防灾规划进行局部修订，涉及修改总体规划强制性内容的，应当按照原规划的审批要求评审和报批。"},{"i":16,"n":"第十六条","txt":"抗震设防区城市的各项建设必须符合城市抗震防灾规划的要求。"},{"i":17,"n":"第十七条","txt":"在城市抗震防灾规划所确定的危险地段不得进行新的开发建设，已建的应当限期拆除或者停止使用。"},{"i":18,"n":"第十八条","txt":"重大建设工程和各类生命线工程的选址与建设应当避开不利地段，并采取有效的抗震措施。"},{"i":19,"n":"第十九条","txt":"地震时可能发生严重次生灾害的工程不得建在城市人口稠密地区，已建的应当逐步迁出；正在使用的，迁出前应当采取必要的抗震防灾措施。"},{"i":20,"n":"第二十条","txt":"任何单位和个人不得在抗震防灾规划确定的避震疏散场地和避震通道上搭建临时性建（构）筑物或者堆放物资。 重要建（构）筑物、超高建（构）筑物、人员密集的教育、文化、体育等设施的外部通道及间距应当满足抗震防灾的原则要求。"},{"i":21,"n":"第二十一条","txt":"直辖市、市、县人民政府城乡规划行政主管部门应当建立举报投诉制度，接受社会和舆论的监督。"},{"i":22,"n":"第二十二条","txt":"省、自治区人民政府建设行政主管部门应当定期对本行政区域内的城市抗震防灾规划的实施情况进行监督检查。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人从事建设活动违反城市抗震防灾规划的，按照《中华人民共和国城乡规划法》等有关法律、法规和规章的有关规定处罚。"},{"i":24,"n":"第二十四条","txt":"本规定自2003年11月1日起施行。本规定颁布前，城市抗震防灾规划管理规定与本规定不一致的，以本规定为准。"}],"chengshiqiaoliangjianceheyanghuweixiuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强城市桥梁的检测和养护维修管理，确保城市桥梁的完好、安全和通畅，充分发挥城市桥梁的功能，根据《中华人民共和国安全生产法》、《城市道路管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称城市桥梁，是指城市范围内连接或者跨越城市道路的，供车辆、行人通行的桥梁以及高架道路（包括轻轨高架部分）。"},{"i":3,"n":"第三条","txt":"国务院建设行政主管部门负责全国城市桥梁检测和养护维修的管理工作。 省、自治区人民政府建设行政主管部门负责本行政区域内的城市桥梁检测和养护维修活动的管理工作。 县级以上城市人民政府市政工程设施行政主管部门负责本行政区域内城市桥梁检测和养护维修活动的管理工作。"},{"i":4,"n":"第四条","txt":"城市桥梁产权人或者委托管理人，负责对其所有的或者受托管理的城市桥梁进行检测和养护维修。"},{"i":5,"n":"第五条","txt":"县级以上城市人民政府市政工程设施行政主管部门应当建立本行政区域内城市桥梁信息管理系统和技术档案。"},{"i":6,"n":"第六条","txt":"城市桥梁竣工后，按照国家有关规定进行验收。未经验收或者验收不合格，以及未设置、施划有效交通标志的桥梁，不得交付使用。"},{"i":7,"n":"第七条","txt":"城市桥梁质量保修依照《建设工程质量管理条例》的有关规定执行。"},{"i":8,"n":"第八条","txt":"政府投资（含贷款）建设的城市桥梁，其养护维修由城市人民政府委托的管理人负责。 由政府投资建设但已经出让经营权的城市桥梁，或者由企业投资建设的城市桥梁，在经营期限内，养护维修由获得经营权的企业负责养护维修。经营期满后，按照设计荷载标准以及相关技术规范，经检测评估确认合格后，方可交还城市人民政府管理。 社会力量投资修建的公益性城市桥梁，其养护维修由城市人民政府委托的管理人负责。"},{"i":9,"n":"第九条","txt":"单位自建的用于专业用途的桥梁，由自建单位负责养护维修。"},{"i":10,"n":"第十条","txt":"县级以上城市人民政府市政工程设施行政主管部门应当编制城市桥梁养护维修的中长期规划和年度计划，报城市人民政府批准后实施。 城市桥梁产权人或者委托管理人应当编制城市桥梁养护维修的中长期规划和年度计划，报城市人民政府市政工程设施行政主管部门批准后实施。"},{"i":11,"n":"第十一条","txt":"城市桥梁的养护维修费用由城市桥梁产权人或者委托管理人依据养护维修年度计划，并参照城市道路养护工程估算定额指标等规定确定。"},{"i":12,"n":"第十二条","txt":"城市桥梁产权人或者委托管理人应当按照养护维修年度计划和技术规范对城市桥梁进行养护。城市人民政府市政工程设施行政主管部门应当按照计划定期对城市桥梁养护情况进行检查。"},{"i":13,"n":"第十三条","txt":"城市桥梁产权人或者委托管理人应当按照有关规定，在城市桥梁上设置承载能力、限高等标志，并保持其完好、清晰。"},{"i":14,"n":"第十四条","txt":"城市人民政府市政工程设施行政主管部门应当根据城市桥梁的具体技术特点、结构安全条件等情况，确定城市桥梁的施工控制范围。 在城市桥梁施工控制范围内从事河道疏浚、挖掘、打桩、地下管道顶进、爆破等作业的单位和个人，在取得施工许可证前应当先经城市人民政府市政工程设施行政主管部门同意，并与城市桥梁的产权人签订保护协议，采取保护措施后，方可施工。"},{"i":15,"n":"第十五条","txt":"城市人民政府市政工程设施行政主管部门应当经常检查城市桥梁施工控制范围内的施工作业情况，避免城市桥梁发生损伤。"},{"i":16,"n":"第十六条","txt":"超限机动车辆、履带车、铁轮车等需经过城市桥梁的，在报公安交通管理部门审批前，应当先经城市人民政府市政工程设施行政主管部门同意，并采取相应技术措施后，方可通行。"},{"i":17,"n":"第十七条","txt":"在城市桥梁上架设各种市政管线、电力线、电信线等，应当先经原设计单位提出技术安全意见，报城市人民政府市政工程设施行政主管部门批准后，方可实施。"},{"i":18,"n":"第十八条","txt":"在城市桥梁上设置大型广告、悬挂物等辅助物的，应当出具相应的风载、荷载实验报告以及原设计单位的技术安全意见，报城市人民政府市政工程设施行政主管部门批准后，方可实施。"},{"i":19,"n":"第十九条","txt":"城市桥梁产权人或者委托管理人应当制定所负责管理的城市桥梁的安全抢险预备方案，明确固定的抢险队伍，并签订安全责任书，确定安全责任人。"},{"i":20,"n":"第二十条","txt":"县级以上城市人民政府市政工程设施行政主管部门应当建立、健全城市桥梁检测评估制度，组织实施对城市桥梁的检测评估。 城市桥梁的检测评估分为经常性检查、定期检测、特殊检测。 经常性检查是指对城市桥梁及其附属设施的技术状况进行日常巡检。 定期检测是指对城市桥梁及其附属设施的可靠性等进行定期检查评估。 特殊检测是指当城市桥梁遭遇地震、洪水、台风等自然灾害或者车船撞击等人为事故后所进行的可靠性检测评估。"},{"i":21,"n":"第二十一条","txt":"城市桥梁产权人或者委托管理人应当委托具有相应资格的城市桥梁检测评估机构进行城市桥梁的检测评估。"},{"i":22,"n":"第二十二条","txt":"城市桥梁检测评估机构应当根据有关技术规范，提供真实、准确的检测数据和评估结论，评定桥梁的技术等级。"},{"i":23,"n":"第二十三条","txt":"经过检测评估，确定城市桥梁的承载能力下降，但尚未构成危桥的，城市桥梁产权人和委托管理人应当及时设置警示标志，并立即采取加固等安全措施。 经检测评估判定为危桥的，城市桥梁产权人和委托管理人应当立即采取措施，设置显著的警示标志，并在二十四小时内，向城市人民政府市政工程设施行政主管部门报告；城市人民政府市政工程设施行政主管部门应当提出处理意见，并限期排除危险；在危险排除之前，不得使用或者转让。 城市桥梁产权人或者委托管理人对检测评估结论有异议的，可以依法申请重新检测评估。但重新检测评估结论未果之前，不得停止执行前款规定。"},{"i":24,"n":"第二十四条","txt":"县级以上城市人民政府市政工程设施行政主管部门应当将城市桥梁每次的检测评估结果及评定的技术等级及时归档。"},{"i":25,"n":"第二十五条","txt":"城市桥梁产权人或者委托管理人有下列行为之一的，由城市人民政府市政工程设施行政主管部门责令限期改正，并可处1000元以上5000元以下的罚款： （一）未按照规定编制城市桥梁养护维修的中长期规划和年度计划，或者未经批准即实施的； （二）未按照规定设置相应的标志，并保持其完好、清晰的； （三）未按照规定委托具有相应资格的机构对城市桥梁进行检测评估的； （四）未按照规定制定城市桥梁的安全抢险预备方案的； （五）未按照规定对城市桥梁进行养护维修的。"},{"i":26,"n":"第二十六条","txt":"单位或者个人擅自在城市桥梁上架设各类管线、设置广告等辅助物的，由城市人民政府市政工程设施行政主管部门责令限期改正，并可处2万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":27,"n":"第二十七条","txt":"单位和个人擅自在城市桥梁施工控制范围内从事本办法第十四条第二款规定的活动的，由城市人民政府市政工程设施行政主管部门责令限期改正，并可处1万元以上3万元以下的罚款。"},{"i":28,"n":"第二十八条","txt":"违反本办法第十六条　、第二十三条规定，由城市人民政府市政工程设施行政主管部门责令限期改正，并可处1万元以上2万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":29,"n":"第二十九条","txt":"城市人民政府市政工程设施行政主管部门工作人员玩忽职守、滥用职权、徇私舞弊的，应当依法给予行政处分。"},{"i":30,"n":"第三十条","txt":"建制镇的桥梁的检测和养护维修管理参照本办法执行。具体办法由省、自治区人民政府建设行政主管部门和直辖市人民政府市政工程设施行政主管部门制定。"},{"i":31,"n":"第三十一条","txt":"列入文物保护单位的城市桥梁的检测和养护维修，还应当符合《文物保护法》的有关规定。"},{"i":32,"n":"第三十二条","txt":"本规定自2004年1月1日起施行。"}],"chengshizhaomingguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强城市照明管理，促进能源节约，改善城市照明环境，制定本规定。"},{"i":2,"n":"第二条","txt":"城市照明的规划、建设、维护和监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"城市照明工作应当遵循以人为本、经济适用、节能环保、美化环境的原则，严格控制公用设施和大型建筑物装饰性景观照明能耗。"},{"i":4,"n":"第四条","txt":"国务院住房和城乡建设主管部门指导全国的城市照明工作。 省、自治区人民政府住房和城乡建设主管部门对本行政区域内城市照明实施监督管理。 城市人民政府确定的城市照明主管部门负责本行政区域内城市照明管理的具体工作。"},{"i":5,"n":"第五条","txt":"城市照明主管部门应当对在城市照明节能工作中做出显著成绩的单位和个人给予表彰或者奖励。"},{"i":6,"n":"第六条","txt":"城市照明主管部门应当会同有关部门，依据城市总体规划，组织编制城市照明专项规划，报本级人民政府批准后组织实施。"},{"i":7,"n":"第七条","txt":"城市照明主管部门应当委托具备相应资质的单位承担城市照明专项规划的编制工作。 编制城市照明专项规划，应当根据城市经济社会发展水平，结合城市自然地理环境、人文条件，按照城市总体规划确定的城市功能分区，对不同区域的照明效果提出要求。"},{"i":8,"n":"第八条","txt":"从事城市照明工程勘察、设计、施工、监理的单位应当具备相应的资质；相关专业技术人员应当依法取得相应的执业资格。"},{"i":9,"n":"第九条","txt":"城市照明主管部门应当依据城市照明专项规划，组织制定城市照明设施建设年度计划，报同级人民政府批准后实施。"},{"i":10,"n":"第十条","txt":"新建、改建城市照明设施，应当根据城市照明专项规划确定各类区域照明的亮度、能耗标准，并符合国家有关标准规范。"},{"i":11,"n":"第十一条","txt":"政府投资的城市照明设施的建设经费，应当纳入城市建设资金计划。 国家鼓励社会资金用于城市照明设施的建设和维护。"},{"i":12,"n":"第十二条","txt":"新建、改建城市道路项目的功能照明装灯率应当达到100%。 与城市道路、住宅区及重要建（构）筑物配套的城市照明设施，应当按照城市照明规划建设，与主体工程同步设计、施工、验收和使用。"},{"i":13,"n":"第十三条","txt":"对符合城市照明设施安装条件的建（构）筑物和支撑物，可以在不影响其功能和周边环境的前提下，安装照明设施。"},{"i":14,"n":"第十四条","txt":"国家支持城市照明科学技术研究，推广使用节能、环保的照明新技术、新产品，开展绿色照明活动，提高城市照明的科学技术水平。"},{"i":15,"n":"第十五条","txt":"国家鼓励在城市照明设施建设和改造中安装和使用太阳能等可再生能源利用系统。"},{"i":16,"n":"第十六条","txt":"城市照明主管部门应当依据城市照明规划，制定城市照明节能计划和节能技术措施，优先发展和建设功能照明，严格控制景观照明的范围、亮度和能耗密度，并依据国家有关规定，限时全部淘汰低效照明产品。"},{"i":17,"n":"第十七条","txt":"城市照明主管部门应当定期开展节能教育和岗位节能培训，提高城市照明维护单位的节能水平。"},{"i":18,"n":"第十八条","txt":"城市照明主管部门应当建立城市照明能耗考核制度，定期对城市景观照明能耗等情况进行检查。"},{"i":19,"n":"第十九条","txt":"城市照明维护单位应当建立和完善分区、分时、分级的照明节能控制措施，严禁使用高耗能灯具，积极采用高效的光源和照明灯具、节能型的镇流器和控制电器以及先进的灯控方式，优先选择通过认证的高效节能产品。 任何单位不得在城市景观照明中有过度照明等超能耗标准的行为。"},{"i":20,"n":"第二十条","txt":"城市照明可以采取合同能源管理的方式，选择专业性能源管理公司管理城市照明设施。"},{"i":21,"n":"第二十一条","txt":"城市照明主管部门应当建立健全各项规章制度，加强对城市照明设施的监管，保证城市照明设施的完好和正常运行。"},{"i":22,"n":"第二十二条","txt":"城市照明设施的管理和维护，应当符合有关标准规范。"},{"i":23,"n":"第二十三条","txt":"城市照明主管部门可以采取招标投标的方式确定城市照明设施维护单位，具体负责政府投资的城市照明设施的维护工作。"},{"i":24,"n":"第二十四条","txt":"非政府投资建设的城市照明设施由建设单位负责维护；符合下列条件的，办理资产移交手续后，可以移交城市照明主管部门管理： （一）符合城市照明专项规划及有关标准； （二）提供必要的维护、运行条件； （三）提供完整的竣工验收资料； （四）城市人民政府规定的其他条件和范围。"},{"i":25,"n":"第二十五条","txt":"政府预算安排的城市照明设施运行维护费用应当专款专用，保证城市照明设施的正常运行。"},{"i":26,"n":"第二十六条","txt":"城市照明设施维护单位应当定期对照明灯具进行清扫，改善照明效果，并可以采取精确等量分时照明等节能措施。"},{"i":27,"n":"第二十七条","txt":"因自然生长而不符合安全距离标准的树木，由城市照明主管部门通知有关单位及时修剪；因不可抗力致使树木严重危及城市照明设施安全运行的，城市照明维护单位可以采取紧急措施进行修剪，并及时报告城市园林绿化主管部门。"},{"i":28,"n":"第二十八条","txt":"任何单位和个人都应当保护城市照明设施，不得实施下列行为： （一）在城市照明设施上刻划、涂污； （二）在城市照明设施安全距离内，擅自植树、挖坑取土或者设置其他物体，或者倾倒含酸、碱、盐等腐蚀物或者具有腐蚀性的废渣、废液； （三）擅自在城市照明设施上张贴、悬挂、设置宣传品、广告； （四）擅自在城市照明设施上架设线缆、安置其它设施或者接用电源； （五）擅自迁移、拆除、利用城市照明设施； （六）其他可能影响城市照明设施正常运行的行为。"},{"i":29,"n":"第二十九条","txt":"损坏城市照明设施的单位和个人，应当立即保护事故现场，防止事故扩大，并通知城市照明主管部门。"},{"i":30,"n":"第三十条","txt":"不具备相应资质的单位和不具备相应执业资格证书的专业技术人员从事城市照明工程勘察、设计、施工、监理的，依照有关法律、法规和规章予以处罚。"},{"i":31,"n":"第三十一条","txt":"违反本规定，在城市景观照明中有过度照明等超能耗标准行为的，由城市照明主管部门责令限期改正；逾期未改正的，处以1000元以上3万元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"违反本规定，有第二十八条规定行为之一的，由城市照明主管部门责令限期改正，对个人处以200元以上1000元以下的罚款；对单位处以1000元以上3万元以下的罚款；造成损失的，依法赔偿损失。"},{"i":33,"n":"第三十三条","txt":"城市照明主管部门工作人员玩忽职守、滥用职权、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"本规定下列用语的含义是： （一）城市照明是指在城市规划区内城市道路、隧道、广场、公园、公共绿地、名胜古迹以及其他建（构）筑物的功能照明或者景观照明。 （二）功能照明是指通过人工光以保障人们出行和户外活动安全为目的的照明。 （三）景观照明是指在户外通过人工光以装饰和造景为目的的照明。 （四）城市照明设施是指用于城市照明的照明器具以及配电、监控、节能等系统的设备和附属设施等。"},{"i":35,"n":"第三十五条","txt":"镇、乡和未设镇建制工矿区的照明管理，可以参照本规定执行。 各地可以根据本规定制定实施细则。"},{"i":36,"n":"第三十六条","txt":"本规定自2010年7月1日起施行，《城市道路照明设施管理规定》（建设部令第21号）、《建设部关于修改〈城市道路照明设施管理规定〉的决定》（建设部令第104号）同时废止。"}],"chengshishenghuolajiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强城市生活垃圾管理，改善城市市容和环境卫生，根据《中华人民共和国固体废物污染环境防治法》、《城市市容和环境卫生管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内城市生活垃圾的清扫、收集、运输、处置及相关管理活动。"},{"i":3,"n":"第三条","txt":"城市生活垃圾的治理，实行减量化、资源化、无害化和谁产生、谁依法负责的原则。 国家采取有利于城市生活垃圾综合利用的经济、技术政策和措施，提高城市生活垃圾治理的科学技术水平，鼓励对城市生活垃圾实行充分回收和合理利用。"},{"i":4,"n":"第四条","txt":"产生城市生活垃圾的单位和个人，应当按照城市人民政府确定的生活垃圾处理费收费标准和有关规定缴纳城市生活垃圾处理费。 城市生活垃圾处理费应当专项用于城市生活垃圾收集、运输和处置，严禁挪作他用。"},{"i":5,"n":"第五条","txt":"国务院建设主管部门负责全国城市生活垃圾管理工作。 省、自治区人民政府建设主管部门负责本行政区域内城市生活垃圾管理工作。 直辖市、市、县人民政府建设（环境卫生）主管部门负责本行政区域内城市生活垃圾的管理工作。"},{"i":6,"n":"第六条","txt":"任何单位和个人都应当遵守城市生活垃圾管理的有关规定，并有权对违反本办法的单位和个人进行检举和控告。"},{"i":7,"n":"第七条","txt":"直辖市、市、县人民政府建设（环境卫生）主管部门应当会同城市规划等有关部门，依据城市总体规划和本地区国民经济和社会发展计划等，制定城市生活垃圾治理规划，统筹安排城市生活垃圾收集、处置设施的布局、用地和规模。 制定城市生活垃圾治理规划，应当广泛征求公众意见。"},{"i":8,"n":"第八条","txt":"城市生活垃圾收集、处置设施用地应当纳入城市黄线保护范围，任何单位和个人不得擅自占用或者改变其用途。"},{"i":9,"n":"第九条","txt":"城市生活垃圾收集、处置设施建设，应当符合城市生活垃圾治理规划和国家有关技术标准。"},{"i":10,"n":"第十条","txt":"从事新区开发、旧区改建和住宅小区开发建设的单位，以及机场、码头、车站、公园、商店等公共设施、场所的经营管理单位，应当按照城市生活垃圾治理规划和环境卫生设施的设置标准，配套建设城市生活垃圾收集设施。"},{"i":11,"n":"第十一条","txt":"城市生活垃圾收集、处置设施工程建设的勘察、设计、施工和监理，应当严格执行国家有关法律、法规和技术标准。"},{"i":12,"n":"第十二条","txt":"城市生活垃圾收集、处置设施工程竣工后，建设单位应当依法组织竣工验收，并在竣工验收后三个月内，依法向当地人民政府建设主管部门和环境卫生主管部门报送建设工程项目档案。未经验收或者验收不合格的，不得交付使用。"},{"i":13,"n":"第十三条","txt":"任何单位和个人不得擅自关闭、闲置或者拆除城市生活垃圾处置设施、场所；确有必要关闭、闲置或者拆除的，必须经所在地县级以上地方人民政府建设（环境卫生）主管部门和环境保护主管部门核准，并采取措施，防止污染环境。"},{"i":14,"n":"第十四条","txt":"申请关闭、闲置或者拆除城市生活垃圾处置设施、场所的，应当提交以下材料： （一）书面申请； （二）权属关系证明材料； （三）丧失使用功能或其使用功能被其他设施替代的证明； （四）防止环境污染的方案； （五）拟关闭、闲置或者拆除设施的现状图及拆除方案； （六）拟新建设施设计图； （七）因实施城市规划需要闲置、关闭或者拆除的，还应当提供规划、建设主管部门的批准文件。"},{"i":15,"n":"第十五条","txt":"城市生活垃圾应当逐步实行分类投放、收集和运输。具体办法，由直辖市、市、县人民政府建设（环境卫生）主管部门根据国家标准和本地区实际制定。"},{"i":16,"n":"第十六条","txt":"单位和个人应当按照规定的地点、时间等要求，将生活垃圾投放到指定的垃圾容器或者收集场所。废旧家具等大件垃圾应当按规定时间投放在指定的收集场所。 城市生活垃圾实行分类收集的地区，单位和个人应当按照规定的分类要求，将生活垃圾装入相应的垃圾袋内，投入指定的垃圾容器或者收集场所。 宾馆、饭店、餐馆以及机关、院校等单位应当按照规定单独收集、存放本单位产生的餐厨垃圾，并交符合本办法要求的城市生活垃圾收集、运输企业运至规定的城市生活垃圾处理场所。 禁止随意倾倒、抛洒或者堆放城市生活垃圾。"},{"i":17,"n":"第十七条","txt":"从事城市生活垃圾经营性清扫、收集、运输的企业，应当取得城市生活垃圾经营性清扫、收集、运输服务许可证。 未取得城市生活垃圾经营性清扫、收集、运输服务许可证的企业，不得从事城市生活垃圾经营性清扫、收集、运输活动。"},{"i":18,"n":"第十八条","txt":"直辖市、市、县建设（环境卫生）主管部门应当通过招投标等公平竞争方式作出城市生活垃圾经营性清扫、收集、运输许可的决定，向中标人颁发城市生活垃圾经营性清扫、收集、运输服务许可证。 直辖市、市、县建设（环境卫生）主管部门应当与中标人签订城市生活垃圾清扫、收集、运输经营协议。 城市生活垃圾清扫、收集、运输经营协议应当明确约定经营期限、服务标准等内容，作为城市生活垃圾清扫、收集、运输服务许可证的附件。"},{"i":19,"n":"第十九条","txt":"从事城市生活垃圾经营性清扫、收集、运输服务的企业，应当具备以下条件： （一）机械清扫能力达到总清扫能力的20％以上，机械清扫车辆包括洒水车和清扫保洁车辆。机械清扫车辆应当具有自动洒水、防尘、防遗撒、安全警示功能，安装车辆行驶及清扫过程记录仪； （二）垃圾收集应当采用全密闭运输工具，并应当具有分类收集功能； （三）垃圾运输应当采用全密闭自动卸载车辆或船只，具有防臭味扩散、防遗撒、防渗沥液滴漏功能，安装行驶及装卸记录仪； （四）具有健全的技术、质量、安全和监测管理制度并得到有效执行； （五）具有合法的道路运输经营许可证、车辆行驶证； （六）具有固定的办公及机械、设备、车辆、船只停放场所。"},{"i":20,"n":"第二十条","txt":"从事城市生活垃圾经营性清扫、收集、运输的企业应当履行以下义务： （一）按照环境卫生作业标准和作业规范，在规定的时间内及时清扫、收运城市生活垃圾； （二）将收集的城市生活垃圾运到直辖市、市、县人民政府建设（环境卫生）主管部门认可的处置场所； （三）清扫、收运城市生活垃圾后，对生活垃圾收集设施及时保洁、复位，清理作业场地，保持生活垃圾收集设施和周边环境的干净整洁； （四）用于收集、运输城市生活垃圾的车辆、船舶应当做到密闭、完好和整洁。"},{"i":21,"n":"第二十一条","txt":"从事城市生活垃圾经营性清扫、收集、运输的企业，禁止实施下列行为： （一）任意倾倒、抛洒或者堆放城市生活垃圾； （二）擅自停业、歇业； （三）在运输过程中沿途丢弃、遗撒生活垃圾。"},{"i":22,"n":"第二十二条","txt":"工业固体废弃物、危险废物应当按照国家有关规定单独收集、运输，严禁混入城市生活垃圾。"},{"i":23,"n":"第二十三条","txt":"城市生活垃圾应当在城市生活垃圾转运站、处理厂（场）处置。 任何单位和个人不得任意处置城市生活垃圾。"},{"i":24,"n":"第二十四条","txt":"城市生活垃圾处置所采用的技术、设备、材料，应当符合国家有关城市生活垃圾处理技术标准的要求，防止对环境造成污染。"},{"i":25,"n":"第二十五条","txt":"从事城市生活垃圾经营性处置的企业，应当向所在地直辖市、市、县人民政府建设（环境卫生）主管部门取得城市生活垃圾经营性处置服务许可证。 未取得城市生活垃圾经营性处置服务许可证，不得从事城市生活垃圾经营性处置活动。"},{"i":26,"n":"第二十六条","txt":"直辖市、市、县建设（环境卫生）主管部门应当通过招投标等公平竞争方式作出城市生活垃圾经营性处置许可的决定，向中标人颁发城市生活垃圾经营性处置服务许可证。 直辖市、市、县建设（环境卫生）主管部门应当与中标人签订城市生活垃圾处置经营协议，明确约定经营期限、服务标准等内容，并作为城市生活垃圾经营性处置服务许可证的附件。"},{"i":27,"n":"第二十七条","txt":"从事城市生活垃圾经营性处置服务的企业，应当具备以下条件： （一）卫生填埋场、堆肥厂和焚烧厂的选址符合城乡规划，并取得规划许可文件； （二）采用的技术、工艺符合国家有关标准； （三）有至少5名具有初级以上专业技术职称的人员，其中包括环境工程、机械、环境监测等专业的技术人员。技术负责人具有5年以上垃圾处理工作经历，并具有中级以上专业技术职称； （四）具有完善的工艺运行、设备管理、环境监测与保护、财务管理、生产安全、计量统计等方面的管理制度并得到有效执行； （五）生活垃圾处理设施配备沼气检测仪器，配备环境监测设施如渗沥液监测井、尾气取样孔，安装在线监测系统等监测设备并与建设（环境卫生）主管部门联网； （六）具有完善的生活垃圾渗沥液、沼气的利用和处理技术方案，卫生填埋场对不同垃圾进行分区填埋方案、生活垃圾处理的渗沥液、沼气、焚烧烟气、残渣等处理残余物达标处理排放方案； （七）有控制污染和突发事"},{"i":28,"n":"第二十八条","txt":"从事城市生活垃圾经营性处置的企业应当履行以下义务： （一）严格按照国家有关规定和技术标准，处置城市生活垃圾； （二）按照规定处理处置过程中产生的污水、废气、废渣、粉尘等，防止二次污染； （三）按照所在地建设（环境卫生）主管部门规定的时间和要求接收生活垃圾； （四）按照要求配备城市生活垃圾处置设备、设施，保证设施、设备运行良好； （五）保证城市生活垃圾处置站、场（厂）环境整洁； （六）按照要求配备合格的管理人员及操作人员； （七）对每日收运、进出场站、处置的生活垃圾进行计量，按照要求将统计数据和报表报送所在地建设（环境卫生）主管部门； （八）按照要求定期进行水、气、土壤等环境影响监测，对生活垃圾处理设施的性能和环保指标进行检测、评价，向所在地建设（环境卫生）主管部门报告检测、评价结果。"},{"i":29,"n":"第二十九条","txt":"国务院建设主管部门和省、自治区人民政府建设主管部门应当建立健全监督管理制度，对本办法的执行情况进行监督检查。 直辖市、市、县人民政府建设（环境卫生）主管部门应当对本行政区域内城市生活垃圾经营性清扫、收集、运输、处置企业执行本办法的情况进行监督检查；根据需要，可以向城市生活垃圾经营性处置企业派驻监督员。"},{"i":30,"n":"第三十条","txt":"直辖市、市、县人民政府建设（环境卫生）主管部门实施监督检查时，有权采取下列措施： （一）查阅复制有关文件和资料； （二）要求被检查的单位和个人就有关问题做出说明； （三）进入现场开展检查； （四）责令有关单位和个人改正违法行为。 有关单位和个人应当支持配合监督检查并提供工作方便，不得妨碍与阻挠监督检查人员依法执行职务。"},{"i":31,"n":"第三十一条","txt":"直辖市、市、县人民政府建设（环境卫生）主管部门应当委托具有计量认证资格的机构，定期对城市生活垃圾处理场站的垃圾处置数量、质量和环境影响进行监测。"},{"i":32,"n":"第三十二条","txt":"城市生活垃圾经营性清扫、收集、运输、处置服务许可有效期届满需要继续从事城市生活垃圾经营性清扫、收集、运输、处置活动的，应当在有效期届满30日前向原发证机关申请办理延续手续。准予延续的，直辖市、市、县建设（环境卫生）主管部门应当与城市生活垃圾经营性清扫、收集、运输、处置企业重新订立经营协议。"},{"i":33,"n":"第三十三条","txt":"有下列情形之一的，可以依法撤销许可证书： （一）建设（环境卫生）主管部门工作人员滥用职权、玩忽职守作出准予城市生活垃圾清扫、收集、运输或者处置许可决定的； （二）超越法定职权作出准予城市生活垃圾清扫、收集、运输或者处置许可决定的； （三）违反法定程序作出准予城市生活垃圾清扫、收集、运输或者处置许可决定的； （四）对不符合许可条件的申请人作出准予许可的； （五）依法可以撤销许可的其他情形。 申请人以欺骗、贿赂等不正当手段取得许可的，应当予以撤销。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，从事城市生活垃圾经营性清扫、收集、运输或者处置的企业应当向原许可机关提出注销许可证的申请，交回许可证书；原许可机关应当办理注销手续，公告其许可证书作废： （一）许可事项有效期届满，未依法申请延期的； （二）企业依法终止的； （三）许可证依法被撤回、撤销或者吊销的； （四）法律、法规规定的其他应当注销的情形。"},{"i":35,"n":"第三十五条","txt":"从事城市生活垃圾经营性清扫、收集、运输、处置的企业需停业、歇业的，应当提前半年向所在地直辖市、市、县人民政府建设（环境卫生）主管部门报告，经同意后方可停业或者歇业。 直辖市、市、县人民政府建设（环境卫生）主管部门应当在城市生活垃圾经营性清扫、收集、运输、处置企业停业或者歇业前，落实保障及时清扫、收集、运输、处置城市生活垃圾的措施。"},{"i":36,"n":"第三十六条","txt":"直辖市、市、县人民政府建设（环境卫生）主管部门应当会同有关部门制定城市生活垃圾清扫、收集、运输和处置应急预案，建立城市生活垃圾应急处理系统，确保紧急或者特殊情况下城市生活垃圾的正常清扫、收集、运输和处置。 从事城市生活垃圾经营性清扫、收集、运输和处置的企业，应当制定突发事件生活垃圾污染防范的应急方案，并报所在地直辖市、市、县人民政府建设（环境卫生）主管部门备案。"},{"i":37,"n":"第三十七条","txt":"从事城市生活垃圾经营性清扫、收集、运输或者处置的企业应当按照国家劳动保护的要求和规定，改善职工的工作条件，采取有效措施，逐步提高职工的工资和福利待遇，做好职工的卫生保健和技术培训工作。"},{"i":38,"n":"第三十八条","txt":"单位和个人未按规定缴纳城市生活垃圾处理费的，由直辖市、市、县人民政府建设（环境卫生）主管部门责令限期改正，逾期不改正的，对单位可处以应交城市生活垃圾处理费三倍以下且不超过3万元的罚款，对个人可处以应交城市生活垃圾处理费三倍以下且不超过1000元的罚款。"},{"i":39,"n":"第三十九条","txt":"违反本办法第十条规定，未按照城市生活垃圾治理规划和环境卫生设施标准配套建设城市生活垃圾收集设施的，由直辖市、市、县人民政府建设（环境卫生）主管部门责令限期改正，并可处以1万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"违反本办法第十二条规定，城市生活垃圾处置设施未经验收或者验收不合格投入使用的，由直辖市、市、县人民政府建设主管部门责令改正，处工程合同价款2%以上4%以下的罚款；造成损失的，应当承担赔偿责任。"},{"i":41,"n":"第四十一条","txt":"违反本办法第十三条规定，未经批准擅自关闭、闲置或者拆除城市生活垃圾处置设施、场所的，由直辖市、市、县人民政府建设（环境卫生）主管部门责令停止违法行为，限期改正，处以1万元以上10万元以下的罚款。"},{"i":42,"n":"第四十二条","txt":"违反本办法第十六条规定，随意倾倒、抛洒、堆放城市生活垃圾的，由直辖市、市、县人民政府建设（环境卫生）主管部门责令停止违法行为，限期改正，对单位处以5000元以上5万元以下的罚款。个人有以上行为的，处以200元以下的罚款。"},{"i":43,"n":"第四十三条","txt":"违反本办法第十七条、第二十五条规定，未经批准从事城市生活垃圾经营性清扫、收集、运输或者处置活动的，由直辖市、市、县人民政府建设（环境卫生）主管部门责令停止违法行为，并处以3万元的罚款。"},{"i":44,"n":"第四十四条","txt":"违反本办法规定，从事城市生活垃圾经营性清扫、收集、运输的企业在运输过程中沿途丢弃、遗撒生活垃圾的，由直辖市、市、县人民政府建设（环境卫生）卫生主管部门责令停止违法行为，限期改正，处以5000元以上5万元以下的罚款。"},{"i":45,"n":"第四十五条","txt":"从事生活垃圾经营性清扫、收集、运输的企业不履行本办法第二十条规定义务的，由直辖市、市、县人民政府建设（环境卫生）主管部门责令限期改正，并可处以5000元以上3万元以下的罚款；城市生活垃圾经营性处置企业不履行本办法第二十八条规定义务的，由直辖市、市、县人民政府建设（环境卫生）主管部门责令限期改正，并可处以3万元以上10万元以下的罚款。造成损失的，依法承担赔偿责任。"},{"i":46,"n":"第四十六条","txt":"违反本办法规定，从事城市生活垃圾经营性清扫、收集、运输的企业，未经批准擅自停业、歇业的，由直辖市、市、县人民政府建设（环境卫生）主管部门责令限期改正，并可处以1万元以上3万元以下罚款；从事城市生活垃圾经营性处置的企业，未经批准擅自停业、歇业的，由直辖市、市、县人民政府建设（环境卫生）主管部门责令限期改正，并可处以5万元以上10万元以下罚款。造成损失的，依法承担赔偿责任。"},{"i":47,"n":"第四十七条","txt":"违反本办法规定的职权和程序，核发城市生活垃圾清扫、收集、运输、处理许可证的，由上级主管机关责令改正，并对其主管人员及其他直接责任人员给予行政处分；构成犯罪的，应当追究刑事责任。 国家机关工作人员在城市生活垃圾监督管理工作中，玩忽职守、滥用职权、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"城市建筑垃圾的管理适用《城市建筑垃圾管理规定》（建设部令第139号）。"},{"i":49,"n":"第四十九条","txt":"本办法的规定适用于从事城市生活垃圾非经营性清扫、收集、运输、处置的单位；但是，有关行政许可的规定以及第四十五条、第四十六条的规定除外。"},{"i":50,"n":"第五十条","txt":"城市生活垃圾清扫、收集、运输服务许可证和城市生活垃圾处置服务许可证由国务院建设主管部门统一规定格式，省、自治区人民政府建设主管部门和直辖市人民政府建设（环境卫生）主管部门组织印制。"},{"i":51,"n":"第五十一条","txt":"本办法自2007年7月1日起施行。1993年8月10日建设部颁布的《城市生活垃圾管理办法》（建设部令第27号）同时废止。"}],"chengshiguanlizhifabanfa":[{"i":1,"n":"第一条","txt":"为了规范城市管理执法工作，提高执法和服务水平，维护城市管理秩序，保护公民、法人和其他组织的合法权益，根据行政处罚法、行政强制法等法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"城市、县人民政府所在地镇建成区内的城市管理执法活动以及执法监督活动，适用本办法。 本办法所称城市管理执法，是指城市管理执法主管部门在城市管理领域根据法律法规规章规定履行行政处罚、行政强制等行政执法职责的行为。"},{"i":3,"n":"第三条","txt":"城市管理执法应当遵循以人为本、依法治理、源头治理、权责一致、协调创新的原则，坚持严格规范公正文明执法。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责全国城市管理执法的指导监督协调工作。 各省、自治区人民政府住房城乡建设主管部门负责本行政区域内城市管理执法的指导监督考核协调工作。 城市、县人民政府城市管理执法主管部门负责本行政区域内的城市管理执法工作。"},{"i":5,"n":"第五条","txt":"城市管理执法主管部门应当推动建立城市管理协调机制，协调有关部门做好城市管理执法工作。"},{"i":6,"n":"第六条","txt":"城市管理执法主管部门应当加强城市管理法律法规规章的宣传普及工作，增强全民守法意识，共同维护城市管理秩序。"},{"i":7,"n":"第七条","txt":"城市管理执法主管部门应当积极为公众监督城市管理执法活动提供条件。"},{"i":8,"n":"第八条","txt":"城市管理执法的行政处罚权范围依照法律法规和国务院有关规定确定，包括住房城乡建设领域法律法规规章规定的行政处罚权，以及环境保护管理、工商管理、交通管理、水务管理、食品药品监管方面与城市管理相关部分的行政处罚权。"},{"i":9,"n":"第九条","txt":"需要集中行使的城市管理执法事项，应当同时具备下列条件： （一）与城市管理密切相关； （二）与群众生产生活密切相关、多头执法扰民问题突出； （三）执法频率高、专业技术要求适宜； （四）确实需要集中行使的。"},{"i":10,"n":"第十条","txt":"城市管理执法主管部门依法相对集中行使行政处罚权的，可以实施法律法规规定的与行政处罚权相关的行政强制措施。"},{"i":11,"n":"第十一条","txt":"城市管理执法事项范围确定后，应当向社会公开。"},{"i":12,"n":"第十二条","txt":"城市管理执法主管部门集中行使原由其他部门行使的行政处罚权的，应当与其他部门明确职责权限和工作机制。"},{"i":13,"n":"第十三条","txt":"城市管理执法主管部门按照权责清晰、事权统一、精简效能的原则设置执法队伍。"},{"i":14,"n":"第十四条","txt":"直辖市、设区的市城市管理执法推行市级执法或者区级执法。 直辖市、设区的市的城市管理执法事项，市辖区人民政府城市管理执法主管部门能够承担的，可以实行区级执法。 直辖市、设区的市人民政府城市管理执法主管部门可以承担跨区域和重大复杂违法案件的查处。"},{"i":15,"n":"第十五条","txt":"市辖区人民政府城市管理执法主管部门可以向街道派出执法机构。直辖市、设区的市人民政府城市管理执法主管部门可以向市辖区或者街道派出执法机构。 派出机构以设立该派出机构的城市管理执法主管部门的名义，在所辖区域范围内履行城市管理执法职责。"},{"i":16,"n":"第十六条","txt":"城市管理执法主管部门应当依据国家相关标准，提出确定城市管理执法人员数量的合理意见，并按程序报同级编制主管部门审批。"},{"i":17,"n":"第十七条","txt":"城市管理执法人员应当持证上岗。 城市管理执法主管部门应当定期开展执法人员的培训和考核。"},{"i":18,"n":"第十八条","txt":"城市管理执法主管部门可以配置城市管理执法协管人员，配合执法人员从事执法辅助事务。 协管人员从事执法辅助事务产生的法律后果，由本级城市管理执法主管部门承担。 城市管理执法主管部门应当严格协管人员的招录程序、资格条件，规范执法辅助行为，建立退出机制。"},{"i":19,"n":"第十九条","txt":"城市管理执法人员依法开展执法活动和协管人员依法开展执法辅助事务，受法律保护。"},{"i":20,"n":"第二十条","txt":"城市管理执法主管部门应当按照规定配置执法执勤用车以及调查取证设施、通讯设施等装备配备，并规范管理。"},{"i":21,"n":"第二十一条","txt":"城市管理执法制式服装、标志标识应当全国统一，由国务院住房城乡建设主管部门制定式样和标准。"},{"i":22,"n":"第二十二条","txt":"城市管理执法应当保障必要的工作经费。 工作经费按规定已列入同级财政预算，城市管理执法主管部门不得以罚没收入作为经费来源。"},{"i":23,"n":"第二十三条","txt":"城市管理领域应当建立数字化城市管理平台，实现城市管理的信息采集、指挥调度、督察督办、公众参与等功能，并逐步实现与有关部门信息平台的共享。 城市管理领域应当整合城市管理相关电话服务平台，建立统一的城市管理服务热线。"},{"i":24,"n":"第二十四条","txt":"城市管理执法需要实施鉴定、检验、检测的，城市管理执法主管部门可以开展鉴定、检验、检测，或者按照有关规定委托第三方实施。"},{"i":25,"n":"第二十五条","txt":"城市管理执法主管部门依照法定程序开展执法活动，应当保障当事人依法享有的陈述、申辩、听证等权利。"},{"i":26,"n":"第二十六条","txt":"城市管理执法主管部门开展执法活动，应当根据违法行为的性质和危害后果依法给予相应的行政处罚。 对违法行为轻微的，可以采取教育、劝诫、疏导等方式予以纠正。"},{"i":27,"n":"第二十七条","txt":"城市管理执法人员开展执法活动，可以依法采取以下措施： （一）以勘验、拍照、录音、摄像等方式进行现场取证； （二）在现场设置警示标志； （三）询问案件当事人、证人等； （四）查阅、调取、复制有关文件资料等； （五）法律、法规规定的其他措施。"},{"i":28,"n":"第二十八条","txt":"城市管理执法主管部门应当依法、全面、客观收集相关证据，规范建立城市管理执法档案并完整保存。 城市管理执法主管部门应当运用执法记录仪、视频监控等技术，实现执法活动全过程记录。"},{"i":29,"n":"第二十九条","txt":"城市管理执法主管部门对查封、扣押的物品，应当妥善保管，不得使用、截留、损毁或者擅自处置。查封、扣押的物品属非法物品的，移送有关部门处理。"},{"i":30,"n":"第三十条","txt":"城市管理执法主管部门不得对罚款、没收违法所得设定任务和目标。 罚款、没收违法所得的款项，应当按照规定全额上缴。"},{"i":31,"n":"第三十一条","txt":"城市管理执法主管部门应当确定法制审核机构，配备一定比例符合条件的法制审核人员，对重大执法决定在执法主体、管辖权限、执法程序、事实认定、法律适用等方面进行法制审核。"},{"i":32,"n":"第三十二条","txt":"城市管理执法主管部门开展执法活动，应当使用统一格式的行政执法文书。"},{"i":33,"n":"第三十三条","txt":"行政执法文书的送达，依照民事诉讼法等法律规定执行。 当事人提供送达地址或者同意电子送达的，可以按照其提供的地址或者传真、电子邮件送达。 采取直接、留置、邮寄、委托、转交等方式无法送达的，可以通过报纸、门户网站等方式公告送达。"},{"i":34,"n":"第三十四条","txt":"城市管理执法主管部门应当通过门户网站、办事窗口等渠道或者场所，公开行政执法职责、权限、依据、监督方式等行政执法信息。"},{"i":35,"n":"第三十五条","txt":"城市管理执法主管部门应当与有关部门建立行政执法信息互通共享机制，及时通报行政执法信息和相关行政管理信息。"},{"i":36,"n":"第三十六条","txt":"城市管理执法主管部门可以对城市管理执法事项实行网格化管理。"},{"i":37,"n":"第三十七条","txt":"城市管理执法主管部门在执法活动中发现依法应当由其他部门查处的违法行为，应当及时告知或者移送有关部门。"},{"i":38,"n":"第三十八条","txt":"城市管理执法主管部门应当向社会公布投诉、举报电话及其他监督方式。 城市管理执法主管部门应当为投诉人、举报人保密。"},{"i":39,"n":"第三十九条","txt":"城市管理执法主管部门违反本办法规定，有下列行为之一的，由上级城市管理执法主管部门或者有关部门责令改正，通报批评；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。 （一）没有法定依据实施行政处罚的； （二）违反法定程序实施行政处罚的； （三）以罚款、没收违法所得作为经费来源的； （四）使用、截留、损毁或者擅自处置查封、扣押物品的； （五）其他违反法律法规和本办法规定的。"},{"i":40,"n":"第四十条","txt":"非城市管理执法人员着城市管理执法制式服装的，城市管理执法主管部门应当予以纠正，依法追究法律责任。"},{"i":41,"n":"第四十一条","txt":"本办法第二条第一款规定范围以外的城市管理执法工作，参照本办法执行。"},{"i":42,"n":"第四十二条","txt":"本办法自2017年5月1日起施行。1992年6月3日发布的《城建监察规定》（建设部令第20号）同时废止。"}],"chengshizixianguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对城市历史文化街区和历史建筑的保护，根据《中华人民共和国城乡规划法》、《中华人民共和国文物保护法》和国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称城市紫线，是指国家历史文化名城内的历史文化街区和省、自治区、直辖市人民政府公布的历史文化街区的保护范围界线，以及历史文化街区外经县级以上人民政府公布保护的历史建筑的保护范围界线。本办法所称紫线管理是划定城市紫线和对城市紫线范围内的建设活动实施监督、管理。"},{"i":3,"n":"第三条","txt":"在编制城市规划时应当划定保护历史文化街区和历史建筑的紫线。国家历史文化名城的城市紫线由城市人民政府在组织编制历史文化名城保护规划时划定。其他城市的城市紫线由城市人民政府在组织编制城市总体规划时划定。"},{"i":4,"n":"第四条","txt":"国务院建设行政主管部门负责全国城市紫线管理工作。 省、自治区人民政府建设行政主管部门负责本行政区域内的城市紫线管理工作。 市、县人民政府城乡规划行政主管部门负责本行政区域内的城市紫线管理工作。"},{"i":5,"n":"第五条","txt":"任何单位和个人都有权了解历史文化街区和历史建筑的紫线范围及其保护规划，对规划的制定和实施管理提出意见，对破坏保护规划的行为进行检举。"},{"i":6,"n":"第六条","txt":"划定保护历史文化街区和历史建筑的紫线应当遵循下列原则： （一）历史文化街区的保护范围应当包括历史建筑物、构筑物和其风貌环境所组成的核心地段，以及为确保该地段的风貌、特色完整性而必须进行建设控制的地区。 （二）历史建筑的保护范围应当包括历史建筑本身和必要的风貌协调区。 （三）控制范围清晰，附有明确的地理座标及相应的界址地形图。 城市紫线范围内文物保护单位保护范围的划定，依据国家有关文物保护的法律、法规。"},{"i":7,"n":"第七条","txt":"编制历史文化名城和历史文化街区保护规划，应当包括征求公众意见的程序。审查历史文化名城和历史文化街区保护规划，应当组织专家进行充分论证，并作为法定审批程序的组成部分。 市、县人民政府批准保护规划前，必须报经上一级人民政府主管部门审查同意。"},{"i":8,"n":"第八条","txt":"历史文化名城和历史文化街区保护规划一经批准，原则上不得调整。因改善和加强保护工作的需要，确需调整的，由所在城市人民政府提出专题报告，经省、自治区、直辖市人民政府城乡规划行政主管部门审查同意后，方可组织编制调整方案。 调整后的保护规划在审批前，应当将规划方案公示，并组织专家论证。审批后应当报历史文化名城批准机关备案，其中国家历史文化名城报国务院建设行政主管部门备案。"},{"i":9,"n":"第九条","txt":"市、县人民政府应当在批准历史文化街区保护规划后的一个月内，将保护规划报省、自治区人民政府建设行政主管部门备案。其中国家历史文化名城内的历史文化街区保护规划还应当报国务院建设行政主管部门备案。"},{"i":10,"n":"第十条","txt":"历史文化名城、历史文化街区和历史建筑保护规划一经批准，有关市、县人民政府城乡规划行政主管部门必须向社会公布，接受公众监督。"},{"i":11,"n":"第十一条","txt":"历史文化街区和历史建筑已经破坏，不再具有保护价值的，有关市、县人民政府应当向所在省、自治区、直辖市人民政府提出专题报告，经批准后方可撤销相关的城市紫线。 撤销国家历史文化名城中的城市紫线，应当经国务院建设行政主管部门批准。"},{"i":12,"n":"第十二条","txt":"历史文化街区内的各项建设必须坚持保护真实的历史文化遗存，维护街区传统格局和风貌，改善基础设施、提高环境质量的原则。历史建筑的维修和整治必须保持原有外形和风貌，保护范围内的各项建设不得影响历史建筑风貌的展示。 市、县人民政府应当依据保护规划，对历史文化街区进行整治和更新，以改善人居环境为前提，加强基础设施、公共设施的改造和建设。"},{"i":13,"n":"第十三条","txt":"在城市紫线范围内禁止进行下列活动： （一）违反保护规划的大面积拆除、开发； （二）对历史文化街区传统格局和风貌构成影响的大面积改建； （三）损坏或者拆毁保护规划确定保护的建筑物、构筑物和其他设施； （四）修建破坏历史文化街区传统风貌的建筑物、构筑物和其他设施； （五）占用或者破坏保护规划确定保留的园林绿地、河湖水系、道路和古树名木等； （六）其他对历史文化街区和历史建筑的保护构成破坏性影响的活动。"},{"i":14,"n":"第十四条","txt":"在城市紫线范围内确定各类建设项目，必须先由市、县人民政府城乡规划行政主管部门依据保护规划进行审查，组织专家论证并进行公示后核发选址意见书。"},{"i":15,"n":"第十五条","txt":"在城市紫线范围内进行新建或者改建各类建筑物、构筑物和其他设施，对规划确定保护的建筑物、构筑物和其他设施进行修缮和维修以及改变建筑物、构筑物的使用性质，应当依照相关法律、法规的规定，办理相关手续后方可进行。"},{"i":16,"n":"第十六条","txt":"城市紫线范围内各类建设的规划审批，实行备案制度。 省、自治区、直辖市人民政府公布的历史文化街区，报省、自治区人民政府建设行政主管部门或者直辖市人民政府城乡规划行政主管部门备案。其中国家历史文化名城内的历史文化街区报国务院建设行政主管部门备案。"},{"i":17,"n":"第十七条","txt":"在城市紫线范围内进行建设活动，涉及文物保护单位的，应当符合国家有关文物保护的法律、法规的规定。"},{"i":18,"n":"第十八条","txt":"省、自治区建设行政主管部门和直辖市城乡规划行政主管部门，应当定期对保护规划执行情况进行检查监督，并向国务院建设行政主管部门提出报告。 对于监督中发现的擅自调整和改变城市紫线，擅自调整和违反保护规划的行政行为，或者由于人为原因，导致历史文化街区和历史建筑遭受局部破坏的，监督机关可以提出纠正决定，督促执行。"},{"i":19,"n":"第十九条","txt":"国务院建设行政主管部门，省、自治区人民政府建设行政主管部门和直辖市人民政府城乡规划行政主管部门根据需要可以向有关城市派出规划监督员，对城市紫线的执行情况进行监督。 规划监督员行使下述职能： （一）参与保护规划的专家论证，就保护规划方案的科学合理性向派出机关报告； （二）参与城市紫线范围内建设项目立项的专家论证，了解公示情况，可以对建设项目的可行性提出意见，并向派出机关报告； （三）对城市紫线范围内各项建设审批的可行性提出意见，并向派出机关报告； （四）接受公众的投诉，进行调查，向有关行政主管部门提出处理建议，并向派出机关报告。"},{"i":20,"n":"第二十条","txt":"违反本办法规定，未经市、县人民政府城乡规划行政主管部门批准，在城市紫线范围内进行建设活动的，由市、县人民政府城乡规划行政主管部门按照《中华人民共和国城乡规划法》等法律、法规的规定处罚。"},{"i":21,"n":"第二十一条","txt":"违反本办法规定，擅自在城市紫线范围内审批建设项目和批准建设的，对有关责任人员给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"本办法自2004年2月1日起施行。"}],"chengshilvxianguanlibanfa":[{"i":1,"n":"第一条","txt":"为建立并严格实行城市绿线管理制度，加强城市生态环境建设，创造良好的人居环境，促进城市可持续发展，根据《中华人民共和国城乡规划法》、《城市绿化条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称城市绿线，是指城市各类绿地范围的控制线。 本办法所称城市，是指国家按行政建制设立的直辖市、市、镇。"},{"i":3,"n":"第三条","txt":"城市绿线的划定和监督管理，适用本办法。"},{"i":4,"n":"第四条","txt":"国务院建设行政主管部门负责全国城市绿线管理工作。 省、自治区人民政府建设行政主管部门负责本行政区域内的城市绿线管理工作。 城市人民政府规划、园林绿化行政主管部门，按照职责分工负责城市绿线的监督和管理工作。"},{"i":5,"n":"第五条","txt":"城市规划、园林绿化等行政主管部门应当密切合作，组织编制城市绿地系统规划。 城市绿地系统规划是城市总体规划的组成部分，应当确定城市绿化目标和布局，规定城市各类绿地的控制原则，按照规定标准确定绿化用地面积，分层次合理布局公共绿地，确定防护绿地、大型公共绿地等的绿线。"},{"i":6,"n":"第六条","txt":"控制性详细规划应当提出不同类型用地的界线、规定绿化率控制指标和绿化用地界线的具体坐标。"},{"i":7,"n":"第七条","txt":"修建性详细规划应当根据控制性详细规划，明确绿地布局，提出绿化配置的原则或者方案，划定绿地界线。"},{"i":8,"n":"第八条","txt":"城市绿线的审批、调整，按照《中华人民共和国城乡规划法》、《城市绿化条例》的规定进行。"},{"i":9,"n":"第九条","txt":"批准的城市绿线要向社会公布，接受公众监督。 任何单位和个人都有保护城市绿地、服从城市绿线管理的义务，有监督城市绿线管理、对违反城市绿线管理行为进行检举的权利。"},{"i":10,"n":"第十条","txt":"城市绿线范围内的公共绿地、防护绿地、生产绿地、居住区绿地、单位附属绿地、道路绿地、风景林地等，必须按照《城市用地分类与规划建设用地标准》、《公园设计规范》等标准，进行绿地建设。"},{"i":11,"n":"第十一条","txt":"城市绿线内的用地，不得改作他用，不得违反法律法规、强制性标准以及批准的规划进行开发建设。 有关部门不得违反规定，批准在城市绿线范围内进行建设。 因建设或者其他特殊情况，需要临时占用城市绿线内用地的，必须依法办理相关审批手续。 在城市绿线范围内，不符合规划要求的建筑物、构筑物及其他设施应当限期迁出。"},{"i":12,"n":"第十二条","txt":"任何单位和个人不得在城市绿地范围内进行拦河截溪、取土采石、设置垃圾堆场、排放污水以及其他对生态环境构成破坏的活动。 近期不进行绿化建设的规划绿地范围内的建设活动，应当进行生态环境影响分析，并按照《中华人民共和国城乡规划法》的规定，予以严格控制。"},{"i":13,"n":"第十三条","txt":"居住区绿化、单位绿化及各类建设项目的配套绿化都要达到《城市绿化规划建设指标的规定》的标准。 各类建设工程要与其配套的绿化工程同步设计，同步施工，同步验收。达不到规定标准的，不得投入使用。"},{"i":14,"n":"第十四条","txt":"城市人民政府规划、园林绿化行政主管部门按照职责分工，对城市绿线的控制和实施情况进行检查，并向同级人民政府和上级行政主管部门报告。"},{"i":15,"n":"第十五条","txt":"省、自治区人民政府建设行政主管部门应当定期对本行政区域内城市绿线的管理情况进行监督检查，对违法行为，及时纠正。"},{"i":16,"n":"第十六条","txt":"违反本办法规定，擅自改变城市绿线内土地用途、占用或者破坏城市绿地的，由城市规划、园林绿化行政主管部门，按照《中华人民共和国城乡规划法》、《城市绿化条例》的有关规定处罚。"},{"i":17,"n":"第十七条","txt":"违反本办法规定，在城市绿地范围内进行拦河截溪、取土采石、设置垃圾堆场、排放污水以及其他对城市生态环境造成破坏活动的，由城市园林绿化行政主管部门责令改正，并处一万元以上三万元以下的罚款。"},{"i":18,"n":"第十八条","txt":"违反本办法规定，在已经划定的城市绿线范围内违反规定审批建设项目的，对有关责任人员由有关机关给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"城镇体系规划所确定的，城市规划区外防护绿地、绿化隔离带等的绿线划定、监督和管理，参照本办法执行。"},{"i":20,"n":"第二十条","txt":"本办法自二〇〇二年十一月一日起施行。"}],"chengshijieyueyongshuiguanliguiding":[{"i":1,"n":"第一条","txt":"为加强城市节约用水管理，保护和合理利用水资源，促进国民经济和社会发展，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于城市规划区内节约用水的管理工作。 在城市规划区内使用公共供水和自建设施供水的单位和个人，必须遵守本规定。"},{"i":3,"n":"第三条","txt":"城市实行计划用水和节约用水。"},{"i":4,"n":"第四条","txt":"国家鼓励城市节约用水科学技术研究，推广先进技术，提高城市节约用水科学技术水平。 在城市节约用水工作中作出显著成绩的单位和个人，由人民政府给予奖励。"},{"i":5,"n":"第五条","txt":"国务院城市建设行政主管部门主管全国的城市节约用水工作，业务上受国务院水行政主管部门指导。 国务院其他有关部门按照国务院规定的职责分工，负责本行业的节约用水管理工作。 省、自治区人民政府和县级以上城市人民政府城市建设行政主管部门和其他有关行业主管部门，按照同级人民政府规定的职责分工，负责城市节约用水管理工作。"},{"i":6,"n":"第六条","txt":"城市人民政府应当在制定城市供水发展规划的同时，制定节约用水发展规划，并根据节约用水发展规划制定节约用水年度计划。 各有关行业行政主管部门应当制定本行业的节约用水发展规划和节约用水年度计划。"},{"i":7,"n":"第七条","txt":"工业用水重复利用率低于40％（不包括热电厂用水）的城市，新建供水工程时，未经上一级城市建设行政主管部门的同意，不得新增工业用水量。"},{"i":8,"n":"第八条","txt":"单位自建供水设施取用地下水，必须经城市建设行政主管部门核准后，依照国家规定申请取水许可。"},{"i":9,"n":"第九条","txt":"城市的新建、扩建和改建工程项目，应当配套建设节约用水设施。城市建设行政主管部门应当参加节约用水设施的竣工验收。"},{"i":10,"n":"第十条","txt":"城市建设行政主管部门应当会同有关行业行政主管部门制定行业综合用水定额和单项用水定额。"},{"i":11,"n":"第十一条","txt":"城市用水计划由城市建设行政主管部门根据水资源统筹规划和水长期供求计划制定，并下达执行。 超计划用水必须缴纳超计划用水加价水费。超计划用水加价水费，应当从税后留利或者预算包干经费中支出，不得纳入成本或者从当年预算中支出。 超计划用水加价水费的具体征收办法由省、自治区、直辖市人民政府制定。"},{"i":12,"n":"第十二条","txt":"生活用水按户计量收费。新建住宅应当安装分户计量水表；现有住户未装分户计量水表的，应当限期安装。"},{"i":13,"n":"第十三条","txt":"各用水单位应当在用水设备上安装计量水表，进行用水单耗考核，降低单位产品用水量；应当采取循环用水、一水多用等措施，在保证用水质量标准的前提下，提高水的重复利用率。"},{"i":14,"n":"第十四条","txt":"水资源紧缺城市，应当在保证用水质量标准的前提下，采取措施提高城市污水利用率。 沿海城市应当积极开发利用海水资源。 有咸水资源的城市，应当合理开发利用咸水资源。"},{"i":15,"n":"第十五条","txt":"城市供水企业、自建供水设施的单位应当加强供水设施的维修管理，减少水的漏损量。"},{"i":16,"n":"第十六条","txt":"各级统计部门、城市建设行政主管部门应当做好城市节约用水统计工作。"},{"i":17,"n":"第十七条","txt":"城市的新建、扩建和改建工程项目未按规定配套建设节约用水设施或者节约用水设施经验收不合格的，由城市建设行政主管部门限制其用水量，并责令其限期完善节约用水设施，可以并处罚款。"},{"i":18,"n":"第十八条","txt":"超计划用水加价水费必须按规定的期限缴纳。逾期不缴纳的，城市建设行政主管部门除限期缴纳外，并按日加收超计划用水加价水费5‰的滞纳金。"},{"i":19,"n":"第十九条","txt":"拒不安装生活用水分户计量水表的，城市建设行政主管部门应当责令其限期安装；逾期仍不安装的，由城市建设行政主管部门限制其用水量，可以并处罚款。"},{"i":20,"n":"第二十条","txt":"当事人对行政处罚决定不服的，可以在接到处罚通知次日起15日内，向作出处罚决定机关的上一级机关申请复议；对复议决定不服的，可以在接到复议通知次日起15日内向人民法院起诉。逾期不申请复议或者不向人民法院起诉又不履行处罚决定的，由作出处罚决定的机关申请人民法院强制执行。"},{"i":21,"n":"第二十一条","txt":"城市建设行政主管部门的工作人员玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管部门给予行政处分；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"各省、自治区、直辖市人民政府可以根据本规定制定实施办法。"},{"i":23,"n":"第二十三条","txt":"本规定由国务院城市建设行政主管部门负责解释。"},{"i":24,"n":"第二十四条","txt":"本规定自1989年1月1日起施行。"}],"chengshilanxianguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对城市水系的保护与管理，保障城市供水、防洪防涝和通航安全，改善城市人居生态环境，提升城市功能，促进城市健康、协调和可持续发展，根据《中华人民共和国城乡规划法》、《中华人民共和国水法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称城市蓝线，是指城市规划确定的江、河、湖、库、渠和湿地等城市地表水体保护和控制的地域界线。 城市蓝线的划定和管理，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"国务院建设主管部门负责全国城市蓝线管理工作。 县级以上地方人民政府建设主管部门（城乡规划主管部门）负责本行政区域内的城市蓝线管理工作。"},{"i":4,"n":"第四条","txt":"任何单位和个人都有服从城市蓝线管理的义务，有监督城市蓝线管理、对违反城市蓝线管理行为进行检举的权利。"},{"i":5,"n":"第五条","txt":"编制各类城市规划，应当划定城市蓝线。 城市蓝线由直辖市、市、县人民政府在组织编制各类城市规划时划定。 城市蓝线应当与城市规划一并报批。"},{"i":6,"n":"第六条","txt":"划定城市蓝线，应当遵循以下原则： （一）统筹考虑城市水系的整体性、协调性、安全性和功能性，改善城市生态和人居环境，保障城市水系安全； （二）与同阶段城市规划的深度保持一致； （三）控制范围界定清晰； （四）符合法律、法规的规定和国家有关技术标准、规范的要求。"},{"i":7,"n":"第七条","txt":"在城市总体规划阶段，应当确定城市规划区范围内需要保护和控制的主要地表水体，划定城市蓝线，并明确城市蓝线保护和控制的要求。"},{"i":8,"n":"第八条","txt":"在控制性详细规划阶段，应当依据城市总体规划划定的城市蓝线，规定城市蓝线范围内的保护要求和控制指标，并附有明确的城市蓝线坐标和相应的界址地形图。"},{"i":9,"n":"第九条","txt":"城市蓝线一经批准，不得擅自调整。 因城市发展和城市布局结构变化等原因，确实需要调整城市蓝线的，应当依法调整城市规划，并相应调整城市蓝线。调整后的城市蓝线，应当随调整后的城市规划一并报批。 调整后的城市蓝线应当在报批前进行公示，但法律、法规规定不得公开的除外。"},{"i":10,"n":"第十条","txt":"在城市蓝线内禁止进行下列活动： （一）违反城市蓝线保护和控制要求的建设活动； （二）擅自填埋、占用城市蓝线内水域； （三）影响水系安全的爆破、采石、取土； （四）擅自建设各类排污设施； （五）其它对城市水系保护构成破坏的活动。"},{"i":11,"n":"第十一条","txt":"在城市蓝线内进行各项建设，应当符合经批准的城市规划。 在城市蓝线内新建、改建、扩建各类建筑物、构筑物、道路、管线和其他工程设施，应当依法向建设主管部门（城乡规划主管部门）申请办理城市规划许可，并依照有关法律、法规办理相关手续。"},{"i":12,"n":"第十二条","txt":"需要临时占用城市蓝线内的用地或水域的，应当报经直辖市、市、县人民政府建设主管部门（城乡规划主管部门）同意，并依法办理相关审批手续；临时占用后，应当限期恢复。"},{"i":13,"n":"第十三条","txt":"县级以上地方人民政府建设主管部门（城乡规划主管部门）应当定期对城市蓝线管理情况进行监督检查。"},{"i":14,"n":"第十四条","txt":"违反本办法规定，在城市蓝线范围内进行各类建设活动的，按照《中华人民共和国城乡规划法》等有关法律、法规的规定处罚。"},{"i":15,"n":"第十五条","txt":"县级以上地方人民政府建设主管部门（城乡规划主管部门）违反本办法规定，批准在城市蓝线范围内进行建设的，对有关责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"本办法自2006年3月1日起施行。"}],"chengshiguihuabianzhibanfa":[{"i":1,"n":"第一条","txt":"为了规范城市规划编制工作，提高城市规划的科学性和严肃性，根据国家有关法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"按国家行政建制设立的市，组织编制城市规划，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"城市规划是政府调控城市空间资源、指导城乡发展与建设、维护社会公平、保障公共安全和公众利益的重要公共政策之一。"},{"i":4,"n":"第四条","txt":"编制城市规划，应当以科学发展观为指导，以构建社会主义和谐社会为基本目标，坚持五个统筹，坚持中国特色的城镇化道路，坚持节约和集约利用资源，保护生态环境，保护人文资源，尊重历史文化，坚持因地制宜确定城市发展目标与战略，促进城市全面协调可持续发展。"},{"i":5,"n":"第五条","txt":"编制城市规划，应当考虑人民群众需要，改善人居环境，方便群众生活，充分关注中低收入人群，扶助弱势群体，维护社会稳定和公共安全。"},{"i":6,"n":"第六条","txt":"编制城市规划，应当坚持政府组织、专家领衔、部门合作、公众参与、科学决策的原则。"},{"i":7,"n":"第七条","txt":"城市规划分为总体规划和详细规划两个阶段。大、中城市根据需要，可以依法在总体规划的基础上组织编制分区规划。 城市详细规划分为控制性详细规划和修建性详细规划。"},{"i":8,"n":"第八条","txt":"国务院建设主管部门组织编制的全国城镇体系规划和省、自治区人民政府组织编制的省域城镇体系规划，应当作为城市总体规划编制的依据。"},{"i":9,"n":"第九条","txt":"编制城市规划，应当遵守国家有关标准和技术规范，采用符合国家有关规定的基础资料。"},{"i":10,"n":"第十条","txt":"承担城市规划编制的单位，应当取得城市规划编制资质证书，并在资质等级许可的范围内从事城市规划编制工作。"},{"i":11,"n":"第十一条","txt":"城市人民政府负责组织编制城市总体规划和城市分区规划。具体工作由城市人民政府建设主管部门（城乡规划主管部门）承担。 城市人民政府应当依据城市总体规划，结合国民经济和社会发展规划以及土地利用总体规划，组织制定近期建设规划。 控制性详细规划由城市人民政府建设主管部门（城乡规划主管部门）依据已经批准的城市总体规划或者城市分区规划组织编制。 修建性详细规划可以由有关单位依据控制性详细规划及建设主管部门（城乡规划主管部门）提出的规划条件，委托城市规划编制单位编制。"},{"i":12,"n":"第十二条","txt":"城市人民政府提出编制城市总体规划前，应当对现行城市总体规划以及各专项规划的实施情况进行总结，对基础设施的支撑能力和建设条件做出评价；针对存在问题和出现的新情况，从土地、水、能源和环境等城市长期的发展保障出发，依据全国城镇体系规划和省域城镇体系规划，着眼区域统筹和城乡统筹，对城市的定位、发展目标、城市功能和空间布局等战略问题进行前瞻性研究，作为城市总体规划编制的工作基础。"},{"i":13,"n":"第十三条","txt":"城市总体规划应当按照以下程序组织编制： （一）按照本办法第十二条规定组织前期研究，在此基础上，按规定提出进行编制工作的报告，经同意后方可组织编制。其中，组织编制直辖市、省会城市、国务院指定市的城市总体规划的，应当向国务院建设主管部门提出报告；组织编制其他市的城市总体规划的，应当向省、自治区建设主管部门提出报告。 （二）组织编制城市总体规划纲要，按规定提请审查。其中，组织编制直辖市、省会城市、国务院指定市的城市总体规划的，应当报请国务院建设主管部门组织审查；组织编制其他市的城市总体规划的，应当报请省、自治区建设主管部门组织审查。 （三）依据国务院建设主管部门或者省、自治区建设主管部门提出的审查意见，组织编制城市总体规划成果，按法定程序报请审查和批准。"},{"i":14,"n":"第十四条","txt":"在城市总体规划的编制中，对于涉及资源与环境保护、区域统筹与城乡统筹、城市发展目标与空间布局、城市历史文化遗产保护等重大专题，应当在城市人民政府组织下，由相关领域的专家领衔进行研究。"},{"i":15,"n":"第十五条","txt":"在城市总体规划的编制中，应当在城市人民政府组织下，充分吸取政府有关部门和军事机关的意见。 对于政府有关部门和军事机关提出意见的采纳结果，应当作为城市总体规划报送审批材料的专题组成部分。 组织编制城市详细规划，应当充分听取政府有关部门的意见，保证有关专业规划的空间落实。"},{"i":16,"n":"第十六条","txt":"在城市总体规划报送审批前，城市人民政府应当依法采取有效措施，充分征求社会公众的意见。 在城市详细规划的编制中，应当采取公示、征询等方式，充分听取规划涉及的单位、公众的意见。对有关意见采纳结果应当公布。"},{"i":17,"n":"第十七条","txt":"城市总体规划调整，应当按规定向规划审批机关提出调整报告，经认定后依照法律规定组织调整。 城市详细规划调整，应当取得规划批准机关的同意。规划调整方案，应当向社会公开，听取有关单位和公众的意见，并将有关意见的采纳结果公示。"},{"i":18,"n":"第十八条","txt":"编制城市规划，要妥善处理城乡关系，引导城镇化健康发展，体现布局合理、资源节约、环境友好的原则，保护自然与文化资源、体现城市特色，考虑城市安全和国防建设需要。"},{"i":19,"n":"第十九条","txt":"编制城市规划，对涉及城市发展长期保障的资源利用和环境保护、区域协调发展、风景名胜资源管理、自然与文化遗产保护、公共安全和公众利益等方面的内容，应当确定为必须严格执行的强制性内容。"},{"i":20,"n":"第二十条","txt":"城市总体规划包括市域城镇体系规划和中心城区规划。 编制城市总体规划，应当先组织编制总体规划纲要，研究确定总体规划中的重大问题，作为编制规划成果的依据。"},{"i":21,"n":"第二十一条","txt":"编制城市总体规划，应当以全国城镇体系规划、省域城镇体系规划以及其它上层次法定规划为依据，从区域经济社会发展的角度研究城市定位和发展战略，按照人口与产业、就业岗位的协调发展要求，控制人口规模、提高人口素质，按照有效配置公共资源、改善人居环境的要求，充分发挥中心城市的区域辐射和带动作用，合理确定城乡空间布局，促进区域经济社会全面、协调和可持续发展。"},{"i":22,"n":"第二十二条","txt":"编制城市近期建设规划，应当依据已经依法批准的城市总体规划，明确近期内实施城市总体规划的重点和发展时序，确定城市近期发展方向、规模、空间布局、重要基础设施和公共服务设施选址安排，提出自然遗产与历史文化遗产的保护、城市生态环境建设与治理的措施。"},{"i":23,"n":"第二十三条","txt":"编制城市分区规划，应当依据已经依法批准的城市总体规划，对城市土地利用、人口分布和公共服务设施、基础设施的配置做出进一步的安排，对控制性详细规划的编制提出指导性要求。"},{"i":24,"n":"第二十四条","txt":"编制城市控制性详细规划，应当依据已经依法批准的城市总体规划或分区规划，考虑相关专项规划的要求，对具体地块的土地利用和建设提出控制指标，作为建设主管部门（城乡规划主管部门）作出建设项目规划许可的依据。 编制城市修建性详细规划，应当依据已经依法批准的控制性详细规划，对所在地块的建设提出具体的安排和设计。"},{"i":25,"n":"第二十五条","txt":"历史文化名城的城市总体规划，应当包括专门的历史文化名城保护规划。 历史文化街区应当编制专门的保护性详细规划。"},{"i":26,"n":"第二十六条","txt":"城市规划成果的表达应当清晰、规范，成果文件、图件与附件中说明、专题研究、分析图纸等表达应有区分。 城市规划成果文件应当以书面和电子文件两种方式表达。"},{"i":27,"n":"第二十七条","txt":"城市规划编制单位应当严格依据法律、法规的规定编制城市规划，提交的规划成果应当符合本办法和国家有关标准。"},{"i":28,"n":"第二十八条","txt":"城市总体规划的期限一般为二十年，同时可以对城市远景发展的空间布局提出设想。 确定城市总体规划具体期限，应当符合国家有关政策的要求。"},{"i":29,"n":"第二十九条","txt":"总体规划纲要应当包括下列内容： （一）市域城镇体系规划纲要，内容包括：提出市域城乡统筹发展战略；确定生态环境、土地和水资源、能源、自然和历史文化遗产保护等方面的综合目标和保护要求，提出空间管制原则；预测市域总人口及城镇化水平，确定各城镇人口规模、职能分工、空间布局方案和建设标准；原则确定市域交通发展策略。 （二）提出城市规划区范围。 （三）分析城市职能、提出城市性质和发展目标。 （四）提出禁建区、限建区、适建区范围。 （五）预测城市人口规模。 （六）研究中心城区空间增长边界，提出建设用地规模和建设用地范围； （七）提出交通发展战略及主要对外交通设施布局原则。 （八）提出重大基础设施和公共服务设施的发展目标。 （九）提出建立综合防灾体系的原则和建设方针。"},{"i":30,"n":"第三十条","txt":"市域城镇体系规划应当包括下列内容： （一）提出市域城乡统筹的发展战略。其中位于人口、经济、建设高度聚集的城镇密集地区的中心城市，应当根据需要，提出与相邻行政区域在空间发展布局、重大基础设施和公共服务设施建设、生态环境保护、城乡统筹发展等方面进行协调的建议。 （二）确定生态环境、土地和水资源、能源、自然和历史文化遗产等方面的保护与利用的综合目标和要求，提出空间管制原则和措施。 （三）预测市域总人口及城镇化水平，确定各城镇人口规模、职能分工、空间布局和建设标准。 （四）提出重点城镇的发展定位、用地规模和建设用地控制范围。 （五）确定市域交通发展策略；原则确定市域交通、通讯、能源、供水、排水、防洪、垃圾处理等重大基础设施，重要社会服务设施，危险品生产储存设施的布局。 （六）根据城市建设、发展和资源管理的需要划定城市规划区。城市规划区的范围应当位于城市的行政管辖范围内。 （七）提出实施规划的措"},{"i":31,"n":"第三十一条","txt":"中心城区规划应当包括下列内容： （一）分析确定城市性质、职能和发展目标。 （二）预测城市人口规模。 （三）划定禁建区、限建区、适建区和已建区，并制定空间管制措施。 （四）确定村镇发展与控制的原则和措施；确定需要发展、限制发展和不再保留的村庄，提出村镇建设控制标准。 （五）安排建设用地、农业用地、生态用地和其它用地。 （六）研究中心城区空间增长边界，确定建设用地规模，划定建设用地范围。 （七）确定建设用地的空间布局，提出土地使用强度管制区划和相应的控制指标（建筑密度、建筑高度、容积率、人口容量等）。 （八）确定市级和区级中心的位置和规模，提出主要的公共服务设施的布局。 （九）确定交通发展战略和城市公共交通的总体布局，落实公交优先政策，确定主要对外交通设施和主要道路交通设施布局。 （十）确定绿地系统的发展目标及总体布局，划定各种功能绿地的保护范围（绿线），划定河湖水面的保护范围（蓝线），确"},{"i":32,"n":"第三十二条","txt":"城市总体规划的强制性内容包括： （一）城市规划区范围。 （二）市域内应当控制开发的地域。包括：基本农田保护区，风景名胜区，湿地、水源保护区等生态敏感区，地下矿产资源分布地区。 （三）城市建设用地。包括：规划期限内城市建设用地的发展规模，土地使用强度管制区划和相应的控制指标（建设用地面积、容积率、人口容量等）；城市各类绿地的具体布局；城市地下空间开发布局。 （四）城市基础设施和公共服务设施。包括：城市干道系统网络、城市轨道交通网络、交通枢纽布局；城市水源地及其保护区范围和其他重大市政基础设施；文化、教育、卫生、体育等方面主要公共服务设施的布局。 （五）城市历史文化遗产保护。包括：历史文化保护的具体控制指标和规定；历史文化街区、历史建筑、重要地下文物埋藏区的具体位置和界线。 （六）生态环境保护与建设目标，污染控制与治理措施。 （七）城市防灾工程。包括：城市防洪标准、防洪堤走向；城市抗震与消"},{"i":33,"n":"第三十三条","txt":"总体规划纲要成果包括纲要文本、说明、相应的图纸和研究报告。 城市总体规划的成果应当包括规划文本、图纸及附件（说明、研究报告和基础资料等）。在规划文本中应当明确表述规划的强制性内容。"},{"i":34,"n":"第三十四条","txt":"城市总体规划应当明确综合交通、环境保护、商业网点、医疗卫生、绿地系统、河湖水系、历史文化名城保护、地下空间、基础设施、综合防灾等专项规划的原则。 编制各类专项规划，应当依据城市总体规划。"},{"i":35,"n":"第三十五条","txt":"近期建设规划的期限原则上应当与城市国民经济和社会发展规划的年限一致，并不得违背城市总体规划的强制性内容。 近期建设规划到期时，应当依据城市总体规划组织编制新的近期建设规划。"},{"i":36,"n":"第三十六条","txt":"近期建设规划的内容应当包括： （一）确定近期人口和建设用地规模，确定近期建设用地范围和布局。 （二）确定近期交通发展策略，确定主要对外交通设施和主要道路交通设施布局； （三）确定各项基础设施、公共服务和公益设施的建设规模和选址。 （四）确定近期居住用地安排和布局； （五）确定历史文化名城、历史文化街区、风景名胜区等的保护措施，城市河湖水系、绿化、环境等保护、整治和建设措施。 （六）确定控制和引导城市近期发展的原则和措施。"},{"i":37,"n":"第三十七条","txt":"近期建设规划的成果应当包括规划文本、图纸，以及包括相应说明的附件。在规划文本中应当明确表达规划的强制性内容。"},{"i":38,"n":"第三十八条","txt":"编制分区规划，应当综合考虑城市总体规划确定的城市布局、片区特征、河流道路等自然和人工界限，结合城市行政区划，划定分区的范围界限。"},{"i":39,"n":"第三十九条","txt":"分区规划应当包括下列内容： （一）确定分区的空间布局、功能分区、土地使用性质和居住人口分布。 （二）确定绿地系统、河湖水面、供电高压线走廊、对外交通设施用地界线和风景名胜区、文物古迹、历史文化街区的保护范围，提出空间形态的保护要求。 （三）确定市、区、居住区级公共服务设施的分布、用地范围和控制原则； （四）确定主要市政公用设施的位置、控制范围和工程干管的线路位置、管径，进行管线综合。 （五）确定城市干道的红线位置、断面、控制点座标和标高，确定支路的走向、宽度，确定主要交叉口、广场、公交站场、交通枢纽等交通设施的位置和规模，确定轨道交通线路走向及控制范围，确定主要停车场规模与布局。"},{"i":40,"n":"第四十条","txt":"分区规划的成果应当包括规划文本、图件，以及包括相应说明的附件。"},{"i":41,"n":"第四十一条","txt":"控制性详细规划应当包括下列内容： （一）确定规划范围内不同性质用地的界线，确定各类用地内适建，不适建或者有条件地允许建设的建筑类型。 （二）确定各地块建筑高度、建筑密度、容积率、绿地率等控制指标；确定公共设施配套要求、交通出入口方位、停车泊位、建筑后退红线距离等要求。 （三）提出各地块的建筑体量、体型、色彩等城市设计指导原则； （四）根据交通需求分析，确定地块出入口位置、停车泊位、公共交通场站用地范围和站点位置、步行交通以及其它交通设施。规定各级道路的红线、断面、交叉口形式及渠化措施、控制点坐标和标高。 （五）根据规划建设容量，确定市政工程管线位置、管径和工程设施的用地界线，进行管线综合。确定地下空间开发利用具体要求。 （六）制定相应的土地使用与建筑管理规定。"},{"i":42,"n":"第四十二条","txt":"控制性详细规划确定的各地块的主要用途、建筑密度、建筑高度、容积率、绿地率、基础设施和公共服务设施配套规定应当作为强制性内容。"},{"i":43,"n":"第四十三条","txt":"修建性详细规划应当包括下列内容： （一）建设条件分析及综合技术经济论证。 （二）建筑、道路和绿地等的空间布局和景观规划设计，布置总平面图。 （三）对住宅、医院、学校和托幼等建筑进行日照分析。 （四）根据交通影响分析，提出交通组织方案和设计。 （五）市政工程管线规划设计和管线综合。 （六）竖向规划设计。 （七）估算工程量、拆迁量和总造价，分析投资效益。"},{"i":44,"n":"第四十四条","txt":"控制性详细规划成果应当包括规划文本、图件和附件。图件由图纸和图则两部分组成，规划说明、基础资料和研究报告收入附件。 修建性详细规划成果应当包括规划说明书、图纸。"},{"i":45,"n":"第四十五条","txt":"县人民政府所在地镇的城市规划编制，参照本办法执行。"},{"i":46,"n":"第四十六条","txt":"对城市规划文本、图纸、说明、基础资料等的具体内容、深度要求和规格等，由国务院建设主管部门另行规定。"},{"i":47,"n":"第四十七条","txt":"本办法自2006年4月1日起施行。1991年9月3日建设部颁布的《城市规划编制办法》同时废止。"}],"chengshishejiguanlibanfa":[{"i":1,"n":"第一条","txt":"为提高城市建设水平，塑造城市风貌特色，推进城市设计工作，完善城市规划建设管理，依据《中华人民共和国城乡规划法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"城市、县人民政府所在地建制镇开展城市设计管理工作，适用本办法。"},{"i":3,"n":"第三条","txt":"城市设计是落实城市规划、指导建筑设计、塑造城市特色风貌的有效手段，贯穿于城市规划建设管理全过程。通过城市设计，从整体平面和立体空间上统筹城市建筑布局、协调城市景观风貌，体现地域特征、民族特色和时代风貌。"},{"i":4,"n":"第四条","txt":"开展城市设计，应当符合城市（县人民政府所在地建制镇）总体规划和相关标准；尊重城市发展规律，坚持以人为本，保护自然环境，传承历史文化，塑造城市特色，优化城市形态，节约集约用地，创造宜居公共空间；根据经济社会发展水平、资源条件和管理需要，因地制宜，逐步推进。"},{"i":5,"n":"第五条","txt":"国务院城乡规划主管部门负责指导和监督全国城市设计工作。 省、自治区城乡规划主管部门负责指导和监督本行政区域内城市设计工作。 城市、县人民政府城乡规划主管部门负责本行政区域内城市设计的监督管理。"},{"i":6,"n":"第六条","txt":"城市、县人民政府城乡规划主管部门，应当充分利用新技术开展城市设计工作。有条件的地方可以建立城市设计管理辅助决策系统，并将城市设计要求纳入城市规划管理信息平台。"},{"i":7,"n":"第七条","txt":"城市设计分为总体城市设计和重点地区城市设计。"},{"i":8,"n":"第八条","txt":"总体城市设计应当确定城市风貌特色，保护自然山水格局，优化城市形态格局，明确公共空间体系，并可与城市（县人民政府所在地建制镇）总体规划一并报批。"},{"i":9,"n":"第九条","txt":"下列区域应当编制重点地区城市设计： （一）城市核心区和中心地区； （二）体现城市历史风貌的地区； （三）新城新区； （四）重要街道，包括商业街； （五）滨水地区，包括沿河、沿海、沿湖地带； （六）山前地区； （七）其他能够集中体现和塑造城市文化、风貌特色，具有特殊价值的地区。"},{"i":10,"n":"第十条","txt":"重点地区城市设计应当塑造城市风貌特色，注重与山水自然的共生关系，协调市政工程，组织城市公共空间功能，注重建筑空间尺度，提出建筑高度、体量、风格、色彩等控制要求。"},{"i":11,"n":"第十一条","txt":"历史文化街区和历史风貌保护相关控制地区开展城市设计，应当根据相关保护规划和要求，整体安排空间格局，保护延续历史文化，明确新建建筑和改扩建建筑的控制要求。 重要街道、街区开展城市设计，应当根据居民生活和城市公共活动需要，统筹交通组织，合理布置交通设施、市政设施、街道家具，拓展步行活动和绿化空间，提升街道特色和活力。"},{"i":12,"n":"第十二条","txt":"城市设计重点地区范围以外地区，可以根据当地实际条件，依据总体城市设计，单独或者结合控制性详细规划等开展城市设计，明确建筑特色、公共空间和景观风貌等方面的要求。"},{"i":13,"n":"第十三条","txt":"编制城市设计时，组织编制机关应当通过座谈、论证、网络等多种形式及渠道，广泛征求专家和公众意见。审批前应依法进行公示，公示时间不少于30日。 城市设计成果应当自批准之日起20个工作日内，通过政府信息网站以及当地主要新闻媒体予以公布。"},{"i":14,"n":"第十四条","txt":"重点地区城市设计的内容和要求应当纳入控制性详细规划，并落实到控制性详细规划的相关指标中。 重点地区的控制性详细规划未体现城市设计内容和要求的，应当及时修改完善。"},{"i":15,"n":"第十五条","txt":"单体建筑设计和景观、市政工程方案设计应当符合城市设计要求。"},{"i":16,"n":"第十六条","txt":"以出让方式提供国有土地使用权，以及在城市、县人民政府所在地建制镇规划区内的大型公共建筑项目，应当将城市设计要求纳入规划条件。"},{"i":17,"n":"第十七条","txt":"城市、县人民政府城乡规划主管部门负责组织编制本行政区域内总体城市设计、重点地区的城市设计，并报本级人民政府审批。"},{"i":18,"n":"第十八条","txt":"城市、县人民政府城乡规划主管部门组织编制城市设计所需的经费，应列入城乡规划的编制经费预算。"},{"i":19,"n":"第十九条","txt":"城市、县人民政府城乡规划主管部门开展城乡规划监督检查时，应当加强监督检查城市设计工作情况。 国务院和省、自治区人民政府城乡规划主管部门应当定期对各地的城市设计工作和风貌管理情况进行检查。"},{"i":20,"n":"第二十条","txt":"城市、县人民政府城乡规划主管部门进行建筑设计方案审查和规划核实时，应当审核城市设计要求落实情况。"},{"i":21,"n":"第二十一条","txt":"城市、县人民政府城乡规划主管部门开展城市规划实施评估时，应当同时评估城市设计工作实施情况。"},{"i":22,"n":"第二十二条","txt":"城市设计的技术管理规定由国务院城乡规划主管部门另行制定。"},{"i":23,"n":"第二十三条","txt":"各地可根据本办法，按照实际情况，制定实施细则和技术导则。"},{"i":24,"n":"第二十四条","txt":"县人民政府所在地以外的镇可以参照本办法开展城市设计工作。"},{"i":25,"n":"第二十五条","txt":"本办法自2017年6月1日起施行。"}],"chengshihuangxianguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强城市基础设施用地管理，保障城市基础设施的正常、高效运转，保证城市经济、社会健康发展，根据《中华人民共和国城乡规划法》，制定本办法。"},{"i":2,"n":"第二条","txt":"城市黄线的划定和规划管理，适用本办法。 本办法所称城市黄线，是指对城市发展全局有影响的、城市规划中确定的、必须控制的城市基础设施用地的控制界线。 本办法所称城市基础设施包括： （一）城市公共汽车首末站、出租汽车停车场、大型公共停车场；城市轨道交通线、站、场、车辆段、保养维修基地；城市水运码头；机场；城市交通综合换乘枢纽；城市交通广场等城市公共交通设施。 （二）取水工程设施（取水点、取水构筑物及一级泵站）和水处理工程设施等城市供水设施。 （三）排水设施；污水处理设施；垃圾转运站、垃圾码头、垃圾堆肥厂、垃圾焚烧厂、卫生填埋场（厂）；环境卫生车辆停车场和修造厂；环境质量监测站等城市环境卫生设施。 （四）城市气源和燃气储配站等城市供燃气设施。 （五）城市热源、区域性热力站、热力线走廊等城市供热设施。 （六）城市发电厂、区域变电所（站）、市区变电所（站）、高压线走廊等城市供电设施。 （七）邮政局"},{"i":3,"n":"第三条","txt":"国务院建设主管部门负责全国城市黄线管理工作。 县级以上地方人民政府建设主管部门（城乡规划主管部门）负责本行政区域内城市黄线的规划管理工作。"},{"i":4,"n":"第四条","txt":"任何单位和个人都有保护城市基础设施用地、服从城市黄线管理的义务，有监督城市黄线管理、对违反城市黄线管理的行为进行检举的权利。"},{"i":5,"n":"第五条","txt":"城市黄线应当在制定城市总体规划和详细规划时划定。 直辖市、市、县人民政府建设主管部门（城乡规划主管部门）应当根据不同规划阶段的规划深度要求，负责组织划定城市黄线的具体工作。"},{"i":6,"n":"第六条","txt":"城市黄线的划定，应当遵循以下原则： （一）与同阶段城市规划内容及深度保持一致； （二）控制范围界定清晰； （三）符合国家有关技术标准、规范。"},{"i":7,"n":"第七条","txt":"编制城市总体规划，应当根据规划内容和深度要求，合理布置城市基础设施，确定城市基础设施的用地位置和范围，划定其用地控制界线。"},{"i":8,"n":"第八条","txt":"编制控制性详细规划，应当依据城市总体规划，落实城市总体规划确定的城市基础设施的用地位置和面积，划定城市基础设施用地界线，规定城市黄线范围内的控制指标和要求，并明确城市黄线的地理坐标。 修建性详细规划应当依据控制性详细规划，按不同项目具体落实城市基础设施用地界线，提出城市基础设施用地配置原则或者方案，并标明城市黄线的地理坐标和相应的界址地形图。"},{"i":9,"n":"第九条","txt":"城市黄线应当作为城市规划的强制性内容，与城市规划一并报批。城市黄线上报审批前，应当进行技术经济论证，并征求有关部门意见。"},{"i":10,"n":"第十条","txt":"城市黄线经批准后，应当与城市规划一并由直辖市、市、县人民政府予以公布；但法律、法规规定不得公开的除外。"},{"i":11,"n":"第十一条","txt":"城市黄线一经批准，不得擅自调整。 因城市发展和城市功能、布局变化等，需要调整城市黄线的，应当组织专家论证，依法调整城市规划，并相应调整城市黄线。调整后的城市黄线，应当随调整后的城市规划一并报批。 调整后的城市黄线应当在报批前进行公示，但法律、法规规定不得公开的除外。"},{"i":12,"n":"第十二条","txt":"在城市黄线内进行建设活动，应当贯彻安全、高效、经济的方针，处理好近远期关系，根据城市发展的实际需要，分期有序实施。"},{"i":13,"n":"第十三条","txt":"在城市黄线范围内禁止进行下列活动： （一）违反城市规划要求，进行建筑物、构筑物及其他设施的建设； （二）违反国家有关技术标准和规范进行建设； （三）未经批准，改装、迁移或拆毁原有城市基础设施； （四）其他损坏城市基础设施或影响城市基础设施安全和正常运转的行为。"},{"i":14,"n":"第十四条","txt":"在城市黄线内进行建设，应当符合经批准的城市规划。 在城市黄线内新建、改建、扩建各类建筑物、构筑物、道路、管线和其他工程设施，应当依法向建设主管部门（城乡规划主管部门）申请办理城市规划许可，并依据有关法律、法规办理相关手续。 迁移、拆除城市黄线内城市基础设施的，应当依据有关法律、法规办理相关手续。"},{"i":15,"n":"第十五条","txt":"因建设或其他特殊情况需要临时占用城市黄线内土地的，应当依法办理相关审批手续。"},{"i":16,"n":"第十六条","txt":"县级以上地方人民政府建设主管部门（城乡规划主管部门）应当定期对城市黄线管理情况进行监督检查。"},{"i":17,"n":"第十七条","txt":"违反本办法规定，有下列行为之一的，依据《中华人民共和国城乡规划法》等法律、法规予以处罚： （一）未经直辖市、市、县人民政府建设主管部门（城乡规划主管部门）批准在城市黄线范围内进行建设活动的； （二）擅自改变城市黄线内土地用途的； （三）未按规划许可的要求进行建设的。"},{"i":18,"n":"第十八条","txt":"县级以上地方人民政府建设主管部门（城乡规划主管部门）违反本办法规定，批准在城市黄线范围内进行建设的，对有关责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"本办法自2006年3月1日起施行。"}],"chengzhenwushuipairupaishuiguanwangxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对污水排入城镇排水管网的管理，保障城镇排水与污水处理设施安全运行，防治城镇水污染，根据《中华人民共和国行政许可法》、《城镇排水与污水处理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内申请污水排入排水管网许可（以下称排水许可），对从事工业、建筑、餐饮、医疗等活动的企业事业单位、个体工商户（以下称排水户）向城镇排水设施排放污水的活动实施监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"国务院住房和城乡建设主管部门负责全国排水许可工作的指导监督。 省、自治区人民政府住房和城乡建设主管部门负责本行政区域内排水许可工作的指导监督。 直辖市、市、县人民政府城镇排水与污水处理主管部门（以下简称城镇排水主管部门）负责本行政区域内排水许可证书的颁发和监督管理。城镇排水主管部门可以委托专门机构承担排水许可审核管理的具体工作。"},{"i":4,"n":"第四条","txt":"城镇排水设施覆盖范围内的排水户应当按照国家有关规定，将污水排入城镇排水设施。排水户向城镇排水设施排放污水，应当按照本办法的规定，申请领取排水许可证。未取得排水许可证，排水户不得向城镇排水设施排放污水。城镇居民排放生活污水不需要申请领取排水许可证。 在雨水、污水分流排放的地区，不得将污水排入雨水管网。 工程建设疏干排水应当优先利用和补给水体。"},{"i":5,"n":"第五条","txt":"城镇排水主管部门应当因地制宜，按照排水行为影响城镇排水与污水处理设施安全运行的程度，对排水户进行分级分类管理。 对列入重点排污单位名录的排水户和城镇排水主管部门确定的对城镇排水与污水处理设施安全运行影响较大的排水户，应当作为重点排水户进行管理。"},{"i":6,"n":"第六条","txt":"排水户向排水行为发生地的城镇排水主管部门申请领取排水许可证。城镇排水主管部门应当自受理申请之日起15日内作出决定。 集中管理的建筑或者单位内有多个排水户的，可以由产权单位或者其委托的物业服务人统一申请领取排水许可证，并由领证单位对排水户的排水行为负责。 因施工作业需要向城镇排水设施排入污水的，由建设单位申请领取排水许可证。"},{"i":7,"n":"第七条","txt":"申请领取排水许可证，应当如实提交下列材料： （一）排水许可申请表； （二）排水户内部排水管网、专用检测井、雨污水排放口位置和口径的图纸及说明等材料； （三）按照国家有关规定建设污水预处理设施的有关材料； （四）排水隐蔽工程竣工报告，或者排水户承诺排水隐蔽工程合格且不存在雨水污水管网混接错接、雨水污水混排的书面承诺书； （五）排水水质符合相关标准的检测报告或者排水水质符合相关标准的书面承诺书； （六）列入重点排污单位名录的排水户应当提供已安装的主要水污染物排放自动监测设备有关材料；"},{"i":8,"n":"第八条","txt":"城镇排水主管部门在作出许可决定前，应当按照排水户分级分类管理要求，对重点排水户进行现场核查，对其他排水户采取抽查方式进行现场核查。"},{"i":9,"n":"第九条","txt":"符合以下条件的，由城镇排水主管部门核发排水许可证： （一）污水排放口的设置符合城镇排水与污水处理规划的要求； （二）排放污水的水质符合国家或者地方规定的有关排放标准； （三）按照国家有关规定建设相应的预处理设施； （四）按照国家有关规定在排放口设置便于采样和水量计量的专用检测井和计量设备；列入重点排污单位名录的排水户已安装主要水污染物排放自动监测设备； （五）法律、法规规定的其他条件。"},{"i":10,"n":"第十条","txt":"排水许可证的有效期为5年。 因施工作业需要向城镇排水设施排水的，排水许可证的有效期，由城镇排水主管部门根据排水状况确定，但不得超过施工期限。"},{"i":11,"n":"第十一条","txt":"排水许可证有效期满需要继续排放污水的，排水户应当在有效期届满30日前，向城镇排水主管部门提出申请。城镇排水主管部门应当在有效期届满前作出是否准予延续的决定。准予延续的，有效期延续5年。 排水户在排水许可证有效期内，严格按照许可内容排放污水，且未发生违反本办法规定行为的，有效期届满30日前，排水户可提出延期申请，经原许可机关同意，不再进行审查，排水许可证有效期延期5年。"},{"i":12,"n":"第十二条","txt":"在排水许可证的有效期内，排水口数量和位置、排水量、主要污染物项目或者浓度等排水许可内容变更的，排水户应当按照本办法规定，重新申请领取排水许可证。 排水户名称、法定代表人等其他事项变更的，排水户应当在变更之日起30日内向城镇排水主管部门申请办理变更。"},{"i":13,"n":"第十三条","txt":"排水户应当按照排水许可证确定的排水类别、总量、时限、排放口位置和数量、排放的主要污染物项目和浓度等要求排放污水。"},{"i":14,"n":"第十四条","txt":"排水户不得有下列危及城镇排水设施安全的活动： （一）向城镇排水设施排放、倾倒剧毒、易燃易爆、腐蚀性废液和废渣； （二）向城镇排水设施排放有害气体和烹饪油烟； （三）堵塞城镇排水设施或者向城镇排水设施内排放、倾倒垃圾、渣土、施工泥浆、油脂、污泥等易堵塞物； （四）擅自拆卸、移动、穿凿和接入城镇排水设施； （五）擅自向城镇排水设施加压排放污水； （六）其他危及城镇排水与污水处理设施安全的活动。"},{"i":15,"n":"第十五条","txt":"排水户因发生事故或者其他突发事件，排放的污水可能危及城镇排水与污水处理设施安全运行的，应当立即暂停排放，采取措施消除危害，并按规定及时向城镇排水主管部门等有关部门报告。"},{"i":16,"n":"第十六条","txt":"城镇排水主管部门应当加强对排水户的排放口设置、连接管网、预处理设施和水质、水量监测设施建设和运行的指导和监督。"},{"i":17,"n":"第十七条","txt":"重点排水户应当建立档案管理制度，对污水预处理设施、内部排水管网、与市政管网的连接管、专用检测井运行维护情况、发生异常的原因和采取的措施等进行记录，记录保存期限不少于5年。 鼓励排水户推进传统载体档案数字化。电子档案与传统载体档案具有同等效力。"},{"i":18,"n":"第十八条","txt":"城镇排水主管部门应当结合排水户分级分类情况，通过‘双随机、一公开’方式，对排水户排放污水的情况实施监督检查。实施监督检查时，有权采取下列措施： （一）进入现场开展检查、监测； （二）要求被监督检查的排水户出示排水许可证； （三）查阅、复制有关文件和材料； （四）要求被监督检查的单位和个人就有关问题作出说明； （五）依法采取禁止排水户向城镇排水设施排放污水等措施，纠正违反有关法律、法规和本办法规定的行为。 被监督检查的单位和个人应当予以配合，不得妨碍和阻挠依法进行的监督检查活动。 城镇排水主管部门可以通过政府购买服务等方式，组织或者委托排水监测机构等技术服务单位为排水许可监督检查工作提供技术服务。受委托的具有计量认证资质的排水监测机构应当对排水户排放污水的水质、水量进行监测，建立排水监测档案。"},{"i":19,"n":"第十九条","txt":"城镇排水主管部门委托的专门机构，可以开展排水许可审查、档案管理、监督指导排水户排水行为等工作，并协助城镇排水主管部门对排水许可实施监督管理。"},{"i":20,"n":"第二十条","txt":"城镇排水主管部门应当将排水户的基本信息、排水许可内容等信息载入城市排水信息系统。涉及排水户的排水许可内容、行政处罚、不良信用记录等信息，应当依法向社会公示。 城镇排水主管部门可以根据排水户的信用情况，依法采取守信激励、失信惩戒措施。"},{"i":21,"n":"第二十一条","txt":"有下列情形之一的，许可机关或者其上级行政机关，根据利害关系人的请求或者依据职权，可以撤销排水许可： （一）城镇排水主管部门工作人员滥用职权、玩忽职守作出准予排水许可决定的； （二）超越法定职权作出准予排水许可决定的； （三）违反法定程序作出准予排水许可决定的； （四）对不符合许可条件的申请人作出准予排水许可决定的； （五）依法可以撤销排水许可的其他情形。 排水户以欺骗、贿赂等不正当手段取得排水许可的，应当予以撤销。"},{"i":22,"n":"第二十二条","txt":"有下列情形之一的，城镇排水主管部门应当依法办理排水许可的注销手续： （一）排水户依法终止的； （二）排水许可依法被撤销、撤回，或者排水许可证被吊销的； （三）排水许可证有效期满且未延续许可的； （四）法律、法规规定的应当注销排水许可的其他情形。"},{"i":23,"n":"第二十三条","txt":"城镇排水主管部门应当按照国家有关规定将监督检查的情况向社会公开。 城镇排水主管部门及其委托的专门机构、排水监测机构的工作人员对知悉的被监督检查单位和个人的技术和商业秘密负有保密义务。"},{"i":24,"n":"第二十四条","txt":"城镇排水主管部门实施排水许可不得收费。 城镇排水主管部门实施排水许可所需经费，应当列入城镇排水主管部门的预算，由本级财政予以保障，按照批准的预算予以核拨。"},{"i":25,"n":"第二十五条","txt":"城镇排水主管部门有下列情形之一的，由其上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）对不符合本规定条件的申请人准予排水许可的； （二）对符合本规定条件的申请人不予核发排水许可证或者不在法定期限内作出准予许可决定的； （三）利用职务上的便利，收受他人财物或者谋取其他利益的； （四）泄露被监督检查单位和个人的技术或者商业秘密的； （五）不依法履行监督管理职责或者监督不力，造成严重后果的。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，在城镇排水与污水处理设施覆盖范围内，未按照国家有关规定将污水排入城镇排水设施，或者在雨水、污水分流地区将污水排入雨水管网的，由城镇排水主管部门责令改正，给予警告；逾期不改正或者造成严重后果的，对单位处10万元以上20万元以下罚款；对个人处2万元以上10万元以下罚款，造成损失的，依法承担赔偿责任。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，排水户未取得排水许可，向城镇排水设施排放污水的，由城镇排水主管部门责令停止违法行为，限期采取治理措施，补办排水许可证，可以处50万元以下罚款；对列入重点排污单位名录的排水户，可以处30万元以上50万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"排水户未按照排水许可证的要求，向城镇排水设施排放污水的，由城镇排水主管部门责令停止违法行为，限期改正，可以处5万元以下罚款；造成严重后果的，吊销排水许可证，并处5万元以上50万元以下罚款，对列入重点排污单位名录的排水户，处30万元以上50万元以下罚款，并将有关情况通知同级环境保护主管部门，可以向社会予以通报；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"排水户名称、法定代表人等其他事项变更，未按本办法规定及时向城镇排水主管部门申请办理变更的，由城镇排水主管部门责令改正，可以处1万元以下罚款。"},{"i":30,"n":"第三十条","txt":"排水户以欺骗、贿赂等不正当手段取得排水许可的，可以处3万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"违反本办法规定，排水户因发生事故或者其他突发事件，排放的污水可能危及城镇排水与污水处理设施安全运行，没有立即暂停排放，未采取措施消除危害，或者并未按规定及时向城镇排水主管部门等有关部门报告的，城镇排水主管部门可以处3万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定，从事危及城镇排水设施安全的活动的，由城镇排水主管部门责令停止违法行为，限期恢复原状或者采取其他补救措施，并给予警告；逾期不采取补救措施或者造成严重后果的，对单位处10万元以上30万元以下罚款，对个人处2万元以上10万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"重点排水户未按照本办法规定建立档案管理制度，或者档案记录保存期限少于5年的，由城镇排水主管部门责令改正，可以处3万元以下罚款。"},{"i":34,"n":"第三十四条","txt":"排水户违反本办法规定，拒不接受水质、水量监测或者妨碍、阻挠城镇排水主管部门依法监督检查的，由城镇排水主管部门给予警告；情节严重的，处3万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"排水许可证由国务院住房和城乡建设主管部门制定格式，由省、自治区人民政府住房和城乡建设主管部门以及直辖市人民政府城镇排水主管部门组织印制。鼓励城镇排水主管部门实行电子许可证，电子许可证与纸质许可证具有同等效力。 排水许可申请表、排水户书面承诺书由国务院住房和城乡建设主管部门制定推荐格式，城镇排水主管部门可以参考制定。"},{"i":36,"n":"第三十六条","txt":"本办法自2015年3月1日起施行。《城市排水许可管理办法》（建设部令第152号）同时废止。"}],"shishigongchengjiansheqiangzhixingbiaozhunjiandugua83a4a":[{"i":1,"n":"第一条","txt":"为加强工程建设强制性标准实施的监督工作，保证建设工程质量，保障人民的生命、财产安全，维护社会公共利益，根据《中华人民共和国标准化法》、《中华人民共和国标准化法实施条例》、《建设工程质量管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事新建、扩建、改建等工程建设活动，必须执行工程建设强制性标准。"},{"i":3,"n":"第三条","txt":"本规定所称工程建设强制性标准是指直接涉及工程质量、安全、卫生及环境保护等方面的工程建设标准强制性条文。 国家工程建设标准强制性条文由国务院住房城乡建设主管部门会同国务院有关主管部门确定。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责全国实施工程建设强制性标准的监督管理工作。 国务院有关主管部门按照国务院的职能分工负责实施工程建设强制性标准的监督管理工作。 县级以上地方人民政府住房城乡建设主管部门负责本行政区域内实施工程建设强制性标准的监督管理工作。"},{"i":5,"n":"第五条","txt":"建设工程勘察、设计文件中规定采用的新技术、新材料，可能影响建设工程质量和安全，又没有国家技术标准的，应当由国家认可的检测机构进行试验、论证，出具检测报告，并经国务院有关主管部门或者省、自治区、直辖市人民政府有关主管部门组织的建设工程技术专家委员会审定后，方可使用。"},{"i":6,"n":"第六条","txt":"建设项目规划审查机关应当对工程建设规划阶段执行强制性标准的情况实施监督。 施工图设计文件审查单位应当对工程建设勘察、设计阶段执行强制性标准的情况实施监督。 建筑安全监督管理机构应当对工程建设施工阶段执行施工安全强制性标准的情况实施监督。 工程质量监督机构应当对工程建设施工、监理、验收等阶段执行强制性标准的情况实施监督。"},{"i":7,"n":"第七条","txt":"建设项目规划审查机关、施工图设计文件审查单位、建筑安全监督管理机构、工程质量监督机构的技术人员必须熟悉、掌握工程建设强制性标准。"},{"i":8,"n":"第八条","txt":"工程建设标准批准部门应当定期对建设项目规划审查机关、施工图设计文件审查单位、建筑安全监督管理机构、工程质量监督机构实施强制性标准的监督进行检查，对监督不力的单位和个人，给予通报批评，建议有关部门处理。"},{"i":9,"n":"第九条","txt":"工程建设标准批准部门应当对工程项目执行强制性标准情况进行监督检查。监督检查可以采取重点检查、抽查和专项检查的方式。"},{"i":10,"n":"第十条","txt":"强制性标准监督检查的内容包括： （一）有关工程技术人员是否熟悉、掌握强制性标准； （二）工程项目的规划、勘察、设计、施工、验收等是否符合强制性标准的规定； （三）工程项目采用的材料、设备是否符合强制性标准的规定； （四）工程项目的安全、质量是否符合强制性标准的规定； （五）工程中采用的导则、指南、手册、计算机软件的内容是否符合强制性标准的规定。"},{"i":11,"n":"第十一条","txt":"工程建设标准批准部门应当将强制性标准监督检查结果在一定范围内公告。"},{"i":12,"n":"第十二条","txt":"工程建设强制性标准的解释由工程建设标准批准部门负责。 有关标准具体技术内容的解释，工程建设标准批准部门可以委托该标准的编制管理单位负责。"},{"i":13,"n":"第十三条","txt":"工程技术人员应当参加有关工程建设强制性标准的培训，并可以计入继续教育学时。"},{"i":14,"n":"第十四条","txt":"住房城乡建设主管部门或者有关主管部门在处理重大工程事故时，应当有工程建设标准方面的专家参加；工程事故报告应当包括是否符合工程建设强制性标准的意见。"},{"i":15,"n":"第十五条","txt":"任何单位和个人对违反工程建设强制性标准的行为有权向住房城乡建设主管部门或者有关部门检举、控告、投诉。"},{"i":16,"n":"第十六条","txt":"建设单位有下列行为之一的，责令改正，并处以20万元以上50万元以下的罚款： （一）明示或者暗示施工单位使用不合格的建筑材料、建筑构配件和设备的； （二）明示或者暗示设计单位或者施工单位违反工程建设强制性标准，降低工程质量的。"},{"i":17,"n":"第十七条","txt":"勘察、设计单位违反工程建设强制性标准进行勘察、设计的，责令改正，并处以10万元以上30万元以下的罚款。 有前款行为，造成工程质量事故的，责令停业整顿，降低资质等级；情节严重的，吊销资质证书；造成损失的，依法承担赔偿责任。"},{"i":18,"n":"第十八条","txt":"施工单位违反工程建设强制性标准的，责令改正，处工程合同价款２％以上４％以下的罚款；造成建设工程质量不符合规定的质量标准的，负责返工、修理，并赔偿因此造成的损失；情节严重的，责令停业整顿，降低资质等级或者吊销资质证书。"},{"i":19,"n":"第十九条","txt":"工程监理单位违反强制性标准规定，将不合格的建设工程以及建筑材料、建筑构配件和设备按照合格签字的，责令改正，处50万元以上100万元以下的罚款，降低资质等级或者吊销资质证书；有违法所得的，予以没收；造成损失的，承担连带赔偿责任。"},{"i":20,"n":"第二十条","txt":"违反工程建设强制性标准造成工程质量、安全隐患或者工程质量安全事故的，按照《建设工程质量管理条例》、《建设工程勘察设计管理条例》和《建设工程安全生产管理条例》的有关规定进行处罚。"},{"i":21,"n":"第二十一条","txt":"有关责令停业整顿、降低资质等级和吊销资质证书的行政处罚，由颁发资质证书的机关决定；其他行政处罚，由住房城乡建设主管部门或者有关部门依照法定职权决定。"},{"i":22,"n":"第二十二条","txt":"住房城乡建设主管部门和有关主管部门工作人员，玩忽职守、滥用职权、徇私舞弊的，给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"本规定由国务院住房城乡建设主管部门负责解释。"},{"i":24,"n":"第二十四条","txt":"本规定自发布之日起施行。"}],"gongchengjiansheguojiabiaozhunguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强工程建设国家标准的管理，促进技术进步，保证工程质量，保障人体健康和人身、财产安全，根据《中华人民共和国标准化法》、《中华人民共和国标准化法实施条例》和国家有关工程建设的法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"对需要在全国范围内统一的下列技术要求，应当制定国家标准： （一）工程建设勘察、规划、设计、施工（包括安装）及验收等通用的质量要求； （二）工程建设通用的有关安全、卫生和环境保护的技术要求； （三）工程建设通用的术语、符号、代号、量与单位、建筑模数和制图方法； （四）工程建设通用的试验、检验和评定等方法； （五）工程建设通用的信息技术要求； （六）国家需要控制的其他工程建设通用的技术要求。 法律另有规定的，依照法律的规定执行。"},{"i":3,"n":"第三条","txt":"国家标准分为强制性标准和推荐性标准。 下列标准属于强制性标准： （一）工程建设勘察、规划、设计、施工（包括安装）及验收等通用的综合标准和重要的通用的质量标准； （二）工程建设通用的有关安全、卫生和环境保护的标准； （三）工程建设重要的通用的术语、符号、代号、量与单位、建筑模数和制图方法标准； （四）工程建设重要的通用的试验、检验和评定方法等标准； （五）工程建设重要的通用的信息技术标准； （六）国家需要控制的其他工程建设通用的标准。 强制性标准以外的标准是推荐性标准。"},{"i":4,"n":"第四条","txt":"国家标准的计划分为五年计划和年度计划。 五年计划是编制年度计划的依据；年度计划是确定工作任务和组织编制标准的依据。"},{"i":5,"n":"第五条","txt":"编制国家标准的计划，应当遵循下列原则： （一）在国民经济发展的总目标和总方针的指导下进行，体现国家的技术、经济政策； （二）适应工程建设和科学技术发展的需要； （三）在充分做好调查研究和认真总结经验的基础上，根据工程建设标准体系表的要求，综合考虑相关标准之间的构成和协调配套； （四）从实际出发，保证重点，统筹兼顾，根据需要和可能，分别轻重缓急，做好计划的综合平衡。"},{"i":6,"n":"第六条","txt":"五年计划由计划编制纲要和计划项目两部分组成。其内容应当符合下列要求： （一）计划编制纲要包括计划编制的依据、指导思想、预期目标、工作重点和实施计划的主要措施等； （二）计划项目的内容包括标准名称、制订或修订、适用范围及其主要技术内容、主编部门、主编单位和起始年限等。"},{"i":7,"n":"第七条","txt":"列入五年计划的国家标准制订项目应当落实主编单位、主编单位应当具备下列条件： （一）承担过与该国家标准项目相应的工程建设勘察、规划、设计、施工或科研任务的企业、事业单位； （二）具有较丰富的工程建设经验、较高的技术水平和组织管理水平，能组织解决国家标准编制中的重大技术问题。"},{"i":8,"n":"第八条","txt":"列入五年计划的国家标准修订项目，其主编单位一般由原国家标准的管理单位承担。"},{"i":9,"n":"第九条","txt":"五年计划的编制工作应当按下列程序进行： （一）国务院工程建设行政主管部门根据国家编制国民经济和社会发展五年计划的原则和要求，统一部署编制国家标准五年计划的任务； （二）国务院有关行政主管部门和省、自治区、直辖市工程建设行政主管部门，根据国务院工程建设行政主管部门统一部署的要求，提出五年计划建议草案，报国务院工程建设行政主管部门； （三）国务院工程建设行政主管部门对五年计划建议草案进行汇总，在与各有关方面充分协商的基础上进行综合平衡，并提出五年计划草案，报国务院计划行政主管部门批准下达。"},{"i":10,"n":"第十条","txt":"年度计划由计划编制的简要说明和计划项目两部分组成。计划项目的内容包括标准名称、制订或修订、适用范围及其主要技术内容、主编部门和主编单位、参加单位、起止年限、进度要求等。"},{"i":11,"n":"第十一条","txt":"年度计划应当在五年计划的基础上进行编制。国家标准项目在列入年度计划之前由主编单位做好年度计划的前期工作，并提出前期工作报告。前期工作报告应当包括：国家标准项目名称、目的和作用、技术条件和成熟程度、与各类现行标准的关系、预期的经济效益和社会效益、建议参编单位和起止年限。"},{"i":12,"n":"第十二条","txt":"列入年度计划的国家标准项目，应当具备下列条件： （一）有年度计划的前期工作报告； （二）有生产和建设的实践经验； （三）相应的科研成果经过鉴定和验证，具备推广应用的条件； （四）不与相关的国家标准重复或矛盾； （五）参编单位已落实。"},{"i":13,"n":"第十三条","txt":"年度计划的编制工作应当按下列程序进行： （一）国务院有关行政主管部门和省、自治区、直辖市工程建设行政主管部门，应当根据五年计划的要求，分期分批地安排各国家标准项目的主编单位进行年度计划的前期工作。由主编单位提出的前期工作报告和年度计划项目表，报主管部门审查； （二）国务院有关行政主管部门和省、自治区、直辖市工程建设行政主管部门，根据国务院工程建设行政主管部门当年的统一部署，做好所承担年度计划项目的落实工作并在规定期限前报国务院工程建设行政主管部门； （三）国务院工程建设行政主管部门根据各主管部门提出的计划项目，经综合平衡后，编制工程建设国家标准的年度计划草案，在规定期限前报国务院计划行政主管部门批准下达。"},{"i":14,"n":"第十四条","txt":"列入年度计划国家标准项目的主编单位应当按计划要求组织实施。在计划执行中遇有特殊情况，不能按原计划实施时，应当向主管部门提交申请变更计划的报告。各主管部门可根据实际情况提出调整计划的建议，经国务院工程建设行政主管部门批准后，按调整的计划组织实施。"},{"i":15,"n":"第十五条","txt":"国务院各有关行政主管部门和省、自治区、直辖市工程建设行政主管部门对主管的国家标准项目计划执行情况负有监督和检查的责任，并负责协调解决计划执行中的重大问题。各主编单位在每年年底前将本年度计划执行情况和下年度的工作安排报行政主管部门，并报国务院工程建设行政主管部门备案。"},{"i":16,"n":"第十六条","txt":"制订国家标准必须贯彻执行国家的有关法律、法规和方针、政策，密切结合自然条件，合理利用资源，充分考虑使用和维修的要求，做到安全适用、技术先进、经济合理。"},{"i":17,"n":"第十七条","txt":"制订国家标准，对需要进行科学试验或测试验证的项目，应当纳入各级主管部门的科研计划，认真组织实施，写出成果报告。凡经过行政主管部门或受委托单位鉴定，技术上成熟，经济上合理的项目应当纳入标准。"},{"i":18,"n":"第十八条","txt":"制订国家标准应当积极采用新技术、新工艺、新设备、新材料。纳入标准的新技术、新工艺、新设备、新材料，应当经有关主管部门或受委托单位鉴定，有完整的技术文件，且经实践检验行之有效。"},{"i":19,"n":"第十九条","txt":"制订国家标准要积极采用国际标准和国外先进标准，凡经过认真分析论证或测试验证，并且符合我国国情的，应当纳入国家标准。"},{"i":20,"n":"第二十条","txt":"制订国家标准，其条文规定应当严谨明确，文句简练，不得模棱两可；其内容深度、术语、符号、计量单位等应当前后一致，不得矛盾。"},{"i":21,"n":"第二十一条","txt":"制订国家标准必须做好与现行相关标准之间的协调工作。对需要与现行工程建设国家标准协调的，应当遵守现行工程建设国家标准的规定；确有充分依据对其内容进行更改的，必须经过国务院工程建设行政主管部门审批，方可另行规定。凡属于产品标准方面的内容，不得在工程建设国家标准中加以规定。"},{"i":22,"n":"第二十二条","txt":"制订国家标准必须充分发扬民主。对国家标准中有关政策性问题，应当认真研究、充分讨论、统一认识；对有争论的技术性问题，应当在调查研究、试验验证或专题讨论的基础上，经过充分协商，恰如其分地做出结论。"},{"i":23,"n":"第二十三条","txt":"制订国家标准的工作程序按准备、征求意见、送审和报批四个阶段进行。"},{"i":24,"n":"第二十四条","txt":"准备阶段的工作应当符合下列要求： （一）主编单位根据年度计划的要求，进行编制国家标准的筹备工作。落实国家标准编制组成员，草拟制订国家标准的工作大纲。工作大纲包括国家标准的主要章节内容、需要调查研究的主要问题、必要的测试验证项目、工作进度计划及编制组成员分工等内容； （二）主编单位筹备工作完成后，由主编部门或由主编部门委托主编单位主持召开编制组第一次工作会议。其内容包括：宣布编制组成员、学习工程建设标准化工作的有关文件、讨论通过工作大纲和会议纪要。会议纪要印发国家标准的参编部门和单位，并报国务院工程建设行政主管部门备案。"},{"i":25,"n":"第二十五条","txt":"征求意见阶段的工作应当符合下列要求： （一）编制组根据制订国家标准的工作大纲开展调查研究工作。调查对象应当具有代表性和典型性。调查研究工作结束后，应当及时提出调查研究报告，并将整理好的原始调查记录和收集到的国内外有关资料由编制组统一归档； （二）测试验证工作在编制组统一计划下进行，落实负责单位、制订测试验证工作大纲、确定统一的测试验证方法等。测试验证结果，应当由项目的负责单位组织有关专家进行鉴定。鉴定成果及有关的原始资料由编制组统一归档； （三）编制组对国家标准中的重大问题或有分歧的问题，应当根据需要召开专题会议。专题会议邀请有代表性和有经验的专家参加，并应当形成会议纪要。会议纪要及会议记录等由编制组统一归档； （四）编制组在做好上述各项工作的基础上，编写标准征求意见稿及其条文说明。主编单位对标准征求意见稿及其条文说明的内容全面负责； （五）主编部门对主编单位提出的征求意见稿及其条文说"},{"i":26,"n":"第二十六条","txt":"送审阶段的工作应当符合下列要求： （一）编制组将征求意见阶段收集到的意见，逐条归纳整理，在分析研究的基础上提出处理意见，形成国家标准送审稿及其条文说明。对其中有争议的重大问题可以视具体情况进行补充的调查研究、测试验证或召开专题会议，提出处理意见； （二）当国家标准需要进行全面的综合技术经济比较时，编制组要按国家标准送审稿组织试设计或施工试用。试设计或施工试用应当选择有代表性的工程进行。试设计或施工试用结束后应当提出报告； （三）国家标准送审的文件一般应当包括：国家标准送审稿及其条文说明、送审报告、主要问题的专题报告、试设计或施工试用报告等。送审报告的内容主要包括：制订标准任务的来源、制订标准过程中所作的主要工作、标准中重点内容确定的依据及其成熟程度、与国外相关标准水平的对比、标准实施后的经济效益和社会效益以及对标准的初步总评价、标准中尚存在的主要问题和今后需要进行的主要工作等； （四）"},{"i":27,"n":"第二十七条","txt":"报批阶段的工作应当符合下列要求： （一）编制组根据审查会议或函审和小型审定会议的审查意见，修改标准送审稿及其条文说明，形成标准报批稿及其条文说明。标准的报批文件经主编单位审查后报主编部门。报批文件一般包括标准报批稿及其条文说明、报批报告、审查或审定会议纪要、主要问题的专题报告、试设计或施工试用报告等。 （二）主编部门应当对标准报批文件进行全面审查，并会同国务院工程建设行政主管部门共同对标准报批稿进行审核。主编部门将共同确认的标准报批文件一式三份报国务院工程建设行政主管部门审批。"},{"i":28,"n":"第二十八条","txt":"国家标准由国务院工程建设行政主管部门审查批准，由国务院标准化行政主管部门统一编号，由国务院标准化行政主管部门和国务院工程建设行政主管部门联合发布。"},{"i":29,"n":"第二十九条","txt":"国家标准的编号由国家标准代号、发布标准的顺序号和发布标准的年号组成，并应当符合下列统一格式： （一）强制性国家标准的编号为： GB　50 ＊＊＊— ＊＊ ─┬─　─┬──　┬─ └───┼───┼───────强制性国家标准的代号 └───┼────────发布标准的顺序号 └─────────发布标准的年号 （二）推荐性国家编号为： GB／T　50＊＊＊　—　＊＊ ─┬─　─┬──　　─┬─ └───┼─────┼───────推荐性国家标准的代号 └─────┼─────发布标准的顺序号 └───发布标准的年号"},{"i":30,"n":"第三十条","txt":"国家标准的出版由国务院工程建设行政主管部门负责组织。国家标准的出版印刷应当符合工程建设标准出版印刷的统一要求。"},{"i":31,"n":"第三十一条","txt":"国家标准属于科技成果。对技术水平高、取得显著经济效益或社会效益的国家标准，应当纳入各级科学技术进步奖励范围，予以奖励。"},{"i":32,"n":"第三十二条","txt":"国家标准实施后，应当根据科学技术的发展和工程建设的需要，由该国家标准的管理部门适时组织有关单位进行复审。复审一般在国家标准实施后五年进行一次。"},{"i":33,"n":"第三十三条","txt":"国家标准复审的具体工作由国家标准管理单位负责。复审可以采取函审或会议审查，一般由参加过该标准编制或审查的单位或个人参加。"},{"i":34,"n":"第三十四条","txt":"国家标准复审后，标准管理单位应当提出其继续有效或者予以修订、废止的意见，经该国家标准的主管部门确认后报国务院工程建设行政主管部门批准。"},{"i":35,"n":"第三十五条","txt":"对确认继续有效的国家标准，当再版或汇编时，应在其封面或扉页上的标准编号下方增加“   年  月确认继续有效”。对确认继续有效或予以废止的国家标准，由国务院工程建设行政主管部门在指定的报刊上公布。"},{"i":36,"n":"第三十六条","txt":"对需要全面修订的国家标准，由其管理单位做好前期工作。国家标准修订的准备阶段工作应在管理阶段进行，其他有关的要求应当符合制订国家标准的有关规定。"},{"i":37,"n":"第三十七条","txt":"凡属下列情况之一的国家标准应当进行局部修订： （一）国家标准的部分规定已制约了科学技术新成果的推广应用； （二）国家标准的部分规定经修订后可取得明显的经济效益，社会效益，环境效益； （三）国家标准的部分规定有明显缺陷或与相关的国家标准相抵触； （四）需要对现行的国家标准做局部补充规定。"},{"i":38,"n":"第三十八条","txt":"国家标准局部修订的计划和编制程序，应当符合工程建设技术标准局部修订的统一规定。"},{"i":39,"n":"第三十九条","txt":"国家标准发布后，由其管理单位组建国家标准管理组，负责国家标准的日常管理工作。"},{"i":40,"n":"第四十条","txt":"国家标准管理组设专职或兼职若干人。其人员组成，经国家标准管理单位报该国家标准管理部门审定后报国务院工程建设行政主管部门备案。"},{"i":41,"n":"第四十一条","txt":"国家标准日常管理的主要任务是： （一）根据主管部门的授权负责国家标准的解释； （二）对国家标准中遗留的问题，负责组织调查研究、必要的测试验证和重点科研工作； （三）负责国家标准的宣传贯彻工作； （四）调查了解国家标准的实施情况，收集和研究国内外有关标准、技术信息资料和实践经验，参加相应的国际标准化活动； （五）参与有关工程建设质量事故的调查和咨询； （六）负责开展标准的研究和学术交流活动； （七）负责国家标准的复审、局部修订和技术档案工作。"},{"i":42,"n":"第四十二条","txt":"国家标准管理人员在该国家标准管理部门和管理单位的领导下工作。管理单位应当加强对其的领导，进行经常性的督促检查，定期研究和解决国家标准日常管理工作中的问题。"},{"i":43,"n":"第四十三条","txt":"推荐性国家标准可由国务院工程建设行政主管部门委托中国工程建设标准化协会等单位编制计划、组织制订。"},{"i":44,"n":"第四十四条","txt":"本办法由国务院工程建设行政主管部门负责解释。"},{"i":45,"n":"第四十五条","txt":"本办法自发布之日起施行。"}],"gongchengjianshehangyebiaozhunguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强工程建设行业标准的管理，根据《中华人民共和国标准化法》、《中华人民共和国标准化法实施条例》和国家有关工程建设的法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"对没有国家标准而需要在全国某个行业范围内统一的下列技术要求，可以制定行业标准： （一）工程建设勘察、规划、设计、施工（包括安装）及验收等行业专用的质量要求； （二）工程建设行业专用的有关安全、卫生和环境保护的技术要求； （三）工程建设行业专用的术语、符号、代号、量与单位和制图方法； （四）工程建设行业专用的试验、检验和评定等方法； （五）工程建设行业专用的信息技术要求； （六）其他工程建设行业专用的技术要求。"},{"i":3,"n":"第三条","txt":"行业标准分为强制性标准和推荐性标准。 下列标准属于强制性标准： （一）工程建设勘察、规划、设计、施工（包括安装）及验收等行业专用的综合性标准和重要的行业专用的质量标准； （二）工程建设行业专用的有关安全、卫生和环境保护的标准； （三）工程建设重要的行业专用的术语、符号、代号、量与单位和制图方法标准； （四）工程建设重要的行业专用的试验、检验和评定方法等标准； （五）工程建设重要的行业专用的信息技术标准； （六）行业需要控制的其他工程建设标准。 强制性标准以外的标准是推荐性标准。"},{"i":4,"n":"第四条","txt":"国务院有关行政主管部门根据《中华人民共和国标准化法》和国务院工程建设行政主管部门确定的行业标准管理范围，履行行业标准的管理职责。"},{"i":5,"n":"第五条","txt":"行业标准的计划根据国务院工程建设行政主管部门的统一部署由国务院有关行政主管部门组织编制和下达，并报国务院工程建设行政主管部门备案。 与两个以上国务院行政主管部门有关的行业标准，其主编部门由相关的行政主管部门协商确定或由国务院工程建设行政主管部门协调确定，其计划由被确定的主编部门下达。"},{"i":6,"n":"第六条","txt":"行业标准不得与国家标准相抵触。有关行业标准之间应当协调、统一、避免重复。"},{"i":7,"n":"第七条","txt":"制订、修订行业标准的工作程序，可以按准备、征求意见、送审和报批四个阶段进行。"},{"i":8,"n":"第八条","txt":"行业标准的编写应当符合工程建设标准编写的统一规定。"},{"i":9,"n":"第九条","txt":"行业标准由国务院有关行政主管部门审批、编号和发布。 其中，两个以上部门共同制订的行业标准，由有关的行政主管部门联合审批、发布，并由其主编部门负责编号。"},{"i":10,"n":"第十条","txt":"行业标准的某些规定与国家标准不一致时，必须有充分的科学依据和理由，并经国家标准的审批部门批准。 行业标准在相应的国家标准实施后，应当及时修订或废止。"},{"i":11,"n":"第十一条","txt":"行业标准实施后，该标准的批准部门应当根据科学技术的发展和工程建设的实际需要适时进行复审，确认其继续有效或予以修订、废止。一般五年复审一次，复审结果报国务院工程建设行政主管部门备案。"},{"i":12,"n":"第十二条","txt":"行业标准的编号由行业标准的代号、标准发布的顺序号和批准标准的年号组成，并应当符合下列统一格式： （一）强制性行业标准的编号： 　XX＊＊＊＊─＊＊ ─┬─　─┬──　┬─ 　└───┼───┼───────强制性行业标准的代号 　└───┼────────发布标准的顺序号 └─────────发布标准的年号 （二）推荐性行业标准的编号： 　XX/T　＊＊＊＊ ── ＊＊ ─┬─　─┬────┬─ 　└───┼──────┼───────推荐性行业标准的代号 └──────┼─────发布标准的顺序号 └───发布标准的年号"},{"i":13,"n":"第十三条","txt":"行业标准发布后，应当报国务院工程建设行政主管部门备案。"},{"i":14,"n":"第十四条","txt":"行业标准由标准的批准部门负责组织出版，并应当符合工程建设标准出版印刷的统一规定。"},{"i":15,"n":"第十五条","txt":"行业标准属于科技成果。对技术水平高，取得显著经济效益、社会效益和环境效益的行业标准，应当纳入各级科学技术进步奖励范围，并予以奖励。"},{"i":16,"n":"第十六条","txt":"国务院有关行政主管部门可以根据《中华人民共和国标准化法》，《中华人民共和国标准化法实施条例》和本办法制定本行业的工程建设行业标准管理细则。"},{"i":17,"n":"第十七条","txt":"本办法由国务院工程建设行政主管部门负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自发布之日起实施。原《工程建设专业标准规范管理暂行办法》同时废止。"}],"gongchengjianliqiyezizhiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强工程监理企业资质管理，规范建设工程监理活动，维护建筑市场秩序，根据《中华人民共和国建筑法》、《中华人民共和国行政许可法》、《建设工程质量管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事建设工程监理活动，申请工程监理企业资质，实施对工程监理企业资质监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"从事建设工程监理活动的企业，应当按照本规定取得工程监理企业资质，并在工程监理企业资质证书（以下简称资质证书）许可的范围内从事工程监理活动。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责全国工程监理企业资质的统一监督管理工作。国务院铁路、交通、水利、信息产业、民航等有关部门配合国务院住房城乡建设主管部门实施相关资质类别工程监理企业资质的监督管理工作。 省、自治区、直辖市人民政府住房城乡建设主管部门负责本行政区域内工程监理企业资质的统一监督管理工作。省、自治区、直辖市人民政府交通、水利、信息产业等有关部门配合同级住房城乡建设主管部门实施相关资质类别工程监理企业资质的监督管理工作。"},{"i":5,"n":"第五条","txt":"工程监理行业组织应当加强工程监理行业自律管理。 鼓励工程监理企业加入工程监理行业组织。"},{"i":6,"n":"第六条","txt":"工程监理企业资质分为综合资质、专业资质和事务所资质。其中，专业资质按照工程性质和技术特点划分为若干工程类别。 综合资质、事务所资质不分级别。专业资质分为甲级、乙级；其中，房屋建筑、水利水电、公路和市政公用专业资质可设立丙级。"},{"i":7,"n":"第七条","txt":"工程监理企业的资质等级标准如下： （一）综合资质标准 1．具有独立法人资格且具有符合国家有关规定的资产。 2、企业技术负责人应为注册监理工程师，并具有15年以上从事工程建设工作的经历或者具有工程类高级职称。 3、具有5个以上工程类别的专业甲级工程监理资质。 4、注册监理工程师不少于60人，注册造价工程师不少于5人，一级注册建造师、一级注册建筑师、一级注册结构工程师或者其它勘察设计注册工程师合计不少于15人次。 5、企业具有完善的组织结构和质量管理体系，有健全的技术、档案等管理制度。 6、企业具有必要的工程试验检测设备。 7、申请工程监理资质之日前一年内没有本规定第十六条禁止的行为。 8、申请工程监理资质之日前一年内没有因本企业监理责任造成重大质量事故。 9、申请工程监理资质之日前一年内没有因本企业监理责任发生三级以上工程建设重大安全事故或者发生两起以上四级工程建设安全事故。 （二）专业"},{"i":8,"n":"第八条","txt":"工程监理企业资质相应许可的业务范围如下： （一）综合资质 可以承担所有专业工程类别建设工程项目的工程监理业务。 （二）专业资质 1、专业甲级资质 可承担相应专业工程类别建设工程项目的工程监理业务（见附表2）。 2、专业乙级资质： 可承担相应专业工程类别二级以下（含二级）建设工程项目的工程监理业务（见附表2）。 3、专业丙级资质： 可承担相应专业工程类别三级建设工程项目的工程监理业务（见附表2）。 （三）事务所资质 可承担三级建设工程项目的工程监理业务（见附表2），但是，国家规定必须实行强制监理的工程除外。 工程监理企业可以开展相应类别建设工程的项目管理、技术咨询等业务。"},{"i":9,"n":"第九条","txt":"申请综合资质、专业甲级资质的，可以向企业工商注册所在地的省、自治区、直辖市人民政府住房城乡建设主管部门提交申请材料。 省、自治区、直辖市人民政府住房城乡建设主管部门收到申请材料后，应当在5日内将全部申请材料报审批部门。 国务院住房城乡建设主管部门在收到申请材料后，应当依法作出是否受理的决定，并出具凭证；申请材料不齐全或者不符合法定形式的，应当在5日内一次性告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。 国务院住房城乡建设主管部门应当自受理之日起20日内作出审批决定。自作出决定之日起10日内公告审批结果。其中，涉及铁路、交通、水利、通信、民航等专业工程监理资质的，由国务院住房城乡建设主管部门送国务院有关部门审核。国务院有关部门应当在15日内审核完毕，并将审核意见报国务院住房城乡建设主管部门。 组织专家评审所需时间不计算在上述时限内，但应当明确告知申请人。"},{"i":10,"n":"第十条","txt":"专业乙级、丙级资质和事务所资质由企业所在地省、自治区、直辖市人民政府住房城乡建设主管部门审批。 专业乙级、丙级资质和事务所资质许可、延续的实施程序由省、自治区、直辖市人民政府住房城乡建设主管部门依法确定。 省、自治区、直辖市人民政府住房城乡建设主管部门应当自作出决定之日起10日内，将准予资质许可的决定报国务院住房城乡建设主管部门备案。"},{"i":11,"n":"第十一条","txt":"工程监理企业资质证书分为正本和副本，每套资质证书包括一本正本，四本副本。正、副本具有同等法律效力。 工程监理企业资质证书的有效期为5年。 工程监理企业资质证书由国务院住房城乡建设主管部门统一印制并发放。"},{"i":12,"n":"第十二条","txt":"企业申请工程监理企业资质，在资质许可机关的网站或审批平台提出申请事项，提交专业技术人员、技术装备和已完成业绩等电子材料。"},{"i":13,"n":"第十三条","txt":"资质有效期届满，工程监理企业需要继续从事工程监理活动的，应当在资质证书有效期届满60日前，向原资质许可机关申请办理延续手续。 对在资质有效期内遵守有关法律、法规、规章、技术标准，信用档案中无不良记录，且专业技术人员满足资质标准要求的企业，经资质许可机关同意，有效期延续5年。"},{"i":14,"n":"第十四条","txt":"工程监理企业在资质证书有效期内名称、地址、注册资本、法定代表人等发生变更的，应当在工商行政管理部门办理变更手续后30日内办理资质证书变更手续。 涉及综合资质、专业甲级资质证书中企业名称变更的，由国务院住房城乡建设主管部门负责办理，并自受理申请之日起3日内办理变更手续。 前款规定以外的资质证书变更手续，由省、自治区、直辖市人民政府住房城乡建设主管部门负责办理。省、自治区、直辖市人民政府住房城乡建设主管部门应当自受理申请之日起3日内办理变更手续，并在办理资质证书变更手续后15日内将变更结果报国务院住房城乡建设主管部门备案。"},{"i":15,"n":"第十五条","txt":"申请资质证书变更，应当提交以下材料： （一）资质证书变更的申请报告； （二）企业法人营业执照副本原件； （三）工程监理企业资质证书正、副本原件。 工程监理企业改制的，除前款规定材料外，还应当提交企业职工代表大会或股东大会关于企业改制或股权变更的决议、企业上级主管部门关于企业申请改制的批复文件。"},{"i":16,"n":"第十六条","txt":"工程监理企业不得有下列行为： （一）与建设单位串通投标或者与其他工程监理企业串通投标，以行贿手段谋取中标； （二）与建设单位或者施工单位串通弄虚作假、降低工程质量； （三）将不合格的建设工程、建筑材料、建筑构配件和设备按照合格签字； （四）超越本企业资质等级或以其他企业名义承揽监理业务； （五）允许其他单位或个人以本企业的名义承揽工程； （六）将承揽的监理业务转包； （七）在监理过程中实施商业贿赂； （八）涂改、伪造、出借、转让工程监理企业资质证书； （九）其他违反法律法规的行为。"},{"i":17,"n":"第十七条","txt":"工程监理企业合并的，合并后存续或者新设立的工程监理企业可以承继合并前各方中较高的资质等级，但应当符合相应的资质等级条件。 工程监理企业分立的，分立后企业的资质等级，根据实际达到的资质条件，按照本规定的审批程序核定。"},{"i":18,"n":"第十八条","txt":"企业需增补工程监理企业资质证书的（含增加、更换、遗失补办），应当持资质证书增补申请及电子文档等材料向资质许可机关申请办理。遗失资质证书的，在申请补办前应当在公众媒体刊登遗失声明。资质许可机关应当自受理申请之日起3日内予以办理。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府住房城乡建设主管部门和其他有关部门应当依照有关法律、法规和本规定，加强对工程监理企业资质的监督管理。"},{"i":20,"n":"第二十条","txt":"住房城乡建设主管部门履行监督检查职责时，有权采取下列措施： （一）要求被检查单位提供工程监理企业资质证书、注册监理工程师注册执业证书，有关工程监理业务的文档，有关质量管理、安全生产管理、档案管理等企业内部管理制度的文件； （二）进入被检查单位进行检查，查阅相关资料； （三）纠正违反有关法律、法规和本规定及有关规范和标准的行为。"},{"i":21,"n":"第二十一条","txt":"住房城乡建设主管部门进行监督检查时，应当有两名以上监督检查人员参加，并出示执法证件，不得妨碍被检查单位的正常经营活动，不得索取或者收受财物、谋取其他利益。 有关单位和个人对依法进行的监督检查应当协助与配合，不得拒绝或者阻挠。 监督检查机关应当将监督检查的处理结果向社会公布。"},{"i":22,"n":"第二十二条","txt":"工程监理企业违法从事工程监理活动的，违法行为发生地的县级以上地方人民政府住房城乡建设主管部门应当依法查处，并将违法事实、处理结果或处理建议及时报告该工程监理企业资质的许可机关。"},{"i":23,"n":"第二十三条","txt":"工程监理企业取得工程监理企业资质后不再符合相应资质条件的，资质许可机关根据利害关系人的请求或者依据职权，可以责令其限期改正；逾期不改的，可以撤回其资质。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，资质许可机关或者其上级机关，根据利害关系人的请求或者依据职权，可以撤销工程监理企业资质： （一）资质许可机关工作人员滥用职权、玩忽职守作出准予工程监理企业资质许可的； （二）超越法定职权作出准予工程监理企业资质许可的； （三）违反资质审批程序作出准予工程监理企业资质许可的； （四）对不符合许可条件的申请人作出准予工程监理企业资质许可的； （五）依法可以撤销资质证书的其他情形。 以欺骗、贿赂等不正当手段取得工程监理企业资质证书的，应当予以撤销。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，工程监理企业应当及时向资质许可机关提出注销资质的申请，交回资质证书，国务院住房城乡建设主管部门应当办理注销手续，公告其资质证书作废： （一）资质证书有效期届满，未依法申请延续的； （二）工程监理企业依法终止的； （三）工程监理企业资质依法被撤销、撤回或吊销的； （四）法律、法规规定的应当注销资质的其他情形。"},{"i":26,"n":"第二十六条","txt":"工程监理企业应当按照有关规定，向资质许可机关提供真实、准确、完整的工程监理企业的信用档案信息。 工程监理企业的信用档案应当包括基本情况、业绩、工程质量和安全、合同违约等情况。被投诉举报和处理、行政处罚等情况应当作为不良行为记入其信用档案。 工程监理企业的信用档案信息按照有关规定向社会公示，公众有权查阅。"},{"i":27,"n":"第二十七条","txt":"申请人隐瞒有关情况或者提供虚假材料申请工程监理企业资质的，资质许可机关不予受理或者不予行政许可，并给予警告，申请人在1年内不得再次申请工程监理企业资质。"},{"i":28,"n":"第二十八条","txt":"以欺骗、贿赂等不正当手段取得工程监理企业资质证书的，由县级以上地方人民政府住房城乡建设主管部门或者有关部门给予警告，并处1万元以上2万元以下的罚款，申请人3年内不得再次申请工程监理企业资质。"},{"i":29,"n":"第二十九条","txt":"工程监理企业有本规定第十六条第七项、第八项行为之一的，由县级以上地方人民政府住房城乡建设主管部门或者有关部门予以警告，责令其改正，并处1万元以上3万元以下的罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"违反本规定，工程监理企业不及时办理资质证书变更手续的，由资质许可机关责令限期办理；逾期不办理的，可处以1千元以上1万元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"工程监理企业未按照本规定要求提供工程监理企业信用档案信息的，由县级以上地方人民政府住房城乡建设主管部门予以警告，责令限期改正；逾期未改正的，可处以1千元以上1万元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府住房城乡建设主管部门依法给予工程监理企业行政处罚的，应当将行政处罚决定以及给予行政处罚的事实、理由和依据，报国务院住房城乡建设主管部门备案。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府住房城乡建设主管部门及有关部门有下列情形之一的，由其上级行政主管部门或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）对不符合本规定条件的申请人准予工程监理企业资质许可的； （二）对符合本规定条件的申请人不予工程监理企业资质许可或者不在法定期限内作出准予许可决定的； （三）对符合法定条件的申请不予受理或者未在法定期限内初审完毕的； （四）利用职务上的便利，收受他人财物或者其他好处的； （五）不依法履行监督管理职责或者监督不力，造成严重后果的。"},{"i":34,"n":"第三十四条","txt":"本规定自2007年8月1日起施行。2001年8月29日建设部颁布的《工程监理企业资质管理规定》（建设部令第102号）同时废止。 附件：1．专业资质注册监理工程师人数配备表       2．专业工程类别和等级表 附表1 专业资质注册监理工程师人数配备表（单位：人） 序号 工程类别 甲级 乙级 丙级 1 房屋建筑工程 15 10 5 2 冶炼工程 15 10 3 矿山工程 20 12 4 化工石油工程 15 10 5 水利水电工程 20 12 5 6 电力工程 15 10 7 农林工程 15 10 8 铁路工程 23 14 9 公路工程 20 12 5 10 港口与航道工程 20 12 11 航天航空工程 20 12 12 通信工程 20 12 13 市政公用工程 15 10 5 14 机电安装工程 15 10 注：表中各专业资质注册监理工程师人数配备是指企业取得本专业工程类别注册的注册监"}],"gongchengzaojiazixunqiyeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对工程造价咨询企业的管理，提高工程造价咨询工作质量，维护建设市场秩序和社会公共利益，根据《中华人民共和国行政许可法》、《国务院对确需保留的行政审批项目设定行政许可的决定》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事工程造价咨询活动，实施对工程造价咨询企业的监督管理，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称工程造价咨询企业，是指接受委托，对建设项目投资、工程造价的确定与控制提供专业咨询服务的企业。"},{"i":4,"n":"第四条","txt":"工程造价咨询企业应当依法取得工程造价咨询企业资质，并在其资质等级许可的范围内从事工程造价咨询活动。"},{"i":5,"n":"第五条","txt":"工程造价咨询企业从事工程造价咨询活动，应当遵循独立、客观、公正、诚实信用的原则，不得损害社会公共利益和他人的合法权益。 任何单位和个人不得非法干预依法进行的工程造价咨询活动。"},{"i":6,"n":"第六条","txt":"国务院住房城乡建设主管部门负责全国工程造价咨询企业的统一监督管理工作。 省、自治区、直辖市人民政府住房城乡建设主管部门负责本行政区域内工程造价咨询企业的监督管理工作。 有关专业部门负责对本专业工程造价咨询企业实施监督管理。"},{"i":7,"n":"第七条","txt":"工程造价咨询行业组织应当加强行业自律管理。 鼓励工程造价咨询企业加入工程造价咨询行业组织。"},{"i":8,"n":"第八条","txt":"工程造价咨询企业资质等级分为甲级、乙级。"},{"i":9,"n":"第九条","txt":"甲级工程造价咨询企业资质标准如下： （一）已取得乙级工程造价咨询企业资质证书满3年； （二）技术负责人已取得一级造价工程师注册证书，并具有工程或工程经济类高级专业技术职称，且从事工程造价专业工作15年以上； （三）专职从事工程造价专业工作的人员（以下简称专职专业人员）不少于12人，其中，具有工程（或工程经济类）中级以上专业技术职称或者取得二级造价工程师注册证书的人员合计不少于10人；取得一级造价工程师注册证书的人员不少于6人，其他人员具有从事工程造价专业工作的经历； （四）企业与专职专业人员签订劳动合同，且专职专业人员符合国家规定的职业年龄（出资人除外）； （五）企业近3年工程造价咨询营业收入累计不低于人民币500万元； （六）企业为本单位专职专业人员办理的社会基本养老保险手续齐全； （七）在申请核定资质等级之日前3年内无本办法第二十五条禁止的行为。"},{"i":10,"n":"第十条","txt":"乙级工程造价咨询企业资质标准如下： （一）技术负责人已取得一级造价工程师注册证书，并具有工程或工程经济类高级专业技术职称，且从事工程造价专业工作10年以上； （二）专职专业人员不少于6人，其中，具有工程（或工程经济类）中级以上专业技术职称或者取得二级造价工程师注册证书的人员合计不少于4人；取得一级造价工程师注册证书的人员不少于3人，其他人员具有从事工程造价专业工作的经历； （三）企业与专职专业人员签订劳动合同，且专职专业人员符合国家规定的职业年龄（出资人除外）； （四）企业为本单位专职专业人员办理的社会基本养老保险手续齐全； （五）暂定期内工程造价咨询营业收入累计不低于人民币50万元； （六）申请核定资质等级之日前无本办法第二十五条禁止的行为。"},{"i":11,"n":"第十一条","txt":"甲级工程造价咨询企业资质，由国务院住房城乡建设主管部门审批。 申请甲级工程造价咨询企业资质的，可以向申请人工商注册所在地省、自治区、直辖市人民政府住房城乡建设主管部门或者国务院有关专业部门提交申请材料。 省、自治区、直辖市人民政府住房城乡建设主管部门或者国务院有关专业部门收到申请材料后，应当在5日内将全部申请材料报国务院住房城乡建设主管部门，国务院住房城乡建设主管部门应当自受理之日起20日内作出决定。 组织专家评审所需时间不计算在上述时限内，但应当明确告知申请人。"},{"i":12,"n":"第十二条","txt":"申请乙级工程造价咨询企业资质的，由省、自治区、直辖市人民政府住房城乡建设主管部门审查决定。其中，申请有关专业乙级工程造价咨询企业资质的，由省、自治区、直辖市人民政府住房城乡建设主管部门商同级有关专业部门审查决定。 乙级工程造价咨询企业资质许可的实施程序由省、自治区、直辖市人民政府住房城乡建设主管部门依法确定。 省、自治区、直辖市人民政府住房城乡建设主管部门应当自作出决定之日起30日内，将准予资质许可的决定报国务院住房城乡建设主管部门备案。"},{"i":13,"n":"第十三条","txt":"企业在申请工程造价咨询甲级（或乙级）资质，以及在资质延续、变更时，应当提交以下申报材料： （一）工程造价咨询企业资质申请书（含企业法定代表人承诺书）； （二）专职专业人员（含技术负责人）的中级以上专业技术职称证书和身份证； （三）企业开具的工程造价咨询营业收入发票和对应的工程造价咨询合同（如发票能体现工程造价咨询业务的，可不提供对应的工程造价咨询合同；新申请工程造价咨询企业资质的，不需提供）； （四）工程造价咨询企业资质证书（新申请工程造价咨询企业资质的，不需提供）； （五）企业营业执照。 企业在申请工程造价咨询甲级（或乙级）资质，以及在资质延续、变更时，企业法定代表人应当对下列事项进行承诺，并由资质许可机关调查核实： （一）企业与专职专业人员签订劳动合同； （二）企业缴纳营业收入的增值税； （三）企业为专职专业人员（含技术负责人）缴纳本年度社会基本养老保险费用。"},{"i":14,"n":"第十四条","txt":"新申请工程造价咨询企业资质的，其资质等级按照本办法第十条第（一）项至第（四）项所列资质标准核定为乙级，设暂定期一年。 暂定期届满需继续从事工程造价咨询活动的，应当在暂定期届满30日前，向资质许可机关申请换发资质证书。符合乙级资质条件的，由资质许可机关换发资质证书。"},{"i":15,"n":"第十五条","txt":"准予资质许可的，资质许可机关应当向申请人颁发工程造价咨询企业资质证书。 工程造价咨询企业资质证书由国务院住房城乡建设主管部门统一印制，分正本和副本。正本和副本具有同等法律效力。 工程造价咨询企业遗失资质证书的，应当向资质许可机关申请补办，由资质许可机关在官网发布信息。"},{"i":16,"n":"第十六条","txt":"工程造价咨询企业资质有效期为3年。 资质有效期届满，需要继续从事工程造价咨询活动的，应当在资质有效期届满30日前向资质许可机关提出资质延续申请。资质许可机关应当根据申请作出是否准予延续的决定。准予延续的，资质有效期延续3年。"},{"i":17,"n":"第十七条","txt":"工程造价咨询企业的名称、住所、组织形式、法定代表人、技术负责人、注册资本等事项发生变更的，应当自变更确立之日起30日内，到资质许可机关办理资质证书变更手续。"},{"i":18,"n":"第十八条","txt":"工程造价咨询企业合并的，合并后存续或者新设立的工程造价咨询企业可以承继合并前各方中较高的资质等级，但应当符合相应的资质等级条件。 工程造价咨询企业分立的，只能由分立后的一方承继原工程造价咨询企业资质，但应当符合原工程造价咨询企业资质等级条件。"},{"i":19,"n":"第十九条","txt":"工程造价咨询企业依法从事工程造价咨询活动，不受行政区域限制。 甲级工程造价咨询企业可以从事各类建设项目的工程造价咨询业务。 乙级工程造价咨询企业可以从事工程造价2亿元人民币以下的各类建设项目的工程造价咨询业务。"},{"i":20,"n":"第二十条","txt":"工程造价咨询业务范围包括： （一）建设项目建议书及可行性研究投资估算、项目经济评价报告的编制和审核； （二）建设项目概预算的编制与审核，并配合设计方案比选、优化设计、限额设计等工作进行工程造价分析与控制； （三）建设项目合同价款的确定（包括招标工程工程量清单和标底、投标报价的编制和审核）；合同价款的签订与调整（包括工程变更、工程洽商和索赔费用的计算）及工程款支付，工程结算及竣工结（决）算报告的编制与审核等； （四）工程造价经济纠纷的鉴定和仲裁的咨询； （五）提供工程造价信息服务等。 工程造价咨询企业可以对建设项目的组织实施进行全过程或者若干阶段的管理和服务。"},{"i":21,"n":"第二十一条","txt":"工程造价咨询企业在承接各类建设项目的工程造价咨询业务时，应当与委托人订立书面工程造价咨询合同。 工程造价咨询企业与委托人可以参照《建设工程造价咨询合同》（示范文本）订立合同。"},{"i":22,"n":"第二十二条","txt":"工程造价咨询企业从事工程造价咨询业务，应当按照有关规定的要求出具工程造价成果文件。 工程造价成果文件应当由工程造价咨询企业加盖有企业名称、资质等级及证书编号的执业印章，并由执行咨询业务的注册造价工程师签字、加盖执业印章。"},{"i":23,"n":"第二十三条","txt":"工程造价咨询企业跨省、自治区、直辖市承接工程造价咨询业务的，应当自承接业务之日起30日内到建设工程所在地省、自治区、直辖市人民政府住房城乡建设主管部门备案。"},{"i":24,"n":"第二十四条","txt":"工程造价咨询收费应当按照有关规定，由当事人在建设工程造价咨询合同中约定。"},{"i":25,"n":"第二十五条","txt":"工程造价咨询企业不得有下列行为： （一）涂改、倒卖、出租、出借资质证书，或者以其他形式非法转让资质证书； （二）超越资质等级业务范围承接工程造价咨询业务； （三）同时接受招标人和投标人或两个以上投标人对同一工程项目的工程造价咨询业务； （四）以给予回扣、恶意压低收费等方式进行不正当竞争； （五）转包承接的工程造价咨询业务； （六）法律、法规禁止的其他行为。"},{"i":26,"n":"第二十六条","txt":"除法律、法规另有规定外，未经委托人书面同意，工程造价咨询企业不得对外提供工程造价咨询服务过程中获知的当事人的商业秘密和业务资料。"},{"i":27,"n":"第二十七条","txt":"县级以上地方人民政府住房城乡建设主管部门、有关专业部门应当依照有关法律、法规和本办法的规定，对工程造价咨询企业从事工程造价咨询业务的活动实施监督检查。"},{"i":28,"n":"第二十八条","txt":"监督检查机关履行监督检查职责时，有权采取下列措施： （一）要求被检查单位提供工程造价咨询企业资质证书、造价工程师注册证书，有关工程造价咨询业务的文档，有关技术档案管理制度、质量控制制度、财务管理制度的文件； （二）进入被检查单位进行检查，查阅工程造价咨询成果文件以及工程造价咨询合同等相关资料； （三）纠正违反有关法律、法规和本办法及执业规程规定的行为。 监督检查机关应当将监督检查的处理结果向社会公布。"},{"i":29,"n":"第二十九条","txt":"监督检查机关进行监督检查时，应当有两名以上监督检查人员参加，并出示执法证件，不得妨碍被检查单位的正常经营活动，不得索取或者收受财物、谋取其他利益。 有关单位和个人对依法进行的监督检查应当协助与配合，不得拒绝或者阻挠。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，资质许可机关或者其上级机关，根据利害关系人的请求或者依据职权，可以撤销工程造价咨询企业资质： （一）资质许可机关工作人员滥用职权、玩忽职守作出准予工程造价咨询企业资质许可的； （二）超越法定职权作出准予工程造价咨询企业资质许可的； （三）违反法定程序作出准予工程造价咨询企业资质许可的； （四）对不具备行政许可条件的申请人作出准予工程造价咨询企业资质许可的； （五）依法可以撤销工程造价咨询企业资质的其他情形。 工程造价咨询企业以欺骗、贿赂等不正当手段取得工程造价咨询企业资质的，应当予以撤销。"},{"i":31,"n":"第三十一条","txt":"工程造价咨询企业取得工程造价咨询企业资质后，不再符合相应资质条件的，资质许可机关根据利害关系人的请求或者依据职权，可以责令其限期改正；逾期不改的，可以撤回其资质。"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的，资质许可机关应当依法注销工程造价咨询企业资质： （一）工程造价咨询企业资质有效期满，未申请延续的； （二）工程造价咨询企业资质被撤销、撤回的； （三）工程造价咨询企业依法终止的； （四）法律、法规规定的应当注销工程造价咨询企业资质的其他情形。"},{"i":33,"n":"第三十三条","txt":"工程造价咨询企业应当按照有关规定，向资质许可机关提供真实、准确、完整的工程造价咨询企业信用档案信息。 工程造价咨询企业信用档案应当包括工程造价咨询企业的基本情况、业绩、良好行为、不良行为等内容。违法行为、被投诉举报处理、行政处罚等情况应当作为工程造价咨询企业的不良记录记入其信用档案。 任何单位和个人有权查阅信用档案。"},{"i":34,"n":"第三十四条","txt":"申请人隐瞒有关情况或者提供虚假材料申请工程造价咨询企业资质的，不予受理或者不予资质许可，并给予警告，申请人在1年内不得再次申请工程造价咨询企业资质。"},{"i":35,"n":"第三十五条","txt":"以欺骗、贿赂等不正当手段取得工程造价咨询企业资质的，由县级以上地方人民政府住房城乡建设主管部门或者有关专业部门给予警告，并处以1万元以上3万元以下的罚款，申请人3年内不得再次申请工程造价咨询企业资质。"},{"i":36,"n":"第三十六条","txt":"未取得工程造价咨询企业资质从事工程造价咨询活动或者超越资质等级承接工程造价咨询业务的，出具的工程造价成果文件无效，由县级以上地方人民政府住房城乡建设主管部门或者有关专业部门给予警告，责令限期改正，并处以1万元以上3万元以下的罚款。"},{"i":37,"n":"第三十七条","txt":"违反本办法第十七条规定，工程造价咨询企业不及时办理资质证书变更手续的，由资质许可机关责令限期办理；逾期不办理的，可处以1万元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"违反本办法第二十三条规定，跨省、自治区、直辖市承接业务不备案的，由县级以上地方人民政府住房城乡建设主管部门或者有关专业部门给予警告，责令限期改正；逾期未改正的，可处以5000元以上2万元以下的罚款。"},{"i":39,"n":"第三十九条","txt":"工程造价咨询企业有本办法第二十五条行为之一的，由县级以上地方人民政府住房城乡建设主管部门或者有关专业部门给予警告，责令限期改正，并处以1万元以上3万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"资质许可机关有下列情形之一的，由其上级行政主管部门或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）对不符合法定条件的申请人准予工程造价咨询企业资质许可或者超越职权作出准予工程造价咨询企业资质许可决定的； （二）对符合法定条件的申请人不予工程造价咨询企业资质许可或者不在法定期限内作出准予工程造价咨询企业资质许可决定的； （三）利用职务上的便利，收受他人财物或者其他利益的； （四）不履行监督管理职责，或者发现违法行为不予查处的。"},{"i":41,"n":"第四十一条","txt":"本办法自2006年7月1日起施行。2000年1月25日建设部发布的《工程造价咨询单位管理办法》（建设部令第74号）同时废止。 本办法施行前建设部发布的规章与本办法的规定不一致的，以本办法为准。"}],"yigougongyouzhufanghejingjishiyongzhufangshangshic29b988":[{"i":1,"n":"第一条","txt":"为规范已购公有住房和经济适用住房的上市出售活动，促进房地产市场的发展和存量住房的流通，满足居民改善居住条件的需要，根据《国务院关于进一步深化城镇住房制度改革加快住房建设的通知》及有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于已购公有住房和经济适用住房首次进入市场出售的管理。"},{"i":3,"n":"第三条","txt":"本办法所称已购公有住房和经济适用住房，是指城镇职工根据国家和县级以上地方人民政府有关城镇住房制度改革政策规定，按照成本价（或者标准价）购买的公有住房，或者按照地方人民政府指导价购买的经济适用住房。 本办法所称经济适用住房包括安居工程住房和集资合作建设的住房。"},{"i":4,"n":"第四条","txt":"经省、自治区、直辖市人民政府批准，具备下列条件的市、县可以开放已购公有住房和经济适用住房上市出售的交易市场： （一）已按照个人申报、单位审核、登记立档的方式对城镇职工家庭住房状况进行了普查，并对申报人在住房制度改革中有违法、违纪行为的进行了处理； （二）已制定了已购公有住房和经济适用住房上市出售收益分配管理办法； （三）已制定了已购公有住房和经济适用住房上市出售的具体实施办法； （四）法律、法规规定的其他条件。"},{"i":5,"n":"第五条","txt":"已取得合法产权证书的已购公有住房和经济适用住房可以上市出售，但有下列情形之一的已购公有住房和经济适用住房不得上市出售： （一）以低于房改政策规定的价格购买且没有按照规定补足房价款的； （二）住房面积超过省、自治区、直辖市人民政府规定的控制标准，或者违反规定利用公款超标准装修，且超标部分未按照规定退回或者补足房价款及装修费用的； （三）处于户籍冻结地区并已列入拆迁公告范围内的； （四）产权共有的房屋，其他共有人不同意出售的； （五）已抵押且未经抵押权人书面同意转让的； （六）上市出售后形成新的住房困难的； （七）擅自改变房屋使用性质的； （八）法律、法规以及县级以上人民政府规定其他不宜出售的。"},{"i":6,"n":"第六条","txt":"已购公有住房和经济适用住房所有权人要求将已购公有住房和经济适用住房上市出售的，应当向房屋所在地的县级以上人民政府房地产行政主管部门提出申请，并提交下列材料： （一）职工已购公有住房和经济适用住房上市出售申请表； （二）房屋所有权证书、土地使用权证书或者房地产权证书； （三）身份证及户籍证明或者其他有效身份证件； （四）同住成年人同意上市出售的书面意见； （五）个人拥有部分产权的住房，还应当提供原产权单位在同等条件下保留或者放弃优先购买权的书面意见。"},{"i":7,"n":"第七条","txt":"房地产行政主管部门对已购公有住房和经济适用住房所有权人提出的上市出售申请进行审核，并自收到申请之日起十五日内作出是否准予其上市出售的书面意见。"},{"i":8,"n":"第八条","txt":"经房地产行政主管部门审核，准予出售的房屋，由买卖当事人向房屋所在地房地产交易管理部门申请办理交易过户手续，如实申报成交价格。并按照规定到有关部门缴纳有关税费和土地收益。 成交价格按照政府宏观指导下的市场原则，由买卖双方协商议定。房地产交易管理部门对所申报的成交价格进行核实，对需要评估的房屋进行现场查勘和评估。"},{"i":9,"n":"第九条","txt":"买卖当事人在办理完毕交易过户手续之日起三十日内，应当向房地产行政主管部门申请办理房屋所有权转移登记手续，并凭变更后的房屋所有权证书向同级人民政府土地行政主管部门申请土地使用权变更登记手续。 在本办法实施前，尚未领取土地使用权证书的已购公有住房和经济适用住房在2000年底以前需要上市出售的，房屋产权人可以凭房屋所有权证书先行办理交易过户手续，办理完毕房屋所有权转移登记手续之日起三十日内由受让人持变更后的房屋所有权证书到房屋所在地的市、县人民政府土地行政主管部门办理土地使用权变更登记手续。"},{"i":10,"n":"第十条","txt":"城镇职工以成本价购买、产权归个人所有的已购公有住房和经济适用住房上市出售的，其收入在按照规定交纳有关税费和土地收益后归职工个人所有。 以标准价购买、职工拥有部分产权的已购公有住房和经济适用住房上市出售的，可以先按照成本价补足房价款及利息，原购住房全部产权归个人所有后，该已购公有住房和经济适用住房上市出售收入按照本条前款的规定处理；也可以直接上市出售，其收入在按照规定交纳有关税费和土地收益后，由职工与原产权单位按照产权比例分成。原产权单位撤消的，其应当所得部分由房地产交易管理部门代收后，纳入地方住房基金专户管理。"},{"i":11,"n":"第十一条","txt":"鼓励城镇职工家庭为改善居住条件，将已购公有住房和经济适用住房上市出售换购住房。已购公有住房和经济适用住房上市出售后一年内该户家庭按照市场价购买住房，或者已购公有住房和经济适用住房上市出售前一年内该户家庭已按照市场价购买住房的，可以视同房屋产权交换。"},{"i":12,"n":"第十二条","txt":"已购公有住房和经济适用住房上市出售后，房屋维修仍按照上市出售前公有住房售后维修管理的有关规定执行。个人缴交的住房共用部位、共用设施设备维修基金的结余部分不予退还，随房屋产权同时过户。"},{"i":13,"n":"第十三条","txt":"已购公有住房和经济适用住房上市出售后，该户家庭不得再按照成本价或者标准价购买公有住房，也不得再购买经济适用住房等政府提供优惠政策建设的住房。"},{"i":14,"n":"第十四条","txt":"违反本办法第五条的规定，将不准上市出售的已购公有住房和经济适用住房上市出售的，没收违法所得，并处以10000元以上30000元以下罚款。"},{"i":15,"n":"第十五条","txt":"违反本办法第十三条的规定，将已购公有住房和经济适用住房上市出售后，该户家庭又以非法手段按照成本价（或者标准价）购买公有住房或者政府提供优惠政策建设的住房的，由房地产行政主管部门责令退回所购房屋，不予办理产权登记手续，并处以10000元以上30000元以下罚款；或者按照商品房市场价格补齐房价款，并处以10000元以上30000元以下罚款。"},{"i":16,"n":"第十六条","txt":"房地产行政主管部门工作人员玩忽职守、滥用职权、徇私舞弊、贪污受贿的，由其所在单位或者上级主管部门给予行政处分；情节严重、构成犯罪的，依法追究刑事责任。"},{"i":17,"n":"第十七条","txt":"省、自治区、直辖市人民政府可以根据本办法的规定和当地实际情况，选择部分条件比较成熟的市、县先行试点。"},{"i":18,"n":"第十八条","txt":"已购公有住房和经济适用住房上市出售补交土地收益的具体办法另行规定。"},{"i":19,"n":"第十九条","txt":"本办法由国务院建设行政主管部门负责解释。"},{"i":20,"n":"第二十条","txt":"本办法自1999年5月1日起施行。"}],"shizhenggongyongshiyetexujingyingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加快推进市政公用事业市场化，规范市政公用事业特许经营活动，加强市场监管，保障社会公共利益和公共安全，促进市政公用事业健康发展，根据国家有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称市政公用事业特许经营，是指政府按照有关法律、法规规定，通过市场竞争机制选择市政公用事业投资者或者经营者，明确其在一定期限和范围内经营某项市政公用事业产品或者提供某项服务的制度。 城市供水、供气、供热、公共交通、污水处理、垃圾处理等行业，依法实施特许经营的，适用本办法。"},{"i":3,"n":"第三条","txt":"实施特许经营的项目由省、自治区、直辖市通过法定形式和程序确定。"},{"i":4,"n":"第四条","txt":"国务院建设主管部门负责全国市政公用事业特许经营活动的指导和监督工作。 省、自治区人民政府建设主管部门负责本行政区域内的市政公用事业特许经营活动的指导和监督工作。 直辖市、市、县人民政府市政公用事业主管部门依据人民政府的授权（以下简称主管部门），负责本行政区域内的市政公用事业特许经营的具体实施。"},{"i":5,"n":"第五条","txt":"实施市政公用事业特许经营，应当遵循公开、公平、公正和公共利益优先的原则。"},{"i":6,"n":"第六条","txt":"实施市政公用事业特许经营，应当坚持合理布局，有效配置资源的原则，鼓励跨行政区域的市政公用基础设施共享。 跨行政区域的市政公用基础设施特许经营，应当本着有关各方平等协商的原则，共同加强监管。"},{"i":7,"n":"第七条","txt":"参与特许经营权竞标者应当具备以下条件： （一）依法注册的企业法人； （二）有相应的设施、设备； （三）有良好的银行资信、财务状况及相应的偿债能力； （四）有相应的从业经历和良好的业绩； （五）有相应数量的技术、财务、经营等关键岗位人员； （六）有切实可行的经营方案； （七）地方性法规、规章规定的其他条件。"},{"i":8,"n":"第八条","txt":"主管部门应当依照下列程序选择投资者或者经营者： （一）提出市政公用事业特许经营项目，报直辖市、市、县人民政府批准后，向社会公开发布招标条件，受理投标； （二）根据招标条件，对特许经营权的投标人进行资格审查和方案预审，推荐出符合条件的投标候选人； （三）组织评审委员会依法进行评审，并经过质询和公开答辩，择优选择特许经营权授予对象； （四）向社会公示中标结果，公示时间不少于20天； （五）公示期满，对中标者没有异议的，经直辖市、市、县人民政府批准，与中标者（以下简称“获得特许经营权的企业”）签订特许经营协议。"},{"i":9,"n":"第九条","txt":"特许经营协议应当包括以下内容： （一）特许经营内容、区域、范围及有效期限； （二）产品和服务标准； （三）价格和收费的确定方法、标准以及调整程序； （四）设施的权属与处置； （五）设施维护和更新改造； （六）安全管理； （七）履约担保； （八）特许经营权的终止和变更； （九）违约责任； （十）争议解决方式； （十一）双方认为应该约定的其他事项。"},{"i":10,"n":"第十条","txt":"主管部门应当履行下列责任： （一）协助相关部门核算和监控企业成本，提出价格调整意见； （二）监督获得特许经营权的企业履行法定义务和协议书规定的义务； （三）对获得特许经营权的企业的经营计划实施情况、产品和服务的质量以及安全生产情况进行监督； （四）受理公众对获得特许经营权的企业的投诉； （五）向政府提交年度特许经营监督检查报告； （六）在危及或者可能危及公共利益、公共安全等紧急情况下，临时接管特许经营项目； （七）协议约定的其他责任。"},{"i":11,"n":"第十一条","txt":"获得特许经营权的企业应当履行下列责任： （一）科学合理地制定企业年度生产、供应计划； （二）按照国家安全生产法规和行业安全生产标准规范，组织企业安全生产； （三）履行经营协议，为社会提供足量的、符合标准的产品和服务； （四）接受主管部门对产品和服务质量的监督检查； （五）按规定的时间将中长期发展规划、年度经营计划、年度报告、董事会决议等报主管部门备案； （六）加强对生产设施、设备的运行维护和更新改造，确保设施完好； （七）协议约定的其他责任。"},{"i":12,"n":"第十二条","txt":"特许经营期限应当根据行业特点、规模、经营方式等因素确定，最长不得超过30年。"},{"i":13,"n":"第十三条","txt":"获得特许经营权的企业承担政府公益性指令任务造成经济损失的，政府应当给予相应的补偿。"},{"i":14,"n":"第十四条","txt":"在协议有效期限内，若协议的内容确需变更的，协议双方应当在共同协商的基础上签订补充协议。"},{"i":15,"n":"第十五条","txt":"获得特许经营权的企业确需变更名称、地址、法定代表人的，应当提前书面告知主管部门，并经其同意。"},{"i":16,"n":"第十六条","txt":"特许经营期限届满，主管部门应当按照本办法规定的程序组织招标，选择特许经营者。"},{"i":17,"n":"第十七条","txt":"获得特许经营权的企业在协议有效期内单方提出解除协议的，应当提前提出申请，主管部门应当自收到获得特许经营权的企业申请的3个月内作出答复。在主管部门同意解除协议前，获得特许经营权的企业必须保证正常的经营与服务。"},{"i":18,"n":"第十八条","txt":"获得特许经营权的企业在特许经营期间有下列行为之一的，主管部门应当依法终止特许经营协议，取消其特许经营权，并可以实施临时接管： （一）擅自转让、出租特许经营权的； （二）擅自将所经营的财产进行处置或者抵押的； （三）因管理不善，发生重大质量、生产安全事故的； （四）擅自停业、歇业，严重影响到社会公共利益和安全的； （五）法律、法规禁止的其他行为。"},{"i":19,"n":"第十九条","txt":"特许经营权发生变更或者终止时，主管部门必须采取有效措施保证市政公用产品供应和服务的连续性与稳定性。"},{"i":20,"n":"第二十条","txt":"主管部门应当在特许经营协议签订后30日内，将协议报上一级市政公用事业主管部门备案。"},{"i":21,"n":"第二十一条","txt":"在项目运营的过程中，主管部门应当组织专家对获得特许经营权的企业经营情况进行中期评估。 评估周期一般不得低于两年，特殊情况下可以实施年度评估。"},{"i":22,"n":"第二十二条","txt":"直辖市、市、县人民政府有关部门按照有关法律、法规规定的原则和程序，审定和监管市政公用事业产品和服务价格。"},{"i":23,"n":"第二十三条","txt":"未经直辖市、市、县人民政府批准，获得特许经营权的企业不得擅自停业、歇业。 获得特许经营权的企业擅自停业、歇业的，主管部门应当责令其限期改正，或者依法采取有效措施督促其履行义务。"},{"i":24,"n":"第二十四条","txt":"主管部门实施监督检查，不得妨碍获得特许经营权的企业正常的生产经营活动。"},{"i":25,"n":"第二十五条","txt":"主管部门应当建立特许经营项目的临时接管应急预案。 对获得特许经营权的企业取消特许经营权并实施临时接管的，必须按照有关法律、法规的规定进行，并召开听证会。"},{"i":26,"n":"第二十六条","txt":"社会公众对市政公用事业特许经营享有知情权、建议权。 直辖市、市、县人民政府应当建立社会公众参与机制，保障公众能够对实施特许经营情况进行监督。"},{"i":27,"n":"第二十七条","txt":"国务院建设主管部门应当加强对直辖市市政公用事业主管部门实施特许经营活动的监督检查，省、自治区人民政府建设主管部门应当加强对市、县人民政府市政公用事业主管部门实施特许经营活动的监督检查，及时纠正实施特许经营中的违法行为。"},{"i":28,"n":"第二十八条","txt":"对以欺骗、贿赂等不正当手段获得特许经营权的企业，主管部门应当取消其特许经营权，并向国务院建设主管部门报告，由国务院建设主管部门通过媒体等形式向社会公开披露。被取消特许经营权的企业在三年内不得参与市政公用事业特许经营竞标。"},{"i":29,"n":"第二十九条","txt":"主管部门或者获得特许经营权的企业违反协议的，由过错方承担违约责任，给对方造成损失的，应当承担赔偿责任。"},{"i":30,"n":"第三十条","txt":"主管部门及其工作人员有下列情形之一的，由对其授权的直辖市、市、县人民政府或者监察机关责令改正，对负主要责任的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）不依法履行监督职责或者监督不力，造成严重后果的； （二）对不符合法定条件的竞标者授予特许经营权的； （三）滥用职权、循私舞弊的。"},{"i":31,"n":"第三十一条","txt":"本办法自2004年5月1日起施行。"}],"shizhenggongyongsheshikangzaishefangguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对市政公用设施抗灾设防的监督管理，提高市政公用设施的抗灾能力，保障市政公用设施的运行安全，保护人民生命财产安全，根据《中华人民共和国城乡规划法》、《中华人民共和国防震减灾法》、《中华人民共和国突发事件应对法》、《建设工程质量管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"市政公用设施的抗灾设防，适用本规定。 本规定所称市政公用设施，是指规划区内的城市道路（含桥梁）、城市轨道交通、供水、排水、燃气、热力、园林绿化、环境卫生、道路照明等设施及附属设施。 本规定所称抗灾设防是指针对地震、台风、雨雪冰冻、暴雨、地质灾害等自然灾害所采取的工程和非工程措施。"},{"i":3,"n":"第三条","txt":"市政公用设施抗灾设防实行预防为主、平灾结合的方针。"},{"i":4,"n":"第四条","txt":"国务院住房和城乡建设主管部门（以下简称国务院住房城乡建设主管部门）依法负责全国市政公用设施抗灾设防的监督管理工作。 县级以上地方人民政府住房城乡建设主管部门依法负责本行政区域内市政公用设施抗灾设防的具体管理工作。"},{"i":5,"n":"第五条","txt":"国务院住房城乡建设主管部门和省、自治区、直辖市人民政府住房城乡建设主管部门应当根据实际防灾要求，制定、修订有关工程建设标准，将市政公用设施的抗灾设防要求和先进、适用、成熟的技术措施纳入工程建设标准。"},{"i":6,"n":"第六条","txt":"国家鼓励采用符合工程建设标准的先进技术方法和材料设备，进行市政公用设施的抗灾设计与施工。市政公用设施勘察、设计文件中规定采用的新技术、新材料，可能影响市政公用设施抗灾安全，又没有国家技术标准的，应当按照国家有关规定经检测和审定后，方可使用。"},{"i":7,"n":"第七条","txt":"市政公用设施的建设单位、勘察单位、设计单位、施工单位、工程监理单位，市政公用设施的运营、养护单位以及从事市政公用设施抗灾抗震鉴定、工程检测活动的单位，应当遵守有关建设工程抗灾设防的法律、法规和技术标准，依法承担相应责任。"},{"i":8,"n":"第八条","txt":"城乡规划中的防灾专项规划应当包括以下内容： （一）在对规划区进行地质灾害危险性评估的基础上，对重大市政公用设施和可能发生严重次生灾害的市政公用设施，进行灾害及次生灾害风险、抗灾性能、功能失效影响和灾时保障能力评估，并制定相应的对策； （二）根据各类灾害的发生概率、城镇规模以及市政公用设施的重要性、使用功能、修复难易程度、发生次生灾害的可能性等，提出市政公用设施布局、建设和改造的抗灾设防要求和主要措施； （三）避开可能产生滑坡、塌陷、水淹危险或者周边有危险源的地带，充分考虑人们及时、就近避难的要求，利用广场、停车场、公园绿地等设立避难场所，配备应急供水、排水、供电、消防、通讯、交通等设施。"},{"i":9,"n":"第九条","txt":"城乡规划中的市政公用设施专项规划应当满足下列要求： （一）快速路、主干道以及对抗灾救灾有重要影响的道路应当与周边建筑和设施设置足够的间距，广场、停车场、公园绿地、城市轨道交通应当符合发生灾害时能尽快疏散人群和救灾的要求； （二）水源、气源和热源设置，供水、燃气、热力干线的设计以及相应厂站的布置，应当满足抗灾和灾后迅速恢复供应的要求，符合防止和控制爆炸、火灾等次生灾害的要求，重要厂站应当配有自备电源和必要的应急储备； （三）排水设施应当充分考虑下沉式立交桥下、地下工程和其他低洼地段的排水要求，防止次生洪涝灾害； （四）生活垃圾集中处理和污水处理设施应当符合灾后恢复运营和预防二次污染的要求，环境卫生设施配置应当满足灾后垃圾清运的要求； （五）法律、法规、规章规定的其他要求。"},{"i":10,"n":"第十条","txt":"市政公用设施的选址和建设应当符合城乡规划以及防灾专项规划、市政公用设施各项专业规划和有关工程建设标准的要求。 位于抗震设防区、洪涝易发区或者地质灾害易发区内的市政公用设施的选址和建设还应当分别符合城市抗震防灾、洪涝防治和地质灾害防治等专项规划的要求。"},{"i":11,"n":"第十一条","txt":"新建、改建和扩建市政公用设施应当按照有关工程建设标准进行抗灾设防。任何单位和个人不得擅自降低抗灾设防标准。"},{"i":12,"n":"第十二条","txt":"新建、改建和扩建市政公用设施应当按照国家有关标准设置安全监测、健康监测、应急自动处置和防灾设施，并与主体工程同时设计、同时施工、同时投入使用。安全监测、健康监测、应急自动处置和防灾设施投资应当纳入建设项目预算。"},{"i":13,"n":"第十三条","txt":"对重大市政公用设施和可能发生严重次生灾害的市政公用设施进行可行性研究时，建设单位应当组织专家对工程选址和设计方案进行抗灾设防专项论证。"},{"i":14,"n":"第十四条","txt":"对抗震设防区的下列市政公用设施，建设单位应当在初步设计阶段组织专家进行抗震专项论证： （一）属于《建筑工程抗震设防分类标准》中特殊设防类、重点设防类的市政公用设施； （二）结构复杂或者采用隔震减震措施的大型城镇桥梁和城市轨道交通桥梁，直接作为地面建筑或者桥梁基础以及处于可能液化或者软粘土层的隧道； （三）超过一万平方米的地下停车场等地下工程设施； （四）震后可能发生严重次生灾害的共同沟工程、污水集中处理设施和生活垃圾集中处理设施； （五）超出现行工程建设标准适用范围的市政公用设施。 国家或者地方对抗震设防区的市政公用设施还有其他规定的，还应当符合其规定。"},{"i":15,"n":"第十五条","txt":"市政公用设施抗震专项论证的内容包括：市政公用设施的抗震设防类别、抗震设防烈度及设计地震动参数的采用、场地类型和场地抗震性能、抗震概念设计、抗震计算、抗震及防止次生灾害措施、基础抗震性能等。对有特殊要求的工程，还应当论证其地震应急处置方案和健康监测方案设计。"},{"i":16,"n":"第十六条","txt":"建设单位组织抗震专项论证时，应当有三名以上国家或者工程所在地的省、自治区、直辖市市政公用设施抗震专项论证专家库成员参加。 国家或者省、自治区、直辖市的市政公用设施抗震专项论证专家库成员分别由国务院住房城乡建设主管部门和省、自治区、直辖市人民政府住房城乡建设主管部门公布。"},{"i":17,"n":"第十七条","txt":"对风荷载起控制作用的城镇桥梁和城市轨道交通桥梁等市政公用设施，建设单位应当在初步设计阶段组织专家进行抗风专项论证。"},{"i":18,"n":"第十八条","txt":"施工图审查机构在进行施工图审查时，应当审查市政公用设施抗灾设防内容。 对应当进行抗灾设防专项论证、抗震专项论证、抗风专项论证的市政公用设施，建设单位应当在提交施工图的同时将专项论证意见送施工图审查机构。 对应当进行而未进行抗灾设防专项论证、抗震专项论证、抗风专项论证的市政公用设施，或者进行了抗灾设防专项论证、抗震专项论证、抗风专项论证的市政公用设施，其设计图纸未执行专项论证意见的，施工图审查结论为不合格。"},{"i":19,"n":"第十九条","txt":"建设单位应当针对市政公用设施建设期间的防灾薄弱环节，组织制定技术措施和应急预案，并组织实施。"},{"i":20,"n":"第二十条","txt":"市政公用设施的运营、养护单位应当定期对市政公用设施进行维护、检查和更新，确保市政公用设施的抗灾能力。 市政公用设施的运营、养护单位应当加强对重大市政公用设施、可能发生严重次生灾害的市政公用设施的关键部位和关键设备的安全监测、健康监测工作，定期对土建工程和运营设施的抗灾性能进行评价，并制定相应的技术措施。 市政公用设施的运营、养护单位应当保存有关市政公用设施抗灾设防资料和维护、检查、监测、评价、鉴定、修复、加固、更新、拆除等记录，建立信息系统，实行动态管理，并及时将有关资料报城建档案管理机构备案。"},{"i":21,"n":"第二十一条","txt":"任何单位和个人不得擅自变动或者破坏市政公用设施的防灾设施、抗震抗风构件、隔震或者振动控制装置、安全监测系统、健康监测系统、应急自动处置系统以及地震反应观测系统等设施。"},{"i":22,"n":"第二十二条","txt":"市政公用设施的运营、养护单位应当按照工程建设标准和应急措施，设置安全报警、监控电视、漏电报警、燃气等易燃易爆气体和有毒有害气体报警、防汛、消防、逃生、紧急疏散照明、应急发电、应急通讯、救援等器材和设备，定期维护、检查、更新，并保持正常运行。"},{"i":23,"n":"第二十三条","txt":"市政公用设施超出合理使用年限，或者在合理使用年限内，但因环境、人为等各种因素抗灾能力受损的，市政公用设施的运营、养护单位应当委托具有相应资质的单位进行检测评估，需要进行修复或者加固的，应当委托具有相应资质的单位进行修复或者加固。"},{"i":24,"n":"第二十四条","txt":"抗震设防区内已建成的下列市政公用设施，原设计未采取抗震设防措施且未列入近期改造、改建、拆除计划的，市政公用设施的产权单位应当委托具有相应设计资质的单位按照抗震鉴定标准进行抗震鉴定： （一）属于《建筑工程抗震设防分类标准》中特殊设防类、重点设防类的城镇桥梁，城市轨道交通，燃气、供水、排水、热力设施； （二）第（一）项之外的其他重大市政公用设施和可能发生严重次生灾害的市政公用设施； （三）有重大文物价值和纪念意义的市政公用设施； （四）地震重点监视防御区内的市政公用设施。 经鉴定不符合抗震要求的市政公用设施应当进行改造、改建，或者由具有相应资质的设计、施工单位按照有关工程建设标准依法进行抗震加固设计与施工；未进行改造、改建或者加固前，应当限制使用。"},{"i":25,"n":"第二十五条","txt":"县级以上地方人民政府住房城乡建设主管部门应当根据当地实际情况，制定自然灾害应急预案并组织实施。 市政公用设施的运营、养护单位应当根据市政公用设施的具体情况，制定自然灾害应急预案，建立应急抢险和救援队伍，配备抢险、救援器材设备，并定期组织演练。定期演练每年不得少于一次。"},{"i":26,"n":"第二十六条","txt":"灾害发生时，县级以上地方人民政府住房城乡建设主管部门以及市政公用设施的运营、养护单位应当按照相应的应急预案及时组织应对响应。"},{"i":27,"n":"第二十七条","txt":"灾害发生后，县级以上地方人民政府住房城乡建设主管部门应当组织工程技术人员对受灾的市政公用设施进行应急评估，并及时将市政公用设施因灾直接经济损失情况报上级住房城乡建设主管部门以及同级人民政府民政主管部门。 经应急评估需进行抗灾鉴定的市政公用设施，其运营、养护单位应当委托具有相应资质的单位，按照国家有关工程建设标准进行鉴定。经鉴定需修复、加固或者重建的，应当按照工程建设标准进行修复、加固或者重建。 经应急评估可继续使用的市政公用设施，其运营、养护单位应当进行安全性检查，经检查合格后，方可恢复运营、使用。"},{"i":28,"n":"第二十八条","txt":"自然灾害发生后，县级以上地方人民政府住房城乡建设主管部门应当组织专家，对破坏程度超出工程建设标准允许范围的市政公用设施进行调查分析，对因违反工程建设强制性标准造成破坏的，依法追究有关责任人的责任。"},{"i":29,"n":"第二十九条","txt":"灾区人民政府住房城乡建设主管部门进行恢复重建时，应当坚持基础设施先行的原则。 需易地重建的市政公用设施，应当按照国家有关法律、法规的规定进行规划和建设。 地震后修复或者建设市政公用设施，应当以国家地震部门审定、发布的地震动参数复核结果，作为抗震设防的依据。 当发生超过当地设防标准的其他自然灾害时，灾后修复或者建设的市政公用设施，应当以国家相关灾害预测、预报部门公布的灾害发生概率，作为抗灾设防的依据。"},{"i":30,"n":"第三十条","txt":"县级以上地方人民政府住房城乡建设主管部门应当加强对市政公用设施抗灾设防质量的监督管理，并对本行政区域内市政公用设施执行抗灾设防的法律、法规和工程建设强制性标准情况，定期进行监督检查，并可以采取下列措施： （一）要求被检查的单位提供有关市政公用设施抗灾设防的文件和资料； （二）发现有影响市政公用设施抗灾设防质量的问题时，责令相关责任人委托具有资质的专业机构进行必要的检测、鉴定，并提出整改措施。"},{"i":31,"n":"第三十一条","txt":"违反本规定，擅自使用没有国家技术标准又未经审定的新技术、新材料的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，并处以1万元以上3万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"违反本规定，擅自变动或者破坏市政公用设施的防灾设施、抗震抗风构件、隔震或者振动控制装置、安全监测系统、健康监测系统、应急自动处置系统以及地震反应观测系统等设施的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，并对个人处以1000元以下罚款，对单位处以1万元以上3万元以下罚款。"},{"i":33,"n":"第三十三条","txt":"违反本规定，未对经鉴定不符合抗震要求的市政公用设施进行改造、改建或者抗震加固，又未限制使用的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，逾期不改的，处以1万元以上3万元以下罚款。"},{"i":34,"n":"第三十四条","txt":"本规定所称重大市政公用设施，包括快速路、主干道、对抗灾救灾有重要影响的城镇道路上的大型桥梁（含大型高架桥、立交桥）、隧道工程、城市广场、防灾公园绿地，公共地下停车场工程、城市轨道交通工程、城镇水源工程、水厂、供水排水主干管、高压和次高压城镇燃气热力枢纽工程、城镇燃气热力管道主干管、城镇排水工程、大型污水处理中心、大型垃圾处理设施等。 本规定所称可能发生严重次生灾害的市政公用设施，是指遭受破坏后可能引发强烈爆炸或者大面积的火灾、污染、水淹等情况的市政公用设施。 本规定所称抗震设防区，是指地震基本烈度六度及六度以上地区（地震动峰值加速度≥0.05g的地区）。"},{"i":35,"n":"第三十五条","txt":"本规定自2008年12月1日起施行，建设部1994年11月10日发布的《建设工程抗御地震灾害管理规定》（建设部令第38号）同时废止。"}],"lianzuzhufangbaozhangbanfa":[{"i":1,"n":"第一条","txt":"为促进廉租住房制度建设，逐步解决城市低收入家庭的住房困难，制定本办法。"},{"i":2,"n":"第二条","txt":"城市低收入住房困难家庭的廉租住房保障及其监督管理，适用本办法。 本办法所称城市低收入住房困难家庭，是指城市和县人民政府所在地的镇范围内，家庭收入、住房状况等符合市、县人民政府规定条件的家庭。"},{"i":3,"n":"第三条","txt":"市、县人民政府应当在解决城市低收入家庭住房困难的发展规划及年度计划中，明确廉租住房保障工作目标、措施，并纳入本级国民经济与社会发展规划和住房建设规划。"},{"i":4,"n":"第四条","txt":"国务院建设主管部门指导和监督全国廉租住房保障工作。县级以上地方人民政府建设（住房保障） 主管部门负责本行政区域内廉租住房保障管理工作。廉租住房保障的具体工作可以由市、县人民政府确定的实施机构承担。 县级以上人民政府发展改革（价格）、监察、民政、财政、国土资源、金融管理、税务、统计等部门按照职责分工，负责廉租住房保障的相关工作。"},{"i":5,"n":"第五条","txt":"廉租住房保障方式实行货币补贴和实物配租等相结合。货币补贴是指县级以上地方人民政府向申请廉租住房保障的城市低收入住房困难家庭发放租赁住房补贴，由其自行承租住房。实物配租是指县级以上地方人民政府向申请廉租住房保障的城市低收入住房困难家庭提供住房，并按照规定标准收取租金。 实施廉租住房保障，主要通过发放租赁补贴，增强城市低收入住房困难家庭承租住房的能力。廉租住房紧缺的城市，应当通过新建和收购等方式，增加廉租住房实物配租的房源。"},{"i":6,"n":"第六条","txt":"市、县人民政府应当根据当地家庭平均住房水平、财政承受能力以及城市低收入住房困难家庭的人口数量、结构等因素，以户为单位确定廉租住房保障面积标准。"},{"i":7,"n":"第七条","txt":"采取货币补贴方式的，补贴额度按照城市低收入住房困难家庭现住房面积与保障面积标准的差额、每平方米租赁住房补贴标准确定。 每平方米租赁住房补贴标准由市、县人民政府根据当地经济发展水平、市场平均租金、城市低收入住房困难家庭的经济承受能力等因素确定。其中对城市居民最低生活保障家庭，可以按照当地市场平均租金确定租赁住房补贴标准；对其他城市低收入住房困难家庭，可以根据收入情况等分类确定租赁住房补贴标准。"},{"i":8,"n":"第八条","txt":"采取实物配租方式的，配租面积为城市低收入住房困难家庭现住房面积与保障面积标准的差额。 实物配租的住房租金标准实行政府定价。实物配租住房的租金，按照配租面积和市、县人民政府规定的租金标准确定。有条件的地区，对城市居民最低生活保障家庭，可以免收实物配租住房中住房保障面积标准内的租金。"},{"i":9,"n":"第九条","txt":"廉租住房保障资金采取多种渠道筹措。 廉租住房保障资金来源包括： （一）年度财政预算安排的廉租住房保障资金； （二） 提取贷款风险准备金和管理费用后的住房公积金增值收益余额； （三）土地出让净收益中安排的廉租住房保障资金 ； （四）政府的廉租住房租金收入； （五）社会捐赠及其他方式筹集的资金。"},{"i":10,"n":"第十条","txt":"提取贷款风险准备金和管理费用后的住房公积金增值收益余额，应当全部用于廉租住房建设。 土地出让净收益用于廉租住房保障资金的比例，不得低于10%。 政府的廉租住房租金收入应当按照国家财政预算支出和财务制度的有关规定，实行收支两条线管理，专项用于廉租住房的维护和管理。"},{"i":11,"n":"第十一条","txt":"对中西部财政困难地区，按照中央预算内投资补助和中央财政廉租住房保障专项补助资金的有关规定给予支持。"},{"i":12,"n":"第十二条","txt":"实物配租的廉租住房来源主要包括： （一）政府新建、收购的住房； （二）腾退的公有住房； （三）社会捐赠的住房； （四）其他渠道筹集的住房。"},{"i":13,"n":"第十三条","txt":"廉租住房建设用地，应当在土地供应计划中优先安排，并在申报年度用地指标时单独列出，采取划拨方式，保证供应。 廉租住房建设用地的规划布局，应当考虑城市低收入住房困难家庭居住和就业的便利。 廉租住房建设应当坚持经济、适用原则，提高规划设计水平，满足基本使用功能，应当按照发展节能省地环保型住宅的要求，推广新材料、新技术、新工艺。廉租住房应当符合国家质量安全标准。"},{"i":14,"n":"第十四条","txt":"新建廉租住房，应当采取配套建设与相对集中建设相结合的方式，主要在经济适用住房、普通商品住房项目中配套建设。 新建廉租住房，应当将单套的建筑面积控制在50平方米以内，并根据城市低收入住房困难家庭的居住需要，合理确定套型结构。 配套建设廉租住房的经济适用住房或者普通商品住房项目，应当在用地规划、国有土地划拨决定书或者国有土地使用权出让合同中，明确配套建设的廉租住房总建筑面积、套数、布局、套型以及建成后的移交或回购等事项。"},{"i":15,"n":"第十五条","txt":"廉租住房建设免征行政事业性收费和政府性基金。 鼓励社会捐赠住房作为廉租住房房源或捐赠用于廉租住房的资金。 政府或经政府认定的单位新建、购买、改建住房作为廉租住房，社会捐赠廉租住房房源、资金，按照国家规定的有关税收政策执行 。"},{"i":16,"n":"第十六条","txt":"申请廉租住房保障，应当提供下列材料： （一）家庭收入情况的证明材料； （二）家庭住房状况的证明材料； （三）家庭成员身份证和户口簿； （四）市、县人民政府规定的其他证明材料。"},{"i":17,"n":"第十七条","txt":"申请廉租住房保障，按照下列程序办理： （一）申请廉租住房保障的家庭，应当由户主向户口所在地街道办事处或者镇人民政府提出书面申请； （二）街道办事处或者镇人民政府应当自受理申请之日起30日内，就申请人的家庭收入、家庭住房状况是否符合规定条件进行审核，提出初审意见并张榜公布，将初审意见和申请材料一并报送市（区）、县人民政府 建设（住房保障）主管部门； （三）建设（住房保障）主管部门应当自收到申请材料之日起15日内，就申请人的家庭住房状况是否符合规定条件提出审核意见，并将符合条件的申请人的申请材料转同级民政部门； （四）民政部门应当自收到申请材料之日起15日内，就申请人的家庭收入是否符合规定条件提出审核意见，并反馈同级建设（住房保障）主管部门； （五）经审核，家庭收入、家庭住房状况符合规定条件的，由建设（住房保障）主管部门予以公示，公示期限为15日；对经公示无异议或者异议不成立的，作为廉租住"},{"i":18,"n":"第十八条","txt":"建设（住房保障）主管部门、民政等有关部门以及街道办事处、镇人民政府，可以通过入户调查、邻里访问以及信函索证等方式对申请人的家庭收入和住房状况等进行核实。申请人及有关单位和个人应当予以配合，如实提供有关情况。"},{"i":19,"n":"第十九条","txt":"建设（住房保障）主管部门应当综合考虑登记的城市低收入住房困难家庭的收入水平、住房困难程度和申请顺序以及个人申请的保障方式等，确定相应的保障方式及轮候顺序，并向社会公开。 对已经登记为廉租住房保障对象的城市居民最低生活保障家庭，凡申请租赁住房货币补贴的，要优先安排发放补贴，基本做到应保尽保。 实物配租应当优先面向已经登记为廉租住房保障对象的孤、老、病、残等特殊困难家庭，城市居民最低生活保障家庭以及其他急需救助的家庭。"},{"i":20,"n":"第二十条","txt":"对轮候到位的城市低收入住房困难家庭，建设（住房保障）主管部门或者具体实施机构应当按照已确定的保障方式，与其签订租赁住房补贴协议或者廉租住房租赁合同，予以发放租赁住房补贴或者配租廉租住房。 发放租赁住房补贴和配租廉租住房的结果，应当予以公布。"},{"i":21,"n":"第二十一条","txt":"租赁住房补贴协议应当明确租赁住房补贴额度、停止发放租赁住房补贴的情形等内容。 廉租住房租赁合同应当明确下列内容： （一）房屋的位置、朝向、面积、结构、附属设施和设备状况； （二）租金及其支付方式； （三）房屋用途和使用要求； （四）租赁期限； （五）房屋维修责任； （六）停止实物配租的情形，包括承租人已不符合规定条件的，将所承租的廉租住房转借、转租或者改变用途，无正当理由连续6个月以上未在所承租的廉租住房居住或者未交纳廉租住房租金等； （七）违约责任及争议解决办法，包括退回廉租住房、调整租金、依照有关法律法规规定处理等； （八）其他约定。"},{"i":22,"n":"第二十二条","txt":"国务院建设主管部门、省级建设（住房保障）主管部门应当会同有关部门，加强对廉租住房保障工作的监督检查，并公布监督检查结果。 市、县人民政府应当定期向社会公布城市低收入住房困难家庭廉租住房保障情况。"},{"i":23,"n":"第二十三条","txt":"市（区）、县人民政府建设（住房保障）主管部门应当按户建立廉租住房档案，并采取定期走访、抽查等方式，及时掌握城市低收入住房困难家庭的人口、收入及住房变动等有关情况。"},{"i":24,"n":"第二十四条","txt":"已领取租赁住房补贴或者配租廉租住房的城市低收入住房困难家庭，应当按年度向所在地街道办事处或者镇人民政府如实申报家庭人口、收入及住房等变动情况。 街道办事处或者镇人民政府可以对申报情况进行核实、张榜公布，并将申报情况及核实结果报建设（住房保障）主管部门。 建设（住房保障）主管部门应当根据城市低收入住房困难家庭人口、收入、住房等变化情况，调整租赁住房补贴额度或实物配租面积、租金等；对不再符合规定条件的，应当停止发放租赁住房补贴，或者由承租人按照合同约定退回廉租住房。"},{"i":25,"n":"第二十五条","txt":"城市低收入住房困难家庭不得将所承租的廉租住房转借、转租或者改变用途。 城市低收入住房困难家庭违反前款规定或者有下列行为之一的，应当按照合同约定退回廉租住房： （一）无正当理由连续6个月以上未在所承租的廉租住房居住的； （二）无正当理由累计6个月以上未交纳廉租住房租金的。"},{"i":26,"n":"第二十六条","txt":"城市低收入住房困难家庭未按照合同约定退回廉租住房的，建设（住房保障）主管部门应当责令其限期退回；逾期未退回的，可以按照合同约定，采取调整租金等方式处理。 城市低收入住房困难家庭拒绝接受前款规定的处理方式的，由建设（住房保障）主管部门或者具体实施机构依照有关法律法规规定处理。"},{"i":27,"n":"第二十七条","txt":"城市低收入住房困难家庭的收入标准、住房困难标准等以及住房保障面积标准，实行动态管理，由市、县人民政府每年向社会公布一次。"},{"i":28,"n":"第二十八条","txt":"任何单位和个人有权对违反本办法规定的行为进行检举和控告。"},{"i":29,"n":"第二十九条","txt":"城市低收入住房困难家庭隐瞒有关情况或者提供虚假材料申请廉租住房保障的，建设（住房保障）主管部门不予受理，并给予警告。"},{"i":30,"n":"第三十条","txt":"对以欺骗等不正当手段，取得审核同意或者获得廉租住房保障的，由建设（住房保障）主管部门 给予警告；对已经登记但尚未获得廉租住房保障的，取消其登记；对已经获得廉租住房保障的，责令其退还已领取的租赁住房补贴，或者退出实物配租的住房并按市场价格补交以前房租。"},{"i":31,"n":"第三十一条","txt":"廉租住房保障实施机构违反本办法规定，不执行政府规定的廉租住房租金标准的，由价格主管部门依法查处。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定，建设（住房保障）主管部门及有关部门的工作人员或者市、县人民政府确定的实施机构的工作人员，在廉租住房保障工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"对承租直管公房的城市低收入家庭，可以参照本办法有关规定，对住房保障面积标准范围内的租金予以适当减免。"},{"i":34,"n":"第三十四条","txt":"本办法自2007年12月1日起施行。2003年12月31日发布的《城镇最低收入家庭廉租住房管理办法》（建设部、财政部、民政部、国土资源部、国家税务总局令第120号）同时废止。"}],"jianzhizhenguihuajiansheguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强建制镇规划建设管理，根据《城乡规划法》、《城市房地产管理法》等法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"制定和实施建制镇规划，在建制镇规划区内进行建设和房地产、市政公用设施、镇容环境卫生等管理，必须遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称建制镇，是指国家按行政建制设立的镇，不含县城关镇。 本办法所称建制镇规划区，是指镇政府驻地的建成区和因建设及发展需要实行规划控制的区域。建制镇规划区的具体范围，在建制镇总体规划中划定。"},{"i":4,"n":"第四条","txt":"建制镇规划建设要适应农村经济和社会发展的需要，为促进乡镇企业适当集中建设、农村富余劳动力向非农产业转移，加快农村城市化进程服务。"},{"i":5,"n":"第五条","txt":"建制镇建设应当坚持合理布局、节约用地的原则，全面规划、正确引导、依靠群众、自力更生、因地制宜、逐步建设，实现经济效益、社会效益和环境效益的统一。"},{"i":6,"n":"第六条","txt":"地处洪涝、地震、台风、滑坡等自然灾害容易发生地区的建制镇，应当按照国家和地方的有关规定，在建制镇总体规划中制定防灾措施。"},{"i":7,"n":"第七条","txt":"国务院建设行政主管部门主管全国建制镇规划建设管理工作。 县级以上地方人民政府建设行政主管部门主管本行政区域内建制镇规划建设管理工作。 建制镇人民政府的建设行政主管部门负责建制镇的规划建设管理工作。"},{"i":8,"n":"第八条","txt":"建制镇建设行政主管部门主要职责是： （一）贯彻和执行国家及地方有关法律、行政法规、规章； （二）负责编制建制镇的规划，并负责组织和监督规划的实施； （三）负责县级建设行政主管部门授权的建设工程项目的设计管理与施工管理； （四）负责县级建设行政主管部门授权的房地产管理； （五）负责建制镇镇容和环境卫生、园林、绿化管理、市政公用设施的维护与管理； （六）负责建筑市场、建筑队伍和个体工匠的管理； （七）负责技术服务和技术咨询； （八）负责建设统计、建设档案管理及法律、法规规定的其它职责。"},{"i":9,"n":"第九条","txt":"在县级以上地方人民政府城市规划行政主管部门指导下，建制镇规划由建制镇人民政府负责组织编制。 建制镇在设市城市规划区内的，其规划应服从设市城市的总体规划。 编制建制镇规划应当依照《村镇规划标准》进行。"},{"i":10,"n":"第十条","txt":"建制镇的总体规划报县级人民政府审批，详细规划报建制镇人民政府审批。建制镇人民政府在向县级人民政府报请审批建制镇总体规划前，须经建制镇人民代表大会审查同意。"},{"i":11,"n":"第十一条","txt":"任何组织和个人不得擅自改变已经批准的建制镇规划。确需修改时，由建制镇人民政府根据当地经济和社会发展需要进行调整，并报原审批机关审批。"},{"i":12,"n":"第十二条","txt":"建制镇规划区内的土地利用各项建设必须符合建制镇规划，服从规划管理。 任何单位和个人必须服从建制镇人民政府根据建制镇规划作出的调整用地决定。"},{"i":13,"n":"第十三条","txt":"建制镇规划区内的建设工程项目在报请计划部门批准时，必须附有县级以上建设行政主管部门的选址意见书。"},{"i":14,"n":"第十四条","txt":"在建制镇规划区内进行建设需要申请用地的，必须持建设项目的批准文件，向建制镇建设行政主管部门申请定点，由建制镇建设行政主管部门根据规划核定其用地位置和界限，并提出规划设计条件的意见，报县级人民政府建设行政主管部门审批。县级人民政府建设行政主管部门审核批准的，发给建设用地规划许可证。建设单位和个人在取得建设用地规划许可证后，方可依法申请办理用地批准手续。"},{"i":15,"n":"第十五条","txt":"建设规划用地批准后，任何单位和个人不得随意改变土地使用性质和范围。如需改变土地使用性质和范围，必须重新履行规划审批手续。"},{"i":16,"n":"第十六条","txt":"在建制镇规划区内新建、扩建和改建建筑物、构筑物、道路、管线和其它工程设施，必须持有关批准文件向建制镇建设行政主管部门提出建设工程规划许可证的申请，由建制镇建设行政主管部门对工程项目施工图进行审查，并提出是否发给建设工程规划许可证的意见，报县级人民政府建设行政主管部门审批。县级人民政府建设行政主管部门审核批准的，发给建设工程规划许可证。建设单位和个人在取得建设工程规划许可证件和其他有关批准文件后，方可申请办理开工手续。"},{"i":17,"n":"第十七条","txt":"在建制镇规划区内建临时建筑，必须经建制镇建设行政主管部门批准。临时建筑必须在批准的使用期限内拆除。如国家或集体需要用地，必须在规定期限内拆除。 禁止在批准临时使用的土地上建设永久性建筑物、构筑物和其它设施。"},{"i":18,"n":"第十八条","txt":"建制镇建设行政主管部门有权对建制镇规划区内的建设工程是否符合规划要求进行检查。被检查者应当如实提供情况和资料，检查者有责任为被检查者保守技术秘密和业务秘密。"},{"i":19,"n":"第十九条","txt":"在建制镇规划区内，凡建筑跨度、跨径或者高度超出规定范围的生产建筑、公共建筑、市政公用设施，以及二层以上的住宅（以下简称建设工程），必须由取得相应设计资格证书的单位进行设计，或者选用通用设计、标准设计。 跨度、跨径和高度的限定，由省、自治区、直辖市人民政府建设行政主管部门规定。"},{"i":20,"n":"第二十条","txt":"建制镇规划区内的建设工程的设计，应当符合建制镇规划的要求，与建设工程所在地的周围环境相协调，保持地方特色和民族风格，体现时代特点。"},{"i":21,"n":"第二十一条","txt":"建设工程设计应当贯彻适用、安全、经济、美观的原则，并应当符合国家和地方有关节约土地、能源、材料及抗御灾害的规定。"},{"i":22,"n":"第二十二条","txt":"经过审查批准的设计文件，不得擅自更改。确需更改的，必须征得审批机关的同意。"},{"i":23,"n":"第二十三条","txt":"建制镇规划区内的建设工程开工实行施工许可证制度。建设单位和个人应当根据《建设工程施工现场管理规定》的规定，取得施工许可证，并由建设行政主管部门派专人到现场定位放线或验线后，方可开工。"},{"i":24,"n":"第二十四条","txt":"凡在建制镇规划区内承建工程项目的施工企业，必须持有《施工企业资质等级证书》或者《资质审查证书》，并到当地镇建设管理机构登记后，方可按照规定的经营范围承建工程。严禁无证或者越级承建工程。 在建制镇规划区内从事建筑施工的个体工匠应当到建制镇建设行政主管部门办理登记手续。"},{"i":25,"n":"第二十五条","txt":"施工企业和个体工匠必须保证施工质量，按照有关的技术规定进行施工，使用符合工程质量要求的建筑构件和建筑材料。"},{"i":26,"n":"第二十六条","txt":"县级人民政府建设行政主管部门应当对施工质量进行监督检查，并督促有关部门或建设单位对建设项目进行竣工验收。凡验收不合格的，不得交付使用。"},{"i":27,"n":"第二十七条","txt":"在建制镇规划区国有土地范围内从事房地产开发、交易，按照《城市房地产管理法》执行。"},{"i":28,"n":"第二十八条","txt":"房屋所有人应当向房屋所在地建制镇建设行政主管部门申请登记，由县级人民政府建设行政主管部门或者其委托的机构核实并颁发房屋所有权证书或者房地产权证书。 房产转让或者变更时，应当向房屋所在地建制镇建设行政主管部门申请变更登记，由县级人民政府建设行政主管部门或者委托的机构核实并换发房屋所有权证书。"},{"i":29,"n":"第二十九条","txt":"房屋所有人申请登记，应当提交房屋土地使用权证和下列证件： （一）新建、扩建和改建的房屋，提交房屋所在地建设行政主管部门颁发的建设用地规划许可证、建设工程规划许可证； （二）购买的房屋，提交原房屋所有权证或者房地产权属证书（以下简称房屋所有权证）、买卖合同和契证； （三）受赠的房屋，提交原房屋所有权证、赠与书和契证； （四）交换的房屋，提交双方的房屋所有权证、双方签订的交换协议书和契证； （五）继承的房屋，提交原房屋所有权证、遗产继承证件和契证； （六）分家析产分割的房屋，提交原房屋所有权证，分家析产单和契证。"},{"i":30,"n":"第三十条","txt":"房产转让时，房屋的所有权和该房屋占用范围内的土地使用权同时转让。"},{"i":31,"n":"第三十一条","txt":"房屋租赁，出租人和承租人应当签订书面租赁合同，约定租赁期限、租赁用途、租赁价格、修缮责任、双方的权利和义务等条款，并向建制镇建设行政主管部门登记备案。"},{"i":32,"n":"第三十二条","txt":"建制镇规划区内的房屋因建制镇建设需要拆迁时，建设单位应当给予房屋所有人合理补偿，并对房屋使用人予以妥善安置。 被拆迁房屋的所有人或者使用人应当服从建制镇建设的需要，按期搬迁，不得借故拖延。"},{"i":33,"n":"第三十三条","txt":"从建制镇收取的城市维护建设税，必须用于建制镇市政公用设施的维护和建设，任何单位不得截留、挪用。"},{"i":34,"n":"第三十四条","txt":"建制镇的市政公用设施应当逐步实行有偿使用制度。建制镇人民政府可以根据本地区经济发展情况，制定市政公用设施有偿使用办法。"},{"i":35,"n":"第三十五条","txt":"建制镇人民政府可以根据谁投资谁受益的原则，组织有关单位和个人投资兴建市政公用设施。 国家依法保护投资人的合法权益。"},{"i":36,"n":"第三十六条","txt":"任何单位和个人都应当遵守国家和地方有关建制镇市政公用设施的管理规定，合理使用市政公用设施。 严禁损毁建制镇规划区内的市政公用设施和集贸市场。"},{"i":37,"n":"第三十七条","txt":"任何单位和个人都应当遵守国家有关风景名胜、文物保护的法规，不得损坏、擅自占用建制镇内园林绿地、绿化设施和树木花草，破坏文物古迹和风景名胜。"},{"i":38,"n":"第三十八条","txt":"建制镇建设行政主管部门应当加强建制镇镇容和环境卫生管理，保持建制镇容貌整齐，环境清洁卫生。"},{"i":39,"n":"第三十九条","txt":"在建制镇规划区内，未取得建设用地规划许可证而取得建设用地批准文件，占用土地的，批准文件无效，占用的土地由县级以上人民政府责令退回。"},{"i":40,"n":"第四十条","txt":"在建制镇规划区内，未取得建设工程规划许可证件或者违反建设工程规划许可证的规定进行建设，严重影响建制镇规划的，由县级人民政府建设行政主管部门责令停止建设，限期拆除或者没收违法建筑物、构筑物及其它设施；虽影响建制镇规划，但尚可采取改正措施的，由县级人民政府建设行政主管部门责令限期改正，可以并处罚款。"},{"i":41,"n":"第四十一条","txt":"有下列行为之一的，由县级人民政府建设行政主管部门责令停止设计或者施工、限期改正，可以并处罚款；情节严重的，提请原发证机关吊销设计或者施工的资格证书； （一）未取得相应的设计资质证书，承担建筑跨度、跨径和高度超出规定范围的工程以及二层以上住宅的设计任务的； （二）未取得施工《资质等级证书》或者《资质审查证书》，或者未按规定的经营范围承担施工任务的； （三）未取得施工许可证而擅自开工的； （四）未按设计图纸施工或者擅自修改设计图纸的； （五）不按有关技术规定施工或者使用不符合工程质量要求的建筑材料和建筑构配件的。"},{"i":42,"n":"第四十二条","txt":"损坏房屋、市政公用设施的，由建制镇人民政府建设行政主管部门责令停止侵害、恢复原状、赔偿损失，可以并处罚款。"},{"i":43,"n":"第四十三条","txt":"擅自在建制镇规划区内修建临时建筑物、构筑物和其它设施的，或者在批准临时使用的土地上建设永久性建筑物、构筑物和其它设施的，由建制镇人民政府建设行政主管部门责令限期拆除，可以并处罚款。"},{"i":44,"n":"第四十四条","txt":"破坏建制镇镇容和环境卫生的，由建制镇人民政府建设行政主管部门依据《城市市容和环境卫生管理条例》的规定进行处罚。"},{"i":45,"n":"第四十五条","txt":"占用、损坏建制镇园林绿地、绿化设施和树木花草的，由建制镇人民政府建设行政主管部门依据《城市绿化条例》的规定进行处罚。"},{"i":46,"n":"第四十六条","txt":"损坏建制镇规划区内的文物古迹、古树名木和风景名胜的，依照有关法律、法规的规定处罚。"},{"i":47,"n":"第四十七条","txt":"违反本办法，构成违反治安管理的行为，依照《治安管理处罚法》的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"建制镇建设行政主管部门应当执行有关城建监察的规定，确定执法人员，对建制镇规划、市政公用设施、园林绿化和环境卫生、风景名胜的实施情况进行执法检查。"},{"i":49,"n":"第四十九条","txt":"省、自治区、直辖市人民政府建设行政主管部门可以根据办法制定实施细则。"},{"i":50,"n":"第五十条","txt":"本办法由国务院建设行政主管部门负责解释。"},{"i":51,"n":"第五十一条","txt":"本办法自1995年7月1日起施行。"}],"jianzhuyeqiyezizhiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对建筑活动的监督管理，维护公共利益和规范建筑市场秩序，保证建设工程质量安全，促进建筑业的健康发展，根据《中华人民共和国建筑法》、《中华人民共和国行政许可法》、《建设工程质量管理条例》、《建设工程安全生产管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内申请建筑业企业资质，实施对建筑业企业资质监督管理，适用本规定。 本规定所称建筑业企业，是指从事土木工程、建筑工程、线路管道设备安装工程的新建、扩建、改建等施工活动的企业。"},{"i":3,"n":"第三条","txt":"企业应当按照其拥有的资产、主要人员、已完成的工程业绩和技术装备等条件申请建筑业企业资质，经审查合格，取得建筑业企业资质证书后，方可在资质许可的范围内从事建筑施工活动。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责全国建筑业企业资质的统一监督管理。国务院交通运输、水利、工业信息化等有关部门配合国务院住房城乡建设主管部门实施相关资质类别建筑业企业资质的管理工作。 省、自治区、直辖市人民政府住房城乡建设主管部门负责本行政区域内建筑业企业资质的统一监督管理。省、自治区、直辖市人民政府交通运输、水利、通信等有关部门配合同级住房城乡建设主管部门实施本行政区域内相关资质类别建筑业企业资质的管理工作。"},{"i":5,"n":"第五条","txt":"建筑业企业资质分为施工总承包资质、专业承包资质、施工劳务资质三个序列。 施工总承包资质、专业承包资质按照工程性质和技术特点分别划分为若干资质类别，各资质类别按照规定的条件划分为若干资质等级。施工劳务资质不分类别与等级。"},{"i":6,"n":"第六条","txt":"建筑业企业资质标准和取得相应资质的企业可以承担工程的具体范围，由国务院住房城乡建设主管部门会同国务院有关部门制定。"},{"i":7,"n":"第七条","txt":"国家鼓励取得施工总承包资质的企业拥有全资或者控股的劳务企业。 建筑业企业应当加强技术创新和人员培训，使用先进的建造技术、建筑材料，开展绿色施工。"},{"i":8,"n":"第八条","txt":"企业可以申请一项或多项建筑业企业资质。 企业首次申请或增项申请资质，应当申请最低等级资质。"},{"i":9,"n":"第九条","txt":"下列建筑业企业资质，由国务院住房城乡建设主管部门许可： （一）施工总承包资质序列特级资质、一级资质及铁路工程施工总承包二级资质； （二）专业承包资质序列公路、水运、水利、铁路、民航方面的专业承包一级资质及铁路、民航方面的专业承包二级资质；涉及多个专业的专业承包一级资质。"},{"i":10,"n":"第十条","txt":"下列建筑业企业资质，由企业工商注册所在地省、自治区、直辖市人民政府住房城乡建设主管部门许可： （一）施工总承包资质序列二级资质及铁路、通信工程施工总承包三级资质； （二）专业承包资质序列一级资质（不含公路、水运、水利、铁路、民航方面的专业承包一级资质及涉及多个专业的专业承包一级资质）； （三）专业承包资质序列二级资质（不含铁路、民航方面的专业承包二级资质）；铁路方面专业承包三级资质；特种工程专业承包资质。"},{"i":11,"n":"第十一条","txt":"下列建筑业企业资质，由企业工商注册所在地设区的市人民政府住房城乡建设主管部门许可： （一）施工总承包资质序列三级资质（不含铁路、通信工程施工总承包三级资质）； （二）专业承包资质序列三级资质（不含铁路方面专业承包资质）及预拌混凝土、模板脚手架专业承包资质； （三）施工劳务资质； （四）燃气燃烧器具安装、维修企业资质。"},{"i":12,"n":"第十二条","txt":"申请本规定第九条所列资质的，可以向企业工商注册所在地省、自治区、直辖市人民政府住房城乡建设主管部门提交申请材料。 省、自治区、直辖市人民政府住房城乡建设主管部门收到申请材料后，应当在5日内将全部申请材料报审批部门。 国务院住房城乡建设主管部门在收到申请材料后，应当依法作出是否受理的决定，并出具凭证；申请材料不齐全或者不符合法定形式的，应当在5日内一次性告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。 国务院住房城乡建设主管部门应当自受理之日起20个工作日内完成审查。自作出决定之日起10日内公告审批结果。其中，涉及公路、水运、水利、通信、铁路、民航等方面资质的，由国务院住房城乡建设主管部门会同国务院有关部门审查。 需要组织专家评审的，所需时间不计算在许可时限内，但应当明确告知申请人。"},{"i":13,"n":"第十三条","txt":"本规定第十条规定的资质许可程序由省、自治区、直辖市人民政府住房城乡建设主管部门依法确定，并向社会公布。 本规定第十一条规定的资质许可程序由设区的市级人民政府住房城乡建设主管部门依法确定，并向社会公布。"},{"i":14,"n":"第十四条","txt":"企业申请建筑业企业资质，在资质许可机关的网站或审批平台提出申请事项，提交资金、专业技术人员、技术装备和已完成业绩等电子材料。"},{"i":15,"n":"第十五条","txt":"企业申请建筑业企业资质，应当如实提交有关申请材料。资质许可机关收到申请材料后，应当按照《中华人民共和国行政许可法》的规定办理受理手续。"},{"i":16,"n":"第十六条","txt":"资质许可机关应当及时将资质许可决定向社会公开，并为公众查询提供便利。"},{"i":17,"n":"第十七条","txt":"建筑业企业资质证书分为正本和副本，由国务院住房城乡建设主管部门统一印制，正、副 本具备同等法律效力。资质证书有效期为5年。"},{"i":18,"n":"第十八条","txt":"建筑业企业资质证书有效期届满，企业继续从事建筑施工活动的，应当于资质证书有效期届满3个月前，向原资质许可机关提出延续申请。 资质许可机关应当在建筑业企业资质证书有效期届满前做出是否准予延续的决定；逾期未做出决定的，视为准予延续。"},{"i":19,"n":"第十九条","txt":"企业在建筑业企业资质证书有效期内名称、地址、注册资本、法定代表人等发生变更的，应当在工商部门办理变更手续后1个月内办理资质证书变更手续。"},{"i":20,"n":"第二十条","txt":"由国务院住房城乡建设主管部门颁发的建筑业企业资质证书的变更，企业应当向企业工商注册所在地省、自治区、直辖市人民政府住房城乡建设主管部门提出变更申请，省、自治区、直辖市人民政府住房城乡建设主管部门应当自受理申请之日起2日内将有关变更证明材料报国务院住房城乡建设主管部门，由国务院住房城乡建设主管部门在2日内办理变更手续。 前款规定以外的资质证书的变更，由企业工商注册所在地的省、自治区、直辖市人民政府住房城乡建设主管部门或者设区的市人民政府住房城乡建设主管部门依法另行规定。变更结果应当在资质证书变更后15日内，报国务院住房城乡建设主管部门备案。 涉及公路、水运、水利、通信、铁路、民航等方面的建筑业企业资质证书的变更，办理变更手续的住房城乡建设主管部门应当将建筑业企业资质证书变更情况告知同级有关部门。"},{"i":21,"n":"第二十一条","txt":"企业发生合并、分立、重组以及改制等事项，需承继原建筑业企业资质的，应当申请重新核定建筑业企业资质等级。"},{"i":22,"n":"第二十二条","txt":"企业需更换、遗失补办建筑业企业资质证书的，应当持建筑业企业资质证书更换、遗失补办申请等材料向资质许可机关申请办理。资质许可机关应当在2个工作日内办理完毕。 企业遗失建筑业企业资质证书的，在申请补办前应当在公众媒体上刊登遗失声明。"},{"i":23,"n":"第二十三条","txt":"企业申请建筑业企业资质升级、资质增项，在申请之日起前一年至资质许可决定作出前，有下列情形之一的，资质许可机关不予批准其建筑业企业资质升级申请和增项申请： （一）超越本企业资质等级或以其他企业的名义承揽工程，或允许其他企业或个人以本企业的名义承揽工程的； （二）与建设单位或企业之间相互串通投标，或以行贿等不正当手段谋取中标的； （三）未取得施工许可证擅自施工的； （四）将承包的工程转包或违法分包的； （五）违反国家工程建设强制性标准施工的； （六）恶意拖欠分包企业工程款或者劳务人员工资的； （七）隐瞒或谎报、拖延报告工程质量安全事故，破坏事故现场、阻碍对事故调查的； （八）按照国家法律、法规和标准规定需要持证上岗的现场管理人员和技术工种作业人员未取得证书上岗的； （九）未依法履行工程质量保修义务或拖延履行保修义务的； （十）伪造、变造、倒卖、出租、出借或者以其他形式非法转让建筑业企业资质"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府住房城乡建设主管部门和其他有关部门应当依照有关法律、法规和本规定，加强对企业取得建筑业企业资质后是否满足资质标准和市场行为的监督管理。 上级住房城乡建设主管部门应当加强对下级住房城乡建设主管部门资质管理工作的监督检查，及时纠正建筑业企业资质管理中的违法行为。"},{"i":25,"n":"第二十五条","txt":"住房城乡建设主管部门、其他有关部门的监督检查人员履行监督检查职责时，有权采取下列措施： （一）要求被检查企业提供建筑业企业资质证书、企业有关人员的注册执业证书、职称证书、岗位证书和考核或者培训合格证书，有关施工业务的文档，有关质量管理、安全生产管理、合同管理、档案管理、财务管理等企业内部管理制度的文件； （二）进入被检查企业进行检查，查阅相关资料； （三）纠正违反有关法律、法规和本规定及有关规范和标准的行为。 监督检查人员应当将监督检查情况和处理结果予以记录，由监督检查人员和被检查企业的有关人员签字确认后归档。"},{"i":26,"n":"第二十六条","txt":"住房城乡建设主管部门、其他有关部门的监督检查人员在实施监督检查时，应当出示证件，并要有两名以上人员参加。 监督检查人员应当为被检查企业保守商业秘密，不得索取或者收受企业的财物，不得谋取其他利益。 有关企业和个人对依法进行的监督检查应当协助与配合，不得拒绝或者阻挠。 监督检查机关应当将监督检查的处理结果向社会公布。"},{"i":27,"n":"第二十七条","txt":"企业违法从事建筑活动的，违法行为发生地的县级以上地方人民政府住房城乡建设主管部门或者其他有关部门应当依法查处，并将违法事实、处理结果或者处理建议及时告知该建筑业企业资质的许可机关。 对取得国务院住房城乡建设主管部门颁发的建筑业企业资质证书的企业需要处以停业整顿、降低资质等级、吊销资质证书行政处罚的，县级以上地方人民政府住房城乡建设主管部门或者其他有关部门，应当通过省、自治区、直辖市人民政府住房城乡建设主管部门或者国务院有关部门，将违法事实、处理建议及时报送国务院住房城乡建设主管部门。"},{"i":28,"n":"第二十八条","txt":"取得建筑业企业资质证书的企业，应当保持资产、主要人员、技术装备等方面满足相应建筑业企业资质标准要求的条件。 企业不再符合相应建筑业企业资质标准要求条件的，县级以上地方人民政府住房城乡建设主管部门、其他有关部门，应当责令其限期改正并向社会公告，整改期限最长不超过3个月；企业整改期间不得申请建筑业企业资质的升级、增项，不能承揽新的工程；逾期仍未达到建筑业企业资质标准要求条件的，资质许可机关可以撤回其建筑业企业资质证书。 被撤回建筑业企业资质证书的企业，可以在资质被撤回后3个月内，向资质许可机关提出核定低于原等级同类别资质的申请。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，资质许可机关应当撤销建筑业企业资质： （一）资质许可机关工作人员滥用职权、玩忽职守准予资质许可的； （二）超越法定职权准予资质许可的； （三）违反法定程序准予资质许可的； （四）对不符合资质标准条件的申请企业准予资质许可的； （五）依法可以撤销资质许可的其他情形。 以欺骗、贿赂等不正当手段取得资质许可的，应当予以撤销。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，资质许可机关应当依法注销建筑业企业资质，并向社会公布其建筑业企业资质证书作废，企业应当及时将建筑业企业资质证书交回资质许可机关： （一）资质证书有效期届满，未依法申请延续的； （二）企业依法终止的； （三）资质证书依法被撤回、撤销或吊销的； （四）企业提出注销申请的； （五）法律、法规规定的应当注销建筑业企业资质的其他情形。"},{"i":31,"n":"第三十一条","txt":"有关部门应当将监督检查情况和处理意见及时告知资质许可机关。资质许可机关应当将涉及有关公路、水运、水利、通信、铁路、民航等方面的建筑业企业资质许可被撤回、撤销、吊销和注销的情况告知同级有关部门。"},{"i":32,"n":"第三十二条","txt":"资质许可机关应当建立、健全建筑业企业信用档案管理制度。建筑业企业信用档案应当包括企业基本情况、资质、业绩、工程质量和安全、合同履约、社会投诉和违法行为等情况。 企业的信用档案信息按照有关规定向社会公开。 取得建筑业企业资质的企业应当按照有关规定，向资质许可机关提供真实、准确、完整的企业信用档案信息。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人民政府住房城乡建设主管部门或其它有关部门依法给予企业行政处罚的，应当将行政处罚决定以及给予行政处罚的事实、理由和依据，通过省、自治区、直辖市人民政府住房城乡建设主管部门或者国务院有关部门报国务院住房城乡建设主管部门备案。"},{"i":34,"n":"第三十四条","txt":"资质许可机关应当推行建筑业企业资质许可电子化，建立建筑业企业资质管理信息系统。"},{"i":35,"n":"第三十五条","txt":"申请企业隐瞒有关真实情况或者提供虚假材料申请建筑业企业资质的，资质许可机关不予许可，并给予警告，申请企业在1年内不得再次申请建筑业企业资质。"},{"i":36,"n":"第三十六条","txt":"企业以欺骗、贿赂等不正当手段取得建筑业企业资质的，由原资质许可机关予以撤销；由县级以上地方人民政府住房城乡建设主管部门或者其他有关部门给予警告，并处3万元的罚款；申请企业3年内不得再次申请建筑业企业资质。"},{"i":37,"n":"第三十七条","txt":"企业有本规定第二十三条行为之一，《中华人民共和国建筑法》、《建设工程质量管理条例》和其他有关法律、法规对处罚机关和处罚方式有规定的，依照法律、法规的规定执行；法律、法规未作规定的，由县级以上地方人民政府住房城乡建设主管部门或者其他有关部门给予警告，责令改正，并处1万元以上3万元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"企业未按照本规定及时办理建筑业企业资质证书变更手续的，由县级以上地方人民政府住房城乡建设主管部门责令限期办理；逾期不办理的，可处以1000元以上1万元以下的罚款。"},{"i":39,"n":"第三十九条","txt":"企业在接受监督检查时，不如实提供有关材料，或者拒绝、阻碍监督检查的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，并可以处3万元以下罚款。"},{"i":40,"n":"第四十条","txt":"企业未按照本规定要求提供企业信用档案信息的，由县级以上地方人民政府住房城乡建设主管部门或者其他有关部门给予警告，责令限期改正；逾期未改正的，可处以1000元以上1万元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"县级以上人民政府住房城乡建设主管部门及其工作人员，违反本规定，有下列情形之一的，由其上级行政机关或者监察机关责令改正；对直接负责的主管人员和其他直接责任人员，依法给予行政处分；直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任： （一）对不符合资质标准规定条件的申请企业准予资质许可的； （二）对符合受理条件的申请企业不予受理或者未在法定期限内初审完毕的； （三）对符合资质标准规定条件的申请企业不予许可或者不在法定期限内准予资质许可的； （四）发现违反本规定规定的行为不予查处，或者接到举报后不依法处理的； （五）在企业资质许可和监督管理中，利用职务上的便利，收受他人财物或者其他好处，以及有其他违法行为的。"},{"i":42,"n":"第四十二条","txt":"本规定自2015年3月1日起施行。2007年6月26日建设部颁布的《建筑业企业资质管理规定》（建设部令第159号）同时废止。"}],"jianzhugongchengshigongfabaoyuchengbaojijiaguanlib6674f9":[{"i":1,"n":"第一条","txt":"为了规范建筑工程施工发包与承包计价行为，维护建筑工程发包与承包双方的合法权益，促进建筑市场的健康发展，根据有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内的建筑工程施工发包与承包计价（以下简称工程发承包计价）管理，适用本办法。 本办法所称建筑工程是指房屋建筑和市政基础设施工程。 本办法所称工程发承包计价包括编制工程量清单、最高投标限价、招标标底、投标报价，进行工程结算，以及签订和调整合同价款等活动。"},{"i":3,"n":"第三条","txt":"建筑工程施工发包与承包价在政府宏观调控下，由市场竞争形成。 工程发承包计价应当遵循公平、合法和诚实信用的原则。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责全国工程发承包计价工作的管理。 县级以上地方人民政府住房城乡建设主管部门负责本行政区域内工程发承包计价工作的管理。其具体工作可以委托工程造价管理机构负责。"},{"i":5,"n":"第五条","txt":"国家推广工程造价咨询制度，对建筑工程项目实行全过程造价管理。"},{"i":6,"n":"第六条","txt":"全部使用国有资金投资或者以国有资金投资为主的建筑工程（以下简称国有资金投资的建筑工程），应当采用工程量清单计价；非国有资金投资的建筑工程，鼓励采用工程量清单计价。 国有资金投资的建筑工程招标的，应当设有最高投标限价；非国有资金投资的建筑工程招标的，可以设有最高投标限价或者招标标底。 最高投标限价及其成果文件，应当由招标人报工程所在地县级以上地方人民政府住房城乡建设主管部门备案。"},{"i":7,"n":"第七条","txt":"工程量清单应当依据国家制定的工程量清单计价规范、工程量计算规范等编制。工程量清单应当作为招标文件的组成部分。"},{"i":8,"n":"第八条","txt":"最高投标限价应当依据工程量清单、工程计价有关规定和市场价格信息等编制。招标人设有最高投标限价的，应当在招标时公布最高投标限价的总价，以及各单位工程的分部分项工程费、措施项目费、其他项目费、规费和税金。"},{"i":9,"n":"第九条","txt":"招标标底应当依据工程计价有关规定和市场价格信息等编制。"},{"i":10,"n":"第十条","txt":"投标报价不得低于工程成本，不得高于最高投标限价。 投标报价应当依据工程量清单、工程计价有关规定、企业定额和市场价格信息等编制。"},{"i":11,"n":"第十一条","txt":"投标报价低于工程成本或者高于最高投标限价总价的，评标委员会应当否决投标人的投标。 对是否低于工程成本报价的异议，评标委员会可以参照国务院住房城乡建设主管部门和省、自治区、直辖市人民政府住房城乡建设主管部门发布的有关规定进行评审。"},{"i":12,"n":"第十二条","txt":"招标人与中标人应当根据中标价订立合同。不实行招标投标的工程由发承包双方协商订立合同。 合同价款的有关事项由发承包双方约定，一般包括合同价款约定方式，预付工程款、工程进度款、工程竣工价款的支付和结算方式，以及合同价款的调整情形等。"},{"i":13,"n":"第十三条","txt":"发承包双方在确定合同价款时，应当考虑市场环境和生产要素价格变化对合同价款的影响。 实行工程量清单计价的建筑工程，鼓励发承包双方采用单价方式确定合同价款。 建设规模较小、技术难度较低、工期较短的建筑工程，发承包双方可以采用总价方式确定合同价款。 紧急抢险、救灾以及施工技术特别复杂的建筑工程，发承包双方可以采用成本加酬金方式确定合同价款。"},{"i":14,"n":"第十四条","txt":"发承包双方应当在合同中约定，发生下列情形时合同价款的调整方法： （一）法律、法规、规章或者国家有关政策变化影响合同价款的； （二）工程造价管理机构发布价格调整信息的； （三）经批准变更设计的； （四）发包方更改经审定批准的施工组织设计造成费用增加的； （五）双方约定的其他因素。"},{"i":15,"n":"第十五条","txt":"发承包双方应当根据国务院住房城乡建设主管部门和省、自治区、直辖市人民政府住房城乡建设主管部门的规定，结合工程款、建设工期等情况在合同中约定预付工程款的具体事宜。 预付工程款按照合同价款或者年度工程计划额度的一定比例确定和支付，并在工程进度款中予以抵扣。"},{"i":16,"n":"第十六条","txt":"承包方应当按照合同约定向发包方提交已完成工程量报告。发包方收到工程量报告后，应当按照合同约定及时核对并确认。"},{"i":17,"n":"第十七条","txt":"发承包双方应当按照合同约定，定期或者按照工程进度分段进行工程款结算和支付。"},{"i":18,"n":"第十八条","txt":"工程完工后，应当按照下列规定进行竣工结算： （一）承包方应当在工程完工后的约定期限内提交竣工结算文件。 （二）国有资金投资建筑工程的发包方，应当委托具有相应资质的工程造价咨询企业对竣工结算文件进行审核，并在收到竣工结算文件后的约定期限内向承包方提出由工程造价咨询企业出具的竣工结算文件审核意见；逾期未答复的，按照合同约定处理，合同没有约定的，竣工结算文件视为已被认可。 非国有资金投资的建筑工程发包方，应当在收到竣工结算文件后的约定期限内予以答复，逾期未答复的，按照合同约定处理，合同没有约定的，竣工结算文件视为已被认可；发包方对竣工结算文件有异议的，应当在答复期内向承包方提出，并可以在提出异议之日起的约定期限内与承包方协商；发包方在协商期内未与承包方协商或者经协商未能与承包方达成协议的，应当委托工程造价咨询企业进行竣工结算审核，并在协商期满后的约定期限内向承包方提出由工程造价咨询企业出具的"},{"i":19,"n":"第十九条","txt":"工程竣工结算文件经发承包双方签字确认的，应当作为工程决算的依据，未经对方同意，另一方不得就已生效的竣工结算文件委托工程造价咨询企业重复审核。发包方应当按照竣工结算文件及时支付竣工结算款。 竣工结算文件应当由发包方报工程所在地县级以上地方人民政府住房城乡建设主管部门备案。"},{"i":20,"n":"第二十条","txt":"造价工程师编制工程量清单、最高投标限价、招标标底、投标报价、工程结算审核和工程造价鉴定文件，应当签字并加盖造价工程师执业专用章。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府住房城乡建设主管部门应当依照有关法律、法规和本办法规定，加强对建筑工程发承包计价活动的监督检查和投诉举报的核查，并有权采取下列措施： （一）要求被检查单位提供有关文件和资料； （二）就有关问题询问签署文件的人员； （三）要求改正违反有关法律、法规、本办法或者工程建设强制性标准的行为。 县级以上地方人民政府住房城乡建设主管部门应当将监督检查的处理结果向社会公开。"},{"i":22,"n":"第二十二条","txt":"造价工程师在最高投标限价、招标标底或者投标报价编制、工程结算审核和工程造价鉴定中，签署有虚假记载、误导性陈述的工程造价成果文件的，记入造价工程师信用档案，依照《注册造价工程师管理办法》进行查处；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"工程造价咨询企业在建筑工程计价活动中，出具有虚假记载、误导性陈述的工程造价成果文件的，记入工程造价咨询企业信用档案，由县级以上地方人民政府住房城乡建设主管部门责令改正，处1万元以上3万元以下的罚款，并予以通报。"},{"i":24,"n":"第二十四条","txt":"国家机关工作人员在建筑工程计价监督管理工作中玩忽职守、徇私舞弊、滥用职权的，由有关机关给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"建筑工程以外的工程施工发包与承包计价管理可以参照本办法执行。"},{"i":26,"n":"第二十六条","txt":"省、自治区、直辖市人民政府住房城乡建设主管部门可以根据本办法制定实施细则。"},{"i":27,"n":"第二十七条","txt":"本办法自2014年2月1日起施行。原建设部2001年11月5日发布的《建筑工程施工发包与承包计价管理办法》（建设部令第107号）同时废止。"}],"jianzhugongchengshigongxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对建筑活动的监督管理，维护建筑市场秩序，保证建筑工程的质量和安全，根据《中华人民共和国建筑法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事各类房屋建筑及其附属设施的建造、装修装饰和与其配套的线路、管道、设备的安装，以及城镇市政基础设施工程的施工，建设单位在开工前应当依照本办法的规定，向工程所在地的县级以上地方人民政府住房城乡建设主管部门（以下简称发证机关）申请领取施工许可证。 工程投资额在30万元以下或者建筑面积在300平方米以下的建筑工程，可以不申请办理施工许可证。省、自治区、直辖市人民政府住房城乡建设主管部门可以根据当地的实际情况，对限额进行调整，并报国务院住房城乡建设主管部门备案。 按照国务院规定的权限和程序批准开工报告的建筑工程，不再领取施工许可证。"},{"i":3,"n":"第三条","txt":"本办法规定应当申请领取施工许可证的建筑工程未取得施工许可证的，一律不得开工。 任何单位和个人不得将应当申请领取施工许可证的工程项目分解为若干限额以下的工程项目，规避申请领取施工许可证。"},{"i":4,"n":"第四条","txt":"建设单位申请领取施工许可证，应当具备下列条件，并提交相应的证明文件： （一）依法应当办理用地批准手续的，已经办理该建筑工程用地批准手续。 （二）依法应当办理建设工程规划许可证的，已经取得建设工程规划许可证。 （三）施工场地已经基本具备施工条件，需要征收房屋的，其进度符合施工要求。 （四）已经确定施工企业。按照规定应当招标的工程没有招标，应当公开招标的工程没有公开招标，或者肢解发包工程，以及将工程发包给不具备相应资质条件的企业的，所确定的施工企业无效。 （五）有满足施工需要的资金安排、施工图纸及技术资料，建设单位应当提供建设资金已经落实承诺书，施工图设计文件已按规定审查合格。 （六）有保证工程质量和安全的具体措施。施工企业编制的施工组织设计中有根据建筑工程特点制定的相应质量、安全技术措施。建立工程质量安全责任制并落实到人。专业性较强的工程项目编制了专项质量、安全施工组织设计，并按照规定办"},{"i":5,"n":"第五条","txt":"申请办理施工许可证，应当按照下列程序进行： （一）建设单位向发证机关领取《建筑工程施工许可证申请表》。 （二）建设单位持加盖单位及法定代表人印鉴的《建筑工程施工许可证申请表》，并附本办法第四条规定的证明文件，向发证机关提出申请。 （三）发证机关在收到建设单位报送的《建筑工程施工许可证申请表》和所附证明文件后，对于符合条件的，应当自收到申请之日起七日内颁发施工许可证；对于证明文件不齐全或者失效的，应当当场或者五日内一次告知建设单位需要补正的全部内容，审批时间可以自证明文件补正齐全后作相应顺延；对于不符合条件的，应当自收到申请之日起七日内书面通知建设单位，并说明理由。 建筑工程在施工过程中，建设单位或者施工单位发生变更的，应当重新申请领取施工许可证。"},{"i":6,"n":"第六条","txt":"建设单位申请领取施工许可证的工程名称、地点、规模，应当符合依法签订的施工承包合同。 施工许可证应当放置在施工现场备查，并按规定在施工现场公开。"},{"i":7,"n":"第七条","txt":"施工许可证不得伪造和涂改。"},{"i":8,"n":"第八条","txt":"建设单位应当自领取施工许可证之日起三个月内开工。因故不能按期开工的，应当在期满前向发证机关申请延期，并说明理由；延期以两次为限，每次不超过三个月。既不开工又不申请延期或者超过延期次数、时限的，施工许可证自行废止。"},{"i":9,"n":"第九条","txt":"在建的建筑工程因故中止施工的，建设单位应当自中止施工之日起一个月内向发证机关报告，报告内容包括中止施工的时间、原因、在施部位、维修管理措施等，并按照规定做好建筑工程的维护管理工作。 建筑工程恢复施工时，应当向发证机关报告；中止施工满一年的工程恢复施工前，建设单位应当报发证机关核验施工许可证。"},{"i":10,"n":"第十条","txt":"发证机关应当将办理施工许可证的依据、条件、程序、期限以及需要提交的全部材料和申请表示范文本等，在办公场所和有关网站予以公示。 发证机关作出的施工许可决定，应当予以公开，公众有权查阅。"},{"i":11,"n":"第十一条","txt":"发证机关应当建立颁发施工许可证后的监督检查制度，对取得施工许可证后条件发生变化、延期开工、中止施工等行为进行监督检查，发现违法违规行为及时处理。"},{"i":12,"n":"第十二条","txt":"对于未取得施工许可证或者为规避办理施工许可证将工程项目分解后擅自施工的，由有管辖权的发证机关责令停止施工，限期改正，对建设单位处工程合同价款1%以上2%以下罚款；对施工单位处3万元以下罚款。"},{"i":13,"n":"第十三条","txt":"建设单位采用欺骗、贿赂等不正当手段取得施工许可证的，由原发证机关撤销施工许可证，责令停止施工，并处1万元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"建设单位隐瞒有关情况或者提供虚假材料申请施工许可证的，发证机关不予受理或者不予许可，并处1万元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。 建设单位伪造或者涂改施工许可证的，由发证机关责令停止施工，并处1万元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":15,"n":"第十五条","txt":"依照本办法规定，给予单位罚款处罚的，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额5%以上10%以下罚款。 单位及相关责任人受到处罚的，作为不良行为记录予以通报。"},{"i":16,"n":"第十六条","txt":"发证机关及其工作人员，违反本办法，有下列情形之一的，由其上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分： （一）对不符合条件的申请人准予施工许可的； （二）对符合条件的申请人不予施工许可或者未在法定期限内作出准予许可决定的； （三）对符合条件的申请不予受理的； （四）利用职务上的便利，收受他人财物或者谋取其他利益的； （五）不依法履行监督职责或者监督不力，造成严重后果的。"},{"i":17,"n":"第十七条","txt":"建筑工程施工许可证由国务院住房城乡建设主管部门制定格式，由各省、自治区、直辖市人民政府住房城乡建设主管部门统一印制。 施工许可证分为正本和副本，正本和副本具有同等法律效力。复印的施工许可证无效。"},{"i":18,"n":"第十八条","txt":"本办法关于施工许可管理的规定适用于其他专业建筑工程。有关法律、行政法规有明确规定的，从其规定。 《建筑法》第八十三条第三款规定的建筑活动，不适用本办法。 军事房屋建筑工程施工许可的管理，按国务院、中央军事委员会制定的办法执行。"},{"i":19,"n":"第十九条","txt":"省、自治区、直辖市人民政府住房城乡建设主管部门可以根据本办法制定实施细则。"},{"i":20,"n":"第二十条","txt":"本办法自2014年10月25日起施行。1999年10月15日建设部令第71号发布、2001年7月4日建设部令第91号修正的《建筑工程施工许可管理办法》同时废止。"}],"jianzhugongchengshejizhaobiaotoubiaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范建筑工程设计市场，提高建筑工程设计水平，促进公平竞争，繁荣建筑创作，根据《中华人民共和国建筑法》、《中华人民共和国招标投标法》、《建设工程勘察设计管理条例》和《中华人民共和国招标投标法实施条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"依法必须进行招标的各类房屋建筑工程，其设计招标投标活动，适用本办法。"},{"i":3,"n":"第三条","txt":"国务院住房城乡建设主管部门依法对全国建筑工程设计招标投标活动实施监督。 县级以上地方人民政府住房城乡建设主管部门依法对本行政区域内建筑工程设计招标投标活动实施监督，依法查处招标投标活动中的违法违规行为。"},{"i":4,"n":"第四条","txt":"建筑工程设计招标范围和规模标准按照国家有关规定执行，有下列情形之一的，可以不进行招标： （一）采用不可替代的专利或者专有技术的； （二）对建筑艺术造型有特殊要求，并经有关主管部门批准的； （三）建设单位依法能够自行设计的； （四）建筑工程项目的改建、扩建或者技术改造，需要由原设计单位设计，否则将影响功能配套要求的； （五）国家规定的其他特殊情形。"},{"i":5,"n":"第五条","txt":"建筑工程设计招标应当依法进行公开招标或者邀请招标。"},{"i":6,"n":"第六条","txt":"建筑工程设计招标可以采用设计方案招标或者设计团队招标，招标人可以根据项目特点和实际需要选择。 设计方案招标，是指主要通过对投标人提交的设计方案进行评审确定中标人。 设计团队招标，是指主要通过对投标人拟派设计团队的综合能力进行评审确定中标人。"},{"i":7,"n":"第七条","txt":"公开招标的，招标人应当发布招标公告。邀请招标的，招标人应当向3个以上潜在投标人发出投标邀请书。 招标公告或者投标邀请书应当载明招标人名称和地址、招标项目的基本要求、投标人的资质要求以及获取招标文件的办法等事项。"},{"i":8,"n":"第八条","txt":"招标人一般应当将建筑工程的方案设计、初步设计和施工图设计一并招标。确需另行选择设计单位承担初步设计、施工图设计的，应当在招标公告或者投标邀请书中明确。"},{"i":9,"n":"第九条","txt":"鼓励建筑工程实行设计总包。实行设计总包的，按照合同约定或者经招标人同意，设计单位可以不通过招标方式将建筑工程非主体部分的设计进行分包。"},{"i":10,"n":"第十条","txt":"招标文件应当满足设计方案招标或者设计团队招标的不同需求，主要包括以下内容： （一）项目基本情况； （二）城乡规划和城市设计对项目的基本要求； （三）项目工程经济技术要求； （四）项目有关基础资料； （五）招标内容； （六）招标文件答疑、现场踏勘安排； （七）投标文件编制要求； （八）评标标准和方法； （九）投标文件送达地点和截止时间； （十）开标时间和地点； （十一）拟签订合同的主要条款； （十二）设计费或者计费方法； （十三）未中标方案补偿办法。"},{"i":11,"n":"第十一条","txt":"招标人应当在资格预审公告、招标公告或者投标邀请书中载明是否接受联合体投标。采用联合体形式投标的，联合体各方应当签订共同投标协议，明确约定各方承担的工作和责任，就中标项目向招标人承担连带责任。"},{"i":12,"n":"第十二条","txt":"招标人可以对已发出的招标文件进行必要的澄清或者修改。澄清或者修改的内容可能影响投标文件编制的，招标人应当在投标截止时间至少15日前，以书面形式通知所有获取招标文件的潜在投标人，不足15日的，招标人应当顺延提交投标文件的截止时间。 潜在投标人或者其他利害关系人对招标文件有异议的，应当在投标截止时间10日前提出。招标人应当自收到异议之日起3日内作出答复；作出答复前，应当暂停招标投标活动。"},{"i":13,"n":"第十三条","txt":"招标人应当确定投标人编制投标文件所需要的合理时间，自招标文件开始发出之日起至投标人提交投标文件截止之日止，时限最短不少于20日。"},{"i":14,"n":"第十四条","txt":"投标人应当具有与招标项目相适应的工程设计资质。境外设计单位参加国内建筑工程设计投标的，按照国家有关规定执行。"},{"i":15,"n":"第十五条","txt":"投标人应当按照招标文件的要求编制投标文件。投标文件应当对招标文件提出的实质性要求和条件作出响应。"},{"i":16,"n":"第十六条","txt":"评标由评标委员会负责。 评标委员会由招标人代表和有关专家组成。评标委员会人数为5人以上单数，其中技术和经济方面的专家不得少于成员总数的2/3。建筑工程设计方案评标时，建筑专业专家不得少于技术和经济方面专家总数的2/3。 评标专家一般从专家库随机抽取，对于技术复杂、专业性强或者国家有特殊要求的项目，招标人也可以直接邀请相应专业的中国科学院院士、中国工程院院士、全国工程勘察设计大师以及境外具有相应资历的专家参加评标。 投标人或者与投标人有利害关系的人员不得参加评标委员会。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，评标委员会应当否决其投标： （一）投标文件未按招标文件要求经投标人盖章和单位负责人签字； （二）投标联合体没有提交共同投标协议； （三）投标人不符合国家或者招标文件规定的资格条件； （四）同一投标人提交两个以上不同的投标文件或者投标报价，但招标文件要求提交备选投标的除外； （五）投标文件没有对招标文件的实质性要求和条件作出响应； （六）投标人有串通投标、弄虚作假、行贿等违法行为； （七）法律法规规定的其他应当否决投标的情形。"},{"i":18,"n":"第十八条","txt":"评标委员会应当按照招标文件确定的评标标准和方法，对投标文件进行评审。 采用设计方案招标的，评标委员会应当在符合城乡规划、城市设计以及安全、绿色、节能、环保要求的前提下，重点对功能、技术、经济和美观等进行评审。 采用设计团队招标的，评标委员会应当对投标人拟从事项目设计的人员构成、人员业绩、人员从业经历、项目解读、设计构思、投标人信用情况和业绩等进行评审。"},{"i":19,"n":"第十九条","txt":"评标委员会应当在评标完成后，向招标人提出书面评标报告，推荐不超过3个中标候选人，并标明顺序。"},{"i":20,"n":"第二十条","txt":"招标人应当公示中标候选人。采用设计团队招标的，招标人应当公示中标候选人投标文件中所列主要人员、业绩等内容。"},{"i":21,"n":"第二十一条","txt":"招标人根据评标委员会的书面评标报告和推荐的中标候选人确定中标人。招标人也可以授权评标委员会直接确定中标人。 采用设计方案招标的，招标人认为评标委员会推荐的候选方案不能最大限度满足招标文件规定的要求的，应当依法重新招标。"},{"i":22,"n":"第二十二条","txt":"招标人应当在确定中标人后及时向中标人发出中标通知书，并同时将中标结果通知所有未中标人。"},{"i":23,"n":"第二十三条","txt":"招标人应当自确定中标人之日起15日内，向县级以上地方人民政府住房城乡建设主管部门提交招标投标情况的书面报告。"},{"i":24,"n":"第二十四条","txt":"县级以上地方人民政府住房城乡建设主管部门应当自收到招标投标情况的书面报告之日起5个工作日内，公开专家评审意见等信息，涉及国家秘密、商业秘密的除外。"},{"i":25,"n":"第二十五条","txt":"招标人和中标人应当自中标通知书发出之日起30日内，按照招标文件和中标人的投标文件订立书面合同。"},{"i":26,"n":"第二十六条","txt":"招标人、中标人使用未中标方案的，应当征得提交方案的投标人同意并付给使用费。"},{"i":27,"n":"第二十七条","txt":"国务院住房城乡建设主管部门，省、自治区、直辖市人民政府住房城乡建设主管部门应当加强建筑工程设计评标专家和专家库的管理。 建筑专业专家库应当按建筑工程类别细化分类。"},{"i":28,"n":"第二十八条","txt":"住房城乡建设主管部门应当加快推进电子招标投标，完善招标投标信息平台建设，促进建筑工程设计招标投标信息化监管。"},{"i":29,"n":"第二十九条","txt":"招标人以不合理的条件限制或者排斥潜在投标人的，对潜在投标人实行歧视待遇的，强制要求投标人组成联合体共同投标的，或者限制投标人之间竞争的，由县级以上地方人民政府住房城乡建设主管部门责令改正，可以处1万元以上5万元以下的罚款。"},{"i":30,"n":"第三十条","txt":"招标人澄清、修改招标文件的时限，或者确定的提交投标文件的时限不符合本办法规定的，由县级以上地方人民政府住房城乡建设主管部门责令改正，可以处10万元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"招标人不按照规定组建评标委员会，或者评标委员会成员的确定违反本办法规定的，由县级以上地方人民政府住房城乡建设主管部门责令改正，可以处10万元以下的罚款，相应评审结论无效，依法重新进行评审。"},{"i":32,"n":"第三十二条","txt":"招标人有下列情形之一的，由县级以上地方人民政府住房城乡建设主管部门责令改正，可以处中标项目金额10‰以下的罚款；给他人造成损失的，依法承担赔偿责任；对单位直接负责的主管人员和其他直接责任人员依法给予处分： （一）无正当理由未按本办法规定发出中标通知书； （二）不按照规定确定中标人； （三）中标通知书发出后无正当理由改变中标结果； （四）无正当理由未按本办法规定与中标人订立合同； （五）在订立合同时向中标人提出附加条件。"},{"i":33,"n":"第三十三条","txt":"投标人以他人名义投标或者以其他方式弄虚作假，骗取中标的，中标无效，给招标人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。 投标人有前款所列行为尚未构成犯罪的，由县级以上地方人民政府住房城乡建设主管部门处中标项目金额5‰以上10‰以下的罚款，对单位直接负责的主管人员和其他直接责任人员处单位罚款数额5%以上10%以下的罚款；有违法所得的，并处没收违法所得；情节严重的，取消其1年至3年内参加依法必须进行招标的建筑工程设计招标的投标资格，并予以公告，直至由工商行政管理机关吊销营业执照。"},{"i":34,"n":"第三十四条","txt":"评标委员会成员收受投标人的财物或者其他好处的，评标委员会成员或者参加评标的有关工作人员向他人透露对投标文件的评审和比较、中标候选人的推荐以及与评标有关的其他情况的，由县级以上地方人民政府住房城乡建设主管部门给予警告，没收收受的财物，可以并处3000元以上5万元以下的罚款。 评标委员会成员有前款所列行为的，由有关主管部门通报批评并取消担任评标委员会成员的资格，不得再参加任何依法必须进行招标的建筑工程设计招标投标的评标；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"评标委员会成员违反本办法规定，对应当否决的投标不提出否决意见的，由县级以上地方人民政府住房城乡建设主管部门责令改正；情节严重的，禁止其在一定期限内参加依法必须进行招标的建筑工程设计招标投标的评标；情节特别严重的，由有关主管部门取消其担任评标委员会成员的资格。"},{"i":36,"n":"第三十六条","txt":"住房城乡建设主管部门或者有关职能部门的工作人员徇私舞弊、滥用职权或者玩忽职守，构成犯罪的，依法追究刑事责任；不构成犯罪的，依法给予行政处分。"},{"i":37,"n":"第三十七条","txt":"市政公用工程及园林工程设计招标投标参照本办法执行。"},{"i":38,"n":"第三十八条","txt":"本办法自2017年5月1日起施行。2000年10月18日建设部颁布的《建筑工程设计招标投标管理办法》（建设部令第82号）同时废止。"}],"jianzhushigongqiyezhuyaofuzerenxiangmufuzerenhezhudd88b7":[{"i":1,"n":"第一条","txt":"为了加强房屋建筑和市政基础设施工程施工安全监督管理，提高建筑施工企业主要负责人、项目负责人和专职安全生产管理人员（以下合称“安管人员”）的安全生产管理能力，根据《中华人民共和国安全生产法》、《建设工程安全生产管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事房屋建筑和市政基础设施工程施工活动的建筑施工企业的“安管人员”，参加安全生产考核，履行安全生产责任，以及对其实施安全生产监督管理，应当符合本规定。"},{"i":3,"n":"第三条","txt":"企业主要负责人，是指对本企业生产经营活动和安全生产工作具有决策权的领导人员。 项目负责人，是指取得相应注册执业资格，由企业法定代表人授权，负责具体工程项目管理的人员。 专职安全生产管理人员，是指在企业专职从事安全生产管理工作的人员，包括企业安全生产管理机构的人员和工程项目专职从事安全生产管理工作的人员。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责对全国“安管人员”安全生产工作进行监督管理。 县级以上地方人民政府住房城乡建设主管部门负责对本行政区域内“安管人员”安全生产工作进行监督管理。"},{"i":5,"n":"第五条","txt":"“安管人员”应当通过其受聘企业，向企业工商注册地的省、自治区、直辖市人民政府住房城乡建设主管部门（以下简称考核机关）申请安全生产考核，并取得安全生产考核合格证书。安全生产考核不得收费。"},{"i":6,"n":"第六条","txt":"申请参加安全生产考核的“安管人员”，应当具备相应文化程度、专业技术职称和一定安全生产工作经历，与企业确立劳动关系，并经企业年度安全生产教育培训合格。"},{"i":7,"n":"第七条","txt":"安全生产考核包括安全生产知识考核和管理能力考核。 安全生产知识考核内容包括：建筑施工安全的法律法规、规章制度、标准规范，建筑施工安全管理基本理论等。 安全生产管理能力考核内容包括：建立和落实安全生产管理制度、辨识和监控危险性较大的分部分项工程、发现和消除安全事故隐患、报告和处置生产安全事故等方面的能力。"},{"i":8,"n":"第八条","txt":"对安全生产考核合格的，考核机关应当在20个工作日内核发安全生产考核合格证书，并予以公告；对不合格的，应当通过“安管人员”所在企业通知本人并说明理由。"},{"i":9,"n":"第九条","txt":"安全生产考核合格证书有效期为3年，证书在全国范围内有效。 证书式样由国务院住房城乡建设主管部门统一规定。"},{"i":10,"n":"第十条","txt":"安全生产考核合格证书有效期届满需要延续的，“安管人员”应当在有效期届满前3个月内，由本人通过受聘企业向原考核机关申请证书延续。准予证书延续的，证书有效期延续3年。 对证书有效期内未因生产安全事故或者违反本规定受到行政处罚，信用档案中无不良行为记录，且已按规定参加企业和县级以上人民政府住房城乡建设主管部门组织的安全生产教育培训的，考核机关应当在受理延续申请之日起20个工作日内，准予证书延续。"},{"i":11,"n":"第十一条","txt":"“安管人员”变更受聘企业的，应当与原聘用企业解除劳动关系，并通过新聘用企业到考核机关申请办理证书变更手续。考核机关应当在受理变更申请之日起5个工作日内办理完毕。"},{"i":12,"n":"第十二条","txt":"“安管人员”遗失安全生产考核合格证书的，应当在公共媒体上声明作废，通过其受聘企业向原考核机关申请补办。考核机关应当在受理申请之日起5个工作日内办理完毕。"},{"i":13,"n":"第十三条","txt":"“安管人员”不得涂改、倒卖、出租、出借或者以其他形式非法转让安全生产考核合格证书。"},{"i":14,"n":"第十四条","txt":"主要负责人对本企业安全生产工作全面负责，应当建立健全企业安全生产管理体系，设置安全生产管理机构，配备专职安全生产管理人员，保证安全生产投入，督促检查本企业安全生产工作，及时消除安全事故隐患，落实安全生产责任。"},{"i":15,"n":"第十五条","txt":"主要负责人应当与项目负责人签订安全生产责任书，确定项目安全生产考核目标、奖惩措施，以及企业为项目提供的安全管理和技术保障措施。 工程项目实行总承包的，总承包企业应当与分包企业签订安全生产协议，明确双方安全生产责任。"},{"i":16,"n":"第十六条","txt":"主要负责人应当按规定检查企业所承担的工程项目，考核项目负责人安全生产管理能力。发现项目负责人履职不到位的，应当责令其改正；必要时，调整项目负责人。检查情况应当记入企业和项目安全管理档案。"},{"i":17,"n":"第十七条","txt":"项目负责人对本项目安全生产管理全面负责，应当建立项目安全生产管理体系，明确项目管理人员安全职责，落实安全生产管理制度，确保项目安全生产费用有效使用。"},{"i":18,"n":"第十八条","txt":"项目负责人应当按规定实施项目安全生产管理，监控危险性较大分部分项工程，及时排查处理施工现场安全事故隐患，隐患排查处理情况应当记入项目安全管理档案；发生事故时，应当按规定及时报告并开展现场救援。 工程项目实行总承包的，总承包企业项目负责人应当定期考核分包企业安全生产管理情况。"},{"i":19,"n":"第十九条","txt":"企业安全生产管理机构专职安全生产管理人员应当检查在建项目安全生产管理情况，重点检查项目负责人、项目专职安全生产管理人员履责情况，处理在建项目违规违章行为，并记入企业安全管理档案。"},{"i":20,"n":"第二十条","txt":"项目专职安全生产管理人员应当每天在施工现场开展安全检查，现场监督危险性较大的分部分项工程安全专项施工方案实施。对检查中发现的安全事故隐患，应当立即处理；不能处理的，应当及时报告项目负责人和企业安全生产管理机构。项目负责人应当及时处理。检查及处理情况应当记入项目安全管理档案。"},{"i":21,"n":"第二十一条","txt":"建筑施工企业应当建立安全生产教育培训制度，制定年度培训计划，每年对“安管人员”进行培训和考核，考核不合格的，不得上岗。培训情况应当记入企业安全生产教育培训档案。"},{"i":22,"n":"第二十二条","txt":"建筑施工企业安全生产管理机构和工程项目应当按规定配备相应数量和相关专业的专职安全生产管理人员。危险性较大的分部分项工程施工时，应当安排专职安全生产管理人员现场监督。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府住房城乡建设主管部门应当依照有关法律法规和本规定，对“安管人员”持证上岗、教育培训和履行职责等情况进行监督检查。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府住房城乡建设主管部门在实施监督检查时，应当有两名以上监督检查人员参加，不得妨碍企业正常的生产经营活动，不得索取或者收受企业的财物，不得谋取其他利益。 有关企业和个人对依法进行的监督检查应当协助与配合，不得拒绝或者阻挠。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府住房城乡建设主管部门依法进行监督检查时，发现“安管人员”有违反本规定行为的，应当依法查处并将违法事实、处理结果或者处理建议告知考核机关。"},{"i":26,"n":"第二十六条","txt":"考核机关应当建立本行政区域内“安管人员”的信用档案。违法违规行为、被投诉举报处理、行政处罚等情况应当作为不良行为记入信用档案，并按规定向社会公开。 “安管人员”及其受聘企业应当按规定向考核机关提供相关信息。"},{"i":27,"n":"第二十七条","txt":"“安管人员”隐瞒有关情况或者提供虚假材料申请安全生产考核的，考核机关不予考核，并给予警告；“安管人员”1年内不得再次申请考核。 “安管人员”以欺骗、贿赂等不正当手段取得安全生产考核合格证书的，由原考核机关撤销安全生产考核合格证书；“安管人员”3年内不得再次申请考核。"},{"i":28,"n":"第二十八条","txt":"“安管人员”涂改、倒卖、出租、出借或者以其他形式非法转让安全生产考核合格证书的，由县级以上地方人民政府住房城乡建设主管部门给予警告，并处1000元以上5000元以下的罚款。"},{"i":29,"n":"第二十九条","txt":"建筑施工企业未按规定开展“安管人员”安全生产教育培训考核，或者未按规定如实将考核情况记入安全生产教育培训档案的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，并处2万元以下的罚款。"},{"i":30,"n":"第三十条","txt":"建筑施工企业有下列行为之一的，由县级以上人民政府住房城乡建设主管部门责令限期改正；逾期未改正的，责令停业整顿，并处2万元以下的罚款；导致不具备《安全生产许可证条例》规定的安全生产条件的，应当依法暂扣或者吊销安全生产许可证： （一）未按规定设立安全生产管理机构的； （二）未按规定配备专职安全生产管理人员的； （三）危险性较大的分部分项工程施工时未安排专职安全生产管理人员现场监督的； （四）“安管人员”未取得安全生产考核合格证书的。"},{"i":31,"n":"第三十一条","txt":"“安管人员”未按规定办理证书变更的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，并处1000元以上5000元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"主要负责人、项目负责人未按规定履行安全生产管理职责的，由县级以上人民政府住房城乡建设主管部门责令限期改正；逾期未改正的，责令建筑施工企业停业整顿；造成生产安全事故或者其他严重后果的，按照《生产安全事故报告和调查处理条例》的有关规定，依法暂扣或者吊销安全生产考核合格证书；构成犯罪的，依法追究刑事责任。 主要负责人、项目负责人有前款违法行为，尚不够刑事处罚的，处2万元以上20万元以下的罚款或者按照管理权限给予撤职处分；自刑罚执行完毕或者受处分之日起，5年内不得担任建筑施工企业的主要负责人、项目负责人。"},{"i":33,"n":"第三十三条","txt":"专职安全生产管理人员未按规定履行安全生产管理职责的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，并处1000元以上5000元以下的罚款；造成生产安全事故或者其他严重后果的，按照《生产安全事故报告和调查处理条例》的有关规定，依法暂扣或者吊销安全生产考核合格证书；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"县级以上人民政府住房城乡建设主管部门及其工作人员，有下列情形之一的，由其上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）向不具备法定条件的“安管人员”核发安全生产考核合格证书的； （二）对符合法定条件的“安管人员”不予核发或者不在法定期限内核发安全生产考核合格证书的； （三）对符合法定条件的申请不予受理或者未在法定期限内办理完毕的； （四）利用职务上的便利，索取或者收受他人财物或者谋取其他利益的； （五）不依法履行监督管理职责，造成严重后果的。"},{"i":35,"n":"第三十五条","txt":"本规定自2014年9月1日起施行。"}],"jianzhushigongqiyeanquanshengchanxukezhengguanligufa5bb0":[{"i":1,"n":"第一条","txt":"为了严格规范建筑施工企业安全生产条件，进一步加强安全生产监督管理，防止和减少生产安全事故，根据《安全生产许可证条例》、《建设工程安全生产管理条例》等有关行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"国家对建筑施工企业实行安全生产许可制度。 建筑施工企业未取得安全生产许可证的，不得从事建筑施工活动。 本规定所称建筑施工企业，是指从事土木工程、建筑工程、线路管道和设备安装工程及装修工程的新建、扩建、改建和拆除等有关活动的企业。"},{"i":3,"n":"第三条","txt":"国务院住房城乡建设主管部门负责对全国建筑施工企业安全生产许可证的颁发和管理工作进行监督指导。 省、自治区、直辖市人民政府住房城乡建设主管部门负责本行政区域内建筑施工企业安全生产许可证的颁发和管理工作。 市、县人民政府住房城乡建设主管部门负责本行政区域内建筑施工企业安全生产许可证的监督管理，并将监督检查中发现的企业违法行为及时报告安全生产许可证颁发管理机关。"},{"i":4,"n":"第四条","txt":"建筑施工企业取得安全生产许可证，应当具备下列安全生产条件： （一）建立、健全安全生产责任制，制定完备的安全生产规章制度和操作规程； （二）保证本单位安全生产条件所需资金的投入； （三）设置安全生产管理机构，按照国家有关规定配备专职安全生产管理人员； （四）主要负责人、项目负责人、专职安全生产管理人员经住房城乡建设主管部门或者其他有关部门考核合格； （五）特种作业人员经有关业务主管部门考核合格，取得特种作业操作资格证书； （六）管理人员和作业人员每年至少进行一次安全生产教育培训并考核合格； （七）依法参加工伤保险，依法为施工现场从事危险作业的人员办理意外伤害保险，为从业人员交纳保险费； （八）施工现场的办公、生活区及作业场所和安全防护用具、机械设备、施工机具及配件符合有关安全生产法律、法规、标准和规程的要求； （九）有职业危害防治措施，并为作业人员配备符合国家标准或者行业标准的安全防护用"},{"i":5,"n":"第五条","txt":"建筑施工企业从事建筑施工活动前，应当依照本规定向企业注册所在地省、自治区、直辖市人民政府住房城乡建设主管部门申请领取安全生产许可证。"},{"i":6,"n":"第六条","txt":"建筑施工企业申请安全生产许可证时，应当向住房城乡建设主管部门提供下列材料： （一）建筑施工企业安全生产许可证申请表； （二）企业法人营业执照； （三）第四条规定的相关文件、材料。 建筑施工企业申请安全生产许可证，应当对申请材料实质内容的真实性负责，不得隐瞒有关情况或者提供虚假材料。"},{"i":7,"n":"第七条","txt":"住房城乡建设主管部门应当自受理建筑施工企业的申请之日起45日内审查完毕；经审查符合安全生产条件的，颁发安全生产许可证；不符合安全生产条件的，不予颁发安全生产许可证，书面通知企业并说明理由。企业自接到通知之日起应当进行整改，整改合格后方可再次提出申请。 住房城乡建设主管部门审查建筑施工企业安全生产许可证申请，涉及铁路、交通、水利等有关专业工程时，可以征求铁路、交通、水利等有关部门的意见。"},{"i":8,"n":"第八条","txt":"安全生产许可证的有效期为3年。安全生产许可证有效期满需要延期的，企业应当于期满前3个月向原安全生产许可证颁发管理机关申请办理延期手续。 企业在安全生产许可证有效期内，严格遵守有关安全生产的法律法规，未发生死亡事故的，安全生产许可证有效期届满时，经原安全生产许可证颁发管理机关同意，不再审查，安全生产许可证有效期延期3年。"},{"i":9,"n":"第九条","txt":"建筑施工企业变更名称、地址、法定代表人等，应当在变更后10日内，到原安全生产许可证颁发管理机关办理安全生产许可证变更手续。"},{"i":10,"n":"第十条","txt":"建筑施工企业破产、倒闭、撤销的，应当将安全生产许可证交回原安全生产许可证颁发管理机关予以注销。"},{"i":11,"n":"第十一条","txt":"建筑施工企业遗失安全生产许可证，应当立即向原安全生产许可证颁发管理机关报告，并在公众媒体上声明作废后，方可申请补办。"},{"i":12,"n":"第十二条","txt":"安全生产许可证申请表采用建设部规定的统一式样。 安全生产许可证采用国务院安全生产监督管理部门规定的统一式样。 安全生产许可证分正本和副本，正、副本具有同等法律效力。"},{"i":13,"n":"第十三条","txt":"县级以上人民政府住房城乡建设主管部门应当加强对建筑施工企业安全生产许可证的监督管理。住房城乡建设主管部门在审核发放施工许可证时，应当对已经确定的建筑施工企业是否有安全生产许可证进行审查，对没有取得安全生产许可证的，不得颁发施工许可证。"},{"i":14,"n":"第十四条","txt":"跨省从事建筑施工活动的建筑施工企业有违反本规定行为的，由工程所在地的省级人民政府住房城乡建设主管部门将建筑施工企业在本地区的违法事实、处理结果和处理建议抄告原安全生产许可证颁发管理机关。"},{"i":15,"n":"第十五条","txt":"建筑施工企业取得安全生产许可证后，不得降低安全生产条件，并应当加强日常安全生产管理，接受住房城乡建设主管部门的监督检查。安全生产许可证颁发管理机关发现企业不再具备安全生产条件的，应当暂扣或者吊销安全生产许可证。"},{"i":16,"n":"第十六条","txt":"安全生产许可证颁发管理机关或者其上级行政机关发现有下列情形之一的，可以撤销已经颁发的安全生产许可证： （一）安全生产许可证颁发管理机关工作人员滥用职权、玩忽职守颁发安全生产许可证的； （二）超越法定职权颁发安全生产许可证的； （三）违反法定程序颁发安全生产许可证的； （四）对不具备安全生产条件的建筑施工企业颁发安全生产许可证的； （五）依法可以撤销已经颁发的安全生产许可证的其他情形。 依照前款规定撤销安全生产许可证，建筑施工企业的合法权益受到损害的，住房城乡建设主管部门应当依法给予赔偿。"},{"i":17,"n":"第十七条","txt":"安全生产许可证颁发管理机关应当建立、健全安全生产许可证档案管理制度，定期向社会公布企业取得安全生产许可证的情况，每年向同级安全生产监督管理部门通报建筑施工企业安全生产许可证颁发和管理情况。"},{"i":18,"n":"第十八条","txt":"建筑施工企业不得转让、冒用安全生产许可证或者使用伪造的安全生产许可证。"},{"i":19,"n":"第十九条","txt":"住房城乡建设主管部门工作人员在安全生产许可证颁发、管理和监督检查工作中，不得索取或者接受建筑施工企业的财物，不得谋取其他利益。"},{"i":20,"n":"第二十条","txt":"任何单位或者个人对违反本规定的行为，有权向安全生产许可证颁发管理机关或者监察机关等有关部门举报。"},{"i":21,"n":"第二十一条","txt":"违反本规定，住房城乡建设主管部门工作人员有下列行为之一的，给予降级或者撤职的行政处分；构成犯罪的，依法追究刑事责任： （一）向不符合安全生产条件的建筑施工企业颁发安全生产许可证的； （二）发现建筑施工企业未依法取得安全生产许可证擅自从事建筑施工活动，不依法处理的； （三）发现取得安全生产许可证的建筑施工企业不再具备安全生产条件，不依法处理的； （四）接到对违反本规定行为的举报后，不及时处理的； （五）在安全生产许可证颁发、管理和监督检查工作中，索取或者接受建筑施工企业的财物，或者谋取其他利益的。 由于建筑施工企业弄虚作假，造成前款第（一）项行为的，对住房城乡建设主管部门工作人员不予处分。"},{"i":22,"n":"第二十二条","txt":"取得安全生产许可证的建筑施工企业，发生重大安全事故的，暂扣安全生产许可证并限期整改。"},{"i":23,"n":"第二十三条","txt":"建筑施工企业不再具备安全生产条件的，暂扣安全生产许可证并限期整改；情节严重的，吊销安全生产许可证。"},{"i":24,"n":"第二十四条","txt":"违反本规定，建筑施工企业未取得安全生产许可证擅自从事建筑施工活动的，责令其在建项目停止施工，没收违法所得，并处10万元以上50万元以下的罚款；造成重大安全事故或者其他严重后果，构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"违反本规定，安全生产许可证有效期满未办理延期手续，继续从事建筑施工活动的，责令其在建项目停止施工，限期补办延期手续，没收违法所得，并处5万元以上10万元以下的罚款；逾期仍不办理延期手续，继续从事建筑施工活动的，依照本规定第二十四条的规定处罚。"},{"i":26,"n":"第二十六条","txt":"违反本规定，建筑施工企业转让安全生产许可证的，没收违法所得，处10万元以上50万元以下的罚款，并吊销安全生产许可证；构成犯罪的，依法追究刑事责任；接受转让的，依照本规定第二十四条的规定处罚。 冒用安全生产许可证或者使用伪造的安全生产许可证的，依照本规定第二十四条的规定处罚。"},{"i":27,"n":"第二十七条","txt":"违反本规定，建筑施工企业隐瞒有关情况或者提供虚假材料申请安全生产许可证的，不予受理或者不予颁发安全生产许可证，并给予警告，1年内不得申请安全生产许可证。 建筑施工企业以欺骗、贿赂等不正当手段取得安全生产许可证的，撤销安全生产许可证，3年内不得再次申请安全生产许可证；构成犯罪的，依法追究刑事责任。"},{"i":28,"n":"第二十八条","txt":"本规定的暂扣、吊销安全生产许可证的行政处罚，由安全生产许可证的颁发管理机关决定；其他行政处罚，由县级以上地方人民政府住房城乡建设主管部门决定。"},{"i":29,"n":"第二十九条","txt":"本规定施行前已依法从事建筑施工活动的建筑施工企业，应当自《安全生产许可证条例》施行之日起（2004年1月13日起）1年内向住房城乡建设主管部门申请办理建筑施工企业安全生产许可证；逾期不办理安全生产许可证，或者经审查不符合本规定的安全生产条件，未取得安全生产许可证，继续进行建筑施工活动的，依照本规定第二十四条的规定处罚。"},{"i":30,"n":"第三十条","txt":"本规定自公布之日起施行。"}],"jianzhuqizhongjixieanquanjianduguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强建筑起重机械的安全监督管理，防止和减少生产安全事故，保障人民群众生命和财产安全，依据《建设工程安全生产管理条例》、《特种设备安全监察条例》、《安全生产许可证条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"建筑起重机械的租赁、安装、拆卸、使用及其监督管理，适用本规定。 本规定所称建筑起重机械，是指纳入特种设备目录，在房屋建筑工地和市政工程工地安装、拆卸、使用的起重机械。"},{"i":3,"n":"第三条","txt":"国务院建设主管部门对全国建筑起重机械的租赁、安装、拆卸、使用实施监督管理。 县级以上地方人民政府建设主管部门对本行政区域内的建筑起重机械的租赁、安装、拆卸、使用实施监督管理。"},{"i":4,"n":"第四条","txt":"出租单位出租的建筑起重机械和使用单位购置、租赁、使用的建筑起重机械应当具有特种设备制造许可证、产品合格证、制造监督检验证明。"},{"i":5,"n":"第五条","txt":"出租单位在建筑起重机械首次出租前，自购建筑起重机械的使用单位在建筑起重机械首次安装前，应当持建筑起重机械特种设备制造许可证、产品合格证和制造监督检验证明到本单位工商注册所在地县级以上地方人民政府建设主管部门办理备案。"},{"i":6,"n":"第六条","txt":"出租单位应当在签订的建筑起重机械租赁合同中，明确租赁双方的安全责任，并出具建筑起重机械特种设备制造许可证、产品合格证、制造监督检验证明、备案证明和自检合格证明，提交安装使用说明书。"},{"i":7,"n":"第七条","txt":"有下列情形之一的建筑起重机械，不得出租、使用： （一）属国家明令淘汰或者禁止使用的； （二）超过安全技术标准或者制造厂家规定的使用年限的； （三）经检验达不到安全技术标准规定的； （四）没有完整安全技术档案的； （五）没有齐全有效的安全保护装置的。"},{"i":8,"n":"第八条","txt":"建筑起重机械有本规定第七条第（一）、（二）、（三）项情形之一的，出租单位或者自购建筑起重机械的使用单位应当予以报废，并向原备案机关办理注销手续。"},{"i":9,"n":"第九条","txt":"出租单位、自购建筑起重机械的使用单位，应当建立建筑起重机械安全技术档案。 建筑起重机械安全技术档案应当包括以下资料： （一）购销合同、制造许可证、产品合格证、制造监督检验证明、安装使用说明书、备案证明等原始资料； （二）定期检验报告、定期自行检查记录、定期维护保养记录、维修和技术改造记录、运行故障和生产安全事故记录、累计运转记录等运行资料； （三）历次安装验收资料。"},{"i":10,"n":"第十条","txt":"从事建筑起重机械安装、拆卸活动的单位（以下简称安装单位）应当依法取得建设主管部门颁发的相应资质和建筑施工企业安全生产许可证，并在其资质许可范围内承揽建筑起重机械安装、拆卸工程。"},{"i":11,"n":"第十一条","txt":"建筑起重机械使用单位和安装单位应当在签订的建筑起重机械安装、拆卸合同中明确双方的安全生产责任。 实行施工总承包的，施工总承包单位应当与安装单位签订建筑起重机械安装、拆卸工程安全协议书。"},{"i":12,"n":"第十二条","txt":"安装单位应当履行下列安全职责： （一）按照安全技术标准及建筑起重机械性能要求，编制建筑起重机械安装、拆卸工程专项施工方案，并由本单位技术负责人签字； （二）按照安全技术标准及安装使用说明书等检查建筑起重机械及现场施工条件； （三）组织安全施工技术交底并签字确认； （四）制定建筑起重机械安装、拆卸工程生产安全事故应急救援预案； （五）将建筑起重机械安装、拆卸工程专项施工方案，安装、拆卸人员名单，安装、拆卸时间等材料报施工总承包单位和监理单位审核后，告知工程所在地县级以上地方人民政府建设主管部门。"},{"i":13,"n":"第十三条","txt":"安装单位应当按照建筑起重机械安装、拆卸工程专项施工方案及安全操作规程组织安装、拆卸作业。 安装单位的专业技术人员、专职安全生产管理人员应当进行现场监督，技术负责人应当定期巡查。"},{"i":14,"n":"第十四条","txt":"建筑起重机械安装完毕后，安装单位应当按照安全技术标准及安装使用说明书的有关要求对建筑起重机械进行自检、调试和试运转。自检合格的，应当出具自检合格证明，并向使用单位进行安全使用说明。"},{"i":15,"n":"第十五条","txt":"安装单位应当建立建筑起重机械安装、拆卸工程档案。 建筑起重机械安装、拆卸工程档案应当包括以下资料： （一）安装、拆卸合同及安全协议书； （二）安装、拆卸工程专项施工方案； （三）安全施工技术交底的有关资料； （四）安装工程验收资料； （五）安装、拆卸工程生产安全事故应急救援预案。"},{"i":16,"n":"第十六条","txt":"建筑起重机械安装完毕后，使用单位应当组织出租、安装、监理等有关单位进行验收，或者委托具有相应资质的检验检测机构进行验收。建筑起重机械经验收合格后方可投入使用，未经验收或者验收不合格的不得使用。 实行施工总承包的，由施工总承包单位组织验收。 建筑起重机械在验收前应当经有相应资质的检验检测机构监督检验合格。 检验检测机构和检验检测人员对检验检测结果、鉴定结论依法承担法律责任。"},{"i":17,"n":"第十七条","txt":"使用单位应当自建筑起重机械安装验收合格之日起30日内，将建筑起重机械安装验收资料、建筑起重机械安全管理制度、特种作业人员名单等，向工程所在地县级以上地方人民政府建设主管部门办理建筑起重机械使用登记。登记标志置于或者附着于该设备的显著位置。"},{"i":18,"n":"第十八条","txt":"使用单位应当履行下列安全职责： （一）根据不同施工阶段、周围环境以及季节、气候的变化，对建筑起重机械采取相应的安全防护措施； （二）制定建筑起重机械生产安全事故应急救援预案； （三）在建筑起重机械活动范围内设置明显的安全警示标志，对集中作业区做好安全防护； （四）设置相应的设备管理机构或者配备专职的设备管理人员； （五）指定专职设备管理人员、专职安全生产管理人员进行现场监督检查； （六）建筑起重机械出现故障或者发生异常情况的，立即停止使用，消除故障和事故隐患后，方可重新投入使用。"},{"i":19,"n":"第十九条","txt":"使用单位应当对在用的建筑起重机械及其安全保护装置、吊具、索具等进行经常性和定期的检查、维护和保养，并做好记录。 使用单位在建筑起重机械租期结束后，应当将定期检查、维护和保养记录移交出租单位。 建筑起重机械租赁合同对建筑起重机械的检查、维护、保养另有约定的，从其约定。"},{"i":20,"n":"第二十条","txt":"建筑起重机械在使用过程中需要附着的，使用单位应当委托原安装单位或者具有相应资质的安装单位按照专项施工方案实施，并按照本规定第十六条规定组织验收。验收合格后方可投入使用。 建筑起重机械在使用过程中需要顶升的，使用单位委托原安装单位或者具有相应资质的安装单位按照专项施工方案实施后，即可投入使用。 禁止擅自在建筑起重机械上安装非原制造厂制造的标准节和附着装置。"},{"i":21,"n":"第二十一条","txt":"施工总承包单位应当履行下列安全职责： （一）向安装单位提供拟安装设备位置的基础施工资料，确保建筑起重机械进场安装、拆卸所需的施工条件； （二）审核建筑起重机械的特种设备制造许可证、产品合格证、制造监督检验证明、备案证明等文件； （三）审核安装单位、使用单位的资质证书、安全生产许可证和特种作业人员的特种作业操作资格证书； （四）审核安装单位制定的建筑起重机械安装、拆卸工程专项施工方案和生产安全事故应急救援预案； （五）审核使用单位制定的建筑起重机械生产安全事故应急救援预案； （六）指定专职安全生产管理人员监督检查建筑起重机械安装、拆卸、使用情况； （七）施工现场有多台塔式起重机作业时，应当组织制定并实施防止塔式起重机相互碰撞的安全措施。"},{"i":22,"n":"第二十二条","txt":"监理单位应当履行下列安全职责： （一）审核建筑起重机械特种设备制造许可证、产品合格证、制造监督检验证明、备案证明等文件； （二）审核建筑起重机械安装单位、使用单位的资质证书、安全生产许可证和特种作业人员的特种作业操作资格证书； （三）审核建筑起重机械安装、拆卸工程专项施工方案； （四）监督安装单位执行建筑起重机械安装、拆卸工程专项施工方案情况； （五）监督检查建筑起重机械的使用情况； （六）发现存在生产安全事故隐患的，应当要求安装单位、使用单位限期整改，对安装单位、使用单位拒不整改的，及时向建设单位报告。"},{"i":23,"n":"第二十三条","txt":"依法发包给两个及两个以上施工单位的工程，不同施工单位在同一施工现场使用多台塔式起重机作业时，建设单位应当协调组织制定防止塔式起重机相互碰撞的安全措施。 安装单位、使用单位拒不整改生产安全事故隐患的，建设单位接到监理单位报告后，应当责令安装单位、使用单位立即停工整改。"},{"i":24,"n":"第二十四条","txt":"建筑起重机械特种作业人员应当遵守建筑起重机械安全操作规程和安全管理制度，在作业中有权拒绝违章指挥和强令冒险作业，有权在发生危及人身安全的紧急情况时立即停止作业或者采取必要的应急措施后撤离危险区域。"},{"i":25,"n":"第二十五条","txt":"建筑起重机械安装拆卸工、起重信号工、起重司机、司索工等特种作业人员应当经建设主管部门考核合格，并取得特种作业操作资格证书后，方可上岗作业。 省、自治区、直辖市人民政府建设主管部门负责组织实施建筑施工企业特种作业人员的考核。 特种作业人员的特种作业操作资格证书由国务院建设主管部门规定统一的样式。"},{"i":26,"n":"第二十六条","txt":"建设主管部门履行安全监督检查职责时，有权采取下列措施： （一）要求被检查的单位提供有关建筑起重机械的文件和资料； （二）进入被检查单位和被检查单位的施工现场进行检查； （三）对检查中发现的建筑起重机械生产安全事故隐患，责令立即排除；重大生产安全事故隐患排除前或者排除过程中无法保证安全的，责令从危险区域撤出作业人员或者暂时停止施工。"},{"i":27,"n":"第二十七条","txt":"负责办理备案或者登记的建设主管部门应当建立本行政区域内的建筑起重机械档案，按照有关规定对建筑起重机械进行统一编号，并定期向社会公布建筑起重机械的安全状况。"},{"i":28,"n":"第二十八条","txt":"违反本规定，出租单位、自购建筑起重机械的使用单位，有下列行为之一的，由县级以上地方人民政府建设主管部门责令限期改正，予以警告，并处以5000元以上1万元以下罚款： （一）未按照规定办理备案的； （二）未按照规定办理注销手续的； （三）未按照规定建立建筑起重机械安全技术档案的。"},{"i":29,"n":"第二十九条","txt":"违反本规定，安装单位有下列行为之一的，由县级以上地方人民政府建设主管部门责令限期改正，予以警告，并处以5000元以上3万元以下罚款： （一）未履行第十二条第（二）、（四）、（五）项安全职责的； （二）未按照规定建立建筑起重机械安装、拆卸工程档案的； （三）未按照建筑起重机械安装、拆卸工程专项施工方案及安全操作规程组织安装、拆卸作业的。"},{"i":30,"n":"第三十条","txt":"违反本规定，使用单位有下列行为之一的，由县级以上地方人民政府建设主管部门责令限期改正，予以警告，并处以5000元以上3万元以下罚款： （一）未履行第十八条第（一）、（二）、（四）、（六）项安全职责的； （二）未指定专职设备管理人员进行现场监督检查的； （三）擅自在建筑起重机械上安装非原制造厂制造的标准节和附着装置的。"},{"i":31,"n":"第三十一条","txt":"违反本规定，施工总承包单位未履行第二十一条第（一）、（三）、（四）、（五）、（七）项安全职责的，由县级以上地方人民政府建设主管部门责令限期改正，予以警告，并处以5000元以上3万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"违反本规定，监理单位未履行第二十二条第（一）、（二）、（四）、（五）项安全职责的，由县级以上地方人民政府建设主管部门责令限期改正，予以警告，并处以5000元以上3万元以下罚款。"},{"i":33,"n":"第三十三条","txt":"违反本规定，建设单位有下列行为之一的，由县级以上地方人民政府建设主管部门责令限期改正，予以警告，并处以5000元以上3万元以下罚款；逾期未改的，责令停止施工： （一）未按照规定协调组织制定防止多台塔式起重机相互碰撞的安全措施的； （二）接到监理单位报告后，未责令安装单位、使用单位立即停工整改的。"},{"i":34,"n":"第三十四条","txt":"违反本规定，建设主管部门的工作人员有下列行为之一的，依法给予处分；构成犯罪的，依法追究刑事责任： （一）发现违反本规定的违法行为不依法查处的； （二）发现在用的建筑起重机械存在严重生产安全事故隐患不依法处理的； （三）不依法履行监督管理职责的其他行为。"},{"i":35,"n":"第三十五条","txt":"本规定自2008年6月1日起施行。"}],"jianshegongchengkanchashejizizhiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对建设工程勘察、设计活动的监督管理，保证建设工程勘察、设计质量，根据《中华人民共和国行政许可法》、《中华人民共和国建筑法》、《建设工程质量管理条例》和《建设工程勘察设计管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内申请建设工程勘察、工程设计资质，实施对建设工程勘察、工程设计资质的监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"从事建设工程勘察、工程设计活动的企业，应当按照其拥有的资产、专业技术人员、技术装备和勘察设计业绩等条件申请资质，经审查合格，取得建设工程勘察、工程设计资质证书后，方可在资质许可的范围内从事建设工程勘察、工程设计活动。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责全国建设工程勘察、工程设计资质的统一监督管理。国务院铁路、交通、水利、信息产业、民航等有关部门配合国务院住房城乡建设主管部门实施相应行业的建设工程勘察、工程设计资质管理工作。 省、自治区、直辖市人民政府住房城乡建设主管部门负责本行政区域内建设工程勘察、工程设计资质的统一监督管理。省、自治区、直辖市人民政府交通、水利、信息产业等有关部门配合同级住房城乡建设主管部门实施本行政区域内相应行业的建设工程勘察、工程设计资质管理工作。"},{"i":5,"n":"第五条","txt":"工程勘察资质分为工程勘察综合资质、工程勘察专业资质、工程勘察劳务资质。 工程勘察综合资质只设甲级；工程勘察专业资质设甲级、乙级，根据工程性质和技术特点，部分专业可以设丙级；工程勘察劳务资质不分等级。 取得工程勘察综合资质的企业，可以承接各专业（海洋工程勘察除外）、各等级工程勘察业务；取得工程勘察专业资质的企业，可以承接相应等级相应专业的工程勘察业务；取得工程勘察劳务资质的企业，可以承接岩土工程治理、工程钻探、凿井等工程勘察劳务业务。"},{"i":6,"n":"第六条","txt":"工程设计资质分为工程设计综合资质、工程设计行业资质、工程设计专业资质和工程设计专项资质。 工程设计综合资质只设甲级；工程设计行业资质、工程设计专业资质、工程设计专项资质设甲级、乙级。 根据工程性质和技术特点，个别行业、专业、专项资质可以设丙级，建筑工程专业资质可以设丁级。 取得工程设计综合资质的企业，可以承接各行业、各等级的建设工程设计业务；取得工程设计行业资质的企业，可以承接相应行业相应等级的工程设计业务及本行业范围内同级别的相应专业、专项（设计施工一体化资质除外）工程设计业务；取得工程设计专业资质的企业，可以承接本专业相应等级的专业工程设计业务及同级别的相应专项工程设计业务（设计施工一体化资质除外）；取得工程设计专项资质的企业，可以承接本专项相应等级的专项工程设计业务。"},{"i":7,"n":"第七条","txt":"建设工程勘察、工程设计资质标准和各资质类别、级别企业承担工程的具体范围由国务院住房城乡建设主管部门商国务院有关部门制定。"},{"i":8,"n":"第八条","txt":"申请工程勘察甲级资质、工程设计甲级资质，以及涉及铁路、交通、水利、信息产业、民航等方面的工程设计乙级资质的，可以向企业工商注册所在地的省、自治区、直辖市人民政府住房城乡建设主管部门提交申请材料。 省、自治区、直辖市人民政府住房城乡建设主管部门收到申请材料后，应当在5日内将全部申请材料报审批部门。 国务院住房城乡建设主管部门在收到申请材料后，应当依法作出是否受理的决定，并出具凭证；申请材料不齐全或者不符合法定形式的，应当在5日内一次性告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。 国务院住房城乡建设主管部门应当自受理之日起20日内完成审查。自作出决定之日起10日内公告审批结果。其中，涉及铁路、交通、水利、信息产业、民航等方面的工程设计资质，由国务院住房城乡建设主管部门送国务院有关部门审核，国务院有关部门应当在15日内审核完毕，并将审核意见送国务院住房城乡建设主"},{"i":9,"n":"第九条","txt":"工程勘察乙级及以下资质、劳务资质、工程设计乙级（涉及铁路、交通、水利、信息产业、民航等方面的工程设计乙级资质除外）及以下资质许可由省、自治区、直辖市人民政府住房城乡建设主管部门实施。具体实施程序由省、自治区、直辖市人民政府住房城乡建设主管部门依法确定。 省、自治区、直辖市人民政府住房城乡建设主管部门应当自作出决定之日起30日内，将准予资质许可的决定报国务院住房城乡建设主管部门备案。"},{"i":10,"n":"第十条","txt":"工程勘察、工程设计资质证书分为正本和副本，正本一份，副本六份，由国务院住房城乡建设主管部门统一印制，正、副本具备同等法律效力。资质证书有效期为5年。"},{"i":11,"n":"第十一条","txt":"企业申请工程勘察、工程设计资质，应在资质许可机关的官方网站或审批平台上提出申请，提交资金、专业技术人员、技术装备和已完成的业绩等电子材料。"},{"i":12,"n":"第十二条","txt":"资质有效期届满，企业需要延续资质证书有效期的，应当在资质证书有效期届满60日前，向原资质许可机关提出资质延续申请。 对在资质有效期内遵守有关法律、法规、规章、技术标准，信用档案中无不良行为记录，且专业技术人员满足资质标准要求的企业，经资质许可机关同意，有效期延续5年。"},{"i":13,"n":"第十三条","txt":"企业在资质证书有效期内名称、地址、注册资本、法定代表人等发生变更的，应当在工商部门办理变更手续后30日内办理资质证书变更手续。 取得工程勘察甲级资质、工程设计甲级资质，以及涉及铁路、交通、水利、信息产业、民航等方面的工程设计乙级资质的企业，在资质证书有效期内发生企业名称变更的，应当向企业工商注册所在地省、自治区、直辖市人民政府住房城乡建设主管部门提出变更申请，省、自治区、直辖市人民政府住房城乡建设主管部门应当自受理申请之日起2日内将有关变更证明材料报国务院住房城乡建设主管部门，由国务院住房城乡建设主管部门在2日内办理变更手续。 前款规定以外的资质证书变更手续，由企业工商注册所在地的省、自治区、直辖市人民政府住房城乡建设主管部门负责办理。省、自治区、直辖市人民政府住房城乡建设主管部门应当自受理申请之日起2日内办理变更手续，并在办理资质证书变更手续后15日内将变更结果报国务院住房城乡建设主"},{"i":14,"n":"第十四条","txt":"企业申请资质证书变更，应当提交以下材料： （一）资质证书变更申请； （二）企业法人、合伙企业营业执照副本复印件； （三）资质证书正、副本原件； （四）与资质变更事项有关的证明材料。 企业改制的，除提供前款规定资料外，还应当提供改制重组方案、上级资产管理部门或者股东大会的批准决定、企业职工代表大会同意改制重组的决议。"},{"i":15,"n":"第十五条","txt":"企业首次申请、增项申请工程勘察、工程设计资质，其申请资质等级最高不超过乙级，且不考核企业工程勘察、工程设计业绩。 已具备施工资质的企业首次申请同类别或相近类别的工程勘察、工程设计资质的，可以将相应规模的工程总承包业绩作为工程业绩予以申报。其申请资质等级最高不超过其现有施工资质等级。"},{"i":16,"n":"第十六条","txt":"企业合并的，合并后存续或者新设立的企业可以承继合并前各方中较高的资质等级，但应当符合相应的资质标准条件。 企业分立的，分立后企业的资质按照资质标准及本规定的审批程序核定。 企业改制的，改制后不再符合资质标准的，应按其实际达到的资质标准及本规定重新核定；资质条件不发生变化的，按本规定第十六条办理。"},{"i":17,"n":"第十七条","txt":"从事建设工程勘察、设计活动的企业，申请资质升级、资质增项，在申请之日起前一年内有下列情形之一的，资质许可机关不予批准企业的资质升级申请和增项申请： （一）企业相互串通投标或者与招标人串通投标承揽工程勘察、工程设计业务的； （二）将承揽的工程勘察、工程设计业务转包或违法分包的； （三）注册执业人员未按照规定在勘察设计文件上签字的； （四）违反国家工程建设强制性标准的； （五）因勘察设计原因造成过重大生产安全事故的； （六）设计单位未根据勘察成果文件进行工程设计的； （七）设计单位违反规定指定建筑材料、建筑构配件的生产厂、供应商的； （八）无工程勘察、工程设计资质或者超越资质等级范围承揽工程勘察、工程设计业务的； （九）涂改、倒卖、出租、出借或者以其他形式非法转让资质证书的； （十）允许其他单位、个人以本单位名义承揽建设工程勘察、设计业务的； （十一）其他违反法律、法规行为的。"},{"i":18,"n":"第十八条","txt":"企业在领取新的工程勘察、工程设计资质证书的同时，应当将原资质证书交回原发证机关予以注销。 企业需增补（含增加、更换、遗失补办）工程勘察、工程设计资质证书的，应当持资质证书增补申请等材料向资质许可机关申请办理。遗失资质证书的，在申请补办前应当在公众媒体上刊登遗失声明。资质许可机关应当在2日内办理完毕。"},{"i":19,"n":"第十九条","txt":"国务院住房城乡建设主管部门对全国的建设工程勘察、设计资质实施统一的监督管理。国务院铁路、交通、水利、信息产业、民航等有关部门配合国务院住房城乡建设主管部门对相应的行业资质进行监督管理。 县级以上地方人民政府住房城乡建设主管部门负责对本行政区域内的建设工程勘察、设计资质实施监督管理。县级以上人民政府交通、水利、信息产业等有关部门配合同级住房城乡建设主管部门对相应的行业资质进行监督管理。 上级住房城乡建设主管部门应当加强对下级住房城乡建设主管部门资质管理工作的监督检查，及时纠正资质管理中的违法行为。"},{"i":20,"n":"第二十条","txt":"住房城乡建设主管部门、有关部门履行监督检查职责时，有权采取下列措施： （一）要求被检查单位提供工程勘察、设计资质证书、注册执业人员的注册执业证书，有关工程勘察、设计业务的文档，有关质量管理、安全生产管理、档案管理、财务管理等企业内部管理制度的文件； （二）进入被检查单位进行检查，查阅相关资料； （三）纠正违反有关法律、法规和本规定及有关规范和标准的行为。 住房城乡建设主管部门、有关部门依法对企业从事行政许可事项的活动进行监督检查时，应当将监督检查情况和处理结果予以记录，由监督检查人员签字后归档。"},{"i":21,"n":"第二十一条","txt":"住房城乡建设主管部门、有关部门在实施监督检查时，应当有两名以上监督检查人员参加，并出示执法证件，不得妨碍企业正常的生产经营活动，不得索取或者收受企业的财物，不得谋取其他利益。 有关单位和个人对依法进行的监督检查应当协助与配合，不得拒绝或者阻挠。 监督检查机关应当将监督检查的处理结果向社会公布。"},{"i":22,"n":"第二十二条","txt":"企业违法从事工程勘察、工程设计活动的，其违法行为发生地的住房城乡建设主管部门应当依法将企业的违法事实、处理结果或处理建议告知该企业的资质许可机关。"},{"i":23,"n":"第二十三条","txt":"企业取得工程勘察、设计资质后，不再符合相应资质条件的，住房城乡建设主管部门、有关部门根据利害关系人的请求或者依据职权，可以责令其限期改正；逾期不改的，资质许可机关可以撤回其资质。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，资质许可机关或者其上级机关，根据利害关系人的请求或者依据职权，可以撤销工程勘察、工程设计资质： （一）资质许可机关工作人员滥用职权、玩忽职守作出准予工程勘察、工程设计资质许可的； （二）超越法定职权作出准予工程勘察、工程设计资质许可； （三）违反资质审批程序作出准予工程勘察、工程设计资质许可的； （四）对不符合许可条件的申请人作出工程勘察、工程设计资质许可的； （五）依法可以撤销资质证书的其他情形。 以欺骗、贿赂等不正当手段取得工程勘察、工程设计资质证书的，应当予以撤销。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，企业应当及时向资质许可机关提出注销资质的申请，交回资质证书，资质许可机关应当办理注销手续，公告其资质证书作废： （一）资质证书有效期届满未依法申请延续的； （二）企业依法终止的； （三）资质证书依法被撤销、撤回，或者吊销的； （四）法律、法规规定的应当注销资质的其他情形。"},{"i":26,"n":"第二十六条","txt":"有关部门应当将监督检查情况和处理意见及时告知住房城乡建设主管部门。资质许可机关应当将涉及铁路、交通、水利、信息产业、民航等方面的资质被撤回、撤销和注销的情况及时告知有关部门。"},{"i":27,"n":"第二十七条","txt":"企业应当按照有关规定，向资质许可机关提供真实、准确、完整的企业信用档案信息。 企业的信用档案应当包括企业基本情况、业绩、工程质量和安全、合同违约等情况。被投诉举报和处理、行政处罚等情况应当作为不良行为记入其信用档案。 企业的信用档案信息按照有关规定向社会公示。"},{"i":28,"n":"第二十八条","txt":"企业隐瞒有关情况或者提供虚假材料申请资质的，资质许可机关不予受理或者不予行政许可，并给予警告，该企业在1年内不得再次申请该资质。"},{"i":29,"n":"第二十九条","txt":"企业以欺骗、贿赂等不正当手段取得资质证书的，由县级以上地方人民政府住房城乡建设主管部门或者有关部门给予警告，并依法处以罚款；该企业在3年内不得再次申请该资质。"},{"i":30,"n":"第三十条","txt":"企业不及时办理资质证书变更手续的，由资质许可机关责令限期办理；逾期不办理的，可处以1000元以上1万元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"企业未按照规定提供信用档案信息的，由县级以上地方人民政府住房城乡建设主管部门给予警告，责令限期改正；逾期未改正的，可处以1000元以上1万元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"涂改、倒卖、出租、出借或者以其他形式非法转让资质证书的，由县级以上地方人民政府住房城乡建设主管部门或者有关部门给予警告，责令改正，并处以1万元以上3万元以下的罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"县级以上地方人民政府住房城乡建设主管部门依法给予工程勘察、设计企业行政处罚的，应当将行政处罚决定以及给予行政处罚的事实、理由和依据，报国务院住房城乡建设主管部门备案。"},{"i":34,"n":"第三十四条","txt":"住房城乡建设主管部门及其工作人员，违反本规定，有下列情形之一的，由其上级行政机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予行政处分： （一）对不符合条件的申请人准予工程勘察、设计资质许可的； （二）对符合条件的申请人不予工程勘察、设计资质许可或者未在法定期限内作出许可决定的； （三）对符合条件的申请不予受理或者未在法定期限内初审完毕的； （四）利用职务上的便利，收受他人财物或者其他好处的； （五）不依法履行监督职责或者监督不力，造成严重后果的。"},{"i":35,"n":"第三十五条","txt":"本规定所称建设工程勘察包括建设工程项目的岩土工程、水文地质、工程测量、海洋工程勘察等。"},{"i":36,"n":"第三十六条","txt":"本规定所称建设工程设计是指： （一）建设工程项目的主体工程和配套工程（含厂（矿）区内的自备电站、道路、专用铁路、通信、各种管网管线和配套的建筑物等全部配套工程）以及与主体工程、配套工程相关的工艺、土木、建筑、环境保护、水土保持、消防、安全、卫生、节能、防雷、抗震、照明工程等的设计。 （二）建筑工程建设用地规划许可证范围内的室外工程设计、建筑物构筑物设计、民用建筑修建的地下工程设计及住宅小区、工厂厂前区、工厂生活区、小区规划设计及单体设计等，以及上述建筑工程所包含的相关专业的设计内容（包括总平面布置、竖向设计、各类管网管线设计、景观设计、室内外环境设计及建筑装饰、道路、消防、安保、通信、防雷、人防、供配电、照明、废水治理、空调设施、抗震加固等）。"},{"i":37,"n":"第三十七条","txt":"取得工程勘察、工程设计资质证书的企业，可以从事资质证书许可范围内相应的建设工程总承包业务，可以从事工程项目管理和相关的技术与管理服务。"},{"i":38,"n":"第三十八条","txt":"本规定自2007年9月1日起实施。2001年7月25日建设部颁布的《建设工程勘察设计企业资质管理规定》（建设部令第93号）同时废止。"}],"jianshegongchengkanchazhiliangguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对建设工程勘察质量的管理，保证建设工程质量，根据《中华人民共和国建筑法》、《建设工程质量管理条例》、《建设工程勘察设计管理条例》等有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"凡在中华人民共和国境内从事建设工程勘察活动的，必须遵守本办法。 本办法所称建设工程勘察，是指根据建设工程的要求，查明、分析、评价建设场地的地质地理环境特征和岩土工程条件，编制建设工程勘察文件的活动。"},{"i":3,"n":"第三条","txt":"工程勘察企业应当按照有关建设工程质量的法律、法规、工程建设强制性标准和勘察合同进行勘察工作，并对勘察质量负责。 勘察文件应当符合国家规定的勘察深度要求，必须真实、准确。"},{"i":4,"n":"第四条","txt":"国务院住房和城乡建设主管部门对全国的建设工程勘察质量实施统一监督管理。 国务院铁路、交通、水利等有关部门按照国务院规定的职责分工，负责对全国的有关专业建设工程勘察质量的监督管理。 县级以上地方人民政府住房和城乡建设主管部门对本行政区域内的建设工程勘察质量实施监督管理。 县级以上地方人民政府有关部门在各自的职责范围内，负责对本行政区域内的有关专业建设工程勘察质量的监督管理。"},{"i":5,"n":"第五条","txt":"建设单位应当为勘察工作提供必要的现场工作条件，保证合理的勘察工期，提供真实、可靠的原始资料。 建设单位应当加强履约管理，及时足额支付勘察费用，不得迫使工程勘察企业以低于成本的价格承揽任务。 建设单位应当依法将工程勘察文件送施工图审查机构审查。建设单位应当验收勘察报告，组织勘察技术交底和验槽。 建设单位项目负责人应当按照有关规定履行代表建设单位进行勘察质量管理的职责。"},{"i":6,"n":"第六条","txt":"工程勘察企业必须依法取得工程勘察资质证书，并在资质等级许可的范围内承揽勘察业务。 工程勘察企业不得超越其资质等级许可的业务范围或者以其他勘察企业的名义承揽勘察业务；不得允许其他企业或者个人以本企业的名义承揽勘察业务；不得转包或者违法分包所承揽的勘察业务。"},{"i":7,"n":"第七条","txt":"工程勘察企业应当健全勘察质量管理体系和质量责任制度，建立勘察现场工作质量责任可追溯制度。 工程勘察企业将勘探、试验、测试等技术服务工作交由具备相应技术条件的其他单位承担的，工程勘察企业对相关勘探、试验、测试工作成果质量全面负责。"},{"i":8,"n":"第八条","txt":"工程勘察企业应当拒绝用户提出的违反国家有关规定的不合理要求，有权提出保证工程勘察质量所必需的现场工作条件和合理工期。"},{"i":9,"n":"第九条","txt":"工程勘察企业应当向设计、施工和监理等单位进行勘察技术交底，参与施工验槽，及时解决工程设计和施工中与勘察工作有关的问题，按规定参加工程竣工验收。"},{"i":10,"n":"第十条","txt":"工程勘察企业应当参与建设工程质量事故的分析，并对因勘察原因造成的质量事故，提出相应的技术处理方案。"},{"i":11,"n":"第十一条","txt":"工程勘察项目负责人、审核人、审定人及有关技术人员应当具有相应的技术职称或者注册资格。"},{"i":12,"n":"第十二条","txt":"工程勘察企业法定代表人应当建立健全并落实本单位质量管理制度，授权具备相应资格的人员担任项目负责人。 工程勘察企业项目负责人应当签署质量终身责任承诺书，执行勘察纲要和工程建设强制性标准，落实本单位勘察质量管理制度，制定项目质量保证措施，组织开展工程勘察各项工作。"},{"i":13,"n":"第十三条","txt":"工程勘察企业的法定代表人、项目负责人、审核人、审定人等相关人员，应当在勘察文件上签字或者盖章，并对勘察质量负责。 工程勘察企业法定代表人对本企业勘察质量全面负责；项目负责人对项目的勘察文件负主要质量责任；项目审核人、审定人对其审核、审定项目的勘察文件负审核、审定的质量责任。"},{"i":14,"n":"第十四条","txt":"工程勘察工作的原始记录应当在勘察过程中及时整理、核对，确保取样、记录的真实和准确，禁止原始记录弄虚作假。钻探、取样、原位测试、室内试验等主要过程的影像资料应当留存备查。 司钻员、描述员、土工试验员等作业人员应当在原始记录上签字。工程勘察企业项目负责人应当对原始记录进行验收并签字。 鼓励工程勘察企业采用信息化手段，实时采集、记录、存储工程勘察数据。"},{"i":15,"n":"第十五条","txt":"工程勘察企业应当确保仪器、设备的完好。钻探、取样的机具设备、原位测试、室内试验及测量仪器等应当符合有关规范、规程的要求。"},{"i":16,"n":"第十六条","txt":"工程勘察企业应当加强职工技术培训和职业道德教育，提高勘察人员的质量责任意识。司钻员、描述员、土工试验员等人员应当按照有关规定接受安全生产、职业道德、理论知识和操作技能等方面的专业培训。"},{"i":17,"n":"第十七条","txt":"工程勘察企业应当建立工程勘察档案管理制度。工程勘察企业应当在勘察报告提交建设单位后20日内将工程勘察文件和勘探、试验、测试原始记录及成果、质量安全管理记录归档保存。归档资料应当经项目负责人签字确认，保存期限应当不少于工程的设计使用年限。 国家鼓励工程勘察企业推进传统载体档案数字化。电子档案与传统载体档案具有同等效力。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府住房和城乡建设主管部门或者其他有关部门（以下简称工程勘察质量监督部门）应当通过“双随机、一公开”方式开展工程勘察质量监管，检查及处理结果及时向社会公开。 工程勘察质量监督部门可以通过政府购买技术服务方式，聘请具有专业技术能力的单位和人员对工程勘察质量进行检查，所需费用向本级财政申请予以保障。 工程勘察质量监督部门应当运用互联网等信息化手段开展工程勘察质量监管，提升监管的精准化、智能化水平。"},{"i":19,"n":"第十九条","txt":"工程勘察发生重大质量、安全事故时，有关单位应当按照规定向工程勘察质量监督部门报告。"},{"i":20,"n":"第二十条","txt":"任何单位和个人有权向工程勘察质量监督部门检举、投诉工程勘察质量、安全问题。"},{"i":21,"n":"第二十一条","txt":"工程勘察企业违反《建设工程勘察设计管理条例》、《建设工程质量管理条例》的，由工程勘察质量监督部门按照有关规定给予处罚。"},{"i":22,"n":"第二十二条","txt":"违反本办法规定，建设单位有下列行为之一的，由工程勘察质量监督部门责令改正，处1万元以上3万元以下的罚款： （一）未提供必要的现场工作条件； （二）未提供与工程勘察有关的原始资料或者提供的原始资料不真实、不可靠； （三）未组织勘察技术交底； （四）未组织验槽。"},{"i":23,"n":"第二十三条","txt":"违反本办法规定，工程勘察企业未按照工程建设强制性标准进行勘察、弄虚作假、提供虚假成果资料的，由工程勘察质量监督部门责令改正，处10万元以上30万元以下的罚款；造成工程质量事故的，责令停业整顿，降低资质等级；情节严重的，吊销资质证书；造成损失的，依法承担赔偿责任。"},{"i":24,"n":"第二十四条","txt":"违反本办法规定，工程勘察企业有下列行为之一的，由工程勘察质量监督部门责令改正，处1万元以上3万元以下的罚款： （一）使用的勘察仪器、设备不满足相关规定； （二）司钻员、描述员、土工试验员等关键岗位作业人员未接受专业培训； （三）未按规定参加建设单位组织的勘察技术交底或者验槽； （四）原始记录弄虚作假； （五）未将钻探、取样、原位测试、室内试验等主要过程的影像资料留存备查； （六）未按规定及时将工程勘察文件和勘探、试验、测试原始记录及成果、质量安全管理记录归档保存。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，工程勘察企业法定代表人有下列行为之一的，由工程勘察质量监督部门责令改正，处1万元以上3万元以下的罚款： （一）未建立或者落实本单位勘察质量管理制度； （二）授权不具备相应资格的项目负责人开展勘察工作； （三）未按规定在工程勘察文件上签字或者盖章。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，工程勘察企业项目负责人有下列行为之一的，由工程勘察质量监督部门责令改正，处1万元以上3万元以下的罚款： （一）未执行勘察纲要和工程建设强制性标准； （二）未落实本单位勘察质量管理制度，未制定项目质量保证措施； （三）未按规定在工程勘察文件上签字； （四）未对原始记录进行验收并签字； （五）未对归档资料签字确认。"},{"i":27,"n":"第二十七条","txt":"依照本办法规定，给予建设单位、勘察企业罚款处罚的，由工程勘察质量监督部门对建设单位、勘察企业的法定代表人和其他直接责任人员处以企业罚款数额的5%以上10%以下的罚款。"},{"i":28,"n":"第二十八条","txt":"国家机关工作人员在建设工程勘察质量监督管理工作中玩忽职守、滥用职权、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"本办法自2003年2月1日起施行。"}],"jianshegongchengjianlifanweiheguimobiaozhunguiding":[{"i":1,"n":"第一条","txt":"为了确定必须实行监理的建设工程项目具体范围和规模标准，规范建设工程监理活动，根据《建设工程质量管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"下列建设工程必须实行监理： （一）国家重点建设工程； （二）大中型公用事业工程； （三）成片开发建设的住宅小区工程； （四）利用外国政府或者国际组织贷款、援助资金的工程； （五）国家规定必须实行监理的其他工程。"},{"i":3,"n":"第三条","txt":"国家重点建设工程，是指依据《国家重点建设项目管理办法》所确定的对国民经济和社会发展有重大影响的骨干项目。"},{"i":4,"n":"第四条","txt":"大中型公用事业工程，是指项目总投资额在3000万元以上的下列工程项目： （一）供水、供电、供气、供热等市政工程项目； （二）科技、教育、文化等项目； （三）体育、旅游、商业等项目； （四）卫生、社会福利等项目； （五）其他公用事业项目。"},{"i":5,"n":"第五条","txt":"成片开发建设的住宅小区工程，建筑面积在5万平方米以上的住宅建设工程必须实行监理；5万平方米以下的住宅建设工程，可以实行监理，具体范围和规模标准，由省、自治区、直辖市人民政府建设行政主管部门规定。 为了保证住宅质量，对高层住宅及地基、结构复杂的多层住宅应当实行监理。"},{"i":6,"n":"第六条","txt":"利用外国政府或者国际组织贷款、援助资金的工程范围包括： （一）使用世界银行、亚洲开发银行等国际组织贷款资金的项目； （二）使用国外政府及其机构贷款资金的项目； （三）使用国际组织或者国外政府援助资金的项目。 第七条国家规定必须实行监理的其他工程是指： （一）项目总投资额在3000万元以上关系社会公共利益、公众安全的下列基础设施项目： （1）煤炭、石油、化工、天然气、电力、新能源等项目； （2）铁路、公路、管道、水运、民航以及其他交通运输业等项目； （3）邮政、电信枢纽、通信、信息网络等项目； （4）防洪、灌溉、排涝、发电、引（供）水、滩涂治理、水资源保护、水土保持等水利建设项目； （5）道路、桥梁、地铁和轻轨交通、污水排放及处理、垃圾处理、地下管道、公共停车场等城市基础设施项目； （6）生态环境保护项目； （7）其他基础设施项目。 （二）学校、影剧院、体育场馆项目。"},{"i":7,"n":"第八条","txt":"国务院建设行政主管部门商同国务院有关部门后，可以对本规定确定的必须实行监理的建设工程具体范围和规模标准进行调整。"},{"i":8,"n":"第九条","txt":"本规定由国务院建设行政主管部门负责解释。"},{"i":9,"n":"第十条","txt":"本规定自发布之日起施行。"}],"jianshebuguanyunaruguowuyuanjuedingdeshiwuxiangxind9464a":[],"jianshelingyutuiguangyingyongxinjishuguanliguiding":[{"i":1,"n":"第一条","txt":"为了促进建设科技成果推广转化，调整产业、产品结构，推动产业技术升级，提高建设工程质量，节约资源，保护和改善环境，根据《中华人民共和国促进科技成果转化法》、《建设工程质量管理条例》和有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在建设领域推广应用新技术和限制、禁止使用落后技术的活动，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称的新技术，是指经过鉴定、评估的先进、成熟、适用的技术、材料、工艺、产品。 本规定所称限制、禁止使用的落后技术，是指已无法满足工程建设、城市建设、村镇建设等领域的使用要求，阻碍技术进步与行业发展，且已有替代技术，需要对其应用范围加以限制或者禁止使用的技术、材料、工艺和产品。"},{"i":4,"n":"第四条","txt":"推广应用新技术和限制、禁止使用落后技术应当遵循有利于可持续发展、有利于行业科技进步和科技成果产业化、有利于产业技术升级以及有利于提高经济效益、社会效益和环境效益的原则。 推广应用新技术应当遵循自愿、互利、公平、诚实信用原则，依法或者依照合同的约定，享受利益，承担风险。"},{"i":5,"n":"第五条","txt":"国务院建设行政主管部门负责管理全国建设领域推广应用新技术和限制、禁止使用落后技术工作。 县级以上地方人民政府建设行政主管部门负责管理本行政区域内建设领域推广应用新技术和限制、禁止使用落后技术工作。"},{"i":6,"n":"第六条","txt":"推广应用新技术和限制、禁止使用落后技术的发布采取以下方式： （一）《建设部重点实施技术》（以下简称《重点实施技术》）。由国务院建设行政主管部门根据产业优化升级的要求，选择技术成熟可靠，使用范围广，对建设行业技术进步有显著促进作用，需重点组织技术推广的技术领域，定期发布。 《重点实施技术》主要发布需重点组织技术推广的技术领域名称。 （二）《推广应用新技术和限制、禁止使用落后技术公告》（以下简称《技术公告》）。根据《重点实施技术》确定的技术领域和行业发展的需要，由国务院建设行政主管部门和省、自治区、直辖市人民政府建设行政主管部门分别组织编制，定期发布。 《技术公告》主要发布推广应用和限制、禁止使用的技术类别、主要技术指标和适用范围。 限制和禁止使用落后技术的内容，涉及国家发布的工程建设强制性标准的，应由国务院建设行政主管部门发布。 （三）《科技成果推广项目》（以下简称《推广项目》）。根据《"},{"i":7,"n":"第七条","txt":"国务院建设行政主管部门发布的《重点实施技术》、《技术公告》和《推广项目》适用于全国或者规定的范围；省、自治区、直辖市人民政府建设行政主管部门发布的《技术公告》和《推广项目》适用于本行政区域或者本行政区域内规定的范围。"},{"i":8,"n":"第八条","txt":"发布《技术公告》的建设行政主管部门，对于限制或者禁止使用的落后技术，应当及时修订有关的标准、定额，组织修编相应的标准图和相关计算机软件等，对该类技术及相关工作实施规范化管理。"},{"i":9,"n":"第九条","txt":"国务院建设行政主管部门和省、自治区、直辖市人民政府建设行政主管部门应当制定推广应用新技术的政策措施和规划，组织重点实施技术示范工程，制定相应的标准规范，建立新技术产业化基地，培育建设技术市场，促进新技术的推广应用。"},{"i":10,"n":"第十条","txt":"国家鼓励使用《推广项目》中的新技术，保护和支持各种合法形式的新技术推广应用活动。"},{"i":11,"n":"第十一条","txt":"市、县人民政府建设行政主管部门应当制定相应的政策措施，选择适宜的工程项目，协助或者组织实施建设部和省、自治区、直辖市人民政府建设行政主管部门重点实施技术示范工程。 重点实施技术示范工程选用的新技术应当是《推广项目》发布的推广技术。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府建设行政主管部门应当积极鼓励和扶持建设科技中介服务机构从事新技术推广应用工作，充分发挥行业协会、学会的作用，开展新技术推广应用工作。"},{"i":13,"n":"第十三条","txt":"城市规划、公用事业、工程勘察、工程设计、建筑施工、工程监理和房地产开发等单位，应当积极采用和支持应用发布的新技术，其应用新技术的业绩应当作为衡量企业技术进步的重要内容。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府建设行政主管部门，应当确定相应的机构和人员，负责新技术的推广应用、限制和禁止使用落后技术工作。"},{"i":15,"n":"第十五条","txt":"从事新技术推广应用的有关人员应当具有一定的专业知识，或者接受相应的专业技术培训，掌握相关的知识和技能，具有较丰富的工程实践经验。"},{"i":16,"n":"第十六条","txt":"对在推广应用新技术工作中作出突出贡献的单位和个人，其主管部门应当予以奖励。"},{"i":17,"n":"第十七条","txt":"新技术的技术依托单位在推广应用过程中，应当提供配套的技术文件，采取有效措施做好技术服务，并在合同中约定质量指标。"},{"i":18,"n":"第十八条","txt":"任何单位和个人不得超越范围应用限制使用的技术，不得应用禁止使用的技术。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府建设行政主管部门应当加强对有关单位执行《技术公告》的监督管理，对明令限制或者禁止使用的内容，应当采取有效措施限制或者禁止使用。"},{"i":20,"n":"第二十条","txt":"违反本规定应用限制或者禁止使用的落后技术并违反工程建设强制性标准的，依据《建设工程质量管理条例》进行处罚。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市人民政府建设行政主管部门可以依据本规定制定实施细则。"},{"i":22,"n":"第二十二条","txt":"本规定由国务院建设行政主管部门负责解释。"},{"i":23,"n":"第二十三条","txt":"本规定自发布之日起施行。"}],"fangchancehuiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强房产测绘管理，规范房产测绘行为，保护房屋权利人的合法权益，根据《中华人民共和国测绘法》和《中华人民共和国城市房地产管理法》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事房产测绘活动，实施房产测绘管理，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"房产测绘单位应当严格遵守国家有关法律、法规，执行国家房产测量规范和有关技术标准、规定，对其完成的房产测绘成果质量负责。 房产测绘单位应当采用先进技术和设备，提高测绘技术水平，接受房地产行政主管部门和测绘行政主管部门的技术指导和业务监督。"},{"i":4,"n":"第四条","txt":"房产测绘从业人员应当保证测绘成果的完整、准确，不得违规测绘、弄虚作假，不得损害国家利益、社会公共利益和他人合法权益。"},{"i":5,"n":"第五条","txt":"国务院测绘行政主管部门和国务院建设行政主管部门根据国务院确定的职责分工负责房产测绘及成果应用的监督管理。 省、自治区、直辖市人民政府测绘行政主管部门（以下简称省级测绘行政主管部门）和省、自治区人民政府建设行政主管部门、直辖市人民政府房地产行政主管部门（以下简称省级房地产行政主管部门）根据省、自治区、直辖市人民政府确定的职责分工负责房产测绘及成果应用的监督管理。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，房屋权利申请人、房屋权利人或者其他利害关系人应当委托房产测绘单位进行房产测绘： （一）申请产权初始登记的房屋； （二）自然状况发生变化的房屋； （三）房屋权利人或者其他利害关系人要求测绘的房屋。 房产管理中需要的房产测绘，由房地产行政主管部门委托房产测绘单位进行。"},{"i":7,"n":"第七条","txt":"房产测绘成果资料应当与房产自然状况保持一致。房产自然状况发生变化时，应当及时实施房产变更测量。"},{"i":8,"n":"第八条","txt":"委托房产测绘的，委托人与房产测绘单位应当签订书面房产测绘合同。"},{"i":9,"n":"第九条","txt":"房产测绘单位应当是独立的经济实体，与委托人不得有利害关系。"},{"i":10,"n":"第十条","txt":"房产测绘所需费用由委托人支付。 房产测绘收费标准按照国家有关规定执行。"},{"i":11,"n":"第十一条","txt":"国家实行房产测绘单位资格审查认证制度。"},{"i":12,"n":"第十二条","txt":"房产测绘单位应当依照《中华人民共和国测绘法》和本办法的规定，取得省级以上人民政府测绘行政主管部门颁发的载明房产测绘业务的《测绘资格证书》。"},{"i":13,"n":"第十三条","txt":"除本办法另有规定外、房产测绘资格审查、分级标准、作业限额、年度检验等按照国家有关规定执行。"},{"i":14,"n":"第十四条","txt":"申请房产测绘资格的单位应当向所在地省级测绘行政主管部门提出书面申请，并按照测绘资格审查管理的要求提交有关材料。 省级测绘行政主管部门在决定受理之日起5日内，转省级房地产行政主管部门初审。省级房地产行政主管部门应当在15日内，提出书面初审意见，并反馈省级测绘行政主管部门；其中，对申请甲级房产测绘资格的初审意见应当同时报国务院建设行政主管部门备案。 申请甲级房产测绘资格的，由省级测绘行政主管部门报国务院测绘行政主管部门审批发证；申请乙级以下房产测绘资格的，由省级测绘行政主管部门审批发证。 取得甲级房产测绘资格的单位，由国务院测绘行政主管部门和国务院建设行政主管部门联合向社会公告。取得乙级以下房产测绘资格的单位，由省级测绘行政主管部门和省级房地产行政主管部门联合向社会公告。"},{"i":15,"n":"第十五条","txt":"《测绘资格证书》有效期为5年，期满3个月前，由持证单位提请复审，发证机关负责审查和换证。对有房产测绘项目的，发证机关在审查和换证时，应当征求同级房地产行政主管部门的意见。 在《测绘资格证书》有效期内，房产测绘资格由测绘行政主管部门进行年检。年检时，测绘行政主管部门应当征求同级房地产行政主管部门的意见。对年检中被降级或者取消房产测绘资格的单位，由年检的测绘行政主管部门和同级房地产行政主管部门联合向社会公告。 在《测绘资格证书》有效期内申请房产测绘资格升级的，依照本办法第十四条的规定重新办理资格审查手续。"},{"i":16,"n":"第十六条","txt":"房产测绘成果包括：房产簿册、房产数据和房产图集等。"},{"i":17,"n":"第十七条","txt":"当事人对房产测绘成果有异议的，可以委托国家认定的房产测绘成果鉴定机构鉴定。"},{"i":18,"n":"第十八条","txt":"用于房屋权属登记等房产管理的房产测绘成果，房地产行政主管部门应当对施测单位的资格、测绘成果的适用性、界址点准确性、面积测算依据与方法等内容进行审核。审核后的房产测绘成果纳入房产档案统一管理。"},{"i":19,"n":"第十九条","txt":"向国（境）外团体和个人提供、赠送、出售未公开的房产测绘成果资料，委托国（境）外机构印制房产测绘图件，应当按照《中华人民共和国测绘法》和《中华人民共和国测绘成果管理规定》以及国家安全、保密等有关规定办理。"},{"i":20,"n":"第二十条","txt":"未取得载明房产测绘业务的《测绘资格证书》从事房产测绘业务以及承担房产测绘任务超出《测绘资格证书》所规定的房产测绘业务范围、作业限额的，依照《中华人民共和国测绘法》和《测绘资格审查认证管理规定》的规定处罚。"},{"i":21,"n":"第二十一条","txt":"房产测绘单位有下列情形之一的，由县级以上人民政府房地产行政主管部门给予警告并责令限期改正，并可处以1万元以上3万元以下的罚款；情节严重的，由发证机关予以降级或者取消其房产测绘资格： （一）在房产面积测算中不执行国家标准、规范和规定的； （二）在房产面积测算中弄虚作假、欺骗房屋权利人的； （三）房产面积测算失误，造成重大损失的。"},{"i":22,"n":"第二十二条","txt":"违反本办法第十九条规定的，根据《中华人民共和国测绘法》、《中华人民共和国测绘成果管理规定》及国家安全、保密法律法规的规定处理。"},{"i":23,"n":"第二十三条","txt":"房产测绘管理人员、工作人员在工作中玩忽职守、滥用职权、徇私舞弊的，给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"省级房地产行政主管部门和测绘行政主管部门可以根据本办法制定实施细则。"},{"i":25,"n":"第二十五条","txt":"本办法由国务院建设行政主管部门和国务院测绘行政主管部门共同解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2001年5月1日起施行。"}],"fangdichangujiajigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范房地产估价机构行为，维护房地产估价市场秩序，保障房地产估价活动当事人合法权益，根据《中华人民共和国城市房地产管理法》、《中华人民共和国行政许可法》和《国务院对确需保留的行政审批项目设定行政许可的决定》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内申请房地产估价机构资质，从事房地产估价活动，对房地产估价机构实施监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称房地产估价机构，是指依法设立并取得房地产估价机构资质，从事房地产估价活动的中介服务机构。 本办法所称房地产估价活动，包括土地、建筑物、构筑物、在建工程、以房地产为主的企业整体资产、企业整体资产中的房地产等各类房地产评估，以及因转让、抵押、房屋征收、司法鉴定、课税、公司上市、企业改制、企业清算、资产重组、资产处置等需要进行的房地产评估。"},{"i":4,"n":"第四条","txt":"房地产估价机构从事房地产估价活动，应当坚持独立、客观、公正的原则，执行房地产估价规范和标准。 房地产估价机构依法从事房地产估价活动，不受行政区域、行业限制。任何组织或者个人不得非法干预房地产估价活动和估价结果。"},{"i":5,"n":"第五条","txt":"国务院住房城乡建设主管部门负责全国房地产估价机构的监督管理工作。 省、自治区人民政府住房城乡建设主管部门、直辖市人民政府房地产主管部门负责本行政区域内房地产估价机构的监督管理工作。 市、县人民政府房地产主管部门负责本行政区域内房地产估价机构的监督管理工作。"},{"i":6,"n":"第六条","txt":"房地产估价行业组织应当加强房地产估价行业自律管理。 鼓励房地产估价机构加入房地产估价行业组织。"},{"i":7,"n":"第七条","txt":"国家建立全国统一的房地产估价行业管理信息平台，实现房地产估价机构资质核准、人员注册、信用档案管理等信息关联共享。"},{"i":8,"n":"第八条","txt":"房地产估价机构资质等级分为一、二、三级。 省、自治区人民政府住房城乡建设主管部门、直辖市人民政府房地产主管部门负责房地产估价机构资质许可。 省、自治区人民政府住房城乡建设主管部门、直辖市人民政府房地产主管部门应当执行国家统一的资质许可条件，加强房地产估价机构资质许可管理，营造公平竞争的市场环境。 国务院住房城乡建设主管部门应当加强对省、自治区人民政府住房城乡建设主管部门、直辖市人民政府房地产主管部门资质许可工作的指导和监督检查，及时纠正资质许可中的违法行为。"},{"i":9,"n":"第九条","txt":"房地产估价机构应当由自然人出资，以有限责任公司或者合伙企业形式设立。"},{"i":10,"n":"第十条","txt":"各资质等级房地产估价机构的条件如下： （一）一级资质 1.机构名称有房地产估价或者房地产评估字样； 2.从事房地产估价活动连续6年以上，且取得二级房地产估价机构资质3年以上； 3.有15名以上专职注册房地产估价师； 4.在申请核定资质等级之日前3年平均每年完成估价标的物建筑面积50万平方米以上或者土地面积25万平方米以上； 5.法定代表人或者执行合伙人是注册后从事房地产估价工作3年以上的专职注册房地产估价师； 6.有限责任公司的股东中有3名以上、合伙企业的合伙人中有2名以上专职注册房地产估价师，股东或者合伙人中有一半以上是注册后从事房地产估价工作3年以上的专职注册房地产估价师； 7.有限责任公司的股份或者合伙企业的出资额中专职注册房地产估价师的股份或者出资额合计不低于60％； 8.有固定的经营服务场所； 9.估价质量管理、估价档案管理、财务管理等各项企业内部管理制度健全； 10.随机抽"},{"i":11,"n":"第十一条","txt":"申请核定房地产估价机构资质等级，应当如实向资质许可机关提交下列材料： （一）房地产估价机构资质等级申请表（一式二份，加盖申报机构公章）； （二）房地产估价机构原资质证书正本复印件、副本原件； （三）营业执照正、副本复印件（加盖申报机构公章）； （四）法定代表人或者执行合伙人的任职文件复印件（加盖申报机构公章）； （五）专职注册房地产估价师证明； （六）固定经营服务场所的证明； （七）经工商行政管理部门备案的公司章程或者合伙协议复印件（加盖申报机构公章）及有关估价质量管理、估价档案管理、财务管理等企业内部管理制度的文件、申报机构信用档案信息； （八）随机抽查的在申请核定资质等级之日前3年内申报机构所完成的1份房地产估价报告复印件（一式二份，加盖申报机构公章）。 申请人应当对其提交的申请材料实质内容的真实性负责。"},{"i":12,"n":"第十二条","txt":"新设立的中介服务机构申请房地产估价机构资质的，应当提供第十一条第（一）项、第（三）项至第（八）项材料。 新设立中介服务机构的房地产估价机构资质等级应当核定为三级资质，设1年的暂定期。"},{"i":13,"n":"第十三条","txt":"房地产估价机构资质核准中的房地产估价报告抽查，应当执行全国统一的标准。"},{"i":14,"n":"第十四条","txt":"申请核定房地产估价机构资质的，应当向设区的市人民政府房地产主管部门提出申请，并提交本办法第十一条规定的材料。 设区的市人民政府房地产主管部门应当自受理申请之日起20日内审查完毕，并将初审意见和全部申请材料报省、自治区人民政府住房城乡建设主管部门、直辖市人民政府房地产主管部门。 省、自治区人民政府住房城乡建设主管部门、直辖市人民政府房地产主管部门应当自受理申请材料之日起20日内作出决定。 省、自治区人民政府住房城乡建设主管部门、直辖市人民政府房地产主管部门应当在作出资质许可决定之日起10日内，将准予资质许可的决定报国务院住房城乡建设主管部门备案。"},{"i":15,"n":"第十五条","txt":"房地产估价机构资质证书分为正本和副本，由国务院住房城乡建设主管部门统一印制，正、副本具有同等法律效力。 房地产估价机构遗失资质证书的，应当在公众媒体上声明作废后，申请补办。"},{"i":16,"n":"第十六条","txt":"房地产估价机构资质有效期为3年。 资质有效期届满，房地产估价机构需要继续从事房地产估价活动的，应当在资质有效期届满30日前向资质许可机关提出资质延续申请。资质许可机关应当根据申请作出是否准予延续的决定。准予延续的，有效期延续3年。 在资质有效期内遵守有关房地产估价的法律、法规、规章、技术标准和职业道德的房地产估价机构，经原资质许可机关同意，不再审查，有效期延续3年。"},{"i":17,"n":"第十七条","txt":"房地产估价机构的名称、法定代表人或者执行合伙人、组织形式、住所等事项发生变更的，应当在工商行政管理部门办理变更手续后30日内，到资质许可机关办理资质证书变更手续。"},{"i":18,"n":"第十八条","txt":"房地产估价机构合并的，合并后存续或者新设立的房地产估价机构可以承继合并前各方中较高的资质等级，但应当符合相应的资质等级条件。 房地产估价机构分立的，只能由分立后的一方房地产估价机构承继原房地产估价机构资质，但应当符合原房地产估价机构资质等级条件。承继原房地产估价机构资质的一方由各方协商确定；其他各方按照新设立的中介服务机构申请房地产估价机构资质。"},{"i":19,"n":"第十九条","txt":"房地产估价机构的工商登记注销后，其资质证书失效。"},{"i":20,"n":"第二十条","txt":"一级资质房地产估价机构可以按照本办法第二十一条的规定设立分支机构。二、三级资质房地产估价机构不得设立分支机构。 分支机构应当以设立该分支机构的房地产估价机构的名义出具估价报告，并加盖该房地产估价机构公章。"},{"i":21,"n":"第二十一条","txt":"分支机构应当具备下列条件： （一）名称采用“房地产估价机构名称＋分支机构所在地行政区划名＋分公司（分所）”的形式； （二）分支机构负责人应当是注册后从事房地产估价工作3年以上并无不良执业记录的专职注册房地产估价师； （三）在分支机构所在地有3名以上专职注册房地产估价师； （四）有固定的经营服务场所； （五）估价质量管理、估价档案管理、财务管理等各项内部管理制度健全。 注册于分支机构的专职注册房地产估价师，不计入设立分支机构的房地产估价机构的专职注册房地产估价师人数。"},{"i":22,"n":"第二十二条","txt":"新设立的分支机构，应当自领取分支机构营业执照之日起30日内，到分支机构工商注册所在地的省、自治区人民政府住房城乡建设主管部门、直辖市人民政府房地产主管部门备案。 省、自治区人民政府住房城乡建设主管部门、直辖市人民政府房地产主管部门应当在接受备案后10日内，告知分支机构工商注册所在地的市、县人民政府房地产主管部门，并报国务院住房城乡建设主管部门备案。"},{"i":23,"n":"第二十三条","txt":"分支机构备案，应当提交下列材料： （一）分支机构的营业执照复印件； （二）房地产估价机构资质证书正本复印件； （三）分支机构及设立该分支机构的房地产估价机构负责人的身份证明； （四）拟在分支机构执业的专职注册房地产估价师注册证书复印件。"},{"i":24,"n":"第二十四条","txt":"分支机构变更名称、负责人、住所等事项或房地产估价机构撤销分支机构，应当在工商行政管理部门办理变更或者注销登记手续后30日内，报原备案机关备案。"},{"i":25,"n":"第二十五条","txt":"从事房地产估价活动的机构，应当依法取得房地产估价机构资质，并在其资质等级许可范围内从事估价业务。 一级资质房地产估价机构可以从事各类房地产估价业务。 二级资质房地产估价机构可以从事除公司上市、企业清算以外的房地产估价业务。 三级资质房地产估价机构可以从事除公司上市、企业清算、司法鉴定以外的房地产估价业务。 暂定期内的三级资质房地产估价机构可以从事除公司上市、企业清算、司法鉴定、房屋征收、在建工程抵押以外的房地产估价业务。"},{"i":26,"n":"第二十六条","txt":"房地产估价业务应当由房地产估价机构统一接受委托，统一收取费用。 房地产估价师不得以个人名义承揽估价业务，分支机构应当以设立该分支机构的房地产估价机构名义承揽估价业务。"},{"i":27,"n":"第二十七条","txt":"房地产估价机构及执行房地产估价业务的估价人员与委托人或者估价业务相对人有利害关系的，应当回避。"},{"i":28,"n":"第二十八条","txt":"房地产估价机构承揽房地产估价业务，应当与委托人签订书面估价委托合同。 估价委托合同应当包括下列内容： （一）委托人的名称或者姓名和住所； （二）估价机构的名称和住所； （三）估价对象； （四）估价目的； （五）价值时点； （六）委托人的协助义务； （七）估价服务费及其支付方式； （八）估价报告交付的日期和方式； （九）违约责任； （十）解决争议的方法。"},{"i":29,"n":"第二十九条","txt":"房地产估价机构未经委托人书面同意，不得转让受托的估价业务。 经委托人书面同意，房地产估价机构可以与其他房地产估价机构合作完成估价业务，以合作双方的名义共同出具估价报告。"},{"i":30,"n":"第三十条","txt":"委托人及相关当事人应当协助房地产估价机构进行实地查勘，如实向房地产估价机构提供估价所必需的资料，并对其所提供资料的真实性负责。"},{"i":31,"n":"第三十一条","txt":"房地产估价机构和注册房地产估价师因估价需要向房地产主管部门查询房地产交易、登记信息时，房地产主管部门应当提供查询服务，但涉及国家秘密、商业秘密和个人隐私的内容除外。"},{"i":32,"n":"第三十二条","txt":"房地产估价报告应当由房地产估价机构出具，加盖房地产估价机构公章，并有至少2名专职注册房地产估价师签字。"},{"i":33,"n":"第三十三条","txt":"房地产估价机构不得有下列行为： （一）涂改、倒卖、出租、出借或者以其他形式非法转让资质证书； （二）超越资质等级业务范围承接房地产估价业务； （三）以迎合高估或者低估要求、给予回扣、恶意压低收费等方式进行不正当竞争； （四）违反房地产估价规范和标准； （五）出具有虚假记载、误导性陈述或者重大遗漏的估价报告； （六）擅自设立分支机构； （七）未经委托人书面同意，擅自转让受托的估价业务； （八）法律、法规禁止的其他行为。"},{"i":34,"n":"第三十四条","txt":"房地产估价机构应当妥善保管房地产估价报告及相关资料。 房地产估价报告及相关资料的保管期限自估价报告出具之日起不得少于10年。保管期限届满而估价服务的行为尚未结束的，应当保管到估价服务的行为结束为止。"},{"i":35,"n":"第三十五条","txt":"除法律、法规另有规定外，未经委托人书面同意，房地产估价机构不得对外提供估价过程中获知的当事人的商业秘密和业务资料。"},{"i":36,"n":"第三十六条","txt":"房地产估价机构应当加强对执业人员的职业道德教育和业务培训，为本机构的房地产估价师参加继续教育提供必要的条件。"},{"i":37,"n":"第三十七条","txt":"县级以上人民政府房地产主管部门应当依照有关法律、法规和本办法的规定，对房地产估价机构和分支机构的设立、估价业务及执行房地产估价规范和标准的情况实施监督检查。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府房地产主管部门履行监督检查职责时，有权采取下列措施： （一）要求被检查单位提供房地产估价机构资质证书、房地产估价师注册证书，有关房地产估价业务的文档，有关估价质量管理、估价档案管理、财务管理等企业内部管理制度的文件； （二）进入被检查单位进行检查，查阅房地产估价报告以及估价委托合同、实地查勘记录等估价相关资料； （三）纠正违反有关法律、法规和本办法及房地产估价规范和标准的行为。 县级以上人民政府房地产主管部门应当将监督检查的处理结果向社会公布。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府房地产主管部门进行监督检查时，应当有两名以上监督检查人员参加，并出示执法证件，不得妨碍被检查单位的正常经营活动，不得索取或者收受财物、谋取其他利益。 有关单位和个人对依法进行的监督检查应当协助与配合，不得拒绝或者阻挠。"},{"i":40,"n":"第四十条","txt":"房地产估价机构违法从事房地产估价活动的，违法行为发生地的县级以上地方人民政府房地产主管部门应当依法查处，并将违法事实、处理结果及处理建议及时报告该估价机构资质的许可机关。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，资质许可机关或者其上级机关，根据利害关系人的请求或者依据职权，可以撤销房地产估价机构资质： （一）资质许可机关工作人员滥用职权、玩忽职守作出准予房地产估价机构资质许可的； （二）超越法定职权作出准予房地产估价机构资质许可的； （三）违反法定程序作出准予房地产估价机构资质许可的； （四）对不符合许可条件的申请人作出准予房地产估价机构资质许可的； （五）依法可以撤销房地产估价机构资质的其他情形。 房地产估价机构以欺骗、贿赂等不正当手段取得房地产估价机构资质的，应当予以撤销。"},{"i":42,"n":"第四十二条","txt":"房地产估价机构取得房地产估价机构资质后，不再符合相应资质条件的，资质许可机关根据利害关系人的请求或者依据职权，可以责令其限期改正；逾期不改的，可以撤回其资质。"},{"i":43,"n":"第四十三条","txt":"有下列情形之一的，资质许可机关应当依法注销房地产估价机构资质： （一）房地产估价机构资质有效期届满未延续的； （二）房地产估价机构依法终止的； （三）房地产估价机构资质被撤销、撤回，或者房地产估价资质证书依法被吊销的； （四）法律、法规规定的应当注销房地产估价机构资质的其他情形。"},{"i":44,"n":"第四十四条","txt":"资质许可机关或者房地产估价行业组织应当建立房地产估价机构信用档案。 房地产估价机构应当按照要求提供真实、准确、完整的房地产估价信用档案信息。 房地产估价机构信用档案应当包括房地产估价机构的基本情况、业绩、良好行为、不良行为等内容。违法行为、被投诉举报处理、行政处罚等情况应当作为房地产估价机构的不良记录记入其信用档案。 房地产估价机构的不良行为应当作为该机构法定代表人或者执行合伙人的不良行为记入其信用档案。 任何单位和个人有权查阅信用档案。"},{"i":45,"n":"第四十五条","txt":"申请人隐瞒有关情况或者提供虚假材料申请房地产估价机构资质的，资质许可机关不予受理或者不予行政许可，并给予警告，申请人在1年内不得再次申请房地产估价机构资质。"},{"i":46,"n":"第四十六条","txt":"以欺骗、贿赂等不正当手段取得房地产估价机构资质的，由资质许可机关给予警告，并处1万元以上3万元以下的罚款，申请人3年内不得再次申请房地产估价机构资质。"},{"i":47,"n":"第四十七条","txt":"未取得房地产估价机构资质从事房地产估价活动或者超越资质等级承揽估价业务的，出具的估价报告无效，由县级以上地方人民政府房地产主管部门给予警告，责令限期改正，并处1万元以上3万元以下的罚款；造成当事人损失的，依法承担赔偿责任。"},{"i":48,"n":"第四十八条","txt":"违反本办法第十七条规定，房地产估价机构不及时办理资质证书变更手续的，由资质许可机关责令限期办理；逾期不办理的，可处1万元以下的罚款。"},{"i":49,"n":"第四十九条","txt":"有下列行为之一的，由县级以上地方人民政府房地产主管部门给予警告，责令限期改正，并可处1万元以上2万元以下的罚款： （一）违反本办法第二十条第一款规定设立分支机构的； （二）违反本办法第二十一条规定设立分支机构的； （三）违反本办法第二十二条第一款规定，新设立的分支机构不备案的。"},{"i":50,"n":"第五十条","txt":"有下列行为之一的，由县级以上地方人民政府房地产主管部门给予警告，责令限期改正；逾期未改正的，可处5千元以上2万元以下的罚款；给当事人造成损失的，依法承担赔偿责任： （一）违反本办法第二十六条规定承揽业务的； （二）违反本办法第二十九条第一款规定，擅自转让受托的估价业务的； （三）违反本办法第二十条第二款、第二十九条第二款、第三十二条规定出具估价报告的。"},{"i":51,"n":"第五十一条","txt":"违反本办法第二十七条规定，房地产估价机构及其估价人员应当回避未回避的，由县级以上地方人民政府房地产主管部门给予警告，责令限期改正，并可处1万元以下的罚款；给当事人造成损失的，依法承担赔偿责任。"},{"i":52,"n":"第五十二条","txt":"违反本办法第三十一条规定，房地产主管部门拒绝提供房地产交易、登记信息查询服务的，由其上级房地产主管部门责令改正。"},{"i":53,"n":"第五十三条","txt":"房地产估价机构有本办法第三十三条行为之一的，由县级以上地方人民政府房地产主管部门给予警告，责令限期改正，并处1万元以上3万元以下的罚款；给当事人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"违反本办法第三十五条规定，房地产估价机构擅自对外提供估价过程中获知的当事人的商业秘密和业务资料，给当事人造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"资质许可机关有下列情形之一的，由其上级行政主管部门或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）对不符合法定条件的申请人准予房地产估价机构资质许可或者超越职权作出准予房地产估价机构资质许可决定的； （二）对符合法定条件的申请人不予房地产估价机构资质许可或者不在法定期限内作出准予房地产估价机构资质许可决定的； （三）利用职务上的便利，收受他人财物或者其他利益的； （四）不履行监督管理职责，或者发现违法行为不予查处的。"},{"i":56,"n":"第五十六条","txt":"本办法自2005年12月1日起施行。1997年1月9日建设部颁布的《关于房地产价格评估机构资格等级管理的若干规定》（建房〔1997〕12号）同时废止。 本办法施行前建设部发布的规章的规定与本办法的规定不一致的，以本办法为准。"}],"fangdichankaifaqiyezizhiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强房地产开发企业资质管理，规范房地产开发企业经营行为，根据《中华人民共和国城市房地产管理法》、《城市房地产开发经营管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称房地产开发企业是指依法设立、具有企业法人资格的经济实体。"},{"i":3,"n":"第三条","txt":"房地产开发企业应当按照本规定申请核定企业资质等级。 未取得房地产开发资质等级证书（以下简称资质证书）的企业，不得从事房地产开发经营业务。"},{"i":4,"n":"第四条","txt":"国务院住房和城乡建设主管部门负责全国房地产开发企业的资质管理工作；县级以上地方人民政府房地产开发主管部门负责本行政区域内房地产开发企业的资质管理工作。"},{"i":5,"n":"第五条","txt":"房地产开发企业按照企业条件分为一、二两个资质等级。 各资质等级企业的条件如下： （一）一级资质： 1.从事房地产开发经营5年以上； 2.近3年房屋建筑面积累计竣工30万平方米以上，或者累计完成与此相当的房地产开发投资额； 3.连续5年建筑工程质量合格率达100%； 4.上一年房屋建筑施工面积15万平方米以上，或者完成与此相当的房地产开发投资额； 5.有职称的建筑、结构、财务、房地产及有关经济类的专业管理人员不少于40人，其中具有中级以上职称的管理人员不少于20人，持有专职会计人员不少于4人； 6.工程技术、财务、统计等业务负责人具有相应专业中级以上职称； 7.具有完善的质量保证体系，商品住宅销售中实行了《住宅质量保证书》和《住宅使用说明书》制度； 8.未发生过重大工程质量事故。 （二）二级资质： 1.有职称的建筑、结构、财务、房地产及有关经济类的专业管理人员不少于5人，其中专职会计人员"},{"i":6,"n":"第六条","txt":"临时聘用或者兼职的管理、技术人员不得计入企业管理、技术人员总数。"},{"i":7,"n":"第七条","txt":"申请核定资质等级的房地产开发企业，应当提交下列材料： （一）一级资质： 1.企业资质等级申报表； 2.专业管理、技术人员的职称证件； 3.已开发经营项目的有关材料； 4.《住宅质量保证书》、《住宅使用说明书》执行情况报告，建立质量管理制度、具有质量管理部门及相应质量管理人员等质量保证体系情况说明。 （二）二级资质： 1.企业资质等级申报表； 2.专业管理、技术人员的职称证件； 3.建立质量管理制度、具有质量管理部门及相应质量管理人员等质量保证体系情况说明。"},{"i":8,"n":"第八条","txt":"房地产开发企业资质等级实行分级审批。 一级资质由省、自治区、直辖市人民政府住房和城乡建设主管部门初审，报国务院住房和城乡建设主管部门审批。 二级资质由省、自治区、直辖市人民政府住房和城乡建设主管部门或者其确定的设区的市级人民政府房地产开发主管部门审批。 经资质审查合格的企业，由资质审批部门发给相应等级的资质证书。资质证书有效期为3年。 申请核定资质的房地产开发企业，应当通过相应的政务服务平台提出申请。"},{"i":9,"n":"第九条","txt":"资质证书由国务院住房和城乡建设主管部门统一制作。资质证书分为正本和副本，资质审批部门可以根据需要核发资质证书副本若干份。"},{"i":10,"n":"第十条","txt":"任何单位和个人不得涂改、出租、出借、转让、出卖资质证书。 企业遗失资质证书，必须在新闻媒体上声明作废后，方可补领。"},{"i":11,"n":"第十一条","txt":"企业发生分立、合并的，应当在向市场监督管理部门办理变更手续后的30日内，到原资质审批部门申请办理资质证书注销手续，并重新申请资质等级。"},{"i":12,"n":"第十二条","txt":"企业变更名称、法定代表人和主要管理、技术负责人，应当在变更30日内，向原资质审批部门办理变更手续。"},{"i":13,"n":"第十三条","txt":"企业破产、歇业或者因其他原因终止业务时，应当在向市场监督管理部门办理注销营业执照后的15日内，到原资质审批部门注销资质证书。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府房地产开发主管部门应当开展‘双随机、一公开’监管，依法查处房地产开发企业的违法违规行为。 县级以上人民政府房地产开发主管部门应当加强对房地产开发企业信用监管，不断提升信用监管水平。"},{"i":15,"n":"第十五条","txt":"一级资质的房地产开发企业承担房地产项目的建筑规模不受限制。 二级资质的房地产开发企业可以承担建筑面积25万平方米以下的开发建设项目。 各资质等级企业应当在规定的业务范围内从事房地产开发经营业务，不得越级承担任务。"},{"i":16,"n":"第十六条","txt":"企业未取得资质证书从事房地产开发经营的，由县级以上地方人民政府房地产开发主管部门责令限期改正，处5万元以上10万元以下的罚款；逾期不改正的，由房地产开发主管部门提请市场监督管理部门吊销营业执照。"},{"i":17,"n":"第十七条","txt":"企业超越资质等级从事房地产开发经营的，由县级以上地方人民政府房地产开发主管部门责令限期改正，处5万元以上10万元以下的罚款；逾期不改正的，由原资质审批部门提请市场监督管理部门吊销营业执照，并依法注销资质证书。"},{"i":18,"n":"第十八条","txt":"企业有下列行为之一的，由原资质审批部门按照《中华人民共和国行政许可法》等法律法规规定予以处理，并可处以1万元以上3万元以下的罚款： （一）隐瞒真实情况、弄虚作假骗取资质证书的； （二）涂改、出租、出借、转让、出卖资质证书的。"},{"i":19,"n":"第十九条","txt":"企业开发经营活动中有违法行为的，按照《中华人民共和国行政处罚法》、《中华人民共和国城市房地产管理法》、《城市房地产开发经营管理条例》、《建设工程质量管理条例》、《建设工程安全生产管理条例》、《民用建筑节能条例》等有关法律法规规定予以处罚。"},{"i":20,"n":"第二十条","txt":"各级住房和城乡建设主管部门工作人员在资质审批和管理中玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管部门给予行政处分；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市人民政府住房和城乡建设主管部门可以根据本规定制定实施细则。"},{"i":22,"n":"第二十二条","txt":"本规定由国务院住房和城乡建设主管部门负责解释。"},{"i":23,"n":"第二十三条","txt":"本规定自发布之日起施行。1993年11月16日建设部发布的《房地产开发企业资质管理规定》（建设部令第28号）同时废止。"}],"fangdichanjingjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范房地产经纪活动，保护房地产交易及经纪活动当事人的合法权益，促进房地产市场健康发展，根据《中华人民共和国城市房地产管理法》、《中华人民共和国合同法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事房地产经纪活动，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称房地产经纪，是指房地产经纪机构和房地产经纪人员为促成房地产交易，向委托人提供房地产居间、代理等服务并收取佣金的行为。"},{"i":4,"n":"第四条","txt":"从事房地产经纪活动应当遵循自愿、平等、公平和诚实信用的原则，遵守职业规范，恪守职业道德。"},{"i":5,"n":"第五条","txt":"县级以上人民政府建设（房地产）主管部门、价格主管部门、人力资源和社会保障主管部门应当按照职责分工，分别负责房地产经纪活动的监督和管理。"},{"i":6,"n":"第六条","txt":"房地产经纪行业组织应当按照章程实行自律管理，向有关部门反映行业发展的意见和建议，促进房地产经纪行业发展和人员素质提高。"},{"i":7,"n":"第七条","txt":"本办法所称房地产经纪机构，是指依法设立，从事房地产经纪活动的中介服务机构。 房地产经纪机构可以设立分支机构。"},{"i":8,"n":"第八条","txt":"设立房地产经纪机构和分支机构，应当具有足够数量的房地产经纪人员。 本办法所称房地产经纪人员，是指从事房地产经纪活动的房地产经纪人和房地产经纪人协理。 房地产经纪机构和分支机构与其招用的房地产经纪人员，应当按照《中华人民共和国劳动合同法》的规定签订劳动合同。"},{"i":9,"n":"第九条","txt":"国家对房地产经纪人员实行职业资格制度，纳入全国专业技术人员职业资格制度统一规划和管理。"},{"i":10,"n":"第十条","txt":"房地产经纪人协理和房地产经纪人职业资格实行全国统一大纲、统一命题、统一组织的考试制度，由房地产经纪行业组织负责管理和实施考试工作，原则上每年举行一次考试。国务院住房城乡建设主管部门、人力资源社会保障部门负责对房地产经纪人协理和房地产经纪人职业资格考试进行指导、监督和检查。"},{"i":11,"n":"第十一条","txt":"房地产经纪机构及其分支机构应当自领取营业执照之日起30日内，到所在直辖市、市、县人民政府建设（房地产）主管部门备案。"},{"i":12,"n":"第十二条","txt":"直辖市、市、县人民政府建设（房地产）主管部门应当将房地产经纪机构及其分支机构的名称、住所、法定代表人（执行合伙人）或者负责人、注册资本、房地产经纪人员等备案信息向社会公示。"},{"i":13,"n":"第十三条","txt":"房地产经纪机构及其分支机构变更或者终止的，应当自变更或者终止之日起30日内，办理备案变更或者注销手续。"},{"i":14,"n":"第十四条","txt":"房地产经纪业务应当由房地产经纪机构统一承接，服务报酬由房地产经纪机构统一收取。分支机构应当以设立该分支机构的房地产经纪机构名义承揽业务。 房地产经纪人员不得以个人名义承接房地产经纪业务和收取费用。"},{"i":15,"n":"第十五条","txt":"房地产经纪机构及其分支机构应当在其经营场所醒目位置公示下列内容： （一）营业执照和备案证明文件； （二）服务项目、内容、标准； （三）业务流程； （四）收费项目、依据、标准； （五）交易资金监管方式； （六）信用档案查询方式、投诉电话及12358价格举报电话； （七）政府主管部门或者行业组织制定的房地产经纪服务合同、房屋买卖合同、房屋租赁合同示范文本； （八）法律、法规、规章规定的其他事项。 分支机构还应当公示设立该分支机构的房地产经纪机构的经营地址及联系方式。 房地产经纪机构代理销售商品房项目的，还应当在销售现场明显位置明示商品房销售委托书和批准销售商品房的有关证明文件。"},{"i":16,"n":"第十六条","txt":"房地产经纪机构接受委托提供房地产信息、实地看房、代拟合同等房地产经纪服务的，应当与委托人签订书面房地产经纪服务合同。 房地产经纪服务合同应当包含下列内容： （一）房地产经纪服务双方当事人的姓名（名称）、住所等情况和从事业务的房地产经纪人员情况； （二）房地产经纪服务的项目、内容、要求以及完成的标准； （三）服务费用及其支付方式； （四）合同当事人的权利和义务； （五）违约责任和纠纷解决方式。 建设（房地产）主管部门或者房地产经纪行业组织可以制定房地产经纪服务合同示范文本，供当事人选用。"},{"i":17,"n":"第十七条","txt":"房地产经纪机构提供代办贷款、代办房地产登记等其他服务的，应当向委托人说明服务内容、收费标准等情况，经委托人同意后，另行签订合同。"},{"i":18,"n":"第十八条","txt":"房地产经纪服务实行明码标价制度。房地产经纪机构应当遵守价格法律、法规和规章规定，在经营场所醒目位置标明房地产经纪服务项目、服务内容、收费标准以及相关房地产价格和信息。 房地产经纪机构不得收取任何未予标明的费用；不得利用虚假或者使人误解的标价内容和标价方式进行价格欺诈；一项服务可以分解为多个项目和标准的，应当明确标示每一个项目和标准，不得混合标价、捆绑标价。"},{"i":19,"n":"第十九条","txt":"房地产经纪机构未完成房地产经纪服务合同约定事项，或者服务未达到房地产经纪服务合同约定标准的，不得收取佣金。 两家或者两家以上房地产经纪机构合作开展同一宗房地产经纪业务的，只能按照一宗业务收取佣金，不得向委托人增加收费。"},{"i":20,"n":"第二十条","txt":"房地产经纪机构签订的房地产经纪服务合同，应当加盖房地产经纪机构印章，并由从事该业务的一名房地产经纪人或者两名房地产经纪人协理签名。"},{"i":21,"n":"第二十一条","txt":"房地产经纪机构签订房地产经纪服务合同前，应当向委托人说明房地产经纪服务合同和房屋买卖合同或者房屋租赁合同的相关内容，并书面告知下列事项： （一）是否与委托房屋有利害关系； （二）应当由委托人协助的事宜、提供的资料； （三）委托房屋的市场参考价格； （四）房屋交易的一般程序及可能存在的风险； （五）房屋交易涉及的税费； （六）经纪服务的内容及完成标准； （七）经纪服务收费标准和支付时间； （八）其他需要告知的事项。 房地产经纪机构根据交易当事人需要提供房地产经纪服务以外的其他服务的，应当事先经当事人书面同意并告知服务内容及收费标准。书面告知材料应当经委托人签名（盖章）确认。"},{"i":22,"n":"第二十二条","txt":"房地产经纪机构与委托人签订房屋出售、出租经纪服务合同，应当查看委托出售、出租的房屋及房屋权属证书，委托人的身份证明等有关资料，并应当编制房屋状况说明书。经委托人书面同意后，方可以对外发布相应的房源信息。 房地产经纪机构与委托人签订房屋承购、承租经纪服务合同，应当查看委托人身份证明等有关资料。"},{"i":23,"n":"第二十三条","txt":"委托人与房地产经纪机构签订房地产经纪服务合同，应当向房地产经纪机构提供真实有效的身份证明。委托出售、出租房屋的，还应当向房地产经纪机构提供真实有效的房屋权属证书。委托人未提供规定资料或者提供资料与实际不符的，房地产经纪机构应当拒绝接受委托。"},{"i":24,"n":"第二十四条","txt":"房地产交易当事人约定由房地产经纪机构代收代付交易资金的，应当通过房地产经纪机构在银行开设的客户交易结算资金专用存款账户划转交易资金。 交易资金的划转应当经过房地产交易资金支付方和房地产经纪机构的签字和盖章。"},{"i":25,"n":"第二十五条","txt":"房地产经纪机构和房地产经纪人员不得有下列行为： （一）捏造散布涨价信息，或者与房地产开发经营单位串通捂盘惜售、炒卖房号，操纵市场价格； （二）对交易当事人隐瞒真实的房屋交易信息，低价收进高价卖（租）出房屋赚取差价； （三）以隐瞒、欺诈、胁迫、贿赂等不正当手段招揽业务，诱骗消费者交易或者强制交易； （四）泄露或者不当使用委托人的个人信息或者商业秘密，谋取不正当利益； （五）为交易当事人规避房屋交易税费等非法目的，就同一房屋签订不同交易价款的合同提供便利； （六）改变房屋内部结构分割出租； （七）侵占、挪用房地产交易资金； （八）承购、承租自己提供经纪服务的房屋； （九）为不符合交易条件的保障性住房和禁止交易的房屋提供经纪服务； （十）法律、法规禁止的其他行为。"},{"i":26,"n":"第二十六条","txt":"房地产经纪机构应当建立业务记录制度，如实记录业务情况。 房地产经纪机构应当保存房地产经纪服务合同，保存期不少于5年。"},{"i":27,"n":"第二十七条","txt":"房地产经纪行业组织应当制定房地产经纪从业规程，逐步建立并完善资信评价体系和房地产经纪房源、客源信息共享系统。"},{"i":28,"n":"第二十八条","txt":"建设（房地产）主管部门、价格主管部门应当通过现场巡查、合同抽查、投诉受理等方式，采取约谈、记入信用档案、媒体曝光等措施，对房地产经纪机构和房地产经纪人员进行监督。 房地产经纪机构违反人力资源和社会保障法律法规的行为，由人力资源和社会保障主管部门依法予以查处。 被检查的房地产经纪机构和房地产经纪人员应当予以配合，并根据要求提供检查所需的资料。"},{"i":29,"n":"第二十九条","txt":"建设（房地产）主管部门、价格主管部门、人力资源和社会保障主管部门应当建立房地产经纪机构和房地产经纪人员信息共享制度。建设（房地产）主管部门应当定期将备案的房地产经纪机构情况通报同级价格主管部门、人力资源和社会保障主管部门。"},{"i":30,"n":"第三十条","txt":"直辖市、市、县人民政府建设（房地产）主管部门应当构建统一的房地产经纪网上管理和服务平台，为备案的房地产经纪机构提供下列服务： （一）房地产经纪机构备案信息公示； （二）房地产交易与登记信息查询； （三）房地产交易合同网上签订； （四）房地产经纪信用档案公示； （五）法律、法规和规章规定的其他事项。 经备案的房地产经纪机构可以取得网上签约资格。"},{"i":31,"n":"第三十一条","txt":"县级以上人民政府建设（房地产）主管部门应当建立房地产经纪信用档案，并向社会公示。 县级以上人民政府建设（房地产）主管部门应当将在日常监督检查中发现的房地产经纪机构和房地产经纪人员的违法违规行为、经查证属实的被投诉举报记录等情况，作为不良信用记录记入其信用档案。"},{"i":32,"n":"第三十二条","txt":"房地产经纪机构和房地产经纪人员应当按照规定提供真实、完整的信用档案信息。"},{"i":33,"n":"第三十三条","txt":"违反本办法，有下列行为之一的，由县级以上地方人民政府建设（房地产）主管部门责令限期改正，记入信用档案；对房地产经纪人员处以1万元罚款；对房地产经纪机构处以1万元以上3万元以下罚款： （一）房地产经纪人员以个人名义承接房地产经纪业务和收取费用的； （二）房地产经纪机构提供代办贷款、代办房地产登记等其他服务，未向委托人说明服务内容、收费标准等情况，并未经委托人同意的； （三）房地产经纪服务合同未由从事该业务的一名房地产经纪人或者两名房地产经纪人协理签名的； （四）房地产经纪机构签订房地产经纪服务合同前，不向交易当事人说明和书面告知规定事项的； （五）房地产经纪机构未按照规定如实记录业务情况或者保存房地产经纪服务合同的。"},{"i":34,"n":"第三十四条","txt":"违反本办法第十八条、第十九条、第二十五条第（一）项、第（二）项，构成价格违法行为的，由县级以上人民政府价格主管部门按照价格法律、法规和规章的规定，责令改正、没收违法所得、依法处以罚款；情节严重的，依法给予停业整顿等行政处罚。"},{"i":35,"n":"第三十五条","txt":"违反本办法第二十二条，房地产经纪机构擅自对外发布房源信息的，由县级以上地方人民政府建设（房地产）主管部门责令限期改正，记入信用档案，取消网上签约资格，并处以1万元以上3万元以下罚款。"},{"i":36,"n":"第三十六条","txt":"违反本办法第二十四条，房地产经纪机构擅自划转客户交易结算资金的，由县级以上地方人民政府建设（房地产）主管部门责令限期改正，取消网上签约资格，处以3万元罚款。"},{"i":37,"n":"第三十七条","txt":"违反本办法第二十五条第（三）项、第（四）项、第（五）项、第（六）项、第（七）项、第（八）项、第（九）项、第（十）项的，由县级以上地方人民政府建设（房地产）主管部门责令限期改正，记入信用档案；对房地产经纪人员处以1万元罚款；对房地产经纪机构，取消网上签约资格，处以3万元罚款。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府建设（房地产）主管部门、价格主管部门、人力资源和社会保障主管部门的工作人员在房地产经纪监督管理工作中，玩忽职守、徇私舞弊、滥用职权的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"各地可以依据本办法制定实施细则。"},{"i":40,"n":"第四十条","txt":"本办法自2011年4月1日起施行。"}],"fangwujianzhuheshizhengjichusheshigongchengshigong87203d":[{"i":1,"n":"第一条","txt":"为了规范房屋建筑和市政基础设施工程施工分包活动，维护建筑市场秩序，保证工程质量和施工安全，根据《中华人民共和国建筑法》、《中华人民共和国招标投标法》、《建设工程质量管理条例》等有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事房屋建筑和市政基础设施工程施工分包活动，实施对房屋建筑和市政基础设施工程施工分包活动的监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"国务院住房城乡建设主管部门负责全国房屋建筑和市政基础设施工程施工分包的监督管理工作。 县级以上地方人民政府住房城乡建设主管部门负责本行政区域内房屋建筑和市政基础设施工程施工分包的监督管理工作。"},{"i":4,"n":"第四条","txt":"本办法所称施工分包，是指建筑业企业将其所承包的房屋建筑和市政基础设施工程中的专业工程或者劳务作业发包给其他建筑业企业完成的活动。"},{"i":5,"n":"第五条","txt":"房屋建筑和市政基础设施工程施工分包分为专业工程分包和劳务作业分包。 本办法所称专业工程分包，是指施工总承包企业（以下简称专业分包工程发包人）将其所承包工程中的专业工程发包给具有相应资质的其他建筑业企业（以下简称专业分包工程承包人）完成的活动。 本办法所称劳务作业分包，是指施工总承包企业或者专业承包企业（以下简称劳务作业发包人）将其承包工程中的劳务作业发包给劳务分包企业（以下简称劳务作业承包人）完成的活动。 本办法所称分包工程发包人包括本条第二款、第三款中的专业分包工程发包人和劳务作业发包人；分包工程承包人包括本条第二款、第三款中的专业分包工程承包人和劳务作业承包人。"},{"i":6,"n":"第六条","txt":"房屋建筑和市政基础设施工程施工分包活动必须依法进行。 鼓励发展专业承包企业和劳务分包企业，提倡分包活动进入有形建筑市场公开交易，完善有形建筑市场的分包工程交易功能。"},{"i":7,"n":"第七条","txt":"建设单位不得直接指定分包工程承包人。任何单位和个人不得对依法实施的分包活动进行干预。"},{"i":8,"n":"第八条","txt":"分包工程承包人必须具有相应的资质，并在其资质等级许可的范围内承揽业务。 严禁个人承揽分包工程业务。"},{"i":9,"n":"第九条","txt":"专业工程分包除在施工总承包合同中有约定外，必须经建设单位认可。专业分包工程承包人必须自行完成所承包的工程。 劳务作业分包由劳务作业发包人与劳务作业承包人通过劳务合同约定。劳务作业承包人必须自行完成所承包的任务。"},{"i":10,"n":"第十条","txt":"分包工程发包人和分包工程承包人应当依法签订分包合同，并按照合同履行约定的义务。分包合同必须明确约定支付工程款和劳务工资的时间、结算方式以及保证按期支付的相应措施，确保工程款和劳务工资的支付。"},{"i":11,"n":"第十一条","txt":"分包工程发包人应当设立项目管理机构，组织管理所承包工程的施工活动。 项目管理机构应当具有与承包工程的规模、技术复杂程度相适应的技术、经济管理人员。其中，项目负责人、技术负责人、项目核算负责人、质量管理人员、安全管理人员必须是本单位的人员。具体要求由省、自治区、直辖市人民政府住房城乡建设主管部门规定。 前款所指本单位人员，是指与本单位有合法的人事或者劳动合同、工资以及社会保险关系的人员。"},{"i":12,"n":"第十二条","txt":"分包工程发包人可以就分包合同的履行，要求分包工程承包人提供分包工程履约担保；分包工程承包人在提供担保后，要求分包工程发包人同时提供分包工程付款担保的，分包工程发包人应当提供。"},{"i":13,"n":"第十三条","txt":"禁止将承包的工程进行转包。不履行合同约定，将其承包的全部工程发包给他人，或者将其承包的全部工程肢解后以分包的名义分别发包给他人的，属于转包行为。 违反本办法第十二条规定，分包工程发包人将工程分包后，未在施工现场设立项目管理机构和派驻相应人员，并未对该工程的施工活动进行组织管理的，视同转包行为。"},{"i":14,"n":"第十四条","txt":"禁止将承包的工程进行违法分包。下列行为，属于违法分包： （一）分包工程发包人将专业工程或者劳务作业分包给不具备相应资质条件的分包工程承包人的； （二）施工总承包合同中未有约定，又未经建设单位认可，分包工程发包人将承包工程中的部分专业工程分包给他人的。"},{"i":15,"n":"第十五条","txt":"禁止转让、出借企业资质证书或者以其他方式允许他人以本企业名义承揽工程。 分包工程发包人没有将其承包的工程进行分包，在施工现场所设项目管理机构的项目负责人、技术负责人、项目核算负责人、质量管理人员、安全管理人员不是工程承包人本单位人员的，视同允许他人以本企业名义承揽工程。"},{"i":16,"n":"第十六条","txt":"分包工程承包人应当按照分包合同的约定对其承包的工程向分包工程发包人负责。分包工程发包人和分包工程承包人就分包工程对建设单位承担连带责任。"},{"i":17,"n":"第十七条","txt":"分包工程发包人对施工现场安全负责，并对分包工程承包人的安全生产进行管理。专业分包工程承包人应当将其分包工程的施工组织设计和施工安全方案报分包工程发包人备案，专业分包工程发包人发现事故隐患，应当及时作出处理。　 分包工程承包人就施工现场安全向分包工程发包人负责，并应当服从分包工程发包人对施工现场的安全生产管理。"},{"i":18,"n":"第十八条","txt":"违反本办法规定，转包、违法分包或者允许他人以本企业名义承揽工程的，以及接受转包和用他人名义承揽工程的，按《中华人民共和国建筑法》、《中华人民共和国招标投标法》和《建设工程质量管理条例》的规定予以处罚。具体办法由国务院住房城乡建设主管部门依据有关法律法规另行制定。"},{"i":19,"n":"第十九条","txt":"未取得建筑业企业资质承接分包工程的，按照《中华人民共和国建筑法》第六十五条第三款和《建设工程质量管理条例》第六十条第一款、第二款的规定处罚。"},{"i":20,"n":"第二十条","txt":"本办法自2004年4月1日起施行。原城乡建设环境保护部1986年4月30日发布的《建筑安装工程总分包实施办法》同时废止。"}],"fangwujianzhuheshizhengjichusheshigongchengshigong952f69":[{"i":1,"n":"第一条","txt":"为了加强对房屋建筑工程、市政基础设施工程施工图设计文件审查的管理，提高工程勘察设计质量，根据《建设工程质量管理条例》、《建设工程勘察设计管理条例》等行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事房屋建筑工程、市政基础设施工程施工图设计文件审查和实施监督管理的，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"国家实施施工图设计文件（含勘察文件，以下简称施工图）审查制度。 本办法所称施工图审查，是指施工图审查机构（以下简称审查机构）按照有关法律、法规，对施工图涉及公共利益、公众安全和工程建设强制性标准的内容进行的审查。施工图审查应当坚持先勘察、后设计的原则。 施工图未经审查合格的，不得使用。从事房屋建筑工程、市政基础设施工程施工、监理等活动，以及实施对房屋建筑和市政基础设施工程质量安全监督管理，应当以审查合格的施工图为依据。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责对全国的施工图审查工作实施指导、监督。 县级以上地方人民政府住房城乡建设主管部门负责对本行政区域内的施工图审查工作实施监督管理。"},{"i":5,"n":"第五条","txt":"省、自治区、直辖市人民政府住房城乡建设主管部门应当会同有关主管部门按照本办法规定的审查机构条件，结合本行政区域内的建设规模，确定相应数量的审查机构，逐步推行以政府购买服务方式开展施工图设计文件审查。具体办法由国务院住房城乡建设主管部门另行规定。 审查机构是专门从事施工图审查业务，不以营利为目的的独立法人。 省、自治区、直辖市人民政府住房城乡建设主管部门应当将审查机构名录报国务院住房城乡建设主管部门备案，并向社会公布。"},{"i":6,"n":"第六条","txt":"审查机构按承接业务范围分两类，一类机构承接房屋建筑、市政基础设施工程施工图审查业务范围不受限制；二类机构可以承接中型及以下房屋建筑、市政基础设施工程的施工图审查。 房屋建筑、市政基础设施工程的规模划分，按照国务院住房城乡建设主管部门的有关规定执行。"},{"i":7,"n":"第七条","txt":"一类审查机构应当具备下列条件： （一）有健全的技术管理和质量保证体系。 （二）审查人员应当有良好的职业道德；有15年以上所需专业勘察、设计工作经历；主持过不少于5项大型房屋建筑工程、市政基础设施工程相应专业的设计或者甲级工程勘察项目相应专业的勘察；已实行执业注册制度的专业，审查人员应当具有一级注册建筑师、一级注册结构工程师或者勘察设计注册工程师资格，并在本审查机构注册；未实行执业注册制度的专业，审查人员应当具有高级工程师职称；近5年内未因违反工程建设法律法规和强制性标准受到行政处罚。 （三）在本审查机构专职工作的审查人员数量：从事房屋建筑工程施工图审查的，结构专业审查人员不少于7人，建筑专业不少于3人，电气、暖通、给排水、勘察等专业审查人员各不少于2人；从事市政基础设施工程施工图审查的，所需专业的审查人员不少于7人，其他必须配套的专业审查人员各不少于2人；专门从事勘察文件审查的，勘察专"},{"i":8,"n":"第八条","txt":"二类审查机构应当具备下列条件： （一）有健全的技术管理和质量保证体系。 （二）审查人员应当有良好的职业道德；有10年以上所需专业勘察、设计工作经历；主持过不少于5项中型以上房屋建筑工程、市政基础设施工程相应专业的设计或者乙级以上工程勘察项目相应专业的勘察；已实行执业注册制度的专业，审查人员应当具有一级注册建筑师、一级注册结构工程师或者勘察设计注册工程师资格，并在本审查机构注册；未实行执业注册制度的专业，审查人员应当具有高级工程师职称；近5年内未因违反工程建设法律法规和强制性标准受到行政处罚。 （三）在本审查机构专职工作的审查人员数量：从事房屋建筑工程施工图审查的，结构专业审查人员不少于3人，建筑、电气、暖通、给排水、勘察等专业审查人员各不少于2人；从事市政基础设施工程施工图审查的，所需专业的审查人员不少于4人，其他必须配套的专业审查人员各不少于2人；专门从事勘察文件审查的，勘察专业审查"},{"i":9,"n":"第九条","txt":"建设单位应当将施工图送审查机构审查，但审查机构不得与所审查项目的建设单位、勘察设计企业有隶属关系或者其他利害关系。送审管理的具体办法由省、自治区、直辖市人民政府住房城乡建设主管部门按照“公开、公平、公正”的原则规定。 建设单位不得明示或者暗示审查机构违反法律法规和工程建设强制性标准进行施工图审查，不得压缩合理审查周期、压低合理审查费用。"},{"i":10,"n":"第十条","txt":"建设单位应当向审查机构提供下列资料并对所提供资料的真实性负责： （一）作为勘察、设计依据的政府有关部门的批准文件及附件； （二）全套施工图； （三）其他应当提交的材料。"},{"i":11,"n":"第十一条","txt":"审查机构应当对施工图审查下列内容： （一）是否符合工程建设强制性标准； （二）地基基础和主体结构的安全性； （三）消防安全性； （四）人防工程（不含人防指挥工程）防护安全性； （五）是否符合民用建筑节能强制性标准，对执行绿色建筑标准的项目，还应当审查是否符合绿色建筑标准； （六）勘察设计企业和注册执业人员以及相关人员是否按规定在施工图上加盖相应的图章和签字； （七）法律、法规、规章规定必须审查的其他内容。"},{"i":12,"n":"第十二条","txt":"施工图审查原则上不超过下列时限： （一）大型房屋建筑工程、市政基础设施工程为15个工作日，中型及以下房屋建筑工程、市政基础设施工程为10个工作日。 （二）工程勘察文件，甲级项目为7个工作日，乙级及以下项目为5个工作日。 以上时限不包括施工图修改时间和审查机构的复审时间。"},{"i":13,"n":"第十三条","txt":"审查机构对施工图进行审查后，应当根据下列情况分别作出处理： （一）审查合格的，审查机构应当向建设单位出具审查合格书，并在全套施工图上加盖审查专用章。审查合格书应当有各专业的审查人员签字，经法定代表人签发，并加盖审查机构公章。审查机构应当在出具审查合格书后5个工作日内，将审查情况报工程所在地县级以上地方人民政府住房城乡建设主管部门备案。 （二）审查不合格的，审查机构应当将施工图退建设单位并出具审查意见告知书，说明不合格原因。 同时，应当将审查意见告知书及审查中发现的建设单位、勘察设计企业和注册执业人员违反法律、法规和工程建设强制性标准的问题，报工程所在地县级以上地方人民政府住房城乡建设主管部门。 施工图退建设单位后，建设单位应当要求原勘察设计企业进行修改，并将修改后的施工图送原审查机构复审。"},{"i":14,"n":"第十四条","txt":"任何单位或者个人不得擅自修改审查合格的施工图；确需修改的，凡涉及本办法第十一条规定内容的，建设单位应当将修改后的施工图送原审查机构审查。"},{"i":15,"n":"第十五条","txt":"勘察设计企业应当依法进行建设工程勘察、设计，严格执行工程建设强制性标准，并对建设工程勘察、设计的质量负责。 审查机构对施工图审查工作负责，承担审查责任。施工图经审查合格后，仍有违反法律、法规和工程建设强制性标准的问题，给建设单位造成损失的，审查机构依法承担相应的赔偿责任。"},{"i":16,"n":"第十六条","txt":"审查机构应当建立、健全内部管理制度。施工图审查应当有经各专业审查人员签字的审查记录。审查记录、审查合格书、审查意见告知书等有关资料应当归档保存。"},{"i":17,"n":"第十七条","txt":"已实行执业注册制度的专业，审查人员应当按规定参加执业注册继续教育。 未实行执业注册制度的专业，审查人员应当参加省、自治区、直辖市人民政府住房城乡建设主管部门组织的有关法律、法规和技术标准的培训，每年培训时间不少于40学时。"},{"i":18,"n":"第十八条","txt":"按规定应当进行审查的施工图，未经审查合格的，住房城乡建设主管部门不得颁发施工许可证。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府住房城乡建设主管部门应当加强对审查机构的监督检查，主要检查下列内容： （一）是否符合规定的条件； （二）是否超出范围从事施工图审查； （三）是否使用不符合条件的审查人员； （四）是否按规定的内容进行审查； （五）是否按规定上报审查过程中发现的违法违规行为； （六）是否按规定填写审查意见告知书； （七）是否按规定在审查合格书和施工图上签字盖章； （八）是否建立健全审查机构内部管理制度； （九）审查人员是否按规定参加继续教育。 县级以上人民政府住房城乡建设主管部门实施监督检查时，有权要求被检查的审查机构提供有关施工图审查的文件和资料，并将监督检查结果向社会公布。 涉及消防安全性、人防工程（不含人防指挥工程）防护安全性的，由县级以上人民政府有关部门按照职责分工实施监督检查和行政处罚，并将监督检查结果向社会公布。"},{"i":20,"n":"第二十条","txt":"审查机构应当向县级以上地方人民政府住房城乡建设主管部门报审查情况统计信息。 县级以上地方人民政府住房城乡建设主管部门应当定期对施工图审查情况进行统计，并将统计信息报上级住房城乡建设主管部门。"},{"i":21,"n":"第二十一条","txt":"县级以上人民政府住房城乡建设主管部门应当及时受理对施工图审查工作中违法、违规行为的检举、控告和投诉。"},{"i":22,"n":"第二十二条","txt":"县级以上人民政府住房城乡建设主管部门对审查机构报告的建设单位、勘察设计企业、注册执业人员的违法违规行为，应当依法进行查处。"},{"i":23,"n":"第二十三条","txt":"审查机构列入名录后不再符合规定条件的，省、自治区、直辖市人民政府住房城乡建设主管部门应当责令其限期改正；逾期不改的，不再将其列入审查机构名录。"},{"i":24,"n":"第二十四条","txt":"审查机构违反本办法规定，有下列行为之一的，由县级以上地方人民政府住房城乡建设主管部门责令改正，处3万元罚款，并记入信用档案；情节严重的，省、自治区、直辖市人民政府住房城乡建设主管部门不再将其列入审查机构名录： （一）超出范围从事施工图审查的； （二）使用不符合条件审查人员的； （三）未按规定的内容进行审查的； （四）未按规定上报审查过程中发现的违法违规行为的； （五）未按规定填写审查意见告知书的； （六）未按规定在审查合格书和施工图上签字盖章的； （七）已出具审查合格书的施工图，仍有违反法律、法规和工程建设强制性标准的。"},{"i":25,"n":"第二十五条","txt":"审查机构出具虚假审查合格书的，审查合格书无效，县级以上地方人民政府住房城乡建设主管部门处3万元罚款，省、自治区、直辖市人民政府住房城乡建设主管部门不再将其列入审查机构名录。 审查人员在虚假审查合格书上签字的，终身不得再担任审查人员；对于已实行执业注册制度的专业的审查人员，还应当依照《建设工程质量管理条例》第七十二条、《建设工程安全生产管理条例》第五十八条规定予以处罚。"},{"i":26,"n":"第二十六条","txt":"建设单位违反本办法规定，有下列行为之一的，由县级以上地方人民政府住房城乡建设主管部门责令改正，处3万元罚款；情节严重的，予以通报： （一）压缩合理审查周期的； （二）提供不真实送审资料的； （三）对审查机构提出不符合法律、法规和工程建设强制性标准要求的。 建设单位为房地产开发企业的，还应当依照《房地产开发企业资质管理规定》进行处理。"},{"i":27,"n":"第二十七条","txt":"依照本办法规定，给予审查机构罚款处罚的，对机构的法定代表人和其他直接责任人员处机构罚款数额5%以上10%以下的罚款，并记入信用档案。"},{"i":28,"n":"第二十八条","txt":"省、自治区、直辖市人民政府住房城乡建设主管部门未按照本办法规定确定审查机构的，国务院住房城乡建设主管部门责令改正。"},{"i":29,"n":"第二十九条","txt":"国家机关工作人员在施工图审查监督管理工作中玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":30,"n":"第三十条","txt":"省、自治区、直辖市人民政府住房城乡建设主管部门可以根据本办法，制定实施细则。"},{"i":31,"n":"第三十一条","txt":"本办法自2013年8月1日起施行。原建设部2004年8月23日发布的《房屋建筑和市政基础设施工程施工图设计文件审查管理办法》（建设部令第134号）同时废止。"}],"fangwujianzhuheshizhengjichusheshigongchengshigongddf637":[{"i":1,"n":"第一条","txt":"为了规范房屋建筑和市政基础设施工程施工招标投标活动，维护招标投标当事人的合法权益，依据《中华人民共和国建筑法》、《中华人民共和国招标投标法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"依法必须进行招标的房屋建筑和市政基础设施工程（以下简称工程），其施工招标投标活动，适用本办法。 本办法所称房屋建筑工程，是指各类房屋建筑及其附属设施和与其配套的线路、管道、设备安装工程及室内外装修工程。 本办法所称市政基础设施工程，是指城市道路、公共交通、供水、排水、燃气、热力、园林、环卫、污水处理、垃圾处理、防洪、地下公共设施及附属设施的土建、管道、设备安装工程。"},{"i":3,"n":"第三条","txt":"国务院建设行政主管部门负责全国工程施工招标投标活动的监督管理。 县级以上地方人民政府建设行政主管部门负责本行政区域内工程施工招标投标活动的监督管理。具体的监督管理工作，可以委托工程招标投标监督管理机构负责实施。"},{"i":4,"n":"第四条","txt":"任何单位和个人不得违反法律、行政法规规定，限制或者排斥本地区、本系统以外的法人或者其他组织参加投标，不得以任何方式非法干涉施工招标投标活动。"},{"i":5,"n":"第五条","txt":"施工招标投标活动及其当事人应当依法接受监督。 建设行政主管部门依法对施工招标投标活动实施监督，查处施工招标投标活动中的违法行为。"},{"i":6,"n":"第六条","txt":"工程施工招标由招标人依法组织实施。招标人不得以不合理条件限制或者排斥潜在投标人，不得对潜在投标人实行歧视待遇，不得对潜在投标人提出与招标工程实际要求不符的过高的资质等级要求和其他要求。"},{"i":7,"n":"第七条","txt":"工程施工招标应当具备下列条件： （一）按照国家有关规定需要履行项目审批手续的，已经履行审批手续； （二）工程资金或者资金来源已经落实； （三）有满足施工招标需要的设计文件及其他技术资料； （四）法律、法规、规章规定的其他条件。"},{"i":8,"n":"第八条","txt":"工程施工招标分为公开招标和邀请招标。 依法必须进行施工招标的工程，全部使用国有资金投资或者国有资金投资占控股或者主导地位的，应当公开招标，但经国家计委或者省、自治区、直辖市人民政府依法批准可以进行邀请招标的重点建设项目除外；其他工程可以实行邀请招标。"},{"i":9,"n":"第九条","txt":"工程有下列情形之一的，经县级以上地方人民政府建设行政主管部门批准，可以不进行施工招标： （一）停建或者缓建后恢复建设的单位工程，且承包人未发生变更的； （二）施工企业自建自用的工程，且该施工企业资质等级符合工程要求的； （三）在建工程追加的附属小型工程或者主体加层工程，且承包人未发生变更的； （四）法律、法规、规章规定的其他情形。"},{"i":10,"n":"第十条","txt":"依法必须进行施工招标的工程，招标人自行办理施工招标事宜的，应当具有编制招标文件和组织评标的能力： （一）有专门的施工招标组织机构； （二）有与工程规模、复杂程度相适应并具有同类工程施工招标经验、熟悉有关工程施工招标法律法规的工程技术、概预算及工程管理的专业人员。 不具备上述条件的，招标人应当委托工程招标代理机构代理施工招标。"},{"i":11,"n":"第十一条","txt":"招标人自行办理施工招标事宜的，应当在发布招标公告或者发出投标邀请书的５日前，向工程所在地县级以上地方人民政府建设行政主管部门备案，并报送下列材料： （一）按照国家有关规定办理审批手续的各项批准文件； （二）本办法第十一条所列条件的证明材料，包括专业技术人员的名单、职称证书或者执业资格证书及其工作经历的证明材料； （三）法律、法规、规章规定的其他材料。 招标人不具备自行办理施工招标事宜条件的，建设行政主管部门应当自收到备案材料之日起５日内责令招标人停止自行办理施工招标事宜。"},{"i":12,"n":"第十二条","txt":"全部使用国有资金投资或者国有资金投资占控股或者主导地位，依法必须进行施工招标的工程项目，应当进入有形建筑市场进行招标投标活动。 政府有关管理机关可以在有形建筑市场集中办理有关手续，并依法实施监督。"},{"i":13,"n":"第十三条","txt":"依法必须进行施工公开招标的工程项目，应当在国家或者地方指定的报刊、信息网络或者其他媒介上发布招标公告，并同时在中国工程建设和建筑业信息网上发布招标公告。 招标公告应当载明招标人的名称和地址，招标工程的性质、规模、地点以及获取招标文件的办法等事项。"},{"i":14,"n":"第十四条","txt":"招标人采用邀请招标方式的，应当向３个以上符合资质条件的施工企业发出投标邀请书。 投标邀请书应当载明本办法第十四条第二款规定的事项。"},{"i":15,"n":"第十五条","txt":"招标人可以根据招标工程的需要，对投标申请人进行资格预审，也可以委托工程招标代理机构对投标申请人进行资格预审。实行资格预审的招标工程，招标人应当在招标公告或者投标邀请书中载明资格预审的条件和获取资格预审文件的办法。 资格预审文件一般应当包括资格预审申请书格式、申请人须知，以及需要投标申请人提供的企业资质、业绩、技术装备、财务状况和拟派出的项目经理与主要技术人员的简历、业绩等证明材料。"},{"i":16,"n":"第十六条","txt":"经资格预审后，招标人应当向资格预审合格的投标申请人发出资格预审合格通知书，告知获取招标文件的时间、地点和方法，并同时向资格预审不合格的投标申请人告知资格预审结果。 在资格预审合格的投标申请人过多时，可以由招标人从中选择不少于７家资格预审合格的投标申请人。"},{"i":17,"n":"第十七条","txt":"招标人应当根据招标工程的特点和需要，自行或者委托工程招标代理机构编制招标文件。招标文件应当包括下列内容： （一）投标须知，包括工程概况，招标范围，资格审查条件，工程资金来源或者落实情况，标段划分，工期要求，质量标准，现场踏勘和答疑安排，投标文件编制、提交、修改、撤回的要求，投标报价要求，投标有效期，开标的时间和地点，评标的方法和标准等； （二）招标工程的技术要求和设计文件； （三）采用工程量清单招标的，应当提供工程量清单； （四）投标函的格式及附录； （五）拟签订合同的主要条款； （六）要求投标人提交的其他材料。"},{"i":18,"n":"第十八条","txt":"依法必须进行施工招标的工程，招标人应当在招标文件发出的同时，将招标文件报工程所在地的县级以上地方人民政府建设行政主管部门备案，但实施电子招标投标的项目除外。建设行政主管部门发现招标文件有违反法律、法规内容的，应当责令招标人改正。"},{"i":19,"n":"第十九条","txt":"招标人对已发出的招标文件进行必要的澄清或者修改的，应当在招标文件要求提交投标文件截止时间至少15日前，以书面形式通知所有招标文件收受人，并同时报工程所在地的县级以上地方人民政府建设行政主管部门备案，但实施电子招标投标的项目除外。该澄清或者修改的内容为招标文件的组成部分。"},{"i":20,"n":"第二十条","txt":"招标人设有标底的，应当依据国家规定的工程量计算规则及招标文件规定的计价方法和要求编制标底，并在开标前保密。一个招标工程只能编制一个标底。"},{"i":21,"n":"第二十一条","txt":"招标人对于发出的招标文件可以酌收工本费。其中的设计文件，招标人可以酌收押金。对于开标后将设计文件退还的，招标人应当退还押金。"},{"i":22,"n":"第二十二条","txt":"施工招标的投标人是响应施工招标、参与投标竞争的施工企业。 投标人应当具备相应的施工企业资质，并在工程业绩、技术能力、项目经理资格条件、财务状况等方面满足招标文件提出的要求。"},{"i":23,"n":"第二十三条","txt":"投标人对招标文件有疑问需要澄清的，应当以书面形式向招标人提出。"},{"i":24,"n":"第二十四条","txt":"投标人应当按照招标文件的要求编制投标文件，对招标文件提出的实质性要求和条件作出响应。 招标文件允许投标人提供备选标的，投标人可以按照招标文件的要求提交替代方案，并作出相应报价作备选标。"},{"i":25,"n":"第二十五条","txt":"投标文件应当包括下列内容： （一）投标函； （二）施工组织设计或者施工方案； （三）投标报价； （四）招标文件要求提供的其他材料。"},{"i":26,"n":"第二十六条","txt":"招标人可以在招标文件中要求投标人提交投标担保。投标担保可以采用投标保函或者投标保证金的方式。投标保证金可以使用支票、银行汇票等，一般不得超过投标总价的2％，最高不得超过50万元。 投标人应当按照招标文件要求的方式和金额，将投标保函或者投标保证金随投标文件提交招标人。"},{"i":27,"n":"第二十七条","txt":"投标人应当在招标文件要求提交投标文件的截止时间前，将投标文件密封送达投标地点。招标人收到投标文件后，应当向投标人出具标明签收人和签收时间的凭证，并妥善保存投标文件。在开标前，任何单位和个人均不得开启投标文件。在招标文件要求提交投标文件的截止时间后送达的投标文件，为无效的投标文件，招标人应当拒收。 提交投标文件的投标人少于3个的，招标人应当依法重新招标。"},{"i":28,"n":"第二十八条","txt":"投标人在招标文件要求提交投标文件的截止时间前，可以补充、修改或者撤回已提交的投标文件。补充、修改的内容为投标文件的组成部分，并应当按照本办法第二十八条第一款的规定送达、签收和保管。在招标文件要求提交投标文件的截止时间后送达的补充或者修改的内容无效。"},{"i":29,"n":"第二十九条","txt":"两个以上施工企业可以组成一个联合体，签订共同投标协议，以一个投标人的身份共同投标。联合体各方均应当具备承担招标工程的相应资质条件。相同专业的施工企业组成的联合体，按照资质等级低的施工企业的业务许可范围承揽工程。 招标人不得强制投标人组成联合体共同投标，不得限制投标人之间的竞争。"},{"i":30,"n":"第三十条","txt":"投标人不得相互串通投标，不得排挤其他投标人的公平竞争，损害招标人或者其他投标人的合法权益。 投标人不得与招标人串通投标，损害国家利益、社会公共利益或者他人的合法权益。 禁止投标人以向招标人或者评标委员会成员行贿的手段谋取中标。"},{"i":31,"n":"第三十一条","txt":"投标人不得以低于其企业成本的报价竞标，不得以他人名义投标或者以其他方式弄虚作假，骗取中标。"},{"i":32,"n":"第三十二条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开进行；开标地点应当为招标文件中预先确定的地点。"},{"i":33,"n":"第三十三条","txt":"开标由招标人主持，邀请所有投标人参加。开标应当按照下列规定进行： 由投标人或者其推选的代表检查投标文件的密封情况，也可以由招标人委托的公证机构进行检查并公证。经确认无误后，由有关工作人员当众拆封，宣读投标人名称、投标价格和投标文件的其他主要内容。 招标人在招标文件要求提交投标文件的截止时间前收到的所有投标文件，开标时都应当当众予以拆封、宣读。 开标过程应当记录，并存档备查。"},{"i":34,"n":"第三十四条","txt":"在开标时，投标文件出现下列情形之一的，应当作为无效投标文件，不得进入评标： （一）投标文件未按照招标文件的要求予以密封的； （二）投标文件中的投标函未加盖投标人的企业及企业法定代表人印章的，或者企业法定代表人委托代理人没有合法、有效的委托书（原件）及委托代理人印章的； （三）投标文件的关键内容字迹模糊、无法辨认的； （四）投标人未按照招标文件的要求提供投标保函或者投标保证金的； （五）组成联合体投标的，投标文件未附联合体各方共同投标协议的。"},{"i":35,"n":"第三十五条","txt":"评标由招标人依法组建的评标委员会负责。 依法必须进行施工招标的工程，其评标委员会由招标人的代表和有关技术、经济等方面的专家组成，成员人数为５人以上单数，其中招标人、招标代理机构以外的技术、经济等方面专家不得少于成员总数的三分之二。评标委员会的专家成员，应当由招标人从建设行政主管部门及其他有关政府部门确定的专家名册或者工程招标代理机构的专家库内相关专业的专家名单中确定。确定专家成员一般应当采取随机抽取的方式。 与投标人有利害关系的人不得进入相关工程的评标委员会。评标委员会成员的名单在中标结果确定前应当保密。"},{"i":36,"n":"第三十六条","txt":"建设行政主管部门的专家名册应当拥有一定数量规模并符合法定资格条件的专家。省、自治区、直辖市人民政府建设行政主管部门可以将专家数量少的地区的专家名册予以合并或者实行专家名册计算机联网。 建设行政主管部门应当对进入专家名册的专家组织有关法律和业务培训，对其评标能力、廉洁公正等进行综合评估，及时取消不称职或者违法违规人员的评标专家资格。被取消评标专家资格的人员，不得再参加任何评标活动。"},{"i":37,"n":"第三十七条","txt":"评标委员会应当按照招标文件确定的评标标准和方法，对投标文件进行评审和比较，并对评标结果签字确认；设有标底的，应当参考标底。"},{"i":38,"n":"第三十八条","txt":"评标委员会可以用书面形式要求投标人对投标文件中含义不明确的内容作必要的澄清或者说明。投标人应当采用书面形式进行澄清或者说明，其澄清或者说明不得超出投标文件的范围或者改变投标文件的实质性内容。"},{"i":39,"n":"第三十九条","txt":"评标委员会经评审，认为所有投标文件都不符合招标文件要求的，可以否决所有投标。 依法必须进行施工招标工程的所有投标被否决的，招标人应当依法重新招标。"},{"i":40,"n":"第四十条","txt":"评标可以采用综合评估法、经评审的最低投标价法或者法律法规允许的其他评标方法。 采用综合评估法的，应当对投标文件提出的工程质量、施工工期、投标价格、施工组织设计或者施工方案、投标人及项目经理业绩等，能否最大限度地满足招标文件中规定的各项要求和评价标准进行评审和比较。以评分方式进行评估的，对于各种评比奖项不得额外计分。 采用经评审的最低投标价法的，应当在投标文件能够满足招标文件实质性要求的投标人中，评审出投标价格最低的投标人，但投标价格低于其企业成本的除外。"},{"i":41,"n":"第四十一条","txt":"评标委员会完成评标后，应当向招标人提出书面评标报告，阐明评标委员会对各投标文件的评审和比较意见，并按照招标文件中规定的评标方法，推荐不超过３名有排序的合格的中标候选人。招标人根据评标委员会提出的书面评标报告和推荐的中标候选人确定中标人。 使用国有资金投资或者国家融资的工程项目，招标人应当按照中标候选人的排序确定中标人。当确定中标的中标候选人放弃中标或者因不可抗力提出不能履行合同的，招标人可以依序确定其他中标候选人为中标人。 招标人也可以授权评标委员会直接确定中标人。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，评标委员会可以要求投标人作出书面说明并提供相关材料： （一）设有标底的，投标报价低于标底合理幅度的； （二）不设标底的，投标报价明显低于其他投标报价，有可能低于其企业成本的。 经评标委员会论证，认定该投标人的报价低于其企业成本的，不能推荐为中标候选人或者中标人。"},{"i":43,"n":"第四十三条","txt":"招标人应当在投标有效期截止时限30日前确定中标人。投标有效期应当在招标文件中载明。"},{"i":44,"n":"第四十四条","txt":"依法必须进行施工招标的工程，招标人应当自确定中标人之日起15日内，向工程所在地的县级以上地方人民政府建设行政主管部门提交施工招标投标情况的书面报告。书面报告应当包括下列内容： （一）施工招标投标的基本情况，包括施工招标范围、施工招标方式、资格审查、开评标过程和确定中标人的方式及理由等。 （二）相关的文件资料，包括招标公告或者投标邀请书、投标报名表、资格预审文件、招标文件、评标委员会的评标报告（设有标底的，应当附标底）、中标人的投标文件。委托工程招标代理的，还应当附工程施工招标代理委托合同。 前款第二项中已按照本办法的规定办理了备案的文件资料，不再重复提交。"},{"i":45,"n":"第四十五条","txt":"建设行政主管部门自收到书面报告之日起5日内未通知招标人在招标投标活动中有违法行为的，招标人可以向中标人发出中标通知书，并将中标结果通知所有未中标的投标人。"},{"i":46,"n":"第四十六条","txt":"招标人和中标人应当自中标通知书发出之日起30日内，按照招标文件和中标人的投标文件订立书面合同；招标人和中标人不得再行订立背离合同实质性内容的其他协议。 中标人不与招标人订立合同的，投标保证金不予退还并取消其中标资格，给招标人造成的损失超过投标保证金数额的，应当对超过部分予以赔偿；没有提交投标保证金的，应当对招标人的损失承担赔偿责任。 招标人无正当理由不与中标人签订合同，给中标人造成损失的，招标人应当给予赔偿。"},{"i":47,"n":"第四十七条","txt":"招标文件要求中标人提交履约担保的，中标人应当提交。招标人应当同时向中标人提供工程款支付担保。"},{"i":48,"n":"第四十八条","txt":"有违反《招标投标法》行为的，县级以上地方人民政府建设行政主管部门应当按照《招标投标法》的规定予以处罚。"},{"i":49,"n":"第四十九条","txt":"招标投标活动中有《招标投标法》规定中标无效情形的，由县级以上地方人民政府建设行政主管部门宣布中标无效，责令重新组织招标，并依法追究有关责任人责任。"},{"i":50,"n":"第五十条","txt":"应当招标未招标的，应当公开招标未公开招标的，县级以上地方人民政府建设行政主管部门应当责令改正，拒不改正的，不得颁发施工许可证。"},{"i":51,"n":"第五十一条","txt":"招标人不具备自行办理施工招标事宜条件而自行招标的，县级以上地方人民政府建设行政主管部门应当责令改正，处１万元以下的罚款。"},{"i":52,"n":"第五十二条","txt":"评标委员会的组成不符合法律、法规规定的，县级以上地方人民政府建设行政主管部门应当责令招标人重新组织评标委员会。"},{"i":53,"n":"第五十三条","txt":"招标人未向建设行政主管部门提交施工招标投标情况书面报告的，县级以上地方人民政府建设行政主管部门应当责令改正。"},{"i":54,"n":"第五十四条","txt":"工程施工专业分包、劳务分包采用招标方式的，参照本办法执行。"},{"i":55,"n":"第五十五条","txt":"招标文件或者投标文件使用两种以上语言文字的，必须有一种是中文；如对不同文本的解释发生异议的，以中文文本为准。用文字表示的金额与数字表示的金额不一致的，以文字表示的金额为准。"},{"i":56,"n":"第五十六条","txt":"涉及国家安全、国家秘密、抢险救灾或者属于利用扶贫资金实行以工代赈、需要使用农民工等特殊情况，不适宜进行施工招标的工程，按照国家有关规定可以不进行施工招标。"},{"i":57,"n":"第五十七条","txt":"使用国际组织或者外国政府贷款、援助资金的工程进行施工招标，贷款方、资金提供方对招标投标的具体条件和程序有不同规定的，可以适用其规定，但违背中华人民共和国的社会公共利益的除外。"},{"i":58,"n":"第五十八条","txt":"本办法由国务院建设行政主管部门负责解释。"},{"i":59,"n":"第五十九条","txt":"本办法自发布之日起施行。1992年12月30日建设部颁布的《工程建设施工招标投标管理办法》（建设部令第23号）同时废止。"}],"fangwujianzhuheshizhengjichusheshigongchengjungongd4c8e3":[{"i":1,"n":"第一条","txt":"为了加强房屋建筑和市政基础设施工程质量的管理，根据《建设工程质量管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内新建、扩建、改建各类房屋建筑和市政基础设施工程的竣工验收备案，适用本办法。"},{"i":3,"n":"第三条","txt":"国务院住房和城乡建设主管部门负责全国房屋建筑和市政基础设施工程（以下统称工程）的竣工验收备案管理工作。 县级以上地方人民政府建设主管部门负责本行政区域内工程的竣工验收备案管理工作。"},{"i":4,"n":"第四条","txt":"建设单位应当自工程竣工验收合格之日起15日内，依照本办法规定，向工程所在地的县级以上地方人民政府建设主管部门（以下简称备案机关）备案。"},{"i":5,"n":"第五条","txt":"建设单位办理工程竣工验收备案应当提交下列文件： （一）工程竣工验收备案表； （二）工程竣工验收报告。竣工验收报告应当包括工程报建日期，施工许可证号，施工图设计文件审查意见，勘察、设计、施工、工程监理等单位分别签署的质量合格文件及验收人员签署的竣工验收原始文件，市政基础设施的有关质量检测和功能性试验资料以及备案机关认为需要提供的有关资料； （三）法律、行政法规规定应当由规划、环保等部门出具的认可文件或者准许使用文件； （四）法律规定应当由公安消防部门出具的对大型的人员密集场所和其他特殊建设工程验收合格的证明文件； （五）施工单位签署的工程质量保修书； （六）法规、规章规定必须提供的其他文件。 住宅工程还应当提交《住宅质量保证书》和《住宅使用说明书》。"},{"i":6,"n":"第六条","txt":"备案机关收到建设单位报送的竣工验收备案文件，验证文件齐全后，应当在工程竣工验收备案表上签署文件收讫。 工程竣工验收备案表一式两份，一份由建设单位保存，一份留备案机关存档。"},{"i":7,"n":"第七条","txt":"工程质量监督机构应当在工程竣工验收之日起5日内，向备案机关提交工程质量监督报告。"},{"i":8,"n":"第八条","txt":"备案机关发现建设单位在竣工验收过程中有违反国家有关建设工程质量管理规定行为的，应当在收讫竣工验收备案文件15日内，责令停止使用，重新组织竣工验收。"},{"i":9,"n":"第九条","txt":"建设单位在工程竣工验收合格之日起15日内未办理工程竣工验收备案的，备案机关责令限期改正，处20万元以上50万元以下罚款。"},{"i":10,"n":"第十条","txt":"建设单位将备案机关决定重新组织竣工验收的工程，在重新组织竣工验收前，擅自使用的，备案机关责令停止使用，处工程合同价款2％以上4％以下罚款。"},{"i":11,"n":"第十一条","txt":"建设单位采用虚假证明文件办理工程竣工验收备案的，工程竣工验收无效，备案机关责令停止使用，重新组织竣工验收，处20万元以上50万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":12,"n":"第十二条","txt":"备案机关决定重新组织竣工验收并责令停止使用的工程，建设单位在备案之前已投入使用或者建设单位擅自继续使用造成使用人损失的，由建设单位依法承担赔偿责任。"},{"i":13,"n":"第十三条","txt":"竣工验收备案文件齐全，备案机关及其工作人员不办理备案手续的，由有关机关责令改正，对直接责任人员给予行政处分。"},{"i":14,"n":"第十四条","txt":"抢险救灾工程、临时性房屋建筑工程和农民自建低层住宅工程，不适用本办法。"},{"i":15,"n":"第十五条","txt":"军用房屋建筑工程竣工验收备案，按照中央军事委员会的有关规定执行。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市人民政府住房和城乡建设主管部门可以根据本办法制定实施细则。"},{"i":17,"n":"第十七条","txt":"本办法自发布之日起施行。"}],"fangwujianzhuheshizhengjichusheshigongchengzhilianfbc2d0":[{"i":1,"n":"第一条","txt":"为了加强房屋建筑和市政基础设施工程质量的监督，保护人民生命和财产安全，规范住房和城乡建设主管部门及工程质量监督机构（以下简称主管部门）的质量监督行为，根据《中华人民共和国建筑法》、《建设工程质量管理条例》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内主管部门实施对新建、扩建、改建房屋建筑和市政基础设施工程质量监督管理的，适用本规定。"},{"i":3,"n":"第三条","txt":"国务院住房和城乡建设主管部门负责全国房屋建筑和市政基础设施工程（以下简称工程）质量监督管理工作。 县级以上地方人民政府建设主管部门负责本行政区域内工程质量监督管理工作。 工程质量监督管理的具体工作可以由县级以上地方人民政府建设主管部门委托所属的工程质量监督机构（以下简称监督机构）实施。"},{"i":4,"n":"第四条","txt":"本规定所称工程质量监督管理，是指主管部门依据有关法律法规和工程建设强制性标准，对工程实体质量和工程建设、勘察、设计、施工、监理单位（以下简称工程质量责任主体）和质量检测等单位的工程质量行为实施监督。 本规定所称工程实体质量监督，是指主管部门对涉及工程主体结构安全、主要使用功能的工程实体质量情况实施监督。 本规定所称工程质量行为监督，是指主管部门对工程质量责任主体和质量检测等单位履行法定质量责任和义务的情况实施监督。"},{"i":5,"n":"第五条","txt":"工程质量监督管理应当包括下列内容： （一）执行法律法规和工程建设强制性标准的情况； （二）抽查涉及工程主体结构安全和主要使用功能的工程实体质量； （三）抽查工程质量责任主体和质量检测等单位的工程质量行为； （四）抽查主要建筑材料、建筑构配件的质量； （五）对工程竣工验收进行监督； （六）组织或者参与工程质量事故的调查处理； （七）定期对本地区工程质量状况进行统计分析； （八）依法对违法违规行为实施处罚。"},{"i":6,"n":"第六条","txt":"对工程项目实施质量监督，应当依照下列程序进行： （一）受理建设单位办理质量监督手续； （二）制订工作计划并组织实施； （三）对工程实体质量、工程质量责任主体和质量检测等单位的工程质量行为进行抽查、抽测； （四）监督工程竣工验收，重点对验收的组织形式、程序等是否符合有关规定进行监督； （五）形成工程质量监督报告； （六）建立工程质量监督档案。"},{"i":7,"n":"第七条","txt":"工程竣工验收合格后，建设单位应当在建筑物明显部位设置永久性标牌，载明建设、勘察、设计、施工、监理单位等工程质量责任主体的名称和主要责任人姓名。"},{"i":8,"n":"第八条","txt":"主管部门实施监督检查时，有权采取下列措施： （一）要求被检查单位提供有关工程质量的文件和资料； （二）进入被检查单位的施工现场进行检查； （三）发现有影响工程质量的问题时，责令改正。"},{"i":9,"n":"第九条","txt":"县级以上地方人民政府建设主管部门应当根据本地区的工程质量状况，逐步建立工程质量信用档案。"},{"i":10,"n":"第十条","txt":"县级以上地方人民政府建设主管部门应当将工程质量监督中发现的涉及主体结构安全和主要使用功能的工程质量问题及整改情况，及时向社会公布。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市人民政府建设主管部门应当按照国家有关规定，对本行政区域内监督机构每三年进行一次考核。 监督机构经考核合格后，方可依法对工程实施质量监督，并对工程质量监督承担监督责任。"},{"i":12,"n":"第十二条","txt":"监督机构应当具备下列条件： （一）具有符合本规定第十三条规定的监督人员。人员数量由县级以上地方人民政府建设主管部门根据实际需要确定。监督人员应当占监督机构总人数的75%以上； （二）有固定的工作场所和满足工程质量监督检查工作需要的仪器、设备和工具等； （三）有健全的质量监督工作制度，具备与质量监督工作相适应的信息化管理条件。"},{"i":13,"n":"第十三条","txt":"监督人员应当具备下列条件： （一）具有工程类专业大学专科以上学历或者工程类执业注册资格； （二）具有三年以上工程质量管理或者设计、施工、监理等工作经历； （三）熟悉掌握相关法律法规和工程建设强制性标准； （四）具有一定的组织协调能力和良好职业道德。 监督人员符合上述条件经考核合格后，方可从事工程质量监督工作。"},{"i":14,"n":"第十四条","txt":"监督机构可以聘请中级职称以上的工程类专业技术人员协助实施工程质量监督。"},{"i":15,"n":"第十五条","txt":"省、自治区、直辖市人民政府建设主管部门应当每两年对监督人员进行一次岗位考核，每年进行一次法律法规、业务知识培训，并适时组织开展继续教育培训。"},{"i":16,"n":"第十六条","txt":"国务院住房和城乡建设主管部门对监督机构和监督人员的考核情况进行监督抽查。"},{"i":17,"n":"第十七条","txt":"主管部门工作人员玩忽职守、滥用职权、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":18,"n":"第十八条","txt":"抢险救灾工程、临时性房屋建筑工程和农民自建低层住宅工程，不适用本规定。"},{"i":19,"n":"第十九条","txt":"省、自治区、直辖市人民政府建设主管部门可以根据本规定制定具体实施办法。"},{"i":20,"n":"第二十条","txt":"本规定自2010年9月1日起施行。"}],"fangwujianzhugongchengkangzhenshefangguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对房屋建筑工程抗震设防的监督管理，保护人民生命和财产安全，根据《中华人民共和国防震减灾法》、《中华人民共和国建筑法》、《建设工程质量管理条例》、《建设工程勘察设计管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在抗震设防区从事房屋建筑工程抗震设防的有关活动，实施对房屋建筑工程抗震设防的监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"房屋建筑工程的抗震设防，坚持预防为主的方针。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门负责全国房屋建筑工程抗震设防的监督管理工作。 县级以上地方人民政府住房城乡建设主管部门负责本行政区域内房屋建筑工程抗震设防的监督管理工作。"},{"i":5,"n":"第五条","txt":"国家鼓励采用先进的科学技术进行房屋建筑工程的抗震设防。 制定、修订工程建设标准时，应当及时将先进适用的抗震新技术、新材料和新结构体系纳入标准、规范，在房屋建筑工程中推广使用。"},{"i":6,"n":"第六条","txt":"新建、扩建、改建的房屋建筑工程，应当按照国家有关规定和工程建设强制性标准进行抗震设防。 任何单位和个人不得降低抗震设防标准。"},{"i":7,"n":"第七条","txt":"建设单位、勘察单位、设计单位、施工单位、工程监理单位，应当遵守有关房屋建筑工程抗震设防的法律、法规和工程建设强制性标准的规定，保证房屋建筑工程的抗震设防质量，依法承担相应责任。"},{"i":8,"n":"第八条","txt":"城市房屋建筑工程的选址，应当符合城市总体规划中城市抗震防灾专业规划的要求；村庄、集镇建设的工程选址，应当符合村庄与集镇防灾专项规划和村庄与集镇建设规划中有关抗震防灾的要求。"},{"i":9,"n":"第九条","txt":"房屋建筑工程勘察、设计文件中规定采用的新技术、新材料，可能影响房屋建筑工程抗震安全，又没有国家技术标准的，应当按照国家有关规定经检测和审定后，方可使用。"},{"i":10,"n":"第十条","txt":"《建筑工程抗震设防分类标准》中甲类和乙类建筑工程的初步设计文件应当有抗震设防专项内容。 超限高层建筑工程应当在初步设计阶段进行抗震设防专项审查。 新建、扩建、改建房屋建筑工程的抗震设计应当作为施工图审查的重要内容。"},{"i":11,"n":"第十一条","txt":"产权人和使用人不得擅自变动或者破坏房屋建筑抗震构件、隔震装置、减震部件或者地震反应观测系统等抗震设施。"},{"i":12,"n":"第十二条","txt":"已建成的下列房屋建筑工程，未采取抗震设防措施且未列入近期拆除改造计划的，应当委托具有相应设计资质的单位按现行抗震鉴定标准进行抗震鉴定： （一）《建筑工程抗震设防分类标准》中甲类和乙类建筑工程； （二）有重大文物价值和纪念意义的房屋建筑工程； （三）地震重点监视防御区的房屋建筑工程。 鼓励其他未采取抗震设防措施且未列入近期拆除改造计划的房屋建筑工程产权人，委托具有相应设计资质的单位按现行抗震鉴定标准进行抗震鉴定。 经鉴定需加固的房屋建筑工程，应当在县级以上地方人民政府住房城乡建设主管部门确定的限期内采取必要的抗震加固措施；未加固前应当限制使用。"},{"i":13,"n":"第十三条","txt":"从事抗震鉴定的单位，应当遵守有关房屋建筑工程抗震设防的法律、法规和工程建设强制性标准的规定，保证房屋建筑工程的抗震鉴定质量，依法承担相应责任。"},{"i":14,"n":"第十四条","txt":"对经鉴定需抗震加固的房屋建筑工程，产权人应当委托具有相应资质的设计、施工单位进行抗震加固设计与施工，并按国家规定办理相关手续。 抗震加固应当与城市近期建设规划、产权人的房屋维修计划相结合。经鉴定需抗震加固的房屋建筑工程在进行装修改造时，应当同时进行抗震加固。 有重大文物价值和纪念意义的房屋建筑工程的抗震加固，应当注意保持其原有风貌。"},{"i":15,"n":"第十五条","txt":"房屋建筑工程的抗震鉴定、抗震加固费用，由产权人承担。"},{"i":16,"n":"第十六条","txt":"已按工程建设标准进行抗震设计或抗震加固的房屋建筑工程在合理使用年限内，因各种人为因素使房屋建筑工程抗震能力受损的，或者因改变原设计使用性质，导致荷载增加或需提高抗震设防类别的，产权人应当委托有相应资质的单位进行抗震验算、修复或加固。需要进行工程检测的，应由委托具有相应资质的单位进行检测。"},{"i":17,"n":"第十七条","txt":"破坏性地震发生后，当地人民政府住房城乡建设主管部门应当组织对受损房屋建筑工程抗震性能的应急评估，并提出恢复重建方案。"},{"i":18,"n":"第十八条","txt":"震后经应急评估需进行抗震鉴定的房屋建筑工程，应当按照抗震鉴定标准进行鉴定。经鉴定需修复或者抗震加固的，应当按照工程建设强制性标准进行修复或者抗震加固。需易地重建的，应当按照国家有关法律、法规的规定进行规划和建设。"},{"i":19,"n":"第十九条","txt":"当发生地震的实际烈度大于现行地震动参数区划图对应的地震基本烈度时，震后修复或者建设的房屋建筑工程，应当以国家地震部门审定、发布的地震动参数复核结果，作为抗震设防的依据。"},{"i":20,"n":"第二十条","txt":"县级以上地方人民政府住房城乡建设主管部门应当加强对房屋建筑工程抗震设防质量的监督管理，并对本行政区域内房屋建筑工程执行抗震设防的法律、法规和工程建设强制性标准情况，定期进行监督检查。 县级以上地方人民政府住房城乡建设主管部门应当对村镇建设抗震设防进行指导和监督。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府住房城乡建设主管部门应当对农民自建低层住宅抗震设防进行技术指导和技术服务，鼓励和指导其采取经济、合理、可靠的抗震措施。 地震重点监视防御区县级以上地方人民政府住房城乡建设主管部门应当通过拍摄科普教育宣传片、发送农房抗震图集、建设抗震样板房、技术培训等多种方式，积极指导农民自建低层住宅进行抗震设防。"},{"i":22,"n":"第二十二条","txt":"县级以上地方人民政府住房城乡建设主管部门有权组织抗震设防检查，并采取下列措施： （一）要求被检查的单位提供有关房屋建筑工程抗震的文件和资料； （二）发现有影响房屋建筑工程抗震设防质量的问题时，责令改正。"},{"i":23,"n":"第二十三条","txt":"地震发生后，县级以上地方人民政府住房城乡建设主管部门应当组织专家，对破坏程度超出工程建设强制性标准允许范围的房屋建筑工程的破坏原因进行调查，并依法追究有关责任人的责任。 国务院住房城乡建设主管部门应当根据地震调查情况，及时组织力量开展房屋建筑工程抗震科学研究，并对相关工程建设标准进行修订。"},{"i":24,"n":"第二十四条","txt":"任何单位和个人对房屋建筑工程的抗震设防质量问题都有权检举和投诉。"},{"i":25,"n":"第二十五条","txt":"违反本规定，擅自使用没有国家技术标准又未经审定的新技术、新材料的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，并处以1万元以上3万元以下罚款。"},{"i":26,"n":"第二十六条","txt":"违反本规定，擅自变动或者破坏房屋建筑抗震构件、隔震装置、减震部件或者地震反应观测系统等抗震设施的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，并对个人处以1000元以下罚款，对单位处以1万元以上3万元以下罚款。"},{"i":27,"n":"第二十七条","txt":"违反本规定，未对抗震能力受损、荷载增加或者需提高抗震设防类别的房屋建筑工程，进行抗震验算、修复和加固的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，逾期不改的，处以1万元以下罚款。"},{"i":28,"n":"第二十八条","txt":"违反本规定，经鉴定需抗震加固的房屋建筑工程在进行装修改造时未进行抗震加固的，由县级以上地方人民政府住房城乡建设主管部门责令限期改正，逾期不改的，处以1万元以下罚款。"},{"i":29,"n":"第二十九条","txt":"本规定所称抗震设防区，是指地震基本烈度六度及六度以上地区（地震动峰值加速度≥0.05g的地区）。 本规定所称超限高层建筑工程，是指超出国家现行规范、规程所规定的适用高度和适用结构类型的高层建筑工程，体型特别不规则的高层建筑工程，以及有关规范、规程规定应当进行抗震专项审查的高层建筑工程。"},{"i":30,"n":"第三十条","txt":"本规定自2006年4月1日起施行。"}],"fangwujianzhugongchengzhiliangbaoxiubanfa":[{"i":1,"n":"第一条","txt":"为保护建设单位、施工单位、房屋建筑所有人和使用人的合法权益，维护公共安全和公众利益，根据《中华人民共和国建筑法》和《建设工程质量管理条例》，制订本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内新建、扩建、改建各类房屋建筑工程（包括装修工程）的质量保修，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称房屋建筑工程质量保修，是指对房屋建筑工程竣工验收后在保修期限内出现的质量缺陷，予以修复。 本办法所称质量缺陷，是指房屋建筑工程的质量不符合工程建设强制性标准以及合同的约定。"},{"i":4,"n":"第四条","txt":"房屋建筑工程在保修范围和保修期限内出现质量缺陷，施工单位应当履行保修义务。"},{"i":5,"n":"第五条","txt":"国务院建设行政主管部门负责全国房屋建筑工程质量保修的监督管理。 县级以上地方人民政府建设行政主管部门负责本行政区域内房屋建筑工程质量保修的监督管理。"},{"i":6,"n":"第六条","txt":"建设单位和施工单位应当在工程质量保修书中约定保修范围、保修期限和保修责任等，双方约定的保修范围、保修期限必须符合国家有关规定。"},{"i":7,"n":"第七条","txt":"在正常使用下，房屋建筑工程的最低保修期限为： （一）地基基础工程和主体结构工程，为设计文件规定的该工程的合理使用年限； （二）屋面防水工程、有防水要求的卫生间、房间和外墙面的防渗漏，为5年； （三）供热与供冷系统，为2个采暖期、供冷期； （四）电气管线、给排水管道、设备安装为2年； （五）装修工程为2年。 其他项目的保修期限由建设单位和施工单位约定。"},{"i":8,"n":"第八条","txt":"房屋建筑工程保修期从工程竣工验收合格之日起计算。"},{"i":9,"n":"第九条","txt":"房屋建筑工程在保修期限内出现质量缺陷，建设单位或者房屋建筑所有人应当向施工单位发出保修通知。施工单位接到保修通知后，应当到现场核查情况，在保修书约定的时间内予以保修。发生涉及结构安全或者严重影响使用功能的紧急抢修事故，施工单位接到保修通知后，应当立即到达现场抢修。"},{"i":10,"n":"第十条","txt":"发生涉及结构安全的质量缺陷，建设单位或者房屋建筑所有人应当立即向当地建设行政主管部门报告，采取安全防范措施；由原设计单位或者具有相应资质等级的设计单位提出保修方案，施工单位实施保修，原工程质量监督机构负责监督。"},{"i":11,"n":"第十一条","txt":"保修完成后，由建设单位或者房屋建筑所有人组织验收。涉及结构安全的，应当报当地建设行政主管部门备案。"},{"i":12,"n":"第十二条","txt":"施工单位不按工程质量保修书约定保修的，建设单位可以另行委托其他单位保修，由原施工单位承担相应责任。"},{"i":13,"n":"第十三条","txt":"保修费用由质量缺陷的责任方承担。"},{"i":14,"n":"第十四条","txt":"在保修期内，因房屋建筑工程质量缺陷造成房屋所有人、使用人或者第三方人身、财产损害的，房屋所有人、使用人或者第三方可以向建设单位提出赔偿要求。建设单位向造成房屋建筑工程质量缺陷的责任方追偿。"},{"i":15,"n":"第十五条","txt":"因保修不及时造成新的人身、财产损害，由造成拖延的责任方承担赔偿责任。"},{"i":16,"n":"第十六条","txt":"房地产开发企业售出的商品房保修，还应当执行《城市房地产开发经营管理条例》和其他有关规定。"},{"i":17,"n":"第十七条","txt":"下列情况不属于本办法规定的保修范围： （一）因使用不当或者第三方造成的质量缺陷； （二）不可抗力造成的质量缺陷。"},{"i":18,"n":"第十八条","txt":"施工单位有下列行为之一的，由建设行政主管部门责令改正，并处1万元以上3万元以下的罚款。 （一）工程竣工验收后，不向建设单位出具质量保修书的； （二）质量保修的内容、期限违反本办法规定的。"},{"i":19,"n":"第十九条","txt":"施工单位不履行保修义务或者拖延履行保修义务的，由建设行政主管部门责令改正，处10万元以上20万元以下的罚款。"},{"i":20,"n":"第二十条","txt":"军事建设工程的管理，按照中央军事委员会的有关规定执行。"},{"i":21,"n":"第二十一条","txt":"本办法由国务院建设行政主管部门负责解释。"},{"i":22,"n":"第二十二条","txt":"本办法自发布之日起施行。"}],"minyongjianzhujienengguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强民用建筑节能管理，提高能源利用效率，改善室内热环境质量，根据《中华人民共和国节约能源法》、《中华人民共和国建筑法》、《建设工程质量管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称民用建筑，是指居住建筑和公共建筑。 本规定所称民用建筑节能，是指民用建筑在规划、设计、建造和使用过程中，通过采用新型墙体材料，执行建筑节能标准，加强建筑物用能设备的运行管理，合理设计建筑围护结构的热工性能，提高采暖、制冷、照明、通风、给排水和通道系统的运行效率，以及利用可再生能源，在保证建筑物使用功能和室内热环境质量的前提下，降低建筑能源消耗，合理、有效地利用能源的活动。"},{"i":3,"n":"第三条","txt":"国务院建设行政主管部门负责全国民用建筑节能的监督管理工作。 县级以上地方人民政府建设行政主管部门负责本行政区域内民用建筑节能的监督管理工作。"},{"i":4,"n":"第四条","txt":"国务院建设行政主管部门根据国家节能规划，制定国家建筑节能专项规划；省、自治区、直辖市以及设区城市人民政府建设行政主管部门应当根据本地节能规划，制定本地建筑节能专项规划，并组织实施。"},{"i":5,"n":"第五条","txt":"编制城乡规划应当充分考虑能源、资源的综合利用和节约，对城镇布局、功能区设置、建筑特征，基础设施配置的影响进行研究论证。"},{"i":6,"n":"第六条","txt":"国务院建设行政主管部门根据建筑节能发展状况和技术先进、经济合理的原则，组织制定建筑节能相关标准，建立和完善建筑节能标准体系；省、自治区、直辖市人民政府建设行政主管部门应当严格执行国家民用建筑节能有关规定，可以制定严于国家民用建筑节能标准的地方标准或者实施细则。"},{"i":7,"n":"第七条","txt":"鼓励民用建筑节能的科学研究和技术开发，推广应用节能型的建筑、结构、材料、用能设备和附属设施及相应的施工工艺、应用技术和管理技术，促进可再生能源的开发利用。"},{"i":8,"n":"第八条","txt":"鼓励发展下列建筑节能技术和产品： （一）新型节能墙体和屋面的保温、隔热技术与材料； （二）节能门窗的保温隔热和密闭技术； （三）集中供热和热、电、冷联产联供技术； （四）供热采暖系统温度调控和分户热量计量技术与装置； （五）太阳能、地热等可再生能源应用技术及设备； （六）建筑照明节能技术与产品； （七）空调制冷节能技术与产品； （八）其他技术成熟、效果显著的节能技术和节能管理技术。 鼓励推广应用和淘汰的建筑节能部品及技术的目录，由国务院建设行政主管部门制定；省、自治区、直辖市建设行政主管部门可以结合该目录，制定适合本区域的鼓励推广应用和淘汰的建筑节能部品及技术的目录。"},{"i":9,"n":"第九条","txt":"国家鼓励多元化、多渠道投资既有建筑的节能改造，投资人可以按照协议分享节能改造的收益；鼓励研究制定本地区既有建筑节能改造资金筹措办法和相关激励政策。"},{"i":10,"n":"第十条","txt":"建筑工程施工过程中，县级以上地方人民政府建设行政主管部门应当加强对建筑物的围护结构（含墙体、屋面、门窗、玻璃幕墙等）、供热采暖和制冷系统、照明和通风等电器设备是否符合节能要求的监督检查。"},{"i":11,"n":"第十一条","txt":"新建民用建筑应当严格执行建筑节能标准要求，民用建筑工程扩建和改建时，应当对原建筑进行节能改造。 既有建筑节能改造应当考虑建筑物的寿命周期，对改造的必要性、可行性以及投入收益比进行科学论证。节能改造要符合建筑节能标准要求，确保结构安全，优化建筑物使用功能。 寒冷地区和严寒地区既有建筑节能改造应当与供热系统节能改造同步进行。"},{"i":12,"n":"第十二条","txt":"采用集中采暖制冷方式的新建民用建筑应当安设建筑物室内温度控制和用能计量设施，逐步实行基本冷热价和计量冷热价共同构成的两部制用能价格制度。"},{"i":13,"n":"第十三条","txt":"供热单位、公共建筑所有权人或者其委托的物业管理单位应当制定相应的节能建筑运行管理制度，明确节能建筑运行状态各项性能指标、节能工作诸环节的岗位目标责任等事项。"},{"i":14,"n":"第十四条","txt":"公共建筑的所有权人或者委托的物业管理单位应当建立用能档案，在供热或者制冷间歇期委托相关检测机构对用能设备和系统的性能进行综合检测评价，定期进行维护、维修、保养及更新置换，保证设备和系统的正常运行。"},{"i":15,"n":"第十五条","txt":"供热单位、房屋产权单位或者其委托的物业管理等有关单位，应当记录并按有关规定上报能源消耗资料。 鼓励新建民用建筑和既有建筑实施建筑能效测评。"},{"i":16,"n":"第十六条","txt":"从事建筑节能及相关管理活动的单位，应当对其从业人员进行建筑节能标准与技术等专业知识的培训。 建筑节能标准和节能技术应当作为注册城市规划师、注册建筑师、勘察设计注册工程师、注册监理工程师、注册建造师等继续教育的必修内容。"},{"i":17,"n":"第十七条","txt":"建设单位应当按照建筑节能政策要求和建筑节能标准委托工程项目的设计。 建设单位不得以任何理由要求设计单位、施工单位擅自修改经审查合格的节能设计文件，降低建筑节能标准。"},{"i":18,"n":"第十八条","txt":"房地产开发企业应当将所售商品住房的节能措施、围护结构保温隔热性能指标等基本信息在销售现场显著位置予以公示，并在《住宅使用说明书》中予以载明。"},{"i":19,"n":"第十九条","txt":"设计单位应当依据建筑节能标准的要求进行设计，保证建筑节能设计质量。 施工图设计文件审查机构在进行审查时，应当审查节能设计的内容，在审查报告中单列节能审查章节；不符合建筑节能强制性标准的，施工图设计文件审查结论应当定为不合格。"},{"i":20,"n":"第二十条","txt":"施工单位应当按照审查合格的设计文件和建筑节能施工标准的要求进行施工，保证工程施工质量。"},{"i":21,"n":"第二十一条","txt":"监理单位应当依照法律、法规以及建筑节能标准、节能设计文件、建设工程承包合同及监理合同对节能工程建设实施监理。"},{"i":22,"n":"第二十二条","txt":"对超过能源消耗指标的供热单位、公共建筑的所有权人或者其委托的物业管理单位，责令限期达标。"},{"i":23,"n":"第二十三条","txt":"对擅自改变建筑围护结构节能措施，并影响公共利益和他人合法权益的，责令责任人及时予以修复，并承担相应的费用。"},{"i":24,"n":"第二十四条","txt":"建设单位在竣工验收过程中，有违反建筑节能强制性标准行为的，按照《建设工程质量管理条例》的有关规定，重新组织竣工验收。"},{"i":25,"n":"第二十五条","txt":"建设单位未按照建筑节能强制性标准委托设计，擅自修改节能设计文件，明示或暗示设计单位、施工单位违反建筑节能设计强制性标准，降低工程建设质量的，处20万元以上50万元以下的罚款。"},{"i":26,"n":"第二十六条","txt":"设计单位未按照建筑节能强制性标准进行设计的，应当修改设计。未进行修改的，给予警告，处10万元以上30万元以下罚款；造成损失的，依法承担赔偿责任；两年内，累计三项工程未按照建筑节能强制性标准设计的，责令停业整顿，降低资质等级或者吊销资质证书。"},{"i":27,"n":"第二十七条","txt":"对未按照节能设计进行施工的施工单位，责令改正；整改所发生的工程费用，由施工单位负责；可以给予警告，情节严重的，处工程合同价款2％以上4％以下的罚款；两年内，累计三项工程未按照符合节能标准要求的设计进行施工的，责令停业整顿，降低资质等级或者吊销资质证书。"},{"i":28,"n":"第二十八条","txt":"本规定的责令停业整顿、降低资质等级和吊销资质证书的行政处罚，由颁发资质证书的机关决定；其他行政处罚，由建设行政主管部门依照法定职权决定。"},{"i":29,"n":"第二十九条","txt":"农民自建低层住宅不适用本规定。"},{"i":30,"n":"第三十条","txt":"本规定自2006年1月1日起施行。原《民用建筑节能管理规定》（建设部令第76号）同时废止。"}],"zhucejianzaoshiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对注册建造师的管理，规范注册建造师的执业行为，提高工程项目管理水平，保证工程质量和安全，依据《建筑法》、《行政许可法》、《建设工程质量管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内注册建造师的注册、执业、继续教育和监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称注册建造师，是指通过考核认定或考试合格取得中华人民共和国建造师资格证书（以下简称资格证书），并按照本规定注册，取得中华人民共和国建造师注册证书（以下简称注册证书）和执业印章，担任施工单位项目负责人及从事相关活动的专业技术人员。 未取得注册证书和执业印章的，不得担任大中型建设工程项目的施工单位项目负责人，不得以注册建造师的名义从事相关活动。"},{"i":4,"n":"第四条","txt":"国务院建设主管部门对全国注册建造师的注册、执业活动实施统一监督管理；国务院铁路、交通、水利、信息产业、民航等有关部门按照国务院规定的职责分工，对全国有关专业工程注册建造师的执业活动实施监督管理。 县级以上地方人民政府建设主管部门对本行政区域内的注册建造师的注册、执业活动实施监督管理；县级以上地方人民政府交通、水利、通信等有关部门在各自职责范围内，对本行政区域内有关专业工程注册建造师的执业活动实施监督管理。"},{"i":5,"n":"第五条","txt":"注册建造师实行注册执业管理制度，注册建造师分为一级注册建造师和二级注册建造师。 取得资格证书的人员，经过注册方能以注册建造师的名义执业。"},{"i":6,"n":"第六条","txt":"申请初始注册时应当具备以下条件： （一）经考核认定或考试合格取得资格证书； （二）受聘于一个相关单位； （三）达到继续教育要求； （四）没有本规定第十五条所列情形。"},{"i":7,"n":"第七条","txt":"取得一级建造师资格证书并受聘于一个建设工程勘察、设计、施工、监理、招标代理、造价咨询等单位的人员，应当通过聘用单位向单位工商注册所在地的省、自治区、直辖市人民政府建设主管部门提出注册申请。 省、自治区、直辖市人民政府建设主管部门受理后提出初审意见，并将初审意见和全部申报材料报国务院建设主管部门审批；涉及铁路、公路、港口与航道、水利水电、通信与广电、民航专业的，国务院建设主管部门应当将全部申报材料送同级有关部门审核。符合条件的，由国务院建设主管部门核发《中华人民共和国一级建造师注册证书》，并核定执业印章编号。"},{"i":8,"n":"第八条","txt":"对申请初始注册的，省、自治区、直辖市人民政府建设主管部门应当自受理申请之日起，20日内审查完毕，并将申请材料和初审意见报国务院建设主管部门。国务院建设主管部门应当自收到省、自治区、直辖市人民政府建设主管部门上报材料之日起，20日内审批完毕并作出书面决定。有关部门应当在收到国务院建设主管部门移送的申请材料之日起，10日内审核完毕，并将审核意见送国务院建设主管部门。 对申请变更注册、延续注册的，省、自治区、直辖市人民政府建设主管部门应当自受理申请之日起5日内审查完毕。国务院建设主管部门应当自收到省、自治区、直辖市人民政府建设主管部门上报材料之日起，10日内审批完毕并作出书面决定。有关部门在收到国务院建设主管部门移送的申请材料后，应当在5日内审核完毕，并将审核意见送国务院建设主管部门。"},{"i":9,"n":"第九条","txt":"取得二级建造师资格证书的人员申请注册，由省、自治区、直辖市人民政府建设主管部门负责受理和审批，具体审批程序由省、自治区、直辖市人民政府建设主管部门依法确定。对批准注册的，核发由国务院建设主管部门统一样式的《中华人民共和国二级建造师注册证书》和执业印章，并在核发证书后30日内送国务院建设主管部门备案。"},{"i":10,"n":"第十条","txt":"注册证书和执业印章是注册建造师的执业凭证，由注册建造师本人保管、使用。 注册证书与执业印章有效期为3年。 一级注册建造师的注册证书由国务院建设主管部门统一印制，执业印章由国务院建设主管部门统一样式，省、自治区、直辖市人民政府建设主管部门组织制作。"},{"i":11,"n":"第十一条","txt":"初始注册者，可自资格证书签发之日起3年内提出申请。逾期未申请者，须符合本专业继续教育的要求后方可申请初始注册。 申请初始注册需要提交下列材料： （一）注册建造师初始注册申请表； （二）资格证书、学历证书和身份证明复印件； （三）申请人与聘用单位签订的聘用劳动合同复印件或其他有效证明文件； （四）逾期申请初始注册的，应当提供达到继续教育要求的证明材料。"},{"i":12,"n":"第十二条","txt":"注册有效期满需继续执业的，应当在注册有效期届满30日前，按照第七条、第八条的规定申请延续注册。延续注册的，有效期为3年。 申请延续注册的，应当提交下列材料： （一）注册建造师延续注册申请表； （二）原注册证书； （三）申请人与聘用单位签订的聘用劳动合同复印件或其他有效证明文件； （四）申请人注册有效期内达到继续教育要求的证明材料。"},{"i":13,"n":"第十三条","txt":"在注册有效期内，注册建造师变更执业单位，应当与原聘用单位解除劳动关系，并按照第七条、第八条的规定办理变更注册手续，变更注册后仍延续原注册有效期。 申请变更注册的，应当提交下列材料： （一）注册建造师变更注册申请表； （二）注册证书和执业印章； （三）申请人与新聘用单位签订的聘用合同复印件或有效证明文件； （四）工作调动证明（与原聘用单位解除聘用合同或聘用合同到期的证明文件、退休人员的退休证明）。"},{"i":14,"n":"第十四条","txt":"注册建造师需要增加执业专业的，应当按照第七条的规定申请专业增项注册，并提供相应的资格证明。"},{"i":15,"n":"第十五条","txt":"申请人有下列情形之一的，不予注册： （一）不具有完全民事行为能力的； （二）申请在两个或者两个以上单位注册的； （三）未达到注册建造师继续教育要求的； （四）受到刑事处罚，刑事处罚尚未执行完毕的； （五）因执业活动受到刑事处罚，自刑事处罚执行完毕之日起至申请注册之日止不满5年的； （六）因前项规定以外的原因受到刑事处罚，自处罚决定之日起至申请注册之日止不满3年的； （七）被吊销注册证书，自处罚决定之日起至申请注册之日止不满2年的； （八）在申请注册之日前3年内担任项目经理期间，所负责项目发生过重大质量和安全事故的； （九）申请人的聘用单位不符合注册单位要求的； （十）年龄超过65周岁的； （十一）法律、法规规定不予注册的其他情形。"},{"i":16,"n":"第十六条","txt":"注册建造师有下列情形之一的，其注册证书和执业印章失效： （一）聘用单位破产的； （二）聘用单位被吊销营业执照的； （三）聘用单位被吊销或者撤回资质证书的； （四）已与聘用单位解除聘用合同关系的； （五）注册有效期满且未延续注册的； （六）年龄超过65周岁的； （七）死亡或不具有完全民事行为能力的； （八）其他导致注册失效的情形。"},{"i":17,"n":"第十七条","txt":"注册建造师有下列情形之一的，由注册机关办理注销手续，收回注册证书和执业印章或者公告注册证书和执业印章作废： （一）有本规定第十六条所列情形发生的； （二）依法被撤销注册的； （三）依法被吊销注册证书的； （四）受到刑事处罚的； （五）法律、法规规定应当注销注册的其他情形。 注册建造师有前款所列情形之一的，注册建造师本人和聘用单位应当及时向注册机关提出注销注册申请；有关单位和个人有权向注册机关举报；县级以上地方人民政府建设主管部门或者有关部门应当及时告知注册机关。"},{"i":18,"n":"第十八条","txt":"被注销注册或者不予注册的，在重新具备注册条件后，可按第七条、第八条规定重新申请注册。"},{"i":19,"n":"第十九条","txt":"注册建造师因遗失、污损注册证书或执业印章，需要补办的，应当持在公众媒体上刊登的遗失声明的证明，向原注册机关申请补办。原注册机关应当在5日内办理完毕。"},{"i":20,"n":"第二十条","txt":"取得资格证书的人员应当受聘于一个具有建设工程勘察、设计、施工、监理、招标代理、造价咨询等一项或者多项资质的单位，经注册后方可从事相应的执业活动。 担任施工单位项目负责人的，应当受聘并注册于一个具有施工资质的企业。"},{"i":21,"n":"第二十一条","txt":"注册建造师的具体执业范围按照《注册建造师执业工程规模标准》执行。 注册建造师不得同时在两个及两个以上的建设工程项目上担任施工单位项目负责人。 注册建造师可以从事建设工程项目总承包管理或施工管理，建设工程项目管理服务，建设工程技术经济咨询，以及法律、行政法规和国务院建设主管部门规定的其他业务。"},{"i":22,"n":"第二十二条","txt":"建设工程施工活动中形成的有关工程施工管理文件，应当由注册建造师签字并加盖执业印章。 施工单位签署质量合格的文件上，必须有注册建造师的签字盖章。"},{"i":23,"n":"第二十三条","txt":"注册建造师在每一个注册有效期内应当达到国务院建设主管部门规定的继续教育要求。 继续教育分为必修课和选修课，在每一注册有效期内各为60学时。经继续教育达到合格标准的，颁发继续教育合格证书。 继续教育的具体要求由国务院建设主管部门会同国务院有关部门另行规定。"},{"i":24,"n":"第二十四条","txt":"注册建造师享有下列权利： （一）使用注册建造师名称； （二）在规定范围内从事执业活动； （三）在本人执业活动中形成的文件上签字并加盖执业印章； （四）保管和使用本人注册证书、执业印章； （五）对本人执业活动进行解释和辩护； （六）接受继续教育； （七）获得相应的劳动报酬； （八）对侵犯本人权利的行为进行申述。"},{"i":25,"n":"第二十五条","txt":"注册建造师应当履行下列义务： （一）遵守法律、法规和有关管理规定，恪守职业道德； （二）执行技术标准、规范和规程； （三）保证执业成果的质量，并承担相应责任； （四）接受继续教育，努力提高执业水准； （五）保守在执业中知悉的国家秘密和他人的商业、技术等秘密； （六）与当事人有利害关系的，应当主动回避； （七）协助注册管理机关完成相关工作。"},{"i":26,"n":"第二十六条","txt":"注册建造师不得有下列行为： （一）不履行注册建造师义务； （二）在执业过程中，索贿、受贿或者谋取合同约定费用外的其他利益； （三）在执业过程中实施商业贿赂； （四）签署有虚假记载等不合格的文件； （五）允许他人以自己的名义从事执业活动； （六）同时在两个或者两个以上单位受聘或者执业； （七）涂改、倒卖、出租、出借或以其他形式非法转让资格证书、注册证书和执业印章； （八）超出执业范围和聘用单位业务范围内从事执业活动； （九） 法律、法规、规章禁止的其他行为。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府建设主管部门、其他有关部门应当依照有关法律、法规和本规定，对注册建造师的注册、执业和继续教育实施监督检查。"},{"i":28,"n":"第二十八条","txt":"国务院建设主管部门应当将注册建造师注册信息告知省、自治区、直辖市人民政府建设主管部门。 省、自治区、直辖市人民政府建设主管部门应当将注册建造师注册信息告知本行政区域内市、县、市辖区人民政府建设主管部门。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府建设主管部门和有关部门履行监督检查职责时，有权采取下列措施： （一）要求被检查人员出示注册证书； （二）要求被检查人员所在聘用单位提供有关人员签署的文件及相关业务文档； （三）就有关问题询问签署文件的人员； （四）纠正违反有关法律、法规、本规定及工程标准规范的行为。"},{"i":30,"n":"第三十条","txt":"注册建造师违法从事相关活动的，违法行为发生地县级以上地方人民政府建设主管部门或者其他有关部门应当依法查处，并将违法事实、处理结果告知注册机关；依法应当撤销注册的，应当将违法事实、处理建议及有关材料报注册机关。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，注册机关依据职权或者根据利害关系人的请求，可以撤销注册建造师的注册： （一）注册机关工作人员滥用职权、玩忽职守作出准予注册许可的； （二）超越法定职权作出准予注册许可的； （三）违反法定程序作出准予注册许可的； （四）对不符合法定条件的申请人颁发注册证书和执业印章的； （五）依法可以撤销注册的其他情形。 申请人以欺骗、贿赂等不正当手段获准注册的，应当予以撤销。"},{"i":32,"n":"第三十二条","txt":"注册建造师及其聘用单位应当按照要求，向注册机关提供真实、准确、完整的注册建造师信用档案信息。 注册建造师信用档案应当包括注册建造师的基本情况、业绩、良好行为、不良行为等内容。违法违规行为、被投诉举报处理、行政处罚等情况应当作为注册建造师的不良行为记入其信用档案。 注册建造师信用档案信息按照有关规定向社会公示。"},{"i":33,"n":"第三十三条","txt":"隐瞒有关情况或者提供虚假材料申请注册的，建设主管部门不予受理或者不予注册，并给予警告，申请人1年内不得再次申请注册。"},{"i":34,"n":"第三十四条","txt":"以欺骗、贿赂等不正当手段取得注册证书的，由注册机关撤销其注册，3年内不得再次申请注册，并由县级以上地方人民政府建设主管部门处以罚款。其中没有违法所得的，处以1万元以下的罚款；有违法所得的，处以违法所得3倍以下且不超过3万元的罚款。"},{"i":35,"n":"第三十五条","txt":"违反本规定，未取得注册证书和执业印章，担任大中型建设工程项目施工单位项目负责人，或者以注册建造师的名义从事相关活动的，其所签署的工程文件无效，由县级以上地方人民政府建设主管部门或者其他有关部门给予警告，责令停止违法活动，并可处以1万元以上3万元以下的罚款。"},{"i":36,"n":"第三十六条","txt":"违反本规定，未办理变更注册而继续执业的，由县级以上地方人民政府建设主管部门或者其他有关部门责令限期改正；逾期不改正的，可处以5000元以下的罚款。"},{"i":37,"n":"第三十七条","txt":"违反本规定，注册建造师在执业活动中有第二十六条所列行为之一的，由县级以上地方人民政府建设主管部门或者其他有关部门给予警告，责令改正，没有违法所得的，处以1万元以下的罚款；有违法所得的，处以违法所得3倍以下且不超过3万元的罚款。"},{"i":38,"n":"第三十八条","txt":"违反本规定，注册建造师或者其聘用单位未按照要求提供注册建造师信用档案信息的，由县级以上地方人民政府建设主管部门或者其他有关部门责令限期改正；逾期未改正的，可处以1000元以上1万元以下的罚款。"},{"i":39,"n":"第三十九条","txt":"聘用单位为申请人提供虚假注册材料的，由县级以上地方人民政府建设主管部门或者其他有关部门给予警告，责令限期改正；逾期未改正的，可处以1万元以上3万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"县级以上人民政府建设主管部门及其工作人员，在注册建造师管理工作中，有下列情形之一的，由其上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）对不符合法定条件的申请人准予注册的； （二）对符合法定条件的申请人不予注册或者不在法定期限内作出准予注册决定的； （三）对符合法定条件的申请不予受理或者未在法定期限内初审完毕的； （四）利用职务上的便利，收受他人财物或者其他好处的； （五）不依法履行监督管理职责或者监督不力，造成严重后果的。"},{"i":41,"n":"第四十一条","txt":"本规定自2007年3月1日起施行。"}],"zhucefangdichangujiashiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对注册房地产估价师的管理，完善房地产价格评估制度和房地产价格评估人员资格认证制度，规范注册房地产估价师行为，维护公共利益和房地产估价市场秩序，根据《中华人民共和国城市房地产管理法》、《中华人民共和国行政许可法》等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内注册房地产估价师的注册、执业、继续教育和监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称注册房地产估价师，是指通过全国房地产估价师执业资格考试或者资格认定、资格互认，取得中华人民共和国房地产估价师执业资格（以下简称执业资格），并按照本办法注册，取得中华人民共和国房地产估价师注册证书（以下简称注册证书），从事房地产估价活动的人员。"},{"i":4,"n":"第四条","txt":"注册房地产估价师实行注册执业管理制度。 取得执业资格的人员，经过注册方能以注册房地产估价师的名义执业。"},{"i":5,"n":"第五条","txt":"国务院住房城乡建设主管部门对全国注册房地产估价师注册、执业活动实施统一监督管理。 省、自治区、直辖市人民政府住房城乡建设（房地产）主管部门对本行政区域内注册房地产估价师的执业活动实施监督管理。 市、县、市辖区人民政府建设（房地产）主管部门对本行政区域内注册房地产估价师的执业活动实施监督管理。"},{"i":6,"n":"第六条","txt":"房地产估价行业组织应当加强注册房地产估价师自律管理。 鼓励注册房地产估价师加入房地产估价行业组织。"},{"i":7,"n":"第七条","txt":"注册房地产估价师的注册条件为： （一）取得执业资格； （二）达到继续教育合格标准； （三）受聘于具有资质的房地产估价机构； （四）无本办法第十四条规定不予注册的情形。"},{"i":8,"n":"第八条","txt":"申请注册的，应当向国务院住房城乡建设主管部门提出注册申请。 对申请初始注册、变更注册、延续注册和注销注册的，国务院住房城乡建设主管部门应当自受理之日起15日内作出决定。 注册房地产估价师的初始注册、变更注册、延续注册和注销注册，逐步实行网上申报、受理和审批。"},{"i":9,"n":"第九条","txt":"注册证书是注册房地产估价师的执业凭证。注册有效期为3年。"},{"i":10,"n":"第十条","txt":"申请初始注册，应当提交下列材料： （一）初始注册申请表； （二）执业资格证件和身份证件复印件； （三）与聘用单位签订的劳动合同复印件； （四）取得执业资格超过3年申请初始注册的，应当提供达到继续教育合格标准的证明材料； （五）聘用单位委托人才服务中心托管人事档案的证明和社会保险缴纳凭证复印件；或者劳动、人事部门颁发的离退休证复印件；或者外国人就业证书、台港澳人员就业证书复印件。"},{"i":11,"n":"第十一条","txt":"注册有效期满需继续执业的，应当在注册有效期满30日前，按照本办法第八条规定的程序申请延续注册；延续注册的，注册有效期为3年。 延续注册需要提交下列材料： （一）延续注册申请表； （二）与聘用单位签订的劳动合同复印件； （三）申请人注册有效期内达到继续教育合格标准的证明材料。"},{"i":12,"n":"第十二条","txt":"注册房地产估价师变更执业单位，应当与原聘用单位解除劳动合同，并按本办法第八条规定的程序办理变更注册手续，变更注册后延续原注册有效期。 变更注册需要提交下列材料： （一）变更注册申请表； （二）与新聘用单位签订的劳动合同复印件； （三）与原聘用单位解除劳动合同的证明文件； （四）聘用单位委托人才服务中心托管人事档案的证明和社会保险缴纳凭证复印件；或者劳动、人事部门颁发的离退休证复印件；或者外国人就业证书、台港澳人员就业证书复印件。"},{"i":13,"n":"第十三条","txt":"取得执业资格的人员，申请在新设立房地产估价机构、分支机构执业的，应当在申报房地产估价机构资质或者分支机构备案的同时，办理注册手续。"},{"i":14,"n":"第十四条","txt":"申请人有下列情形之一的，不予注册： （一）不具有完全民事行为能力的； （二）刑事处罚尚未执行完毕的； （三）因房地产估价及相关业务活动受刑事处罚，自刑事处罚执行完毕之日起至申请注册之日止不满5年的； （四）因前项规定以外原因受刑事处罚，自刑事处罚执行完毕之日起至申请注册之日止不满3年的； （五）被吊销注册证书，自被处罚之日起至申请注册之日止不满3年的； （六）以欺骗、贿赂等不正当手段获准的房地产估价师注册被撤销，自被撤销注册之日起至申请注册之日止不满3年的； （七）申请在2个或者2个以上房地产估价机构执业的； （八）为现职公务员的； （九）年龄超过65周岁的； （十）法律、行政法规规定不予注册的其他情形。"},{"i":15,"n":"第十五条","txt":"注册房地产估价师有下列情形之一的，其注册证书失效： （一）聘用单位破产的； （二）聘用单位被吊销营业执照的； （三）聘用单位被吊销或者撤回房地产估价机构资质证书的； （四）已与聘用单位解除劳动合同且未被其他房地产估价机构聘用的； （五）注册有效期满且未延续注册的； （六）年龄超过65周岁的； （七）死亡或者不具有完全民事行为能力的； （八）其他导致注册失效的情形。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，注册房地产估价师应当及时向国务院住房城乡建设主管部门提出注销注册的申请，交回注册证书，国务院住房城乡建设主管部门应当办理注销手续，公告其注册证书作废： （一）有本办法第十五条所列情形发生的； （二）依法被撤销注册的； （三）依法被吊销注册证书的； （四）受到刑事处罚的； （五）法律、法规规定应当注销注册的其他情形。 注册房地产估价师有前款所列情形之一的，有关单位和个人有权向国务院住房城乡建设主管部门举报；县级以上地方人民政府建设（房地产）主管部门应当及时报告国务院住房城乡建设主管部门。"},{"i":17,"n":"第十七条","txt":"被注销注册者或者不予注册者，在具备注册条件后，可以按照本办法第八条第一款、第二款规定的程序申请注册。"},{"i":18,"n":"第十八条","txt":"注册房地产估价师遗失注册证书的，应当在公众媒体上声明后，按照本办法第八条第一款、第三款规定的程序申请补发。"},{"i":19,"n":"第十九条","txt":"取得执业资格的人员，应当受聘于一个具有房地产估价机构资质的单位，经注册后方可从事房地产估价执业活动。"},{"i":20,"n":"第二十条","txt":"注册房地产估价师可以在全国范围内开展与其聘用单位业务范围相符的房地产估价活动。"},{"i":21,"n":"第二十一条","txt":"注册房地产估价师从事执业活动，由聘用单位接受委托并统一收费。"},{"i":22,"n":"第二十二条","txt":"在房地产估价过程中给当事人造成经济损失，聘用单位依法应当承担赔偿责任的，可依法向负有过错的注册房地产估价师追偿。"},{"i":23,"n":"第二十三条","txt":"注册房地产估价师在每一注册有效期内应当达到国务院住房城乡建设主管部门规定的继续教育要求。 注册房地产估价师继续教育分为必修课和选修课，每一注册有效期各为60学时。经继续教育达到合格标准的，颁发继续教育合格证书。 注册房地产估价师继续教育，由中国房地产估价师与房地产经纪人学会负责组织。"},{"i":24,"n":"第二十四条","txt":"注册房地产估价师享有下列权利： （一）使用注册房地产估价师名称； （二）在规定范围内执行房地产估价及相关业务； （三）签署房地产估价报告； （四）发起设立房地产估价机构； （五）保管和使用本人的注册证书； （六）对本人执业活动进行解释和辩护； （七）参加继续教育； （八）获得相应的劳动报酬； （九）对侵犯本人权利的行为进行申诉。"},{"i":25,"n":"第二十五条","txt":"注册房地产估价师应当履行下列义务： （一）遵守法律、法规、行业管理规定和职业道德规范； （二）执行房地产估价技术规范和标准； （三）保证估价结果的客观公正，并承担相应责任； （四）保守在执业中知悉的国家秘密和他人的商业、技术秘密； （五）与当事人有利害关系的，应当主动回避； （六）接受继续教育，努力提高执业水准； （七）协助注册管理机构完成相关工作。"},{"i":26,"n":"第二十六条","txt":"注册房地产估价师不得有下列行为： （一）不履行注册房地产估价师义务； （二）在执业过程中，索贿、受贿或者谋取合同约定费用外的其他利益； （三）在执业过程中实施商业贿赂； （四）签署有虚假记载、误导性陈述或者重大遗漏的估价报告； （五）在估价报告中隐瞒或者歪曲事实； （六）允许他人以自己的名义从事房地产估价业务； （七）同时在2个或者2个以上房地产估价机构执业； （八）以个人名义承揽房地产估价业务； （九）涂改、出租、出借或者以其他形式非法转让注册证书； （十）超出聘用单位业务范围从事房地产估价活动； （十一）严重损害他人利益、名誉的行为； （十二）法律、法规禁止的其他行为。"},{"i":27,"n":"第二十七条","txt":"县级以上人民政府建设（房地产）主管部门，应当依照有关法律、法规和本办法的规定，对房地产估价师的执业和继续教育情况实施监督检查。"},{"i":28,"n":"第二十八条","txt":"国务院住房城乡建设主管部门应当将注册房地产估价师注册信息告知省、自治区、直辖市建设（房地产）主管部门。 省、自治区人民政府建设（房地产）主管部门应当将注册房地产估价师注册信息告知本行政区域内市、县人民政府建设（房地产）主管部门。直辖市人民政府建设（房地产）主管部门应当将注册房地产估价师注册信息告知本行政区域内市、县、市辖区人民政府建设（房地产）主管部门。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府建设（房地产）主管部门履行监督检查职责时，有权采取下列措施： （一）要求被检查人员出示注册证书； （二）要求被检查人员所在聘用单位提供有关人员签署的估价报告及相关业务文档； （三）就有关问题询问签署估价报告的人员； （四）纠正违反有关法律、法规和本办法及房地产估价规范和标准的行为。"},{"i":30,"n":"第三十条","txt":"注册房地产估价师违法从事房地产估价活动的，违法行为发生地直辖市、市、县、市辖区人民政府建设（房地产）主管部门应当依法查处，并将违法事实、处理结果告知注册房地产估价师注册所在地的省、自治区、直辖市建设（房地产）主管部门；依法需撤销注册的，应当将违法事实、处理建议及有关材料报国务院住房城乡建设主管部门。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，国务院住房城乡建设主管部门依据职权或者根据利害关系人的请求，可以撤销房地产估价师注册： （一）注册机关工作人员滥用职权、玩忽职守作出准予房地产估价师注册行政许可的； （二）超越法定职权作出准予房地产估价师注册许可的； （三）违反法定程序作出准予房地产估价师注册许可的； （四）对不符合法定条件的申请人作出准予房地产估价师注册许可的； （五）依法可以撤销房地产估价师注册的其他情形。 申请人以欺骗、贿赂等不正当手段获准房地产估价师注册许可的，应当予以撤销。"},{"i":32,"n":"第三十二条","txt":"注册房地产估价师及其聘用单位应当按照要求，向注册机关提供真实、准确、完整的注册房地产估价师信用档案信息。 注册房地产估价师信用档案应当包括注册房地产估价师的基本情况、业绩、良好行为、不良行为等内容。违法违规行为、被投诉举报处理、行政处罚等情况应当作为注册房地产估价师的不良行为记入其信用档案。 注册房地产估价师信用档案信息按照有关规定向社会公示。"},{"i":33,"n":"第三十三条","txt":"隐瞒有关情况或者提供虚假材料申请房地产估价师注册的，建设（房地产）主管部门不予受理或者不予行政许可，并给予警告，在1年内不得再次申请房地产估价师注册。"},{"i":34,"n":"第三十四条","txt":"聘用单位为申请人提供虚假注册材料的，由省、自治区、直辖市人民政府建设（房地产）主管部门给予警告，并可处以1万元以上3万元以下的罚款。"},{"i":35,"n":"第三十五条","txt":"以欺骗、贿赂等不正当手段取得注册证书的，由国务院住房城乡建设主管部门撤销其注册，3年内不得再次申请注册，并由县级以上地方人民政府建设（房地产）主管部门处以罚款，其中没有违法所得的，处以1万元以下罚款，有违法所得的，处以违法所得3倍以下且不超过3万元的罚款；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"违反本办法规定，未经注册，擅自以注册房地产估价师名义从事房地产估价活动的，所签署的估价报告无效，由县级以上地方人民政府建设（房地产）主管部门给予警告，责令停止违法活动，并可处以1万元以上3万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":37,"n":"第三十七条","txt":"违反本办法规定，未办理变更注册仍执业的，由县级以上地方人民政府建设（房地产）主管部门责令限期改正；逾期不改正的，可处以5000元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"注册房地产估价师有本办法第二十六条行为之一的，由县级以上地方人民政府建设（房地产）主管部门给予警告，责令其改正，没有违法所得的，处以1万元以下罚款，有违法所得的，处以违法所得3倍以下且不超过3万元的罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"违反本办法规定，注册房地产估价师或者其聘用单位未按照要求提供房地产估价师信用档案信息的，由县级以上地方人民政府建设（房地产）主管部门责令限期改正；逾期未改正的，可处以1000元以上1万元以下的罚款。"},{"i":40,"n":"第四十条","txt":"县级以上地方人民政府建设（房地产）主管部门依法给予注册房地产估价师或其聘用单位行政处罚的，应当将行政处罚决定以及给予行政处罚的事实、理由和依据，报国务院住房城乡建设主管部门备案。"},{"i":41,"n":"第四十一条","txt":"县级以上人民政府建设（房地产）主管部门，在房地产估价师注册管理工作中，有下列情形之一的，由其上级行政机关或者监察机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）对不符合本办法规定条件的申请人准予房地产估价师注册的； （二）对符合本办法规定条件的申请人不予房地产估价师注册或者不在法定期限内作出准予注册决定的； （三）对符合法定条件的申请不予受理或者未在法定期限内初审完毕的； （四）利用职务上的便利，收受他人财物或者其他好处的； （五）不依法履行监督管理职责或者监督不力，造成严重后果的。"},{"i":42,"n":"第四十二条","txt":"大专院校、科研院所从事房地产教学、研究的人员取得执业资格的，经所在单位同意，可以参照本办法注册，但不得担任房地产估价机构法定代表人或者执行合伙人。"},{"i":43,"n":"第四十三条","txt":"本办法自2007年3月1日起施行。1998年8月20日发布的《房地产估价师注册管理办法》（建设部令第64号）、2001年8月15日发布的《建设部关于修改〈房地产估价师注册管理办法〉的决定》（建设部令第100号）同时废止。"}],"zhucejianligongchengshiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对注册监理工程师的管理，维护公共利益和建筑市场秩序，提高工程监理质量与水平，根据《中华人民共和国建筑法》、《建设工程质量管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内注册监理工程师的注册、执业、继续教育和监督管理，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称注册监理工程师，是指经考试取得中华人民共和国监理工程师资格证书（以下简称资格证书），并按照本规定注册，取得中华人民共和国注册监理工程师注册执业证书（以下简称注册证书）和执业印章，从事工程监理及相关业务活动的专业技术人员。 未取得注册证书和执业印章的人员，不得以注册监理工程师的名义从事工程监理及相关业务活动。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门对全国注册监理工程师的注册、执业活动实施统一监督管理。 县级以上地方人民政府住房城乡建设主管部门对本行政区域内的注册监理工程师的注册、执业活动实施监督管理。"},{"i":5,"n":"第五条","txt":"注册监理工程师实行注册执业管理制度。 取得资格证书的人员，经过注册方能以注册监理工程师的名义执业。"},{"i":6,"n":"第六条","txt":"注册监理工程师依据其所学专业、工作经历、工程业绩，按照《工程监理企业资质管理规定》划分的工程类别，按专业注册。每人最多可以申请两个专业注册。"},{"i":7,"n":"第七条","txt":"取得资格证书的人员申请注册，由国务院住房城乡建设主管部门审批。 取得资格证书并受聘于一个建设工程勘察、设计、施工、监理、招标代理、造价咨询等单位的人员，应当通过聘用单位提出注册申请，并可以向单位工商注册所在地的省、自治区、直辖市人民政府住房城乡建设主管部门提交申请材料；省、自治区、直辖市人民政府住房城乡建设主管部门收到申请材料后，应当在5日内将全部申请材料报审批部门。"},{"i":8,"n":"第八条","txt":"国务院住房城乡建设主管部门在收到申请材料后，应当依法作出是否受理的决定，并出具凭证；申请材料不齐全或者不符合法定形式的，应当在5日内一次性告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。 对申请初始注册的，国务院住房城乡建设主管部门应当自受理申请之日起20日内审批完毕并作出书面决定。自作出决定之日起10日内公告审批结果。 对申请变更注册、延续注册的，国务院住房城乡建设主管部门应当自受理申请之日起10日内审批完毕并作出书面决定。 符合条件的，由国务院住房城乡建设主管部门核发注册证书，并核定执业印章编号。对不予批准的，应当说明理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":9,"n":"第九条","txt":"注册证书和执业印章是注册监理工程师的执业凭证，由注册监理工程师本人保管、使用。 注册证书和执业印章的有效期为3年。"},{"i":10,"n":"第十条","txt":"初始注册者，可自资格证书签发之日起3年内提出申请。逾期未申请者，须符合继续教育的要求后方可申请初始注册。 申请初始注册，应当具备以下条件： （一）经全国注册监理工程师执业资格统一考试合格，取得资格证书； （二）受聘于一个相关单位； （三）达到继续教育要求； （四）没有本规定第十三条所列情形。 初始注册需要提交下列材料： （一）申请人的注册申请表； （二）申请人的资格证书和身份证复印件； （三）申请人与聘用单位签订的聘用劳动合同复印件； （四）所学专业、工作经历、工程业绩、工程类中级及中级以上职称证书等有关证明材料； （五）逾期初始注册的，应当提供达到继续教育要求的证明材料。"},{"i":11,"n":"第十一条","txt":"注册监理工程师每一注册有效期为3年，注册有效期满需继续执业的，应当在注册有效期满30日前，按照本规定第七条规定的程序申请延续注册。延续注册有效期3年。延续注册需要提交下列材料： （一）申请人延续注册申请表； （二）申请人与聘用单位签订的聘用劳动合同复印件； （三）申请人注册有效期内达到继续教育要求的证明材料。"},{"i":12,"n":"第十二条","txt":"在注册有效期内，注册监理工程师变更执业单位，应当与原聘用单位解除劳动关系，并按本规定第七条规定的程序办理变更注册手续，变更注册后仍延续原注册有效期。 变更注册需要提交下列材料： （一）申请人变更注册申请表； （二）申请人与新聘用单位签订的聘用劳动合同复印件； （三）申请人的工作调动证明（与原聘用单位解除聘用劳动合同或者聘用劳动合同到期的证明文件、退休人员的退休证明）。"},{"i":13,"n":"第十三条","txt":"申请人有下列情形之一的，不予初始注册、延续注册或者变更注册： （一）不具有完全民事行为能力的； （二）刑事处罚尚未执行完毕或者因从事工程监理或者相关业务受到刑事处罚，自刑事处罚执行完毕之日起至申请注册之日止不满2年的； （三）未达到监理工程师继续教育要求的； （四）在两个或者两个以上单位申请注册的； （五）以虚假的职称证书参加考试并取得资格证书的； （六）年龄超过65周岁的； （七）法律、法规规定不予注册的其他情形。"},{"i":14,"n":"第十四条","txt":"注册监理工程师有下列情形之一的，其注册证书和执业印章失效： （一）聘用单位破产的； （二）聘用单位被吊销营业执照的； （三）聘用单位被吊销相应资质证书的； （四）已与聘用单位解除劳动关系的； （五）注册有效期满且未延续注册的； （六）年龄超过65周岁的； （七）死亡或者丧失行为能力的； （八）其他导致注册失效的情形。"},{"i":15,"n":"第十五条","txt":"注册监理工程师有下列情形之一的，负责审批的部门应当办理注销手续，收回注册证书和执业印章或者公告其注册证书和执业印章作废： （一）不具有完全民事行为能力的； （二）申请注销注册的； （三）有本规定第十四条所列情形发生的； （四）依法被撤销注册的； （五）依法被吊销注册证书的； （六）受到刑事处罚的； （七）法律、法规规定应当注销注册的其他情形。 注册监理工程师有前款情形之一的，注册监理工程师本人和聘用单位应当及时向国务院住房城乡建设主管部门提出注销注册的申请；有关单位和个人有权向国务院住房城乡建设主管部门举报；县级以上地方人民政府住房城乡建设主管部门或者有关部门应当及时报告或者告知国务院住房城乡建设主管部门。"},{"i":16,"n":"第十六条","txt":"被注销注册者或者不予注册者，在重新具备初始注册条件，并符合继续教育要求后，可以按照本规定第七条规定的程序重新申请注册。"},{"i":17,"n":"第十七条","txt":"取得资格证书的人员，应当受聘于一个具有建设工程勘察、设计、施工、监理、招标代理、造价咨询等一项或者多项资质的单位，经注册后方可从事相应的执业活动。从事工程监理执业活动的，应当受聘并注册于一个具有工程监理资质的单位。"},{"i":18,"n":"第十八条","txt":"注册监理工程师可以从事工程监理、工程经济与技术咨询、工程招标与采购咨询、工程项目管理服务以及国务院有关部门规定的其他业务。"},{"i":19,"n":"第十九条","txt":"工程监理活动中形成的监理文件由注册监理工程师按照规定签字盖章后方可生效。"},{"i":20,"n":"第二十条","txt":"修改经注册监理工程师签字盖章的工程监理文件，应当由该注册监理工程师进行；因特殊情况，该注册监理工程师不能进行修改的，应当由其他注册监理工程师修改，并签字、加盖执业印章，对修改部分承担责任。"},{"i":21,"n":"第二十一条","txt":"注册监理工程师从事执业活动，由所在单位接受委托并统一收费。"},{"i":22,"n":"第二十二条","txt":"因工程监理事故及相关业务造成的经济损失，聘用单位应当承担赔偿责任；聘用单位承担赔偿责任后，可依法向负有过错的注册监理工程师追偿。"},{"i":23,"n":"第二十三条","txt":"注册监理工程师在每一注册有效期内应当达到国务院住房城乡建设主管部门规定的继续教育要求。继续教育作为注册监理工程师逾期初始注册、延续注册和重新申请注册的条件之一。"},{"i":24,"n":"第二十四条","txt":"继续教育分为必修课和选修课，在每一注册有效期内各为48学时。"},{"i":25,"n":"第二十五条","txt":"注册监理工程师享有下列权利： （一）使用注册监理工程师称谓； （二）在规定范围内从事执业活动； （三）依据本人能力从事相应的执业活动； （四）保管和使用本人的注册证书和执业印章； （五）对本人执业活动进行解释和辩护； （六）接受继续教育； （七）获得相应的劳动报酬； （八）对侵犯本人权利的行为进行申诉。"},{"i":26,"n":"第二十六条","txt":"注册监理工程师应当履行下列义务： （一）遵守法律、法规和有关管理规定； （二）履行管理职责，执行技术标准、规范和规程； （三）保证执业活动成果的质量，并承担相应责任； （四）接受继续教育，努力提高执业水准； （五）在本人执业活动所形成的工程监理文件上签字、加盖执业印章； （六）保守在执业中知悉的国家秘密和他人的商业、技术秘密； （七）不得涂改、倒卖、出租、出借或者以其他形式非法转让注册证书或者执业印章； （八）不得同时在两个或者两个以上单位受聘或者执业； （九）在规定的执业范围和聘用单位业务范围内从事执业活动； （十）协助注册管理机构完成相关工作。"},{"i":27,"n":"第二十七条","txt":"隐瞒有关情况或者提供虚假材料申请注册的，住房城乡建设主管部门不予受理或者不予注册，并给予警告，1年之内不得再次申请注册。"},{"i":28,"n":"第二十八条","txt":"以欺骗、贿赂等不正当手段取得注册证书的，由国务院住房城乡建设主管部门撤销其注册，3年内不得再次申请注册，并由县级以上地方人民政府住房城乡建设主管部门处以罚款，其中没有违法所得的，处以1万元以下罚款，有违法所得的，处以违法所得3倍以下且不超过3万元的罚款；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"违反本规定，未经注册，擅自以注册监理工程师的名义从事工程监理及相关业务活动的，由县级以上地方人民政府住房城乡建设主管部门给予警告，责令停止违法行为，处以3万元以下罚款；造成损失的，依法承担赔偿责任。"},{"i":30,"n":"第三十条","txt":"违反本规定，未办理变更注册仍执业的，由县级以上地方人民政府住房城乡建设主管部门给予警告，责令限期改正；逾期不改的，可处以5000元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"注册监理工程师在执业活动中有下列行为之一的，由县级以上地方人民政府住房城乡建设主管部门给予警告，责令其改正，没有违法所得的，处以1万元以下罚款，有违法所得的，处以违法所得3倍以下且不超过3万元的罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）以个人名义承接业务的； （二）涂改、倒卖、出租、出借或者以其他形式非法转让注册证书或者执业印章的； （三）泄露执业中应当保守的秘密并造成严重后果的； （四）超出规定执业范围或者聘用单位业务范围从事执业活动的； （五）弄虚作假提供执业活动成果的； （六）同时受聘于两个或者两个以上的单位，从事执业活动的； （七）其它违反法律、法规、规章的行为。"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的，国务院住房城乡建设主管部门依据职权或者根据利害关系人的请求，可以撤销监理工程师注册： （一）工作人员滥用职权、玩忽职守颁发注册证书和执业印章的； （二）超越法定职权颁发注册证书和执业印章的； （三）违反法定程序颁发注册证书和执业印章的； （四）对不符合法定条件的申请人颁发注册证书和执业印章的； （五）依法可以撤销注册的其他情形。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府住房城乡建设主管部门的工作人员，在注册监理工程师管理工作中，有下列情形之一的，依法给予处分；构成犯罪的，依法追究刑事责任： （一）对不符合法定条件的申请人颁发注册证书和执业印章的； （二）对符合法定条件的申请人不予颁发注册证书和执业印章的； （三）对符合法定条件的申请人未在法定期限内颁发注册证书和执业印章的； （四）对符合法定条件的申请不予受理或者未在法定期限内初审完毕的； （五）利用职务上的便利，收受他人财物或者其他好处的； （六）不依法履行监督管理职责，或者发现违法行为不予查处的。"},{"i":34,"n":"第三十四条","txt":"注册监理工程师资格考试工作按照国务院住房城乡建设主管部门、国务院人事主管部门的有关规定执行。"},{"i":35,"n":"第三十五条","txt":"香港特别行政区、澳门特别行政区、台湾地区及外籍专业技术人员，申请参加注册监理工程师注册和执业的管理办法另行制定。"},{"i":36,"n":"第三十六条","txt":"本规定自2006年4月1日起施行。1992年6月4日建设部颁布的《监理工程师资格考试和注册试行办法》（建设部令第18号）同时废止。"}],"zhucezaojiagongchengshiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对注册造价工程师的管理，规范注册造价工程师执业行为，维护社会公共利益，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内注册造价工程师的注册、执业、继续教育和监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称注册造价工程师，是指通过土木建筑工程或者安装工程专业造价工程师职业资格考试取得造价工程师职业资格证书或者通过资格认定、资格互认，并按照本办法注册后，从事工程造价活动的专业人员。注册造价工程师分为一级注册造价工程师和二级注册造价工程师。"},{"i":4,"n":"第四条","txt":"国务院住房城乡建设主管部门对全国注册造价工程师的注册、执业活动实施统一监督管理，负责实施全国一级注册造价工程师的注册，并负责建立全国统一的注册造价工程师注册信息管理平台；国务院有关专业部门按照国务院规定的职责分工，对本行业注册造价工程师的执业活动实施监督管理。 省、自治区、直辖市人民政府住房城乡建设主管部门对本行政区域内注册造价工程师的执业活动实施监督管理，并实施本行政区域二级注册造价工程师的注册。"},{"i":5,"n":"第五条","txt":"工程造价行业组织应当加强造价工程师自律管理。 鼓励注册造价工程师加入工程造价行业组织。"},{"i":6,"n":"第六条","txt":"注册造价工程师实行注册执业管理制度。 取得职业资格的人员，经过注册方能以注册造价工程师的名义执业。"},{"i":7,"n":"第七条","txt":"注册造价工程师的注册条件为： （一）取得职业资格； （二）受聘于一个工程造价咨询企业或者工程建设领域的建设、勘察设计、施工、招标代理、工程监理、工程造价管理等单位； （三）无本办法第十三条不予注册的情形。"},{"i":8,"n":"第八条","txt":"符合注册条件的人员申请注册的，可以向聘用单位工商注册所在地的省、自治区、直辖市人民政府住房城乡建设主管部门或者国务院有关专业部门提交申请材料。 申请一级注册造价工程师初始注册，省、自治区、直辖市人民政府住房城乡建设主管部门或者国务院有关专业部门收到申请材料后，应当在5日内将申请材料报国务院住房城乡建设主管部门。国务院住房城乡建设主管部门在收到申请材料后，应当依法做出是否受理的决定，并出具凭证；申请材料不齐全或者不符合法定形式的，应当在5日内一次性告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。国务院住房城乡建设主管部门应当自受理之日起20日内作出决定。 申请二级注册造价工程师初始注册，省、自治区、直辖市人民政府住房城乡建设主管部门收到申请材料后，应当依法做出是否受理的决定，并出具凭证；申请材料不齐全或者不符合法定形式的，应当在5日内一次性告知申请人需要补正的全"},{"i":9,"n":"第九条","txt":"准予注册的，由国务院住房城乡建设主管部门或者省、自治区、直辖市人民政府住房城乡建设主管部门（以下简称注册机关）核发注册造价工程师注册证书，注册造价工程师按照规定自行制作执业印章。 注册证书和执业印章是注册造价工程师的执业凭证，由注册造价工程师本人保管、使用。注册证书、执业印章的样式以及编码规则由国务院住房城乡建设主管部门统一制定。 一级注册造价工程师注册证书由国务院住房城乡建设主管部门印制；二级注册造价工程师注册证书由省、自治区、直辖市人民政府住房城乡建设主管部门按照规定分别印制。 注册造价工程师遗失注册证书，应当按照本办法第八条规定的延续注册程序申请补发，并由注册机关在官网发布信息。"},{"i":10,"n":"第十条","txt":"取得职业资格证书的人员，可自职业资格证书签发之日起1年内申请初始注册。逾期未申请者，须符合继续教育的要求后方可申请初始注册。初始注册的有效期为4年。 申请初始注册的，应当提交下列材料： （一）初始注册申请表； （二）职业资格证书和身份证件； （三）与聘用单位签订的劳动合同； （四）取得职业资格证书的人员，自资格证书签发之日起1年后申请初始注册的，应当提供当年的继续教育合格证明； （五）外国人应当提供外国人就业许可证书。 申请初始注册时，造价工程师本人和单位应当对下列事项进行承诺，并由注册机关调查核实： （一）受聘于工程造价岗位； （二）聘用单位为其交纳社会基本养老保险或者已办理退休。"},{"i":11,"n":"第十一条","txt":"注册造价工程师注册有效期满需继续执业的，应当在注册有效期满30日前，按照本办法第八条规定的程序申请延续注册。延续注册的有效期为4年。 申请延续注册的，应当提交下列材料： （一）延续注册申请表； （二）注册证书； （三）申请延续注册时，造价工程师本人和单位应对其前一个注册的工作业绩进行承诺，并由注册机关调查核实。 （四）与聘用单位签订的劳动合同。 （五）继续教育合格证明。"},{"i":12,"n":"第十二条","txt":"在注册有效期内，注册造价工程师变更执业单位的，应当与原聘用单位解除劳动合同，并按照本办法第八条规定的程序，到新聘用单位工商注册所在地的省、自治区、直辖市人民政府住房城乡建设主管部门或者国务院有关专业部门办理变更注册手续。变更注册后延续原注册有效期。 申请变更注册的，应当提交下列材料： （一）变更注册申请表； （二）注册证书； （三）与新聘用单位签订的劳动合同。 申请变更注册时，造价工程师本人和单位应当对下列事项进行承诺，并由注册机关调查核实： （一）与原聘用单位解除劳动合同； （二）聘用单位为其交纳社会基本养老保险或者已办理退休。"},{"i":13,"n":"第十三条","txt":"有下列情形之一的，不予注册： （一）不具有完全民事行为能力的； （二）申请在两个或者两个以上单位注册的； （三）未达到造价工程师继续教育合格标准的； （四）前一个注册期内工作业绩达不到规定标准或未办理暂停执业手续而脱离工程造价业务岗位的； （五）受刑事处罚，刑事处罚尚未执行完毕的； （六）因工程造价业务活动受刑事处罚，自刑事处罚执行完毕之日起至申请注册之日止不满5年的； （七）因前项规定以外原因受刑事处罚，自处罚决定之日起至申请注册之日止不满3年的； （八）被吊销注册证书，自被处罚决定之日起至申请注册之日止不满3年的； （九）以欺骗、贿赂等不正当手段获准注册被撤销，自被撤销注册之日起至申请注册之日止不满3年的； （十）法律、法规规定不予注册的其他情形。"},{"i":14,"n":"第十四条","txt":"被注销注册或者不予注册者，在具备注册条件后重新申请注册的，按照本办法第八条规定的程序办理。"},{"i":15,"n":"第十五条","txt":"一级注册造价工程师执业范围包括建设项目全过程的工程造价管理与工程造价咨询等，具体工作内容： （一）项目建议书、可行性研究投资估算与审核，项目评价造价分析； （二）建设工程设计概算、施工预算编制和审核； （三）建设工程招标投标文件工程量和造价的编制与审核； （四）建设工程合同价款、结算价款、竣工决算价款的编制与管理； （五）建设工程审计、仲裁、诉讼、保险中的造价鉴定，工程造价纠纷调解； （六）建设工程计价依据、造价指标的编制与管理； （七）与工程造价管理有关的其他事项。 二级注册造价工程师协助一级注册造价工程师开展相关工作，并可以独立开展以下工作： （一）建设工程工料分析、计划、组织与成本管理，施工图预算、设计概算编制； （二）建设工程量清单、最高投标限价、投标报价编制； （三）建设工程合同价款、结算价款和竣工决算价款的编制。"},{"i":16,"n":"第十六条","txt":"注册造价工程师享有下列权利： （一）使用注册造价工程师名称； （二）依法从事工程造价业务； （三）在本人执业活动中形成的工程造价成果文件上签字并加盖执业印章； （四）发起设立工程造价咨询企业； （五）保管和使用本人的注册证书和执业印章； （六）参加继续教育。"},{"i":17,"n":"第十七条","txt":"注册造价工程师应当履行下列义务： （一）遵守法律、法规、有关管理规定，恪守职业道德； （二）保证执业活动成果的质量； （三）接受继续教育，提高执业水平； （四）执行工程造价计价标准和计价方法； （五）与当事人有利害关系的，应当主动回避； （六）保守在执业中知悉的国家秘密和他人的商业、技术秘密。"},{"i":18,"n":"第十八条","txt":"注册造价工程师应当根据执业范围，在本人形成的工程造价成果文件上签字并加盖执业印章，并承担相应的法律责任。最终出具的工程造价成果文件应当由一级注册造价工程师审核并签字盖章。"},{"i":19,"n":"第十九条","txt":"修改经注册造价工程师签字盖章的工程造价成果文件，应当由签字盖章的注册造价工程师本人进行；注册造价工程师本人因特殊情况不能进行修改的，应当由其他注册造价工程师修改，并签字盖章；修改工程造价成果文件的注册造价工程师对修改部分承担相应的法律责任。"},{"i":20,"n":"第二十条","txt":"注册造价工程师不得有下列行为： （一）不履行注册造价工程师义务； （二）在执业过程中，索贿、受贿或者谋取合同约定费用外的其他利益； （三）在执业过程中实施商业贿赂； （四）签署有虚假记载、误导性陈述的工程造价成果文件； （五）以个人名义承接工程造价业务； （六）允许他人以自己名义从事工程造价业务； （七）同时在两个或者两个以上单位执业； （八）涂改、倒卖、出租、出借或者以其他形式非法转让注册证书或者执业印章； （九）超出执业范围、注册专业范围执业。 （十）法律、法规、规章禁止的其他行为。"},{"i":21,"n":"第二十一条","txt":"在注册有效期内，注册造价工程师因特殊原因需要暂停执业的，应当到注册机关办理暂停执业手续，并交回注册证书和执业印章。"},{"i":22,"n":"第二十二条","txt":"注册造价工程师应当适应岗位需要和职业发展的要求，按照国家专业技术人员继续教育的有关规定接受继续教育，更新专业知识，提高专业水平。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府住房城乡建设主管部门和其他有关部门应当依照有关法律、法规和本办法的规定，对注册造价工程师的注册、执业和继续教育实施监督检查。"},{"i":24,"n":"第二十四条","txt":"国务院住房城乡建设主管部门应当将造价工程师注册信息告知省、自治区、直辖市人民政府住房城乡建设主管部门和国务院有关专业部门。 省、自治区、直辖市人民政府住房城乡建设主管部门应当将造价工程师注册信息告知本行政区域内市、县人民政府住房城乡建设主管部门。"},{"i":25,"n":"第二十五条","txt":"县级以上人民政府住房城乡建设主管部门和其他有关部门依法履行监督检查职责时，有权采取下列措施： （一）要求被检查人员提供注册证书； （二）要求被检查人员所在聘用单位提供有关人员签署的工程造价成果文件及相关业务文档； （三）就有关问题询问签署工程造价成果文件的人员； （四）纠正违反有关法律、法规和本办法及工程造价计价标准和计价办法的行为。"},{"i":26,"n":"第二十六条","txt":"注册造价工程师违法从事工程造价活动的，违法行为发生地县级以上地方人民政府住房城乡建设主管部门或者其他有关部门应当依法查处，并将违法事实、处理结果告知注册机关；依法应当撤销注册的，应当将违法事实、处理建议及有关材料报注册机关。"},{"i":27,"n":"第二十七条","txt":"注册造价工程师有下列情形之一的，其注册证书失效： （一）已与聘用单位解除劳动合同且未被其他单位聘用的； （二）注册有效期满且未延续注册的； （三）死亡或者不具有完全民事行为能力的； （四）其他导致注册失效的情形。"},{"i":28,"n":"第二十八条","txt":"有下列情形之一的，注册机关或者其上级行政机关依据职权或者根据利害关系人的请求，可以撤销注册造价工程师的注册： （一）行政机关工作人员滥用职权、玩忽职守作出准予注册许可的； （二）超越法定职权作出准予注册许可的； （三）违反法定程序作出准予注册许可的； （四）对不具备注册条件的申请人作出准予注册许可的； （五）依法可以撤销注册的其他情形。 申请人以欺骗、贿赂等不正当手段获准注册的，应当予以撤销。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，由注册机关办理注销注册手续，收回注册证书和执业印章或者公告其注册证书和执业印章作废： （一）有本办法第二十七条所列情形发生的； （二）依法被撤销注册的； （三）依法被吊销注册证书的； （四）受到刑事处罚的； （五）法律、法规规定应当注销注册的其他情形。 注册造价工程师有前款所列情形之一的，注册造价工程师本人和聘用单位应当及时向注册机关提出注销注册申请；有关单位和个人有权向注册机关举报；县级以上地方人民政府住房城乡建设主管部门或者其他有关部门应当及时告知注册机关。"},{"i":30,"n":"第三十条","txt":"注册造价工程师及其聘用单位应当按照有关规定，向注册机关提供真实、准确、完整的注册造价工程师信用档案信息。 注册造价工程师信用档案应当包括造价工程师的基本情况、业绩、良好行为、不良行为等内容。违法违规行为、被投诉举报处理、行政处罚等情况应当作为造价工程师的不良行为记入其信用档案。 注册造价工程师信用档案信息按有关规定向社会公示。"},{"i":31,"n":"第三十一条","txt":"隐瞒有关情况或者提供虚假材料申请造价工程师注册的，不予受理或者不予注册，并给予警告，申请人在1年内不得再次申请造价工程师注册。"},{"i":32,"n":"第三十二条","txt":"聘用单位为申请人提供虚假注册材料的，由县级以上地方人民政府住房城乡建设主管部门或者其他有关部门给予警告，并可处以1万元以上3万元以下的罚款。"},{"i":33,"n":"第三十三条","txt":"以欺骗、贿赂等不正当手段取得造价工程师注册的，由注册机关撤销其注册，3年内不得再次申请注册，并由县级以上地方人民政府住房城乡建设主管部门处以罚款。其中，没有违法所得的，处以1万元以下罚款；有违法所得的，处以违法所得3倍以下且不超过3万元的罚款。"},{"i":34,"n":"第三十四条","txt":"违反本办法规定，未经注册而以注册造价工程师的名义从事工程造价活动的，所签署的工程造价成果文件无效，由县级以上地方人民政府住房城乡建设主管部门或者其他有关部门给予警告，责令停止违法活动，并可处以1万元以上3万元以下的罚款。"},{"i":35,"n":"第三十五条","txt":"违反本办法规定，未办理变更注册而继续执业的，由县级以上人民政府住房城乡建设主管部门或者其他有关部门责令限期改正；逾期不改的，可处以5000元以下的罚款。"},{"i":36,"n":"第三十六条","txt":"注册造价工程师有本办法第二十条规定行为之一的，由县级以上地方人民政府住房城乡建设主管部门或者其他有关部门给予警告，责令改正，没有违法所得的，处以1万元以下罚款，有违法所得的，处以违法所得3倍以下且不超过3万元的罚款。"},{"i":37,"n":"第三十七条","txt":"违反本办法规定，注册造价工程师或者其聘用单位未按照要求提供造价工程师信用档案信息的，由县级以上地方人民政府住房城乡建设主管部门或者其他有关部门责令限期改正；逾期未改正的，可处以1000元以上1万元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府住房城乡建设主管部门和其他有关部门工作人员，在注册造价工程师管理工作中，有下列情形之一的，依法给予处分；构成犯罪的，依法追究刑事责任： （一）对不符合注册条件的申请人准予注册许可或者超越法定职权作出注册许可决定的； （二）对符合注册条件的申请人不予注册许可或者不在法定期限内作出注册许可决定的； （三）对符合法定条件的申请不予受理的； （四）利用职务之便，收取他人财物或者其他好处的； （五）不依法履行监督管理职责，或者发现违法行为不予查处的。"},{"i":39,"n":"第三十九条","txt":"造价工程师职业资格考试工作按照国务院人力资源社会保障主管部门的有关规定执行。"},{"i":40,"n":"第四十条","txt":"本办法自2007年3月1日起施行。2000年1月21日发布的《造价工程师注册管理办法》（建设部令第75号）同时废止。"}],"shenghuoyinyongshuiweishengjianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为保证生活饮用水（以下简称饮用水）卫生安全，保障人体健康，根据《中华人民共和国传染病防治法》及《城市供水条例》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于集中式供水、二次供水单位（以下简称供水单位）和涉及饮用水卫生安全的产品的卫生监督管理。 凡在中华人民共和国领域内的任何单位和个人均应遵守本办法。"},{"i":3,"n":"第三条","txt":"国务院卫生计生主管部门主管全国饮用水卫生监督工作。县级以上地方人民政府卫生计生主管部门主管本行政区域内饮用水卫生监督工作。 国务院住房城乡建设主管部门主管全国城市饮用水卫生管理工作。县级以上地方人民政府住房城乡建设主管部门主管本行政区域内城镇饮用水卫生管理工作。"},{"i":4,"n":"第四条","txt":"国家对供水单位和涉及饮用水卫生安全的产品实行卫生许可制度。"},{"i":5,"n":"第五条","txt":"国家鼓励有益于饮用水卫生安全的新产品、新技术、新工艺的研制开发和推广应用。"},{"i":6,"n":"第六条","txt":"供水单位供应的饮用水必须符合国家生活饮用水卫生标准。"},{"i":7,"n":"第七条","txt":"集中式供水单位取得工商行政管理部门颁发的营业执照后，还应当取得县级以上地方人民政府卫生计生主管部门颁发的卫生许可证，方可供水。"},{"i":8,"n":"第八条","txt":"供水单位新建、改建、扩建的饮用水供水工程项目，应当符合卫生要求，选址和设计审查、竣工验收必须有建设、卫生行政主管部门参加。 新建、改建、扩建的城市公共饮用水供水工程项目由住房城乡建设主管部门负责组织选址、设计审查和竣工验收，卫生计生主管部门参加。"},{"i":9,"n":"第九条","txt":"供水单位应建立饮用水卫生管理规章制度，配备专职或兼职人员，负责饮用水卫生管理工作。"},{"i":10,"n":"第十条","txt":"集中式供水单位必须有水质净化消毒设施及必要的水质检验仪器、设备和人员，对水质进行日常性检验，并向当地人民政府卫生计生主管部门和住房城乡建设主管部门报送检测资料。 城市自来水供水企业和自建设施对外供水的企业，其生产管理制度的建立和执行、人员上岗的资格和水质日常检测工作由城市住房城乡建设主管部门负责管理。"},{"i":11,"n":"第十一条","txt":"直接从事供、管水的人员必须取得体检合格证后方可上岗工作，并每年进行一次健康检查。 凡患有痢疾、伤寒、病毒性肝炎、活动性肺结核、化脓性或渗出性皮肤病及其他有碍饮用水卫生的疾病的和病原携带者，不得直接从事供、管水工作。 直接从事供、管水的人员，未经卫生知识培训不得上岗工作。"},{"i":12,"n":"第十二条","txt":"生产涉及饮用水卫生安全的产品的单位和个人，必须按规定向政府卫生计生主管部门申请办理产品卫生许可批准文件，取得批准文件后，方可生产和销售。 任何单位和个人不得生产、销售、使用无批准文件的前款产品。"},{"i":13,"n":"第十三条","txt":"饮用水水源地必须设置水源保护区。保护区内严禁修建任何可能危害水源水质卫生的设施及一切有碍水源水质卫生的行为。"},{"i":14,"n":"第十四条","txt":"二次供水设施选址、设计、施工及所用材料，应保证不使饮用水水质受到污染，并有利于清洗和消毒。各类蓄水设施要加强卫生防护，定期清洗和消毒。具体管理办法由省、自治区、直辖市根据本地区情况另行规定。"},{"i":15,"n":"第十五条","txt":"当饮用水被污染，可能危及人体健康时，有关单位或责任人应立即采取措施，消除污染，并向当地人民政府卫生计生主管部门和住房城乡建设主管部门报告。"},{"i":16,"n":"第十六条","txt":"县级以上人民政府卫生计生主管部门负责本行政区域内饮用水卫生监督监测工作。 供水单位的供水范围在本行政区域内的，由该行政区人民政府卫生计生主管部门负责其饮用水卫生监督监测工作； 供水单位的供水范围超出其所在行政区域的，由供水单位所在行政区域的上一级人民政府卫生计生主管部门负责其饮用水卫生监督监测工作； 供水单位的供水范围超出其所在省、自治区、直辖市的，由该供水单位所在省、自治区、直辖市人民政府卫生计生主管部门负责其饮用水卫生监督监测工作。 铁道、交通、民航行政主管部门设立的卫生监督机构，行使国务院卫生计生主管部门会同国务院有关部门规定的饮用水卫生监督职责。"},{"i":17,"n":"第十七条","txt":"新建、改建、扩建集中式供水项目时，当地人民政府卫生计生主管部门应做好预防性卫生监督工作，并负责本行政区域内饮用水的水源水质监测和评价。"},{"i":18,"n":"第十八条","txt":"医疗单位发现因饮用水污染出现的介水传染病或化学中毒病例时，应及时向当地人民政府卫生计生主管部门和卫生防疫机构报告。"},{"i":19,"n":"第十九条","txt":"县级以上地方人民政府卫生计生主管部门负责本行政区域内饮用水污染事故对人体健康影响的调查。当发现饮用水污染危及人体健康，须停止使用时，对二次供水单位应责令其立即停止供水；对集中式供水单位应当会同城市住房城乡建设主管部门报同级人民政府批准后停止供水。"},{"i":20,"n":"第二十条","txt":"供水单位卫生许可证由县级以上人民政府卫生计生主管部门按照本办法第十六条规定的管理范围发放，有效期四年，有效期满前六个月重新提出申请换发新证。"},{"i":21,"n":"第二十一条","txt":"涉及饮用水卫生安全的产品，应当按照有关规定进行卫生安全性评价，符合卫生标准和卫生规范要求。 利用新材料、新工艺和新化学物质生产的涉及饮用水卫生安全产品应当取得国务院卫生计生主管部门颁发的卫生许可批准文件；除利用新材料、新工艺和新化学物质外生产的其他涉及饮用水卫生安全产品应当取得省级人民政府卫生计生主管部门颁发的卫生许可批准文件。 涉及饮用水卫生安全产品的卫生许可批准文件的有效期为四年。"},{"i":22,"n":"第二十二条","txt":"凡取得卫生许可证的单位或个人，以及取得卫生许可批准文件的饮用水卫生安全的产品，经日常监督检查，发现已不符合卫生许可证颁发条件或不符合卫生许可批准文件颁发要求的，原批准机关有权收回有关证件或批准文件。"},{"i":23,"n":"第二十三条","txt":"县级以上人民政府卫生计生主管部门设饮用水卫生监督员，负责饮用水卫生监督工作。县级人民政府卫生计生主管部门可聘任饮用水卫生检查员，负责乡、镇饮用水卫生检查工作。 饮用水卫生监督员由县级以上人民政府卫生计生主管部门发给证书，饮用水卫生检查员由县级人民政府卫生计生主管部门发给证书。 铁道、交通、民航的饮用水卫生监督员，由其上级行政主管部门发给证书。"},{"i":24,"n":"第二十四条","txt":"饮用水卫生监督员应秉公执法，忠于职守，不得利用职权谋取私利。"},{"i":25,"n":"第二十五条","txt":"集中式供水单位安排未取得体检合格证的人员从事直接供、管水工作或安排患有有碍饮用水卫生疾病的或病原携带者从事直接供、管水工作的，县级以上地方人民政府卫生计生主管部门应当责令限期改进，并可对供水单位处以20元以上1000元以下的罚款。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，有下列情形之一的，县级以上地方人民政府卫生计生主管部门应当责令限期改进，并可处以20元以上5000元以下的罚款： （一）在饮用水水源保护区修建危害水源水质卫生的设施或进行有碍水源水质卫生的作业的； （二）新建、改建、扩建的饮用水供水项目未经卫生计生主管部门参加选址、设计审查和竣工验收而擅自供水的； （三）供水单位未取得卫生许可证而擅自供水的； （四）供水单位供应的饮用水不符合国家规定的生活饮用水卫生标准的；"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，生产或者销售无卫生许可批准文件的涉及饮用水卫生安全的产品的，县级以上地方人民政府卫生计生主管部门应当责令改进，并可处以违法所得３倍以下的罚款，但最高不超过30000元，或处以500元以上10000元以下的罚款。"},{"i":28,"n":"第二十八条","txt":"城市自来水供水企业和自建设施对外供水的企业，有下列行为之一的，由住房城乡建设主管部门责令限期改进，并可处以违法所得3倍以下的罚款，但最高不超过30000元，没有违法所得的可处以10000元以下罚款： （一）新建、改建、扩建的饮用水供水工程项目未经住房城乡建设主管部门设计审查和竣工验收而擅自建设并投入使用的； （二）未按规定进行日常性水质检验工作的；"},{"i":29,"n":"第二十九条","txt":"本办法下列用语的含义是： 集中式供水：由水源集中取水，经统一净化处理和消毒后，由输水管网送至用户的供水方式（包括公共供水和单位自建设施供水）。 二次供水：将来自集中式供水的管道水另行加压，贮存，再送至水站或用户的供水设施；包括客运船舶、火车客车等交通运输工具上的供水（有独自制水设施者除外）。 涉及饮用水卫生安全的产品：凡在饮用水生产和供水过程中与饮用水接触的联接止水材料、塑料及有机合成管材、管件、防护涂料、水处理剂、除垢剂、水质处理器及其他新材料和化学物质。 直接从事供、管水的人员：从事净水、取样、化验、二次供水卫生管理及水池、水箱清洗人员。"},{"i":30,"n":"第三十条","txt":"本办法由国务院卫生计生主管部门、国务院住房城乡建设主管部门负责解释。"},{"i":31,"n":"第三十一条","txt":"本办法自一九九七年一月一日起施行。"}],"shengyuchengzhentixiguihuabianzhishenpibanfa":[{"i":1,"n":"第一条","txt":"为了规范省域城镇体系规划编制和审批工作，提高规划的科学性，根据《中华人民共和国城乡规划法》，制定本办法。"},{"i":2,"n":"第二条","txt":"省域城镇体系规划的编制和审批，适用本办法。"},{"i":3,"n":"第三条","txt":"省域城镇体系规划是省、自治区人民政府实施城乡规划管理，合理配置省域空间资源，优化城乡空间布局，统筹基础设施和公共设施建设的基本依据，是落实全国城镇体系规划，引导本省、自治区城镇化和城镇发展，指导下层次规划编制的公共政策。"},{"i":4,"n":"第四条","txt":"编制省域城镇体系规划，应当以科学发展观为指导，坚持城乡统筹规划，促进区域协调发展；坚持因地制宜，分类指导；坚持走有中国特色的城镇化道路，节约集约利用资源、能源，保护自然人文资源和生态环境。"},{"i":5,"n":"第五条","txt":"编制省域城镇体系规划，应当遵守国家有关法律、行政法规，并与有关规划相协调。"},{"i":6,"n":"第六条","txt":"省域城镇体系规划的编制和管理经费应当纳入省级财政预算。"},{"i":7,"n":"第七条","txt":"经依法批准的省域城镇体系规划应当及时向社会公布，但法律、行政法规规定不得公开的内容除外。"},{"i":8,"n":"第八条","txt":"省、自治区人民政府负责组织编制省域城镇体系规划。省、自治区人民政府城乡规划主管部门负责省域城镇体系规划组织编制的具体工作。"},{"i":9,"n":"第九条","txt":"省、自治区人民政府城乡规划主管部门应当委托具有城乡规划甲级资质证书的单位承担省域城镇体系规划的具体编制工作。"},{"i":10,"n":"第十条","txt":"省域城镇体系规划编制工作一般分为编制省域城镇体系规划纲要（以下简称规划纲要）和编制省域城镇体系规划成果（以下简称规划成果）两个阶段。"},{"i":11,"n":"第十一条","txt":"编制规划纲要的目的是综合评价省、自治区城镇化发展条件及对城乡空间布局的基本要求，分析研究省域相关规划和重大项目布局对城乡空间的影响，明确规划编制的原则和重点，研究提出城镇化目标和拟采取的对策和措施，为编制规划成果提供基础。 编制规划纲要时，应当对影响本省、自治区城镇化和城镇发展的重大问题进行专题研究。"},{"i":12,"n":"第十二条","txt":"省、自治区人民政府城乡规划主管部门应当对规划纲要和规划成果进行充分论证，并征求同级人民政府有关部门和下一级人民政府的意见。"},{"i":13,"n":"第十三条","txt":"国务院城乡规划主管部门应当加强对省域城镇体系规划编制工作的指导。 在规划纲要编制和规划成果编制阶段，国务院城乡规划主管部门应当分别组织对规划纲要和规划成果进行审查，并出具审查意见。"},{"i":14,"n":"第十四条","txt":"省、自治区人民政府城乡规划主管部门向国务院城乡规划主管部门提交审查规划纲要和规划成果时，应当附专题研究报告、规划协调论证的说明和对各方面意见的采纳情况。"},{"i":15,"n":"第十五条","txt":"省域城镇体系规划由省、自治区人民政府报国务院审批。"},{"i":16,"n":"第十六条","txt":"省域城镇体系规划报送审批前，省、自治区人民政府应当将规划成果予以公告，并征求专家和公众的意见。公告时间不得少于三十日。"},{"i":17,"n":"第十七条","txt":"省、自治区人民政府在省域城镇体系规划报国务院审批前，应当将规划成果提请省、自治区人民代表大会常务委员会审议。"},{"i":18,"n":"第十八条","txt":"上报国务院的规划成果应当附具省域城镇体系规划说明书、规划编制工作的说明、征求意见和意见采纳的情况、人大常务委员会组成人员的审议意见和根据审议意见修改规划的情况等。"},{"i":19,"n":"第十九条","txt":"省域城镇体系规划成果应当包括规划文本、图纸，以书面和电子文件两种形式表达。 规划成果的表达应当清晰、规范，符合城乡规划有关的技术标准和技术规范。"},{"i":20,"n":"第二十条","txt":"修改省域城镇体系规划，应当符合《中华人民共和国城乡规划法》的相关规定。 修改省域城镇体系规划向国务院报告前，省、自治区人民政府城乡规划主管部门应当结合对省域城镇体系规划实施情况的评估，提出规划修改的必要性、修改规划的基本思路和重点，经省、自治区人民政府同意后，向国务院城乡规划主管部门报告。"},{"i":21,"n":"第二十一条","txt":"修改省域城镇体系规划，应当符合本办法规定的省域城镇体系规划的编制审批程序。"},{"i":22,"n":"第二十二条","txt":"根据实施省域城镇体系规划的需要，省、自治区人民政府城乡规划主管部门可以依据经批准的省域城镇体系规划，会同有关部门组织编制省域范围内的区域性专项规划和跨下一级行政单元的规划，落实省域城镇体系规划的要求。"},{"i":23,"n":"第二十三条","txt":"省域范围内的区域性专项规划和跨下一级行政单元的规划，报省、自治区人民政府审批。"},{"i":24,"n":"第二十四条","txt":"规划纲要应当包括下列内容： （一）分析评价现行省域城镇体系规划实施情况，明确规划编制原则、重点和应当解决的主要问题。 （二）按照全国城镇体系规划的要求，提出本省、自治区在国家城镇化与区域协调发展中的地位和作用。 （三）综合评价土地资源、水资源、能源、生态环境承载能力等城镇发展支撑条件和制约因素，提出城镇化进程中重要资源、能源合理利用与保护、生态环境保护和防灾减灾的要求。 （四）综合分析经济社会发展目标和产业发展趋势、城乡人口流动和人口分布趋势、省域内城镇化和城镇发展的区域差异等影响本省、自治区城镇发展的主要因素，提出城镇化的目标、任务及要求。 （五）按照城乡区域全面协调可持续发展的要求，综合考虑经济社会发展与人口资源环境条件，提出优化城乡空间格局的规划要求，包括省域城乡空间布局，城乡居民点体系和优化农村居民点布局的要求；提出省域综合交通和重大市政基础设施、公共设施布局的建议；提出需要从"},{"i":25,"n":"第二十五条","txt":"规划成果应当包括下列内容： （一）明确全省、自治区城乡统筹发展的总体要求。包括城镇化目标和战略，城镇化发展质量目标及相关指标，城镇化途径和相应的城镇协调发展政策和策略；城乡统筹发展目标、城乡结构变化趋势和规划策略；根据省、自治区内的区域差异提出分类指导的城镇化政策。 （二）明确资源利用与资源生态环境保护的目标、要求和措施。包括土地资源、水资源、能源等的合理利用与保护，历史文化遗产的保护，地域传统文化特色的体现，生态环境保护。 （三）明确省域城乡空间和规模控制要求。包括中心城市等级体系和空间布局；需要从省域层面重点协调、引导地区的定位及协调、引导措施；优化农村居民点布局的目标、原则和规划要求。 （四）明确与城乡空间布局相协调的区域综合交通体系。包括省域综合交通发展目标、策略及综合交通设施与城乡空间布局协调的原则，省域综合交通网络和重要交通设施布局，综合交通枢纽城市及其规划要求。 （五）明"},{"i":26,"n":"第二十六条","txt":"限制建设区、禁止建设区的管制要求，重要资源和生态环境保护目标，省域内区域性重大基础设施布局等，应当作为省域城镇体系规划的强制性内容。"},{"i":27,"n":"第二十七条","txt":"省域城镇体系规划的规划期限一般为二十年，还可以对资源生态环境保护和城乡空间布局等重大问题作出更长远的预测性安排。"},{"i":28,"n":"第二十八条","txt":"省域范围内的区域性专项规划和跨下一级行政单元规划内容和编制审批的具体要求，由各地参照本办法确定。"},{"i":29,"n":"第二十九条","txt":"本办法自2010年7月1日起施行。1994年8月15日建设部发布的《城镇体系规划编制审批办法》（建设部令第36号）同时废止。"}],"chaoxiangaocengjianzhugongchengkangzhenshefangguancf2d2e":[{"i":1,"n":"第一条","txt":"为了加强超限高层建筑工程的抗震设防管理，提高超限高层建筑工程抗震设计的可靠性和安全性，保证超限高层建筑工程抗震设防的质量，根据《中华人民共和国建筑法》、《中华人民共和国防震减灾法》、《建设工程质量管理条例》、《建设工程勘察设计管理条例》等法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于抗震设防区内超限高层建筑工程的抗震设防管理。 本规定所称超限高层建筑工程，是指超出国家现行规范、规程所规定的适用高度和适用结构类型的高层建筑工程，体型特别不规则的高层建筑工程，以及有关规范、规程规定应当进行抗震专项审查的高层建筑工程。"},{"i":3,"n":"第三条","txt":"国务院建设行政主管部门负责全国超限高层建筑工程抗震设防的管理工作。 省、自治区、直辖市人民政府建设行政主管部门负责本行政区内超限高层建筑工程抗震设防的管理工作。"},{"i":4,"n":"第四条","txt":"超限高层建筑工程的抗震设防应当采取有效的抗震措施，确保超限高层建筑工程达到规范规定的抗震设防目标。"},{"i":5,"n":"第五条","txt":"在抗震设防区内进行超限高层建筑工程的建设时，建设单位应当在初步设计阶段向工程所在地的省、自治区、直辖市人民政府建设行政主管部门提出专项报告。"},{"i":6,"n":"第六条","txt":"超限高层建筑工程所在地的省、自治区、直辖市人民政府建设行政主管部门，负责组织省、自治区、直辖市超限高层建筑工程抗震设防专家委员会对超限高层建筑工程进行抗震设防专项审查。 审查难度大或者审查意见难以统一的，工程所在地的省、自治区、直辖市人民政府建设行政主管部门可请全国超限高层建筑工程抗震设防专家委员会提出专项审查意见，并报国务院建设行政主管部门备案。"},{"i":7,"n":"第七条","txt":"全国和省、自治区、直辖市的超限高层建筑工程抗震设防审查专家委员会委员分别由国务院建设行政主管部门和省、自治区、直辖市人民政府建设行政主管部门聘任。 超限高层建筑工程抗震设防专家委员会应当由长期从事并精通高层建筑工程抗震的勘察、设计、科研、教学和管理专家组成，并对抗震设防专项审查意见承担相应的审查责任。"},{"i":8,"n":"第八条","txt":"超限高层建筑工程的抗震设防专项审查内容包括：建筑的抗震设防分类、抗震设防烈度（或者设计地震动参数）、场地抗震性能评价、抗震概念设计、主要结构布置、建筑与结构的协调、使用的计算程序、结构计算结果、地基基础和上部结构抗震性能评估等。"},{"i":9,"n":"第九条","txt":"建设单位申报超限高层建筑工程的抗震设防专项审查时，应当提供以下材料： （一）超限高层建筑工程抗震设防专项审查表； （二）设计的主要内容、技术依据、可行性论证及主要抗震措施； （三）工程勘察报告； （四）结构设计计算的主要结果； （五）结构抗震薄弱部位的分析和相应措施； （六）初步设计文件； （七）设计时参照使用的国外有关抗震设计标准、工程和震害资料及计算机程序； （八）对要求进行模型抗震性能试验研究的，应当提供抗震试验研究报告。"},{"i":10,"n":"第十条","txt":"建设行政主管部门应当自接到抗震设防专项审查全部申报材料之日起25日内，组织专家委员会提出书面审查意见，并将审查结果通知建设单位。"},{"i":11,"n":"第十一条","txt":"超限高层建筑工程抗震设防专项审查费用由建设单位承担。"},{"i":12,"n":"第十二条","txt":"超限高层建筑工程的勘察、设计、施工、监理，应当由具备甲级（一级及以上）资质的勘察、设计、施工和工程监理单位承担，其中建筑设计和结构设计应当分别由具有高层建筑设计经验的一级注册建筑师和一级注册结构工程师承担。"},{"i":13,"n":"第十三条","txt":"建设单位、勘察单位、设计单位应当严格按照抗震设防专项审查意见进行超限高层建筑工程的勘察、设计。"},{"i":14,"n":"第十四条","txt":"未经超限高层建筑工程抗震设防专项审查，建设行政主管部门和其他有关部门不得对超限高层建筑工程施工图设计文件进行审查。 超限高层建筑工程的施工图设计文件审查应当由经国务院建设行政主管部门认定的具有超限高层建筑工程审查资格的施工图设计文件审查机构承担。 施工图设计文件审查时应当检查设计图纸是否执行了抗震设防专项审查意见；未执行专项审查意见的，施工图设计文件审查不能通过。"},{"i":15,"n":"第十五条","txt":"建设单位、施工单位、工程监理单位应当严格按照经抗震设防专项审查和施工图设计文件审查的勘察设计文件进行超限高层建筑工程的抗震设防和采取抗震措施。"},{"i":16,"n":"第十六条","txt":"对国家现行规范要求设置建筑结构地震反应观测系统的超限高层建筑工程，建设单位应当按照规范要求设置地震反应观测系统。"},{"i":17,"n":"第十七条","txt":"建设单位违反本规定，施工图设计文件未经审查或者审查不合格，擅自施工的，责令改正，处以20万元以上50万元以下的罚款。"},{"i":18,"n":"第十八条","txt":"勘察、设计单位违反本规定，未按照抗震设防专项审查意见进行超限高层建筑工程勘察、设计的，责令改正，处以1万元以上3万元以下的罚款；造成损失的，依法承担赔偿责任。"},{"i":19,"n":"第十九条","txt":"国家机关工作人员在超限高层建筑工程抗震设防管理工作中玩忽职守，滥用职权，徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":20,"n":"第二十条","txt":"省、自治区、直辖市人民政府建设行政主管部门，可结合本地区的具体情况制定实施细则，并报国务院建设行政主管部门备案。"},{"i":21,"n":"第二十一条","txt":"本规定自2002年9月1日起施行。1997年12月23日建设部颁布的《超限高层建筑工程抗震设防管理暂行规定》（建设部令第59号）同时废止。"}],"gaodengxuexiaojianzhuleizhuanyejiaoyupingguzanxing96ce26":[{"i":1,"n":"第一条","txt":"为客观地、科学地评价我国高等学校建筑类专业的办学水平，保证和不断提高建筑类专业教育的质量，加强普通高等学校建筑类专业的教育评估工作，适应国际间相互承认学历的需要，根据《普通高等学校教育评估暂行规定》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于建筑学、城市规划、建筑工程、给水排水工程、供热通风与空调工程、城市燃气工程、房地产经营管理等专业教育的评估工作。"},{"i":3,"n":"第三条","txt":"高等学校建筑类专业教育评估必须坚持社会主义办学方向，认真贯彻教育必须为社会主义建设服务、与生产劳动相结合、德智体全面发展的方针；坚持与国际公认的有关专业教育标准相衔接，在保证质量的基础上，办出各校的特色；坚持社会对学校教育的参与和监督。"},{"i":4,"n":"第四条","txt":"高等学校建筑类专业教育评估要对学校的教学质量、教学条件、教学过程和社会对毕业生质量的评价等方面进行客观、全面的评价。"},{"i":5,"n":"第五条","txt":"建设部授权全国建筑教育标准认定委员会负责指导、协调各专业教育评估委员会的工作。"},{"i":6,"n":"第六条","txt":"高等学校建筑类专业教育评估工作由专业教育评估委员会组织实施。专业教育评估委员会依法独立行使职权。"},{"i":7,"n":"第七条","txt":"专业教育评估委员会由该专业的全国教育界、工程技术界、用人部门和管理部门的专家学者15～17人组成。其中教育专家6～7人；工程技术专家6～7人；建设部指派3人。 专业教育评估委员会委员由建设部聘任，每届任期为四年；连任不得超过两届。 专业教育评估委员会设主任1名，副主任2～3名，秘书长1名。委员会办事机构为评估委员会办公室。"},{"i":8,"n":"第八条","txt":"专业教育评估委员会的主要任务是： （一）审查并受理评估申请； （二）制订、修订评估指标体系、评估标准和评估方法； （三）制定有关专业评估工作规程和细则； （四）制定评估工作计划； （五）选派赴评估院校的专家视察小组，并指导专家视察小组工作； （六）审议评估院校的自评报告和专家小组视察报告，作出评估结论； （七）受理评估院校对评估结论的申述，并报全国建筑教育标准认定委员会进行裁决； （八）按年度发布评估合格专业的院校名单； （九）对全国有关建筑类专业院系与评估工作有关的事项提供咨询； （十）总结专业教育评估工作经验，对专业评估与专业建设提出意见和建议。"},{"i":9,"n":"第九条","txt":"高等学校申请专业教育评估，必须具有以下条件： （一）学校应是国家教育委员会正式批准设置的； （二）申请评估的专业应是国家教育委员会批准或在国家教育委员会备案的；并应具有国务院学位委员会批准的学士学位授予资格； （三）符合建设部制定的该专业教育评估标准的要求。"},{"i":10,"n":"第十条","txt":"专业教育评估的主要程序是： （一）学校提出评估申请； （二）评估委员会审核评估申请； （三）学校自评、提出自评报告； （四）评估委员会审查自评报告； （五）对评估委员会审查通过自评报告的，评估委员会选派专家视察小组； （六）专家视察小组到学校实地视察，提交视察报告，提出评估结论建议； （七）评估委员会审核视察报告，作出评估结论； （八）公布评估合格结论，对合格专业颁发证书。"},{"i":11,"n":"第十一条","txt":"为全面了解毕业生的质量，学校应建立对毕业生跟踪调查和与社会用人部门经常联系的制度。"},{"i":12,"n":"第十二条","txt":"学校自评应严格按照评估标准逐项进行。学校自评报告应在规定期限内报专业教育评估委员会。自评所依据的原始资料应按要求分项单列成册，其中重要资料应作为附件列入自评报告，附件同时报评估委员会。"},{"i":13,"n":"第十三条","txt":"专业教育评估委员会对学校自评报告进行审查，经审查不合格的予以退还。被退还的学校在规定的期限内不得再次提出评估申请。"},{"i":14,"n":"第十四条","txt":"专家视察工作由专业教育评估委员会派出的视察小组进行。视察小组是临时性工作组织，其任务是：根据评估标准、程序与方法、评估工作有关细则及评估委员会的要求，视察申请学校（院、系）办学情况，写出视察报告，提出评估结论的建议，交评估委员会审议。"},{"i":15,"n":"第十五条","txt":"专业教育评估合格证书的有效期为4—6年，有关专业的有效期应在合格证书上明确。在有效期限内，专业教育评估委员会可以对该专业进行检查。 学校必须在评估合格有效期满前一年重新申请评估，逾期未申请评估的学校，该专业不再列入年度发布的评估合格专业的院校名单。"},{"i":16,"n":"第十六条","txt":"申请院校如对评估结论有不同意见，可在专业教育评估委员会规定的期限内提出申诉，并由专业教育评估委员会提请全国建筑教育标准认定委员会进行裁决。"},{"i":17,"n":"第十七条","txt":"高等学校建筑类专业教育评估经费由有关行业主管部门和申请教育评估的学校共同承担，同时鼓励社会资助。"},{"i":18,"n":"第十八条","txt":"本规定由建设部负责解释。"},{"i":19,"n":"第十九条","txt":"本规定自发布之日起施行。"}]};
